<?php declare(strict_types = 1);

/*
 * The PostgreSQL driver uses PDO. Enable PDO function calls:
 * phpcs:disable WordPress.DB.RestrictedClasses.mysql__PDO
 */

/**
 * PostgreSQL-backed driver scaffold.
 *
 * This class is intentionally not a PDO subclass. It exposes the small driver
 * surface consumed by the WordPress wpdb drop-in while the MySQL-to-PostgreSQL
 * emulation layer is extracted in later work.
 */
class WP_PostgreSQL_Driver {
	const MYSQL_COLUMN_METADATA_TABLE      = '__wp_postgresql_mysql_column_metadata';
	const MYSQL_INDEX_METADATA_TABLE       = '__wp_postgresql_mysql_index_metadata';
	const MYSQL_FOREIGN_KEY_METADATA_TABLE = '__wp_postgresql_mysql_foreign_key_metadata';
	const MYSQL_CHECK_METADATA_TABLE       = '__wp_postgresql_mysql_check_metadata';
	const MYSQL_CHARSET_METADATA_TABLE     = '__wp_postgresql_mysql_charset_metadata';
	const MYSQL_TABLE_METADATA_TABLE       = '__wp_postgresql_mysql_table_metadata';
	const DEFAULT_MYSQL_CHARSET            = 'utf8mb4';
	const DEFAULT_MYSQL_COLLATION          = 'utf8mb4_unicode_ci';

	private const DEFAULT_MYSQL_SQL_MODES = array(
		'ERROR_FOR_DIVISION_BY_ZERO',
		'NO_ENGINE_SUBSTITUTION',
		'NO_ZERO_DATE',
		'NO_ZERO_IN_DATE',
		'ONLY_FULL_GROUP_BY',
		'STRICT_TRANS_TABLES',
	);

	private const MYSQL_SQL_MODE_COMPOSITES = array(
		'ANSI'        => array(
			'REAL_AS_FLOAT',
			'PIPES_AS_CONCAT',
			'ANSI_QUOTES',
			'IGNORE_SPACE',
			'ONLY_FULL_GROUP_BY',
		),
		'TRADITIONAL' => array(
			'STRICT_TRANS_TABLES',
			'STRICT_ALL_TABLES',
			'NO_ZERO_IN_DATE',
			'NO_ZERO_DATE',
			'ERROR_FOR_DIVISION_BY_ZERO',
			'NO_ENGINE_SUBSTITUTION',
		),
	);

	private const MYSQL_SHOW_GRANTS_COLUMN = 'Grants for root@%';

	private const MYSQL_SHOW_GRANTS_VALUE = 'GRANT SELECT, INSERT, UPDATE, DELETE, CREATE, DROP, RELOAD, SHUTDOWN, ' .
		'PROCESS, FILE, REFERENCES, INDEX, ALTER, SHOW DATABASES, SUPER, CREATE TEMPORARY TABLES, LOCK TABLES, ' .
		'EXECUTE, REPLICATION SLAVE, REPLICATION CLIENT, CREATE VIEW, SHOW VIEW, CREATE ROUTINE, ALTER ROUTINE, ' .
		'CREATE USER, EVENT, TRIGGER, CREATE TABLESPACE, CREATE ROLE, DROP ROLE ON *.* TO `root`@`localhost` WITH GRANT OPTION';

	/**
	 * Prefix for encoded MySQL text bytes PostgreSQL text cannot store directly.
	 */
	private const MYSQL_TEXT_ENCODING_PREFIX = "\xEE\x80\x80WP_MYSQL_TEXT_V1:";

	/**
	 * Hash context for the MySQL text encoding envelope.
	 */
	private const MYSQL_TEXT_ENCODING_HASH_CONTEXT = 'wp-mysql-text-v1:';

	/**
	 * Bit mask for the base PDO fetch style without fetchAll() grouping flags.
	 */
	private const PDO_FETCH_STYLE_MASK = 0x0f;

	/**
	 * Hidden column used to carry FOUND_ROWS() accounting with a paged result.
	 */
	private const SQL_CALC_FOUND_ROWS_WINDOW_COLUMN = '__wp_pg_found_rows';

	/**
	 * Maximum number of exact MySQL query translations cached per connection.
	 */
	private const MYSQL_QUERY_TRANSLATION_CACHE_LIMIT = 256;

	/**
	 * PostgreSQL server version string.
	 *
	 * @var string
	 */
	public $client_info;

	/**
	 * MySQL server version emulated by the driver.
	 *
	 * @var int
	 */
	private $mysql_version;

	/**
	 * PostgreSQL connection.
	 *
	 * @var WP_PostgreSQL_Connection
	 */
	private $connection;

	/**
	 * Configured main MySQL-facing database name.
	 *
	 * @var string
	 */
	private $main_db_name;

	/**
	 * Current MySQL-facing database name.
	 *
	 * @var string
	 */
	private $db_name;

	/**
	 * Result of the last query.
	 *
	 * @var mixed
	 */
	private $last_result;

	/**
	 * Column metadata for the last result set.
	 *
	 * @var array
	 */
	private $last_column_meta = array();

	/**
	 * Number of exposed columns for the last result set.
	 *
	 * This is tracked separately so callers can ask for the column count without
	 * forcing PDO metadata normalization for common WordPress result fetches.
	 *
	 * @var int
	 */
	private $last_column_count = 0;

	/**
	 * Statement whose column metadata can be normalized lazily.
	 *
	 * @var PDOStatement|null
	 */
	private $last_column_meta_statement = null;

	/**
	 * Lazy metadata column names hidden from MySQL-facing callers.
	 *
	 * @var array
	 */
	private $last_column_meta_excluded_names = array();

	/**
	 * Incoming MySQL-dialect query for the last request.
	 *
	 * @var string|null
	 */
	private $last_mysql_query;

	/**
	 * PostgreSQL queries executed for the last request.
	 *
	 * @var array
	 */
	private $last_postgresql_queries = array();

	/**
	 * Whether the MySQL metadata side tables were ensured for this connection.
	 *
	 * @var bool
	 */
	private $mysql_schema_metadata_tables_ensured = false;

	/**
	 * Resolved backend schema names for MySQL table introspection.
	 *
	 * @var array<string, string>
	 */
	private $mysql_table_schema_introspection_cache = array();

	/**
	 * Ordered DML column metadata rows keyed by backend schema and table.
	 *
	 * @var array<string, array>
	 */
	private $mysql_dml_column_metadata_cache = array();

	/**
	 * DML identity metadata rows keyed by backend schema and table.
	 *
	 * @var array<string, array>
	 */
	private $mysql_dml_identity_column_metadata_cache = array();

	/**
	 * MySQL column type metadata keyed by backend schema, table, and column.
	 *
	 * @var array<string, array<string, string|null>>
	 */
	private $mysql_table_column_type_cache = array();

	/**
	 * MySQL column collation metadata keyed by backend schema, table, and column.
	 *
	 * @var array<string, array<string, string|null>>
	 */
	private $mysql_table_column_collation_cache = array();

	/**
	 * Stored MySQL column metadata existence keyed by backend schema and table.
	 *
	 * @var array<string, bool>
	 */
	private $mysql_table_has_column_metadata_cache = array();

	/**
	 * Stored MySQL column names keyed by backend schema, table, and requested column.
	 *
	 * @var array<string, array<string, string|null>>
	 */
	private $mysql_table_column_name_cache = array();

	/**
	 * Cached MySQL upsert conflict targets keyed by table and inserted columns.
	 *
	 * @var array<string, string[]|null>
	 */
	private $mysql_upsert_conflict_target_cache = array();

	/**
	 * Cached MySQL introspection results keyed by query shape.
	 *
	 * @var array<string, array{column_meta: array, result: mixed}>
	 */
	private $mysql_introspection_result_cache = array();

	/**
	 * Cached exact MySQL SELECT translations keyed by query hash.
	 *
	 * @var array<string, array{query: string, sql: string, translated: bool}>
	 */
	private $mysql_select_translation_cache = array();

	/**
	 * Cached exact SQL_CALC_FOUND_ROWS count SQL keyed by source query hash.
	 *
	 * @var array<string, array{query: string, sql: string}>
	 */
	private $mysql_sql_calc_found_rows_count_query_cache = array();

	/**
	 * Most recently tokenized MySQL query.
	 *
	 * @var string|null
	 */
	private $mysql_token_cache_query = null;

	/**
	 * SQL mode string for the most recently tokenized MySQL query.
	 *
	 * @var string|null
	 */
	private $mysql_token_cache_sql_mode = null;

	/**
	 * Token stream for the most recently tokenized MySQL query.
	 *
	 * @var WP_MySQL_Token[]
	 */
	private $mysql_token_cache_tokens = array();

	/**
	 * FOUND_ROWS() value for the last SQL_CALC_FOUND_ROWS query.
	 *
	 * @var int
	 */
	private $last_found_rows = 0;

	/**
	 * MySQL-compatible insert ID for the last successful insert-like query.
	 *
	 * @var int|string
	 */
	private $last_insert_id = 0;

	/**
	 * MySQL-compatible session SQL mode state.
	 *
	 * @var string[]
	 */
	private $active_sql_modes = self::DEFAULT_MYSQL_SQL_MODES;

	/**
	 * MySQL-compatible session character set state.
	 *
	 * @var string
	 */
	private $charset = self::DEFAULT_MYSQL_CHARSET;

	/**
	 * MySQL-compatible session collation state.
	 *
	 * @var string
	 */
	private $collation = self::DEFAULT_MYSQL_COLLATION;

	/**
	 * MySQL-compatible session variable overrides.
	 *
	 * @var array<string, string>
	 */
	private $mysql_session_variable_values = array();

	/**
	 * MySQL-compatible user variables.
	 *
	 * @var array<string, string|null>
	 */
	private $mysql_user_variables = array();

	/**
	 * Narrow in-memory procedure registry for WordPress mysqli compatibility tests.
	 *
	 * @var array<string, string>
	 */
	private $procedures = array();

	/**
	 * Constructor.
	 *
	 * @param WP_PostgreSQL_Connection $connection    PostgreSQL connection.
	 * @param string                   $database      MySQL-facing database name.
	 * @param int                      $mysql_version MySQL version to emulate.
	 */
	public function __construct(
		WP_PostgreSQL_Connection $connection,
		string $database,
		int $mysql_version = 80038
	) {
		$this->connection    = $connection;
		$this->main_db_name  = $database;
		$this->db_name       = $database;
		$this->mysql_version = $mysql_version;
		$this->client_info   = $this->read_server_version();

		$connection->get_pdo()->setAttribute( PDO::ATTR_STRINGIFY_FETCHES, true );
	}

	/**
	 * Get the PostgreSQL connection instance.
	 *
	 * @return WP_PostgreSQL_Connection
	 */
	public function get_connection(): WP_PostgreSQL_Connection {
		return $this->connection;
	}

	/**
	 * Get the PostgreSQL server version.
	 *
	 * @return string
	 */
	public function get_postgresql_version(): string {
		return $this->client_info;
	}

	/**
	 * Get the last executed MySQL query.
	 *
	 * @return string|null
	 */
	public function get_last_mysql_query(): ?string {
		return $this->last_mysql_query;
	}

	/**
	 * Get backend queries executed for the last MySQL query.
	 *
	 * @return array
	 */
	public function get_last_postgresql_queries(): array {
		return $this->last_postgresql_queries;
	}

	/**
	 * Get the auto-increment value generated for the last query.
	 *
	 * @return int|string
	 */
	public function get_insert_id() {
		return is_numeric( $this->last_insert_id ) ? (int) $this->last_insert_id : $this->last_insert_id;
	}

	/**
	 * Set the emulated MySQL session SQL mode.
	 *
	 * @param string $sql_mode Comma-separated SQL mode string.
	 */
	public function set_sql_mode( string $sql_mode ): void {
		$this->active_sql_modes = $this->normalize_mysql_sql_modes( $sql_mode );
		unset( $this->mysql_session_variable_values['sql_mode'] );
		$this->clear_mysql_token_cache();
		$this->clear_mysql_query_translation_caches();
	}

	/**
	 * Get the emulated MySQL session SQL mode.
	 *
	 * @return string Comma-separated SQL mode string.
	 */
	public function get_sql_mode(): string {
		return implode( ',', $this->active_sql_modes );
	}

	/**
	 * Check if a specific SQL mode is active.
	 *
	 * @param string $mode SQL mode name.
	 * @return bool Whether the mode is active.
	 */
	public function is_sql_mode_active( string $mode ): bool {
		return in_array( strtoupper( $mode ), $this->active_sql_modes, true );
	}

	/**
	 * Normalize a MySQL SQL mode assignment to a canonical mode list.
	 *
	 * @param string $sql_mode Comma-separated SQL mode assignment value.
	 * @return string[] Normalized mode names.
	 */
	private function normalize_mysql_sql_modes( string $sql_mode ): array {
		$sql_mode = trim( $sql_mode, "'\"` \t\n\r\0\x0B" );
		if ( '' === $sql_mode || '0' === $sql_mode ) {
			return array();
		}

		if ( 'DEFAULT' === strtoupper( $sql_mode ) ) {
			return self::DEFAULT_MYSQL_SQL_MODES;
		}

		$normalized = array();
		foreach ( explode( ',', $sql_mode ) as $mode ) {
			$mode = strtoupper( trim( $mode, "'\"` \t\n\r\0\x0B" ) );
			if ( '' === $mode ) {
				continue;
			}

			$modes = self::MYSQL_SQL_MODE_COMPOSITES[ $mode ] ?? array( $mode );
			foreach ( $modes as $expanded_mode ) {
				if ( ! in_array( $expanded_mode, $normalized, true ) ) {
					$normalized[] = $expanded_mode;
				}
			}
		}

		return $normalized;
	}

	/**
	 * Set the emulated MySQL session charset/collation.
	 *
	 * @param string      $charset   MySQL charset.
	 * @param string|null $collation Optional MySQL collation.
	 */
	public function set_charset( string $charset, ?string $collation = null ): void {
		if ( 'default' === $this->normalize_mysql_charset_name( $charset ) ) {
			$this->charset   = self::DEFAULT_MYSQL_CHARSET;
			$this->collation = self::DEFAULT_MYSQL_COLLATION;
			$this->sync_mysql_charset_session_variables();
			return;
		}

		$this->charset   = $this->normalize_mysql_charset_name( $charset );
		$this->collation = null === $collation || '' === $collation
			? $this->get_default_mysql_collation_for_charset( $this->charset )
			: $this->normalize_mysql_collation_name( $collation );
		$this->sync_mysql_charset_session_variables();
	}

	/**
	 * Get the emulated MySQL session charset.
	 *
	 * @return string MySQL charset.
	 */
	public function get_charset(): string {
		return $this->charset;
	}

	/**
	 * Get the emulated MySQL session collation.
	 *
	 * @return string MySQL collation.
	 */
	public function get_collation(): string {
		return $this->collation;
	}

	/**
	 * Execute a query.
	 *
	 * @param string $query              Full SQL statement string.
	 * @param int    $fetch_mode         PDO fetch mode. Default is PDO::FETCH_OBJ.
	 * @param array  ...$fetch_mode_args Additional fetch mode arguments.
	 * @return mixed Return value, depending on the query type.
	 */
	public function query( string $query, $fetch_mode = PDO::FETCH_OBJ, ...$fetch_mode_args ) {
		$this->reset_query_state();
		$this->last_mysql_query = $query;

		$runtime_setting_result = $this->execute_mysql_runtime_setting_query( $query );
		if ( null !== $runtime_setting_result ) {
			return $runtime_setting_result;
		}

		$use_database_name = $this->get_mysql_use_database_name( $query );
		if ( null !== $use_database_name ) {
			return $this->execute_mysql_use_statement( $use_database_name );
		}

		$transaction_control_query = $this->get_mysql_transaction_control_query( $query );
		if ( null !== $transaction_control_query ) {
			return $this->execute_mysql_transaction_control_query( $transaction_control_query );
		}

		$savepoint_query = $this->get_mysql_savepoint_query( $query );
		if ( null !== $savepoint_query ) {
			return $this->execute_mysql_savepoint_query( $savepoint_query );
		}

		$procedure_result = $this->handle_mysql_procedure_query( $query, $fetch_mode, ...$fetch_mode_args );
		if ( null !== $procedure_result ) {
			return $procedure_result;
		}

		$mysql_variable_select_query = $this->get_mysql_variable_select_query( $query );
		if ( null !== $mysql_variable_select_query ) {
			return $this->execute_mysql_variable_select_query(
				$mysql_variable_select_query,
				$fetch_mode,
				...$fetch_mode_args
			);
		}

		$database_function_column = $this->get_mysql_database_function_select_column( $query );
		if ( null !== $database_function_column ) {
			return $this->set_mysql_static_show_result(
				array( $database_function_column ),
				array( array( $database_function_column => $this->db_name ) ),
				$fetch_mode,
				...$fetch_mode_args
			);
		}

		$show_variables_query = $this->get_show_variables_query( $query );
		if ( null !== $show_variables_query ) {
			return $this->execute_show_variables_query( $show_variables_query, $fetch_mode, ...$fetch_mode_args );
		}

		$show_character_set_query = $this->get_show_character_set_query( $query );
		if ( null !== $show_character_set_query ) {
			return $this->execute_show_character_set_query( $show_character_set_query, $fetch_mode, ...$fetch_mode_args );
		}

		$show_collation_query = $this->get_show_collation_query( $query );
		if ( null !== $show_collation_query ) {
			return $this->execute_show_collation_query( $show_collation_query, $fetch_mode, ...$fetch_mode_args );
		}

		$show_databases_query = $this->get_show_databases_query( $query );
		if ( null !== $show_databases_query ) {
			return $this->execute_show_databases_query( $show_databases_query, $fetch_mode, ...$fetch_mode_args );
		}

		$show_create_database_query = $this->get_show_create_database_query( $query );
		if ( null !== $show_create_database_query ) {
			return $this->execute_show_create_database_query( $show_create_database_query, $fetch_mode, ...$fetch_mode_args );
		}

		$show_engines_query = $this->get_show_engines_query( $query );
		if ( null !== $show_engines_query ) {
			return $this->execute_show_engines_query( $show_engines_query, $fetch_mode, ...$fetch_mode_args );
		}

		$show_grants_query = $this->get_show_grants_query( $query );
		if ( null !== $show_grants_query ) {
			return $this->execute_show_grants_query( $fetch_mode, ...$fetch_mode_args );
		}

		$show_status_query = $this->get_show_status_query( $query );
		if ( null !== $show_status_query ) {
			return $this->execute_show_status_query( $show_status_query, $fetch_mode, ...$fetch_mode_args );
		}

		$show_warnings_query = $this->get_show_diagnostics_query( $query, WP_MySQL_Lexer::WARNINGS_SYMBOL, 'warnings' );
		if ( null !== $show_warnings_query ) {
			return $this->execute_show_diagnostics_query( $show_warnings_query, $fetch_mode, ...$fetch_mode_args );
		}

		$show_errors_query = $this->get_show_diagnostics_query( $query, WP_MySQL_Lexer::ERRORS_SYMBOL, 'errors' );
		if ( null !== $show_errors_query ) {
			return $this->execute_show_diagnostics_query( $show_errors_query, $fetch_mode, ...$fetch_mode_args );
		}

		$show_processlist_query = $this->get_show_processlist_query( $query );
		if ( null !== $show_processlist_query ) {
			return $this->execute_show_processlist_query( $show_processlist_query, $fetch_mode, ...$fetch_mode_args );
		}

		$direct_information_schema_cte_translated = false;
		$direct_information_schema_cte_query      = $this->translate_direct_information_schema_cte_select_query( $query );
		if ( null !== $direct_information_schema_cte_query ) {
			$query                                    = $direct_information_schema_cte_query;
			$direct_information_schema_cte_translated = true;
		}

		if ( ! $direct_information_schema_cte_translated && $this->should_reject_information_schema_backend_query( $query ) ) {
			throw new InvalidArgumentException( 'Unsupported information_schema query.' );
		}

		$lock_tables_query = $this->get_mysql_lock_tables_query( $query );
		if ( null !== $lock_tables_query ) {
			return $this->execute_mysql_lock_tables_query( $lock_tables_query );
		}

		$truncate_table_query = $this->get_mysql_truncate_table_query( $query );
		if ( null !== $truncate_table_query ) {
			return $this->execute_mysql_truncate_table_query( $truncate_table_query );
		}

		if ( $this->is_found_rows_query( $query ) ) {
			$this->last_result      = array( (object) array( 'FOUND_ROWS()' => (string) $this->last_found_rows ) );
			$this->last_column_meta = array(
				array(
					'name'             => 'FOUND_ROWS()',
					'table'            => '',
					'mysqli:orgtable'  => '',
					'mysqli:orgname'   => 'FOUND_ROWS()',
					'mysqli:db'        => $this->db_name,
					'mysqli:charsetnr' => 63,
					'mysqli:flags'     => 0,
					'mysqli:type'      => 8,
					'len'              => 20,
					'precision'        => 0,
					'native_type'      => 'integer',
				),
			);
			return $this->last_result;
		}

		$create_table_select_query = $this->translate_mysql_create_table_select_query( $query );
		if ( null !== $create_table_select_query ) {
			$result = $this->execute_postgresql_statements( array( $create_table_select_query['sql'] ) );
			$this->store_mysql_create_table_select_metadata(
				$create_table_select_query['temporary']
					? $this->get_temporary_schema_for_metadata_table( $create_table_select_query['table'] )
					: $create_table_select_query['schema'],
				$create_table_select_query['table']
			);
			return $result;
		}

		if ( $this->contains_unsupported_mysql_create_table_column_attribute_query( $query ) ) {
			throw new InvalidArgumentException( 'Unsupported CREATE TABLE column attribute.' );
		}

		if ( $this->is_create_table_query( $query ) ) {
			$this->validate_mysql_create_table_target_database( $query );

			$translator = new WP_PostgreSQL_Create_Table_Translator( $this->active_sql_modes );
			$result     = $this->execute_postgresql_statements( $translator->translate_schema( $query ) );
			if ( $this->is_temporary_create_table_query( $query ) ) {
				$this->store_mysql_temporary_schema_metadata( $query );
			} else {
				$this->store_mysql_schema_metadata( $query );
				$this->sync_mysql_on_update_current_timestamp_triggers_for_create_query( $query );
			}
			return $result;
		}

		$create_index_query = $this->translate_mysql_create_index_query( $query );
		if ( null !== $create_index_query ) {
			$this->execute_postgresql_statements( $create_index_query['statements'] );
			$this->apply_mysql_create_index_metadata( $create_index_query['metadata'] );
			$this->last_result = 0;
			return $this->last_result;
		}
		$unsupported_create_statement = $this->get_unsupported_mysql_create_statement_message( $query );
		if ( null !== $unsupported_create_statement ) {
			throw new InvalidArgumentException( $unsupported_create_statement );
		}

		$alter_query = $this->translate_mysql_dbdelta_alter_table_query( $query );
		if ( null !== $alter_query ) {
			$result = $this->execute_postgresql_statements( $alter_query['statements'] );
			$this->apply_mysql_dbdelta_alter_metadata( $alter_query['metadata'] );
			if (
				$this->mysql_dbdelta_alter_metadata_has_operation( $alter_query['metadata'], 'drop_index' )
				|| $this->mysql_dbdelta_alter_metadata_has_operation( $alter_query['metadata'], 'rename_table' )
				|| $this->mysql_dbdelta_alter_metadata_has_operation( $alter_query['metadata'], 'set_auto_increment' )
			) {
				$this->last_result = 0;
				return $this->last_result;
			}
			return $result;
		}
		if ( $this->is_mysql_alter_table_query( $query ) ) {
			throw new InvalidArgumentException( 'Unsupported ALTER TABLE statement.' );
		}

		$drop_query = $this->translate_mysql_drop_table_query( $query );
		if ( null !== $drop_query ) {
			$this->execute_postgresql_statements( $drop_query['statements'] );
			$this->maybe_clear_mysql_schema_metadata_table_state( $drop_query['tables'] );
			$this->delete_mysql_schema_metadata_for_table_targets( $drop_query['metadata_targets'] );
			$this->last_result = 0;
			return $this->last_result;
		}

		$drop_index_query = $this->translate_mysql_drop_index_query( $query );
		if ( null !== $drop_index_query ) {
			$this->execute_postgresql_statements( $drop_index_query['statements'] );
			$this->apply_mysql_drop_index_metadata( $drop_index_query['metadata'] );
			$this->last_result = 0;
			return $this->last_result;
		}
		$unsupported_drop_statement = $this->get_unsupported_mysql_drop_statement_message( $query );
		if ( null !== $unsupported_drop_statement ) {
			throw new InvalidArgumentException( $unsupported_drop_statement );
		}

		$rename_table_query = $this->translate_mysql_rename_table_query( $query );
		if ( null !== $rename_table_query ) {
			$this->execute_postgresql_statements( $rename_table_query['statements'] );
			$this->apply_mysql_rename_table_metadata( $rename_table_query['metadata'] );
			$this->last_result = 0;
			return $this->last_result;
		}
		if ( $this->is_mysql_rename_table_query( $query ) ) {
			throw new InvalidArgumentException( 'Unsupported RENAME TABLE statement.' );
		}

		$describe_table_reference = $this->get_describe_table_reference( $query );
		if ( null !== $describe_table_reference ) {
			return $this->execute_describe_query(
				$describe_table_reference['schema'],
				$describe_table_reference['table'],
				$fetch_mode,
				...$fetch_mode_args
			);
		}

		$show_tables_query = $this->get_show_tables_query( $query );
		if ( null !== $show_tables_query ) {
			return $this->execute_show_tables_query(
				$show_tables_query['full'],
				$show_tables_query['schema'],
				$show_tables_query['database'],
				$show_tables_query['like'],
				$show_tables_query['where'],
				$fetch_mode,
				...$fetch_mode_args
			);
		}

		$show_table_status_query = $this->get_show_table_status_query( $query );
		if ( null !== $show_table_status_query ) {
			return $this->execute_show_table_status_query(
				$show_table_status_query,
				$fetch_mode,
				...$fetch_mode_args
			);
		}

		$show_create_table_query = $this->get_show_create_table_query( $query );
		if ( null !== $show_create_table_query ) {
			return $this->execute_show_create_table_query(
				$show_create_table_query,
				$fetch_mode,
				...$fetch_mode_args
			);
		}

		$show_columns_query = $this->get_show_columns_query( $query );
		if ( null !== $show_columns_query ) {
			return $this->execute_show_columns_query(
				$show_columns_query['schema'],
				$show_columns_query['table'],
				$show_columns_query['full'],
				$show_columns_query['like'],
				$show_columns_query['where'],
				$fetch_mode,
				...$fetch_mode_args
			);
		}

		$show_index_query = $this->get_show_index_query( $query );
		if ( null !== $show_index_query ) {
			return $this->execute_show_index_query(
				$show_index_query['schema'],
				$show_index_query['table'],
				$show_index_query['where'],
				$fetch_mode,
				...$fetch_mode_args
			);
		}

		$table_administration_query = $this->get_mysql_table_administration_query( $query );
		if ( null !== $table_administration_query ) {
			return $this->execute_mysql_table_administration_query(
				$table_administration_query,
				$fetch_mode,
				...$fetch_mode_args
			);
		}

		$translated_for_postgresql = $direct_information_schema_cte_translated;
		$dml_identity_repair_query = null;

		$translated_query = $this->translate_wordpress_options_regexp_delete_query( $query );
		if ( null !== $translated_query ) {
			$query                     = $translated_query;
			$translated_for_postgresql = true;
		}

		$translated_query = $this->translate_wordpress_expired_transients_delete_query( $query );
		if ( null !== $translated_query ) {
			return $this->execute_postgresql_statements( array( $translated_query ) );
		}

			$translated_query = $this->translate_mysql_left_join_orphan_delete_query( $query );
		if ( null !== $translated_query ) {
			$query                     = $translated_query;
			$translated_for_postgresql = true;
		}

			$multi_target_delete_query = $this->translate_mysql_multi_target_delete_query( $query );
		if ( null !== $multi_target_delete_query ) {
			return $this->execute_mysql_multi_target_delete_query( $multi_target_delete_query );
		}

			$translated_query = $this->translate_mysql_single_target_join_delete_query( $query );
		if ( null !== $translated_query ) {
			$query                     = $translated_query;
			$translated_for_postgresql = true;
		}

		$translated_query = $this->translate_simple_mysql_delete_query( $query );
		if ( null !== $translated_query ) {
			$query                     = $translated_query;
			$translated_for_postgresql = true;
		}
		if ( ! $translated_for_postgresql && $this->is_unsupported_mysql_delete_query( $query ) ) {
			throw new InvalidArgumentException( 'Unsupported DELETE statement.' );
		}

		$upsert_query = $this->translate_mysql_on_duplicate_key_update_query( $query );
		if ( null !== $upsert_query ) {
			if ( isset( $upsert_query['statements'] ) && is_array( $upsert_query['statements'] ) ) {
				return $this->execute_translated_dml_statements( $upsert_query );
			}
			$query                     = $upsert_query['sql'];
			$dml_identity_repair_query = $upsert_query;
			$translated_for_postgresql = true;
		} elseif ( $this->is_unsupported_mysql_on_duplicate_key_update_query( $query ) ) {
			throw new InvalidArgumentException( 'Unsupported ON DUPLICATE KEY UPDATE statement.' );
		}

		$replace_return_value = null;
		$replace_query        = $this->translate_simple_mysql_replace_query( $query );
		if ( null !== $replace_query ) {
			if ( null !== $replace_query['conflict_column'] && empty( $replace_query['replace_select_materialized'] ) ) {
				$replace_return_value = $this->get_mysql_replace_return_value( $replace_query );
			}
			if ( isset( $replace_query['statements'] ) && is_array( $replace_query['statements'] ) ) {
				if ( ! empty( $replace_query['replace_select_materialized'] ) ) {
					return $this->execute_materialized_mysql_replace_select_statements( $replace_query );
				}
				return $this->execute_translated_dml_statements( $replace_query, $replace_return_value );
			}
			$query                     = $replace_query['sql'];
			$dml_identity_repair_query = $replace_query;
			$translated_for_postgresql = true;
		} elseif ( $this->is_mysql_replace_query( $query ) ) {
			throw new InvalidArgumentException( 'Unsupported REPLACE statement.' );
		}

		$insert_query = $this->translate_simple_mysql_insert_query( $query );
		if ( null !== $insert_query ) {
			$query                     = $insert_query['sql'];
			$dml_identity_repair_query = $insert_query;
			$translated_for_postgresql = true;
		} elseif ( ! $translated_for_postgresql && $this->is_unsupported_mysql_insert_set_query( $query ) ) {
			throw new InvalidArgumentException( 'Unsupported INSERT statement.' );
		}

		$insert_select_query = $this->translate_simple_mysql_insert_select_query( $query );
		if ( null !== $insert_select_query ) {
			$query                     = $insert_select_query['sql'];
			$dml_identity_repair_query = $insert_select_query;
			$translated_for_postgresql = true;
		}

		$multi_target_update_query = $this->translate_mysql_multi_target_update_query( $query );
		if ( null !== $multi_target_update_query ) {
			return $this->execute_mysql_multi_target_update_query( $multi_target_update_query );
		}

		$translated_query = $this->translate_simple_mysql_update_query( $query );
		if ( null !== $translated_query ) {
			$query                     = $translated_query;
			$translated_for_postgresql = true;
		} elseif ( $this->is_unsupported_mysql_multi_table_update_query( $query ) ) {
			throw new InvalidArgumentException( 'Unsupported UPDATE statement.' );
		}

		$is_sql_calc_found_rows_query = $this->is_sql_calc_found_rows_select_query( $query );
		$sql_calc_found_rows_query    = $is_sql_calc_found_rows_query ? $query : null;
		$sql_calc_found_rows_window   = false;

		if ( ! $translated_for_postgresql ) {
			$translated_query = null !== $sql_calc_found_rows_query && $this->is_sql_calc_found_rows_window_fetch_mode( $fetch_mode )
				? $this->translate_sql_calc_found_rows_window_select_query( $query )
				: null;
			if ( null !== $translated_query ) {
				$query                      = $translated_query;
				$translated_for_postgresql  = true;
				$sql_calc_found_rows_window = true;
			} elseif ( $this->is_mysql_select_translation_cacheable_query( $query ) ) {
				$select_translation        = $this->get_mysql_select_query_translation( $query );
				$query                     = $select_translation['sql'];
				$translated_for_postgresql = $select_translation['translated'];
			} elseif ( $this->is_mysql_top_level_select_query( $query ) ) {
				$select_translation        = $this->translate_mysql_select_query_for_postgresql( $query );
				$query                     = $select_translation['sql'];
				$translated_for_postgresql = $select_translation['translated'];
			} else {
				$translated_query = $this->translate_mysql_compatible_query( $query );
				if ( null !== $translated_query ) {
					$query = $translated_query;
				}
			}
		}

		if ( $this->contains_mysql_index_hint_syntax( $query ) ) {
			throw new InvalidArgumentException( 'Unsupported MySQL index hint syntax.' );
		}

		if ( $this->contains_unsupported_mysql_date_arithmetic_function_query( $query ) ) {
			throw new InvalidArgumentException( 'Unsupported MySQL date arithmetic statement.' );
		}

		if ( $this->contains_unsupported_mysql_common_function_query( $query ) ) {
			throw new InvalidArgumentException( 'Unsupported MySQL runtime function form.' );
		}

		if ( $this->contains_unsupported_mysql_week_function_query( $query ) ) {
			throw new InvalidArgumentException( 'Unsupported MySQL WEEK() mode.' );
		}

		$unsupported_mysql_administration_statement = $this->get_unsupported_mysql_administration_statement_message( $query );
		if ( null !== $unsupported_mysql_administration_statement ) {
			throw new InvalidArgumentException( $unsupported_mysql_administration_statement );
		}

		$stmt                            = $this->connection->query( $query );
		$this->last_postgresql_queries[] = array(
			'sql'    => $query,
			'params' => array(),
		);

		$affected_rows = $stmt->rowCount();

		$column_count = $stmt->columnCount();
		if ( $column_count > 0 ) {
			$this->set_lazy_last_column_meta( $stmt, $column_count );
			$this->last_result = $this->decode_postgresql_text_for_mysql_in_result(
				$stmt->fetchAll( $fetch_mode, ...$fetch_mode_args )
			);
			if ( $sql_calc_found_rows_window ) {
				$found_rows = $this->extract_sql_calc_found_rows_window_result( $this->last_result );
				$this->remove_sql_calc_found_rows_window_column_meta();
				$this->last_found_rows = null === $found_rows && null !== $sql_calc_found_rows_query
					? $this->execute_sql_calc_found_rows_count_query( $sql_calc_found_rows_query )
					: (int) $found_rows;
			} elseif ( null !== $sql_calc_found_rows_query ) {
				$this->last_found_rows = $this->execute_sql_calc_found_rows_count_query( $sql_calc_found_rows_query );
			}
		} else {
			$this->clear_last_column_meta();
			$this->last_result = $affected_rows;
			if ( null !== $replace_return_value ) {
				$this->last_result = $replace_return_value;
			}
		}

		if ( null !== $dml_identity_repair_query ) {
			$this->set_last_insert_id_after_dml_success( $dml_identity_repair_query, $affected_rows );
			$this->repair_dml_identity_sequences_after_success( $dml_identity_repair_query, $affected_rows );
		}

		return $this->last_result;
	}

	/**
	 * Get an explicit unsupported error for unclaimed MySQL administration SQL.
	 *
	 * Supported SHOW/table-administration forms are dispatched before this guard.
	 * If one of these MySQL-only statement families reaches the backend fallback,
	 * fail closed rather than letting PostgreSQL parse incompatible SQL.
	 *
	 * @param string $query MySQL query.
	 * @return string|null Unsupported error message, or null when not guarded.
	 */
	private function get_unsupported_mysql_administration_statement_message( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) ) {
			return null;
		}

		switch ( $tokens[0]->id ) {
			case WP_MySQL_Lexer::SHOW_SYMBOL:
				return 'Unsupported SHOW statement.';

			case WP_MySQL_Lexer::ANALYZE_SYMBOL:
			case WP_MySQL_Lexer::CHECK_SYMBOL:
			case WP_MySQL_Lexer::OPTIMIZE_SYMBOL:
			case WP_MySQL_Lexer::REPAIR_SYMBOL:
				return 'Unsupported table administration statement.';

			case WP_MySQL_Lexer::CHECKSUM_SYMBOL:
				return 'Unsupported CHECKSUM TABLE statement.';

			case WP_MySQL_Lexer::FLUSH_SYMBOL:
				return 'Unsupported FLUSH statement.';

			case WP_MySQL_Lexer::KILL_SYMBOL:
				return 'Unsupported KILL statement.';

			case WP_MySQL_Lexer::CACHE_SYMBOL:
				return 'Unsupported CACHE INDEX statement.';

			case WP_MySQL_Lexer::LOAD_SYMBOL:
				return 'Unsupported LOAD statement.';

			case WP_MySQL_Lexer::BINLOG_SYMBOL:
				return 'Unsupported BINLOG statement.';

			case WP_MySQL_Lexer::SHUTDOWN_SYMBOL:
				return 'Unsupported SHUTDOWN statement.';

			case WP_MySQL_Lexer::GRANT_SYMBOL:
				return 'Unsupported GRANT statement.';

			case WP_MySQL_Lexer::REVOKE_SYMBOL:
				return 'Unsupported REVOKE statement.';

			case WP_MySQL_Lexer::RESET_SYMBOL:
				return 'Unsupported RESET statement.';

			case WP_MySQL_Lexer::PURGE_SYMBOL:
				return 'Unsupported PURGE statement.';

			case WP_MySQL_Lexer::INSTALL_SYMBOL:
				return 'Unsupported INSTALL statement.';

			case WP_MySQL_Lexer::UNINSTALL_SYMBOL:
				return 'Unsupported UNINSTALL statement.';

			case WP_MySQL_Lexer::ALTER_SYMBOL:
				switch ( $tokens[1]->id ?? null ) {
					case WP_MySQL_Lexer::TABLE_SYMBOL:
						return null;

					case WP_MySQL_Lexer::DATABASE_SYMBOL:
						return 'Unsupported ALTER DATABASE statement.';

					case WP_MySQL_Lexer::EVENT_SYMBOL:
						return 'Unsupported ALTER EVENT statement.';

					case WP_MySQL_Lexer::LOGFILE_SYMBOL:
						return 'Unsupported ALTER LOGFILE statement.';

					case WP_MySQL_Lexer::SERVER_SYMBOL:
						return 'Unsupported ALTER SERVER statement.';

					case WP_MySQL_Lexer::TABLESPACE_SYMBOL:
						return 'Unsupported ALTER TABLESPACE statement.';

					case WP_MySQL_Lexer::UNDO_SYMBOL:
						return 'Unsupported ALTER UNDO TABLESPACE statement.';

					case WP_MySQL_Lexer::USER_SYMBOL:
						return 'Unsupported ALTER USER statement.';

					case WP_MySQL_Lexer::VIEW_SYMBOL:
						return 'Unsupported ALTER VIEW statement.';
				}
				return null;

			case WP_MySQL_Lexer::RENAME_SYMBOL:
				if ( isset( $tokens[1] ) && WP_MySQL_Lexer::USER_SYMBOL === $tokens[1]->id ) {
					return 'Unsupported RENAME USER statement.';
				}
				return null;
		}

		return null;
	}

	/**
	 * Get an explicit unsupported error for unclaimed MySQL CREATE statements.
	 *
	 * Supported CREATE TABLE/CREATE INDEX forms are dispatched before this guard.
	 * Plain PostgreSQL-compatible CREATE TABLE statements may still fall through,
	 * but MySQL-only CREATE constructs should not reach the backend parser.
	 *
	 * @param string $query MySQL query.
	 * @return string|null Unsupported error message, or null when not guarded.
	 */
	private function get_unsupported_mysql_create_statement_message( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::CREATE_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return 'Unsupported CREATE statement.';
		}

		$position = 1;
		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::OR_SYMBOL === $tokens[ $position ]->id
			&& WP_MySQL_Lexer::REPLACE_SYMBOL === $tokens[ $position + 1 ]->id
		) {
			$position += 2;
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::TEMPORARY_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::TABLE_SYMBOL === $tokens[ $position ]->id ) {
			return $this->get_unsupported_mysql_create_table_statement_message( $tokens, $position + 1 );
		}

		$statement_token = $tokens[ $position ] ?? null;
		if (
			null !== $statement_token
			&& WP_MySQL_Lexer::SPATIAL_SYMBOL === $statement_token->id
			&& isset( $tokens[ $position + 1 ], $tokens[ $position + 2 ] )
			&& WP_MySQL_Lexer::REFERENCE_SYMBOL === $tokens[ $position + 1 ]->id
			&& WP_MySQL_Lexer::SYSTEM_SYMBOL === $tokens[ $position + 2 ]->id
		) {
			return 'Unsupported CREATE SPATIAL REFERENCE SYSTEM statement.';
		}

		switch ( $statement_token->id ?? null ) {
			case WP_MySQL_Lexer::DATABASE_SYMBOL:
			case WP_MySQL_Lexer::SCHEMA_SYMBOL:
				return 'Unsupported CREATE DATABASE statement.';

			case WP_MySQL_Lexer::VIEW_SYMBOL:
				return 'Unsupported CREATE VIEW statement.';

			case WP_MySQL_Lexer::INDEX_SYMBOL:
			case WP_MySQL_Lexer::UNIQUE_SYMBOL:
			case WP_MySQL_Lexer::FULLTEXT_SYMBOL:
			case WP_MySQL_Lexer::SPATIAL_SYMBOL:
				return 'Unsupported CREATE INDEX statement.';

			case WP_MySQL_Lexer::PROCEDURE_SYMBOL:
				return 'Unsupported CREATE PROCEDURE statement.';

			case WP_MySQL_Lexer::FUNCTION_SYMBOL:
				return 'Unsupported CREATE FUNCTION statement.';

			case WP_MySQL_Lexer::TRIGGER_SYMBOL:
				return 'Unsupported CREATE TRIGGER statement.';

			case WP_MySQL_Lexer::EVENT_SYMBOL:
				return 'Unsupported CREATE EVENT statement.';

			case WP_MySQL_Lexer::USER_SYMBOL:
				return 'Unsupported CREATE USER statement.';

			case WP_MySQL_Lexer::ROLE_SYMBOL:
				return 'Unsupported CREATE ROLE statement.';

			case WP_MySQL_Lexer::SERVER_SYMBOL:
				return 'Unsupported CREATE SERVER statement.';

			case WP_MySQL_Lexer::LOGFILE_SYMBOL:
				return 'Unsupported CREATE LOGFILE statement.';

			case WP_MySQL_Lexer::TABLESPACE_SYMBOL:
				return 'Unsupported CREATE TABLESPACE statement.';
		}

		return 'Unsupported CREATE statement.';
	}

	/**
	 * Get an explicit unsupported error for MySQL CREATE TABLE forms not handled by supported translators.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Position immediately after TABLE.
	 * @return string|null Unsupported error message, or null for backend-compatible plain CREATE TABLE.
	 */
	private function get_unsupported_mysql_create_table_statement_message( array $tokens, int $position ): ?string {
		$statement_end = $this->get_mysql_statement_end_position( $tokens, $position );
		if ( null === $statement_end ) {
			return 'Unsupported CREATE TABLE statement.';
		}

		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ], $tokens[ $position + 2 ] )
			&& WP_MySQL_Lexer::IF_SYMBOL === $tokens[ $position ]->id
			&& WP_MySQL_Lexer::NOT_SYMBOL === $tokens[ $position + 1 ]->id
			&& WP_MySQL_Lexer::EXISTS_SYMBOL === $tokens[ $position + 2 ]->id
		) {
			$position += 3;
		}

		$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position, true );
		if ( null === $table_reference ) {
			return 'Unsupported CREATE TABLE statement.';
		}

		if ( $this->is_at_mysql_query_end( $tokens, $position ) ) {
			return 'Unsupported CREATE TABLE statement.';
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::LIKE_SYMBOL === $tokens[ $position ]->id ) {
			return 'Unsupported CREATE TABLE statement.';
		}

		$has_as = false;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::AS_SYMBOL === $tokens[ $position ]->id ) {
			$has_as = true;
			++$position;
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[ $position ]->id ) {
			return 'Unsupported CREATE TABLE statement.';
		}

		if ( $has_as && isset( $tokens[ $position ] ) && WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
			return 'Unsupported CREATE TABLE statement.';
		}

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position ]->id ) {
			return 'Unsupported CREATE TABLE statement.';
		}

		$definition_end = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $statement_end );
		if ( null === $definition_end ) {
			return 'Unsupported CREATE TABLE statement.';
		}

		$position = $definition_end;
		if ( $this->is_at_mysql_query_end( $tokens, $position ) ) {
			return null;
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::AS_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		if (
			isset( $tokens[ $position ] )
			&& (
				WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[ $position ]->id
				|| WP_MySQL_Lexer::LIKE_SYMBOL === $tokens[ $position ]->id
			)
		) {
			return 'Unsupported CREATE TABLE statement.';
		}

		return 'Unsupported CREATE TABLE statement.';
	}

	/**
	 * Check whether CREATE TABLE has unsupported MySQL column attributes.
	 *
	 * @param string $query MySQL query.
	 * @return bool Whether the statement should fail before backend execution.
	 */
	private function contains_unsupported_mysql_create_table_column_attribute_query( string $query ): bool {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! $this->is_mysql_create_table_statement_prefix( $tokens ) ) {
			return false;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if (
			null === $statement_end
			|| ! $this->contains_unsupported_mysql_column_attribute_tokens( $tokens, 0, $statement_end )
		) {
			return false;
		}

		try {
			$translator = new WP_PostgreSQL_Create_Table_Translator( $this->active_sql_modes );
			$translator->translate_schema( $query );
		} catch ( InvalidArgumentException $e ) {
			return 'Unsupported CREATE TABLE column attribute.' === $e->getMessage();
		}

		return false;
	}

	/**
	 * Check whether a token stream starts with CREATE [TEMPORARY] TABLE.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @return bool Whether this is a CREATE TABLE statement.
	 */
	private function is_mysql_create_table_statement_prefix( array $tokens ): bool {
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::CREATE_SYMBOL !== $tokens[0]->id ) {
			return false;
		}

		$position = 1;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::TEMPORARY_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		return isset( $tokens[ $position ] ) && WP_MySQL_Lexer::TABLE_SYMBOL === $tokens[ $position ]->id;
	}

	/**
	 * Check whether a query can use the exact SELECT translation cache.
	 *
	 * This intentionally uses a cheap prefix check. Queries with leading comments
	 * or parenthesized SELECTs keep the uncached fallback path rather than paying
	 * lexer cost just to decide cacheability.
	 *
	 * @param string $query MySQL query.
	 * @return bool Whether the query is cacheable by exact SQL text.
	 */
	private function is_mysql_select_translation_cacheable_query( string $query ): bool {
		return 1 === preg_match( '/\A\s*SELECT\b/i', $query );
	}

	/**
	 * Get the PostgreSQL execution SQL for a MySQL SELECT query.
	 *
	 * @param string $query MySQL SELECT query.
	 * @return array{sql: string, translated: bool} PostgreSQL SQL and translation flag.
	 */
	private function get_mysql_select_query_translation( string $query ): array {
		$cached_translation = $this->get_mysql_select_translation_cache_entry( $query );
		if ( null !== $cached_translation ) {
			return array(
				'sql'        => $cached_translation['sql'],
				'translated' => $cached_translation['translated'],
			);
		}

		$translation = $this->translate_mysql_select_query_for_postgresql( $query );
		$this->set_mysql_select_translation_cache_entry( $query, $translation );

		return $translation;
	}

	/**
	 * Check whether a query is a top-level MySQL SELECT after lexer normalization.
	 *
	 * @param string $query MySQL query.
	 * @return bool Whether the lexer sees a complete SELECT statement.
	 */
	private function is_mysql_top_level_select_query( string $query ): bool {
		$tokens = $this->get_mysql_tokens( $query );
		return isset( $tokens[0] )
			&& WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[0]->id
			&& null !== $this->get_mysql_statement_end_position( $tokens, 1 );
	}

	/**
	 * Translate a MySQL SELECT query using the existing ordered translator chain.
	 *
	 * @param string $query MySQL SELECT query.
	 * @return array{sql: string, translated: bool} PostgreSQL SQL and translation flag.
	 */
	private function translate_mysql_select_query_for_postgresql( string $query ): array {
		$translated_query = $this->translate_information_schema_tables_site_health_query( $query );
		if ( null !== $translated_query ) {
			return array(
				'sql'        => $translated_query,
				'translated' => true,
			);
		}

		$translated_query = $this->translate_mysql_select_row_locking_query( $query );
		if ( null !== $translated_query ) {
			return array(
				'sql'        => $translated_query,
				'translated' => true,
			);
		}

		$translated_query = $this->translate_direct_information_schema_select_query( $query );
		if ( null !== $translated_query ) {
			return array(
				'sql'        => $translated_query,
				'translated' => true,
			);
		}
		if ( $this->should_reject_unsupported_direct_information_schema_select_query( $query ) ) {
			throw new InvalidArgumentException( 'Unsupported information_schema query.' );
		}

		$translated_query = $this->translate_strict_aggregate_grouped_order_by_query( $query );
		if ( null !== $translated_query ) {
			return array(
				'sql'        => $translated_query,
				'translated' => true,
			);
		}

		$translated_query = $this->translate_grouped_having_alias_query( $query );
		if ( null !== $translated_query ) {
			return array(
				'sql'        => $translated_query,
				'translated' => true,
			);
		}

		$translated_query = $this->translate_wordpress_available_post_mime_types_query( $query );
		if ( null !== $translated_query ) {
			return array(
				'sql'        => $translated_query,
				'translated' => true,
			);
		}

		$translated_query = $this->translate_wordpress_term_cache_priming_query( $query );
		if ( null !== $translated_query ) {
			return array(
				'sql'        => $translated_query,
				'translated' => true,
			);
		}

		$translated_query = $this->translate_wordpress_approved_comments_query( $query );
		if ( null !== $translated_query ) {
			return array(
				'sql'        => $translated_query,
				'translated' => true,
			);
		}

		$translated_query = $this->translate_mysql_version_function_select_query( $query );
		if ( null !== $translated_query ) {
			return array(
				'sql'        => $translated_query,
				'translated' => true,
			);
		}

		$translated_query = $this->translate_wordpress_postmeta_distinct_meta_key_having_query( $query );
		if ( null !== $translated_query ) {
			return array(
				'sql'        => $translated_query,
				'translated' => true,
			);
		}

		$translated_query = $this->translate_simple_mysql_select_query( $query );
		if ( null !== $translated_query ) {
			return array(
				'sql'        => $translated_query,
				'translated' => true,
			);
		}

		$translated_query = $this->translate_distinct_order_by_query( $query );
		if ( null !== $translated_query ) {
			return array(
				'sql'        => $translated_query,
				'translated' => true,
			);
		}

		$translated_query = $this->translate_sql_calc_found_rows_select_query( $query );
		if ( null !== $translated_query ) {
			return array(
				'sql'        => $translated_query,
				'translated' => true,
			);
		}

		$translated_query = $this->translate_mysql_compatible_query( $query );
		if ( null !== $translated_query ) {
			return array(
				'sql'        => $translated_query,
				'translated' => true,
			);
		}

		return array(
			'sql'        => $query,
			'translated' => false,
		);
	}

	/**
	 * Get a cached exact SELECT translation.
	 *
	 * @param string $query MySQL SELECT query.
	 * @return array{query: string, sql: string, translated: bool}|null Cached translation.
	 */
	private function get_mysql_select_translation_cache_entry( string $query ): ?array {
		$cache_key = $this->get_mysql_query_translation_cache_key( $query );
		if (
			! isset( $this->mysql_select_translation_cache[ $cache_key ] )
			|| $this->mysql_select_translation_cache[ $cache_key ]['query'] !== $query
		) {
			return null;
		}

		return $this->mysql_select_translation_cache[ $cache_key ];
	}

	/**
	 * Store a cached exact SELECT translation.
	 *
	 * @param string                           $query       MySQL SELECT query.
	 * @param array{sql: string, translated: bool} $translation PostgreSQL translation.
	 */
	private function set_mysql_select_translation_cache_entry( string $query, array $translation ): void {
		$cache_key = $this->get_mysql_query_translation_cache_key( $query );
		$this->mysql_select_translation_cache[ $cache_key ] = array(
			'query'      => $query,
			'sql'        => $translation['sql'],
			'translated' => $translation['translated'],
		);

		$this->limit_mysql_query_translation_cache( $this->mysql_select_translation_cache );
	}

	/**
	 * Get the cache key for an exact MySQL query translation.
	 *
	 * @param string $query MySQL query.
	 * @return string Cache key.
	 */
	private function get_mysql_query_translation_cache_key( string $query ): string {
		return sha1( $query );
	}

	/**
	 * Keep an exact query translation cache bounded.
	 *
	 * @param array $cache Cache to trim.
	 */
	private function limit_mysql_query_translation_cache( array &$cache ): void {
		while ( count( $cache ) > self::MYSQL_QUERY_TRANSLATION_CACHE_LIMIT ) {
			reset( $cache );
			$first_key = key( $cache );
			if ( null === $first_key ) {
				return;
			}
			unset( $cache[ $first_key ] );
		}
	}

	/**
	 * Decode PostgreSQL-safe text envelopes in fetched result data.
	 *
	 * @param mixed $value Fetched result value.
	 * @return mixed MySQL-facing result value.
	 */
	private function decode_postgresql_text_for_mysql_in_result( $value ) {
		if ( is_string( $value ) ) {
			return self::decode_postgresql_text_for_mysql_value( $value );
		}

		if ( is_array( $value ) ) {
			foreach ( $value as $key => $item ) {
				$value[ $key ] = $this->decode_postgresql_text_for_mysql_in_result( $item );
			}
			return $value;
		}

		if ( is_object( $value ) ) {
			foreach ( get_object_vars( $value ) as $key => $item ) {
				$value->$key = $this->decode_postgresql_text_for_mysql_in_result( $item );
			}
		}

		return $value;
	}

	/**
	 * Decode MySQL text bytes previously encoded for PostgreSQL storage.
	 *
	 * @param string $value PostgreSQL text value.
	 * @return string MySQL-facing text value.
	 */
	private static function decode_postgresql_text_for_mysql_value( string $value ): string {
		if ( 0 !== strpos( $value, self::MYSQL_TEXT_ENCODING_PREFIX ) ) {
			return $value;
		}

		$encoded          = substr( $value, strlen( self::MYSQL_TEXT_ENCODING_PREFIX ) );
		$length_separator = strpos( $encoded, ':' );
		if ( false === $length_separator ) {
			return $value;
		}

		$length = substr( $encoded, 0, $length_separator );
		if ( ! self::is_canonical_decimal_string( $length ) ) {
			return $value;
		}

		$encoded        = substr( $encoded, $length_separator + 1 );
		$hash_separator = strpos( $encoded, ':' );
		if ( false === $hash_separator ) {
			return $value;
		}

		$hash = substr( $encoded, 0, $hash_separator );
		$hex  = substr( $encoded, $hash_separator + 1 );
		if (
			1 !== preg_match( '/\A[0-9a-f]{64}\z/', $hash )
			|| 0 !== strlen( $hex ) % 2
			|| ! ctype_xdigit( $hex )
		) {
			return $value;
		}

		$decoded = hex2bin( $hex );
		if (
			false === $decoded
			|| (string) strlen( $decoded ) !== $length
			|| ! hash_equals( $hash, hash( 'sha256', self::MYSQL_TEXT_ENCODING_HASH_CONTEXT . $decoded ) )
		) {
			return $value;
		}

		return $decoded;
	}

	/**
	 * Check whether a string is a canonical decimal integer.
	 *
	 * @param string $value String value.
	 * @return bool Whether the value is canonical decimal.
	 */
	private static function is_canonical_decimal_string( string $value ): bool {
		if ( '' === $value ) {
			return false;
		}

		if ( '0' === $value ) {
			return true;
		}

		return '0' !== $value[0] && ctype_digit( $value );
	}

	/**
	 * Execute the unbounded count query for a SQL_CALC_FOUND_ROWS SELECT.
	 *
	 * @param string $query MySQL query.
	 * @return int Total matching rows before LIMIT/OFFSET.
	 */
	private function execute_sql_calc_found_rows_count_query( string $query ): int {
		$count_query = $this->get_sql_calc_found_rows_count_query( $query );
		if ( null === $count_query ) {
			throw new PDOException( 'Unsupported SQL_CALC_FOUND_ROWS query shape for PostgreSQL FOUND_ROWS accounting.' );
		}

		$stmt                            = $this->connection->query( $count_query );
		$this->last_postgresql_queries[] = array(
			'sql'    => $count_query,
			'params' => array(),
		);

		$row = $stmt->fetch( PDO::FETCH_ASSOC );
		if ( ! is_array( $row ) || ! array_key_exists( '__wp_pg_found_rows', $row ) ) {
			throw new PDOException( 'Failed to read PostgreSQL FOUND_ROWS accounting result.' );
		}

		return (int) $row['__wp_pg_found_rows'];
	}

	/**
	 * Build the PostgreSQL count query for a SQL_CALC_FOUND_ROWS SELECT.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL count query, or null when unsupported.
	 */
	private function get_sql_calc_found_rows_count_query( string $query ): ?string {
		$cached_count_query = $this->get_mysql_sql_calc_found_rows_count_query_cache_entry( $query );
		if ( null !== $cached_count_query ) {
			return $cached_count_query;
		}

		$count_query = $this->get_sql_calc_found_rows_direct_count_query( $query );
		if ( null !== $count_query ) {
			$this->set_mysql_sql_calc_found_rows_count_query_cache_entry( $query, $count_query );
			return $count_query;
		}

		$select_query = $this->translate_sql_calc_found_rows_count_select_query( $query );
		if ( null === $select_query ) {
			return null;
		}

		$alias       = $this->connection->quote_identifier( '__wp_pg_found_rows' );
		$count_query = sprintf(
			'SELECT COUNT(*) AS %1$s FROM (%2$s) AS %1$s',
			$alias,
			$select_query
		);
		$this->set_mysql_sql_calc_found_rows_count_query_cache_entry( $query, $count_query );
		return $count_query;
	}

	/**
	 * Get cached PostgreSQL SQL for a SQL_CALC_FOUND_ROWS count query.
	 *
	 * @param string $query MySQL SQL_CALC_FOUND_ROWS query.
	 * @return string|null Cached PostgreSQL count SQL.
	 */
	private function get_mysql_sql_calc_found_rows_count_query_cache_entry( string $query ): ?string {
		$cache_key = $this->get_mysql_query_translation_cache_key( $query );
		if (
			! isset( $this->mysql_sql_calc_found_rows_count_query_cache[ $cache_key ] )
			|| $this->mysql_sql_calc_found_rows_count_query_cache[ $cache_key ]['query'] !== $query
		) {
			return null;
		}

		return $this->mysql_sql_calc_found_rows_count_query_cache[ $cache_key ]['sql'];
	}

	/**
	 * Store cached PostgreSQL SQL for a SQL_CALC_FOUND_ROWS count query.
	 *
	 * @param string $query       MySQL SQL_CALC_FOUND_ROWS query.
	 * @param string $count_query PostgreSQL count SQL.
	 */
	private function set_mysql_sql_calc_found_rows_count_query_cache_entry( string $query, string $count_query ): void {
		$cache_key = $this->get_mysql_query_translation_cache_key( $query );
		$this->mysql_sql_calc_found_rows_count_query_cache[ $cache_key ] = array(
			'query' => $query,
			'sql'   => $count_query,
		);

		$this->limit_mysql_query_translation_cache( $this->mysql_sql_calc_found_rows_count_query_cache );
	}

	/**
	 * Check whether a fetch mode can hide the internal FOUND_ROWS window column.
	 *
	 * @param int $fetch_mode PDO fetch mode.
	 * @return bool Whether the hidden window column can be removed safely.
	 */
	private function is_sql_calc_found_rows_window_fetch_mode( $fetch_mode ): bool {
		return in_array( (int) $fetch_mode, array( PDO::FETCH_OBJ, PDO::FETCH_ASSOC ), true );
	}

	/**
	 * Translate a simple SQL_CALC_FOUND_ROWS SELECT using one PostgreSQL query.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query carrying a hidden FOUND_ROWS value, or null.
	 */
	private function translate_sql_calc_found_rows_window_select_query( string $query ): ?string {
		if ( false !== stripos( $query, self::SQL_CALC_FOUND_ROWS_WINDOW_COLUMN ) ) {
			return null;
		}

		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0], $tokens[1] )
			|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id
			|| WP_MySQL_Lexer::SQL_CALC_FOUND_ROWS_SYMBOL !== $tokens[1]->id
		) {
			return null;
		}

		$projection_start = 2;
		$statement_end    = $this->get_mysql_statement_end_position( $tokens, $projection_start );
		if ( null === $statement_end ) {
			return null;
		}

		$limit_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::LIMIT_SYMBOL,
			$projection_start,
			$statement_end
		);
		if ( null !== $limit_position && ! $this->is_supported_simple_select_limit_clause( $tokens, $limit_position, $statement_end ) ) {
			return null;
		}

		$select_end = $limit_position ?? $statement_end;
		if (
			$this->contains_top_level_mysql_token(
				$tokens,
				$projection_start,
				$select_end,
				array(
					WP_MySQL_Lexer::DISTINCT_SYMBOL,
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::GROUP_SYMBOL,
					WP_MySQL_Lexer::HAVING_SYMBOL,
					WP_MySQL_Lexer::HIGH_PRIORITY_SYMBOL,
					WP_MySQL_Lexer::INTO_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::SELECT_SYMBOL,
					WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				)
			)
		) {
			return null;
		}

		$from_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::FROM_SYMBOL,
			$projection_start,
			$select_end
		);
		if ( null === $from_position || $projection_start === $from_position ) {
			return null;
		}

		if ( $this->contains_mysql_aggregate_call( $tokens, $projection_start, $from_position ) ) {
			return null;
		}

		$replacements = $this->get_mysql_select_statement_contextual_replacements(
			$tokens,
			$projection_start,
			$select_end
		) ?? array();

		$sql = sprintf(
			'SELECT %s, COUNT(*) OVER() AS %s %s',
			$this->translate_mysql_token_sequence_to_postgresql( $tokens, $projection_start, $from_position ),
			$this->connection->quote_identifier( self::SQL_CALC_FOUND_ROWS_WINDOW_COLUMN ),
			$this->translate_mysql_token_sequence_with_replacements_to_postgresql(
				$tokens,
				$from_position,
				$select_end,
				$replacements
			)
		);

		if ( null !== $limit_position ) {
			$sql .= $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end );
		}

			return $sql;
	}

	/**
	 * Extract and remove the hidden FOUND_ROWS window column from result rows.
	 *
	 * @param mixed $rows Result rows.
	 * @return int|null FOUND_ROWS value, or null when the fallback count is needed.
	 */
	private function extract_sql_calc_found_rows_window_result( &$rows ): ?int {
		if ( ! is_array( $rows ) || empty( $rows ) ) {
			return null;
		}

		$found_rows = null;
		$column     = self::SQL_CALC_FOUND_ROWS_WINDOW_COLUMN;
		foreach ( $rows as &$row ) {
			if ( is_object( $row ) ) {
				if ( ! property_exists( $row, $column ) ) {
					return null;
				}

				$found_rows = (int) $row->{$column};
				unset( $row->{$column} );
				continue;
			}

			if ( ! is_array( $row ) || ! array_key_exists( $column, $row ) ) {
				return null;
			}

			$found_rows = (int) $row[ $column ];
			unset( $row[ $column ] );
		}
		unset( $row );

		return $found_rows;
	}

	/**
	 * Remove hidden FOUND_ROWS metadata before exposing column metadata to wpdb.
	 */
	private function remove_sql_calc_found_rows_window_column_meta(): void {
		if ( null !== $this->last_column_meta_statement ) {
			$this->last_column_meta_excluded_names[ self::SQL_CALC_FOUND_ROWS_WINDOW_COLUMN ] = true;
			$this->last_column_count = max( 0, $this->last_column_count - 1 );
			return;
		}

		foreach ( $this->last_column_meta as $index => $column_meta ) {
			if ( self::SQL_CALC_FOUND_ROWS_WINDOW_COLUMN !== ( $column_meta['name'] ?? '' ) ) {
				continue;
			}

			unset( $this->last_column_meta[ $index ] );
			$this->last_column_meta = array_values( $this->last_column_meta );
			return;
		}
	}

	/**
	 * Build a direct PostgreSQL count query for simple SQL_CALC_FOUND_ROWS SELECTs.
	 *
	 * Non-DISTINCT, non-grouped, non-aggregate SELECTs have the same FOUND_ROWS
	 * cardinality as COUNT(*) over the FROM/WHERE source. DISTINCT, aggregate,
	 * GROUP BY, and HAVING shapes stay on the derived-table fallback because
	 * their projection determines the counted row set.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL count query, or null when the wrapped fallback is required.
	 */
	private function get_sql_calc_found_rows_direct_count_query( string $query ): ?string {
		$query = $this->get_sql_calc_found_rows_count_source_query( $query );
		if ( null === $query ) {
			return null;
		}

		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0], $tokens[1] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$projection_start = 1;
		if ( WP_MySQL_Lexer::SQL_CALC_FOUND_ROWS_SYMBOL === $tokens[ $projection_start ]->id ) {
			++$projection_start;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, $projection_start );
		if ( null === $statement_end ) {
			return null;
		}

		if (
			$this->contains_top_level_mysql_token(
				$tokens,
				$projection_start,
				$statement_end,
				array(
					WP_MySQL_Lexer::DISTINCT_SYMBOL,
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::GROUP_SYMBOL,
					WP_MySQL_Lexer::HAVING_SYMBOL,
					WP_MySQL_Lexer::INTO_SYMBOL,
					WP_MySQL_Lexer::LIMIT_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::ORDER_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				)
			)
		) {
			return null;
		}

		$from_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::FROM_SYMBOL,
			$projection_start,
			$statement_end
		);
		if ( null === $from_position ) {
			return null;
		}

		if ( $this->contains_mysql_aggregate_call( $tokens, $projection_start, $from_position ) ) {
			return null;
		}

		return sprintf(
			'SELECT COUNT(*) AS %s %s',
			$this->connection->quote_identifier( '__wp_pg_found_rows' ),
			$this->translate_sql_calc_found_rows_direct_count_source_to_postgresql( $tokens, $from_position, $statement_end )
		);
	}

	/**
	 * Translate a direct FOUND_ROWS count source while preserving contextual predicate rewrites.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $from_position FROM token position.
	 * @param int              $statement_end Final statement token position, exclusive.
	 * @return string PostgreSQL FROM/WHERE SQL.
	 */
	private function translate_sql_calc_found_rows_direct_count_source_to_postgresql(
		array $tokens,
		int $from_position,
		int $statement_end
	): string {
		$where_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::WHERE_SYMBOL,
			$from_position + 1,
			$statement_end
		);
		if ( null === $where_position ) {
			return $this->translate_mysql_token_sequence_to_postgresql( $tokens, $from_position, $statement_end );
		}

		$scope = $this->get_mysql_select_scope( $tokens, $from_position + 1, $where_position );
		if ( null === $scope ) {
			return $this->translate_mysql_token_sequence_to_postgresql( $tokens, $from_position, $statement_end );
		}

		$where_sql = $this->translate_mysql_predicate_token_sequence_to_postgresql(
			$tokens,
			$where_position + 1,
			$statement_end,
			$scope
		);
		if ( ! $where_sql['changed'] ) {
			return $this->translate_mysql_token_sequence_to_postgresql( $tokens, $from_position, $statement_end );
		}

		return $this->translate_mysql_token_sequence_with_replacements_to_postgresql(
			$tokens,
			$from_position,
			$statement_end,
			array(
				array(
					'start' => $where_position + 1,
					'end'   => $statement_end,
					'sql'   => $where_sql['sql'],
				),
			)
		);
	}

	/**
	 * Translate the unbounded SELECT used for SQL_CALC_FOUND_ROWS accounting.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL SELECT query, or null when unsupported.
	 */
	private function translate_sql_calc_found_rows_count_select_query( string $query ): ?string {
		$query = $this->get_sql_calc_found_rows_count_source_query( $query );
		if ( null === $query ) {
			return null;
		}

		$translated_query = $this->translate_strict_aggregate_grouped_order_by_query( $query, false );
		if ( null !== $translated_query ) {
			return $translated_query;
		}

		$translated_query = $this->translate_distinct_order_by_query( $query, false );
		if ( null !== $translated_query ) {
			return $translated_query;
		}

		return $this->translate_sql_calc_found_rows_select_query( $query, false );
	}

	/**
	 * Build the unordered, unbounded MySQL SELECT used for FOUND_ROWS accounting.
	 *
	 * @param string $query MySQL query.
	 * @return string|null MySQL query without top-level ORDER BY or LIMIT clauses.
	 */
	private function get_sql_calc_found_rows_count_source_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return null;
		}

		$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, 1, $statement_end );
		if ( null !== $limit_position && ! $this->is_supported_simple_select_limit_clause( $tokens, $limit_position, $statement_end ) ) {
			return null;
		}

		$select_end     = $limit_position ?? $statement_end;
		$order_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::ORDER_SYMBOL, 1, $select_end );
		$count_end      = $order_position ?? $select_end;

		return rtrim( substr( $query, 0, $tokens[ $count_end ]->start ) );
	}

	/**
	 * Execute translated PostgreSQL statements for a single MySQL-facing query.
	 *
	 * @param string[] $statements PostgreSQL SQL statements to execute.
	 * @return mixed Return value from the last executed statement.
	 */
	private function execute_postgresql_statements( array $statements ) {
		if ( empty( $statements ) ) {
			return 0;
		}

		foreach ( $statements as $statement ) {
			$stmt                            = $this->connection->query( $statement );
			$this->last_postgresql_queries[] = array(
				'sql'    => $statement,
				'params' => array(),
			);
			$this->last_result               = $stmt->rowCount();
		}

		$this->last_column_meta = array();
		return $this->last_result;
	}

	/**
	 * Execute PostgreSQL side-effect statements without changing the query result.
	 *
	 * @param string[] $statements PostgreSQL SQL statements to execute.
	 */
	private function execute_postgresql_side_effect_statements( array $statements ): void {
		foreach ( $statements as $statement ) {
			$this->connection->query( $statement );
			$this->last_postgresql_queries[] = array(
				'sql'    => $statement,
				'params' => array(),
			);
		}
	}

	/**
	 * Execute translated DML statements for a single MySQL-facing query.
	 *
	 * @param array    $dml_query    Translated DML query metadata.
	 * @param int|null $return_value Optional MySQL-compatible return value.
	 * @return int Number of affected rows.
	 */
	private function execute_translated_dml_statements( array $dml_query, ?int $return_value = null ): int {
		if ( ! isset( $dml_query['statements'] ) || ! is_array( $dml_query['statements'] ) ) {
			return 0;
		}

		$affected_rows = 0;
		foreach ( $dml_query['statements'] as $statement ) {
			$statement                       = (string) $statement;
			$stmt                            = $this->connection->query( $statement );
			$this->last_postgresql_queries[] = array(
				'sql'    => $statement,
				'params' => array(),
			);
			$affected_rows                  += $stmt->rowCount();
		}

		$this->clear_last_column_meta();
		$this->last_result = $return_value ?? $affected_rows;
		$this->set_last_insert_id_after_dml_success( $dml_query, $affected_rows );
		$this->repair_dml_identity_sequences_after_success( $dml_query, $affected_rows );

		return (int) $this->last_result;
	}

	/**
	 * Execute a materialized REPLACE ... SELECT delete-then-insert flow.
	 *
	 * @param array $replace_query Translated REPLACE ... SELECT metadata.
	 * @return int MySQL-compatible affected rows.
	 */
	private function execute_materialized_mysql_replace_select_statements( array $replace_query ): int {
		$materialize_statements = isset( $replace_query['materialize_statements'] ) && is_array( $replace_query['materialize_statements'] )
			? $replace_query['materialize_statements']
			: array();
		$mutation_statements    = isset( $replace_query['mutation_statements'] ) && is_array( $replace_query['mutation_statements'] )
			? $replace_query['mutation_statements']
			: array();
		$cleanup_statements     = isset( $replace_query['cleanup_statements'] ) && is_array( $replace_query['cleanup_statements'] )
			? $replace_query['cleanup_statements']
			: array();

		foreach ( $materialize_statements as $statement ) {
			$statement                       = (string) $statement;
			$stmt                            = $this->connection->query( $statement );
			$this->last_postgresql_queries[] = array(
				'sql'    => $statement,
				'params' => array(),
			);
			$stmt->closeCursor();
		}

		try {
			if ( isset( $replace_query['duplicate_conflict_rows_sql'] ) && is_string( $replace_query['duplicate_conflict_rows_sql'] ) ) {
				$stmt          = $this->connection->query( $replace_query['duplicate_conflict_rows_sql'] );
				$has_duplicate = false !== $stmt->fetchColumn();
				$stmt->closeCursor();
			} else {
				$has_duplicate = false;
			}

			$return_value = null;
			if ( $has_duplicate ) {
				$affected_rows                     = $this->execute_materialized_mysql_replace_select_rows_sequentially( $replace_query );
				$return_value                      = $affected_rows;
				$replace_query['inserted_new_row'] = $affected_rows > 0;
			} elseif ( isset( $replace_query['replace_select_affected_rows_sql'] ) && is_string( $replace_query['replace_select_affected_rows_sql'] ) ) {
				$stmt = $this->connection->query( $replace_query['replace_select_affected_rows_sql'] );
				$row  = $stmt->fetch( PDO::FETCH_ASSOC );
				$stmt->closeCursor();
				if ( is_array( $row ) && isset( $row['affected_rows'] ) ) {
					$return_value                      = (int) $row['affected_rows'];
					$replace_query['inserted_new_row'] = isset( $row['inserted_rows'] ) && (int) $row['inserted_rows'] > 0;
				}
			}

			if ( ! $has_duplicate ) {
				$affected_rows = 0;
				foreach ( $mutation_statements as $statement ) {
					$statement                       = (string) $statement;
					$stmt                            = $this->connection->query( $statement );
					$this->last_postgresql_queries[] = array(
						'sql'    => $statement,
						'params' => array(),
					);
					$affected_rows                  += $stmt->rowCount();
				}
			}
		} finally {
			foreach ( $cleanup_statements as $statement ) {
				$statement                       = (string) $statement;
				$stmt                            = $this->connection->query( $statement );
				$this->last_postgresql_queries[] = array(
					'sql'    => $statement,
					'params' => array(),
				);
				$stmt->closeCursor();
			}
		}

		$this->clear_last_column_meta();
		$this->last_result = $return_value ?? $affected_rows;
		$this->set_last_insert_id_after_dml_success( $replace_query, $affected_rows );
		$this->repair_dml_identity_sequences_after_success( $replace_query, $affected_rows );

		return (int) $this->last_result;
	}

	/**
	 * Replay a materialized REPLACE ... SELECT source one row at a time.
	 *
	 * Duplicate source conflict keys need MySQL's row-by-row REPLACE semantics:
	 * each later row may delete the row inserted by an earlier source row.
	 *
	 * @param array $replace_query Translated REPLACE ... SELECT metadata.
	 * @return int MySQL-compatible affected rows.
	 */
	private function execute_materialized_mysql_replace_select_rows_sequentially( array $replace_query ): int {
		if (
			! isset( $replace_query['table_name'], $replace_query['columns'], $replace_query['source_table_sql'], $replace_query['ordinal_source_table_sql'], $replace_query['conflict_index_groups'] )
			|| ! is_string( $replace_query['table_name'] )
			|| ! is_array( $replace_query['columns'] )
			|| ! is_string( $replace_query['source_table_sql'] )
			|| ! is_string( $replace_query['ordinal_source_table_sql'] )
			|| ! is_array( $replace_query['conflict_index_groups'] )
		) {
			throw new InvalidArgumentException( 'Unsupported REPLACE SELECT statement.' );
		}

		$ordinal_column       = '__wp_pg_replace_ordinal';
		$quoted_ordinal      = $this->connection->quote_identifier( $ordinal_column );
		$source_alias        = $this->connection->quote_identifier( '__wp_pg_replace_source' );
		$rows_alias          = $this->connection->quote_identifier( '__wp_pg_replace_rows' );
		$target_alias        = $this->connection->quote_identifier( '__wp_pg_replace_target' );
		$quoted_target_table = $this->connection->quote_identifier( $replace_query['table_name'] );
		$column_sql          = implode( ', ', array_map( array( $this->connection, 'quote_identifier' ), $replace_query['columns'] ) );

		$insert_projection_sql = array();
		foreach ( $replace_query['columns'] as $column ) {
			$insert_projection_sql[] = sprintf(
				'%s.%s',
				$rows_alias,
				$this->connection->quote_identifier( (string) $column )
			);
		}

		$delete_predicate_sql = $this->get_mysql_replace_select_delete_predicate_sql(
			$target_alias,
			$rows_alias,
			$replace_query['conflict_index_groups']
		);
		if ( null === $delete_predicate_sql ) {
			throw new InvalidArgumentException( 'Unsupported REPLACE SELECT statement.' );
		}

		$create_ordinal_table_sql = sprintf(
			'CREATE TEMPORARY TABLE %s AS SELECT ROW_NUMBER() OVER () AS %s, %s.* FROM %s AS %s',
			$replace_query['ordinal_source_table_sql'],
			$quoted_ordinal,
			$source_alias,
			$replace_query['source_table_sql'],
			$source_alias
		);
		$stmt                     = $this->connection->query( $create_ordinal_table_sql );
		$this->last_postgresql_queries[] = array(
			'sql'    => $create_ordinal_table_sql,
			'params' => array(),
		);
		$stmt->closeCursor();

		$drop_ordinal_table_sql = sprintf( 'DROP TABLE IF EXISTS %s', $replace_query['ordinal_source_table_sql'] );

		try {
			$stmt     = $this->connection->query(
				sprintf(
					'SELECT %1$s FROM %2$s ORDER BY %1$s',
					$quoted_ordinal,
					$replace_query['ordinal_source_table_sql']
				)
			);
			$ordinals = $stmt->fetchAll( PDO::FETCH_COLUMN );
			$stmt->closeCursor();

			$affected_rows = 0;
			foreach ( $ordinals as $ordinal ) {
				$ordinal_value = (int) $ordinal;
				$row_filter    = sprintf( '%s.%s = %d', $rows_alias, $quoted_ordinal, $ordinal_value );
				$delete_sql    = sprintf(
					'DELETE FROM %s AS %s WHERE EXISTS (SELECT 1 FROM %s AS %s WHERE %s AND %s)',
					$quoted_target_table,
					$target_alias,
					$replace_query['ordinal_source_table_sql'],
					$rows_alias,
					$row_filter,
					$delete_predicate_sql
				);
				$insert_sql    = sprintf(
					'INSERT INTO %s (%s) SELECT %s FROM %s AS %s WHERE %s',
					$quoted_target_table,
					$column_sql,
					implode( ', ', $insert_projection_sql ),
					$replace_query['ordinal_source_table_sql'],
					$rows_alias,
					$row_filter
				);

				foreach ( array( $delete_sql, $insert_sql ) as $statement ) {
					$stmt                            = $this->connection->query( $statement );
					$this->last_postgresql_queries[] = array(
						'sql'    => $statement,
						'params' => array(),
					);
					$affected_rows                  += $stmt->rowCount();
				}
			}

			return $affected_rows;
		} finally {
			$stmt                            = $this->connection->query( $drop_ordinal_table_sql );
			$this->last_postgresql_queries[] = array(
				'sql'    => $drop_ordinal_table_sql,
				'params' => array(),
			);
			$stmt->closeCursor();
		}
	}

	/**
	 * Execute a translated MySQL multi-target DELETE query.
	 *
	 * @param string $statement PostgreSQL writable-CTE statement.
	 * @return int Total rows deleted from all target tables.
	 */
	private function execute_mysql_multi_target_delete_query( string $statement ): int {
		$stmt                            = $this->connection->query( $statement );
		$this->last_postgresql_queries[] = array(
			'sql'    => $statement,
			'params' => array(),
		);

		$row = $stmt->fetch( PDO::FETCH_ASSOC );
		$this->clear_last_column_meta();
		$this->last_result = isset( $row['affected_rows'] ) ? (int) $row['affected_rows'] : 0;

		return $this->last_result;
	}

	/**
	 * Execute a translated MySQL multi-target UPDATE query.
	 *
	 * @param string $statement PostgreSQL writable-CTE statement.
	 * @return int Total rows updated across all target tables.
	 */
	private function execute_mysql_multi_target_update_query( string $statement ): int {
		$stmt                            = $this->connection->query( $statement );
		$this->last_postgresql_queries[] = array(
			'sql'    => $statement,
			'params' => array(),
		);

		$row = $stmt->fetch( PDO::FETCH_ASSOC );
		$this->clear_last_column_meta();
		$this->last_result = isset( $row['affected_rows'] ) ? (int) $row['affected_rows'] : 0;

		return $this->last_result;
	}

	/**
	 * Execute a simple MySQL transaction-control statement in PostgreSQL.
	 *
	 * @param string $statement Canonical PostgreSQL transaction statement.
	 * @return int Number of affected rows.
	 */
	private function execute_mysql_transaction_control_query( string $statement ): int {
		$pdo            = $this->connection->get_pdo();
		$in_transaction = $pdo->inTransaction();

		if ( 'BEGIN' === $statement ) {
			if ( $in_transaction ) {
				$pdo->commit();
				$this->connection->reset_statement_savepoint_state();
				$this->last_postgresql_queries[] = array(
					'sql'    => 'COMMIT',
					'params' => array(),
				);
			}
			$pdo->beginTransaction();
			$this->connection->reset_statement_savepoint_state();
			$this->last_postgresql_queries[] = array(
				'sql'    => 'BEGIN',
				'params' => array(),
			);
			$this->last_result               = 0;
			$this->last_column_meta          = array();
			return $this->last_result;
		}

		if ( ! $in_transaction ) {
			$this->connection->reset_statement_savepoint_state();
			$this->last_result      = 0;
			$this->last_column_meta = array();
			return $this->last_result;
		}

		if ( 'COMMIT' === $statement ) {
			$pdo->commit();
		} else {
			$pdo->rollBack();
		}
		$this->connection->reset_statement_savepoint_state();
		$this->last_postgresql_queries[] = array(
			'sql'    => $statement,
			'params' => array(),
		);
		$this->last_result               = 0;
		$this->last_column_meta          = array();
		return $this->last_result;
	}

	/**
	 * Execute a public MySQL savepoint statement.
	 *
	 * @param string $statement Canonical PostgreSQL savepoint statement.
	 * @return int Number of affected rows.
	 */
	private function execute_mysql_savepoint_query( string $statement ): int {
		$this->connection->query( $statement );
		$this->last_postgresql_queries[] = array(
			'sql'    => $statement,
			'params' => array(),
		);
		$this->last_result               = 0;
		$this->clear_last_column_meta();

		return $this->last_result;
	}

	/**
	 * Execute a supported MySQL runtime SET statement from emulated session state.
	 *
	 * @param string $query MySQL query.
	 * @return int|null Query result for handled SET statements, or null when this is not SET.
	 */
	private function execute_mysql_runtime_setting_query( string $query ): ?int {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::SET_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		if ( $this->apply_mysql_set_names_tokens( $tokens ) || $this->apply_mysql_set_charset_tokens( $tokens ) ) {
			$this->last_result      = 0;
			$this->last_column_meta = array();
			return $this->last_result;
		}

		$operations = $this->get_mysql_set_assignment_operations( $tokens );
		if ( null === $operations ) {
			throw new InvalidArgumentException( 'Unsupported SET statement.' );
		}

		foreach ( $operations as $operation ) {
			if ( 'user' === $operation['target_type'] ) {
				$this->mysql_user_variables[ $operation['name'] ] = $operation['value'];
				continue;
			}

			$this->set_mysql_session_variable_value( $operation['name'], $operation['value'] );
		}

		$this->last_result      = 0;
		$this->last_column_meta = array();
		return $this->last_result;
	}

	/**
	 * Apply a supported MySQL SET NAMES statement to the emulated session.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @return bool Whether the query was handled.
	 */
	private function apply_mysql_set_names_tokens( array $tokens ): bool {
		if (
			! isset( $tokens[0], $tokens[1], $tokens[2] )
			|| WP_MySQL_Lexer::SET_SYMBOL !== $tokens[0]->id
			|| WP_MySQL_Lexer::NAMES_SYMBOL !== $tokens[1]->id
			|| ! $this->is_mysql_charset_token( $tokens[2] )
		) {
			return false;
		}

		$charset   = $this->get_mysql_charset_token_value( $tokens[2] );
		$collation = null;
		$position  = 3;

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COLLATE_SYMBOL === $tokens[ $position ]->id ) {
			if ( ! isset( $tokens[ $position + 1 ] ) || ! $this->is_mysql_charset_token( $tokens[ $position + 1 ] ) ) {
				return false;
			}

			$collation = $this->get_mysql_charset_token_value( $tokens[ $position + 1 ] );
			$position += 2;
		}

		if ( ! $this->is_at_mysql_query_end( $tokens, $position ) ) {
			return false;
		}

		$this->set_charset( $charset, $collation );
		return true;
	}

	/**
	 * Apply supported MySQL SET CHARSET and SET CHARACTER SET statements.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @return bool Whether the query was handled.
	 */
	private function apply_mysql_set_charset_tokens( array $tokens ): bool {
		if (
			isset( $tokens[0], $tokens[1], $tokens[2] )
			&& WP_MySQL_Lexer::SET_SYMBOL === $tokens[0]->id
			&& $this->is_mysql_token_value( $tokens[1], 'charset' )
			&& $this->is_mysql_charset_token( $tokens[2] )
			&& $this->is_at_mysql_query_end( $tokens, 3 )
		) {
			$this->set_charset( $this->get_mysql_charset_token_value( $tokens[2] ) );
			return true;
		}

		if (
			isset( $tokens[0], $tokens[1], $tokens[2], $tokens[3] )
			&& WP_MySQL_Lexer::SET_SYMBOL === $tokens[0]->id
			&& $this->is_mysql_token_value( $tokens[1], 'character' )
			&& WP_MySQL_Lexer::SET_SYMBOL === $tokens[2]->id
			&& $this->is_mysql_charset_token( $tokens[3] )
			&& $this->is_at_mysql_query_end( $tokens, 4 )
		) {
			$this->set_charset( $this->get_mysql_charset_token_value( $tokens[3] ) );
			return true;
		}

		return false;
	}

	/**
	 * Parse supported MySQL SET assignment operations.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @return array<int, array{target_type: string, name: string, value: string|null}>|null Assignment operations, or null when unsupported.
	 */
	private function get_mysql_set_assignment_operations( array $tokens ): ?array {
		$position = 1;
		$this->get_mysql_set_statement_scope( $tokens, $position );
		$ops = array();

		while ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::EOF !== $tokens[ $position ]->id ) {
			$target = $this->parse_mysql_set_assignment_target( $tokens, $position );
			if ( null === $target ) {
				return null;
			}

			if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::EQUAL_OPERATOR !== $tokens[ $position ]->id ) {
				return null;
			}

			++$position;
			$operation = $this->parse_mysql_set_assignment_operation( $tokens, $position, $target );
			if ( null === $operation ) {
				return null;
			}

			$ops[] = $operation;
			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
				continue;
			}

			break;
		}

		if ( array() === $ops || ! $this->is_at_mysql_query_end( $tokens, $position ) ) {
			return null;
		}

		return $ops;
	}

	/**
	 * Get the statement-level SET scope, if present.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current token position, updated on success.
	 * @return string|null SET scope.
	 */
	private function get_mysql_set_statement_scope( array $tokens, int &$position ): ?string {
		if (
			isset( $tokens[ $position ] )
			&& in_array(
				$tokens[ $position ]->id,
				array(
					WP_MySQL_Lexer::GLOBAL_SYMBOL,
					WP_MySQL_Lexer::LOCAL_SYMBOL,
					WP_MySQL_Lexer::SESSION_SYMBOL,
				),
				true
			)
		) {
			return strtolower( $tokens[ $position++ ]->get_value() );
		}

		return null;
	}

	/**
	 * Parse a SET assignment target.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current token position, updated on success.
	 * @return array{type: string, name: string}|null Assignment target.
	 */
	private function parse_mysql_set_assignment_target( array $tokens, int &$position ): ?array {
		if ( ! isset( $tokens[ $position ] ) ) {
			return null;
		}

		if ( WP_MySQL_Lexer::AT_TEXT_SUFFIX === $tokens[ $position ]->id ) {
			return array(
				'type' => 'user',
				'name' => $this->normalize_mysql_user_variable_name( $tokens[ $position++ ]->get_value() ),
			);
		}

		if ( WP_MySQL_Lexer::AT_AT_SIGN_SYMBOL === $tokens[ $position ]->id ) {
			$name = $this->parse_mysql_system_variable_reference( $tokens, $position );
			if ( null === $name || ! $this->is_supported_mysql_system_variable( $name ) ) {
				return null;
			}

			return array(
				'type' => 'system',
				'name' => $name,
			);
		}

		$name = strtolower( $tokens[ $position ]->get_value() );
		if ( ! $this->is_supported_mysql_system_variable( $name ) ) {
			return null;
		}

		++$position;
		return array(
			'type' => 'system',
			'name' => $name,
		);
	}

	/**
	 * Parse a SET assignment operation.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current token position, updated on success.
	 * @param array            $target   Parsed assignment target.
	 * @return array{target_type: string, name: string, value: string|null}|null Assignment operation.
	 */
	private function parse_mysql_set_assignment_operation( array $tokens, int &$position, array $target ): ?array {
		$value = $this->parse_mysql_set_assignment_value( $tokens, $position, $target );
		if ( null === $value ) {
			return null;
		}

		if ( 'system' === $target['type'] ) {
			$value = $this->normalize_mysql_system_variable_assignment_value( $target['name'], $value );
			if ( null === $value ) {
				return null;
			}
		}

		return array(
			'target_type' => $target['type'],
			'name'        => $target['name'],
			'value'       => $value,
		);
	}

	/**
	 * Parse a supported SET assignment value.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current token position, updated on success.
	 * @param array            $target   Parsed assignment target.
	 * @return string|null Assignment value, or null when unsupported.
	 */
	private function parse_mysql_set_assignment_value( array $tokens, int &$position, array $target ): ?string {
		if ( ! isset( $tokens[ $position ] ) ) {
			return null;
		}

		if ( WP_MySQL_Lexer::AT_TEXT_SUFFIX === $tokens[ $position ]->id ) {
			$user_variable_name = $this->normalize_mysql_user_variable_name( $tokens[ $position++ ]->get_value() );

			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::PLUS_OPERATOR === $tokens[ $position ]->id ) {
				return $this->parse_mysql_user_variable_increment_value(
					$tokens,
					$position,
					$target,
					$user_variable_name
				);
			}

			return $this->get_mysql_user_variable_value( $user_variable_name );
		}

		if ( WP_MySQL_Lexer::AT_AT_SIGN_SYMBOL === $tokens[ $position ]->id ) {
			$system_variable_name = $this->parse_mysql_system_variable_reference( $tokens, $position );
			return null === $system_variable_name ? null : $this->get_mysql_system_variable_value( $system_variable_name );
		}

		$value = $this->get_mysql_set_literal_token_value( $tokens[ $position ] );
		if ( null === $value ) {
			return null;
		}

		++$position;
		return $value;
	}

	/**
	 * Parse @name = @name + integer assignment values.
	 *
	 * @param WP_MySQL_Token[] $tokens               MySQL lexer token stream.
	 * @param int              $position             Current token position, updated on success.
	 * @param array            $target               Parsed assignment target.
	 * @param string           $source_variable_name Source user variable name.
	 * @return string|null Incremented value, or null when unsupported.
	 */
	private function parse_mysql_user_variable_increment_value(
		array $tokens,
		int &$position,
		array $target,
		string $source_variable_name
	): ?string {
		if (
			'user' !== $target['type']
			|| $target['name'] !== $source_variable_name
			|| ! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::PLUS_OPERATOR !== $tokens[ $position ]->id
			|| ! $this->is_mysql_unsigned_integer_token( $tokens[ $position + 1 ] )
		) {
			return null;
		}

		$current_value = $this->get_mysql_user_variable_value( $source_variable_name );
		if ( null === $current_value || ! preg_match( '/\A[0-9]+\z/', $current_value ) ) {
			return null;
		}

		$increment = $tokens[ $position + 1 ]->get_value();
		$position += 2;
		return (string) ( (int) $current_value + (int) $increment );
	}

	/**
	 * Get a simple literal token value allowed in supported SET assignments.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return string|null Literal value, or null when unsupported.
	 */
	private function get_mysql_set_literal_token_value( WP_MySQL_Token $token ): ?string {
		if (
			in_array(
				$token->id,
				array(
					WP_MySQL_Lexer::AT_AT_SIGN_SYMBOL,
					WP_MySQL_Lexer::AT_SIGN_SYMBOL,
					WP_MySQL_Lexer::AT_TEXT_SUFFIX,
					WP_MySQL_Lexer::CLOSE_PAR_SYMBOL,
					WP_MySQL_Lexer::COMMA_SYMBOL,
					WP_MySQL_Lexer::DOT_SYMBOL,
					WP_MySQL_Lexer::EOF,
					WP_MySQL_Lexer::EQUAL_OPERATOR,
					WP_MySQL_Lexer::MINUS_OPERATOR,
					WP_MySQL_Lexer::OPEN_PAR_SYMBOL,
					WP_MySQL_Lexer::PLUS_OPERATOR,
					WP_MySQL_Lexer::SEMICOLON_SYMBOL,
				),
				true
			)
		) {
			return null;
		}

		return $token->get_value();
	}

	/**
	 * Get the canonical PostgreSQL transaction statement for a simple MySQL query.
	 *
	 * @param string $query MySQL query.
	 * @return string|null Canonical PostgreSQL statement, or null when unsupported.
	 */
	private function get_mysql_transaction_control_query( string $query ): ?string {
		$statement = trim( $query );
		$statement = preg_replace( '/;\s*\z/', '', $statement );
		if ( null === $statement ) {
			return null;
		}

		$normalized_statement = preg_replace( '/\s+/', ' ', $statement );
		if ( null === $normalized_statement ) {
			return null;
		}

		$statement = trim( $normalized_statement );
		if ( '' === $statement ) {
			return null;
		}

		if ( 1 === preg_match( '/\A(?:START TRANSACTION|BEGIN(?: WORK)?)\z/i', $statement ) ) {
			return 'BEGIN';
		}

		if ( 1 === preg_match( '/\ACOMMIT(?: WORK)?\z/i', $statement ) ) {
			return 'COMMIT';
		}

		if ( 1 === preg_match( '/\AROLLBACK(?: WORK)?\z/i', $statement ) ) {
			return 'ROLLBACK';
		}

		return null;
	}

	/**
	 * Get the canonical PostgreSQL statement for a public MySQL savepoint query.
	 *
	 * @param string $query MySQL query.
	 * @return string|null Canonical PostgreSQL savepoint statement, or null when this is not SAVEPOINT SQL.
	 */
	private function get_mysql_savepoint_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) ) {
			return null;
		}

		if ( WP_MySQL_Lexer::SAVEPOINT_SYMBOL === $tokens[0]->id ) {
			$position = 1;
			$name     = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
			if ( null === $name || ! $this->is_at_mysql_query_end( $tokens, $position + 1 ) ) {
				throw new InvalidArgumentException( 'Unsupported SAVEPOINT statement.' );
			}

			return 'SAVEPOINT ' . $this->connection->quote_identifier( $name );
		}

		if ( WP_MySQL_Lexer::ROLLBACK_SYMBOL === $tokens[0]->id ) {
			$position = 1;
			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::WORK_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
			}

			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::SAVEPOINT_SYMBOL === $tokens[ $position ]->id ) {
				throw new InvalidArgumentException( 'Unsupported SAVEPOINT statement.' );
			}

			if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::TO_SYMBOL !== $tokens[ $position ]->id ) {
				return null;
			}

			++$position;
			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::SAVEPOINT_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
			}

			$name = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
			if ( null === $name || ! $this->is_at_mysql_query_end( $tokens, $position + 1 ) ) {
				throw new InvalidArgumentException( 'Unsupported SAVEPOINT statement.' );
			}

			return 'ROLLBACK TO SAVEPOINT ' . $this->connection->quote_identifier( $name );
		}

		if ( WP_MySQL_Lexer::RELEASE_SYMBOL === $tokens[0]->id ) {
			$position = 1;
			if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::SAVEPOINT_SYMBOL !== $tokens[ $position ]->id ) {
				throw new InvalidArgumentException( 'Unsupported SAVEPOINT statement.' );
			}

			++$position;
			$name = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
			if ( null === $name || ! $this->is_at_mysql_query_end( $tokens, $position + 1 ) ) {
				throw new InvalidArgumentException( 'Unsupported SAVEPOINT statement.' );
			}

			return 'RELEASE SAVEPOINT ' . $this->connection->quote_identifier( $name );
		}

		return null;
	}

	/**
	 * Execute a supported MySQL TRUNCATE TABLE statement.
	 *
	 * @param array{schema: string|null, table: string} $truncate_table_query Parsed truncate query.
	 * @return int Number of affected rows.
	 */
	private function execute_mysql_truncate_table_query( array $truncate_table_query ): int {
		$requested_schema = $truncate_table_query['schema'];
		$table_name       = $truncate_table_query['table'];

		if (
			( null === $requested_schema && 0 === strcasecmp( $this->db_name, 'information_schema' ) )
			|| ( null !== $requested_schema && 0 !== strcasecmp( $requested_schema, $this->main_db_name ) )
		) {
			throw new InvalidArgumentException( 'Unsupported TRUNCATE TABLE statement.' );
		}

		$statement = 'TRUNCATE TABLE ' . $this->connection->quote_identifier( $table_name ) . ' RESTART IDENTITY';
		if ( 'sqlite' === (string) $this->connection->get_pdo()->getAttribute( PDO::ATTR_DRIVER_NAME ) ) {
			$statement = 'DELETE FROM ' . $this->connection->quote_identifier( $table_name );
		}

		$this->connection->query( $statement );
		$this->last_postgresql_queries[] = array(
			'sql'    => $statement,
			'params' => array(),
		);

		if ( 'sqlite' === (string) $this->connection->get_pdo()->getAttribute( PDO::ATTR_DRIVER_NAME ) ) {
			$this->reset_sqlite_autoincrement_sequence( $table_name );
		}

		$this->mysql_introspection_result_cache = array();
		$this->last_result                      = 0;
		$this->clear_last_column_meta();

		return $this->last_result;
	}

	/**
	 * Reset a SQLite AUTOINCREMENT sequence after TRUNCATE emulation.
	 *
	 * @param string $table_name Table name.
	 */
	private function reset_sqlite_autoincrement_sequence( string $table_name ): void {
		try {
			$this->connection->query(
				'DELETE FROM sqlite_sequence WHERE name = ?',
				array( $table_name )
			);
		} catch ( PDOException $e ) {
			if ( false === strpos( $e->getMessage(), 'no such table' ) ) {
				throw $e;
			}
		}
	}

	/**
	 * Create the MySQL schema metadata tables used by dbDelta emulation.
	 */
	private function ensure_mysql_schema_metadata_tables(): void {
		if ( $this->mysql_schema_metadata_tables_ensured ) {
			return;
		}

		$this->connection->query(
			sprintf(
				'CREATE TABLE IF NOT EXISTS %s (
					table_schema TEXT NOT NULL,
					table_name TEXT NOT NULL,
					table_comment TEXT NOT NULL DEFAULT \'\',
					PRIMARY KEY (table_schema, table_name)
				)',
				$this->connection->quote_identifier( self::MYSQL_TABLE_METADATA_TABLE )
			)
		);

		$this->connection->query(
			sprintf(
				'CREATE TABLE IF NOT EXISTS %s (
					table_schema TEXT NOT NULL,
					table_name TEXT NOT NULL,
					column_name TEXT NOT NULL,
					ordinal_position INTEGER NOT NULL,
					column_type TEXT NOT NULL,
					character_set_name TEXT,
					collation_name TEXT,
					is_nullable TEXT NOT NULL,
					column_default TEXT,
					extra TEXT NOT NULL,
					column_comment TEXT NOT NULL DEFAULT \'\',
					PRIMARY KEY (table_schema, table_name, column_name)
				)',
				$this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE )
			)
		);

		$this->ensure_mysql_column_metadata_column( 'character_set_name', 'TEXT' );
		$this->ensure_mysql_column_metadata_column( 'collation_name', 'TEXT' );
		$this->ensure_mysql_column_metadata_column( 'column_comment', 'TEXT NOT NULL DEFAULT \'\'' );

		$this->connection->query(
			sprintf(
				'CREATE TABLE IF NOT EXISTS %s (
					table_schema TEXT NOT NULL,
					table_name TEXT NOT NULL,
					key_name TEXT NOT NULL,
					index_ordinal INTEGER NOT NULL,
					seq_in_index INTEGER NOT NULL,
					column_name TEXT NOT NULL,
						non_unique TEXT NOT NULL,
						index_type TEXT NOT NULL,
						"collation" TEXT,
						sub_part TEXT,
					nullable TEXT NOT NULL,
					index_comment TEXT NOT NULL DEFAULT \'\',
					PRIMARY KEY (table_schema, table_name, key_name, seq_in_index)
				)',
				$this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE )
			)
		);
		$this->ensure_mysql_index_metadata_column( 'index_comment', 'TEXT NOT NULL DEFAULT \'\'' );
		$this->ensure_mysql_index_metadata_column( 'collation', 'TEXT' );

		$this->connection->query(
			sprintf(
				'CREATE TABLE IF NOT EXISTS %s (
					table_schema TEXT NOT NULL,
					table_name TEXT NOT NULL,
					constraint_name TEXT NOT NULL,
					constraint_ordinal INTEGER NOT NULL,
					seq_in_index INTEGER NOT NULL,
					column_name TEXT NOT NULL,
					referenced_table_schema TEXT NOT NULL,
					referenced_table_name TEXT NOT NULL,
					referenced_column_name TEXT NOT NULL,
					update_rule TEXT NOT NULL,
					delete_rule TEXT NOT NULL,
					PRIMARY KEY (table_schema, table_name, constraint_name, seq_in_index)
				)',
				$this->connection->quote_identifier( self::MYSQL_FOREIGN_KEY_METADATA_TABLE )
			)
		);

		$this->connection->query(
			sprintf(
				'CREATE TABLE IF NOT EXISTS %s (
					table_schema TEXT NOT NULL,
					table_name TEXT NOT NULL,
					constraint_name TEXT NOT NULL,
					constraint_ordinal INTEGER NOT NULL,
					check_clause TEXT NOT NULL,
					enforced TEXT NOT NULL,
					PRIMARY KEY (table_schema, table_name, constraint_name)
				)',
				$this->connection->quote_identifier( self::MYSQL_CHECK_METADATA_TABLE )
			)
		);

		$this->mysql_schema_metadata_tables_ensured = true;
	}

	/**
	 * Clear all cached MySQL metadata derived from side tables.
	 */
	private function clear_mysql_metadata_caches(): void {
		$this->mysql_table_schema_introspection_cache   = array();
		$this->mysql_dml_column_metadata_cache          = array();
		$this->mysql_dml_identity_column_metadata_cache = array();
		$this->mysql_table_column_type_cache            = array();
		$this->mysql_table_column_collation_cache       = array();
		$this->mysql_table_has_column_metadata_cache    = array();
		$this->mysql_table_column_name_cache            = array();
		$this->mysql_upsert_conflict_target_cache       = array();
		$this->mysql_introspection_result_cache         = array();
		$this->clear_mysql_query_translation_caches();
	}

	/**
	 * Clear cached MySQL metadata for one table.
	 *
	 * @param string $table_schema Metadata schema.
	 * @param string $table_name   Table name.
	 */
	private function clear_mysql_metadata_cache_for_table( string $table_schema, string $table_name ): void {
		$cache_key = $this->get_mysql_metadata_cache_key( $table_schema, $table_name );
		unset(
			$this->mysql_dml_column_metadata_cache[ $cache_key ],
			$this->mysql_dml_identity_column_metadata_cache[ $cache_key ],
			$this->mysql_table_column_type_cache[ $cache_key ],
			$this->mysql_table_column_collation_cache[ $cache_key ],
			$this->mysql_table_has_column_metadata_cache[ $cache_key ],
			$this->mysql_table_column_name_cache[ $cache_key ]
		);
		$this->mysql_upsert_conflict_target_cache = array();
		$this->mysql_introspection_result_cache   = array();
		$this->clear_mysql_query_translation_caches();

		/*
		 * Temporary table creation/drop can change which backend schema an
		 * unqualified MySQL table resolves to, so clear all schema resolutions.
		 */
		$this->mysql_table_schema_introspection_cache = array();
	}

	/**
	 * Get a cache key for metadata keyed by backend schema and table name.
	 *
	 * @param string $table_schema Metadata schema.
	 * @param string $table_name   Table name.
	 * @return string Cache key.
	 */
	private function get_mysql_metadata_cache_key( string $table_schema, string $table_name ): string {
		return $table_schema . "\0" . $table_name;
	}

	/**
	 * Clear exact query translation caches derived from metadata-sensitive rewrites.
	 */
	private function clear_mysql_query_translation_caches(): void {
		$this->mysql_select_translation_cache              = array();
		$this->mysql_sql_calc_found_rows_count_query_cache = array();
	}

	/**
	 * Clear the mode-sensitive MySQL token cache.
	 */
	private function clear_mysql_token_cache(): void {
		$this->mysql_token_cache_query    = null;
		$this->mysql_token_cache_sql_mode = null;
		$this->mysql_token_cache_tokens   = array();
	}

	/**
	 * Reset metadata side-table state if a query drops the side tables directly.
	 *
	 * @param string[] $table_names Dropped table names.
	 */
	private function maybe_clear_mysql_schema_metadata_table_state( array $table_names ): void {
		foreach ( $table_names as $table_name ) {
			if ( ! $this->is_mysql_schema_metadata_table_name( (string) $table_name ) ) {
				continue;
			}

			$this->mysql_schema_metadata_tables_ensured = false;
			$this->clear_mysql_metadata_caches();
			return;
		}
	}

	/**
	 * Check whether a table name belongs to the driver's metadata side tables.
	 *
	 * @param string $table_name Table name.
	 * @return bool Whether this is a metadata side table.
	 */
	private function is_mysql_schema_metadata_table_name( string $table_name ): bool {
		return in_array(
			$table_name,
			array(
				self::MYSQL_COLUMN_METADATA_TABLE,
				self::MYSQL_INDEX_METADATA_TABLE,
				self::MYSQL_FOREIGN_KEY_METADATA_TABLE,
				self::MYSQL_CHECK_METADATA_TABLE,
				self::MYSQL_TABLE_METADATA_TABLE,
			),
			true
		);
	}

	/**
	 * Add a MySQL column metadata field when upgrading an existing side table.
	 *
	 * @param string $column_name Column name.
	 * @param string $column_type Column type SQL.
	 */
	private function ensure_mysql_column_metadata_column( string $column_name, string $column_type ): void {
		$this->ensure_mysql_metadata_column( self::MYSQL_COLUMN_METADATA_TABLE, $column_name, $column_type );
	}

	/**
	 * Add a MySQL index metadata field when upgrading an existing side table.
	 *
	 * @param string $column_name Column name.
	 * @param string $column_type Column type SQL.
	 */
	private function ensure_mysql_index_metadata_column( string $column_name, string $column_type ): void {
		$this->ensure_mysql_metadata_column( self::MYSQL_INDEX_METADATA_TABLE, $column_name, $column_type );
	}

	/**
	 * Add a metadata field when upgrading an existing side table.
	 *
	 * @param string $metadata_table Metadata side-table name.
	 * @param string $column_name    Column name.
	 * @param string $column_type    Column type SQL.
	 */
	private function ensure_mysql_metadata_column( string $metadata_table, string $column_name, string $column_type ): void {
		if ( $this->mysql_metadata_column_exists( $metadata_table, $column_name ) ) {
			return;
		}

		$this->connection->query(
			sprintf(
				'ALTER TABLE %s ADD COLUMN %s %s',
				$this->connection->quote_identifier( $metadata_table ),
				$this->connection->quote_identifier( $column_name ),
				$column_type
			)
		);
	}

	/**
	 * Check whether a metadata side-table field exists.
	 *
	 * @param string $metadata_table Metadata side-table name.
	 * @param string $column_name    Column name.
	 * @return bool Whether the column exists.
	 */
	private function mysql_metadata_column_exists( string $metadata_table, string $column_name ): bool {
		$driver_name = (string) $this->connection->get_pdo()->getAttribute( PDO::ATTR_DRIVER_NAME );
		if ( 'sqlite' === $driver_name ) {
			$stmt = $this->connection->query(
				sprintf(
					'PRAGMA table_info(%s)',
					$this->connection->quote_identifier( $metadata_table )
				)
			);

			foreach ( $stmt->fetchAll( PDO::FETCH_ASSOC ) as $column ) {
				if ( isset( $column['name'] ) && $column_name === $column['name'] ) {
					return true;
				}
			}

			return false;
		}

		$stmt = $this->connection->query(
			'SELECT EXISTS (
				SELECT 1
				FROM information_schema.columns
				WHERE table_schema = current_schema()
					AND table_name = ?
					AND column_name = ?
			)',
			array( $metadata_table, $column_name )
		);

		return (bool) $stmt->fetchColumn();
	}

	/**
	 * Store MySQL-facing schema metadata for translated CREATE TABLE statements.
	 *
	 * @param string $query MySQL CREATE TABLE query.
	 */
	public function store_mysql_schema_metadata( string $query ): void {
		if ( $this->is_temporary_create_table_query( $query ) ) {
			return;
		}

		$this->store_mysql_schema_metadata_for_schema( $query, 'public' );
	}

	/**
	 * Store MySQL-facing schema metadata for translated CREATE TEMPORARY TABLE statements.
	 *
	 * @param string $query MySQL CREATE TEMPORARY TABLE query.
	 */
	private function store_mysql_temporary_schema_metadata( string $query ): void {
		$this->store_mysql_schema_metadata_for_schema(
			$query,
			array( $this, 'get_temporary_schema_for_metadata_table' )
		);
	}

	/**
	 * Store MySQL-facing schema metadata for translated CREATE TABLE statements in one backend schema.
	 *
	 * @param string          $query        MySQL CREATE TABLE query.
	 * @param string|callable $table_schema Metadata schema, or resolver receiving the table name.
	 */
	private function store_mysql_schema_metadata_for_schema( string $query, $table_schema ): void {
		$this->ensure_mysql_schema_metadata_tables();

		$metadata_tables = ( new WP_PostgreSQL_Create_Table_Translator( $this->active_sql_modes ) )->extract_schema_metadata( $query, true );
		foreach ( $metadata_tables as $metadata ) {
			$schema_name = is_callable( $table_schema )
				? (string) call_user_func( $table_schema, $metadata['table_name'] )
				: (string) $table_schema;
			$table_name  = $metadata['table_name'];

			$this->delete_mysql_schema_metadata_for_tables( array( $table_name ), $schema_name );
			$this->clear_mysql_metadata_cache_for_table( $schema_name, $table_name );
			$this->insert_mysql_table_metadata( $schema_name, $table_name, $metadata );

			$column_nullable = array();
			foreach ( $metadata['columns'] as $column ) {
				$this->insert_mysql_column_metadata( $schema_name, $table_name, $column );
				$column_nullable[ strtolower( $column['name'] ) ] = $column['nullable'] ?? 'YES';
			}

			foreach ( $metadata['indexes'] ?? array() as $index ) {
				$this->insert_mysql_index_metadata( $schema_name, $table_name, $index, $column_nullable );
			}

			foreach ( $metadata['foreign_keys'] ?? array() as $foreign_key ) {
				$foreign_key['referenced_schema'] = $foreign_key['referenced_schema'] ?? $schema_name;
				$this->insert_mysql_foreign_key_metadata( $schema_name, $table_name, $foreign_key );
			}

			foreach ( $metadata['checks'] ?? array() as $check ) {
				$this->insert_mysql_check_metadata( $schema_name, $table_name, $check );
			}
		}
	}

	/**
	 * Create PostgreSQL trigger side effects for CREATE TABLE ON UPDATE columns.
	 *
	 * @param string $query MySQL CREATE TABLE query.
	 */
	private function sync_mysql_on_update_current_timestamp_triggers_for_create_query( string $query ): void {
		if ( 'pgsql' !== $this->connection->get_driver_name() ) {
			return;
		}

		$metadata_tables = ( new WP_PostgreSQL_Create_Table_Translator( $this->active_sql_modes ) )->extract_schema_metadata( $query, true );
		foreach ( $metadata_tables as $metadata ) {
			$table_name = (string) $metadata['table_name'];
			foreach ( $metadata['columns'] as $column ) {
				if ( $this->mysql_column_extra_has_on_update_current_timestamp( $column['extra'] ?? '' ) ) {
					$this->execute_postgresql_side_effect_statements(
						$this->get_postgresql_on_update_current_timestamp_create_statements( 'public', $table_name, (string) $column['name'] )
					);
				}
			}
		}
	}

	/**
	 * Check whether MySQL column extra metadata contains ON UPDATE CURRENT_TIMESTAMP.
	 *
	 * @param string|null $extra Extra metadata.
	 * @return bool Whether the column needs an ON UPDATE trigger.
	 */
	private function mysql_column_extra_has_on_update_current_timestamp( ?string $extra ): bool {
		return null !== $extra && false !== stripos( $extra, 'on update CURRENT_TIMESTAMP' );
	}

	/**
	 * Check whether MySQL column extra metadata contains DEFAULT_GENERATED.
	 *
	 * @param string|null $extra Extra metadata.
	 * @return bool Whether the default is generated.
	 */
	private function mysql_column_extra_has_default_generated( ?string $extra ): bool {
		return null !== $extra && false !== stripos( $extra, 'DEFAULT_GENERATED' );
	}

	/**
	 * Get CREATE/replace trigger statements for a MySQL ON UPDATE CURRENT_TIMESTAMP column.
	 *
	 * @param string $table_schema Backend schema.
	 * @param string $table_name   Table name.
	 * @param string $column_name  Column name.
	 * @return string[] PostgreSQL statements.
	 */
	private function get_postgresql_on_update_current_timestamp_create_statements( string $table_schema, string $table_name, string $column_name ): array {
		if ( 'pgsql' !== $this->connection->get_driver_name() ) {
			return array();
		}

		$trigger_name  = $this->get_postgresql_on_update_current_timestamp_trigger_name( $table_schema, $table_name, $column_name );
		$function_name = $this->get_postgresql_on_update_current_timestamp_function_name( $table_schema, $table_name, $column_name );
		$table_sql    = $this->get_postgresql_schema_identifier( $table_schema, $table_name );
		$function_sql = $this->get_postgresql_schema_identifier( $table_schema, $function_name );
		$column_sql   = $this->connection->quote_identifier( $column_name );
		$column_value = $this->connection->quote( $column_name );

		return array(
			sprintf(
				'CREATE OR REPLACE FUNCTION %s()
RETURNS trigger
LANGUAGE plpgsql
AS $wp_mysql_on_update$
BEGIN
  IF NEW.%s IS NOT DISTINCT FROM OLD.%s
     AND to_jsonb(NEW) - %s IS DISTINCT FROM to_jsonb(OLD) - %s THEN
    NEW.%s = TO_CHAR(CURRENT_TIMESTAMP AT TIME ZONE \'UTC\', \'YYYY-MM-DD HH24:MI:SS\');
  END IF;
  RETURN NEW;
END;
$wp_mysql_on_update$',
				$function_sql,
				$column_sql,
				$column_sql,
				$column_value,
				$column_value,
				$column_sql
			),
			sprintf(
				'DROP TRIGGER IF EXISTS %s ON %s',
				$this->connection->quote_identifier( $trigger_name ),
				$table_sql
			),
			sprintf(
				'CREATE TRIGGER %s BEFORE UPDATE ON %s FOR EACH ROW EXECUTE FUNCTION %s()',
				$this->connection->quote_identifier( $trigger_name ),
				$table_sql,
				$function_sql
			),
		);
	}

	/**
	 * Get drop trigger/function statements for a MySQL ON UPDATE CURRENT_TIMESTAMP column.
	 *
	 * @param string $table_schema Backend schema.
	 * @param string $table_name   Table name.
	 * @param string $column_name  Column name.
	 * @return string[] PostgreSQL statements.
	 */
	private function get_postgresql_on_update_current_timestamp_drop_statements( string $table_schema, string $table_name, string $column_name ): array {
		if ( 'pgsql' !== $this->connection->get_driver_name() ) {
			return array();
		}

		$trigger_name  = $this->get_postgresql_on_update_current_timestamp_trigger_name( $table_schema, $table_name, $column_name );
		$function_name = $this->get_postgresql_on_update_current_timestamp_function_name( $table_schema, $table_name, $column_name );

		return array(
			sprintf(
				'DROP TRIGGER IF EXISTS %s ON %s',
				$this->connection->quote_identifier( $trigger_name ),
				$this->get_postgresql_schema_identifier( $table_schema, $table_name )
			),
			sprintf(
				'DROP FUNCTION IF EXISTS %s()',
				$this->get_postgresql_schema_identifier( $table_schema, $function_name )
			),
		);
	}

	/**
	 * Get a stable PostgreSQL trigger name for an ON UPDATE column.
	 *
	 * @param string $table_schema Backend schema.
	 * @param string $table_name   Table name.
	 * @param string $column_name  Column name.
	 * @return string Trigger name.
	 */
	private function get_postgresql_on_update_current_timestamp_trigger_name( string $table_schema, string $table_name, string $column_name ): string {
		return '__wp_pg_on_update_' . substr( sha1( $table_schema . "\0" . $table_name . "\0" . $column_name ), 0, 32 );
	}

	/**
	 * Get a stable PostgreSQL function name for an ON UPDATE column.
	 *
	 * @param string $table_schema Backend schema.
	 * @param string $table_name   Table name.
	 * @param string $column_name  Column name.
	 * @return string Function name.
	 */
	private function get_postgresql_on_update_current_timestamp_function_name( string $table_schema, string $table_name, string $column_name ): string {
		return '__wp_pg_on_update_fn_' . substr( sha1( $table_schema . "\0" . $table_name . "\0" . $column_name ), 0, 29 );
	}

	/**
	 * Get the metadata schema name for an active temporary table.
	 *
	 * @param string $table_name Table name.
	 * @return string Metadata schema name.
	 */
	private function get_temporary_schema_for_metadata_table( string $table_name ): string {
		$schema_name = $this->get_active_temporary_table_schema( $table_name );
		if ( null !== $schema_name ) {
			return $schema_name;
		}

		return $this->get_temporary_drop_table_schema_name();
	}

	/**
	 * Delete stored MySQL schema metadata for dropped tables.
	 *
	 * @param string[] $table_names Table names.
	 * @param string   $table_schema Metadata schema name.
	 */
	private function delete_mysql_schema_metadata_for_tables( array $table_names, string $table_schema = 'public' ): void {
		if ( empty( $table_names ) ) {
			return;
		}

		$this->ensure_mysql_schema_metadata_tables();

		foreach ( $table_names as $table_name ) {
			$params = array( $table_schema, $table_name );
			$this->connection->query(
				sprintf(
					'DELETE FROM %s WHERE table_schema = ? AND table_name = ?',
					$this->connection->quote_identifier( self::MYSQL_TABLE_METADATA_TABLE )
				),
				$params
			);
			$this->connection->query(
				sprintf(
					'DELETE FROM %s WHERE table_schema = ? AND table_name = ?',
					$this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE )
				),
				$params
			);
			$this->connection->query(
				sprintf(
					'DELETE FROM %s WHERE table_schema = ? AND table_name = ?',
					$this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE )
				),
				$params
			);
			$this->connection->query(
				sprintf(
					'DELETE FROM %s WHERE table_schema = ? AND table_name = ?',
					$this->connection->quote_identifier( self::MYSQL_FOREIGN_KEY_METADATA_TABLE )
				),
				$params
			);
			$this->connection->query(
				sprintf(
					'DELETE FROM %s WHERE table_schema = ? AND table_name = ?',
					$this->connection->quote_identifier( self::MYSQL_CHECK_METADATA_TABLE )
				),
				$params
			);
			$this->clear_mysql_metadata_cache_for_table( $table_schema, $table_name );
		}
	}

	/**
	 * Delete stored MySQL schema metadata for concrete schema/table targets.
	 *
	 * @param array[] $targets Metadata targets.
	 */
	private function delete_mysql_schema_metadata_for_table_targets( array $targets ): void {
		foreach ( $targets as $target ) {
			$this->delete_mysql_schema_metadata_for_tables(
				array( $target['table'] ),
				$target['schema']
			);
		}
	}

	/**
	 * Apply metadata changes for a translated dbDelta ALTER TABLE statement.
	 *
	 * @param array $metadata ALTER metadata.
	 */
	private function apply_mysql_dbdelta_alter_metadata( array $metadata ): void {
		$this->ensure_mysql_schema_metadata_tables();

		$table_schema = $metadata['schema'] ?? 'public';
		$table_name   = $metadata['table'];

		if ( 'operations' === $metadata['operation'] ) {
			foreach ( $metadata['operations'] as $operation_metadata ) {
				$operation_metadata['schema'] = $table_schema;
				$operation_metadata['table'] = $table_name;
				$this->apply_mysql_dbdelta_alter_metadata( $operation_metadata );
			}
			return;
		}

		if ( 'noop' === $metadata['operation'] ) {
			return;
		}

		if ( 'set_auto_increment' === $metadata['operation'] ) {
			return;
		}

		if ( 'rename_table' === $metadata['operation'] ) {
			$this->apply_mysql_rename_table_metadata(
				array(
					'schema'    => $table_schema,
					'old_table' => $table_name,
					'new_table' => $metadata['new_table'],
				)
			);
			return;
		}

		if ( 'add_column' === $metadata['operation'] ) {
			$column            = $metadata['column'];
			$column['ordinal'] = $this->get_next_mysql_column_ordinal( $table_schema, $table_name );
			$column_nullable   = array( strtolower( $column['name'] ) => $column['nullable'] ?? 'YES' );
			$this->insert_mysql_column_metadata( $table_schema, $table_name, $column );
			if ( $this->mysql_column_extra_has_on_update_current_timestamp( $column['extra'] ?? '' ) ) {
				$this->execute_postgresql_side_effect_statements(
					$this->get_postgresql_on_update_current_timestamp_create_statements( $table_schema, $table_name, $column['name'] )
				);
			}
			$index_ordinal = $this->get_next_mysql_index_ordinal( $table_schema, $table_name );
			foreach ( $metadata['indexes'] ?? array() as $index ) {
				$index['ordinal'] = $index_ordinal;
				$this->insert_mysql_index_metadata( $table_schema, $table_name, $index, $column_nullable );
				++$index_ordinal;
			}
			foreach ( $metadata['foreign_keys'] ?? array() as $foreign_key ) {
				$foreign_key['referenced_schema'] = $foreign_key['referenced_schema'] ?? $table_schema;
				$this->insert_mysql_foreign_key_metadata( $table_schema, $table_name, $foreign_key );
			}
			foreach ( $metadata['checks'] ?? array() as $check ) {
				$this->insert_mysql_check_metadata( $table_schema, $table_name, $check );
			}
			return;
		}

		if ( 'change_column' === $metadata['operation'] ) {
			$old_extra         = $this->get_mysql_column_extra_metadata( $table_schema, $table_name, $metadata['old_column'] );
			$column            = $metadata['column'];
			$column['ordinal'] = $this->get_existing_mysql_column_ordinal(
				$table_schema,
				$table_name,
				$metadata['old_column']
			) ?? $this->get_next_mysql_column_ordinal( $table_schema, $table_name );

			$this->delete_mysql_column_metadata( $table_schema, $table_name, $metadata['old_column'] );
			$this->insert_mysql_column_metadata( $table_schema, $table_name, $column );
			$column_nullable = array( strtolower( $column['name'] ) => $column['nullable'] ?? 'YES' );
			if ( $this->mysql_column_extra_has_on_update_current_timestamp( $old_extra ) ) {
				$this->execute_postgresql_side_effect_statements(
					$this->get_postgresql_on_update_current_timestamp_drop_statements( $table_schema, $table_name, $metadata['old_column'] )
				);
			}
			if ( $this->mysql_column_extra_has_on_update_current_timestamp( $column['extra'] ?? '' ) ) {
				$this->execute_postgresql_side_effect_statements(
					$this->get_postgresql_on_update_current_timestamp_create_statements( $table_schema, $table_name, $column['name'] )
				);
			}
			$this->rename_mysql_index_column_metadata(
				$table_schema,
				$table_name,
				$metadata['old_column'],
				$column['name']
			);
			$this->rename_mysql_foreign_key_column_metadata(
				$table_schema,
				$table_name,
				$metadata['old_column'],
				$column['name']
			);
			$this->rename_mysql_referenced_foreign_key_column_metadata(
				$table_schema,
				$table_name,
				$metadata['old_column'],
				$column['name']
			);
			$index_ordinal = $this->get_next_mysql_index_ordinal( $table_schema, $table_name );
			foreach ( $metadata['indexes'] ?? array() as $index ) {
				$index['ordinal'] = $index_ordinal;
				$this->delete_mysql_index_metadata( $table_schema, $table_name, $index['name'] );
				$this->insert_mysql_index_metadata( $table_schema, $table_name, $index, $column_nullable );
				++$index_ordinal;
			}
			return;
		}

		if ( 'change_columns' === $metadata['operation'] ) {
			foreach ( $metadata['columns'] as $column_metadata ) {
				$column_metadata['operation'] = 'change_column';
				$column_metadata['table']     = $table_name;
				$this->apply_mysql_dbdelta_alter_metadata( $column_metadata );
			}
			return;
		}

		if ( 'rename_column' === $metadata['operation'] ) {
			$old_extra = $this->get_mysql_column_extra_metadata( $table_schema, $table_name, $metadata['old_column'] );
			$this->rename_mysql_column_metadata(
				$table_schema,
				$table_name,
				$metadata['old_column'],
				$metadata['new_column']
			);
			$this->rename_mysql_index_column_metadata(
				$table_schema,
				$table_name,
				$metadata['old_column'],
				$metadata['new_column']
			);
			$this->rename_mysql_foreign_key_column_metadata(
				$table_schema,
				$table_name,
				$metadata['old_column'],
				$metadata['new_column']
			);
			$this->rename_mysql_referenced_foreign_key_column_metadata(
				$table_schema,
				$table_name,
				$metadata['old_column'],
				$metadata['new_column']
			);
			if ( $this->mysql_column_extra_has_on_update_current_timestamp( $old_extra ) ) {
				$this->execute_postgresql_side_effect_statements(
					array_merge(
						$this->get_postgresql_on_update_current_timestamp_drop_statements( $table_schema, $table_name, $metadata['old_column'] ),
						$this->get_postgresql_on_update_current_timestamp_create_statements( $table_schema, $table_name, $metadata['new_column'] )
					)
				);
			}
			return;
		}

		if ( 'drop_column' === $metadata['operation'] ) {
			$old_extra = $this->get_mysql_column_extra_metadata( $table_schema, $table_name, $metadata['column'] );
			if ( $this->mysql_column_extra_has_on_update_current_timestamp( $old_extra ) ) {
				$this->execute_postgresql_side_effect_statements(
					$this->get_postgresql_on_update_current_timestamp_drop_statements( $table_schema, $table_name, $metadata['column'] )
				);
			}
			$this->delete_mysql_index_metadata_for_column( $table_schema, $table_name, $metadata['column'] );
			$this->delete_mysql_foreign_key_metadata_for_column( $table_schema, $table_name, $metadata['column'] );
			$this->delete_mysql_column_metadata( $table_schema, $table_name, $metadata['column'] );
			return;
		}

		if ( 'add_index' === $metadata['operation'] ) {
			$this->delete_mysql_index_metadata( $table_schema, $table_name, $metadata['index']['name'] );
			$this->insert_mysql_index_metadata( $table_schema, $table_name, $metadata['index'] );
			return;
		}

		if ( 'drop_index' === $metadata['operation'] ) {
			$this->apply_mysql_drop_index_metadata( $metadata );
			return;
		}

		if ( 'rename_index' === $metadata['operation'] ) {
			$this->rename_mysql_index_metadata(
				$table_schema,
				$table_name,
				$metadata['old_index'],
				$metadata['new_index']
			);
			return;
		}

		if ( 'add_foreign_key' === $metadata['operation'] ) {
			$this->insert_mysql_foreign_key_metadata( $table_schema, $table_name, $metadata['foreign_key'] );
			return;
		}

		if ( 'add_check' === $metadata['operation'] ) {
			$this->insert_mysql_check_metadata( $table_schema, $table_name, $metadata['check'] );
			return;
		}

		if ( 'drop_foreign_key' === $metadata['operation'] ) {
			$this->delete_mysql_foreign_key_metadata( $table_schema, $table_name, $metadata['constraint'] );
			return;
		}

		if ( 'drop_check' === $metadata['operation'] ) {
			$this->delete_mysql_check_metadata( $table_schema, $table_name, $metadata['constraint'] );
			return;
		}

		if ( 'set_default' === $metadata['operation'] ) {
			$this->connection->query(
				sprintf(
					'UPDATE %s SET column_default = ? WHERE table_schema = ? AND table_name = ? AND column_name = ?',
					$this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE )
				),
				array( $metadata['default'], $table_schema, $table_name, $metadata['column'] )
			);
			$this->clear_mysql_metadata_cache_for_table( $table_schema, $table_name );
			return;
		}

		if ( 'drop_default' === $metadata['operation'] ) {
			$this->connection->query(
				sprintf(
					'UPDATE %s SET column_default = NULL WHERE table_schema = ? AND table_name = ? AND column_name = ?',
					$this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE )
				),
				array( $table_schema, $table_name, $metadata['column'] )
			);
			$this->clear_mysql_metadata_cache_for_table( $table_schema, $table_name );
		}
	}

	/**
	 * Apply MySQL-facing metadata changes after a table rename.
	 *
	 * @param array{schema: string, old_table: string, new_table: string} $metadata Rename metadata.
	 */
	private function apply_mysql_rename_table_metadata( array $metadata ): void {
		$this->ensure_mysql_schema_metadata_tables();

		$table_schema   = $metadata['schema'];
		$old_table_name = $metadata['old_table'];
		$new_table_name = $metadata['new_table'];
		if ( $old_table_name === $new_table_name ) {
			return;
		}

		$stmt               = $this->connection->query(
			sprintf(
				'SELECT DISTINCT table_schema, table_name FROM %s WHERE referenced_table_schema = ? AND referenced_table_name = ?',
				$this->connection->quote_identifier( self::MYSQL_FOREIGN_KEY_METADATA_TABLE )
			),
			array( $table_schema, $old_table_name )
		);
		$referencing_tables = $stmt->fetchAll( PDO::FETCH_ASSOC );

		foreach ( array( self::MYSQL_TABLE_METADATA_TABLE, self::MYSQL_COLUMN_METADATA_TABLE, self::MYSQL_INDEX_METADATA_TABLE, self::MYSQL_FOREIGN_KEY_METADATA_TABLE, self::MYSQL_CHECK_METADATA_TABLE ) as $metadata_table ) {
			$this->connection->query(
				sprintf(
					'UPDATE %s SET table_name = ? WHERE table_schema = ? AND table_name = ?',
					$this->connection->quote_identifier( $metadata_table )
				),
				array( $new_table_name, $table_schema, $old_table_name )
			);
		}

		$this->connection->query(
			sprintf(
				'UPDATE %s SET referenced_table_name = ? WHERE referenced_table_schema = ? AND referenced_table_name = ?',
				$this->connection->quote_identifier( self::MYSQL_FOREIGN_KEY_METADATA_TABLE )
			),
			array( $new_table_name, $table_schema, $old_table_name )
		);

		$this->clear_mysql_metadata_cache_for_table( $table_schema, $old_table_name );
		$this->clear_mysql_metadata_cache_for_table( $table_schema, $new_table_name );
		foreach ( $referencing_tables as $referencing_table ) {
			$this->clear_mysql_metadata_cache_for_table(
				(string) $referencing_table['table_schema'],
				(string) $referencing_table['table_name']
			);
		}
	}

	/**
	 * Check whether ALTER metadata contains an operation.
	 *
	 * @param array  $metadata  ALTER metadata.
	 * @param string $operation Operation name.
	 * @return bool Whether the operation is present.
	 */
	private function mysql_dbdelta_alter_metadata_has_operation( array $metadata, string $operation ): bool {
		if ( ( $metadata['operation'] ?? '' ) === $operation ) {
			return true;
		}

		if ( 'operations' !== ( $metadata['operation'] ?? '' ) ) {
			return false;
		}

		foreach ( $metadata['operations'] ?? array() as $operation_metadata ) {
			if ( is_array( $operation_metadata ) && $this->mysql_dbdelta_alter_metadata_has_operation( $operation_metadata, $operation ) ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Store MySQL metadata for a standalone CREATE INDEX statement.
	 *
	 * @param array $metadata CREATE INDEX metadata.
	 */
	private function apply_mysql_create_index_metadata( array $metadata ): void {
		$this->ensure_mysql_schema_metadata_tables();

		$table_schema = $metadata['schema'];
		$table_name   = $metadata['table'];
		$index        = $metadata['index'];

		$this->delete_mysql_index_metadata( $table_schema, $table_name, $index['name'] );
		$index['ordinal'] = $this->get_next_mysql_index_ordinal( $table_schema, $table_name );
		$this->insert_mysql_index_metadata( $table_schema, $table_name, $index );
	}

	/**
	 * Remove MySQL metadata for a standalone DROP INDEX statement.
	 *
	 * @param array $metadata DROP INDEX metadata.
	 */
	private function apply_mysql_drop_index_metadata( array $metadata ): void {
		$this->ensure_mysql_schema_metadata_tables();

		$this->delete_mysql_index_metadata(
			$metadata['schema'],
			$metadata['table'],
			$metadata['index']
		);
	}

	/**
	 * Insert or replace table metadata.
	 *
	 * @param string $table_schema Table schema.
	 * @param string $table_name   Table name.
	 * @param array  $metadata     Table metadata.
	 */
	private function insert_mysql_table_metadata( string $table_schema, string $table_name, array $metadata ): void {
		$this->connection->query(
			sprintf(
				'INSERT INTO %s
					(table_schema, table_name, table_comment)
				VALUES (?, ?, ?)',
				$this->connection->quote_identifier( self::MYSQL_TABLE_METADATA_TABLE )
			),
			array(
				$table_schema,
				$table_name,
				$metadata['comment'] ?? '',
			)
		);
		$this->clear_mysql_metadata_cache_for_table( $table_schema, $table_name );
	}

	/**
	 * Insert or replace column metadata.
	 *
	 * @param string $table_schema Table schema.
	 * @param string $table_name   Table name.
	 * @param array  $column       Column metadata.
	 */
	private function insert_mysql_column_metadata( string $table_schema, string $table_name, array $column ): void {
		$this->delete_mysql_column_metadata( $table_schema, $table_name, $column['name'] );
		$this->connection->query(
			sprintf(
				'INSERT INTO %s
					(table_schema, table_name, column_name, ordinal_position, column_type, character_set_name, collation_name, is_nullable, column_default, extra, column_comment)
				VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
				$this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE )
			),
			array(
				$table_schema,
				$table_name,
				$column['name'],
				$column['ordinal'],
				$column['type'],
				$column['charset'] ?? null,
				$column['collation'] ?? null,
				$column['nullable'] ?? 'YES',
				$column['default'] ?? null,
				$column['extra'] ?? '',
				$column['comment'] ?? '',
			)
		);
		$this->clear_mysql_metadata_cache_for_table( $table_schema, $table_name );
	}

	/**
	 * Delete metadata for one column.
	 *
	 * @param string $table_schema Table schema.
	 * @param string $table_name   Table name.
	 * @param string $column_name  Column name.
	 */
	private function delete_mysql_column_metadata( string $table_schema, string $table_name, string $column_name ): void {
		$this->connection->query(
			sprintf(
				'DELETE FROM %s WHERE table_schema = ? AND table_name = ? AND column_name = ?',
				$this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE )
			),
			array( $table_schema, $table_name, $column_name )
		);
		$this->clear_mysql_metadata_cache_for_table( $table_schema, $table_name );
	}

	/**
	 * Rename stored MySQL column metadata.
	 *
	 * @param string $table_schema    Table schema.
	 * @param string $table_name      Table name.
	 * @param string $old_column_name Old column name.
	 * @param string $new_column_name New column name.
	 */
	private function rename_mysql_column_metadata(
		string $table_schema,
		string $table_name,
		string $old_column_name,
		string $new_column_name
	): void {
		if ( $old_column_name === $new_column_name ) {
			return;
		}

		$this->connection->query(
			sprintf(
				'UPDATE %s SET column_name = ? WHERE table_schema = ? AND table_name = ? AND column_name = ?',
				$this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE )
			),
			array( $new_column_name, $table_schema, $table_name, $old_column_name )
		);
		$this->clear_mysql_metadata_cache_for_table( $table_schema, $table_name );
	}

	/**
	 * Insert MySQL SHOW INDEX metadata rows for an index.
	 *
	 * @param string     $table_schema    Table schema.
	 * @param string     $table_name      Table name.
	 * @param array      $index           Index metadata.
	 * @param array|null $column_nullable Optional nullable metadata keyed by lowercase column.
	 */
	private function insert_mysql_index_metadata(
		string $table_schema,
		string $table_name,
		array $index,
		?array $column_nullable = null
	): void {
		$column_nullable = $column_nullable ?? array();

		foreach ( $index['columns'] as $column ) {
			$is_nullable = $column_nullable[ strtolower( $column['column_name'] ) ]
				?? $this->get_mysql_column_nullable( $table_schema, $table_name, $column['column_name'] );

			$this->connection->query(
				sprintf(
					'INSERT INTO %s
						(table_schema, table_name, key_name, index_ordinal, seq_in_index, column_name, non_unique, index_type, "collation", sub_part, nullable, index_comment)
					VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
					$this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE )
				),
				array(
					$table_schema,
					$table_name,
					$index['name'],
					$index['ordinal'],
					$column['seq_in_index'],
					$column['column_name'],
					$index['non_unique'],
					$index['index_type'],
					'FULLTEXT' === strtoupper( (string) $index['index_type'] ) ? null : ( $column['collation'] ?? 'A' ),
					null === $column['sub_part'] ? null : (string) $column['sub_part'],
					'NO' === $is_nullable ? '' : 'YES',
					$index['comment'] ?? '',
				)
			);
		}

		$this->clear_mysql_metadata_cache_for_table( $table_schema, $table_name );
	}

	/**
	 * Delete metadata rows for one index.
	 *
	 * @param string $table_schema Table schema.
	 * @param string $table_name   Table name.
	 * @param string $index_name   Index name.
	 */
	private function delete_mysql_index_metadata( string $table_schema, string $table_name, string $index_name ): void {
		$this->connection->query(
			sprintf(
				'DELETE FROM %s WHERE table_schema = ? AND table_name = ? AND LOWER(key_name) = LOWER(?)',
				$this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE )
			),
			array( $table_schema, $table_name, $index_name )
		);
		$this->clear_mysql_metadata_cache_for_table( $table_schema, $table_name );
	}

	/**
	 * Rename stored MySQL index metadata.
	 *
	 * @param string $table_schema   Metadata schema.
	 * @param string $table_name     Table name.
	 * @param string $old_index_name Old index name.
	 * @param string $new_index_name New index name.
	 */
	private function rename_mysql_index_metadata(
		string $table_schema,
		string $table_name,
		string $old_index_name,
		string $new_index_name
	): void {
		if ( $old_index_name === $new_index_name ) {
			return;
		}

		$this->connection->query(
			sprintf(
				'UPDATE %s SET key_name = ? WHERE table_schema = ? AND table_name = ? AND LOWER(key_name) = LOWER(?)',
				$this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE )
			),
			array( $new_index_name, $table_schema, $table_name, $old_index_name )
		);
		$this->clear_mysql_metadata_cache_for_table( $table_schema, $table_name );
	}

	/**
	 * Check whether stored MySQL metadata has an index with the given name.
	 *
	 * @param string $table_schema Metadata schema.
	 * @param string $table_name   Table name.
	 * @param string $index_name   Index name.
	 * @return bool Whether the index metadata exists.
	 */
	private function mysql_index_metadata_exists( string $table_schema, string $table_name, string $index_name ): bool {
		$this->ensure_mysql_schema_metadata_tables();

		$stmt = $this->connection->query(
			sprintf(
				'SELECT 1 FROM %s WHERE table_schema = ? AND table_name = ? AND LOWER(key_name) = LOWER(?) LIMIT 1',
				$this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE )
			),
			array( $table_schema, $table_name, $index_name )
		);

		return false !== $stmt->fetchColumn();
	}

	/**
	 * Check whether stored MySQL metadata has any indexes for the given table.
	 *
	 * @param string $table_schema Metadata schema.
	 * @param string $table_name   Table name.
	 * @return bool Whether index metadata exists.
	 */
	private function mysql_index_metadata_has_rows( string $table_schema, string $table_name ): bool {
		$this->ensure_mysql_schema_metadata_tables();

		$stmt = $this->connection->query(
			sprintf(
				'SELECT 1 FROM %s WHERE table_schema = ? AND table_name = ? LIMIT 1',
				$this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE )
			),
			array( $table_schema, $table_name )
		);

		return false !== $stmt->fetchColumn();
	}

	/**
	 * Insert MySQL foreign key metadata rows for a constraint.
	 *
	 * @param string $table_schema Metadata schema.
	 * @param string $table_name   Table name.
	 * @param array  $foreign_key  Foreign key metadata.
	 */
	private function insert_mysql_foreign_key_metadata( string $table_schema, string $table_name, array $foreign_key ): void {
		$this->delete_mysql_foreign_key_metadata( $table_schema, $table_name, $foreign_key['name'] );

		$ordinal = $this->get_next_mysql_foreign_key_ordinal( $table_schema, $table_name );
		foreach ( $foreign_key['columns'] as $index => $column_name ) {
			$this->connection->query(
				sprintf(
					'INSERT INTO %s
						(table_schema, table_name, constraint_name, constraint_ordinal, seq_in_index, column_name, referenced_table_schema, referenced_table_name, referenced_column_name, update_rule, delete_rule)
					VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
					$this->connection->quote_identifier( self::MYSQL_FOREIGN_KEY_METADATA_TABLE )
				),
				array(
					$table_schema,
					$table_name,
					$foreign_key['name'],
					$ordinal,
					$index + 1,
					$column_name,
					$foreign_key['referenced_schema'],
					$foreign_key['referenced_table'],
					$foreign_key['referenced_columns'][ $index ],
					$foreign_key['update_rule'],
					$foreign_key['delete_rule'],
				)
			);
		}

		$this->clear_mysql_metadata_cache_for_table( $table_schema, $table_name );
	}

	/**
	 * Insert MySQL CHECK constraint metadata.
	 *
	 * @param string $table_schema Metadata schema.
	 * @param string $table_name   Table name.
	 * @param array  $check        CHECK constraint metadata.
	 */
	private function insert_mysql_check_metadata( string $table_schema, string $table_name, array $check ): void {
		$this->delete_mysql_check_metadata( $table_schema, $table_name, $check['name'] );

		$this->connection->query(
			sprintf(
				'INSERT INTO %s
					(table_schema, table_name, constraint_name, constraint_ordinal, check_clause, enforced)
				VALUES (?, ?, ?, ?, ?, ?)',
				$this->connection->quote_identifier( self::MYSQL_CHECK_METADATA_TABLE )
			),
			array(
				$table_schema,
				$table_name,
				$check['name'],
				$this->get_next_mysql_check_metadata_ordinal( $table_schema, $table_name ),
				$check['check_clause'],
				$check['enforced'] ?? 'YES',
			)
		);

		$this->clear_mysql_metadata_cache_for_table( $table_schema, $table_name );
	}

	/**
	 * Delete metadata rows for one CHECK constraint.
	 *
	 * @param string $table_schema    Metadata schema.
	 * @param string $table_name      Table name.
	 * @param string $constraint_name Constraint name.
	 */
	private function delete_mysql_check_metadata( string $table_schema, string $table_name, string $constraint_name ): void {
		$this->connection->query(
			sprintf(
				'DELETE FROM %s WHERE table_schema = ? AND table_name = ? AND LOWER(constraint_name) = LOWER(?)',
				$this->connection->quote_identifier( self::MYSQL_CHECK_METADATA_TABLE )
			),
			array( $table_schema, $table_name, $constraint_name )
		);

		$this->clear_mysql_metadata_cache_for_table( $table_schema, $table_name );
	}

	/**
	 * Get stored metadata for one CHECK constraint.
	 *
	 * @param string $table_schema    Metadata schema.
	 * @param string $table_name      Table name.
	 * @param string $constraint_name Constraint name.
	 * @return array|null CHECK metadata row, or null when absent.
	 */
	private function get_mysql_check_metadata( string $table_schema, string $table_name, string $constraint_name ): ?array {
		$this->ensure_mysql_schema_metadata_tables();

		$stmt = $this->connection->query(
			sprintf(
				'SELECT constraint_name, check_clause, enforced
				FROM %s
				WHERE table_schema = ? AND table_name = ? AND LOWER(constraint_name) = LOWER(?)
				LIMIT 1',
				$this->connection->quote_identifier( self::MYSQL_CHECK_METADATA_TABLE )
			),
			array( $table_schema, $table_name, $constraint_name )
		);

		$row = $stmt->fetch( PDO::FETCH_ASSOC );
		return false === $row ? null : $row;
	}

	/**
	 * Get the next CHECK metadata ordinal for a table.
	 *
	 * @param string $table_schema Metadata schema.
	 * @param string $table_name   Table name.
	 * @return int Next ordinal.
	 */
	private function get_next_mysql_check_metadata_ordinal( string $table_schema, string $table_name ): int {
		$stmt = $this->connection->query(
			sprintf(
				'SELECT COALESCE(MAX(constraint_ordinal), 0) + 1 FROM %s WHERE table_schema = ? AND table_name = ?',
				$this->connection->quote_identifier( self::MYSQL_CHECK_METADATA_TABLE )
			),
			array( $table_schema, $table_name )
		);

		return (int) $stmt->fetchColumn();
	}

	/**
	 * Delete metadata rows for one foreign key.
	 *
	 * @param string $table_schema    Metadata schema.
	 * @param string $table_name      Table name.
	 * @param string $constraint_name Constraint name.
	 */
	private function delete_mysql_foreign_key_metadata( string $table_schema, string $table_name, string $constraint_name ): void {
		$this->connection->query(
			sprintf(
				'DELETE FROM %s WHERE table_schema = ? AND table_name = ? AND LOWER(constraint_name) = LOWER(?)',
				$this->connection->quote_identifier( self::MYSQL_FOREIGN_KEY_METADATA_TABLE )
			),
			array( $table_schema, $table_name, $constraint_name )
		);

		$this->clear_mysql_metadata_cache_for_table( $table_schema, $table_name );
	}

	/**
	 * Delete metadata for foreign keys that reference one local column.
	 *
	 * @param string $table_schema Metadata schema.
	 * @param string $table_name   Table name.
	 * @param string $column_name  Dropped column name.
	 */
	private function delete_mysql_foreign_key_metadata_for_column( string $table_schema, string $table_name, string $column_name ): void {
		$stmt = $this->connection->query(
			sprintf(
				'SELECT DISTINCT constraint_name FROM %s WHERE table_schema = ? AND table_name = ? AND LOWER(column_name) = LOWER(?)',
				$this->connection->quote_identifier( self::MYSQL_FOREIGN_KEY_METADATA_TABLE )
			),
			array( $table_schema, $table_name, $column_name )
		);

		foreach ( $stmt->fetchAll( PDO::FETCH_COLUMN, 0 ) as $constraint_name ) {
			$this->delete_mysql_foreign_key_metadata( $table_schema, $table_name, (string) $constraint_name );
		}

		$this->clear_mysql_metadata_cache_for_table( $table_schema, $table_name );
	}

	/**
	 * Rename local foreign key column metadata after ALTER TABLE CHANGE COLUMN.
	 *
	 * @param string $table_schema    Metadata schema.
	 * @param string $table_name      Table name.
	 * @param string $old_column_name Old column name.
	 * @param string $new_column_name New column name.
	 */
	private function rename_mysql_foreign_key_column_metadata(
		string $table_schema,
		string $table_name,
		string $old_column_name,
		string $new_column_name
	): void {
		if ( $old_column_name === $new_column_name ) {
			return;
		}

		$this->connection->query(
			sprintf(
				'UPDATE %s SET column_name = ? WHERE table_schema = ? AND table_name = ? AND LOWER(column_name) = LOWER(?)',
				$this->connection->quote_identifier( self::MYSQL_FOREIGN_KEY_METADATA_TABLE )
			),
			array( $new_column_name, $table_schema, $table_name, $old_column_name )
		);

		$this->clear_mysql_metadata_cache_for_table( $table_schema, $table_name );
	}

	/**
	 * Rename referenced foreign key column metadata after a referenced column rename.
	 *
	 * @param string $table_schema    Referenced table schema.
	 * @param string $table_name      Referenced table name.
	 * @param string $old_column_name Old referenced column name.
	 * @param string $new_column_name New referenced column name.
	 */
	private function rename_mysql_referenced_foreign_key_column_metadata(
		string $table_schema,
		string $table_name,
		string $old_column_name,
		string $new_column_name
	): void {
		if ( $old_column_name === $new_column_name ) {
			return;
		}

		$stmt               = $this->connection->query(
			sprintf(
				'SELECT DISTINCT table_schema, table_name FROM %s WHERE referenced_table_schema = ? AND referenced_table_name = ? AND LOWER(referenced_column_name) = LOWER(?)',
				$this->connection->quote_identifier( self::MYSQL_FOREIGN_KEY_METADATA_TABLE )
			),
			array( $table_schema, $table_name, $old_column_name )
		);
		$referencing_tables = $stmt->fetchAll( PDO::FETCH_ASSOC );

		$this->connection->query(
			sprintf(
				'UPDATE %s SET referenced_column_name = ? WHERE referenced_table_schema = ? AND referenced_table_name = ? AND LOWER(referenced_column_name) = LOWER(?)',
				$this->connection->quote_identifier( self::MYSQL_FOREIGN_KEY_METADATA_TABLE )
			),
			array( $new_column_name, $table_schema, $table_name, $old_column_name )
		);

		foreach ( $referencing_tables as $referencing_table ) {
			$this->clear_mysql_metadata_cache_for_table(
				(string) $referencing_table['table_schema'],
				(string) $referencing_table['table_name']
			);
		}
	}

	/**
	 * Get the next stored foreign key ordinal for a table.
	 *
	 * @param string $table_schema Metadata schema.
	 * @param string $table_name   Table name.
	 * @return int Next ordinal.
	 */
	private function get_next_mysql_foreign_key_ordinal( string $table_schema, string $table_name ): int {
		$stmt = $this->connection->query(
			sprintf(
				'SELECT COALESCE(MAX(constraint_ordinal), 0) + 1 FROM %s WHERE table_schema = ? AND table_name = ?',
				$this->connection->quote_identifier( self::MYSQL_FOREIGN_KEY_METADATA_TABLE )
			),
			array( $table_schema, $table_name )
		);

		return (int) $stmt->fetchColumn();
	}

	/**
	 * Generate the next MySQL-style unnamed foreign key constraint name.
	 *
	 * @param string   $table_schema Metadata schema.
	 * @param string   $table_name   Table name.
	 * @param string[] $reserved     Names already generated for this statement.
	 * @return string Constraint name.
	 */
	private function get_next_mysql_foreign_key_constraint_name( string $table_schema, string $table_name, array $reserved = array() ): string {
		$this->ensure_mysql_schema_metadata_tables();

		$stmt = $this->connection->query(
			sprintf(
				'SELECT DISTINCT constraint_name FROM %s WHERE table_schema = ? AND table_name = ?',
				$this->connection->quote_identifier( self::MYSQL_FOREIGN_KEY_METADATA_TABLE )
			),
			array( $table_schema, $table_name )
		);

		$max_suffix = 0;
		$pattern    = '/^' . preg_quote( $table_name, '/' ) . '_ibfk_(\d+)$/i';
		foreach ( array_merge( $stmt->fetchAll( PDO::FETCH_COLUMN, 0 ), $reserved ) as $constraint_name ) {
			if ( 1 === preg_match( $pattern, (string) $constraint_name, $matches ) ) {
				$max_suffix = max( $max_suffix, (int) $matches[1] );
			}
		}

		return sprintf( '%s_ibfk_%d', $table_name, $max_suffix + 1 );
	}

	/**
	 * Check whether stored MySQL metadata has a foreign key with the given name.
	 *
	 * @param string $table_schema    Metadata schema.
	 * @param string $table_name      Table name.
	 * @param string $constraint_name Constraint name.
	 * @return bool Whether the foreign key metadata exists.
	 */
	private function mysql_foreign_key_metadata_exists( string $table_schema, string $table_name, string $constraint_name ): bool {
		$this->ensure_mysql_schema_metadata_tables();

		$stmt = $this->connection->query(
			sprintf(
				'SELECT 1 FROM %s WHERE table_schema = ? AND table_name = ? AND LOWER(constraint_name) = LOWER(?) LIMIT 1',
				$this->connection->quote_identifier( self::MYSQL_FOREIGN_KEY_METADATA_TABLE )
			),
			array( $table_schema, $table_name, $constraint_name )
		);

		return false !== $stmt->fetchColumn();
	}

	/**
	 * Delete metadata key parts for one dropped column and renumber surviving parts.
	 *
	 * MySQL removes a dropped column from every index that contains it. Indexes
	 * remain visible when at least one key part survives.
	 *
	 * @param string $table_schema Table schema.
	 * @param string $table_name   Table name.
	 * @param string $column_name  Dropped column name.
	 */
	private function delete_mysql_index_metadata_for_column( string $table_schema, string $table_name, string $column_name ): void {
		$index_metadata_table = $this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE );

		$this->connection->query(
			sprintf(
				'DELETE FROM %s WHERE table_schema = ? AND table_name = ? AND LOWER(column_name) = LOWER(?)',
				$index_metadata_table
			),
			array( $table_schema, $table_name, $column_name )
		);

		$this->connection->query(
			sprintf(
				'WITH renumbered AS (
					SELECT
						table_schema,
						table_name,
						key_name,
						seq_in_index AS old_seq_in_index,
						row_number() OVER (PARTITION BY key_name ORDER BY seq_in_index) AS new_seq_in_index
					FROM %1$s
					WHERE table_schema = ?
						AND table_name = ?
				)
				UPDATE %1$s AS im
				SET seq_in_index = -(
					SELECT new_seq_in_index
					FROM renumbered
					WHERE renumbered.table_schema = im.table_schema
						AND renumbered.table_name = im.table_name
						AND renumbered.key_name = im.key_name
						AND renumbered.old_seq_in_index = im.seq_in_index
				)
				WHERE im.table_schema = ?
					AND im.table_name = ?
					AND EXISTS (
						SELECT 1
						FROM renumbered
						WHERE renumbered.table_schema = im.table_schema
							AND renumbered.table_name = im.table_name
							AND renumbered.key_name = im.key_name
							AND renumbered.old_seq_in_index = im.seq_in_index
					)',
				$index_metadata_table
			),
			array( $table_schema, $table_name, $table_schema, $table_name )
		);

		$this->connection->query(
			sprintf(
				'UPDATE %s SET seq_in_index = -seq_in_index WHERE table_schema = ? AND table_name = ? AND seq_in_index < 0',
				$index_metadata_table
			),
			array( $table_schema, $table_name )
		);

		$this->clear_mysql_metadata_cache_for_table( $table_schema, $table_name );
	}

	/**
	 * Get the backend primary key constraint name for a MySQL table.
	 *
	 * @param string $table_schema Backend schema.
	 * @param string $table_name   Table name.
	 * @return string PostgreSQL primary key constraint name.
	 */
	private function get_postgresql_primary_key_constraint_name( string $table_schema, string $table_name ): string {
		try {
			$stmt = $this->connection->query(
				"SELECT constraint_name
				FROM information_schema.table_constraints
				WHERE table_schema = ?
					AND table_name = ?
					AND constraint_type = 'PRIMARY KEY'
				ORDER BY constraint_name
				LIMIT 1",
				array( $table_schema, $table_name )
			);

			$constraint_name = $stmt->fetchColumn();
			if ( false !== $constraint_name && '' !== (string) $constraint_name ) {
				return (string) $constraint_name;
			}
		} catch ( PDOException $e ) {
			// Test fixtures and SQLite-backed connections may not expose PostgreSQL catalogs.
		}

		return $table_name . '_pkey';
	}

	/**
	 * Generate the next MySQL-compatible CHECK constraint name for a table.
	 *
	 * @param string $table_schema Backend schema.
	 * @param string $table_name   Table name.
	 * @param array  $reserved     Constraint names already reserved in the current statement.
	 * @return string Generated CHECK constraint name.
	 */
	private function get_next_mysql_check_constraint_name( string $table_schema, string $table_name, array $reserved = array() ): string {
		$prefix = $table_name . '_chk_';
		$max    = 0;

		try {
			$stmt = $this->connection->query(
				"SELECT constraint_name
				FROM information_schema.table_constraints
				WHERE table_schema = ?
					AND table_name = ?
					AND constraint_type = 'CHECK'",
				array( $table_schema, $table_name )
			);

			foreach ( $stmt->fetchAll( PDO::FETCH_COLUMN, 0 ) as $constraint_name ) {
				if ( 1 === preg_match( '/^' . preg_quote( $prefix, '/' ) . '([1-9][0-9]*)$/', (string) $constraint_name, $matches ) ) {
					$max = max( $max, (int) $matches[1] );
				}
			}
		} catch ( PDOException $e ) {
			// Test fixtures and SQLite-backed connections may not expose PostgreSQL catalogs.
		}

		try {
			$this->ensure_mysql_schema_metadata_tables();
			$stmt = $this->connection->query(
				sprintf(
					'SELECT constraint_name
					FROM %s
					WHERE table_schema = ?
						AND table_name = ?',
					$this->connection->quote_identifier( self::MYSQL_CHECK_METADATA_TABLE )
				),
				array( $table_schema, $table_name )
			);

			foreach ( $stmt->fetchAll( PDO::FETCH_COLUMN, 0 ) as $constraint_name ) {
				if ( 1 === preg_match( '/^' . preg_quote( $prefix, '/' ) . '([1-9][0-9]*)$/', (string) $constraint_name, $matches ) ) {
					$max = max( $max, (int) $matches[1] );
				}
			}
		} catch ( PDOException $e ) {
			// Test fixtures and SQLite-backed connections may not expose metadata side tables yet.
		}

		foreach ( $reserved as $constraint_name ) {
			if ( 1 === preg_match( '/^' . preg_quote( $prefix, '/' ) . '([1-9][0-9]*)$/', (string) $constraint_name, $matches ) ) {
				$max = max( $max, (int) $matches[1] );
			}
		}

		return $prefix . ( $max + 1 );
	}

	/**
	 * Rename index column metadata after ALTER TABLE CHANGE COLUMN.
	 *
	 * @param string $table_schema    Table schema.
	 * @param string $table_name      Table name.
	 * @param string $old_column_name Old column name.
	 * @param string $new_column_name New column name.
	 */
	private function rename_mysql_index_column_metadata(
		string $table_schema,
		string $table_name,
		string $old_column_name,
		string $new_column_name
	): void {
		if ( $old_column_name === $new_column_name ) {
			return;
		}

		$this->connection->query(
			sprintf(
				'UPDATE %s SET column_name = ? WHERE table_schema = ? AND table_name = ? AND column_name = ?',
				$this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE )
			),
			array( $new_column_name, $table_schema, $table_name, $old_column_name )
		);
		$this->clear_mysql_metadata_cache_for_table( $table_schema, $table_name );
	}

	/**
	 * Get the next stored column ordinal for a table.
	 *
	 * @param string $table_schema Table schema.
	 * @param string $table_name   Table name.
	 * @return int Next ordinal.
	 */
	private function get_next_mysql_column_ordinal( string $table_schema, string $table_name ): int {
		$stmt = $this->connection->query(
			sprintf(
				'SELECT COALESCE(MAX(ordinal_position), 0) + 1 FROM %s WHERE table_schema = ? AND table_name = ?',
				$this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE )
			),
			array( $table_schema, $table_name )
		);

		return (int) $stmt->fetchColumn();
	}

	/**
	 * Get an existing stored column ordinal.
	 *
	 * @param string $table_schema Table schema.
	 * @param string $table_name   Table name.
	 * @param string $column_name  Column name.
	 * @return int|null Existing ordinal, or null.
	 */
	private function get_existing_mysql_column_ordinal( string $table_schema, string $table_name, string $column_name ): ?int {
		$stmt = $this->connection->query(
			sprintf(
				'SELECT ordinal_position FROM %s WHERE table_schema = ? AND table_name = ? AND column_name = ?',
				$this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE )
			),
			array( $table_schema, $table_name, $column_name )
		);

		$ordinal = $stmt->fetchColumn();
		return false === $ordinal ? null : (int) $ordinal;
	}

	/**
	 * Get the next stored index ordinal for a table.
	 *
	 * @param string $table_schema Table schema.
	 * @param string $table_name   Table name.
	 * @return int Next ordinal.
	 */
	private function get_next_mysql_index_ordinal( string $table_schema, string $table_name ): int {
		$stmt = $this->connection->query(
			sprintf(
				'SELECT COALESCE(MAX(index_ordinal), 0) + 1 FROM %s WHERE table_schema = ? AND table_name = ?',
				$this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE )
			),
			array( $table_schema, $table_name )
		);

		return (int) $stmt->fetchColumn();
	}

	/**
	 * Get stored nullable metadata for an index column.
	 *
	 * @param string $table_schema Table schema.
	 * @param string $table_name   Table name.
	 * @param string $column_name  Column name.
	 * @return string MySQL nullable value.
	 */
	private function get_mysql_column_nullable( string $table_schema, string $table_name, string $column_name ): string {
		$stmt = $this->connection->query(
			sprintf(
				'SELECT is_nullable FROM %s WHERE table_schema = ? AND table_name = ? AND column_name = ?',
				$this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE )
			),
			array( $table_schema, $table_name, $column_name )
		);

		$nullable = $stmt->fetchColumn();
		return false === $nullable ? 'YES' : (string) $nullable;
	}

	/**
	 * Get stored MySQL extra metadata for a table column.
	 *
	 * @param string $table_schema Table schema.
	 * @param string $table_name   Table name.
	 * @param string $column_name  Column name.
	 * @return string Extra metadata.
	 */
	private function get_mysql_column_extra_metadata( string $table_schema, string $table_name, string $column_name ): string {
		$stmt = $this->connection->query(
			sprintf(
				'SELECT extra FROM %s WHERE table_schema = ? AND table_name = ? AND column_name = ?',
				$this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE )
			),
			array( $table_schema, $table_name, $column_name )
		);

		$extra = $stmt->fetchColumn();
		return false === $extra ? '' : (string) $extra;
	}

	/**
	 * Get the stored MySQL type for a table column.
	 *
	 * @param string $table_schema Metadata schema.
	 * @param string $table_name   Table name.
	 * @param string $column_name  Column name.
	 * @return string|null MySQL column type, or null when unavailable.
	 */
	private function get_mysql_table_column_type(
		string $table_schema,
		string $table_name,
		string $column_name
	): ?string {
		$this->ensure_mysql_schema_metadata_tables();

		$table_cache_key  = $this->get_mysql_metadata_cache_key( $table_schema, $table_name );
		$column_cache_key = strtolower( $column_name );
		if (
			isset( $this->mysql_table_column_type_cache[ $table_cache_key ] )
			&& array_key_exists( $column_cache_key, $this->mysql_table_column_type_cache[ $table_cache_key ] )
		) {
			return $this->mysql_table_column_type_cache[ $table_cache_key ][ $column_cache_key ];
		}

		$stmt = $this->connection->query(
			sprintf(
				'SELECT column_type FROM %s
				WHERE table_schema = ?
					AND table_name = ?
					AND LOWER(column_name) = LOWER(?)',
				$this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE )
			),
			array( $table_schema, $table_name, $column_name )
		);

		$column_type = $stmt->fetchColumn();
		$this->mysql_table_column_type_cache[ $table_cache_key ][ $column_cache_key ] = false === $column_type
			? null
			: (string) $column_type;

		return $this->mysql_table_column_type_cache[ $table_cache_key ][ $column_cache_key ];
	}

	/**
	 * Get the stored MySQL collation for a table column.
	 *
	 * @param string $table_schema Metadata schema.
	 * @param string $table_name   Table name.
	 * @param string $column_name  Column name.
	 * @return string|null MySQL collation, or null when unavailable.
	 */
	private function get_mysql_table_column_collation(
		string $table_schema,
		string $table_name,
		string $column_name
	): ?string {
		$this->ensure_mysql_schema_metadata_tables();

		$table_cache_key  = $this->get_mysql_metadata_cache_key( $table_schema, $table_name );
		$column_cache_key = strtolower( $column_name );
		if (
			isset( $this->mysql_table_column_collation_cache[ $table_cache_key ] )
			&& array_key_exists( $column_cache_key, $this->mysql_table_column_collation_cache[ $table_cache_key ] )
		) {
			return $this->mysql_table_column_collation_cache[ $table_cache_key ][ $column_cache_key ];
		}

		$stmt = $this->connection->query(
			sprintf(
				'SELECT collation_name FROM %s
				WHERE table_schema = ?
					AND table_name = ?
					AND LOWER(column_name) = LOWER(?)',
				$this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE )
			),
			array( $table_schema, $table_name, $column_name )
		);

		$collation = $stmt->fetchColumn();
		$this->mysql_table_column_collation_cache[ $table_cache_key ][ $column_cache_key ] = false === $collation || null === $collation
			? null
			: (string) $collation;

		return $this->mysql_table_column_collation_cache[ $table_cache_key ][ $column_cache_key ];
	}

	/**
	 * Check whether stored MySQL metadata exists for a table.
	 *
	 * @param string $table_schema Metadata schema.
	 * @param string $table_name   Table name.
	 * @return bool Whether metadata exists.
	 */
	private function mysql_table_has_column_metadata( string $table_schema, string $table_name ): bool {
		$this->ensure_mysql_schema_metadata_tables();

		$cache_key = $this->get_mysql_metadata_cache_key( $table_schema, $table_name );
		if ( array_key_exists( $cache_key, $this->mysql_table_has_column_metadata_cache ) ) {
			return $this->mysql_table_has_column_metadata_cache[ $cache_key ];
		}

		$stmt = $this->connection->query(
			sprintf(
				'SELECT 1 FROM %s WHERE table_schema = ? AND table_name = ? LIMIT 1',
				$this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE )
			),
			array( $table_schema, $table_name )
		);

		$this->mysql_table_has_column_metadata_cache[ $cache_key ] = false !== $stmt->fetchColumn();
		return $this->mysql_table_has_column_metadata_cache[ $cache_key ];
	}

	/**
	 * Translate supported MySQL CREATE TABLE ... [AS] SELECT statements to PostgreSQL.
	 *
	 * @param string $query MySQL CREATE TABLE ... SELECT query.
	 * @return array{sql: string, schema: string, table: string, temporary: bool}|null Translation, or null when this is not CTAS.
	 */
	private function translate_mysql_create_table_select_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::CREATE_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			throw new InvalidArgumentException( 'Unsupported CREATE TABLE statement.' );
		}

		$position     = 1;
		$is_temporary = false;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::TEMPORARY_SYMBOL === $tokens[ $position ]->id ) {
			$is_temporary = true;
			++$position;
		}

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::TABLE_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		++$position;
		$if_not_exists = false;
		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ], $tokens[ $position + 2 ] )
			&& WP_MySQL_Lexer::IF_SYMBOL === $tokens[ $position ]->id
			&& WP_MySQL_Lexer::NOT_SYMBOL === $tokens[ $position + 1 ]->id
			&& WP_MySQL_Lexer::EXISTS_SYMBOL === $tokens[ $position + 2 ]->id
		) {
			$if_not_exists = true;
			$position     += 3;
		}

		$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position, true );
		if ( null === $table_reference ) {
			return null;
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::AS_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		$select_start = $position;
		$select_end   = $statement_end;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
			$parenthesized_end = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $statement_end );
			if (
				null !== $parenthesized_end
				&& $parenthesized_end === $statement_end
				&& isset( $tokens[ $position + 1 ] )
				&& WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[ $position + 1 ]->id
			) {
				$select_start = $position + 1;
				$select_end   = $parenthesized_end - 1;
			}
		}

		if ( ! isset( $tokens[ $select_start ] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $select_start ]->id ) {
			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
				$definition_end = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $statement_end );
				if ( null !== $definition_end && isset( $tokens[ $definition_end ] ) ) {
					$after_definition = $definition_end;
					if ( WP_MySQL_Lexer::AS_SYMBOL === $tokens[ $after_definition ]->id ) {
						++$after_definition;
					}

					if ( isset( $tokens[ $after_definition ] ) && WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[ $after_definition ]->id ) {
						throw new InvalidArgumentException( 'Unsupported CREATE TABLE statement.' );
					}
				}
			}

			if ( null !== $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::SELECT_SYMBOL, $position, $statement_end ) ) {
				throw new InvalidArgumentException( 'Unsupported CREATE TABLE statement.' );
			}

			return null;
		}

		$schema_name = $this->get_mysql_create_table_select_backend_schema( $table_reference, $is_temporary );
		$select_sql  = $this->get_mysql_token_range_bytes( $query, $tokens, $select_start, $select_end );
		if ( '' === trim( $select_sql ) ) {
			throw new InvalidArgumentException( 'Unsupported CREATE TABLE statement.' );
		}

		$select_translation = $this->translate_mysql_select_query_for_postgresql( $select_sql );
		$table_identifier   = $is_temporary
			? $this->connection->quote_identifier( $table_reference['table'] )
			: $this->get_postgresql_schema_identifier( $schema_name, $table_reference['table'] );

		return array(
			'sql'       => sprintf(
				'CREATE %sTABLE %s%s AS %s',
				$is_temporary ? 'TEMPORARY ' : '',
				$if_not_exists ? 'IF NOT EXISTS ' : '',
				$table_identifier,
				$select_translation['sql']
			),
			'schema'    => $schema_name,
			'table'     => $table_reference['table'],
			'temporary' => $is_temporary,
		);
	}

	/**
	 * Resolve the backend schema for a CREATE TABLE ... SELECT target.
	 *
	 * @param array $table_reference Parsed table reference.
	 * @param bool  $is_temporary    Whether the target table is temporary.
	 * @return string Backend schema name for metadata.
	 */
	private function get_mysql_create_table_select_backend_schema( array $table_reference, bool $is_temporary ): string {
		$requested_schema = $table_reference['schema'];
		if ( null !== $requested_schema && 0 === strcasecmp( $requested_schema, 'information_schema' ) ) {
			throw new InvalidArgumentException( 'Unsupported information_schema query.' );
		}

		if ( $is_temporary ) {
			if (
				null !== $requested_schema
				&& 0 !== strcasecmp( $requested_schema, $this->main_db_name )
				&& 0 !== strcasecmp( $requested_schema, 'public' )
			) {
				throw new InvalidArgumentException( 'Unsupported CREATE TABLE statement.' );
			}

			return $this->get_temporary_drop_table_schema_name();
		}

		if ( null === $requested_schema ) {
			if ( 0 === strcasecmp( $this->db_name, 'information_schema' ) ) {
				throw new InvalidArgumentException( 'Unsupported information_schema query.' );
			}

			return 'public';
		}

		return $this->get_mysql_writable_table_backend_schema( $table_reference, 'CREATE TABLE' );
	}

	/**
	 * Store MySQL-facing column metadata for a CREATE TABLE ... SELECT result.
	 *
	 * @param string $table_schema Backend schema name.
	 * @param string $table_name   Table name.
	 */
	private function store_mysql_create_table_select_metadata( string $table_schema, string $table_name ): void {
		$this->ensure_mysql_schema_metadata_tables();
		$this->delete_mysql_schema_metadata_for_tables( array( $table_name ), $table_schema );

		foreach ( $this->get_mysql_create_table_select_column_metadata( $table_schema, $table_name ) as $column ) {
			$this->insert_mysql_column_metadata( $table_schema, $table_name, $column );
		}

		$this->clear_mysql_metadata_cache_for_table( $table_schema, $table_name );
	}

	/**
	 * Get MySQL-facing column metadata for a backend CTAS table.
	 *
	 * @param string $table_schema Backend schema name.
	 * @param string $table_name   Table name.
	 * @return array[] Column metadata rows.
	 */
	private function get_mysql_create_table_select_column_metadata( string $table_schema, string $table_name ): array {
		$driver_name = (string) $this->connection->get_pdo()->getAttribute( PDO::ATTR_DRIVER_NAME );
		if ( 'sqlite' === $driver_name ) {
			return $this->get_sqlite_create_table_select_column_metadata( $table_schema, $table_name );
		}

		$stmt = $this->connection->query(
			'SELECT column_name, ordinal_position, data_type, character_maximum_length, numeric_precision, numeric_scale, is_nullable, column_default
			FROM information_schema.columns
			WHERE table_schema = ? AND table_name = ?
			ORDER BY ordinal_position',
			array( $table_schema, $table_name )
		);

		$columns = array();
		foreach ( $stmt->fetchAll( PDO::FETCH_ASSOC ) as $column ) {
			$column_type = $this->get_mysql_column_type_from_backend_metadata( $column );
			$columns[]   = array(
				'name'      => (string) $column['column_name'],
				'ordinal'   => (int) $column['ordinal_position'],
				'type'      => $column_type,
				'charset'   => $this->mysql_column_type_uses_charset( $column_type ) ? $this->charset : null,
				'collation' => $this->mysql_column_type_uses_charset( $column_type ) ? $this->collation : null,
				'nullable'  => (string) $column['is_nullable'],
				'default'   => null === $column['column_default'] ? null : (string) $column['column_default'],
				'extra'     => '',
			);
		}

		return $columns;
	}

	/**
	 * Get MySQL-facing column metadata for a SQLite-backed CTAS table.
	 *
	 * @param string $table_schema Backend schema name.
	 * @param string $table_name   Table name.
	 * @return array[] Column metadata rows.
	 */
	private function get_sqlite_create_table_select_column_metadata( string $table_schema, string $table_name ): array {
		$schema_prefix = 'temp' === $table_schema ? 'temp.' : '';
		$stmt          = $this->connection->query(
			sprintf(
				'PRAGMA %stable_info(%s)',
				$schema_prefix,
				$this->connection->quote_identifier( $table_name )
			)
		);

		$columns = array();
		foreach ( $stmt->fetchAll( PDO::FETCH_ASSOC ) as $column ) {
			$column_type = $this->get_mysql_column_type_from_sqlite_type( (string) ( $column['type'] ?? '' ) );
			$columns[]   = array(
				'name'      => (string) $column['name'],
				'ordinal'   => (int) $column['cid'] + 1,
				'type'      => $column_type,
				'charset'   => $this->mysql_column_type_uses_charset( $column_type ) ? $this->charset : null,
				'collation' => $this->mysql_column_type_uses_charset( $column_type ) ? $this->collation : null,
				'nullable'  => ! empty( $column['notnull'] ) ? 'NO' : 'YES',
				'default'   => null === $column['dflt_value'] ? null : (string) $column['dflt_value'],
				'extra'     => '',
			);
		}

		return $columns;
	}

	/**
	 * Convert backend information_schema type metadata into a MySQL-facing type.
	 *
	 * @param array $column Backend column metadata.
	 * @return string MySQL-facing column type.
	 */
	private function get_mysql_column_type_from_backend_metadata( array $column ): string {
		$data_type = strtolower( (string) $column['data_type'] );
		switch ( $data_type ) {
			case 'character varying':
				return null === $column['character_maximum_length'] ? 'varchar' : 'varchar(' . (int) $column['character_maximum_length'] . ')';
			case 'character':
				return null === $column['character_maximum_length'] ? 'char' : 'char(' . (int) $column['character_maximum_length'] . ')';
			case 'integer':
				return 'int';
			case 'boolean':
				return 'tinyint(1)';
			case 'timestamp without time zone':
				return 'datetime';
			case 'timestamp with time zone':
				return 'timestamp';
			case 'numeric':
			case 'decimal':
				if ( null !== $column['numeric_precision'] && null !== $column['numeric_scale'] ) {
					return 'decimal(' . (int) $column['numeric_precision'] . ',' . (int) $column['numeric_scale'] . ')';
				}
				if ( null !== $column['numeric_precision'] ) {
					return 'decimal(' . (int) $column['numeric_precision'] . ')';
				}
				return 'decimal';
			case 'double precision':
				return 'double';
			case 'real':
				return 'float';
			default:
				return '' === $data_type ? 'text' : $data_type;
		}
	}

	/**
	 * Convert a SQLite declared type into a MySQL-facing type.
	 *
	 * @param string $sqlite_type SQLite declared type.
	 * @return string MySQL-facing column type.
	 */
	private function get_mysql_column_type_from_sqlite_type( string $sqlite_type ): string {
		$type = strtoupper( $sqlite_type );
		if ( '' === $type ) {
			return 'text';
		}

		if ( false !== strpos( $type, 'INT' ) ) {
			return 'int';
		}

		if ( false !== strpos( $type, 'CHAR' ) || false !== strpos( $type, 'CLOB' ) || false !== strpos( $type, 'TEXT' ) ) {
			return 'text';
		}

		if ( false !== strpos( $type, 'BLOB' ) ) {
			return 'blob';
		}

		if ( false !== strpos( $type, 'REAL' ) || false !== strpos( $type, 'FLOA' ) || false !== strpos( $type, 'DOUB' ) ) {
			return 'double';
		}

		if ( false !== strpos( $type, 'NUM' ) || false !== strpos( $type, 'DEC' ) ) {
			return 'decimal';
		}

		return strtolower( $sqlite_type );
	}

	/**
	 * Check whether a MySQL-facing column type uses character metadata.
	 *
	 * @param string $column_type MySQL-facing column type.
	 * @return bool Whether charset and collation metadata apply.
	 */
	private function mysql_column_type_uses_charset( string $column_type ): bool {
		$column_type = strtolower( $column_type );
		return 0 === strpos( $column_type, 'char' )
			|| 0 === strpos( $column_type, 'varchar' )
			|| false !== strpos( $column_type, 'text' );
	}

	/**
	 * Check whether a MySQL-facing column type is spatial.
	 *
	 * @param string $column_type MySQL-facing column type.
	 * @return bool Whether the type is spatial.
	 */
	private function is_mysql_spatial_column_type( string $column_type ): bool {
		$column_type     = strtolower( trim( $column_type ) );
		$length_position = strpos( $column_type, '(' );
		if ( false !== $length_position ) {
			$column_type = substr( $column_type, 0, $length_position );
		}
		$space_position = strpos( $column_type, ' ' );
		if ( false !== $space_position ) {
			$column_type = substr( $column_type, 0, $space_position );
		}

		return in_array(
			$column_type,
			array(
				'geometry',
				'point',
				'linestring',
				'polygon',
				'multipoint',
				'multilinestring',
				'multipolygon',
				'geometrycollection',
				'geomcollection',
			),
			true
		);
	}

	/**
	 * Translate supported standalone MySQL CREATE INDEX statements to PostgreSQL.
	 *
	 * @param string $query MySQL CREATE INDEX query.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when this is not CREATE INDEX.
	 */
	private function translate_mysql_create_index_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::CREATE_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			throw new InvalidArgumentException( 'Unsupported CREATE INDEX statement.' );
		}

		$position  = 1;
		$is_unique = false;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::UNIQUE_SYMBOL === $tokens[ $position ]->id ) {
			$is_unique = true;
			++$position;
		}

		$index_type = 'BTREE';
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::FULLTEXT_SYMBOL === $tokens[ $position ]->id ) {
			if ( $is_unique ) {
				throw new InvalidArgumentException( 'Unsupported CREATE INDEX statement.' );
			}
			$index_type = 'FULLTEXT';
			++$position;
		} elseif ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::SPATIAL_SYMBOL === $tokens[ $position ]->id ) {
			if ( $is_unique ) {
				throw new InvalidArgumentException( 'Unsupported CREATE INDEX statement.' );
			}
			$index_type = 'SPATIAL';
			++$position;
		}

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::INDEX_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		++$position;
		$if_not_exists = false;
		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ], $tokens[ $position + 2 ] )
			&& WP_MySQL_Lexer::IF_SYMBOL === $tokens[ $position ]->id
			&& WP_MySQL_Lexer::NOT_SYMBOL === $tokens[ $position + 1 ]->id
			&& WP_MySQL_Lexer::EXISTS_SYMBOL === $tokens[ $position + 2 ]->id
		) {
			$if_not_exists = true;
			$position     += 3;
		}

		$index_name_token = $tokens[ $position ] ?? null;
		$index_name       = $this->get_mysql_identifier_token_value( $index_name_token, true );
		if ( null === $index_name ) {
			throw new InvalidArgumentException( 'Unsupported CREATE INDEX statement.' );
		}

		++$position;
		if ( ! $this->consume_mysql_supported_create_index_type( $tokens, $position ) ) {
			throw new InvalidArgumentException( 'Unsupported CREATE INDEX statement.' );
		}

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::ON_SYMBOL !== $tokens[ $position ]->id ) {
			throw new InvalidArgumentException( 'Unsupported CREATE INDEX statement.' );
		}

		++$position;
		$table_reference_is_quoted = isset( $tokens[ $position ] ) && WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT === $tokens[ $position ]->id;
		$table_reference           = $this->get_mysql_table_administration_table_reference( $tokens, $position, true );
		if ( null === $table_reference ) {
			throw new InvalidArgumentException( 'Unsupported CREATE INDEX statement.' );
		}

		$table_schema = $this->get_mysql_writable_table_backend_schema( $table_reference, 'CREATE INDEX' );
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position ]->id ) {
			throw new InvalidArgumentException( 'Unsupported CREATE INDEX statement.' );
		}

		$key_list_end = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $statement_end );
		if ( null === $key_list_end ) {
			throw new InvalidArgumentException( 'Unsupported CREATE INDEX statement.' );
		}

		$key_parts = $this->parse_mysql_create_index_key_parts(
			$tokens,
			$position + 1,
			$key_list_end - 1,
			$is_unique
		);
		if ( null === $key_parts ) {
			throw new InvalidArgumentException( 'Unsupported CREATE INDEX statement.' );
		}
		if ( 'BTREE' === $index_type && $this->is_mysql_spatial_index_key_parts( $table_schema, $table_reference['table'], $key_parts['metadata'] ) ) {
			$index_type = 'SPATIAL';
		}
		if ( 'SPATIAL' === $index_type ) {
			$key_parts['metadata'] = $this->apply_mysql_spatial_index_sub_parts( $key_parts['metadata'] );
		}

		$position      = $key_list_end;
		$index_comment = '';
		if ( ! $this->consume_mysql_supported_create_index_options( $tokens, $position, $statement_end, $index_type, $index_comment ) ) {
			throw new InvalidArgumentException( 'Unsupported CREATE INDEX statement.' );
		}

		$table_name            = $table_reference['table'];
		$metadata_index_name   = $index_name;
		$postgresql_index_name = $table_name . '__' . $index_name;
		if (
			WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT === $index_name_token->id
			&& $table_reference_is_quoted
			&& 0 === strpos( $index_name, $table_name . '__' )
		) {
			$metadata_index_name   = substr( $index_name, strlen( $table_name ) + 2 );
			$postgresql_index_name = $index_name;
			if ( '' === $metadata_index_name ) {
				throw new InvalidArgumentException( 'Unsupported CREATE INDEX statement.' );
			}
		}

		$postgresql_index = $this->connection->quote_identifier( $postgresql_index_name );
		$postgresql_table = $this->get_postgresql_schema_identifier( $table_schema, $table_name );

		$statements = array();
		if ( ! $this->is_mysql_metadata_only_index_type( $index_type ) ) {
			$statements[] = sprintf(
				'CREATE %sINDEX %s%s ON %s (%s)',
				$is_unique ? 'UNIQUE ' : '',
				$if_not_exists ? 'IF NOT EXISTS ' : '',
				$postgresql_index,
				$postgresql_table,
				implode( ', ', $key_parts['sql'] )
			);
		}

		return array(
			'statements' => $statements,
			'metadata'   => array(
				'schema' => $table_schema,
				'table'  => $table_name,
				'index'  => array(
					'name'       => $metadata_index_name,
					'non_unique' => $is_unique ? '0' : '1',
					'index_type' => $index_type,
					'comment'    => $index_comment,
					'columns'    => $key_parts['metadata'],
				),
			),
		);
	}

	/**
	 * Check whether a MySQL index type is stored only as MySQL metadata.
	 *
	 * @param string $index_type MySQL index type.
	 * @return bool Whether no PostgreSQL physical index should be created.
	 */
	private function is_mysql_metadata_only_index_type( string $index_type ): bool {
		return in_array( strtoupper( $index_type ), array( 'FULLTEXT', 'SPATIAL' ), true );
	}

	/**
	 * Check whether parsed key parts should be exposed as a MySQL SPATIAL index.
	 *
	 * @param string $table_schema Metadata schema.
	 * @param string $table_name   Table name.
	 * @param array  $key_parts    Parsed key-part metadata.
	 * @return bool Whether the first key part targets a spatial column.
	 */
	private function is_mysql_spatial_index_key_parts( string $table_schema, string $table_name, array $key_parts ): bool {
		if ( ! isset( $key_parts[0]['column_name'] ) ) {
			return false;
		}

		$column_type = $this->get_mysql_table_column_type( $table_schema, $table_name, (string) $key_parts[0]['column_name'] );
		return is_string( $column_type ) && $this->is_mysql_spatial_column_type( $column_type );
	}

	/**
	 * Apply MySQL's implicit SPATIAL key-part prefix length.
	 *
	 * @param array $key_parts Parsed key-part metadata.
	 * @return array Key-part metadata with spatial sub-parts.
	 */
	private function apply_mysql_spatial_index_sub_parts( array $key_parts ): array {
		foreach ( $key_parts as $position => $key_part ) {
			if ( null === $key_part['sub_part'] ) {
				$key_parts[ $position ]['sub_part'] = 32;
			}
		}

		return $key_parts;
	}

	/**
	 * Consume a supported MySQL CREATE INDEX USING clause.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current token position, updated on success.
	 * @return bool Whether the optional index type is supported.
	 */
	private function consume_mysql_supported_create_index_type( array $tokens, int &$position ): bool {
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::USING_SYMBOL !== $tokens[ $position ]->id ) {
			return true;
		}

		if ( ! isset( $tokens[ $position + 1 ] ) || ! $this->is_mysql_token_value( $tokens[ $position + 1 ], 'btree' ) ) {
			return false;
		}

		$position += 2;
		return true;
	}

	/**
	 * Parse standalone CREATE INDEX key parts.
	 *
	 * @param WP_MySQL_Token[] $tokens    MySQL lexer token stream.
	 * @param int              $start     First key-part token position.
	 * @param int              $end       Final key-part token position, exclusive.
	 * @param bool             $is_unique Whether the index is unique.
	 * @return array{sql: string[], metadata: array[]}|null Key part SQL and metadata, or null when unsupported.
	 */
	private function parse_mysql_create_index_key_parts( array $tokens, int $start, int $end, bool $is_unique ): ?array {
		$key_part_ranges = $this->split_top_level_mysql_arguments( $tokens, $start, $end );
		if ( null === $key_part_ranges || array() === $key_part_ranges ) {
			return null;
		}

		$sql_parts      = array();
		$metadata_parts = array();
		foreach ( $key_part_ranges as $key_part_range ) {
			$position    = $key_part_range['start'];
			$column_name = $this->get_mysql_index_identifier_token_value( $tokens[ $position ] ?? null, true );
			if ( null === $column_name ) {
				return null;
			}

			++$position;
			$sub_part = null;
			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
				if (
					! isset( $tokens[ $position + 1 ], $tokens[ $position + 2 ] )
					|| ! $this->is_mysql_unsigned_integer_token( $tokens[ $position + 1 ] )
					|| WP_MySQL_Lexer::CLOSE_PAR_SYMBOL !== $tokens[ $position + 2 ]->id
				) {
					return null;
				}

				$sub_part  = $tokens[ $position + 1 ]->get_value();
				$position += 3;
			}

			$direction = '';
			if (
				isset( $tokens[ $position ] )
				&& (
					WP_MySQL_Lexer::ASC_SYMBOL === $tokens[ $position ]->id
					|| WP_MySQL_Lexer::DESC_SYMBOL === $tokens[ $position ]->id
				)
			) {
				$direction = ' ' . strtoupper( $tokens[ $position ]->get_value() );
				++$position;
			}

			if ( $position !== $key_part_range['end'] ) {
				return null;
			}

			$sql_parts[]      = $this->get_mysql_index_key_part_sql( $column_name, $is_unique ? $sub_part : null ) . $direction;
			$metadata_parts[] = array(
				'column_name'  => $column_name,
				'seq_in_index' => count( $metadata_parts ) + 1,
				'collation'    => ' DESC' === $direction ? 'D' : 'A',
				'sub_part'     => $sub_part,
			);
		}

		return array(
			'sql'      => $sql_parts,
			'metadata' => $metadata_parts,
		);
	}

	/**
	 * Get a column identifier token value from a CREATE INDEX key part.
	 *
	 * MySQL permits some unquoted keyword-like names, such as "value" and
	 * "name", in key parts. Keep this fallback local to index column parsing so
	 * statement structure keywords are still handled explicitly by the parser.
	 *
	 * @param WP_MySQL_Token|null $token               MySQL token.
	 * @param bool                $allow_double_quoted Whether to accept double-quoted text as an identifier.
	 * @return string|null Identifier value, or null when unsupported.
	 */
	private function get_mysql_index_identifier_token_value( ?WP_MySQL_Token $token, bool $allow_double_quoted = false ): ?string {
		$identifier = $this->get_mysql_identifier_token_value( $token, $allow_double_quoted );
		if ( null !== $identifier ) {
			return $identifier;
		}

		if ( null === $token ) {
			return null;
		}

		if (
			in_array(
				$token->id,
				array(
					WP_MySQL_Lexer::ASC_SYMBOL,
					WP_MySQL_Lexer::COMMENT_SYMBOL,
					WP_MySQL_Lexer::DESC_SYMBOL,
					WP_MySQL_Lexer::INDEX_SYMBOL,
					WP_MySQL_Lexer::ON_SYMBOL,
					WP_MySQL_Lexer::USING_SYMBOL,
				),
				true
			)
		) {
			return null;
		}

		$value = $token->get_value();
		if ( 1 === preg_match( '/^[A-Za-z_][A-Za-z0-9_]*$/', $value ) ) {
			return $value;
		}

		return null;
	}

	/**
	 * Get PostgreSQL SQL for a MySQL index key part.
	 *
	 * @param string          $column_name Column name.
	 * @param int|string|null $sub_part    Optional prefix length.
	 * @return string PostgreSQL key-part SQL.
	 */
	private function get_mysql_index_key_part_sql( string $column_name, $sub_part ): string {
		if ( null !== $sub_part && '' !== (string) $sub_part ) {
			return sprintf(
				'SUBSTR(CAST(%s AS text), 1, %d)',
				$this->connection->quote_identifier( $column_name ),
				(int) $sub_part
			);
		}

		return $this->connection->quote_identifier( $column_name );
	}

	/**
	 * Consume supported MySQL CREATE INDEX options.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $position      Current token position, updated on success.
	 * @param int              $statement_end Final statement token position, exclusive.
	 * @param string           $index_type    MySQL index type.
	 * @param string           $index_comment Index comment, updated on success.
	 * @return bool Whether all remaining options are supported.
	 */
	private function consume_mysql_supported_create_index_options( array $tokens, int &$position, int $statement_end, string $index_type, string &$index_comment ): bool {
		$allow_btree_options = ! $this->is_mysql_metadata_only_index_type( $index_type );
		if ( ! $allow_btree_options ) {
			return $position === $statement_end;
		}

		while ( $position < $statement_end ) {
			if (
				isset( $tokens[ $position ], $tokens[ $position + 1 ] )
				&& WP_MySQL_Lexer::COMMENT_SYMBOL === $tokens[ $position ]->id
				&& $this->is_mysql_quoted_text_token( $tokens[ $position + 1 ] )
			) {
				$index_comment = $tokens[ $position + 1 ]->get_value();
				$position     += 2;
				continue;
			}

			$before_type_position = $position;
			if ( ! $this->consume_mysql_supported_create_index_type( $tokens, $position ) ) {
				return false;
			}
			if ( $position !== $before_type_position ) {
				continue;
			}

			if (
				isset( $tokens[ $position ] )
				&& (
					WP_MySQL_Lexer::VISIBLE_SYMBOL === $tokens[ $position ]->id
					|| WP_MySQL_Lexer::INVISIBLE_SYMBOL === $tokens[ $position ]->id
				)
			) {
				++$position;
				continue;
			}

			if ( $this->consume_mysql_supported_index_key_block_size_option( $tokens, $position, $statement_end ) ) {
				continue;
			}

			if ( $this->consume_mysql_supported_index_lock_and_algorithm_options( $tokens, $position, $statement_end ) ) {
				continue;
			}

			return false;
		}

		return true;
	}

	/**
	 * Consume a supported MySQL index KEY_BLOCK_SIZE option.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $position      Current token position, updated on success.
	 * @param int              $statement_end Final statement token position, exclusive.
	 * @return bool Whether a supported KEY_BLOCK_SIZE option was consumed.
	 */
	private function consume_mysql_supported_index_key_block_size_option( array $tokens, int &$position, int $statement_end ): bool {
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::KEY_BLOCK_SIZE_SYMBOL !== $tokens[ $position ]->id ) {
			return false;
		}

		$next_position = $position + 1;
		if ( isset( $tokens[ $next_position ] ) && WP_MySQL_Lexer::EQUAL_OPERATOR === $tokens[ $next_position ]->id ) {
			++$next_position;
		}

		if ( $next_position >= $statement_end || ! isset( $tokens[ $next_position ] ) || ! $this->is_mysql_unsigned_integer_token( $tokens[ $next_position ] ) ) {
			return false;
		}

		$position = $next_position + 1;
		return true;
	}

	/**
	 * Consume supported MySQL index ALGORITHM and LOCK options.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $position      Current token position, updated on success.
	 * @param int              $statement_end Final statement token position, exclusive.
	 * @return bool Whether a supported option was consumed.
	 */
	private function consume_mysql_supported_index_lock_and_algorithm_options( array $tokens, int &$position, int $statement_end ): bool {
		if ( ! isset( $tokens[ $position ] ) ) {
			return false;
		}

		if ( WP_MySQL_Lexer::ALGORITHM_SYMBOL === $tokens[ $position ]->id ) {
			return $this->consume_mysql_supported_index_option_value(
				$tokens,
				$position,
				$statement_end,
				array( 'default', 'inplace', 'copy' )
			);
		}

		if ( WP_MySQL_Lexer::LOCK_SYMBOL === $tokens[ $position ]->id ) {
			return $this->consume_mysql_supported_index_option_value(
				$tokens,
				$position,
				$statement_end,
				array( 'default', 'none', 'shared', 'exclusive' )
			);
		}

		return false;
	}

	/**
	 * Consume a MySQL index option with an optional equals sign and a bounded value.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int              $position         Current token position, updated on success.
	 * @param int              $statement_end    Final statement token position, exclusive.
	 * @param string[]         $supported_values Supported option values.
	 * @return bool Whether a supported option value was consumed.
	 */
	private function consume_mysql_supported_index_option_value( array $tokens, int &$position, int $statement_end, array $supported_values ): bool {
		$value_position = $position + 1;
		if ( isset( $tokens[ $value_position ] ) && WP_MySQL_Lexer::EQUAL_OPERATOR === $tokens[ $value_position ]->id ) {
			++$value_position;
		}

		if ( $value_position >= $statement_end || ! isset( $tokens[ $value_position ] ) ) {
			return false;
		}

		foreach ( $supported_values as $supported_value ) {
			if ( $this->is_mysql_token_value( $tokens[ $value_position ], $supported_value ) ) {
				$position = $value_position + 1;
				return true;
			}
		}

		return false;
	}

	/**
	 * Resolve the backend schema for a writable MySQL table reference.
	 *
	 * @param array  $table_reference Parsed table reference.
	 * @param string $statement_type  Statement type for error messages.
	 * @return string Backend schema name.
	 */
	private function get_mysql_writable_table_backend_schema( array $table_reference, string $statement_type ): string {
		$requested_schema = $table_reference['schema'];
		$table_name       = $table_reference['table'];

		if ( null === $requested_schema ) {
			if ( 0 === strcasecmp( $this->db_name, 'information_schema' ) ) {
				throw new InvalidArgumentException( 'Unsupported information_schema query.' );
			}

			return $this->resolve_mysql_table_schema_for_introspection( 'public', $table_name );
		}

		if ( 0 === strcasecmp( $requested_schema, 'information_schema' ) ) {
			throw new InvalidArgumentException( 'Unsupported information_schema query.' );
		}

		if (
			0 === strcasecmp( $requested_schema, $this->main_db_name )
			|| 0 === strcasecmp( $requested_schema, 'public' )
		) {
			return 'public';
		}

		throw new InvalidArgumentException( sprintf( 'Unsupported %s statement.', $statement_type ) );
	}

	/**
	 * Resolve the backend schema for a read-only MySQL table reference.
	 *
	 * @param string|null $requested_schema Requested MySQL-facing schema, or null for the current database.
	 * @return string Backend schema name.
	 */
	private function get_mysql_read_table_backend_schema( ?string $requested_schema ): string {
		if ( null === $requested_schema ) {
			return 0 === strcasecmp( $this->db_name, 'information_schema' ) ? 'information_schema' : 'public';
		}

		if (
			0 === strcasecmp( $requested_schema, $this->main_db_name )
			|| 0 === strcasecmp( $requested_schema, 'public' )
		) {
			return 'public';
		}

		if ( 0 === strcasecmp( $requested_schema, 'information_schema' ) ) {
			return 'information_schema';
		}

		return $requested_schema;
	}

	/**
	 * Build a backend identifier in a specific schema when the test backend supports it.
	 *
	 * @param string $schema_name Backend schema name.
	 * @param string $object_name Object name.
	 * @return string Backend SQL identifier.
	 */
	private function get_postgresql_schema_identifier( string $schema_name, string $object_name ): string {
		$driver_name = (string) $this->connection->get_pdo()->getAttribute( PDO::ATTR_DRIVER_NAME );
		if (
			'sqlite' === $driver_name
			&& (
				'main' === $schema_name
				|| ( 'public' === $schema_name && ! $this->sqlite_database_schema_exists( 'public' ) )
			)
		) {
			return $this->connection->quote_identifier( $object_name );
		}

		return $this->connection->quote_identifier( $schema_name ) . '.' . $this->connection->quote_identifier( $object_name );
	}

	/**
	 * Translate supported dbDelta ALTER TABLE statements to PostgreSQL.
	 *
	 * @param string $query MySQL ALTER TABLE query.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_alter_table_query( string $query ): ?array {
		$query_tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $query_tokens[0], $query_tokens[1] )
			|| WP_MySQL_Lexer::ALTER_SYMBOL !== $query_tokens[0]->id
			|| WP_MySQL_Lexer::TABLE_SYMBOL !== $query_tokens[1]->id
		) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $query_tokens, 2 );
		if ( null === $statement_end ) {
			throw new InvalidArgumentException( 'Unsupported ALTER TABLE statement.' );
		}

		$position        = 2;
		$table_reference = $this->get_mysql_dbdelta_alter_table_target_reference( $query_tokens, $position );
		if ( null === $table_reference || $position >= $statement_end ) {
			throw new InvalidArgumentException( 'Unsupported ALTER TABLE statement.' );
		}

		$table_name = $table_reference['table'];
		$clause     = $this->trim_mysql_statement_fragment(
			$this->get_mysql_token_range_bytes( $query, $query_tokens, $position, $statement_end )
		);

		$tokens        = $this->get_mysql_tokens( $clause );
		$statement_end = $this->get_mysql_statement_end_position( $tokens, 0 );
		if ( null === $statement_end ) {
			return null;
		}

		$ranges = $this->split_top_level_mysql_arguments( $tokens, 0, $statement_end );
		if ( null === $ranges || array() === $ranges ) {
			return null;
		}

		if ( $this->contains_unsupported_mysql_column_attribute_alter_actions( $tokens, $ranges ) ) {
			throw new InvalidArgumentException( 'Unsupported ALTER TABLE statement.' );
		}

		$table_schema = $this->get_mysql_writable_table_backend_schema( $table_reference, 'ALTER TABLE' );

		$statements              = array();
		$metadata_operations     = array();
		$has_online_ddl_options  = false;
		$check_names             = array();
		$foreign_key_names       = array();
		foreach ( $ranges as $range ) {
			$translation = $this->translate_mysql_dbdelta_alter_table_action(
				$table_schema,
				$table_name,
				$clause,
				$tokens,
				$range['start'],
				$range['end'],
				$check_names,
				$foreign_key_names
			);
			if ( null === $translation ) {
				return null;
			}

			$statements = array_merge( $statements, $translation['statements'] );
			if ( 'noop' === ( $translation['metadata']['operation'] ?? '' ) && 'online_ddl_option' === ( $translation['metadata']['option'] ?? '' ) ) {
				$has_online_ddl_options = true;
			}
			if ( 'noop' !== ( $translation['metadata']['operation'] ?? '' ) ) {
				$metadata_operations[] = $translation['metadata'];
			}
		}

		if ( $has_online_ddl_options && $this->has_mysql_dbdelta_metadata_only_index_operation( $metadata_operations ) ) {
			throw new InvalidArgumentException( 'Unsupported ALTER TABLE statement.' );
		}

		$this->preflight_mysql_dbdelta_alter_table_metadata_operations( $table_schema, $table_name, $metadata_operations );

		if ( 1 === count( $metadata_operations ) ) {
			$metadata          = $metadata_operations[0];
			$metadata['schema'] = $table_schema;
			$metadata['table'] = $table_name;
		} elseif ( count( $metadata_operations ) > 1 ) {
			$metadata = array(
				'operation'  => 'operations',
				'schema'     => $table_schema,
				'table'      => $table_name,
				'operations' => $metadata_operations,
			);
		} else {
			$metadata = array(
				'operation' => 'noop',
				'schema'    => $table_schema,
				'table'     => $table_name,
			);
		}

		return array(
			'statements' => $statements,
			'metadata'   => $metadata,
		);
	}

	/**
	 * Validate ALTER TABLE metadata operations before backend DDL executes.
	 *
	 * @param string  $table_schema        Backend schema name.
	 * @param string  $table_name          Table name.
	 * @param array[] $metadata_operations ALTER metadata operations.
	 */
	private function preflight_mysql_dbdelta_alter_table_metadata_operations( string $table_schema, string $table_name, array $metadata_operations ): void {
		$metadata_operations = $this->flatten_mysql_dbdelta_alter_table_metadata_operations( $metadata_operations );
		$added_columns = array();
		$added_indexes = array();

		foreach ( $metadata_operations as $metadata ) {
			if ( 'add_column' === ( $metadata['operation'] ?? '' ) ) {
				$column_name = (string) ( $metadata['column']['name'] ?? '' );
				if ( '' !== $column_name ) {
					$column_key = strtolower( $column_name );
					if (
						isset( $added_columns[ $column_key ] )
						|| $this->mysql_table_has_column_for_translation( $table_schema, $table_name, $column_name )
					) {
						throw new InvalidArgumentException( sprintf( "Duplicate column name '%s'.", $column_name ) );
					}
					$added_columns[ $column_key ] = true;
				}

				foreach ( $metadata['indexes'] ?? array() as $index ) {
					$this->preflight_mysql_dbdelta_alter_table_add_index_metadata( $table_schema, $table_name, $index, $added_indexes );
				}
				continue;
			}

			if ( 'add_index' === ( $metadata['operation'] ?? '' ) ) {
				$this->preflight_mysql_dbdelta_alter_table_add_index_metadata( $table_schema, $table_name, $metadata['index'] ?? array(), $added_indexes );
			}
		}
	}

	/**
	 * Check whether ALTER TABLE metadata operations contain FULLTEXT/SPATIAL indexes.
	 *
	 * @param array[] $metadata_operations ALTER metadata operations.
	 * @return bool Whether any operation targets a metadata-only index type.
	 */
	private function has_mysql_dbdelta_metadata_only_index_operation( array $metadata_operations ): bool {
		foreach ( $this->flatten_mysql_dbdelta_alter_table_metadata_operations( $metadata_operations ) as $metadata ) {
			if (
				'add_index' === ( $metadata['operation'] ?? '' )
				&& $this->is_mysql_metadata_only_index_type( (string) ( $metadata['index']['index_type'] ?? '' ) )
			) {
				return true;
			}

			if ( 'add_column' !== ( $metadata['operation'] ?? '' ) ) {
				continue;
			}

			foreach ( $metadata['indexes'] ?? array() as $index ) {
				if ( $this->is_mysql_metadata_only_index_type( (string) ( $index['index_type'] ?? '' ) ) ) {
					return true;
				}
			}
		}

		return false;
	}

	/**
	 * Flatten nested ALTER TABLE metadata operations for validation.
	 *
	 * @param array[] $metadata_operations ALTER metadata operations.
	 * @return array[] Flat operation list.
	 */
	private function flatten_mysql_dbdelta_alter_table_metadata_operations( array $metadata_operations ): array {
		$flat_operations = array();
		foreach ( $metadata_operations as $metadata ) {
			if ( 'operations' === ( $metadata['operation'] ?? '' ) ) {
				$flat_operations = array_merge(
					$flat_operations,
					$this->flatten_mysql_dbdelta_alter_table_metadata_operations( $metadata['operations'] ?? array() )
				);
				continue;
			}

			$flat_operations[] = $metadata;
		}

		return $flat_operations;
	}

	/**
	 * Validate one ALTER TABLE ADD INDEX metadata operation.
	 *
	 * @param string $table_schema  Backend schema name.
	 * @param string $table_name    Table name.
	 * @param array  $index         Index metadata.
	 * @param array  $added_indexes Index names already added by this ALTER statement.
	 */
	private function preflight_mysql_dbdelta_alter_table_add_index_metadata( string $table_schema, string $table_name, array $index, array &$added_indexes ): void {
		$index_name = (string) ( $index['name'] ?? '' );
		if ( '' === $index_name ) {
			return;
		}

		$index_key = strtolower( $index_name );
		if (
			isset( $added_indexes[ $index_key ] )
			|| $this->mysql_index_metadata_exists( $table_schema, $table_name, $index_name )
		) {
			throw new InvalidArgumentException( sprintf( "Duplicate key name '%s'.", $index_name ) );
		}

		$added_indexes[ $index_key ] = true;
	}

	/**
	 * Parse an ALTER TABLE target reference.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current token position, updated on success.
	 * @return array{schema: string|null, table: string}|null Parsed table reference, or null when unsupported.
	 */
	private function get_mysql_dbdelta_alter_table_target_reference( array $tokens, int &$position ): ?array {
		$first_identifier = $this->get_mysql_alter_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $first_identifier ) {
			return null;
		}

		++$position;
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::DOT_SYMBOL !== $tokens[ $position ]->id ) {
			return array(
				'schema' => null,
				'table'  => $first_identifier,
			);
		}

		$table_name = $this->get_mysql_alter_identifier_token_value( $tokens[ $position + 1 ] ?? null );
		if ( null === $table_name ) {
			return null;
		}

		$position += 2;
		return array(
			'schema' => $first_identifier,
			'table'  => $table_name,
		);
	}

	/**
	 * Resolve an ALTER TABLE target to the supported backend table name.
	 *
	 * @param array{schema: string|null, table: string} $table_reference Parsed table reference.
	 * @return string Table name.
	 */
	private function get_mysql_dbdelta_alter_table_target_name( array $table_reference ): string {
		$this->get_mysql_writable_table_backend_schema( $table_reference, 'ALTER TABLE' );
		return $table_reference['table'];
	}

	/**
	 * Check whether ALTER actions contain unsupported MySQL column attributes.
	 *
	 * @param WP_MySQL_Token[]                 $tokens Clause token stream.
	 * @param array<int,array{start:int,end:int}> $ranges Top-level action ranges.
	 * @return bool Whether an unsupported column attribute is present.
	 */
	private function contains_unsupported_mysql_column_attribute_alter_actions( array $tokens, array $ranges ): bool {
		foreach ( $ranges as $range ) {
			if ( $this->contains_unsupported_mysql_column_attribute_alter_action( $tokens, $range['start'], $range['end'] ) ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Check whether one ALTER action contains unsupported MySQL column attributes.
	 *
	 * @param WP_MySQL_Token[] $tokens Clause token stream.
	 * @param int              $start  First action token.
	 * @param int              $end    Final action token, exclusive.
	 * @return bool Whether an unsupported column attribute is present.
	 */
	private function contains_unsupported_mysql_column_attribute_alter_action( array $tokens, int $start, int $end ): bool {
		if ( $start >= $end || ! isset( $tokens[ $start ] ) ) {
			return false;
		}

		if ( WP_MySQL_Lexer::ADD_SYMBOL === $tokens[ $start ]->id ) {
			if (
				$this->is_mysql_dbdelta_add_index_action( $tokens, $start, $end )
				|| $this->is_mysql_dbdelta_add_constraint_action( $tokens, $start, $end )
			) {
				return false;
			}

			$position = $start + 1;
			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COLUMN_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
			}

			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
				$parenthesized_end = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
				if ( $parenthesized_end !== $end ) {
					return false;
				}

				$ranges = $this->split_top_level_mysql_arguments( $tokens, $position + 1, $end - 1 );
				if ( null === $ranges ) {
					return false;
				}

				foreach ( $ranges as $range ) {
					if (
						! $this->is_mysql_dbdelta_add_index_definition_action( $tokens, $range['start'], $range['end'] )
						&& ! $this->is_mysql_dbdelta_add_constraint_definition_action( $tokens, $range['start'], $range['end'] )
						&& $this->contains_unsupported_mysql_column_attribute_definition_tokens( $tokens, $range['start'], $range['end'] )
					) {
						return true;
					}
				}

				return false;
			}

			return $this->contains_unsupported_mysql_column_attribute_definition_tokens( $tokens, $position, $end );
		}

		if ( WP_MySQL_Lexer::MODIFY_SYMBOL === $tokens[ $start ]->id ) {
			$position = $start + 1;
			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COLUMN_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
			}

			return $this->contains_unsupported_mysql_column_attribute_definition_tokens( $tokens, $position, $end );
		}

		if ( WP_MySQL_Lexer::CHANGE_SYMBOL === $tokens[ $start ]->id ) {
			$position = $start + 1;
			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COLUMN_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
			}
			if ( null === $this->get_mysql_alter_identifier_token_value( $tokens[ $position ] ?? null ) ) {
				return false;
			}
			++$position;
			if ( null === $this->get_mysql_alter_identifier_token_value( $tokens[ $position ] ?? null ) ) {
				return false;
			}
			++$position;

			return $this->contains_unsupported_mysql_column_attribute_tokens( $tokens, $position, $end );
		}

		return false;
	}

	/**
	 * Check whether a column definition range contains unsupported MySQL attributes.
	 *
	 * @param WP_MySQL_Token[] $tokens Clause token stream.
	 * @param int              $start  First definition token.
	 * @param int              $end    Final definition token, exclusive.
	 * @return bool Whether an unsupported column attribute is present.
	 */
	private function contains_unsupported_mysql_column_attribute_definition_tokens( array $tokens, int $start, int $end ): bool {
		if ( $start >= $end ) {
			return false;
		}

		return $this->contains_unsupported_mysql_column_attribute_tokens( $tokens, $start + 1, $end );
	}

	/**
	 * Check whether a token range contains unsupported MySQL column attributes.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token position.
	 * @param int              $end    Final token position, exclusive.
	 * @return bool Whether an unsupported column attribute token is present.
	 */
	private function contains_unsupported_mysql_column_attribute_tokens( array $tokens, int $start, int $end ): bool {
		for ( $i = $start; $i < $end; $i++ ) {
			if (
				isset( $tokens[ $i ] )
				&& in_array(
					$tokens[ $i ]->id,
					array(
						WP_MySQL_Lexer::GENERATED_SYMBOL,
						WP_MySQL_Lexer::COLUMN_FORMAT_SYMBOL,
						WP_MySQL_Lexer::STORAGE_SYMBOL,
						WP_MySQL_Lexer::VISIBLE_SYMBOL,
						WP_MySQL_Lexer::INVISIBLE_SYMBOL,
					),
					true
				)
			) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Translate one ALTER TABLE action.
	 *
	 * @param string           $table_schema Backend schema name.
	 * @param string           $table_name Table name.
	 * @param string           $clause     Full ALTER clause string.
	 * @param WP_MySQL_Token[] $tokens     Clause token stream.
	 * @param int              $start      First action token.
	 * @param int              $end        Final action token, exclusive.
	 * @param string[]         $check_names CHECK names generated for this ALTER TABLE statement.
	 * @param string[]         $foreign_key_names Foreign key names generated for this ALTER TABLE statement.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_alter_table_action( string $table_schema, string $table_name, string $clause, array $tokens, int $start, int $end, array &$check_names, array &$foreign_key_names ): ?array {
		if ( $start >= $end || ! isset( $tokens[ $start ] ) ) {
			return null;
		}

		switch ( $tokens[ $start ]->id ) {
			case WP_MySQL_Lexer::CHANGE_SYMBOL:
				return $this->translate_mysql_dbdelta_change_column_alter_action( $table_name, $clause, $tokens, $start, $end );

			case WP_MySQL_Lexer::MODIFY_SYMBOL:
				return $this->translate_mysql_dbdelta_modify_column_alter_action( $table_name, $clause, $tokens, $start, $end );

			case WP_MySQL_Lexer::ADD_SYMBOL:
				if ( $this->is_mysql_dbdelta_add_constraint_action( $tokens, $start, $end ) ) {
					return $this->translate_mysql_dbdelta_add_constraint_alter_action( $table_schema, $table_name, $clause, $tokens, $start, $end, $check_names, $foreign_key_names );
				}
				if ( $this->is_mysql_dbdelta_add_index_action( $tokens, $start, $end ) ) {
					return $this->translate_mysql_dbdelta_add_index_alter_action( $table_name, $clause, $tokens, $start, $end );
				}
				return $this->translate_mysql_dbdelta_add_column_alter_action( $table_schema, $table_name, $clause, $tokens, $start, $end, $check_names, $foreign_key_names );

			case WP_MySQL_Lexer::DROP_SYMBOL:
				if (
					isset( $tokens[ $start + 2 ] )
					&& WP_MySQL_Lexer::PRIMARY_SYMBOL === $tokens[ $start + 1 ]->id
					&& WP_MySQL_Lexer::KEY_SYMBOL === $tokens[ $start + 2 ]->id
					&& $start + 3 === $end
				) {
					return $this->translate_mysql_dbdelta_drop_primary_key_alter_action( $table_name );
				}
				if (
					isset( $tokens[ $start + 2 ] )
					&& in_array( $tokens[ $start + 1 ]->id, array( WP_MySQL_Lexer::INDEX_SYMBOL, WP_MySQL_Lexer::KEY_SYMBOL ), true )
					&& 'PRIMARY' === strtoupper( (string) $this->get_mysql_alter_identifier_token_value( $tokens[ $start + 2 ] ?? null ) )
					&& $start + 3 === $end
				) {
					return $this->translate_mysql_dbdelta_drop_primary_key_alter_action( $table_name );
				}
				if (
					isset( $tokens[ $start + 2 ] )
					&& WP_MySQL_Lexer::CONSTRAINT_SYMBOL === $tokens[ $start + 1 ]->id
					&& $start + 3 === $end
				) {
					return $this->translate_mysql_dbdelta_drop_constraint_alter_action( $table_name, $tokens, $start, $end );
				}
				if (
						isset( $tokens[ $start + 2 ] )
						&& WP_MySQL_Lexer::CHECK_SYMBOL === $tokens[ $start + 1 ]->id
						&& $start + 3 === $end
					) {
					return $this->translate_mysql_dbdelta_drop_check_alter_action( $table_name, $tokens, $start, $end );
				}
				if ( $this->is_mysql_dbdelta_drop_foreign_key_action( $tokens, $start, $end ) ) {
					return $this->translate_mysql_dbdelta_drop_foreign_key_alter_action( $table_name, $tokens, $start, $end );
				}
				if ( isset( $tokens[ $start + 1 ] ) && in_array( $tokens[ $start + 1 ]->id, array( WP_MySQL_Lexer::INDEX_SYMBOL, WP_MySQL_Lexer::KEY_SYMBOL ), true ) ) {
					return $this->translate_mysql_dbdelta_drop_index_alter_action( $table_name, $tokens, $start, $end );
				}
				return $this->translate_mysql_dbdelta_drop_column_alter_action( $table_name, $tokens, $start, $end );

			case WP_MySQL_Lexer::ALTER_SYMBOL:
				return $this->translate_mysql_dbdelta_alter_column_default_action( $table_name, $clause, $tokens, $start, $end );

			case WP_MySQL_Lexer::RENAME_SYMBOL:
				$table_rename = $this->translate_mysql_dbdelta_rename_table_alter_action( $table_schema, $table_name, $tokens, $start, $end );
				if ( null !== $table_rename ) {
					return $table_rename;
				}
				if ( isset( $tokens[ $start + 1 ] ) && WP_MySQL_Lexer::COLUMN_SYMBOL === $tokens[ $start + 1 ]->id ) {
					return $this->translate_mysql_dbdelta_rename_column_alter_action( $table_name, $tokens, $start, $end );
				}
				if ( isset( $tokens[ $start + 1 ] ) && in_array( $tokens[ $start + 1 ]->id, array( WP_MySQL_Lexer::INDEX_SYMBOL, WP_MySQL_Lexer::KEY_SYMBOL ), true ) ) {
					return $this->translate_mysql_dbdelta_rename_index_alter_action( $table_name, $tokens, $start, $end );
				}
				return null;
		}

		$auto_increment_value = $this->get_mysql_dbdelta_auto_increment_alter_value( $tokens, $start, $end );
		if ( null !== $auto_increment_value ) {
			return $this->translate_mysql_dbdelta_auto_increment_alter_action( $table_name, $auto_increment_value );
		}

		if ( $this->is_supported_mysql_dbdelta_keys_alter_action( $tokens, $start, $end ) ) {
			return array(
				'statements' => array(),
				'metadata'   => array(
					'operation' => 'noop',
				),
			);
		}

		if ( $this->is_supported_mysql_dbdelta_online_ddl_option_alter_action( $tokens, $start, $end ) ) {
			return array(
				'statements' => array(),
				'metadata'   => array(
					'operation' => 'noop',
					'option'    => 'online_ddl_option',
				),
			);
		}

		if ( $this->is_supported_mysql_dbdelta_table_option_alter_action( $clause, $tokens, $start, $end ) ) {
			return array(
				'statements' => array(),
				'metadata'   => array(
					'operation' => 'noop',
				),
			);
		}

		return null;
	}

	/**
	 * Translate an ALTER TABLE RENAME [TO|AS] table action.
	 *
	 * @param string           $table_schema Backend schema name.
	 * @param string           $table_name   Table name.
	 * @param WP_MySQL_Token[] $tokens       Clause token stream.
	 * @param int              $start        First action token.
	 * @param int              $end          Final action token, exclusive.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_rename_table_alter_action( string $table_schema, string $table_name, array $tokens, int $start, int $end ): ?array {
		$new_table_position = $start + 1;
		if (
			isset( $tokens[ $new_table_position ] )
			&& in_array( $tokens[ $new_table_position ]->id, array( WP_MySQL_Lexer::TO_SYMBOL, WP_MySQL_Lexer::AS_SYMBOL ), true )
		) {
			++$new_table_position;
		}

		if ( $new_table_position + 1 !== $end ) {
			return null;
		}

		$new_table_name = $this->get_mysql_table_reference_identifier_token_value( $tokens[ $new_table_position ] ?? null, true );
		if ( null === $new_table_name ) {
			return null;
		}

		return array(
			'statements' => $this->get_mysql_rename_table_statements( $table_schema, $table_name, $new_table_name ),
			'metadata'   => array(
				'operation' => 'rename_table',
				'new_table' => $new_table_name,
			),
		);
	}

	/**
	 * Translate an ALTER TABLE RENAME COLUMN action.
	 *
	 * @param string           $table_name Table name.
	 * @param WP_MySQL_Token[] $tokens     Clause token stream.
	 * @param int              $start      First action token.
	 * @param int              $end        Final action token, exclusive.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_rename_column_alter_action( string $table_name, array $tokens, int $start, int $end ): ?array {
		if (
			! isset( $tokens[ $start + 4 ] )
			|| WP_MySQL_Lexer::COLUMN_SYMBOL !== $tokens[ $start + 1 ]->id
			|| WP_MySQL_Lexer::TO_SYMBOL !== $tokens[ $start + 3 ]->id
			|| $start + 5 !== $end
		) {
			return null;
		}

		$old_column_name = $this->get_mysql_alter_identifier_token_value( $tokens[ $start + 2 ] ?? null );
		$new_column_name = $this->get_mysql_alter_identifier_token_value( $tokens[ $start + 4 ] ?? null );
		if ( null === $old_column_name || null === $new_column_name ) {
			return null;
		}

		return array(
			'statements' => array(
				sprintf(
					'ALTER TABLE %s RENAME COLUMN %s TO %s',
					$this->connection->quote_identifier( $table_name ),
					$this->connection->quote_identifier( $old_column_name ),
					$this->connection->quote_identifier( $new_column_name )
				),
			),
			'metadata'   => array(
				'operation'  => 'rename_column',
				'old_column' => $old_column_name,
				'new_column' => $new_column_name,
			),
		);
	}

	/**
	 * Translate an ALTER TABLE RENAME INDEX/KEY action.
	 *
	 * @param string           $table_name Table name.
	 * @param WP_MySQL_Token[] $tokens     Clause token stream.
	 * @param int              $start      First action token.
	 * @param int              $end        Final action token, exclusive.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_rename_index_alter_action( string $table_name, array $tokens, int $start, int $end ): ?array {
		if (
			! isset( $tokens[ $start + 4 ] )
			|| ! in_array( $tokens[ $start + 1 ]->id, array( WP_MySQL_Lexer::INDEX_SYMBOL, WP_MySQL_Lexer::KEY_SYMBOL ), true )
			|| WP_MySQL_Lexer::TO_SYMBOL !== $tokens[ $start + 3 ]->id
			|| $start + 5 !== $end
		) {
			return null;
		}

		$old_index_name = $this->get_mysql_alter_identifier_token_value( $tokens[ $start + 2 ] ?? null );
		$new_index_name = $this->get_mysql_alter_identifier_token_value( $tokens[ $start + 4 ] ?? null );
		if (
			null === $old_index_name
			|| null === $new_index_name
			|| 'PRIMARY' === strtoupper( $old_index_name )
			|| 'PRIMARY' === strtoupper( $new_index_name )
		) {
			return null;
		}

		$table_reference = array(
			'schema' => null,
			'table'  => $table_name,
		);
		$table_schema    = $this->get_mysql_writable_table_backend_schema( $table_reference, 'ALTER TABLE' );

		if ( $this->mysql_index_metadata_has_rows( $table_schema, $table_name ) ) {
			if (
				! $this->mysql_index_metadata_exists( $table_schema, $table_name, $old_index_name )
				|| $this->mysql_index_metadata_exists( $table_schema, $table_name, $new_index_name )
			) {
				return null;
			}
		}

		$index_type = $this->get_stored_mysql_index_type( $table_schema, $table_name, $old_index_name );

		$statements = array();
		if ( null === $index_type || ! $this->is_mysql_metadata_only_index_type( $index_type ) ) {
			$statements[] = sprintf(
				'ALTER INDEX %s RENAME TO %s',
				$this->get_postgresql_schema_identifier( $table_schema, $table_name . '__' . $old_index_name ),
				$this->connection->quote_identifier( $table_name . '__' . $new_index_name )
			);
		}

		return array(
			'statements' => $statements,
			'metadata'   => array(
				'operation' => 'rename_index',
				'old_index' => $old_index_name,
				'new_index' => $new_index_name,
			),
		);
	}

	/**
	 * Parse an ALTER TABLE AUTO_INCREMENT = N table option.
	 *
	 * @param WP_MySQL_Token[] $tokens Clause token stream.
	 * @param int              $start  First action token.
	 * @param int              $end    Final action token, exclusive.
	 * @return int|null Requested next AUTO_INCREMENT value, or null when not this option.
	 */
	private function get_mysql_dbdelta_auto_increment_alter_value( array $tokens, int $start, int $end ): ?int {
		if ( ! isset( $tokens[ $start ] ) || WP_MySQL_Lexer::AUTO_INCREMENT_SYMBOL !== $tokens[ $start ]->id ) {
			return null;
		}

		$position = $start + 1;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::EQUAL_OPERATOR === $tokens[ $position ]->id ) {
			++$position;
		}

		if (
			$position + 1 !== $end
			|| ! isset( $tokens[ $position ] )
			|| ! in_array( $tokens[ $position ]->id, array( WP_MySQL_Lexer::INT_NUMBER, WP_MySQL_Lexer::LONG_NUMBER, WP_MySQL_Lexer::ULONGLONG_NUMBER ), true )
		) {
			return null;
		}

		$value = $tokens[ $position ]->get_value();
		if ( ! preg_match( '/^[0-9]+$/', $value ) ) {
			return null;
		}

		$value = (int) $value;
		return $value > 0 ? $value : null;
	}

	/**
	 * Translate ALTER TABLE AUTO_INCREMENT = N into backend sequence adjustment.
	 *
	 * @param string $table_name Target table name.
	 * @param int    $value      Requested next AUTO_INCREMENT value.
	 * @return array{statements: string[], metadata: array} Translation.
	 */
	private function translate_mysql_dbdelta_auto_increment_alter_action( string $table_name, int $value ): array {
		$metadata_lookup       = $this->get_mysql_dml_column_metadata_lookup( $table_name );
		$auto_increment_column = $this->get_mysql_auto_increment_column_from_metadata( $metadata_lookup );
		if ( null === $auto_increment_column ) {
			return array(
				'statements' => array(),
				'metadata'   => array(
					'operation' => 'noop',
				),
			);
		}

		$minimum_sequence_value = max( 0, $value - 1 );
		$statements             = array();
		$table_schema           = $this->resolve_mysql_table_schema_for_introspection( 'public', $table_name );

		$statements = $this->get_postgresql_auto_increment_alter_statements( $table_name, $auto_increment_column, $minimum_sequence_value );
		if ( empty( $statements ) && 'sqlite' === $this->connection->get_driver_name() ) {
			$statements = $this->get_sqlite_auto_increment_alter_statements( $table_schema, $table_name, $auto_increment_column, $minimum_sequence_value );
		}

		return array(
			'statements' => $statements,
			'metadata'   => array(
				'operation' => 'set_auto_increment',
			),
		);
	}

	/**
	 * Translate an ALTER TABLE CHANGE COLUMN action.
	 *
	 * @param string           $table_name Table name.
	 * @param string           $clause     Full ALTER clause string.
	 * @param WP_MySQL_Token[] $tokens     Clause token stream.
	 * @param int              $start      First action token.
	 * @param int              $end        Final action token, exclusive.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_change_column_alter_action( string $table_name, string $clause, array $tokens, int $start, int $end ): ?array {
		$position = $start + 1;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COLUMN_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		$old_column = $this->get_mysql_alter_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $old_column ) {
			return null;
		}

		++$position;
		$definition_end = $this->get_mysql_alter_column_definition_end_without_placement( $tokens, $position, $end );
		if ( null === $definition_end || $position >= $definition_end ) {
			return null;
		}

		try {
			$column = $this->translate_mysql_column_definition_fragment(
				$this->get_mysql_token_range_bytes( $clause, $tokens, $position, $definition_end )
			);
		} catch ( InvalidArgumentException $e ) {
			return null;
		}
		if ( null === $column ) {
			return null;
		}

		return array(
			'statements' => $this->get_mysql_dbdelta_change_column_statements( $table_name, $old_column, $column ),
			'metadata'   => array(
				'operation'  => 'change_column',
				'old_column' => $old_column,
				'column'     => $column['metadata'],
				'indexes'    => $column['indexes'],
			),
		);
	}

	/**
	 * Translate an ALTER TABLE MODIFY COLUMN action.
	 *
	 * @param string           $table_name Table name.
	 * @param string           $clause     Full ALTER clause string.
	 * @param WP_MySQL_Token[] $tokens     Clause token stream.
	 * @param int              $start      First action token.
	 * @param int              $end        Final action token, exclusive.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_modify_column_alter_action( string $table_name, string $clause, array $tokens, int $start, int $end ): ?array {
		$position = $start + 1;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COLUMN_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		$definition_end = $this->get_mysql_alter_column_definition_end_without_placement( $tokens, $position, $end );
		if ( null === $definition_end || $position >= $definition_end ) {
			return null;
		}

		try {
			$column = $this->translate_mysql_column_definition_fragment(
				$this->get_mysql_token_range_bytes( $clause, $tokens, $position, $definition_end )
			);
		} catch ( InvalidArgumentException $e ) {
			return null;
		}
		if ( null === $column ) {
			return null;
		}

		$column_name = $column['metadata']['name'];
		return array(
			'statements' => $this->get_mysql_dbdelta_change_column_statements( $table_name, $column_name, $column ),
			'metadata'   => array(
				'operation'  => 'change_column',
				'old_column' => $column_name,
				'column'     => $column['metadata'],
				'indexes'    => $column['indexes'],
			),
		);
	}

	/**
	 * Translate an ALTER TABLE ADD COLUMN action.
	 *
	 * @param string           $table_schema      Backend schema name.
	 * @param string           $table_name        Table name.
	 * @param string           $clause            Full ALTER clause string.
	 * @param WP_MySQL_Token[] $tokens            Clause token stream.
	 * @param int              $start             First action token.
	 * @param int              $end               Final action token, exclusive.
	 * @param string[]         $check_names       CHECK names generated for this ALTER TABLE statement.
	 * @param string[]         $foreign_key_names Foreign key names generated for this ALTER TABLE statement.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_add_column_alter_action( string $table_schema, string $table_name, string $clause, array $tokens, int $start, int $end, array &$check_names, array &$foreign_key_names ): ?array {
		$position = $start + 1;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COLUMN_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
			return $this->translate_mysql_dbdelta_add_parenthesized_columns_alter_action(
				$table_schema,
				$table_name,
				$clause,
				$tokens,
				$position,
				$end,
				$check_names,
				$foreign_key_names
			);
		}

		$definition_end = $this->get_mysql_alter_column_definition_end_without_placement( $tokens, $position, $end );
		if ( null === $definition_end || $position >= $definition_end ) {
			return null;
		}

		return $this->translate_mysql_dbdelta_add_column_definition_alter_action(
			$table_schema,
			$table_name,
			$this->get_mysql_token_range_bytes( $clause, $tokens, $position, $definition_end ),
			$foreign_key_names
		);
	}

	/**
	 * Translate an ALTER TABLE ADD (definition, definition) action.
	 *
	 * @param string           $table_schema      Backend schema name.
	 * @param string           $table_name        Table name.
	 * @param string           $clause            Full ALTER clause string.
	 * @param WP_MySQL_Token[] $tokens            Clause token stream.
	 * @param int              $position          Opening parenthesis token.
	 * @param int              $end               Final action token, exclusive.
	 * @param string[]         $check_names       CHECK names generated for this ALTER TABLE statement.
	 * @param string[]         $foreign_key_names Foreign key names generated for this ALTER TABLE statement.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_add_parenthesized_columns_alter_action( string $table_schema, string $table_name, string $clause, array $tokens, int $position, int $end, array &$check_names, array &$foreign_key_names ): ?array {
		$parenthesized_end = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
		if ( $parenthesized_end !== $end ) {
			return null;
		}

		$ranges = $this->split_top_level_mysql_arguments( $tokens, $position + 1, $end - 1 );
		if ( null === $ranges || array() === $ranges ) {
			return null;
		}

		$statements          = array();
		$metadata_operations = array();
		foreach ( $ranges as $range ) {
			if ( $this->is_mysql_dbdelta_add_index_definition_action( $tokens, $range['start'], $range['end'] ) ) {
				$translation = $this->translate_mysql_dbdelta_add_index_definition_alter_action(
					$table_name,
					$clause,
					$tokens,
					$range['start'],
					$range['end']
				);
			} elseif ( $this->is_mysql_dbdelta_add_constraint_definition_action( $tokens, $range['start'], $range['end'] ) ) {
				$translation = $this->translate_mysql_dbdelta_add_constraint_definition_alter_action(
					$table_schema,
					$table_name,
					$clause,
					$tokens,
					$range['start'],
					$range['end'],
					$check_names,
					$foreign_key_names
				);
			} else {
				$definition_end = $this->get_mysql_alter_column_definition_end_without_placement( $tokens, $range['start'], $range['end'] );
				if ( null === $definition_end || $range['start'] >= $definition_end || $definition_end !== $range['end'] ) {
					return null;
				}

				$translation = $this->translate_mysql_dbdelta_add_column_definition_alter_action(
					$table_schema,
					$table_name,
					$this->get_mysql_token_range_bytes( $clause, $tokens, $range['start'], $definition_end ),
					$foreign_key_names
				);
			}

			if ( null === $translation ) {
				return null;
			}

			$statements            = array_merge( $statements, $translation['statements'] );
			$metadata_operations[] = $translation['metadata'];
		}

		return array(
			'statements' => $statements,
			'metadata'   => array(
				'operation'  => 'operations',
				'operations' => $metadata_operations,
			),
		);
	}

	/**
	 * Translate one ALTER TABLE ADD column definition.
	 *
	 * @param string   $table_schema      Backend schema name.
	 * @param string   $table_name        Table name.
	 * @param string   $definition        Column definition fragment.
	 * @param string[] $foreign_key_names Foreign key names generated for this ALTER TABLE statement.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_add_column_definition_alter_action( string $table_schema, string $table_name, string $definition, array &$foreign_key_names ): ?array {
		try {
			$column = $this->translate_mysql_column_definition_fragment(
				$definition,
				$table_name
			);
		} catch ( InvalidArgumentException $e ) {
			return null;
		}
		if ( null === $column ) {
			return null;
		}

		foreach ( $column['foreign_keys'] as &$foreign_key ) {
			$constraint_name = $this->get_next_mysql_foreign_key_constraint_name( $table_schema, $table_name, $foreign_key_names );
			$column['sql']   = $this->replace_mysql_column_fragment_constraint_name(
				$column['sql'],
				$foreign_key['name'],
				$constraint_name
			);

			$foreign_key['name']              = $constraint_name;
			$foreign_key['referenced_schema'] = $foreign_key['referenced_schema'] ?? $table_schema;
			$foreign_key_names[]              = $constraint_name;
		}
		unset( $foreign_key );

		return array(
			'statements' => array(
				sprintf(
					'ALTER TABLE %s ADD COLUMN %s',
					$this->connection->quote_identifier( $table_name ),
					$column['sql']
				),
			),
			'metadata'   => array(
				'operation'    => 'add_column',
				'column'       => $column['metadata'],
				'indexes'      => $column['indexes'],
				'foreign_keys' => $column['foreign_keys'],
				'checks'       => $column['checks'],
			),
		);
	}

	/**
	 * Translate an ALTER TABLE ADD INDEX action.
	 *
	 * @param string           $table_name Table name.
	 * @param string           $clause     Full ALTER clause string.
	 * @param WP_MySQL_Token[] $tokens     Clause token stream.
	 * @param int              $start      First action token.
	 * @param int              $end        Final action token, exclusive.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_add_index_alter_action( string $table_name, string $clause, array $tokens, int $start, int $end ): ?array {
		$definition_start = $start + 1;
		if ( $definition_start >= $end ) {
			return null;
		}

		return $this->translate_mysql_dbdelta_add_index_definition_alter_action(
			$table_name,
			$clause,
			$tokens,
			$definition_start,
			$end
		);
	}

	/**
	 * Translate an ALTER TABLE ADD index definition without the ADD keyword.
	 *
	 * @param string           $table_name       Table name.
	 * @param string           $clause           Full ALTER clause string.
	 * @param WP_MySQL_Token[] $tokens           Clause token stream.
	 * @param int              $definition_start First index-definition token.
	 * @param int              $end              Final index-definition token, exclusive.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_add_index_definition_alter_action( string $table_name, string $clause, array $tokens, int $definition_start, int $end ): ?array {
		$index = $this->translate_mysql_index_definition_fragment(
			$table_name,
			$this->get_mysql_token_range_bytes( $clause, $tokens, $definition_start, $end )
		);
		if ( null === $index ) {
			return null;
		}

		return array(
			'statements' => $index['statements'],
			'metadata'   => array(
				'operation' => 'add_index',
				'index'     => $index['metadata'],
			),
		);
	}

	/**
	 * Translate an ALTER TABLE ADD CONSTRAINT or ADD CHECK action.
	 *
	 * @param string           $table_schema      Backend schema name.
	 * @param string           $table_name        Table name.
	 * @param string           $clause            Full ALTER clause string.
	 * @param WP_MySQL_Token[] $tokens            Clause token stream.
	 * @param int              $start             First action token.
	 * @param int              $end               Final action token, exclusive.
	 * @param string[]         $check_names       CHECK names generated for this ALTER TABLE statement.
	 * @param string[]         $foreign_key_names Foreign key names generated for this ALTER TABLE statement.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_add_constraint_alter_action( string $table_schema, string $table_name, string $clause, array $tokens, int $start, int $end, array &$check_names, array &$foreign_key_names ): ?array {
		return $this->translate_mysql_dbdelta_add_constraint_definition_alter_action(
			$table_schema,
			$table_name,
			$clause,
			$tokens,
			$start + 1,
			$end,
			$check_names,
			$foreign_key_names
		);
	}

	/**
	 * Translate an ALTER TABLE ADD constraint definition without the ADD keyword.
	 *
	 * @param string           $table_schema      Backend schema name.
	 * @param string           $table_name        Table name.
	 * @param string           $clause            Full ALTER clause string.
	 * @param WP_MySQL_Token[] $tokens            Clause token stream.
	 * @param int              $position          First constraint-definition token.
	 * @param int              $end               Final constraint-definition token, exclusive.
	 * @param string[]         $check_names       CHECK names generated for this ALTER TABLE statement.
	 * @param string[]         $foreign_key_names Foreign key names generated for this ALTER TABLE statement.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_add_constraint_definition_alter_action( string $table_schema, string $table_name, string $clause, array $tokens, int $position, int $end, array &$check_names, array &$foreign_key_names ): ?array {
		$constraint_name = null;
		$definition_start = $position;

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::CONSTRAINT_SYMBOL === $tokens[ $position ]->id ) {
			$constraint_name = $this->get_mysql_alter_identifier_token_value( $tokens[ $position + 1 ] ?? null );
			if ( null === $constraint_name ) {
				return null;
			}
			$position += 2;
		}

		if ( ! isset( $tokens[ $position ] ) ) {
			return null;
		}

		if (
			WP_MySQL_Lexer::PRIMARY_SYMBOL === $tokens[ $position ]->id
			|| WP_MySQL_Lexer::UNIQUE_SYMBOL === $tokens[ $position ]->id
		) {
			$is_unique_constraint = WP_MySQL_Lexer::UNIQUE_SYMBOL === $tokens[ $position ]->id;
			$index                = $this->translate_mysql_index_definition_fragment(
				$table_name,
				$this->get_mysql_token_range_bytes( $clause, $tokens, $definition_start, $end )
			);
			if ( null === $index ) {
				return null;
			}

			if (
				$is_unique_constraint
				&& null !== $constraint_name
				&& isset( $index['metadata']['columns'][0]['column_name'] )
				&& $index['metadata']['name'] === $index['metadata']['columns'][0]['column_name']
			) {
				$index['metadata']['name'] = $constraint_name;
				$columns                   = array();
				foreach ( $index['metadata']['columns'] as $column ) {
					$columns[] = $this->connection->quote_identifier( $column['column_name'] );
				}

				$index['statements'] = array(
					sprintf(
						'CREATE UNIQUE INDEX %s ON %s (%s)',
						$this->connection->quote_identifier( $table_name . '__' . $constraint_name ),
						$this->connection->quote_identifier( $table_name ),
						implode( ', ', $columns )
					),
				);
			}

			return array(
				'statements' => $index['statements'],
				'metadata'   => array(
					'operation' => 'add_index',
					'index'     => $index['metadata'],
				),
			);
		}

		if ( WP_MySQL_Lexer::CHECK_SYMBOL === $tokens[ $position ]->id ) {
			return $this->translate_mysql_dbdelta_add_check_alter_action(
				$table_name,
				$tokens,
				$position,
				$end,
				$constraint_name,
				$check_names
			);
		}

		if ( WP_MySQL_Lexer::FOREIGN_SYMBOL === $tokens[ $position ]->id ) {
			return $this->translate_mysql_dbdelta_add_foreign_key_alter_action(
				$table_schema,
				$table_name,
				$tokens,
				$position,
				$end,
				$constraint_name,
				$foreign_key_names
			);
		}

		return null;
	}

	/**
	 * Translate an ALTER TABLE ADD CHECK action.
	 *
	 * @param string           $table_name      Table name.
	 * @param WP_MySQL_Token[] $tokens          Clause token stream.
	 * @param int              $check_position  CHECK token position.
	 * @param int              $end             Final action token, exclusive.
	 * @param string|null      $constraint_name Optional MySQL constraint name.
	 * @param string[]         $check_names     CHECK names generated for this ALTER TABLE statement.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_add_check_alter_action( string $table_name, array $tokens, int $check_position, int $end, ?string $constraint_name, array &$check_names ): ?array {
		if ( ! isset( $tokens[ $check_position + 1 ] ) || WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $check_position + 1 ]->id ) {
			return null;
		}

		$check_end = $this->get_mysql_parenthesized_sequence_end( $tokens, $check_position + 1, $end );
		if ( null === $check_end || $check_position + 2 >= $check_end - 1 ) {
			return null;
		}

		$enforced = 'YES';
		if ( $check_end < $end ) {
			if ( $check_end + 1 === $end && WP_MySQL_Lexer::ENFORCED_SYMBOL === ( $tokens[ $check_end ]->id ?? null ) ) {
				$enforced = 'YES';
			} elseif (
				$check_end + 2 === $end
				&& WP_MySQL_Lexer::NOT_SYMBOL === ( $tokens[ $check_end ]->id ?? null )
				&& WP_MySQL_Lexer::ENFORCED_SYMBOL === ( $tokens[ $check_end + 1 ]->id ?? null )
			) {
				$enforced = 'NO';
			} else {
				return null;
			}
		}

		if ( null === $constraint_name ) {
			$constraint_name = $this->get_next_mysql_check_constraint_name( 'public', $table_name, $check_names );
			$check_names[]   = $constraint_name;
		}

		$expression = $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$check_position + 2,
			$check_end - 1
		);

		$statements = array();
		if ( 'YES' === $enforced ) {
			$statements[] = sprintf(
				'ALTER TABLE %s ADD CONSTRAINT %s CHECK (%s)',
				$this->connection->quote_identifier( $table_name ),
				$this->connection->quote_identifier( $constraint_name ),
				$expression
			);
		}

		return array(
			'statements' => $statements,
			'metadata'   => array(
				'operation' => 'add_check',
				'check'     => array(
					'name'         => $constraint_name,
					'check_clause' => $expression,
					'enforced'     => $enforced,
				),
			),
		);
	}

	/**
	 * Translate an ALTER TABLE ADD FOREIGN KEY action.
	 *
	 * @param string           $table_schema     Backend schema name.
	 * @param string           $table_name       Table name.
	 * @param WP_MySQL_Token[] $tokens           Clause token stream.
	 * @param int              $foreign_position FOREIGN token position.
	 * @param int              $end              Final action token, exclusive.
	 * @param string|null      $constraint_name  Optional MySQL constraint name.
	 * @param string[]         $foreign_key_names Foreign key names generated for this ALTER TABLE statement.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_add_foreign_key_alter_action( string $table_schema, string $table_name, array $tokens, int $foreign_position, int $end, ?string $constraint_name, array &$foreign_key_names ): ?array {
		if ( ! isset( $tokens[ $foreign_position + 1 ] ) || WP_MySQL_Lexer::KEY_SYMBOL !== $tokens[ $foreign_position + 1 ]->id ) {
			return null;
		}

		$position = $foreign_position + 2;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position ]->id ) {
			$index_name = $this->get_mysql_alter_identifier_token_value( $tokens[ $position ] );
			if ( null === $index_name ) {
				return null;
			}
			++$position;
		}

		$columns = $this->parse_mysql_alter_identifier_list( $tokens, $position );
		if ( null === $columns || empty( $columns ) ) {
			return null;
		}

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::REFERENCES_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		++$position;
		$referenced_table = $this->get_mysql_table_administration_table_reference( $tokens, $position );
		if ( null === $referenced_table ) {
			return null;
		}

		$referenced_schema  = $this->get_mysql_writable_table_backend_schema( $referenced_table, 'ALTER TABLE' );
		$referenced_columns = $this->parse_mysql_alter_identifier_list( $tokens, $position );
		if ( null === $referenced_columns || count( $referenced_columns ) !== count( $columns ) ) {
			return null;
		}

		$rules = $this->parse_mysql_foreign_key_rules( $tokens, $position, $end );
		if ( null === $rules ) {
			return null;
		}

		if ( null === $constraint_name ) {
			$constraint_name     = $this->get_next_mysql_foreign_key_constraint_name( $table_schema, $table_name, $foreign_key_names );
			$foreign_key_names[] = $constraint_name;
		} else {
			$foreign_key_names[] = $constraint_name;
		}

		$foreign_key_sql = sprintf(
			'ALTER TABLE %s ADD CONSTRAINT %s FOREIGN KEY (%s) REFERENCES %s (%s)%s%s',
			$this->connection->quote_identifier( $table_name ),
			$this->connection->quote_identifier( $constraint_name ),
			implode( ', ', array_map( array( $this->connection, 'quote_identifier' ), $columns ) ),
			null === $referenced_table['schema']
				? $this->connection->quote_identifier( $referenced_table['table'] )
				: $this->get_postgresql_schema_identifier( $referenced_schema, $referenced_table['table'] ),
			implode( ', ', array_map( array( $this->connection, 'quote_identifier' ), $referenced_columns ) ),
			'NO ACTION' === $rules['delete_rule'] ? '' : ' ON DELETE ' . $rules['delete_rule'],
			'NO ACTION' === $rules['update_rule'] ? '' : ' ON UPDATE ' . $rules['update_rule']
		);

		return array(
			'statements' => array( $foreign_key_sql ),
			'metadata'   => array(
				'operation'   => 'add_foreign_key',
				'foreign_key' => array(
					'name'               => $constraint_name,
					'columns'            => $columns,
					'referenced_schema'  => $referenced_schema,
					'referenced_table'   => $referenced_table['table'],
					'referenced_columns' => $referenced_columns,
					'update_rule'        => $rules['update_rule'],
					'delete_rule'        => $rules['delete_rule'],
				),
			),
		);
	}

	/**
	 * Parse a parenthesized identifier list in ALTER TABLE contexts.
	 *
	 * @param WP_MySQL_Token[] $tokens   Clause token stream.
	 * @param int             $position Current token position, updated on success.
	 * @return string[]|null Identifier values, or null when unsupported.
	 */
	private function parse_mysql_alter_identifier_list( array $tokens, int &$position ): ?array {
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		++$position;
		$identifiers = array();
		while ( isset( $tokens[ $position ] ) ) {
			$identifier = $this->get_mysql_alter_identifier_token_value( $tokens[ $position ] );
			if ( null === $identifier ) {
				return null;
			}

			$identifiers[] = $identifier;
			++$position;

			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
				continue;
			}

			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
				return $identifiers;
			}

			return null;
		}

		return null;
	}

	/**
	 * Parse optional foreign key ON UPDATE/ON DELETE rules.
	 *
	 * @param WP_MySQL_Token[] $tokens   Clause token stream.
	 * @param int             $position Current token position, updated on success.
	 * @param int             $end      Final action token, exclusive.
	 * @return array{update_rule: string, delete_rule: string}|null Parsed rules, or null when unsupported.
	 */
	private function parse_mysql_foreign_key_rules( array $tokens, int &$position, int $end ): ?array {
		$rules = array(
			'update_rule' => 'NO ACTION',
			'delete_rule' => 'NO ACTION',
		);
		$seen  = array();

		while ( $position < $end ) {
			if ( ! isset( $tokens[ $position ], $tokens[ $position + 1 ] ) || WP_MySQL_Lexer::ON_SYMBOL !== $tokens[ $position ]->id ) {
				return null;
			}

			if ( WP_MySQL_Lexer::UPDATE_SYMBOL === $tokens[ $position + 1 ]->id ) {
				$rule_key = 'update_rule';
			} elseif ( WP_MySQL_Lexer::DELETE_SYMBOL === $tokens[ $position + 1 ]->id ) {
				$rule_key = 'delete_rule';
			} else {
				return null;
			}

			if ( isset( $seen[ $rule_key ] ) ) {
				return null;
			}

			$position += 2;
			$rule      = $this->parse_mysql_foreign_key_reference_option( $tokens, $position, $end );
			if ( null === $rule ) {
				return null;
			}

			$rules[ $rule_key ] = $rule;
			$seen[ $rule_key ]  = true;
		}

		return $rules;
	}

	/**
	 * Parse one foreign key reference option.
	 *
	 * @param WP_MySQL_Token[] $tokens   Clause token stream.
	 * @param int             $position Current token position, updated on success.
	 * @param int             $end      Final action token, exclusive.
	 * @return string|null Reference option, or null when unsupported.
	 */
	private function parse_mysql_foreign_key_reference_option( array $tokens, int &$position, int $end ): ?string {
		if ( $position >= $end || ! isset( $tokens[ $position ] ) ) {
			return null;
		}

		if ( in_array( $tokens[ $position ]->id, array( WP_MySQL_Lexer::CASCADE_SYMBOL, WP_MySQL_Lexer::RESTRICT_SYMBOL ), true ) ) {
			$rule = strtoupper( $tokens[ $position ]->get_value() );
			++$position;
			return $rule;
		}

		if ( WP_MySQL_Lexer::SET_SYMBOL === $tokens[ $position ]->id ) {
			if ( ! isset( $tokens[ $position + 1 ] ) ) {
				return null;
			}

			if ( WP_MySQL_Lexer::NULL_SYMBOL === $tokens[ $position + 1 ]->id ) {
				$position += 2;
				return 'SET NULL';
			}

			if ( WP_MySQL_Lexer::DEFAULT_SYMBOL === $tokens[ $position + 1 ]->id ) {
				$position += 2;
				return 'SET DEFAULT';
			}

			return null;
		}

		if (
			isset( $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::NO_SYMBOL === $tokens[ $position ]->id
			&& WP_MySQL_Lexer::ACTION_SYMBOL === $tokens[ $position + 1 ]->id
		) {
			$position += 2;
			return 'NO ACTION';
		}

		return null;
	}

	/**
	 * Translate an ALTER TABLE DROP INDEX action.
	 *
	 * @param string           $table_name Table name.
	 * @param WP_MySQL_Token[] $tokens     Clause token stream.
	 * @param int              $start      First action token.
	 * @param int              $end        Final action token, exclusive.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_drop_index_alter_action( string $table_name, array $tokens, int $start, int $end ): ?array {
		if ( $start + 3 !== $end ) {
			throw new InvalidArgumentException( 'Unsupported ALTER TABLE statement.' );
		}

		$index_name = $this->get_mysql_alter_identifier_token_value( $tokens[ $start + 2 ] ?? null );
		if ( null === $index_name ) {
			throw new InvalidArgumentException( 'Unsupported ALTER TABLE statement.' );
		}

		$drop_index_query = $this->get_mysql_drop_index_translation(
			array(
				'schema' => null,
				'table'  => $table_name,
			),
			$index_name,
			'ALTER TABLE'
		);

		$drop_index_query['metadata']['operation'] = 'drop_index';
		return $drop_index_query;
	}

	/**
	 * Translate an ALTER TABLE DROP PRIMARY KEY action.
	 *
	 * @param string $table_name Table name.
	 * @return array{statements: string[], metadata: array} Drop primary key translation.
	 */
	private function translate_mysql_dbdelta_drop_primary_key_alter_action( string $table_name ): array {
		return array(
			'statements' => array(
				sprintf(
					'ALTER TABLE %s DROP CONSTRAINT %s',
					$this->connection->quote_identifier( $table_name ),
					$this->connection->quote_identifier(
						$this->get_postgresql_primary_key_constraint_name( 'public', $table_name )
					)
				),
			),
			'metadata'   => array(
				'operation' => 'drop_index',
				'schema'    => 'public',
				'table'     => $table_name,
				'index'     => 'PRIMARY',
			),
		);
	}

	/**
	 * Translate an ALTER TABLE DROP CONSTRAINT action.
	 *
	 * @param string           $table_name Table name.
	 * @param WP_MySQL_Token[] $tokens     Clause token stream.
	 * @param int              $start      First action token.
	 * @param int              $end        Final action token, exclusive.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_drop_constraint_alter_action( string $table_name, array $tokens, int $start, int $end ): ?array {
		$constraint_name = $this->get_mysql_alter_identifier_token_value( $tokens[ $start + 2 ] ?? null );
		if ( null === $constraint_name ) {
			return null;
		}

		if ( 'PRIMARY' === strtoupper( $constraint_name ) ) {
			return $this->translate_mysql_dbdelta_drop_primary_key_alter_action( $table_name );
		}

		if ( $this->mysql_index_metadata_exists( 'public', $table_name, $constraint_name ) ) {
			$drop_index_query = $this->get_mysql_drop_index_translation(
				array(
					'schema' => null,
					'table'  => $table_name,
				),
				$constraint_name,
				'ALTER TABLE'
			);

			$drop_index_query['metadata']['operation'] = 'drop_index';
			return $drop_index_query;
		}

		if ( $this->mysql_foreign_key_metadata_exists( 'public', $table_name, $constraint_name ) ) {
			return $this->get_mysql_dbdelta_drop_foreign_key_translation( $table_name, $constraint_name );
		}

		$check_metadata = $this->get_mysql_check_metadata( 'public', $table_name, $constraint_name );
		return $this->get_mysql_dbdelta_drop_check_translation(
			$table_name,
			$constraint_name,
			null === $check_metadata || 'NO' !== strtoupper( (string) $check_metadata['enforced'] )
		);
	}

	/**
	 * Translate an ALTER TABLE DROP FOREIGN KEY action.
	 *
	 * @param string           $table_name Table name.
	 * @param WP_MySQL_Token[] $tokens     Clause token stream.
	 * @param int              $start      First action token.
	 * @param int              $end        Final action token, exclusive.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_drop_foreign_key_alter_action( string $table_name, array $tokens, int $start, int $end ): ?array {
		if ( $start + 4 !== $end ) {
			return null;
		}

		$constraint_name = $this->get_mysql_alter_identifier_token_value( $tokens[ $start + 3 ] ?? null );
		if ( null === $constraint_name ) {
			return null;
		}

		return $this->get_mysql_dbdelta_drop_foreign_key_translation( $table_name, $constraint_name );
	}

	/**
	 * Build a DROP FOREIGN KEY translation for a named constraint.
	 *
	 * @param string $table_name      Table name.
	 * @param string $constraint_name Constraint name.
	 * @return array{statements: string[], metadata: array} Drop foreign key translation.
	 */
	private function get_mysql_dbdelta_drop_foreign_key_translation( string $table_name, string $constraint_name ): array {
		return array(
			'statements' => array(
				sprintf(
					'ALTER TABLE %s DROP CONSTRAINT %s',
					$this->connection->quote_identifier( $table_name ),
					$this->connection->quote_identifier( $constraint_name )
				),
			),
			'metadata'   => array(
				'operation'  => 'drop_foreign_key',
				'constraint' => $constraint_name,
			),
		);
	}

	/**
	 * Translate an ALTER TABLE DROP CHECK action.
	 *
	 * @param string           $table_name Table name.
	 * @param WP_MySQL_Token[] $tokens     Clause token stream.
	 * @param int              $start      First action token.
	 * @param int              $end        Final action token, exclusive.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_drop_check_alter_action( string $table_name, array $tokens, int $start, int $end ): ?array {
		$constraint_name = $this->get_mysql_alter_identifier_token_value( $tokens[ $start + 2 ] ?? null );
		if ( null === $constraint_name ) {
			return null;
		}

		$check_metadata = $this->get_mysql_check_metadata( 'public', $table_name, $constraint_name );
		return $this->get_mysql_dbdelta_drop_check_translation(
			$table_name,
			$constraint_name,
			null === $check_metadata || 'NO' !== strtoupper( (string) $check_metadata['enforced'] )
		);
	}

	/**
	 * Build a DROP CHECK translation for a named constraint.
	 *
	 * @param string $table_name            Table name.
	 * @param string $constraint_name       Constraint name.
	 * @param bool   $drop_backend_constraint Whether a backend constraint should be dropped.
	 * @return array{statements: string[], metadata: array} Drop CHECK translation.
	 */
	private function get_mysql_dbdelta_drop_check_translation( string $table_name, string $constraint_name, bool $drop_backend_constraint ): array {
		$statements = array();
		if ( $drop_backend_constraint ) {
			$statements[] = sprintf(
				'ALTER TABLE %s DROP CONSTRAINT %s',
				$this->connection->quote_identifier( $table_name ),
				$this->connection->quote_identifier( $constraint_name )
			);
		}

		return array(
			'statements' => $statements,
			'metadata'   => array(
				'operation'  => 'drop_check',
				'constraint' => $constraint_name,
			),
		);
	}

	/**
	 * Translate an ALTER TABLE DROP COLUMN action.
	 *
	 * @param string           $table_name Table name.
	 * @param WP_MySQL_Token[] $tokens     Clause token stream.
	 * @param int              $start      First action token.
	 * @param int              $end        Final action token, exclusive.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_drop_column_alter_action( string $table_name, array $tokens, int $start, int $end ): ?array {
		$position = $start + 1;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COLUMN_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		if (
			$position + 2 === $end
			&& isset( $tokens[ $position + 1 ] )
			&& in_array( $tokens[ $position + 1 ]->id, array( WP_MySQL_Lexer::CASCADE_SYMBOL, WP_MySQL_Lexer::RESTRICT_SYMBOL ), true )
		) {
			--$end;
		}

		if ( $position + 1 !== $end ) {
			return null;
		}

		$column_name = $this->get_mysql_alter_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $column_name ) {
			return null;
		}

		return array(
			'statements' => array(
				sprintf(
					'ALTER TABLE %s DROP COLUMN %s',
					$this->connection->quote_identifier( $table_name ),
					$this->connection->quote_identifier( $column_name )
				),
			),
			'metadata'   => array(
				'operation' => 'drop_column',
				'column'    => $column_name,
			),
		);
	}

	/**
	 * Translate ALTER TABLE ALTER COLUMN default actions.
	 *
	 * @param string           $table_name Table name.
	 * @param string           $clause     Full ALTER clause string.
	 * @param WP_MySQL_Token[] $tokens     Clause token stream.
	 * @param int              $start      First action token.
	 * @param int              $end        Final action token, exclusive.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_alter_column_default_action( string $table_name, string $clause, array $tokens, int $start, int $end ): ?array {
		$position = $start + 1;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COLUMN_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		$column_name = $this->get_mysql_alter_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $column_name || ! isset( $tokens[ $position + 1 ] ) ) {
			return null;
		}

		$position += 1;
		if ( WP_MySQL_Lexer::SET_SYMBOL === $tokens[ $position ]->id ) {
			if ( ! isset( $tokens[ $position + 1 ] ) || WP_MySQL_Lexer::DEFAULT_SYMBOL !== $tokens[ $position + 1 ]->id ) {
				return null;
			}

			$default_start = $position + 2;
			if ( $default_start >= $end ) {
				return null;
			}

			$default = $this->translate_mysql_default_fragment(
				$this->get_mysql_token_range_bytes( $clause, $tokens, $default_start, $end )
			);
			if ( null === $default ) {
				return null;
			}

			return array(
				'statements' => array(
					sprintf(
						'ALTER TABLE %s ALTER COLUMN %s SET DEFAULT %s',
						$this->connection->quote_identifier( $table_name ),
						$this->connection->quote_identifier( $column_name ),
						$default['sql']
					),
				),
				'metadata'   => array(
					'operation' => 'set_default',
					'column'    => $column_name,
					'default'   => $default['metadata'],
				),
			);
		}

		if (
			isset( $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::DROP_SYMBOL === $tokens[ $position ]->id
			&& WP_MySQL_Lexer::DEFAULT_SYMBOL === $tokens[ $position + 1 ]->id
			&& $position + 2 === $end
		) {
			return array(
				'statements' => array(
					sprintf(
						'ALTER TABLE %s ALTER COLUMN %s DROP DEFAULT',
						$this->connection->quote_identifier( $table_name ),
						$this->connection->quote_identifier( $column_name )
					),
				),
				'metadata'   => array(
					'operation' => 'drop_default',
					'column'    => $column_name,
				),
			);
		}

		return null;
	}

	/**
	 * Build PostgreSQL statements for a CHANGE/MODIFY column operation.
	 *
	 * @param string $table_name Table name.
	 * @param string $old_column Existing column name.
	 * @param array  $column     Translated column definition data.
	 * @return string[] PostgreSQL ALTER statements.
	 */
	private function get_mysql_dbdelta_change_column_statements( string $table_name, string $old_column, array $column ): array {
		$new_column = $column['metadata']['name'];
		$statements = array();
		if ( $old_column !== $new_column ) {
			$statements[] = sprintf(
				'ALTER TABLE %s RENAME COLUMN %s TO %s',
				$this->connection->quote_identifier( $table_name ),
				$this->connection->quote_identifier( $old_column ),
				$this->connection->quote_identifier( $new_column )
			);
		}

		$column_type                = $this->get_translated_column_type_from_definition_line( $column['sql'] );
		$preserve_existing_identity = $this->should_preserve_existing_identity_integer_column_change(
			'public',
			$table_name,
			$old_column,
			$column['metadata']
		);
		if ( '' !== $column_type && ! $preserve_existing_identity ) {
			$statements[] = sprintf(
				'ALTER TABLE %s ALTER COLUMN %s TYPE %s',
				$this->connection->quote_identifier( $table_name ),
				$this->connection->quote_identifier( $new_column ),
				$column_type
			);
		}

		$statements[] = sprintf(
			'ALTER TABLE %s ALTER COLUMN %s %s NOT NULL',
			$this->connection->quote_identifier( $table_name ),
			$this->connection->quote_identifier( $new_column ),
			'NO' === ( $column['metadata']['nullable'] ?? 'YES' ) ? 'SET' : 'DROP'
		);

		$default_sql = $this->get_translated_column_default_from_definition_line( $column['sql'] );
		if ( ! $preserve_existing_identity ) {
			if ( null !== $default_sql ) {
				$statements[] = sprintf(
					'ALTER TABLE %s ALTER COLUMN %s SET DEFAULT %s',
					$this->connection->quote_identifier( $table_name ),
					$this->connection->quote_identifier( $new_column ),
					$default_sql
				);
			} else {
				$statements[] = sprintf(
					'ALTER TABLE %s ALTER COLUMN %s DROP DEFAULT',
					$this->connection->quote_identifier( $table_name ),
					$this->connection->quote_identifier( $new_column )
				);
			}
		}

		return array_merge(
			$statements,
			$this->get_mysql_dbdelta_inline_index_statements( $table_name, $column['indexes'] ?? array() )
		);
	}

	/**
	 * Build PostgreSQL statements for inline indexes parsed from a column definition.
	 *
	 * @param string $table_name Table name.
	 * @param array  $indexes    MySQL index metadata rows.
	 * @return string[] PostgreSQL ALTER/CREATE INDEX statements.
	 */
	private function get_mysql_dbdelta_inline_index_statements( string $table_name, array $indexes ): array {
		$statements = array();
		foreach ( $indexes as $index ) {
			$columns = array();
			foreach ( $index['columns'] as $column ) {
				$column_sql = $this->get_mysql_index_key_part_sql(
					(string) $column['column_name'],
					'0' === (string) $index['non_unique'] ? $column['sub_part'] : null
				);
				if ( 'D' === strtoupper( (string) ( $column['collation'] ?? '' ) ) ) {
					$column_sql .= ' DESC';
				}

				$columns[] = $column_sql;
			}

			if ( 'PRIMARY' === strtoupper( (string) $index['name'] ) ) {
				$statements[] = sprintf(
					'ALTER TABLE %s ADD PRIMARY KEY (%s)',
					$this->connection->quote_identifier( $table_name ),
					implode( ', ', $columns )
				);
				continue;
			}

			if ( $this->is_mysql_metadata_only_index_type( (string) $index['index_type'] ) ) {
				continue;
			}

			$statements[] = sprintf(
				'CREATE %sINDEX %s ON %s (%s)',
				'0' === (string) $index['non_unique'] ? 'UNIQUE ' : '',
				$this->connection->quote_identifier( $table_name . '__' . $index['name'] ),
				$this->connection->quote_identifier( $table_name ),
				implode( ', ', $columns )
			);
		}

		return $statements;
	}

	/**
	 * Check whether an ADD action adds an index rather than a column.
	 *
	 * @param WP_MySQL_Token[] $tokens Clause token stream.
	 * @param int              $start  First action token.
	 * @param int              $end    Final action token, exclusive.
	 * @return bool Whether the action is an ADD INDEX form.
	 */
	private function is_mysql_dbdelta_add_index_action( array $tokens, int $start, int $end ): bool {
		if ( $start + 1 >= $end || ! isset( $tokens[ $start + 1 ] ) ) {
			return false;
		}

		return $this->is_mysql_dbdelta_add_index_definition_action( $tokens, $start + 1, $end );
	}

	/**
	 * Check whether a token range is an ADD index definition without the ADD keyword.
	 *
	 * @param WP_MySQL_Token[] $tokens Clause token stream.
	 * @param int              $start  First definition token.
	 * @param int              $end    Final definition token, exclusive.
	 * @return bool Whether the range is an index definition.
	 */
	private function is_mysql_dbdelta_add_index_definition_action( array $tokens, int $start, int $end ): bool {
		if ( $start >= $end || ! isset( $tokens[ $start ] ) ) {
			return false;
		}

		return in_array(
			$tokens[ $start ]->id,
			array(
				WP_MySQL_Lexer::FULLTEXT_SYMBOL,
				WP_MySQL_Lexer::INDEX_SYMBOL,
				WP_MySQL_Lexer::KEY_SYMBOL,
				WP_MySQL_Lexer::PRIMARY_SYMBOL,
				WP_MySQL_Lexer::SPATIAL_SYMBOL,
				WP_MySQL_Lexer::UNIQUE_SYMBOL,
			),
			true
		);
	}

	/**
	 * Check whether an ADD action adds a table constraint.
	 *
	 * @param WP_MySQL_Token[] $tokens Clause token stream.
	 * @param int              $start  First action token.
	 * @param int              $end    Final action token, exclusive.
	 * @return bool Whether the action is an ADD CONSTRAINT or ADD CHECK form.
	 */
	private function is_mysql_dbdelta_add_constraint_action( array $tokens, int $start, int $end ): bool {
		if ( $start + 1 >= $end || ! isset( $tokens[ $start + 1 ] ) ) {
			return false;
		}

		return $this->is_mysql_dbdelta_add_constraint_definition_action( $tokens, $start + 1, $end );
	}

	/**
	 * Check whether a token range is an ADD constraint definition without the ADD keyword.
	 *
	 * @param WP_MySQL_Token[] $tokens Clause token stream.
	 * @param int              $start  First definition token.
	 * @param int              $end    Final definition token, exclusive.
	 * @return bool Whether the range is an ADD CONSTRAINT or ADD CHECK definition.
	 */
	private function is_mysql_dbdelta_add_constraint_definition_action( array $tokens, int $start, int $end ): bool {
		if ( $start >= $end || ! isset( $tokens[ $start ] ) ) {
			return false;
		}

		return in_array(
			$tokens[ $start ]->id,
			array(
				WP_MySQL_Lexer::CHECK_SYMBOL,
				WP_MySQL_Lexer::CONSTRAINT_SYMBOL,
				WP_MySQL_Lexer::FOREIGN_SYMBOL,
			),
			true
		);
	}

	/**
	 * Check whether a DROP action removes a foreign key.
	 *
	 * @param WP_MySQL_Token[] $tokens Clause token stream.
	 * @param int              $start  First action token.
	 * @param int              $end    Final action token, exclusive.
	 * @return bool Whether the action is DROP FOREIGN KEY.
	 */
	private function is_mysql_dbdelta_drop_foreign_key_action( array $tokens, int $start, int $end ): bool {
		return $start + 4 === $end
			&& isset( $tokens[ $start + 1 ], $tokens[ $start + 2 ] )
			&& WP_MySQL_Lexer::FOREIGN_SYMBOL === $tokens[ $start + 1 ]->id
			&& WP_MySQL_Lexer::KEY_SYMBOL === $tokens[ $start + 2 ]->id;
	}

	/**
	 * Get the end of a column definition after removing MySQL placement syntax.
	 *
	 * PostgreSQL cannot preserve MySQL physical column placement. SQLite ignores
	 * it too, so PostgreSQL translation strips FIRST/AFTER while preserving the
	 * column definition and metadata.
	 *
	 * @param WP_MySQL_Token[] $tokens Clause token stream.
	 * @param int              $start  First definition token.
	 * @param int              $end    Final definition token, exclusive.
	 * @return int|null Definition end, exclusive, or null when placement is malformed.
	 */
	private function get_mysql_alter_column_definition_end_without_placement( array $tokens, int $start, int $end ): ?int {
		if ( $start >= $end ) {
			return null;
		}

		if ( isset( $tokens[ $end - 1 ] ) && WP_MySQL_Lexer::FIRST_SYMBOL === $tokens[ $end - 1 ]->id ) {
			return $end - 1;
		}

		if (
			$end - 2 >= $start
			&& isset( $tokens[ $end - 2 ], $tokens[ $end - 1 ] )
			&& WP_MySQL_Lexer::AFTER_SYMBOL === $tokens[ $end - 2 ]->id
			&& null !== $this->get_mysql_alter_identifier_token_value( $tokens[ $end - 1 ] )
		) {
			return $end - 2;
		}

		if (
			$end - 1 >= $start
			&& isset( $tokens[ $end - 1 ] )
			&& WP_MySQL_Lexer::AFTER_SYMBOL === $tokens[ $end - 1 ]->id
		) {
			return null;
		}

		return $end;
	}

	/**
	 * Get an identifier value in ALTER TABLE action contexts.
	 *
	 * MySQL permits unquoted keyword-like column names such as "status".
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @return string|null Identifier value, or null when unsupported.
	 */
	private function get_mysql_alter_identifier_token_value( ?WP_MySQL_Token $token ): ?string {
		return $this->get_mysql_index_identifier_token_value( $token );
	}

	/**
	 * Check whether an ALTER action is a supported MySQL table option no-op.
	 *
	 * @param string           $clause Full ALTER clause string.
	 * @param WP_MySQL_Token[] $tokens Clause token stream.
	 * @param int              $start  First action token.
	 * @param int              $end    Final action token, exclusive.
	 * @return bool Whether this table option can be safely ignored.
	 */
	private function is_supported_mysql_dbdelta_table_option_alter_action( string $clause, array $tokens, int $start, int $end ): bool {
		$fragment = strtoupper( preg_replace( '/\s+/', ' ', trim( $this->get_mysql_token_range_bytes( $clause, $tokens, $start, $end ) ) ) );

		return 1 === preg_match(
			'/^(?:ENGINE|ROW_FORMAT|COMMENT|KEY_BLOCK_SIZE|MAX_ROWS|MIN_ROWS|AVG_ROW_LENGTH|CHECKSUM|DELAY_KEY_WRITE|PACK_KEYS|STATS_PERSISTENT|STATS_AUTO_RECALC|STATS_SAMPLE_PAGES|COMPRESSION|ENCRYPTION|CONNECTION|PASSWORD|INSERT_METHOD|SECONDARY_ENGINE|AUTOEXTEND_SIZE|ENGINE_ATTRIBUTE|SECONDARY_ENGINE_ATTRIBUTE)\s*=|^(?:DEFAULT\s+)?(?:CHARACTER\s+SET|CHARSET|COLLATE)\s*=|^CONVERT\s+TO\s+CHARACTER\s+SET\b|^(?:DATA|INDEX)\s+DIRECTORY\b|^TABLESPACE\b|^UNION\s*=/',
			$fragment
		);
	}

	/**
	 * Check whether an ALTER action is a supported MySQL online-DDL no-op.
	 *
	 * @param WP_MySQL_Token[] $tokens Clause token stream.
	 * @param int              $start  First action token.
	 * @param int              $end    Final action token, exclusive.
	 * @return bool Whether this option can be safely ignored.
	 */
	private function is_supported_mysql_dbdelta_online_ddl_option_alter_action( array $tokens, int $start, int $end ): bool {
		$position = $start;
		return $this->consume_mysql_supported_index_lock_and_algorithm_options( $tokens, $position, $end )
			&& $position === $end;
	}

	/**
	 * Check whether an ALTER action is a supported MySQL key-maintenance no-op.
	 *
	 * MySQL accepts these clauses around bulk data loads. PostgreSQL has no
	 * equivalent table-level index toggle, so the compatible behavior is to
	 * accept them explicitly without backend DDL.
	 *
	 * @param WP_MySQL_Token[] $tokens Clause token stream.
	 * @param int              $start  First action token.
	 * @param int              $end    Final action token, exclusive.
	 * @return bool Whether this key-maintenance clause can be safely ignored.
	 */
	private function is_supported_mysql_dbdelta_keys_alter_action( array $tokens, int $start, int $end ): bool {
		return $start + 2 === $end
			&& isset( $tokens[ $start ], $tokens[ $start + 1 ] )
			&& in_array( $tokens[ $start ]->id, array( WP_MySQL_Lexer::DISABLE_SYMBOL, WP_MySQL_Lexer::ENABLE_SYMBOL ), true )
			&& WP_MySQL_Lexer::KEYS_SYMBOL === $tokens[ $start + 1 ]->id;
	}

	/**
	 * Check whether a query starts with ALTER TABLE.
	 *
	 * @param string $query SQL query.
	 * @return bool Whether this is an ALTER TABLE statement.
	 */
	private function is_mysql_alter_table_query( string $query ): bool {
		$tokens = $this->get_mysql_tokens( $query );
		return isset( $tokens[0], $tokens[1] )
			&& WP_MySQL_Lexer::ALTER_SYMBOL === $tokens[0]->id
			&& WP_MySQL_Lexer::TABLE_SYMBOL === $tokens[1]->id;
	}

	/**
	 * Check whether a query starts with RENAME TABLE.
	 *
	 * @param string $query SQL query.
	 * @return bool Whether this is a RENAME TABLE statement.
	 */
	private function is_mysql_rename_table_query( string $query ): bool {
		$tokens = $this->get_mysql_tokens( $query );
		return isset( $tokens[0], $tokens[1] )
			&& WP_MySQL_Lexer::RENAME_SYMBOL === $tokens[0]->id
			&& WP_MySQL_Lexer::TABLE_SYMBOL === $tokens[1]->id;
	}

	/**
	 * Translate ALTER TABLE MODIFY COLUMN clauses.
	 *
	 * Action Scheduler emits comma-separated MODIFY COLUMN clauses for datetime
	 * null/default adjustments. Treat each one like CHANGE COLUMN without a
	 * rename and keep unsupported ALTER fragments visible by returning null.
	 *
	 * @param string $table_name Table name.
	 * @param string $clause     ALTER TABLE clause fragment.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_dbdelta_modify_column_alter_query( string $table_name, string $clause ): ?array {
		$tokens        = $this->get_mysql_tokens( $clause );
		$statement_end = $this->get_mysql_statement_end_position( $tokens, 0 );
		if ( null === $statement_end ) {
			return null;
		}

		$ranges = $this->split_top_level_mysql_arguments( $tokens, 0, $statement_end );
		if ( null === $ranges || array() === $ranges ) {
			return null;
		}

		$statements = array();
		$columns    = array();
		foreach ( $ranges as $range ) {
			$position = $range['start'];
			if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::MODIFY_SYMBOL !== $tokens[ $position ]->id ) {
				return null;
			}

			++$position;
			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COLUMN_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
			}

			if ( $position >= $range['end'] ) {
				return null;
			}

			$definition = $this->get_mysql_token_range_bytes( $clause, $tokens, $position, $range['end'] );
			try {
				$column = $this->translate_mysql_column_definition_fragment( $definition );
			} catch ( InvalidArgumentException $e ) {
				return null;
			}
			if ( null === $column ) {
				return null;
			}

			$column_name                = $column['metadata']['name'];
			$column_type                = $this->get_translated_column_type_from_definition_line( $column['sql'] );
			$preserve_existing_identity = $this->should_preserve_existing_identity_integer_column_change(
				'public',
				$table_name,
				$column_name,
				$column['metadata']
			);
			if ( '' !== $column_type && ! $preserve_existing_identity ) {
				$statements[] = sprintf(
					'ALTER TABLE %s ALTER COLUMN %s TYPE %s',
					$this->connection->quote_identifier( $table_name ),
					$this->connection->quote_identifier( $column_name ),
					$column_type
				);
			}

			$statements[] = sprintf(
				'ALTER TABLE %s ALTER COLUMN %s %s NOT NULL',
				$this->connection->quote_identifier( $table_name ),
				$this->connection->quote_identifier( $column_name ),
				'NO' === ( $column['metadata']['nullable'] ?? 'YES' ) ? 'SET' : 'DROP'
			);

			$default_sql = $this->get_translated_column_default_from_definition_line( $column['sql'] );
			if ( ! $preserve_existing_identity ) {
				if ( null !== $default_sql ) {
					$statements[] = sprintf(
						'ALTER TABLE %s ALTER COLUMN %s SET DEFAULT %s',
						$this->connection->quote_identifier( $table_name ),
						$this->connection->quote_identifier( $column_name ),
						$default_sql
					);
				} else {
					$statements[] = sprintf(
						'ALTER TABLE %s ALTER COLUMN %s DROP DEFAULT',
						$this->connection->quote_identifier( $table_name ),
						$this->connection->quote_identifier( $column_name )
					);
				}
			}

			$columns[] = array(
				'old_column' => $column_name,
				'column'     => $column['metadata'],
			);
		}

		return array(
			'statements' => $statements,
			'metadata'   => array(
				'operation' => 'change_columns',
				'table'     => $table_name,
				'columns'   => $columns,
			),
		);
	}

	/**
	 * Check whether an AUTO_INCREMENT CHANGE COLUMN should leave PostgreSQL identity DDL untouched.
	 *
	 * @param string $table_schema Table schema.
	 * @param string $table_name   Table name.
	 * @param string $old_column   Existing column name.
	 * @param array  $column       Replacement MySQL metadata.
	 * @return bool Whether the physical type/default changes should be metadata-only.
	 */
	private function should_preserve_existing_identity_integer_column_change(
		string $table_schema,
		string $table_name,
		string $old_column,
		array $column
	): bool {
		if ( 'auto_increment' !== strtolower( (string) ( $column['extra'] ?? '' ) ) ) {
			return false;
		}

		if ( ! $this->is_mysql_integer_family_column_type( (string) ( $column['type'] ?? '' ) ) ) {
			return false;
		}

		$existing = $this->get_existing_dbdelta_column_identity_metadata( $table_schema, $table_name, $old_column );
		if ( null === $existing || ! $this->is_existing_dbdelta_column_identity( $existing ) ) {
			return false;
		}

		$existing_mysql_type = (string) ( $existing['mysql_column_type'] ?? '' );
		if ( '' !== $existing_mysql_type ) {
			return $this->is_mysql_integer_family_column_type( $existing_mysql_type );
		}

		return $this->is_postgresql_integer_family_data_type( (string) ( $existing['data_type'] ?? '' ) );
	}

	/**
	 * Get catalog and MySQL metadata for an existing dbDelta column.
	 *
	 * @param string $table_schema Table schema.
	 * @param string $table_name   Table name.
	 * @param string $column_name  Column name.
	 * @return array|null Existing column metadata, or null.
	 */
	private function get_existing_dbdelta_column_identity_metadata( string $table_schema, string $table_name, string $column_name ): ?array {
		$this->ensure_mysql_schema_metadata_tables();

		$stmt = $this->connection->query(
			sprintf(
				'SELECT
					c.data_type,
					c.is_identity,
					c.column_default,
					cm.column_type AS mysql_column_type,
					cm.extra AS mysql_extra
				FROM information_schema.columns c
				LEFT JOIN %s cm
					ON cm.table_schema = c.table_schema
					AND cm.table_name = c.table_name
					AND cm.column_name = c.column_name
				WHERE c.table_schema = ?
					AND c.table_name = ?
					AND c.column_name = ?',
				$this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE )
			),
			array( $table_schema, $table_name, $column_name )
		);

		$row = $stmt->fetch( PDO::FETCH_ASSOC );
		return false === $row ? null : $row;
	}

	/**
	 * Check whether existing metadata describes a PostgreSQL identity column.
	 *
	 * @param array $metadata Existing column metadata.
	 * @return bool Whether the column is identity/auto_increment.
	 */
	private function is_existing_dbdelta_column_identity( array $metadata ): bool {
		if ( 'auto_increment' === strtolower( (string) ( $metadata['mysql_extra'] ?? '' ) ) ) {
			return true;
		}

		if ( 'YES' === strtoupper( (string) ( $metadata['is_identity'] ?? '' ) ) ) {
			return true;
		}

		$column_default = ltrim( (string) ( $metadata['column_default'] ?? '' ) );
		return 0 === stripos( $column_default, 'nextval(' );
	}

	/**
	 * Check whether a MySQL column type is part of the integer family.
	 *
	 * @param string $column_type MySQL column type.
	 * @return bool Whether the type is integer-like.
	 */
	private function is_mysql_integer_family_column_type( string $column_type ): bool {
		$column_type = strtolower( trim( $column_type ) );
		$column_type = preg_replace( '/\s+unsigned\b/i', '', $column_type );
		$column_type = trim( (string) $column_type );

		return (bool) preg_match( '/^(?:bigint|int|integer|mediumint|smallint|tinyint)(?:\(\d+\))?$/', $column_type );
	}

	/**
	 * Check whether a PostgreSQL catalog data type is integer-like.
	 *
	 * @param string $data_type PostgreSQL information_schema data_type.
	 * @return bool Whether the type is integer-like.
	 */
	private function is_postgresql_integer_family_data_type( string $data_type ): bool {
		return in_array( strtolower( trim( $data_type ) ), array( 'bigint', 'integer', 'smallint' ), true );
	}

	/**
	 * Translate supported DROP TABLE statements and expose dropped table names.
	 *
	 * @param string $query MySQL DROP TABLE query.
	 * @return array{statements: string[], tables: string[], metadata_targets: array[]}|null Translation, or null when unsupported.
	 */
	private function translate_mysql_drop_table_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::DROP_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			throw new InvalidArgumentException( 'Unsupported DROP TABLE statement.' );
		}

		$position  = 1;
		$temporary = false;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::TEMPORARY_SYMBOL === $tokens[ $position ]->id ) {
			$temporary = true;
			++$position;
		}

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::TABLE_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		++$position;
		$if_exists = false;
		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::IF_SYMBOL === $tokens[ $position ]->id
			&& WP_MySQL_Lexer::EXISTS_SYMBOL === $tokens[ $position + 1 ]->id
		) {
			$if_exists = true;
			$position += 2;
		}

		$table_names       = array();
		$table_identifiers = array();
		$metadata_targets  = array();
		while ( $position < $statement_end ) {
			$reference_start = $position;
			$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position );
			if ( null === $table_reference ) {
				throw new InvalidArgumentException( 'Unsupported DROP TABLE statement.' );
			}

			$table_name    = $table_reference['table'];
			$table_names[] = $table_name;

			if ( $temporary ) {
				if ( null !== $table_reference['schema'] ) {
					$this->get_mysql_writable_table_backend_schema( $table_reference, 'DROP TABLE' );
				}

				$table_identifiers[] = $this->get_temporary_drop_table_identifier( $table_name );
				foreach ( $this->get_mysql_schema_metadata_drop_targets( array( $table_name ), true ) as $target ) {
					$metadata_targets[] = $target;
				}
			} else {
				$table_schema        = $this->get_mysql_writable_table_backend_schema( $table_reference, 'DROP TABLE' );
				$table_identifiers[] = null === $table_reference['schema']
					? $this->connection->quote_identifier( $table_name )
					: $this->get_postgresql_schema_identifier( $table_schema, $table_name );
				$metadata_targets[]  = array(
					'schema' => $table_schema,
					'table'  => $table_name,
				);
			}

			if ( $position === $reference_start ) {
				throw new InvalidArgumentException( 'Unsupported DROP TABLE statement.' );
			}

			if ( $position === $statement_end ) {
				break;
			}

			if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::COMMA_SYMBOL !== $tokens[ $position ]->id ) {
				throw new InvalidArgumentException( 'Unsupported DROP TABLE statement.' );
			}

			++$position;
			if ( $position === $statement_end ) {
				throw new InvalidArgumentException( 'Unsupported DROP TABLE statement.' );
			}
		}

		if ( array() === $table_names ) {
			throw new InvalidArgumentException( 'Unsupported DROP TABLE statement.' );
		}

		$statements = array();
		foreach ( $table_identifiers as $table_identifier ) {
			$statements[] = sprintf(
				'DROP TABLE %s%s',
				$if_exists ? 'IF EXISTS ' : '',
				$table_identifier
			);
		}

		return array(
			'statements'       => $statements,
			'tables'           => $table_names,
			'metadata_targets' => $metadata_targets,
		);
	}

	/**
	 * Translate supported standalone MySQL DROP INDEX statements to PostgreSQL.
	 *
	 * @param string $query MySQL DROP INDEX query.
	 * @return array{statements: string[], metadata: array}|null Translation, or null when this is not DROP INDEX.
	 */
	private function translate_mysql_drop_index_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::DROP_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		if ( ! isset( $tokens[1] ) || WP_MySQL_Lexer::INDEX_SYMBOL !== $tokens[1]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 2 );
		if ( null === $statement_end ) {
			throw new InvalidArgumentException( 'Unsupported DROP INDEX statement.' );
		}

		$position   = 2;
		$index_name = $this->get_mysql_index_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $index_name ) {
			throw new InvalidArgumentException( 'Unsupported DROP INDEX statement.' );
		}

		++$position;
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::ON_SYMBOL !== $tokens[ $position ]->id ) {
			throw new InvalidArgumentException( 'Unsupported DROP INDEX statement.' );
		}

		++$position;
		$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position );
		if ( null === $table_reference ) {
			throw new InvalidArgumentException( 'Unsupported DROP INDEX statement.' );
		}

		while ( $position < $statement_end ) {
			if ( ! $this->consume_mysql_supported_index_lock_and_algorithm_options( $tokens, $position, $statement_end ) ) {
				throw new InvalidArgumentException( 'Unsupported DROP INDEX statement.' );
			}
		}

		if ( 'PRIMARY' === strtoupper( $index_name ) ) {
			return $this->get_mysql_drop_primary_key_index_translation( $table_reference, 'DROP INDEX' );
		}

		return $this->get_mysql_drop_index_translation( $table_reference, $index_name, 'DROP INDEX' );
	}

	/**
	 * Get an explicit unsupported error for unclaimed MySQL DROP statements.
	 *
	 * Supported DROP TABLE/DROP INDEX forms and the narrow procedure shim are
	 * dispatched before this guard.
	 *
	 * @param string $query MySQL query.
	 * @return string|null Unsupported error message, or null when not guarded.
	 */
	private function get_unsupported_mysql_drop_statement_message( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::DROP_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$position = 1;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::TEMPORARY_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		switch ( $tokens[ $position ]->id ?? null ) {
			case WP_MySQL_Lexer::TABLE_SYMBOL:
			case WP_MySQL_Lexer::INDEX_SYMBOL:
				return null;

			case WP_MySQL_Lexer::DATABASE_SYMBOL:
			case WP_MySQL_Lexer::SCHEMA_SYMBOL:
				return 'Unsupported DROP DATABASE statement.';

			case WP_MySQL_Lexer::VIEW_SYMBOL:
				return 'Unsupported DROP VIEW statement.';

			case WP_MySQL_Lexer::PROCEDURE_SYMBOL:
				return 'Unsupported DROP PROCEDURE statement.';

			case WP_MySQL_Lexer::FUNCTION_SYMBOL:
				return 'Unsupported DROP FUNCTION statement.';

			case WP_MySQL_Lexer::TRIGGER_SYMBOL:
				return 'Unsupported DROP TRIGGER statement.';

			case WP_MySQL_Lexer::EVENT_SYMBOL:
				return 'Unsupported DROP EVENT statement.';

			case WP_MySQL_Lexer::USER_SYMBOL:
				return 'Unsupported DROP USER statement.';

			case WP_MySQL_Lexer::ROLE_SYMBOL:
				return 'Unsupported DROP ROLE statement.';

			case WP_MySQL_Lexer::SPATIAL_SYMBOL:
				if (
					isset( $tokens[ $position + 1 ], $tokens[ $position + 2 ] )
					&& WP_MySQL_Lexer::REFERENCE_SYMBOL === $tokens[ $position + 1 ]->id
					&& WP_MySQL_Lexer::SYSTEM_SYMBOL === $tokens[ $position + 2 ]->id
				) {
					return 'Unsupported DROP SPATIAL REFERENCE SYSTEM statement.';
				}
				return null;

			case WP_MySQL_Lexer::TABLESPACE_SYMBOL:
				return 'Unsupported DROP TABLESPACE statement.';

			case WP_MySQL_Lexer::UNDO_SYMBOL:
				return 'Unsupported DROP UNDO TABLESPACE statement.';

			case WP_MySQL_Lexer::SERVER_SYMBOL:
				return 'Unsupported DROP SERVER statement.';

			case WP_MySQL_Lexer::LOGFILE_SYMBOL:
				return 'Unsupported DROP LOGFILE statement.';
		}

		return null;
	}

	/**
	 * Build PostgreSQL primary-key DROP SQL and metadata cleanup target.
	 *
	 * @param array{schema: string|null, table: string} $table_reference MySQL table reference.
	 * @param string                                   $statement_type  Statement type for fail-closed error messages.
	 * @return array{statements: string[], metadata: array} Drop primary-key translation.
	 */
	private function get_mysql_drop_primary_key_index_translation( array $table_reference, string $statement_type ): array {
		$table_schema = $this->get_mysql_writable_table_backend_schema( $table_reference, $statement_type );
		$table_name   = $table_reference['table'];

		return array(
			'statements' => array(
				sprintf(
					'ALTER TABLE %s DROP CONSTRAINT %s',
					null === $table_reference['schema']
						? $this->connection->quote_identifier( $table_name )
						: $this->get_postgresql_schema_identifier( $table_schema, $table_name ),
					$this->connection->quote_identifier(
						$this->get_postgresql_primary_key_constraint_name( $table_schema, $table_name )
					)
				),
			),
			'metadata'   => array(
				'schema' => $table_schema,
				'table'  => $table_name,
				'index'  => 'PRIMARY',
			),
		);
	}

	/**
	 * Build PostgreSQL DROP INDEX SQL and metadata cleanup target.
	 *
	 * @param array{schema: string|null, table: string} $table_reference MySQL table reference.
	 * @param string                                   $index_name      MySQL index name.
	 * @param string                                   $statement_type  Statement type for fail-closed error messages.
	 * @return array{statements: string[], metadata: array} Drop index translation.
	 */
	private function get_mysql_drop_index_translation( array $table_reference, string $index_name, string $statement_type ): array {
		if ( 'PRIMARY' === strtoupper( $index_name ) ) {
			throw new InvalidArgumentException( 'Unsupported ' . $statement_type . ' statement.' );
		}

		$table_schema = $this->get_mysql_writable_table_backend_schema( $table_reference, $statement_type );
		$table_name   = $table_reference['table'];
		$index_type   = $this->get_stored_mysql_index_type( $table_schema, $table_name, $index_name );

		$statements = array();
		if ( null === $index_type || ! $this->is_mysql_metadata_only_index_type( $index_type ) ) {
			$statements[] = 'DROP INDEX ' . $this->get_postgresql_schema_identifier( $table_schema, $table_name . '__' . $index_name );
		}

		return array(
			'statements' => $statements,
			'metadata'   => array(
				'schema' => $table_schema,
				'table'  => $table_name,
				'index'  => $index_name,
			),
		);
	}

	/**
	 * Translate supported MySQL RENAME TABLE statements to PostgreSQL.
	 *
	 * @param string $query MySQL query.
	 * @return array{statements: string[], metadata: array{schema: string, old_table: string, new_table: string}}|null Translation, or null when this is not RENAME TABLE.
	 */
	private function translate_mysql_rename_table_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0], $tokens[1] )
			|| WP_MySQL_Lexer::RENAME_SYMBOL !== $tokens[0]->id
			|| WP_MySQL_Lexer::TABLE_SYMBOL !== $tokens[1]->id
		) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 2 );
		if ( null === $statement_end ) {
			throw new InvalidArgumentException( 'Unsupported RENAME TABLE statement.' );
		}

		$position            = 2;
		$old_table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position, true );
		if ( null === $old_table_reference ) {
			throw new InvalidArgumentException( 'Unsupported RENAME TABLE statement.' );
		}

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::TO_SYMBOL !== $tokens[ $position ]->id ) {
			throw new InvalidArgumentException( 'Unsupported RENAME TABLE statement.' );
		}

		++$position;
		$new_table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position, true );
		if ( null === $new_table_reference || $position !== $statement_end ) {
			throw new InvalidArgumentException( 'Unsupported RENAME TABLE statement.' );
		}

		$table_schema     = $this->get_mysql_writable_table_backend_schema( $old_table_reference, 'RENAME TABLE' );
		$new_table_schema = $this->get_mysql_rename_table_target_backend_schema( $new_table_reference, $table_schema, 'RENAME TABLE' );
		if ( $new_table_schema !== $table_schema ) {
			throw new InvalidArgumentException( 'Unsupported RENAME TABLE statement.' );
		}

		$old_table_name = $old_table_reference['table'];
		$new_table_name = $new_table_reference['table'];

		return array(
			'statements' => $this->get_mysql_rename_table_statements( $table_schema, $old_table_name, $new_table_name ),
			'metadata'   => array(
				'schema'    => $table_schema,
				'old_table' => $old_table_name,
				'new_table' => $new_table_name,
			),
		);
	}

	/**
	 * Resolve the backend schema for the new side of a table rename.
	 *
	 * @param array  $table_reference Parsed target table reference.
	 * @param string $default_schema  Schema of the source table.
	 * @param string $statement_type  Statement type for error messages.
	 * @return string Backend schema name.
	 */
	private function get_mysql_rename_table_target_backend_schema( array $table_reference, string $default_schema, string $statement_type ): string {
		$requested_schema = $table_reference['schema'];
		if ( null === $requested_schema ) {
			return $default_schema;
		}

		if ( 0 === strcasecmp( $requested_schema, 'information_schema' ) ) {
			throw new InvalidArgumentException( 'Unsupported information_schema query.' );
		}

		if (
			0 === strcasecmp( $requested_schema, $this->main_db_name )
			|| 0 === strcasecmp( $requested_schema, 'public' )
		) {
			return 'public';
		}

		throw new InvalidArgumentException( sprintf( 'Unsupported %s statement.', $statement_type ) );
	}

	/**
	 * Build PostgreSQL statements for a MySQL table rename.
	 *
	 * @param string $table_schema   Backend schema name.
	 * @param string $old_table_name Old table name.
	 * @param string $new_table_name New table name.
	 * @return string[] PostgreSQL statements.
	 */
	private function get_mysql_rename_table_statements( string $table_schema, string $old_table_name, string $new_table_name ): array {
		$statements = array(
			sprintf(
				'ALTER TABLE %s RENAME TO %s',
				$this->get_postgresql_schema_identifier( $table_schema, $old_table_name ),
				$this->connection->quote_identifier( $new_table_name )
			),
		);

		return array_merge(
			$statements,
			$this->get_mysql_rename_table_index_statements( $table_schema, $old_table_name, $new_table_name )
		);
	}

	/**
	 * Build PostgreSQL index rename statements for indexes whose physical names include the table name.
	 *
	 * @param string $table_schema   Backend schema name.
	 * @param string $old_table_name Old table name.
	 * @param string $new_table_name New table name.
	 * @return string[] PostgreSQL ALTER INDEX statements.
	 */
	private function get_mysql_rename_table_index_statements( string $table_schema, string $old_table_name, string $new_table_name ): array {
		$this->ensure_mysql_schema_metadata_tables();

		$stmt = $this->connection->query(
			sprintf(
				'SELECT DISTINCT key_name, index_type
				FROM %s
				WHERE table_schema = ? AND table_name = ? AND UPPER(key_name) <> \'PRIMARY\'
				ORDER BY key_name',
				$this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE )
			),
			array( $table_schema, $old_table_name )
		);

		$statements = array();
		foreach ( $stmt->fetchAll( PDO::FETCH_ASSOC ) as $row ) {
			$index_type = (string) $row['index_type'];
			if ( $this->is_mysql_metadata_only_index_type( $index_type ) ) {
				continue;
			}

			$key_name     = (string) $row['key_name'];
			$statements[] = sprintf(
				'ALTER INDEX %s RENAME TO %s',
				$this->get_postgresql_schema_identifier( $table_schema, $old_table_name . '__' . $key_name ),
				$this->connection->quote_identifier( $new_table_name . '__' . $key_name )
			);
		}

		return $statements;
	}

	/**
	 * Get a stored MySQL index type from side metadata.
	 *
	 * @param string $table_schema Metadata schema.
	 * @param string $table_name   Table name.
	 * @param string $index_name   Index name.
	 * @return string|null Stored index type, or null when unavailable.
	 */
	private function get_stored_mysql_index_type( string $table_schema, string $table_name, string $index_name ): ?string {
		$this->ensure_mysql_schema_metadata_tables();

		$stmt = $this->connection->query(
			sprintf(
				'SELECT index_type FROM %s WHERE table_schema = ? AND table_name = ? AND LOWER(key_name) = LOWER(?) ORDER BY seq_in_index LIMIT 1',
				$this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE )
			),
			array( $table_schema, $table_name, $index_name )
		);

		$index_type = $stmt->fetchColumn();
		return false === $index_type ? null : (string) $index_type;
	}

	/**
	 * Get the MySQL metadata rows that should be removed after a DROP TABLE.
	 *
	 * @param string[] $table_names Table names.
	 * @param bool     $temporary   Whether the DROP TABLE explicitly targets temporary tables.
	 * @return array[] Metadata targets.
	 */
	private function get_mysql_schema_metadata_drop_targets( array $table_names, bool $temporary ): array {
		$targets = array();

		foreach ( $table_names as $table_name ) {
			$temporary_schema = $this->get_active_temporary_table_schema( $table_name );
			if ( null !== $temporary_schema ) {
				$targets[] = array(
					'schema' => $temporary_schema,
					'table'  => $table_name,
				);
				continue;
			}

			if ( ! $temporary ) {
				$targets[] = array(
					'schema' => 'public',
					'table'  => $table_name,
				);
			}
		}

		return $targets;
	}

	/**
	 * Get the backend table identifier for a MySQL DROP TEMPORARY TABLE target.
	 *
	 * @param string $table_name MySQL table identifier value.
	 * @return string PostgreSQL table identifier constrained to the temporary schema.
	 */
	private function get_temporary_drop_table_identifier( string $table_name ): string {
		return $this->get_temporary_drop_table_schema_name() . '.' . $this->connection->quote_identifier( $table_name );
	}

	/**
	 * Get the backend temporary schema name.
	 *
	 * @return string Backend temporary schema name.
	 */
	private function get_temporary_drop_table_schema_name(): string {
		$driver_name = (string) $this->connection->get_pdo()->getAttribute( PDO::ATTR_DRIVER_NAME );

		if ( 'sqlite' === $driver_name ) {
			return 'temp';
		}

		return 'pg_temp';
	}

	/**
	 * Extract original bytes for a bounded MySQL token range.
	 *
	 * @param string           $query  Original MySQL query fragment.
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token position, inclusive.
	 * @param int              $end    Final token position, exclusive.
	 * @return string Original query bytes for the token range.
	 */
	private function get_mysql_token_range_bytes( string $query, array $tokens, int $start, int $end ): string {
		if ( $start >= $end || ! isset( $tokens[ $start ], $tokens[ $end - 1 ] ) ) {
			return '';
		}

		$range_start = $tokens[ $start ]->start;
		$range_end   = $tokens[ $end - 1 ]->start + $tokens[ $end - 1 ]->length;
		return substr( $query, $range_start, $range_end - $range_start );
	}

	/**
	 * Translate a MySQL column definition fragment via the CREATE TABLE translator.
	 *
	 * @param string      $definition MySQL column definition.
	 * @param string|null $table_name  Table name for inline foreign key names.
	 * @return array{sql: string, metadata: array, indexes: array, foreign_keys: array, checks: array}|null Translated column, or null when unsupported.
	 */
	private function translate_mysql_column_definition_fragment( string $definition, ?string $table_name = null ): ?array {
		$definition = $this->trim_mysql_statement_fragment( $definition );
		$translator = new WP_PostgreSQL_Create_Table_Translator( $this->active_sql_modes );
		$wrapper_table = $table_name ?? '__wp_dbdelta_column';
		$wrapper       = sprintf( 'CREATE TABLE %s (%s)', $this->quote_mysql_identifier( $wrapper_table ), $definition );

		$statements = $translator->translate_schema( $wrapper );
		$metadata   = $translator->extract_schema_metadata( $wrapper, true );
		if ( ! isset( $metadata[0]['columns'][0] ) ) {
			return null;
		}

		return array(
			'sql'          => $this->get_first_translated_create_table_definition( $statements[0] ),
			'metadata'     => $metadata[0]['columns'][0],
			'indexes'      => $metadata[0]['indexes'] ?? array(),
			'foreign_keys' => $metadata[0]['foreign_keys'] ?? array(),
			'checks'       => $metadata[0]['checks'] ?? array(),
		);
	}

	/**
	 * Replace a translated column fragment constraint name.
	 *
	 * @param string $sql      Column definition SQL.
	 * @param string $old_name Existing constraint name.
	 * @param string $new_name Replacement constraint name.
	 * @return string Updated column definition SQL.
	 */
	private function replace_mysql_column_fragment_constraint_name( string $sql, string $old_name, string $new_name ): string {
		$old_sql = 'CONSTRAINT ' . $this->connection->quote_identifier( $old_name );
		$new_sql = 'CONSTRAINT ' . $this->connection->quote_identifier( $new_name );

		if ( false === strpos( $sql, $old_sql ) ) {
			throw new InvalidArgumentException( 'Translated column definition has an unexpected constraint name.' );
		}

		return str_replace( $old_sql, $new_sql, $sql );
	}

	/**
	 * Translate a MySQL index definition fragment via the CREATE TABLE translator.
	 *
	 * @param string $table_name Table name receiving the index.
	 * @param string $definition MySQL index definition.
	 * @return array{statements: string[], metadata: array}|null Translated index, or null when unsupported.
	 */
	private function translate_mysql_index_definition_fragment( string $table_name, string $definition ): ?array {
		$definition = $this->trim_mysql_statement_fragment( $definition );
		$translator = new WP_PostgreSQL_Create_Table_Translator( $this->active_sql_modes );
		$wrapper    = 'CREATE TABLE __wp_dbdelta_index (__wp_dummy int, ' . $definition . ')';

		$metadata = $translator->extract_schema_metadata( $wrapper, true );
		if ( ! isset( $metadata[0]['indexes'][0] ) ) {
			return null;
		}

		$index   = $metadata[0]['indexes'][0];
		$columns = array();
		foreach ( $index['columns'] as $column ) {
			$column_sql = $this->get_mysql_index_key_part_sql(
				(string) $column['column_name'],
				'0' === (string) $index['non_unique'] ? $column['sub_part'] : null
			);
			if ( 'D' === strtoupper( (string) ( $column['collation'] ?? '' ) ) ) {
				$column_sql .= ' DESC';
			}

			$columns[] = $column_sql;
		}

		if ( 'PRIMARY' === strtoupper( $index['name'] ) ) {
			$statement  = sprintf(
				'ALTER TABLE %s ADD PRIMARY KEY (%s)',
				$this->connection->quote_identifier( $table_name ),
				implode( ', ', $columns )
			);
			$statements = array( $statement );
		} elseif ( $this->is_mysql_metadata_only_index_type( $index['index_type'] ) ) {
			$statements = array();
		} else {
			$statement  = sprintf(
				'CREATE %sINDEX %s ON %s (%s)',
				'0' === $index['non_unique'] ? 'UNIQUE ' : '',
				$this->connection->quote_identifier( $table_name . '__' . $index['name'] ),
				$this->connection->quote_identifier( $table_name ),
				implode( ', ', $columns )
			);
			$statements = array( $statement );
		}

		return array(
			'statements' => $statements,
			'metadata'   => $index,
		);
	}

	/**
	 * Extract the first definition from a translated CREATE TABLE statement.
	 *
	 * @param string $create_table_sql Translated CREATE TABLE statement.
	 * @return string First definition line.
	 */
	private function get_first_translated_create_table_definition( string $create_table_sql ): string {
		if ( ! preg_match( "/\\(\\n  (?P<definitions>.*)\\n\\)\\z/s", $create_table_sql, $matches ) ) {
			throw new InvalidArgumentException( 'Translated CREATE TABLE statement has an unexpected shape.' );
		}

		$definitions = explode( ",\n  ", $matches['definitions'] );
		return $definitions[0];
	}

	/**
	 * Extract PostgreSQL type SQL from a translated column definition line.
	 *
	 * @param string $definition_line Translated column definition line.
	 * @return string PostgreSQL type SQL.
	 */
	private function get_translated_column_type_from_definition_line( string $definition_line ): string {
		if ( ! preg_match( '/^"(?:""|[^"])+"\s+(?P<definition>.+)$/s', $definition_line, $matches ) ) {
			return '';
		}

		$definition = $this->remove_translated_inline_key_constraints_from_column_definition( $matches['definition'] );
		$stop_at    = strlen( $definition );
		foreach ( array( ' GENERATED ', ' NOT NULL', ' DEFAULT ' ) as $marker ) {
			$position = stripos( $definition, $marker );
			if ( false !== $position && $position < $stop_at ) {
				$stop_at = $position;
			}
		}

		return trim( substr( $definition, 0, $stop_at ) );
	}

	/**
	 * Extract PostgreSQL DEFAULT SQL from a translated column definition line.
	 *
	 * @param string $definition_line Translated column definition line.
	 * @return string|null Default SQL, or null when absent.
	 */
	private function get_translated_column_default_from_definition_line( string $definition_line ): ?string {
		$definition_line = preg_replace(
			'/\s+GENERATED\s+BY\s+DEFAULT\s+AS\s+IDENTITY\b/i',
			'',
			$definition_line
		);
		$definition_line = $this->remove_translated_inline_key_constraints_from_column_definition( $definition_line );

		if ( ! preg_match( '/\sDEFAULT\s+(?P<default>.+)$/is', $definition_line, $matches ) ) {
			return null;
		}

		return trim( $matches['default'] );
	}

	/**
	 * Remove inline key fragments from translated column SQL.
	 *
	 * @param string $definition Translated column definition or definition tail.
	 * @return string Definition without inline PRIMARY/UNIQUE key fragments.
	 */
	private function remove_translated_inline_key_constraints_from_column_definition( string $definition ): string {
		return preg_replace(
			array(
				'/\s+PRIMARY\s+KEY\b/i',
				'/\s+UNIQUE\b/i',
			),
			'',
			$definition
		);
	}

	/**
	 * Translate a simple MySQL DEFAULT fragment.
	 *
	 * @param string $fragment Default expression fragment.
	 * @return array{sql: string, metadata: string|null}|null Translated default, or null when unsupported.
	 */
	private function translate_mysql_default_fragment( string $fragment ): ?array {
		$fragment = $this->trim_mysql_statement_fragment( $fragment );
		$tokens   = $this->get_mysql_tokens( $fragment );
		$end      = $this->get_mysql_statement_end_position( $tokens, 0 );

		$current_timestamp_metadata = $this->get_mysql_current_timestamp_default_fragment_metadata( $tokens, $end );
		if ( null !== $current_timestamp_metadata ) {
			return array(
				'sql'      => "TO_CHAR(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')",
				'metadata' => $current_timestamp_metadata,
			);
		}

		if ( 1 !== $end ) {
			return null;
		}

		$token = $tokens[0];
		if ( WP_MySQL_Lexer::NULL_SYMBOL === $token->id ) {
			return array(
				'sql'      => 'NULL',
				'metadata' => null,
			);
		}

		if (
			WP_MySQL_Lexer::SINGLE_QUOTED_TEXT === $token->id
			|| WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT === $token->id
			|| WP_MySQL_Lexer::INT_NUMBER === $token->id
			|| WP_MySQL_Lexer::LONG_NUMBER === $token->id
			|| WP_MySQL_Lexer::ULONGLONG_NUMBER === $token->id
			|| WP_MySQL_Lexer::DECIMAL_NUMBER === $token->id
			|| WP_MySQL_Lexer::FLOAT_NUMBER === $token->id
		) {
			return array(
				'sql'      => $this->translate_mysql_token_to_postgresql( $token ),
				'metadata' => $token->get_value(),
			);
		}

		return null;
	}

	/**
	 * Get metadata for a current timestamp DEFAULT fragment.
	 *
	 * @param WP_MySQL_Token[] $tokens Default fragment tokens.
	 * @param int|null         $end    Statement end.
	 * @return string|null Metadata value, or null.
	 */
	private function get_mysql_current_timestamp_default_fragment_metadata( array $tokens, ?int $end ): ?string {
		if ( null === $end ) {
			return null;
		}

		if (
			1 === $end
			&& isset( $tokens[0] )
			&& $this->is_mysql_current_timestamp_token( $tokens[0] )
		) {
			return 'CURRENT_TIMESTAMP';
		}

		if (
			3 === $end
			&& isset( $tokens[0], $tokens[1], $tokens[2] )
			&& $this->is_mysql_current_timestamp_token( $tokens[0] )
			&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[1]->id
			&& WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[2]->id
		) {
			return 'CURRENT_TIMESTAMP';
		}

		if (
			3 === $end
			&& isset( $tokens[0], $tokens[1], $tokens[2] )
			&& WP_MySQL_Lexer::NOW_SYMBOL === $tokens[0]->id
			&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[1]->id
			&& WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[2]->id
		) {
			return 'now()';
		}

		return null;
	}

	/**
	 * Check whether a token represents CURRENT_TIMESTAMP.
	 *
	 * @param WP_MySQL_Token $token Token.
	 * @return bool Whether the token is CURRENT_TIMESTAMP.
	 */
	private function is_mysql_current_timestamp_token( WP_MySQL_Token $token ): bool {
		return WP_MySQL_Lexer::CURRENT_TIMESTAMP_SYMBOL === $token->id
			|| (
				WP_MySQL_Lexer::NOW_SYMBOL === $token->id
				&& 'CURRENT_TIMESTAMP' === strtoupper( $token->get_value() )
			);
	}

	/**
	 * Parse a comma-separated list of simple MySQL identifiers.
	 *
	 * @param string $identifiers Identifier list.
	 * @return string[]|null Identifier values, or null when unsupported.
	 */
	private function parse_mysql_identifier_csv( string $identifiers ): ?array {
		$values = array();

		foreach ( explode( ',', $identifiers ) as $identifier ) {
			$identifier = trim( $identifier );
			if ( preg_match( '/^`([^`]+)`$/', $identifier, $matches ) ) {
				$values[] = $matches[1];
				continue;
			}

			if ( preg_match( '/^[A-Za-z0-9_]+$/', $identifier ) ) {
				$values[] = $identifier;
				continue;
			}

			return null;
		}

		return $values;
	}

	/**
	 * Trim a MySQL statement fragment.
	 *
	 * @param string $fragment SQL fragment.
	 * @return string Trimmed fragment.
	 */
	private function trim_mysql_statement_fragment( string $fragment ): string {
		return rtrim( trim( $fragment ), "; \t\n\r\0\x0B" );
	}

	/**
	 * Emulate the narrow stored procedure surface used by WordPress tests.
	 *
	 * @param string $query              MySQL query.
	 * @param int    $fetch_mode         PDO fetch mode.
	 * @param array  ...$fetch_mode_args Additional fetch mode arguments.
	 * @return mixed|null Query result, or null when the query is not a supported procedure statement.
	 */
	private function handle_mysql_procedure_query( string $query, $fetch_mode = PDO::FETCH_OBJ, ...$fetch_mode_args ) {
		if ( preg_match( '/^\s*DROP\s+PROCEDURE\s+IF\s+EXISTS\s+`?([A-Za-z0-9_]+)`?\s*;?\s*$/i', $query, $matches ) ) {
			unset( $this->procedures[ strtolower( $matches[1] ) ] );
			$this->last_result      = 0;
			$this->last_column_meta = array();
			return $this->last_result;
		}

		if ( preg_match( '/^\s*CREATE\s+PROCEDURE\s+`?([A-Za-z0-9_]+)`?\s*\(\s*\)\s+BEGIN\s+(.*?)\s*;\s*END\s*;?\s*$/is', $query, $matches ) ) {
			$this->procedures[ strtolower( $matches[1] ) ] = trim( $matches[2] );
			$this->last_result                             = 0;
			$this->last_column_meta                        = array();
			return $this->last_result;
		}

		if ( preg_match( '/^\s*SHOW\s+CREATE\s+PROCEDURE\s+`?([A-Za-z0-9_]+)`?\s*;?\s*$/i', $query, $matches ) ) {
			$name = strtolower( $matches[1] );
			if ( ! isset( $this->procedures[ $name ] ) ) {
				$this->last_result      = array();
				$this->last_column_meta = array();
				return $this->last_result;
			}

			$this->last_result      = array(
				(object) array(
					'Procedure'        => $matches[1],
					'sql_mode'         => $this->get_sql_mode(),
					'Create Procedure' => 'CREATE PROCEDURE `' . $matches[1] . '`() BEGIN ' . $this->procedures[ $name ] . '; END',
				),
			);
			$this->last_column_meta = array();
			return $this->last_result;
		}

		if ( preg_match( '/^\s*CALL\s+`?([A-Za-z0-9_]+)`?\s*(?:\(\s*\))?\s*;?\s*$/i', $query, $matches ) ) {
			$name = strtolower( $matches[1] );
			if ( ! isset( $this->procedures[ $name ] ) ) {
				return null;
			}

			return $this->query( $this->procedures[ $name ], $fetch_mode, ...$fetch_mode_args );
		}

		return null;
	}

	/**
	 * Get the target database from a supported MySQL USE statement.
	 *
	 * @param string $query MySQL query.
	 * @return string|null Target database name, or null when this is not USE.
	 */
	private function get_mysql_use_database_name( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::USE_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$database_name = $this->get_mysql_identifier_token_value( $tokens[1] ?? null );
		if ( null === $database_name || ! $this->is_at_mysql_query_end( $tokens, 2 ) ) {
			throw new InvalidArgumentException( 'Unsupported USE statement.' );
		}

		return $database_name;
	}

	/**
	 * Get the table reference from a supported MySQL DESCRIBE/DESC statement.
	 *
	 * @param string $query MySQL query.
	 * @return array{schema: string, table: string}|null Table reference, or null when this is not DESCRIBE/DESC.
	 */
	private function get_describe_table_reference( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0] )
			|| (
				WP_MySQL_Lexer::DESCRIBE_SYMBOL !== $tokens[0]->id
				&& WP_MySQL_Lexer::DESC_SYMBOL !== $tokens[0]->id
			)
		) {
			return null;
		}

		$position        = 1;
		$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position );
		if ( null === $table_reference || ! $this->is_at_mysql_query_end( $tokens, $position ) ) {
			throw new InvalidArgumentException( 'Unsupported DESCRIBE statement.' );
		}

		return array(
			'schema' => $this->get_mysql_writable_table_backend_schema( $table_reference, 'DESCRIBE' ),
			'table'  => $table_reference['table'],
		);
	}

	/**
	 * Parse a supported MySQL SHOW TABLES statement.
	 *
	 * @param string $query MySQL query.
	 * @return array{full: bool, schema: string, database: string, like: string|null, where: array|null}|null SHOW TABLES options, or null when unsupported.
	 */
	private function get_show_tables_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::SHOW_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$position = 1;
		$is_full  = false;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::FULL_SYMBOL === $tokens[ $position ]->id ) {
			$is_full = true;
			++$position;
		}

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::TABLES_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		++$position;
		$schema_name   = 'public';
		$database_name = $this->db_name;
		if (
			isset( $tokens[ $position ] )
			&& (
				WP_MySQL_Lexer::FROM_SYMBOL === $tokens[ $position ]->id
				|| WP_MySQL_Lexer::IN_SYMBOL === $tokens[ $position ]->id
			)
		) {
			$database_name = $this->get_mysql_identifier_token_value( $tokens[ $position + 1 ] ?? null );
			if ( null === $database_name ) {
				throw new InvalidArgumentException( 'Unsupported SHOW TABLES statement.' );
			}

			if (
				0 !== strcasecmp( $database_name, $this->main_db_name )
				&& 0 !== strcasecmp( $database_name, 'public' )
				&& 0 !== strcasecmp( $database_name, 'information_schema' )
			) {
				throw new InvalidArgumentException( 'Unsupported SHOW TABLES statement.' );
			}

			$schema_name = 0 === strcasecmp( $database_name, 'information_schema' ) ? 'information_schema' : 'public';
			$position   += 2;
		}

		$like = null;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::LIKE_SYMBOL === $tokens[ $position ]->id ) {
			if (
				! isset( $tokens[ $position + 1 ] )
				|| (
					WP_MySQL_Lexer::SINGLE_QUOTED_TEXT !== $tokens[ $position + 1 ]->id
					&& WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT !== $tokens[ $position + 1 ]->id
				)
			) {
				return null;
			}

			$like      = $tokens[ $position + 1 ]->get_value();
			$position += 2;
		}

		$where = null;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::WHERE_SYMBOL === $tokens[ $position ]->id ) {
			if ( null !== $like ) {
				throw new InvalidArgumentException( 'Unsupported SHOW TABLES statement.' );
			}

			$allowed_columns = array(
				strtolower( 'Tables_in_' . $database_name ) => 'Tables_in_' . $database_name,
			);
			if ( $is_full ) {
				$allowed_columns['table_type'] = 'Table_type';
			}

			$where = $this->get_mysql_show_where_filters( $tokens, $position, $allowed_columns );
			if ( null === $where ) {
				$where = $this->get_mysql_show_where_expression_filter( $tokens, $position, $allowed_columns );
			}
			if ( null === $where ) {
				throw new InvalidArgumentException( 'Unsupported SHOW TABLES statement.' );
			}

			$position = $this->get_mysql_statement_end_position( $tokens, $position );
			if ( null === $position ) {
				throw new InvalidArgumentException( 'Unsupported SHOW TABLES statement.' );
			}
		}

		if ( ! $this->is_at_mysql_query_end( $tokens, $position ) ) {
			return null;
		}

		return array(
			'full'     => $is_full,
			'schema'   => $schema_name,
			'database' => $database_name,
			'like'     => $like,
			'where'    => $where,
		);
	}

	/**
	 * Parse a supported MySQL SHOW TABLE STATUS statement.
	 *
	 * @param string $query MySQL query.
	 * @return array{database: string, filter_type: string, filter_column: string|null, filter_pattern: string|null, filter_threshold: string|null, conditions?: array<int,array{column: string, operator: string, value: string}>}|null SHOW TABLE STATUS options, or null when this is not SHOW TABLE STATUS.
	 */
	private function get_show_table_status_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0], $tokens[1], $tokens[2] )
			|| WP_MySQL_Lexer::SHOW_SYMBOL !== $tokens[0]->id
			|| WP_MySQL_Lexer::TABLE_SYMBOL !== $tokens[1]->id
			|| WP_MySQL_Lexer::STATUS_SYMBOL !== $tokens[2]->id
		) {
			return null;
		}

		$position      = 3;
		$database_name = $this->db_name;
		if (
			isset( $tokens[ $position ] )
			&& (
				WP_MySQL_Lexer::FROM_SYMBOL === $tokens[ $position ]->id
				|| WP_MySQL_Lexer::IN_SYMBOL === $tokens[ $position ]->id
			)
		) {
			$database_name = $this->get_mysql_identifier_token_value( $tokens[ $position + 1 ] ?? null );
			if ( null === $database_name ) {
				throw new InvalidArgumentException( 'Unsupported SHOW TABLE STATUS statement.' );
			}

			$position += 2;
		}

		if (
			0 !== strcasecmp( $database_name, $this->main_db_name )
			&& 0 !== strcasecmp( $database_name, 'information_schema' )
		) {
			throw new InvalidArgumentException( 'Unsupported SHOW TABLE STATUS statement.' );
		}

		if ( $this->is_at_mysql_query_end( $tokens, $position ) ) {
			return array(
				'database'         => $database_name,
				'filter_type'      => 'all',
				'filter_column'    => null,
				'filter_pattern'   => null,
				'filter_threshold' => null,
			);
		}

		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::LIKE_SYMBOL === $tokens[ $position ]->id
			&& $this->is_mysql_quoted_text_token( $tokens[ $position + 1 ] )
			&& $this->is_at_mysql_query_end( $tokens, $position + 2 )
		) {
			return array(
				'database'         => $database_name,
				'filter_type'      => 'like',
				'filter_column'    => 'Name',
				'filter_pattern'   => $tokens[ $position + 1 ]->get_value(),
				'filter_threshold' => null,
			);
		}

		if (
			isset( $tokens[ $position ] )
			&& WP_MySQL_Lexer::WHERE_SYMBOL === $tokens[ $position ]->id
		) {
			$filter = $this->get_show_table_status_where_filter( $tokens, $position );
			if ( null !== $filter ) {
				$filter['database'] = $database_name;
				return $filter;
			}
		}

		throw new InvalidArgumentException( 'Unsupported SHOW TABLE STATUS statement.' );
	}

	/**
	 * Parse a supported SHOW TABLE STATUS WHERE clause.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position WHERE token position.
	 * @return array{filter_type: string, filter_column: string|null, filter_pattern: string|null, filter_threshold: string|null, conditions?: array<int,array{column: string, operator: string, value: string}>, predicate?: array}|null Parsed filter, or null when unsupported.
	 */
	private function get_show_table_status_where_filter( array $tokens, int $position ): ?array {
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::WHERE_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		$predicate_position = $position + 1;
		if ( ! isset( $tokens[ $predicate_position ] ) ) {
			return null;
		}

		$column = $this->get_mysql_show_output_column_name(
			$tokens[ $predicate_position ],
			array( 'auto_increment' => 'Auto_increment' )
		);
		if (
			'Auto_increment' === $column
			&& isset( $tokens[ $predicate_position + 1 ] )
			&& WP_MySQL_Lexer::GREATER_THAN_OPERATOR === $tokens[ $predicate_position + 1 ]->id
			&& isset( $tokens[ $predicate_position + 2 ] )
			&& $this->is_mysql_unsigned_integer_token( $tokens[ $predicate_position + 2 ] )
			&& $this->is_at_mysql_query_end( $tokens, $predicate_position + 3 )
		) {
			return array(
				'filter_type'      => 'auto_increment_gt',
				'filter_column'    => 'Auto_increment',
				'filter_pattern'   => null,
				'filter_threshold' => $tokens[ $predicate_position + 2 ]->get_value(),
			);
		}

		if (
			'Auto_increment' === $column
			&& isset( $tokens[ $predicate_position + 1 ] )
			&& WP_MySQL_Lexer::IS_SYMBOL === $tokens[ $predicate_position + 1 ]->id
			&& isset( $tokens[ $predicate_position + 2 ] )
			&& WP_MySQL_Lexer::NULL_SYMBOL === $tokens[ $predicate_position + 2 ]->id
			&& $this->is_at_mysql_query_end( $tokens, $predicate_position + 3 )
		) {
			return array(
				'filter_type'      => 'auto_increment_is_null',
				'filter_column'    => 'Auto_increment',
				'filter_pattern'   => null,
				'filter_threshold' => null,
			);
		}

		$allowed_columns = array(
			'name'            => 'Name',
			'engine'          => 'Engine',
			'version'         => 'Version',
			'row_format'      => 'Row_format',
			'rows'            => 'Rows',
			'avg_row_length'  => 'Avg_row_length',
			'data_length'     => 'Data_length',
			'max_data_length' => 'Max_data_length',
			'index_length'    => 'Index_length',
			'data_free'       => 'Data_free',
			'auto_increment'  => 'Auto_increment',
			'create_time'     => 'Create_time',
			'update_time'     => 'Update_time',
			'check_time'      => 'Check_time',
			'collation'       => 'Collation',
			'checksum'        => 'Checksum',
			'create_options'  => 'Create_options',
			'comment'         => 'Comment',
		);
		$numeric_columns  = array(
			'Version',
			'Rows',
			'Avg_row_length',
			'Data_length',
			'Max_data_length',
			'Index_length',
			'Data_free',
			'Auto_increment',
			'Checksum',
		);
		$where_expression = $this->get_mysql_show_where_expression_filter( $tokens, $position, $allowed_columns, $numeric_columns );
		if ( null !== $where_expression ) {
			return array(
				'filter_type'      => 'where_expression',
				'filter_column'    => null,
				'filter_pattern'   => null,
				'filter_threshold' => null,
				'predicate'        => $where_expression['predicate'],
			);
		}

		$where_filter = $this->get_mysql_show_where_filters(
			$tokens,
			$position,
			$allowed_columns,
			$numeric_columns
		);
		if ( null === $where_filter ) {
			return null;
		}

		return array(
			'filter_type'      => 'where',
			'filter_column'    => null,
			'filter_pattern'   => null,
			'filter_threshold' => null,
			'conditions'       => $where_filter,
		);
	}

	/**
	 * Parse a supported MySQL SHOW CREATE TABLE statement.
	 *
	 * @param string $query MySQL query.
	 * @return array{schema: string, table: string}|null SHOW CREATE TABLE options, or null when this is not SHOW CREATE TABLE.
	 */
	private function get_show_create_table_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0], $tokens[1] )
			|| WP_MySQL_Lexer::SHOW_SYMBOL !== $tokens[0]->id
			|| WP_MySQL_Lexer::CREATE_SYMBOL !== $tokens[1]->id
		) {
			return null;
		}

		if ( ! isset( $tokens[2] ) || WP_MySQL_Lexer::TABLE_SYMBOL !== $tokens[2]->id ) {
			return null;
		}

		$table_reference = $this->get_show_create_table_reference( $tokens, 3 );
		if ( null === $table_reference || ! $this->is_at_mysql_query_end( $tokens, $table_reference['position'] ) ) {
			throw new InvalidArgumentException( 'Unsupported SHOW CREATE TABLE statement.' );
		}

		$schema_name = $this->get_mysql_read_table_backend_schema( $table_reference['schema'] );
		if (
			! in_array( $schema_name, array( 'public', 'information_schema' ), true )
			&& 0 !== strcasecmp( $schema_name, $this->main_db_name )
		) {
			throw new InvalidArgumentException( 'Unsupported SHOW CREATE TABLE statement.' );
		}

		return array(
			'schema' => $schema_name,
			'table'  => $table_reference['table'],
		);
	}

	/**
	 * Parse a SHOW CREATE TABLE table reference.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Table reference start position.
	 * @return array{schema: string|null, table: string, position: int}|null Parsed reference, or null when unsupported.
	 */
	private function get_show_create_table_reference( array $tokens, int $position ): ?array {
		$first_identifier = $this->get_mysql_table_reference_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $first_identifier ) {
			return null;
		}

		++$position;
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::DOT_SYMBOL !== $tokens[ $position ]->id ) {
			return array(
				'schema'   => null,
				'table'    => $first_identifier,
				'position' => $position,
			);
		}

		$table_name = $this->get_mysql_table_reference_identifier_token_value( $tokens[ $position + 1 ] ?? null );
		if ( null === $table_name ) {
			return null;
		}

		return array(
			'schema'   => $first_identifier,
			'table'    => $table_name,
			'position' => $position + 2,
		);
	}

	/**
	 * Check whether a token is an unsigned integer literal.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token is an unsigned integer literal.
	 */
	private function is_mysql_unsigned_integer_token( WP_MySQL_Token $token ): bool {
		return in_array(
			$token->id,
			array(
				WP_MySQL_Lexer::INT_NUMBER,
				WP_MySQL_Lexer::LONG_NUMBER,
				WP_MySQL_Lexer::ULONGLONG_NUMBER,
			),
			true
		);
	}

	/**
	 * Parse a supported MySQL SHOW VARIABLES statement.
	 *
	 * @param string $query MySQL query.
	 * @return array{type: string, pattern: string|null, column?: string, conditions?: array[]}|null SHOW VARIABLES options, or null when this is not SHOW VARIABLES.
	 */
	private function get_show_variables_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0], $tokens[1] ) || WP_MySQL_Lexer::SHOW_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$position = 1;
		if (
			WP_MySQL_Lexer::GLOBAL_SYMBOL === $tokens[ $position ]->id
			|| WP_MySQL_Lexer::SESSION_SYMBOL === $tokens[ $position ]->id
		) {
			++$position;
		}

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::VARIABLES_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		++$position;
		if ( $this->is_at_mysql_query_end( $tokens, $position ) ) {
			return array(
				'type'    => 'all',
				'column'  => null,
				'pattern' => null,
			);
		}

		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::LIKE_SYMBOL === $tokens[ $position ]->id
			&& $this->is_mysql_quoted_text_token( $tokens[ $position + 1 ] )
			&& $this->is_at_mysql_query_end( $tokens, $position + 2 )
		) {
			return array(
				'type'    => 'like',
				'column'  => 'Variable_name',
				'pattern' => strtolower( $tokens[ $position + 1 ]->get_value() ),
			);
		}

		$allowed_columns = array(
			'variable_name' => 'Variable_name',
			'value'         => 'Value',
		);
		$where_filters   = $this->get_mysql_show_where_filters( $tokens, $position, $allowed_columns );
		if ( null !== $where_filters ) {
			return array(
				'type'       => 'where',
				'column'     => null,
				'pattern'    => null,
				'conditions' => $where_filters,
			);
		}

		$where_expression = $this->get_mysql_show_where_expression_filter( $tokens, $position, $allowed_columns );
		if ( null !== $where_expression ) {
			return $where_expression;
		}

		throw new InvalidArgumentException( 'Unsupported SHOW VARIABLES statement.' );
	}

	/**
	 * Parse a supported MySQL SHOW CHARACTER SET/SHOW CHARSET statement.
	 *
	 * @param string $query MySQL query.
	 * @return array{type: string, column: string|null, pattern: string|null}|null SHOW CHARACTER SET options, or null when this is not SHOW CHARACTER SET.
	 */
	private function get_show_character_set_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0], $tokens[1] ) || WP_MySQL_Lexer::SHOW_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$position = 1;
		if ( WP_MySQL_Lexer::CHARSET_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		} elseif (
			isset( $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::CHAR_SYMBOL === $tokens[ $position ]->id
			&& WP_MySQL_Lexer::SET_SYMBOL === $tokens[ $position + 1 ]->id
		) {
			$position += 2;
		} else {
			return null;
		}

		$allowed_columns = array(
			'charset'           => 'Charset',
			'description'       => 'Description',
			'default collation' => 'Default collation',
			'maxlen'            => 'Maxlen',
		);
		$filter          = $this->get_show_static_result_filter( $tokens, $position, 'Charset', $allowed_columns );
		if ( null === $filter ) {
			throw new InvalidArgumentException( 'Unsupported SHOW CHARACTER SET statement.' );
		}

		return $filter;
	}

	/**
	 * Parse a supported MySQL SHOW COLLATION statement.
	 *
	 * @param string $query MySQL query.
	 * @return array{type: string, column: string|null, pattern: string|null}|null SHOW COLLATION options, or null when this is not SHOW COLLATION.
	 */
	private function get_show_collation_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0], $tokens[1] )
			|| WP_MySQL_Lexer::SHOW_SYMBOL !== $tokens[0]->id
			|| WP_MySQL_Lexer::COLLATION_SYMBOL !== $tokens[1]->id
		) {
			return null;
		}

		$allowed_columns = array(
			'collation'     => 'Collation',
			'charset'       => 'Charset',
			'id'            => 'Id',
			'default'       => 'Default',
			'compiled'      => 'Compiled',
			'sortlen'       => 'Sortlen',
			'pad_attribute' => 'Pad_attribute',
		);
		$filter          = $this->get_show_static_result_filter( $tokens, 2, 'Collation', $allowed_columns );
		if ( null === $filter ) {
			throw new InvalidArgumentException( 'Unsupported SHOW COLLATION statement.' );
		}

		return $filter;
	}

	/**
	 * Parse a supported MySQL SHOW DATABASES/SHOW SCHEMAS statement.
	 *
	 * @param string $query MySQL query.
	 * @return array{type: string, column: string|null, pattern: string|null}|null SHOW DATABASES options, or null when this is not SHOW DATABASES.
	 */
	private function get_show_databases_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0], $tokens[1] )
			|| WP_MySQL_Lexer::SHOW_SYMBOL !== $tokens[0]->id
			|| (
				WP_MySQL_Lexer::DATABASES_SYMBOL !== $tokens[1]->id
				&& WP_MySQL_Lexer::SCHEMAS_SYMBOL !== $tokens[1]->id
			)
		) {
			return null;
		}

		$filter = $this->get_show_static_result_filter(
			$tokens,
			2,
			'Database',
			array( 'database' => 'Database' )
		);
		if ( null === $filter ) {
			throw new InvalidArgumentException( 'Unsupported SHOW DATABASES statement.' );
		}

		return $filter;
	}

	/**
	 * Parse a supported MySQL SHOW CREATE DATABASE/SCHEMA statement.
	 *
	 * @param string $query MySQL query.
	 * @return array{database: string, if_not_exists: bool}|null SHOW CREATE DATABASE options, or null when this is not SHOW CREATE DATABASE.
	 */
	private function get_show_create_database_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0], $tokens[1], $tokens[2] )
			|| WP_MySQL_Lexer::SHOW_SYMBOL !== $tokens[0]->id
			|| WP_MySQL_Lexer::CREATE_SYMBOL !== $tokens[1]->id
			|| (
				WP_MySQL_Lexer::DATABASE_SYMBOL !== $tokens[2]->id
				&& WP_MySQL_Lexer::SCHEMA_SYMBOL !== $tokens[2]->id
			)
		) {
			return null;
		}

		$position      = 3;
		$if_not_exists = false;
		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ], $tokens[ $position + 2 ] )
			&& WP_MySQL_Lexer::IF_SYMBOL === $tokens[ $position ]->id
			&& WP_MySQL_Lexer::NOT_SYMBOL === $tokens[ $position + 1 ]->id
			&& WP_MySQL_Lexer::EXISTS_SYMBOL === $tokens[ $position + 2 ]->id
		) {
			$if_not_exists = true;
			$position     += 3;
		}

		$database = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null, true );
		if ( null === $database || ! $this->is_at_mysql_query_end( $tokens, $position + 1 ) ) {
			throw new InvalidArgumentException( 'Unsupported SHOW CREATE DATABASE statement.' );
		}

		return array(
			'database'      => $database,
			'if_not_exists' => $if_not_exists,
		);
	}

	/**
	 * Parse a supported MySQL SHOW ENGINES statement.
	 *
	 * @param string $query MySQL query.
	 * @return array{type: string, column: string|null, pattern: string|null}|null SHOW ENGINES options, or null when this is not SHOW ENGINES.
	 */
	private function get_show_engines_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0], $tokens[1] ) || WP_MySQL_Lexer::SHOW_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$position = 1;
		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::STORAGE_SYMBOL === $tokens[ $position ]->id
			&& WP_MySQL_Lexer::ENGINES_SYMBOL === $tokens[ $position + 1 ]->id
		) {
			$position += 2;
		} elseif ( WP_MySQL_Lexer::ENGINES_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		} else {
			return null;
		}

		$allowed_columns = array(
			'engine'       => 'Engine',
			'support'      => 'Support',
			'comment'      => 'Comment',
			'transactions' => 'Transactions',
			'xa'           => 'XA',
			'savepoints'   => 'Savepoints',
		);
		$filter          = $this->get_show_static_result_filter( $tokens, $position, 'Engine', $allowed_columns );
		if ( null === $filter ) {
			throw new InvalidArgumentException( 'Unsupported SHOW ENGINES statement.' );
		}

		return $filter;
	}

	/**
	 * Parse a supported MySQL SHOW GRANTS statement.
	 *
	 * @param string $query MySQL query.
	 * @return array{}|null Empty options array, or null when this is not SHOW GRANTS.
	 */
	private function get_show_grants_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0], $tokens[1] )
			|| WP_MySQL_Lexer::SHOW_SYMBOL !== $tokens[0]->id
			|| WP_MySQL_Lexer::GRANTS_SYMBOL !== $tokens[1]->id
		) {
			return null;
		}

		if ( $this->is_at_mysql_query_end( $tokens, 2 ) ) {
			return array();
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 2 );
		if ( null === $statement_end ) {
			throw new InvalidArgumentException( 'Unsupported SHOW GRANTS statement.' );
		}

		$position = 2;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::FOR_SYMBOL === $tokens[ $position ]->id ) {
			$position = $this->parse_supported_show_grants_principal( $tokens, $position + 1, $statement_end );
			if ( null === $position ) {
				throw new InvalidArgumentException( 'Unsupported SHOW GRANTS statement.' );
			}
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::USING_SYMBOL === $tokens[ $position ]->id ) {
			$position = $this->parse_supported_show_grants_role_list( $tokens, $position + 1, $statement_end );
			if ( null === $position ) {
				throw new InvalidArgumentException( 'Unsupported SHOW GRANTS statement.' );
			}
		}

		if ( $position === $statement_end ) {
			return array();
		}

		throw new InvalidArgumentException( 'Unsupported SHOW GRANTS statement.' );
	}

	/**
	 * Parse the optional principal in a SHOW GRANTS statement.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First principal token.
	 * @param int              $end    Final statement token position, exclusive.
	 * @return int|null Position after the principal, or null when unsupported.
	 */
	private function parse_supported_show_grants_principal( array $tokens, int $start, int $end ): ?int {
		if ( ! isset( $tokens[ $start ] ) ) {
			return null;
		}

		if ( WP_MySQL_Lexer::CURRENT_USER_SYMBOL === $tokens[ $start ]->id ) {
			$position = $start + 1;
			if (
				isset( $tokens[ $position ], $tokens[ $position + 1 ] )
				&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id
				&& WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $position + 1 ]->id
			) {
				$position += 2;
			}

			return $position;
		}

		return $this->parse_supported_show_grants_account_name( $tokens, $start, $end );
	}

	/**
	 * Parse a SHOW GRANTS role list.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First role token.
	 * @param int              $end    Final statement token position, exclusive.
	 * @return int|null Position after the role list, or null when unsupported.
	 */
	private function parse_supported_show_grants_role_list( array $tokens, int $start, int $end ): ?int {
		$position = $this->parse_supported_show_grants_account_name( $tokens, $start, $end );
		if ( null === $position ) {
			return null;
		}

		while ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id ) {
			$position = $this->parse_supported_show_grants_account_name( $tokens, $position + 1, $end );
			if ( null === $position ) {
				return null;
			}
		}

		return $position;
	}

	/**
	 * Parse a MySQL account-style name used by SHOW GRANTS.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First account token.
	 * @param int              $end    Final statement token position, exclusive.
	 * @return int|null Position after the account name, or null when unsupported.
	 */
	private function parse_supported_show_grants_account_name( array $tokens, int $start, int $end ): ?int {
		if ( $start >= $end || ! $this->is_supported_show_grants_name_part( $tokens[ $start ] ?? null ) ) {
			return null;
		}

		$position = $start + 1;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::AT_TEXT_SUFFIX === $tokens[ $position ]->id ) {
			return $position + 1;
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::AT_SIGN_SYMBOL === $tokens[ $position ]->id ) {
			if ( ! $this->is_supported_show_grants_name_part( $tokens[ $position + 1 ] ?? null ) ) {
				return null;
			}

			return $position + 2;
		}

		return $position;
	}

	/**
	 * Check whether a token is a supported SHOW GRANTS account/role part.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @return bool Whether the token can name a user, host, or role part.
	 */
	private function is_supported_show_grants_name_part( ?WP_MySQL_Token $token ): bool {
		return null !== $token
			&& (
				null !== $this->get_mysql_identifier_token_value( $token, true )
				|| WP_MySQL_Lexer::SINGLE_QUOTED_TEXT === $token->id
			);
	}

	/**
	 * Parse a supported MySQL SHOW STATUS statement.
	 *
	 * @param string $query MySQL query.
	 * @return array{type: string, column: string|null, pattern: string|null, conditions?: array[]}|null SHOW STATUS options, or null when this is not SHOW STATUS.
	 */
	private function get_show_status_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0], $tokens[1] ) || WP_MySQL_Lexer::SHOW_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$position = 1;
		if (
			WP_MySQL_Lexer::GLOBAL_SYMBOL === $tokens[ $position ]->id
			|| WP_MySQL_Lexer::SESSION_SYMBOL === $tokens[ $position ]->id
		) {
			++$position;
		}

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::STATUS_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		++$position;
		if ( $this->is_at_mysql_query_end( $tokens, $position ) ) {
			return array(
				'type'    => 'all',
				'column'  => null,
				'pattern' => null,
			);
		}

		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::LIKE_SYMBOL === $tokens[ $position ]->id
			&& $this->is_mysql_quoted_text_token( $tokens[ $position + 1 ] )
			&& $this->is_at_mysql_query_end( $tokens, $position + 2 )
		) {
			return array(
				'type'    => 'like',
				'column'  => 'Variable_name',
				'pattern' => $tokens[ $position + 1 ]->get_value(),
			);
		}

		$allowed_columns = array(
			'variable_name' => 'Variable_name',
			'value'         => 'Value',
		);
		$where_filters   = $this->get_mysql_show_where_filters( $tokens, $position, $allowed_columns );
		if ( null !== $where_filters ) {
			return array(
				'type'       => 'where',
				'column'     => null,
				'pattern'    => null,
				'conditions' => $where_filters,
			);
		}

		$where_expression = $this->get_mysql_show_where_expression_filter( $tokens, $position, $allowed_columns );
		if ( null !== $where_expression ) {
			return $where_expression;
		}

		throw new InvalidArgumentException( 'Unsupported SHOW STATUS statement.' );
	}

	/**
	 * Parse a supported MySQL SHOW WARNINGS/ERRORS statement.
	 *
	 * PostgreSQL execution errors are surfaced directly as exceptions, so there
	 * is no MySQL diagnostics area to inspect. The supported forms return the
	 * compatible empty diagnostics shape, or a zero COUNT(*) row.
	 *
	 * @param string $query            MySQL query.
	 * @param int    $diagnostic_token WARNINGS_SYMBOL or ERRORS_SYMBOL.
	 * @param string $diagnostic_name  Diagnostic type for error messages and count columns.
	 * @return array{type: string, count_column: string|null, statement: string}|null Diagnostics options, or null when this is not the requested SHOW statement.
	 */
	private function get_show_diagnostics_query( string $query, int $diagnostic_token, string $diagnostic_name ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0], $tokens[1] ) || WP_MySQL_Lexer::SHOW_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$position = 1;
		if ( WP_MySQL_Lexer::COUNT_SYMBOL === $tokens[ $position ]->id ) {
			if (
				! isset( $tokens[ $position + 1 ], $tokens[ $position + 2 ], $tokens[ $position + 3 ], $tokens[ $position + 4 ] )
				|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position + 1 ]->id
				|| WP_MySQL_Lexer::MULT_OPERATOR !== $tokens[ $position + 2 ]->id
				|| WP_MySQL_Lexer::CLOSE_PAR_SYMBOL !== $tokens[ $position + 3 ]->id
			) {
				return null;
			}

			$position += 4;
			if ( WP_MySQL_Lexer::WARNINGS_SYMBOL !== $tokens[ $position ]->id && WP_MySQL_Lexer::ERRORS_SYMBOL !== $tokens[ $position ]->id ) {
				return null;
			}

			if ( $diagnostic_token !== $tokens[ $position ]->id ) {
				return null;
			}

			if ( ! $this->is_at_mysql_query_end( $tokens, $position + 1 ) ) {
				throw new InvalidArgumentException( sprintf( 'Unsupported SHOW %s statement.', strtoupper( $diagnostic_name ) ) );
			}

			return array(
				'type'         => 'count',
				'count_column' => '@@session.' . ( 'warnings' === $diagnostic_name ? 'warning_count' : 'error_count' ),
				'statement'    => $diagnostic_name,
			);
		}

		if ( WP_MySQL_Lexer::WARNINGS_SYMBOL !== $tokens[ $position ]->id && WP_MySQL_Lexer::ERRORS_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		if ( $diagnostic_token !== $tokens[ $position ]->id ) {
			return null;
		}

		if ( ! $this->is_at_mysql_query_end( $tokens, $position + 1 ) && ! $this->is_supported_show_diagnostics_limit_clause( $tokens, $position + 1 ) ) {
			throw new InvalidArgumentException( sprintf( 'Unsupported SHOW %s statement.', strtoupper( $diagnostic_name ) ) );
		}

		return array(
			'type'         => 'rows',
			'count_column' => null,
			'statement'    => $diagnostic_name,
		);
	}

	/**
	 * Check whether a SHOW WARNINGS/ERRORS LIMIT clause is supported.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position LIMIT token position.
	 * @return bool Whether the LIMIT clause is supported.
	 */
	private function is_supported_show_diagnostics_limit_clause( array $tokens, int $position ): bool {
		$statement_end = $this->get_mysql_statement_end_position( $tokens, $position );
		if (
			null === $statement_end
			|| ! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::LIMIT_SYMBOL !== $tokens[ $position ]->id
		) {
			return false;
		}

		if ( $position + 2 === $statement_end ) {
			return $this->is_mysql_show_limit_number_token( $tokens[ $position + 1 ] );
		}

		if (
			$position + 4 === $statement_end
			&& isset( $tokens[ $position + 2 ], $tokens[ $position + 3 ] )
			&& WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position + 2 ]->id
		) {
			return $this->is_mysql_show_limit_number_token( $tokens[ $position + 1 ] )
				&& $this->is_mysql_show_limit_number_token( $tokens[ $position + 3 ] );
		}

		if (
			$position + 4 === $statement_end
			&& isset( $tokens[ $position + 2 ], $tokens[ $position + 3 ] )
			&& WP_MySQL_Lexer::OFFSET_SYMBOL === $tokens[ $position + 2 ]->id
		) {
			return $this->is_mysql_show_limit_number_token( $tokens[ $position + 1 ] )
				&& $this->is_mysql_show_limit_number_token( $tokens[ $position + 3 ] );
		}

		return false;
	}

	/**
	 * Check whether a token is a supported SHOW LIMIT number.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token is a non-negative integer literal.
	 */
	private function is_mysql_show_limit_number_token( WP_MySQL_Token $token ): bool {
		return $this->is_mysql_unsigned_integer_token( $token ) && ctype_digit( $token->get_value() );
	}

	/**
	 * Parse a supported MySQL SHOW PROCESSLIST statement.
	 *
	 * @param string $query MySQL query.
	 * @return array{full: bool}|null SHOW PROCESSLIST options, or null when this is not SHOW PROCESSLIST.
	 */
	private function get_show_processlist_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0], $tokens[1] ) || WP_MySQL_Lexer::SHOW_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$position = 1;
		if (
			(
				WP_MySQL_Lexer::GLOBAL_SYMBOL === $tokens[ $position ]->id
				|| WP_MySQL_Lexer::SESSION_SYMBOL === $tokens[ $position ]->id
			)
			&& isset( $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::PROCESSLIST_SYMBOL === $tokens[ $position + 1 ]->id
		) {
			throw new InvalidArgumentException( 'Unsupported SHOW PROCESSLIST statement.' );
		}

		$is_full = false;
		if ( WP_MySQL_Lexer::FULL_SYMBOL === $tokens[ $position ]->id ) {
			$is_full = true;
			++$position;
		}

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::PROCESSLIST_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		if ( ! $this->is_at_mysql_query_end( $tokens, $position + 1 ) ) {
			throw new InvalidArgumentException( 'Unsupported SHOW PROCESSLIST statement.' );
		}

		return array(
			'full' => $is_full,
		);
	}

	/**
	 * Parse optional LIKE or simple WHERE filters for static SHOW result sets.
	 *
	 * @param WP_MySQL_Token[]    $tokens          MySQL lexer token stream.
	 * @param int                 $position        Current token position.
	 * @param string              $like_column     Output column filtered by LIKE.
	 * @param array<string,string> $allowed_columns Allowed output columns keyed by lower-case name.
	 * @return array{type: string, column: string|null, pattern: string|null, predicate?: array}|null Parsed filter, or null when unsupported.
	 */
	private function get_show_static_result_filter(
		array $tokens,
		int $position,
		string $like_column,
		array $allowed_columns
	): ?array {
		if ( $this->is_at_mysql_query_end( $tokens, $position ) ) {
			return array(
				'type'    => 'all',
				'column'  => null,
				'pattern' => null,
			);
		}

		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::LIKE_SYMBOL === $tokens[ $position ]->id
			&& $this->is_mysql_quoted_text_token( $tokens[ $position + 1 ] )
			&& $this->is_at_mysql_query_end( $tokens, $position + 2 )
		) {
			return array(
				'type'    => 'like',
				'column'  => $like_column,
				'pattern' => $tokens[ $position + 1 ]->get_value(),
			);
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::WHERE_SYMBOL === $tokens[ $position ]->id ) {
			return $this->get_mysql_show_where_expression_filter( $tokens, $position, $allowed_columns );
		}

		return null;
	}

	/**
	 * Parse a MySQL WHERE expression that can be evaluated against materialized SHOW rows.
	 *
	 * @param WP_MySQL_Token[]     $tokens          MySQL lexer token stream.
	 * @param int                  $position        WHERE token position.
	 * @param array<string,string> $allowed_columns Allowed output columns keyed by lower-case name.
	 * @param string[]             $numeric_columns Output columns that may be used in arithmetic expressions.
	 * @return array{type: string, column: null, pattern: null, predicate: array}|null Parsed expression filter, or null when unsupported.
	 */
	private function get_mysql_show_where_expression_filter( array $tokens, int $position, array $allowed_columns, array $numeric_columns = array() ): ?array {
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::WHERE_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, $position );
		if ( null === $statement_end || $position + 1 >= $statement_end ) {
			return null;
		}

		$expression_position = $position + 1;
		$predicate           = $this->parse_mysql_show_where_or_expression( $tokens, $expression_position, $statement_end, $allowed_columns, $numeric_columns );
		if ( null === $predicate || $expression_position !== $statement_end ) {
			return null;
		}

		return array(
			'type'      => 'where_expression',
			'column'    => null,
			'pattern'   => null,
			'predicate' => $predicate,
		);
	}

	/**
	 * Check whether a parsed SHOW WHERE filter should be evaluated against materialized rows.
	 *
	 * @param array|null $where_filter Parsed SHOW WHERE filter.
	 * @return bool Whether the filter is an expression filter.
	 */
	private function is_mysql_show_where_expression_filter( ?array $where_filter ): bool {
		return is_array( $where_filter ) && 'where_expression' === ( $where_filter['type'] ?? null );
	}

	/**
	 * Parse OR-combined SHOW WHERE predicates.
	 *
	 * @param WP_MySQL_Token[]     $tokens          MySQL lexer token stream.
	 * @param int                  $position        Current token position, advanced on success.
	 * @param int                  $end             Final token position, exclusive.
	 * @param array<string,string> $allowed_columns Allowed output columns keyed by lower-case name.
	 * @param string[]             $numeric_columns Output columns that may be used in arithmetic expressions.
	 * @return array|null Predicate AST, or null when unsupported.
	 */
	private function parse_mysql_show_where_or_expression( array $tokens, int &$position, int $end, array $allowed_columns, array $numeric_columns = array() ): ?array {
		$left = $this->parse_mysql_show_where_and_expression( $tokens, $position, $end, $allowed_columns, $numeric_columns );
		if ( null === $left ) {
			return null;
		}

		while ( isset( $tokens[ $position ] ) && $position < $end && WP_MySQL_Lexer::OR_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
			$right = $this->parse_mysql_show_where_and_expression( $tokens, $position, $end, $allowed_columns, $numeric_columns );
			if ( null === $right ) {
				return null;
			}

			$left = array(
				'type'  => 'or',
				'left'  => $left,
				'right' => $right,
			);
		}

		return $left;
	}

	/**
	 * Parse AND-combined SHOW WHERE predicates.
	 *
	 * @param WP_MySQL_Token[]     $tokens          MySQL lexer token stream.
	 * @param int                  $position        Current token position, advanced on success.
	 * @param int                  $end             Final token position, exclusive.
	 * @param array<string,string> $allowed_columns Allowed output columns keyed by lower-case name.
	 * @param string[]             $numeric_columns Output columns that may be used in arithmetic expressions.
	 * @return array|null Predicate AST, or null when unsupported.
	 */
	private function parse_mysql_show_where_and_expression( array $tokens, int &$position, int $end, array $allowed_columns, array $numeric_columns = array() ): ?array {
		$left = $this->parse_mysql_show_where_not_expression( $tokens, $position, $end, $allowed_columns, $numeric_columns );
		if ( null === $left ) {
			return null;
		}

		while ( isset( $tokens[ $position ] ) && $position < $end && WP_MySQL_Lexer::AND_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
			$right = $this->parse_mysql_show_where_not_expression( $tokens, $position, $end, $allowed_columns, $numeric_columns );
			if ( null === $right ) {
				return null;
			}

			$left = array(
				'type'  => 'and',
				'left'  => $left,
				'right' => $right,
			);
		}

		return $left;
	}

	/**
	 * Parse optional NOT around SHOW WHERE predicates.
	 *
	 * @param WP_MySQL_Token[]     $tokens          MySQL lexer token stream.
	 * @param int                  $position        Current token position, advanced on success.
	 * @param int                  $end             Final token position, exclusive.
	 * @param array<string,string> $allowed_columns Allowed output columns keyed by lower-case name.
	 * @param string[]             $numeric_columns Output columns that may be used in arithmetic expressions.
	 * @return array|null Predicate AST, or null when unsupported.
	 */
	private function parse_mysql_show_where_not_expression( array $tokens, int &$position, int $end, array $allowed_columns, array $numeric_columns = array() ): ?array {
		if ( isset( $tokens[ $position ] ) && $position < $end && WP_MySQL_Lexer::NOT_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
			$expression = $this->parse_mysql_show_where_not_expression( $tokens, $position, $end, $allowed_columns, $numeric_columns );
			if ( null === $expression ) {
				return null;
			}

			return array(
				'type' => 'not',
				'expr' => $expression,
			);
		}

		return $this->parse_mysql_show_where_boolean_primary( $tokens, $position, $end, $allowed_columns, $numeric_columns );
	}

	/**
	 * Parse a SHOW WHERE parenthesized predicate or comparison.
	 *
	 * @param WP_MySQL_Token[]     $tokens          MySQL lexer token stream.
	 * @param int                  $position        Current token position, advanced on success.
	 * @param int                  $end             Final token position, exclusive.
	 * @param array<string,string> $allowed_columns Allowed output columns keyed by lower-case name.
	 * @param string[]             $numeric_columns Output columns that may be used in arithmetic expressions.
	 * @return array|null Predicate AST, or null when unsupported.
	 */
	private function parse_mysql_show_where_boolean_primary( array $tokens, int &$position, int $end, array $allowed_columns, array $numeric_columns = array() ): ?array {
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
			$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
			if ( null !== $after_close ) {
				$inner_position = $position + 1;
				$predicate      = $this->parse_mysql_show_where_or_expression( $tokens, $inner_position, $after_close - 1, $allowed_columns, $numeric_columns );
				if ( null !== $predicate && $inner_position === $after_close - 1 ) {
					$position = $after_close;
					return $predicate;
				}
			}
		}

		return $this->parse_mysql_show_where_comparison_expression( $tokens, $position, $end, $allowed_columns, $numeric_columns );
	}

	/**
	 * Parse a SHOW WHERE comparison predicate.
	 *
	 * @param WP_MySQL_Token[]     $tokens          MySQL lexer token stream.
	 * @param int                  $position        Current token position, advanced on success.
	 * @param int                  $end             Final token position, exclusive.
	 * @param array<string,string> $allowed_columns Allowed output columns keyed by lower-case name.
	 * @param string[]             $numeric_columns Output columns that may be used in arithmetic expressions.
	 * @return array|null Predicate AST, or null when unsupported.
	 */
	private function parse_mysql_show_where_comparison_expression( array $tokens, int &$position, int $end, array $allowed_columns, array $numeric_columns = array() ): ?array {
		$left = $this->parse_mysql_show_where_value_expression( $tokens, $position, $end, $allowed_columns, $numeric_columns );
		if ( null === $left ) {
			return null;
		}

		if ( ! isset( $tokens[ $position ] ) || $position >= $end ) {
			return array(
				'type' => 'truthy',
				'expr' => $left,
			);
		}

		if ( WP_MySQL_Lexer::IS_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
			$is_not = false;
			if ( isset( $tokens[ $position ] ) && $position < $end && WP_MySQL_Lexer::NOT_SYMBOL === $tokens[ $position ]->id ) {
				$is_not = true;
				++$position;
			}

			if ( ! isset( $tokens[ $position ] ) || $position >= $end || WP_MySQL_Lexer::NULL_SYMBOL !== $tokens[ $position ]->id ) {
				return null;
			}
			++$position;

			return array(
				'type' => 'is_null',
				'expr' => $left,
				'not'  => $is_not,
			);
		}

		$operator = $this->get_mysql_show_where_comparison_operator( $tokens[ $position ] );
		if ( null !== $operator ) {
			++$position;
			$right = $this->parse_mysql_show_where_value_expression( $tokens, $position, $end, $allowed_columns, $numeric_columns );
			if ( null === $right ) {
				return null;
			}

			return array(
				'type'     => 'comparison',
				'operator' => $operator,
				'left'     => $left,
				'right'    => $right,
			);
		}

		$is_not = false;
		if ( WP_MySQL_Lexer::NOT_SYMBOL === $tokens[ $position ]->id ) {
			$is_not = true;
			++$position;
		}

		if ( ! isset( $tokens[ $position ] ) || $position >= $end ) {
			return $is_not ? null : array(
				'type' => 'truthy',
				'expr' => $left,
			);
		}

		if ( WP_MySQL_Lexer::LIKE_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
			$right = $this->parse_mysql_show_where_value_expression( $tokens, $position, $end, $allowed_columns, $numeric_columns );
			if ( null === $right ) {
				return null;
			}

			return array(
				'type'     => 'comparison',
				'operator' => $is_not ? 'not_like' : 'like',
				'left'     => $left,
				'right'    => $right,
			);
		}

		if ( WP_MySQL_Lexer::IN_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
			$values = $this->parse_mysql_show_where_value_list( $tokens, $position, $end, $allowed_columns, $numeric_columns );
			if ( null === $values ) {
				return null;
			}

			return array(
				'type'   => 'in',
				'expr'   => $left,
				'values' => $values,
				'not'    => $is_not,
			);
		}

		if ( WP_MySQL_Lexer::BETWEEN_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
			$lower = $this->parse_mysql_show_where_value_expression( $tokens, $position, $end, $allowed_columns, $numeric_columns );
			if (
				null === $lower
				|| ! isset( $tokens[ $position ] )
				|| $position >= $end
				|| WP_MySQL_Lexer::AND_SYMBOL !== $tokens[ $position ]->id
			) {
				return null;
			}

			++$position;
			$upper = $this->parse_mysql_show_where_value_expression( $tokens, $position, $end, $allowed_columns, $numeric_columns );
			if ( null === $upper ) {
				return null;
			}

			return array(
				'type'  => 'between',
				'expr'  => $left,
				'lower' => $lower,
				'upper' => $upper,
				'not'   => $is_not,
			);
		}

		if ( $is_not ) {
			return null;
		}

		return array(
			'type' => 'truthy',
			'expr' => $left,
		);
	}

	/**
	 * Get a normalized SHOW WHERE comparison operator.
	 *
	 * @param WP_MySQL_Token $token Operator token.
	 * @return string|null Operator, or null when unsupported.
	 */
	private function get_mysql_show_where_comparison_operator( WP_MySQL_Token $token ): ?string {
		switch ( $token->id ) {
			case WP_MySQL_Lexer::EQUAL_OPERATOR:
				return '=';
			case WP_MySQL_Lexer::NOT_EQUAL_OPERATOR:
				return '<>';
			case WP_MySQL_Lexer::GREATER_THAN_OPERATOR:
				return '>';
			case WP_MySQL_Lexer::GREATER_OR_EQUAL_OPERATOR:
				return '>=';
			case WP_MySQL_Lexer::LESS_THAN_OPERATOR:
				return '<';
			case WP_MySQL_Lexer::LESS_OR_EQUAL_OPERATOR:
				return '<=';
			case WP_MySQL_Lexer::NULL_SAFE_EQUAL_OPERATOR:
				return '<=>';
		}

		return null;
	}

	/**
	 * Parse a scalar value expression for SHOW WHERE predicates.
	 *
	 * @param WP_MySQL_Token[]     $tokens          MySQL lexer token stream.
	 * @param int                  $position        Current token position, advanced on success.
	 * @param int                  $end             Final token position, exclusive.
	 * @param array<string,string> $allowed_columns Allowed output columns keyed by lower-case name.
	 * @param string[]             $numeric_columns Output columns that may be used in arithmetic expressions.
	 * @return array|null Value expression AST, or null when unsupported.
	 */
	private function parse_mysql_show_where_value_expression( array $tokens, int &$position, int $end, array $allowed_columns, array $numeric_columns = array() ): ?array {
		$left = $this->parse_mysql_show_where_multiplicative_value_expression( $tokens, $position, $end, $allowed_columns, $numeric_columns );
		if ( null === $left ) {
			return null;
		}

		while (
			isset( $tokens[ $position ] )
			&& $position < $end
			&& in_array( $tokens[ $position ]->id, array( WP_MySQL_Lexer::PLUS_OPERATOR, WP_MySQL_Lexer::MINUS_OPERATOR ), true )
		) {
			$operator = WP_MySQL_Lexer::PLUS_OPERATOR === $tokens[ $position ]->id ? '+' : '-';
			++$position;
			$right = $this->parse_mysql_show_where_multiplicative_value_expression( $tokens, $position, $end, $allowed_columns, $numeric_columns );
			if (
				null === $right
				|| ! $this->is_mysql_show_where_numeric_value_expression( $left, $numeric_columns )
				|| ! $this->is_mysql_show_where_numeric_value_expression( $right, $numeric_columns )
			) {
				return null;
			}

			$left = array(
				'type'     => 'arithmetic',
				'operator' => $operator,
				'left'     => $left,
				'right'    => $right,
			);
		}

		return $left;
	}

	/**
	 * Parse a multiplicative scalar value expression for SHOW WHERE predicates.
	 *
	 * @param WP_MySQL_Token[]     $tokens          MySQL lexer token stream.
	 * @param int                  $position        Current token position, advanced on success.
	 * @param int                  $end             Final token position, exclusive.
	 * @param array<string,string> $allowed_columns Allowed output columns keyed by lower-case name.
	 * @param string[]             $numeric_columns Output columns that may be used in arithmetic expressions.
	 * @return array|null Value expression AST, or null when unsupported.
	 */
	private function parse_mysql_show_where_multiplicative_value_expression( array $tokens, int &$position, int $end, array $allowed_columns, array $numeric_columns = array() ): ?array {
		$left = $this->parse_mysql_show_where_primary_value_expression( $tokens, $position, $end, $allowed_columns, $numeric_columns );
		if ( null === $left ) {
			return null;
		}

		while (
			isset( $tokens[ $position ] )
			&& $position < $end
			&& in_array(
				$tokens[ $position ]->id,
				array(
					WP_MySQL_Lexer::MULT_OPERATOR,
					WP_MySQL_Lexer::DIV_OPERATOR,
					WP_MySQL_Lexer::DIV_SYMBOL,
					WP_MySQL_Lexer::MOD_OPERATOR,
					WP_MySQL_Lexer::MOD_SYMBOL,
				),
				true
			)
		) {
			$operator = '/';
			if ( WP_MySQL_Lexer::MULT_OPERATOR === $tokens[ $position ]->id ) {
				$operator = '*';
			} elseif ( WP_MySQL_Lexer::MOD_OPERATOR === $tokens[ $position ]->id || WP_MySQL_Lexer::MOD_SYMBOL === $tokens[ $position ]->id ) {
				$operator = '%';
			}
			++$position;
			$right = $this->parse_mysql_show_where_primary_value_expression( $tokens, $position, $end, $allowed_columns, $numeric_columns );
			if (
				null === $right
				|| ! $this->is_mysql_show_where_numeric_value_expression( $left, $numeric_columns )
				|| ! $this->is_mysql_show_where_numeric_value_expression( $right, $numeric_columns )
			) {
				return null;
			}

			$left = array(
				'type'     => 'arithmetic',
				'operator' => $operator,
				'left'     => $left,
				'right'    => $right,
			);
		}

		return $left;
	}

	/**
	 * Parse a primary scalar value expression for SHOW WHERE predicates.
	 *
	 * @param WP_MySQL_Token[]     $tokens          MySQL lexer token stream.
	 * @param int                  $position        Current token position, advanced on success.
	 * @param int                  $end             Final token position, exclusive.
	 * @param array<string,string> $allowed_columns Allowed output columns keyed by lower-case name.
	 * @param string[]             $numeric_columns Output columns that may be used in arithmetic expressions.
	 * @return array|null Value expression AST, or null when unsupported.
	 */
	private function parse_mysql_show_where_primary_value_expression( array $tokens, int &$position, int $end, array $allowed_columns, array $numeric_columns = array() ): ?array {
		if ( ! isset( $tokens[ $position ] ) || $position >= $end ) {
			return null;
		}

		$token = $tokens[ $position ];
		if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $token->id ) {
			$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
			if ( null === $after_close ) {
				return null;
			}

			$inner_position = $position + 1;
			$expression     = $this->parse_mysql_show_where_value_expression( $tokens, $inner_position, $after_close - 1, $allowed_columns, $numeric_columns );
			if ( null === $expression || $inner_position !== $after_close - 1 ) {
				return null;
			}

			$position = $after_close;
			return $expression;
		}

		$function = $this->parse_mysql_show_where_function_value_expression( $tokens, $position, $end, $allowed_columns, $numeric_columns );
		if ( null !== $function ) {
			return $function;
		}

		$column = $this->get_mysql_show_output_column_name( $token, $allowed_columns );
		if ( null !== $column ) {
			++$position;
			return array(
				'type'   => 'column',
				'column' => $column,
			);
		}

		if ( $this->is_mysql_quoted_text_token( $token ) ) {
			++$position;
			return array(
				'type'  => 'literal',
				'value' => $token->get_value(),
			);
		}

		if ( WP_MySQL_Lexer::NULL_SYMBOL === $token->id ) {
			++$position;
			return array( 'type' => 'null' );
		}

		if ( WP_MySQL_Lexer::TRUE_SYMBOL === $token->id || WP_MySQL_Lexer::FALSE_SYMBOL === $token->id ) {
			++$position;
			return array(
				'type'  => 'number',
				'value' => WP_MySQL_Lexer::TRUE_SYMBOL === $token->id ? '1' : '0',
			);
		}

		if ( WP_MySQL_Lexer::MINUS_OPERATOR === $token->id && isset( $tokens[ $position + 1 ] ) && $position + 1 < $end && $this->is_mysql_number_token( $tokens[ $position + 1 ] ) ) {
			$value     = '-' . $tokens[ $position + 1 ]->get_value();
			$position += 2;
			return array(
				'type'  => 'number',
				'value' => $value,
			);
		}

		if ( $this->is_mysql_number_token( $token ) ) {
			++$position;
			return array(
				'type'  => 'number',
				'value' => $token->get_value(),
			);
		}

		return null;
	}

	/**
	 * Check whether a SHOW WHERE value expression may be used in arithmetic.
	 *
	 * @param array    $expression      Value expression AST.
	 * @param string[] $numeric_columns Output columns that may be used in arithmetic expressions.
	 * @return bool Whether the expression is numeric.
	 */
	private function is_mysql_show_where_numeric_value_expression( array $expression, array $numeric_columns ): bool {
		switch ( $expression['type'] ?? null ) {
			case 'number':
			case 'arithmetic':
				return true;

			case 'literal':
				return isset( $expression['value'] ) && is_numeric( $expression['value'] );

			case 'column':
				return isset( $expression['column'] ) && in_array( $expression['column'], $numeric_columns, true );

			case 'function':
				return in_array( $expression['function'] ?? null, array( 'length', 'char_length' ), true );
		}

		return false;
	}

	/**
	 * Parse a supported scalar function value for SHOW WHERE predicates.
	 *
	 * @param WP_MySQL_Token[]     $tokens          MySQL lexer token stream.
	 * @param int                  $position        Current token position, advanced on success.
	 * @param int                  $end             Final token position, exclusive.
	 * @param array<string,string> $allowed_columns Allowed output columns keyed by lower-case name.
	 * @param string[]             $numeric_columns Output columns that may be used in arithmetic expressions.
	 * @return array|null Function value AST, or null when unsupported.
	 */
	private function parse_mysql_show_where_function_value_expression( array $tokens, int &$position, int $end, array $allowed_columns, array $numeric_columns = array() ): ?array {
		$function_name = $this->get_mysql_show_where_function_name( $tokens[ $position ] ?? null );
		if (
			null === $function_name
			|| ! isset( $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return null;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position + 1, $end );
		if ( null === $after_close ) {
			return null;
		}

		$argument_ranges = 'substring' === $function_name
			? $this->get_mysql_substring_function_arguments( $tokens, $position + 2, $after_close - 1 )
			: $this->split_top_level_mysql_arguments( $tokens, $position + 2, $after_close - 1 );
		if ( null === $argument_ranges ) {
			return null;
		}

		$arguments = array();
		foreach ( $argument_ranges as $argument_range ) {
			$argument_position = $argument_range['start'];
			$argument          = $this->parse_mysql_show_where_value_expression( $tokens, $argument_position, $argument_range['end'], $allowed_columns, $numeric_columns );
			if ( null === $argument || $argument_position !== $argument_range['end'] ) {
				return null;
			}

			$arguments[] = $argument;
		}

		$argument_count = count( $arguments );
		if (
			( 'substring' === $function_name && ! in_array( $argument_count, array( 2, 3 ), true ) )
			|| ( in_array( $function_name, array( 'left', 'right' ), true ) && 2 !== $argument_count )
			|| ( in_array( $function_name, array( 'lower', 'upper', 'length', 'char_length' ), true ) && 1 !== $argument_count )
			|| (
				'mod' === $function_name
				&& (
					2 !== $argument_count
					|| ! $this->is_mysql_show_where_numeric_value_expression( $arguments[0], $numeric_columns )
					|| ! $this->is_mysql_show_where_numeric_value_expression( $arguments[1], $numeric_columns )
				)
			)
		) {
			return null;
		}

		$position = $after_close;
		return array(
			'type'      => 'function',
			'function'  => $function_name,
			'arguments' => $arguments,
		);
	}

	/**
	 * Get a supported SHOW WHERE scalar function name.
	 *
	 * @param WP_MySQL_Token|null $token Function token.
	 * @return string|null Normalized function name, or null when unsupported.
	 */
	private function get_mysql_show_where_function_name( ?WP_MySQL_Token $token ): ?string {
		if ( null === $token ) {
			return null;
		}

		$keyword_functions = array(
			WP_MySQL_Lexer::LEFT_SYMBOL      => 'left',
			WP_MySQL_Lexer::MOD_SYMBOL       => 'mod',
			WP_MySQL_Lexer::RIGHT_SYMBOL     => 'right',
			WP_MySQL_Lexer::SUBSTR_SYMBOL    => 'substring',
			WP_MySQL_Lexer::SUBSTRING_SYMBOL => 'substring',
		);
		if ( isset( $keyword_functions[ $token->id ] ) ) {
			return $keyword_functions[ $token->id ];
		}

		$name = $this->get_mysql_identifier_token_value( $token );
		if ( null === $name ) {
			return null;
		}

		$name = strtolower( $name );
		if ( in_array( $name, array( 'lcase', 'lower' ), true ) ) {
			return 'lower';
		}

		if ( in_array( $name, array( 'ucase', 'upper' ), true ) ) {
			return 'upper';
		}

		if ( 'substr' === $name || 'substring' === $name || 'mid' === $name ) {
			return 'substring';
		}

		if ( 'length' === $name ) {
			return 'length';
		}

		if ( 'char_length' === $name || 'character_length' === $name ) {
			return 'char_length';
		}

		if ( 'mod' === $name ) {
			return 'mod';
		}

		return in_array( $name, array( 'left', 'right' ), true ) ? $name : null;
	}

	/**
	 * Check whether a token is a supported MySQL numeric literal.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token is numeric.
	 */
	private function is_mysql_number_token( WP_MySQL_Token $token ): bool {
		return $this->is_mysql_unsigned_integer_token( $token )
			|| WP_MySQL_Lexer::DECIMAL_NUMBER === $token->id
			|| WP_MySQL_Lexer::FLOAT_NUMBER === $token->id;
	}

	/**
	 * Parse a non-empty parenthesized value list for SHOW WHERE IN predicates.
	 *
	 * @param WP_MySQL_Token[]     $tokens          MySQL lexer token stream.
	 * @param int                  $position        Current token position, advanced on success.
	 * @param int                  $end             Final token position, exclusive.
	 * @param array<string,string> $allowed_columns Allowed output columns keyed by lower-case name.
	 * @param string[]             $numeric_columns Output columns that may be used in arithmetic expressions.
	 * @return array<int,array>|null Value expressions, or null when unsupported.
	 */
	private function parse_mysql_show_where_value_list( array $tokens, int &$position, int $end, array $allowed_columns, array $numeric_columns = array() ): ?array {
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
		if ( null === $after_close ) {
			return null;
		}

		$argument_ranges = $this->split_top_level_mysql_arguments( $tokens, $position + 1, $after_close - 1 );
		if ( empty( $argument_ranges ) ) {
			return null;
		}

		$values = array();
		foreach ( $argument_ranges as $argument_range ) {
			$argument_position = $argument_range['start'];
			$value             = $this->parse_mysql_show_where_value_expression( $tokens, $argument_position, $argument_range['end'], $allowed_columns, $numeric_columns );
			if ( null === $value || $argument_position !== $argument_range['end'] ) {
				return null;
			}

			$values[] = $value;
		}

		$position = $after_close;
		return $values;
	}

	/**
	 * Parse a safe simple WHERE filter for dynamic SHOW result sets.
	 *
	 * @param WP_MySQL_Token[]    $tokens          MySQL lexer token stream.
	 * @param int                 $position        WHERE token position.
	 * @param array<string,string> $allowed_columns Allowed output columns keyed by lower-case name.
	 * @param string[]            $numeric_columns Output columns that may compare against an unsigned integer literal.
	 * @return array{column: string, operator: string, value: string}|null Parsed filter, or null when unsupported.
	 */
	private function get_mysql_show_where_filter( array $tokens, int $position, array $allowed_columns, array $numeric_columns = array() ): ?array {
		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ], $tokens[ $position + 2 ], $tokens[ $position + 3 ] )
			|| WP_MySQL_Lexer::WHERE_SYMBOL !== $tokens[ $position ]->id
			|| ! $this->is_at_mysql_query_end( $tokens, $position + 4 )
		) {
			return null;
		}

		$column = $this->get_mysql_show_output_column_name( $tokens[ $position + 1 ], $allowed_columns );
		if ( null === $column ) {
			return null;
		}

		$operator_token = $tokens[ $position + 2 ];
		$value_token    = $tokens[ $position + 3 ];
		if ( WP_MySQL_Lexer::EQUAL_OPERATOR === $operator_token->id ) {
			if ( $this->is_mysql_quoted_text_token( $value_token ) ) {
				$value = $value_token->get_value();
			} elseif (
				in_array( $column, $numeric_columns, true )
				&& $this->is_mysql_unsigned_integer_token( $value_token )
			) {
				$value = $value_token->get_value();
			} else {
				return null;
			}

			$operator = '=';
		} elseif ( WP_MySQL_Lexer::LIKE_SYMBOL === $operator_token->id && $this->is_mysql_quoted_text_token( $value_token ) ) {
			$operator = 'like';
			$value    = $value_token->get_value();
		} else {
			return null;
		}

		return array(
			'column'   => $column,
			'operator' => $operator,
			'value'    => $value,
		);
	}

	/**
	 * Parse simple AND-combined WHERE filters for static SHOW result sets.
	 *
	 * @param WP_MySQL_Token[]    $tokens          MySQL lexer token stream.
	 * @param int                 $position        WHERE token position.
	 * @param array<string,string> $allowed_columns Allowed output columns keyed by lower-case name.
	 * @param string[]            $numeric_columns Output columns that may compare against an unsigned integer literal.
	 * @return array<int,array{column: string, operator: string, value: string}>|null Parsed filters, or null when unsupported.
	 */
	private function get_mysql_show_where_filters( array $tokens, int $position, array $allowed_columns, array $numeric_columns = array() ): ?array {
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::WHERE_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, $position );
		if ( null === $statement_end ) {
			return null;
		}

		$filters  = array();
		$position = $position + 1;
		while ( $position < $statement_end ) {
			if ( ! isset( $tokens[ $position ], $tokens[ $position + 1 ], $tokens[ $position + 2 ] ) ) {
				return null;
			}

			$column = $this->get_mysql_show_output_column_name( $tokens[ $position ], $allowed_columns );
			if ( null === $column ) {
				return null;
			}

			$operator_token = $tokens[ $position + 1 ];
			$value_token    = $tokens[ $position + 2 ];
			if ( WP_MySQL_Lexer::EQUAL_OPERATOR === $operator_token->id ) {
				if ( $this->is_mysql_quoted_text_token( $value_token ) ) {
					$value = $value_token->get_value();
				} elseif (
					in_array( $column, $numeric_columns, true )
					&& $this->is_mysql_unsigned_integer_token( $value_token )
				) {
					$value = $value_token->get_value();
				} else {
					return null;
				}

				$operator = '=';
			} elseif ( WP_MySQL_Lexer::LIKE_SYMBOL === $operator_token->id && $this->is_mysql_quoted_text_token( $value_token ) ) {
				$operator = 'like';
				$value    = $value_token->get_value();
			} else {
				return null;
			}

			$filters[] = array(
				'column'   => $column,
				'operator' => $operator,
				'value'    => $value,
			);

			$position += 3;
			if ( $position === $statement_end ) {
				break;
			}

			if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::AND_SYMBOL !== $tokens[ $position ]->id ) {
				return null;
			}
			++$position;
		}

		return empty( $filters ) ? null : $filters;
	}

	/**
	 * Get the MySQL SHOW output column name represented by a token.
	 *
	 * @param WP_MySQL_Token      $token           MySQL token.
	 * @param array<string,string> $allowed_columns Allowed output columns keyed by lower-case name.
	 * @return string|null Output column name, or null when unsupported.
	 */
	private function get_mysql_show_output_column_name( WP_MySQL_Token $token, array $allowed_columns ): ?string {
		$column = $this->get_mysql_identifier_token_value( $token );
		if ( null === $column && $this->is_mysql_show_output_column_keyword_token( $token ) ) {
			$column = $token->get_value();
		}
		if ( null === $column ) {
			return null;
		}

		$column_key = strtolower( $column );
		return $allowed_columns[ $column_key ] ?? null;
	}

	/**
	 * Check whether a MySQL keyword token can represent a SHOW output column.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token is a supported SHOW output column keyword.
	 */
	private function is_mysql_show_output_column_keyword_token( WP_MySQL_Token $token ): bool {
		return in_array(
			$token->id,
			array(
				WP_MySQL_Lexer::AUTO_INCREMENT_SYMBOL,
				WP_MySQL_Lexer::CHARSET_SYMBOL,
				WP_MySQL_Lexer::COLLATION_SYMBOL,
				WP_MySQL_Lexer::COLUMN_NAME_SYMBOL,
				WP_MySQL_Lexer::COMMENT_SYMBOL,
				WP_MySQL_Lexer::CHECKSUM_SYMBOL,
				WP_MySQL_Lexer::DATABASE_SYMBOL,
				WP_MySQL_Lexer::DEFAULT_SYMBOL,
				WP_MySQL_Lexer::ENGINE_SYMBOL,
				WP_MySQL_Lexer::KEY_SYMBOL,
				WP_MySQL_Lexer::NAME_SYMBOL,
				WP_MySQL_Lexer::NULL_SYMBOL,
				WP_MySQL_Lexer::PRIVILEGES_SYMBOL,
				WP_MySQL_Lexer::ROWS_SYMBOL,
				WP_MySQL_Lexer::TABLE_SYMBOL,
				WP_MySQL_Lexer::TYPE_SYMBOL,
				WP_MySQL_Lexer::VALUE_SYMBOL,
				WP_MySQL_Lexer::VISIBLE_SYMBOL,
			),
			true
		);
	}

	/**
	 * Check whether a MySQL token is a quoted text literal.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token is quoted text.
	 */
	private function is_mysql_quoted_text_token( WP_MySQL_Token $token ): bool {
		return WP_MySQL_Lexer::SINGLE_QUOTED_TEXT === $token->id
			|| WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT === $token->id;
	}

	/**
	 * Parse a supported MySQL SHOW COLUMNS/FIELDS statement.
	 *
	 * @param string $query MySQL query.
	 * @return array{schema: string, table: string, full: bool, like: string|null, where: array|null}|null SHOW COLUMNS options, or null when this is not a SHOW COLUMNS/FIELDS statement.
	 */
	private function get_show_columns_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::SHOW_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$position = 1;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::EXTENDED_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		$is_full = false;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::FULL_SYMBOL === $tokens[ $position ]->id ) {
			$is_full = true;
			++$position;
		}

		if (
			! isset( $tokens[ $position ] )
			|| (
				WP_MySQL_Lexer::COLUMNS_SYMBOL !== $tokens[ $position ]->id
				&& WP_MySQL_Lexer::FIELDS_SYMBOL !== $tokens[ $position ]->id
			)
		) {
			return null;
		}

		++$position;
		if (
			! isset( $tokens[ $position ] )
			|| (
				WP_MySQL_Lexer::FROM_SYMBOL !== $tokens[ $position ]->id
				&& WP_MySQL_Lexer::IN_SYMBOL !== $tokens[ $position ]->id
			)
		) {
			throw new InvalidArgumentException( 'Unsupported SHOW COLUMNS statement.' );
		}

		++$position;
		$table_reference = $this->get_show_columns_table_reference( $tokens, $position );
		if ( null === $table_reference ) {
			throw new InvalidArgumentException( 'Unsupported SHOW COLUMNS statement.' );
		}

		$schema_name = $this->get_mysql_read_table_backend_schema( $table_reference['schema'] );
		$table_name  = $table_reference['table'];
		$position    = $table_reference['position'];

		if (
			isset( $tokens[ $position ] )
			&& (
				WP_MySQL_Lexer::FROM_SYMBOL === $tokens[ $position ]->id
				|| WP_MySQL_Lexer::IN_SYMBOL === $tokens[ $position ]->id
			)
		) {
			$schema_name = $this->get_mysql_identifier_token_value( $tokens[ $position + 1 ] ?? null );
			if ( null === $schema_name ) {
				throw new InvalidArgumentException( 'Unsupported SHOW COLUMNS statement.' );
			}

			$schema_name = $this->get_mysql_read_table_backend_schema( $schema_name );
			$position   += 2;
		}

		$like = null;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::LIKE_SYMBOL === $tokens[ $position ]->id ) {
			if (
				! isset( $tokens[ $position + 1 ] )
				|| (
					WP_MySQL_Lexer::SINGLE_QUOTED_TEXT !== $tokens[ $position + 1 ]->id
					&& WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT !== $tokens[ $position + 1 ]->id
				)
			) {
				throw new InvalidArgumentException( 'Unsupported SHOW COLUMNS statement.' );
			}

			$like      = $tokens[ $position + 1 ]->get_value();
			$position += 2;
		}

		$where = null;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::WHERE_SYMBOL === $tokens[ $position ]->id ) {
			if ( null !== $like ) {
				throw new InvalidArgumentException( 'Unsupported SHOW COLUMNS statement.' );
			}

			$allowed_columns = array(
				'field'   => 'Field',
				'type'    => 'Type',
				'null'    => 'Null',
				'key'     => 'Key',
				'default' => 'Default',
				'extra'   => 'Extra',
			);
			if ( $is_full ) {
				$allowed_columns['collation']  = 'Collation';
				$allowed_columns['privileges'] = 'Privileges';
				$allowed_columns['comment']    = 'Comment';
			}

			$where = $this->get_mysql_show_where_filters( $tokens, $position, $allowed_columns );
			if ( null === $where ) {
				$where = $this->get_mysql_show_where_expression_filter( $tokens, $position, $allowed_columns );
			}
			if ( null === $where ) {
				throw new InvalidArgumentException( 'Unsupported SHOW COLUMNS statement.' );
			}

			$position = $this->get_mysql_statement_end_position( $tokens, $position );
			if ( null === $position ) {
				throw new InvalidArgumentException( 'Unsupported SHOW COLUMNS statement.' );
			}
		}

		if ( ! $this->is_at_mysql_query_end( $tokens, $position ) ) {
			throw new InvalidArgumentException( 'Unsupported SHOW COLUMNS statement.' );
		}

		return array(
			'schema' => $schema_name,
			'table'  => $table_name,
			'full'   => $is_full,
			'like'   => $like,
			'where'  => $where,
		);
	}

	/**
	 * Parse a SHOW COLUMNS table reference.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Table reference start position.
	 * @return array{schema: string|null, table: string, position: int}|null Parsed reference, or null when unsupported.
	 */
	private function get_show_columns_table_reference( array $tokens, int $position ): ?array {
		$first_identifier = $this->get_mysql_table_reference_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $first_identifier ) {
			return null;
		}

		++$position;
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::DOT_SYMBOL !== $tokens[ $position ]->id ) {
			return array(
				'schema'   => null,
				'table'    => $first_identifier,
				'position' => $position,
			);
		}

		$table_name = $this->get_mysql_table_reference_identifier_token_value( $tokens[ $position + 1 ] ?? null );
		if ( null === $table_name ) {
			return null;
		}

		return array(
			'schema'   => $first_identifier,
			'table'    => $table_name,
			'position' => $position + 2,
		);
	}

	/**
	 * Parse a supported MySQL SHOW INDEX/SHOW INDEXES/SHOW KEYS statement.
	 *
	 * SHOW EXTENDED INDEX-family statements use the same backing metadata rows;
	 * hidden index rows are not modeled separately by this compatibility layer.
	 *
	 * @param string $query MySQL query.
	 * @return array{schema: string, table: string, where: array|null}|null SHOW INDEX options, or null when this is not a SHOW INDEX statement.
	 */
	private function get_show_index_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0], $tokens[1] ) || WP_MySQL_Lexer::SHOW_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$position = 1;
		if ( WP_MySQL_Lexer::EXTENDED_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		if (
			! isset( $tokens[ $position ] )
			|| (
				WP_MySQL_Lexer::INDEX_SYMBOL !== $tokens[ $position ]->id
				&& WP_MySQL_Lexer::INDEXES_SYMBOL !== $tokens[ $position ]->id
				&& WP_MySQL_Lexer::KEYS_SYMBOL !== $tokens[ $position ]->id
			)
		) {
			return null;
		}

		++$position;
		if (
			! isset( $tokens[ $position ] )
			|| (
				WP_MySQL_Lexer::FROM_SYMBOL !== $tokens[ $position ]->id
				&& WP_MySQL_Lexer::IN_SYMBOL !== $tokens[ $position ]->id
			)
		) {
			throw new InvalidArgumentException( 'Unsupported SHOW INDEX statement.' );
		}

		++$position;
		$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position );
		if ( null === $table_reference ) {
			throw new InvalidArgumentException( 'Unsupported SHOW INDEX statement.' );
		}

		if (
			isset( $tokens[ $position ] )
			&& (
				WP_MySQL_Lexer::FROM_SYMBOL === $tokens[ $position ]->id
				|| WP_MySQL_Lexer::IN_SYMBOL === $tokens[ $position ]->id
			)
		) {
			$schema_name = $this->get_mysql_identifier_token_value( $tokens[ $position + 1 ] ?? null );
			if ( null === $schema_name ) {
				throw new InvalidArgumentException( 'Unsupported SHOW INDEX statement.' );
			}

			$table_reference['schema'] = $this->get_mysql_read_table_backend_schema( $schema_name );
			$position                 += 2;
		}

		$schema_name = $this->get_mysql_read_table_backend_schema( $table_reference['schema'] );
		$table_name  = $table_reference['table'];
		$where       = null;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::WHERE_SYMBOL === $tokens[ $position ]->id ) {
			$allowed_columns = array(
				'table'         => 'Table',
				'non_unique'    => 'Non_unique',
				'key_name'      => 'Key_name',
				'seq_in_index'  => 'Seq_in_index',
				'column_name'   => 'Column_name',
				'collation'     => 'Collation',
				'cardinality'   => 'Cardinality',
				'sub_part'      => 'Sub_part',
				'packed'        => 'Packed',
				'null'          => 'Null',
				'index_type'    => 'Index_type',
				'comment'       => 'Comment',
				'index_comment' => 'Index_comment',
				'visible'       => 'Visible',
				'expression'    => 'Expression',
			);
			$numeric_columns  = array(
				'Non_unique',
				'Seq_in_index',
				'Cardinality',
				'Sub_part',
			);
			$where          = $this->get_mysql_show_where_filters(
				$tokens,
				$position,
				$allowed_columns,
				$numeric_columns
			);
			if ( null === $where ) {
				$where = $this->get_mysql_show_where_expression_filter( $tokens, $position, $allowed_columns, $numeric_columns );
			}
			if ( null === $where ) {
				throw new InvalidArgumentException( 'Unsupported SHOW INDEX statement.' );
			}

			$position = $this->get_mysql_statement_end_position( $tokens, $position );
			if ( null === $position ) {
				throw new InvalidArgumentException( 'Unsupported SHOW INDEX statement.' );
			}
		}

		if ( ! $this->is_at_mysql_query_end( $tokens, $position ) ) {
			throw new InvalidArgumentException( 'Unsupported SHOW INDEX statement.' );
		}

		return array(
			'schema' => $schema_name,
			'table'  => $table_name,
			'where'  => $where,
		);
	}

	/**
	 * Parse a supported MySQL table administration statement.
	 *
	 * @param string $query MySQL query.
	 * @return array{operation: string, tables: array<int, array{schema: string|null, table: string}>}|null Administration query, or null when this is not a table administration statement.
	 */
	private function get_mysql_table_administration_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) ) {
			return null;
		}

		switch ( $tokens[0]->id ) {
			case WP_MySQL_Lexer::ANALYZE_SYMBOL:
				$operation = 'analyze';
				break;
			case WP_MySQL_Lexer::CHECK_SYMBOL:
				$operation = 'check';
				break;
			case WP_MySQL_Lexer::OPTIMIZE_SYMBOL:
				$operation = 'optimize';
				break;
			case WP_MySQL_Lexer::REPAIR_SYMBOL:
				$operation = 'repair';
				break;
			default:
				return null;
		}

		$position = 1;
		$this->consume_mysql_table_administration_leading_option( $tokens, $position, $operation );

		if (
			! isset( $tokens[ $position ] )
			|| ! in_array( $tokens[ $position ]->id, array( WP_MySQL_Lexer::TABLE_SYMBOL, WP_MySQL_Lexer::TABLES_SYMBOL ), true )
		) {
			throw new InvalidArgumentException( 'Unsupported table administration statement.' );
		}

		$tables   = array();
		++$position;
		while ( true ) {
			$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position );
			if ( null === $table_reference ) {
				throw new InvalidArgumentException( 'Unsupported table administration statement.' );
			}

			$tables[] = $table_reference;
			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
				continue;
			}

			break;
		}

		$position = $this->consume_mysql_table_administration_trailing_options( $tokens, $position, $operation );
		if ( null === $position ) {
			throw new InvalidArgumentException( 'Unsupported table administration statement.' );
		}

		if ( ! $this->is_at_mysql_query_end( $tokens, $position ) ) {
			throw new InvalidArgumentException( 'Unsupported table administration statement.' );
		}

		return array(
			'operation' => $operation,
			'tables'    => $tables,
		);
	}

	/**
	 * Consume a supported table-administration option before TABLE.
	 *
	 * @param WP_MySQL_Token[] $tokens    MySQL lexer token stream.
	 * @param int              $position  Current token position, updated on success.
	 * @param string           $operation Administration operation.
	 */
	private function consume_mysql_table_administration_leading_option( array $tokens, int &$position, string $operation ): void {
		if ( ! in_array( $operation, array( 'analyze', 'optimize', 'repair' ), true ) ) {
			return;
		}

		if (
			isset( $tokens[ $position ] )
			&& in_array( $tokens[ $position ]->id, array( WP_MySQL_Lexer::LOCAL_SYMBOL, WP_MySQL_Lexer::NO_WRITE_TO_BINLOG_SYMBOL ), true )
		) {
			++$position;
		}
	}

	/**
	 * Consume supported table-administration options after the table list.
	 *
	 * PostgreSQL has no direct equivalent for MySQL's storage-engine maintenance
	 * modifiers, so they are accepted as compatibility no-ops.
	 *
	 * @param WP_MySQL_Token[] $tokens    MySQL lexer token stream.
	 * @param int              $position  Current token position.
	 * @param string           $operation Administration operation.
	 * @return int|null Position after options, or null when unsupported.
	 */
	private function consume_mysql_table_administration_trailing_options( array $tokens, int $position, string $operation ): ?int {
		if ( 'check' === $operation ) {
			while ( ! $this->is_at_mysql_query_end( $tokens, $position ) ) {
				if (
					isset( $tokens[ $position ], $tokens[ $position + 1 ] )
					&& WP_MySQL_Lexer::FOR_SYMBOL === $tokens[ $position ]->id
					&& WP_MySQL_Lexer::UPGRADE_SYMBOL === $tokens[ $position + 1 ]->id
				) {
					$position += 2;
					continue;
				}

				if (
					isset( $tokens[ $position ] )
					&& in_array(
						$tokens[ $position ]->id,
						array(
							WP_MySQL_Lexer::QUICK_SYMBOL,
							WP_MySQL_Lexer::FAST_SYMBOL,
							WP_MySQL_Lexer::MEDIUM_SYMBOL,
							WP_MySQL_Lexer::EXTENDED_SYMBOL,
							WP_MySQL_Lexer::CHANGED_SYMBOL,
						),
						true
					)
				) {
					++$position;
					continue;
				}

				return null;
			}

			return $position;
		}

		if ( 'analyze' === $operation ) {
			if ( $this->is_at_mysql_query_end( $tokens, $position ) ) {
				return $position;
			}

			if (
				isset( $tokens[ $position ], $tokens[ $position + 1 ], $tokens[ $position + 2 ] )
				&& WP_MySQL_Lexer::UPDATE_SYMBOL === $tokens[ $position ]->id
				&& WP_MySQL_Lexer::HISTOGRAM_SYMBOL === $tokens[ $position + 1 ]->id
				&& WP_MySQL_Lexer::ON_SYMBOL === $tokens[ $position + 2 ]->id
			) {
				$position = $this->consume_mysql_table_administration_histogram_columns( $tokens, $position + 3 );
				if ( null === $position ) {
					return null;
				}

				if ( $this->is_at_mysql_query_end( $tokens, $position ) ) {
					return $position;
				}

				if (
					isset( $tokens[ $position ], $tokens[ $position + 1 ], $tokens[ $position + 2 ] )
					&& WP_MySQL_Lexer::WITH_SYMBOL === $tokens[ $position ]->id
					&& $this->is_mysql_unsigned_integer_token( $tokens[ $position + 1 ] )
					&& WP_MySQL_Lexer::BUCKETS_SYMBOL === $tokens[ $position + 2 ]->id
				) {
					$position += 3;
					if ( $this->is_at_mysql_query_end( $tokens, $position ) ) {
						return $position;
					}
				}

				return $this->consume_mysql_table_administration_using_data_clause( $tokens, $position );
			}

			if (
				isset( $tokens[ $position ], $tokens[ $position + 1 ], $tokens[ $position + 2 ] )
				&& WP_MySQL_Lexer::DROP_SYMBOL === $tokens[ $position ]->id
				&& WP_MySQL_Lexer::HISTOGRAM_SYMBOL === $tokens[ $position + 1 ]->id
				&& WP_MySQL_Lexer::ON_SYMBOL === $tokens[ $position + 2 ]->id
			) {
				return $this->consume_mysql_table_administration_histogram_columns( $tokens, $position + 3 );
			}

			return null;
		}

		if ( 'repair' === $operation ) {
			while ( ! $this->is_at_mysql_query_end( $tokens, $position ) ) {
				if (
					isset( $tokens[ $position ] )
					&& in_array(
						$tokens[ $position ]->id,
						array(
							WP_MySQL_Lexer::QUICK_SYMBOL,
							WP_MySQL_Lexer::EXTENDED_SYMBOL,
							WP_MySQL_Lexer::USE_FRM_SYMBOL,
						),
						true
					)
				) {
					++$position;
					continue;
				}

				return null;
			}

			return $position;
		}

		return $position;
	}

	/**
	 * Consume an ANALYZE TABLE UPDATE HISTOGRAM USING DATA clause.
	 *
	 * PostgreSQL does not consume MySQL histogram JSON, but accepting the clause
	 * keeps MySQL-compatible maintenance statements as no-ops like SQLite.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current token position.
	 * @return int|null Position after the clause, or null when unsupported.
	 */
	private function consume_mysql_table_administration_using_data_clause( array $tokens, int $position ): ?int {
		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ], $tokens[ $position + 2 ] )
			|| WP_MySQL_Lexer::USING_SYMBOL !== $tokens[ $position ]->id
			|| WP_MySQL_Lexer::DATA_SYMBOL !== $tokens[ $position + 1 ]->id
			|| ! $this->is_mysql_string_literal_token( $tokens[ $position + 2 ] )
		) {
			return null;
		}

		$position += 3;
		return $this->is_at_mysql_query_end( $tokens, $position ) ? $position : null;
	}

	/**
	 * Consume a comma-separated ANALYZE TABLE histogram column list.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Current token position.
	 * @return int|null Position after the list, or null when unsupported.
	 */
	private function consume_mysql_table_administration_histogram_columns( array $tokens, int $position ): ?int {
		$matched = false;
		while ( isset( $tokens[ $position ] ) ) {
			$column = $this->get_mysql_identifier_token_value( $tokens[ $position ] );
			if ( null === $column ) {
				return null;
			}

			$matched = true;
			++$position;

			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
				continue;
			}

			break;
		}

		return $matched ? $position : null;
	}

	/**
	 * Parse one table reference from a MySQL table administration statement.
	 *
	 * @param WP_MySQL_Token[] $tokens              MySQL lexer token stream.
	 * @param int              $position            Current token position, updated on success.
	 * @param bool             $allow_double_quoted Whether to accept double-quoted text as an identifier.
	 * @return array{schema: string|null, table: string}|null Parsed table reference, or null when unsupported.
	 */
	private function get_mysql_table_administration_table_reference( array $tokens, int &$position, bool $allow_double_quoted = false ): ?array {
		$first_identifier = $this->get_mysql_table_reference_identifier_token_value( $tokens[ $position ] ?? null, $allow_double_quoted );
		if ( null === $first_identifier ) {
			return null;
		}

		++$position;
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::DOT_SYMBOL !== $tokens[ $position ]->id ) {
			return array(
				'schema' => null,
				'table'  => $first_identifier,
			);
		}

		$table_name = $this->get_mysql_table_reference_identifier_token_value( $tokens[ $position + 1 ] ?? null, $allow_double_quoted );
		if ( null === $table_name ) {
			return null;
		}

		$position += 2;
		return array(
			'schema' => $first_identifier,
			'table'  => $table_name,
		);
	}

	/**
	 * Get an identifier for a table reference, including supported information_schema relation keywords.
	 *
	 * @param WP_MySQL_Token|null $token               MySQL token.
	 * @param bool                $allow_double_quoted Whether double-quoted text may identify a table.
	 * @return string|null Identifier value, or null.
	 */
	private function get_mysql_table_reference_identifier_token_value( ?WP_MySQL_Token $token, bool $allow_double_quoted = false ): ?string {
		$identifier = $this->get_mysql_identifier_token_value( $token, $allow_double_quoted );
		if ( null !== $identifier ) {
			return $identifier;
		}

		$identifier = $this->get_direct_information_schema_identifier_token_value( $token );
		if ( null === $identifier ) {
			return null;
		}

		return null === $this->get_direct_information_schema_relation_columns( $identifier ) ? null : $identifier;
	}

	/**
	 * Parse a supported MySQL TRUNCATE TABLE statement.
	 *
	 * @param string $query MySQL query.
	 * @return array{schema: string|null, table: string}|null Truncate query, or null when this is not TRUNCATE.
	 */
	private function get_mysql_truncate_table_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::TRUNCATE_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$position = 1;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::TABLE_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position );
		if ( null === $table_reference || ! $this->is_at_mysql_query_end( $tokens, $position ) ) {
			throw new InvalidArgumentException( 'Unsupported TRUNCATE TABLE statement.' );
		}

		return $table_reference;
	}

	/**
	 * Parse a supported MySQL LOCK/UNLOCK TABLES statement.
	 *
	 * @param string $query MySQL query.
	 * @return array{operation: string, tables: array<int, array{schema: string|null, table: string, mode: string}>}|null Lock query, or null when this is not LOCK/UNLOCK.
	 */
	private function get_mysql_lock_tables_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) ) {
			return null;
		}

		if ( WP_MySQL_Lexer::UNLOCK_SYMBOL === $tokens[0]->id ) {
			if (
				! isset( $tokens[1] )
				|| (
					WP_MySQL_Lexer::TABLE_SYMBOL !== $tokens[1]->id
					&& WP_MySQL_Lexer::TABLES_SYMBOL !== $tokens[1]->id
				)
				|| ! $this->is_at_mysql_query_end( $tokens, 2 )
			) {
				throw new InvalidArgumentException( 'Unsupported UNLOCK TABLES statement.' );
			}

			return array(
				'operation' => 'unlock',
				'tables'    => array(),
			);
		}

		if ( WP_MySQL_Lexer::LOCK_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		if (
			! isset( $tokens[1] )
			|| (
				WP_MySQL_Lexer::TABLE_SYMBOL !== $tokens[1]->id
				&& WP_MySQL_Lexer::TABLES_SYMBOL !== $tokens[1]->id
			)
		) {
			throw new InvalidArgumentException( 'Unsupported LOCK TABLES statement.' );
		}

		$tables   = array();
		$position = 2;
		while ( true ) {
			$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position );
			if ( null === $table_reference || ! isset( $tokens[ $position ] ) ) {
				throw new InvalidArgumentException( 'Unsupported LOCK TABLES statement.' );
			}

			if ( WP_MySQL_Lexer::READ_SYMBOL === $tokens[ $position ]->id ) {
				$mode = 'read';
			} elseif ( WP_MySQL_Lexer::WRITE_SYMBOL === $tokens[ $position ]->id ) {
				$mode = 'write';
			} else {
				throw new InvalidArgumentException( 'Unsupported LOCK TABLES statement.' );
			}

			++$position;
			$tables[] = array(
				'schema' => $table_reference['schema'],
				'table'  => $table_reference['table'],
				'mode'   => $mode,
			);

			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
				continue;
			}

			break;
		}

		if ( ! $this->is_at_mysql_query_end( $tokens, $position ) ) {
			throw new InvalidArgumentException( 'Unsupported LOCK TABLES statement.' );
		}

		return array(
			'operation' => 'lock',
			'tables'    => $tables,
		);
	}

	/**
	 * Execute a supported MySQL LOCK/UNLOCK TABLES statement as a compatibility no-op.
	 *
	 * @param array $lock_tables_query Parsed lock query.
	 * @return int Number of affected rows.
	 */
	private function execute_mysql_lock_tables_query( array $lock_tables_query ): int {
		if ( 'unlock' === $lock_tables_query['operation'] ) {
			$this->last_result = 0;
			$this->clear_last_column_meta();
			return $this->last_result;
		}

		foreach ( $lock_tables_query['tables'] as $table_reference ) {
			$requested_schema = $table_reference['schema'];
			$table_name       = $table_reference['table'];
			if (
				( null === $requested_schema && 0 === strcasecmp( $this->db_name, 'information_schema' ) )
				|| ( null !== $requested_schema && 0 === strcasecmp( $requested_schema, 'information_schema' ) )
			) {
				throw new InvalidArgumentException( 'Unsupported LOCK TABLES statement.' );
			}

			if ( ! $this->mysql_table_administration_table_exists( $requested_schema, $table_name ) ) {
				$table_label = $this->get_mysql_table_administration_result_table_name( $requested_schema, $table_name );
				throw new InvalidArgumentException( sprintf( "Table '%s' doesn't exist", $table_label ) );
			}
		}

		$this->last_result = 0;
		$this->clear_last_column_meta();
		return $this->last_result;
	}

	/**
	 * Execute a MySQL table administration statement.
	 *
	 * @param array $administration_query Parsed administration query.
	 * @param int   $fetch_mode           PDO fetch mode.
	 * @param array ...$fetch_mode_args   Additional fetch mode arguments.
	 * @return mixed Administration result rows.
	 */
	private function execute_mysql_table_administration_query( array $administration_query, $fetch_mode, ...$fetch_mode_args ) {
		$operation = $administration_query['operation'];
		$rows      = array();

		foreach ( $administration_query['tables'] as $table_reference ) {
			$requested_schema = $table_reference['schema'];
			$table_name       = $table_reference['table'];
			if ( null !== $requested_schema && 'information_schema' === strtolower( $requested_schema ) ) {
				throw new InvalidArgumentException( 'Unsupported table administration statement.' );
			}

			$table_label = $this->get_mysql_table_administration_result_table_name( $requested_schema, $table_name );
			if ( $this->mysql_table_administration_table_exists( $requested_schema, $table_name ) ) {
				$rows[] = array(
					'Table'    => $table_label,
					'Op'       => $operation,
					'Msg_type' => 'status',
					'Msg_text' => 'OK',
				);
				continue;
			}

			$rows[] = array(
				'Table'    => $table_label,
				'Op'       => $operation,
				'Msg_type' => 'Error',
				'Msg_text' => sprintf( "Table '%s' doesn't exist", $table_name ),
			);
			$rows[] = array(
				'Table'    => $table_label,
				'Op'       => $operation,
				'Msg_type' => 'status',
				'Msg_text' => 'Operation failed',
			);
		}

		return $this->set_mysql_static_show_result(
			array( 'Table', 'Op', 'Msg_type', 'Msg_text' ),
			$rows,
			$fetch_mode,
			...$fetch_mode_args
		);
	}

	/**
	 * Get the MySQL-facing Table column value for an administration result row.
	 *
	 * @param string|null $requested_schema Requested schema, or null for the current database.
	 * @param string      $table_name       Table name.
	 * @return string MySQL-facing qualified table name.
	 */
	private function get_mysql_table_administration_result_table_name( ?string $requested_schema, string $table_name ): string {
		$display_schema = null === $requested_schema ? $this->db_name : $requested_schema;
		return $display_schema . '.' . $table_name;
	}

	/**
	 * Check whether a table administration target exists.
	 *
	 * @param string|null $requested_schema Requested schema, or null for the current database.
	 * @param string      $table_name       Table name.
	 * @return bool Whether the backend table exists.
	 */
	private function mysql_table_administration_table_exists( ?string $requested_schema, string $table_name ): bool {
		$schema_name = $this->get_mysql_table_administration_backend_schema( $requested_schema, $table_name );
		$driver_name = $this->connection->get_driver_name();

		if ( 'sqlite' === $driver_name ) {
			return $this->sqlite_table_administration_table_exists( $schema_name, $table_name );
		}

		$stmt = $this->connection->query(
			'SELECT 1
			FROM pg_catalog.pg_class c
			INNER JOIN pg_catalog.pg_namespace n
				ON n.oid = c.relnamespace
			WHERE n.nspname = ?
				AND c.relname = ?
				AND c.relkind IN (\'r\', \'p\')
			LIMIT 1',
			array( $schema_name, $table_name )
		);

		return false !== $stmt->fetchColumn();
	}

	/**
	 * Resolve the backend schema for a MySQL table administration target.
	 *
	 * @param string|null $requested_schema Requested schema, or null for the current database.
	 * @param string      $table_name       Table name.
	 * @return string Backend schema name.
	 */
	private function get_mysql_table_administration_backend_schema( ?string $requested_schema, string $table_name ): string {
		if ( null === $requested_schema || 0 === strcasecmp( $requested_schema, $this->db_name ) ) {
			return $this->resolve_mysql_table_schema_for_introspection( 'public', $table_name );
		}

		return $this->resolve_mysql_table_schema_for_introspection( $requested_schema, $table_name );
	}

	/**
	 * Check whether a SQLite-backed test table administration target exists.
	 *
	 * @param string $schema_name Backend schema name.
	 * @param string $table_name  Table name.
	 * @return bool Whether the table exists.
	 */
	private function sqlite_table_administration_table_exists( string $schema_name, string $table_name ): bool {
		if ( 'temp' === $schema_name ) {
			return $this->sqlite_table_administration_table_exists_in_catalog( 'sqlite_temp_master', $table_name );
		}

		if ( 'public' === $schema_name ) {
			if (
				$this->sqlite_database_schema_exists( 'public' )
				&& $this->sqlite_table_administration_table_exists_in_catalog(
					$this->connection->quote_identifier( 'public' ) . '.sqlite_master',
					$table_name
				)
			) {
				return true;
			}

			return $this->sqlite_table_administration_table_exists_in_catalog( 'sqlite_master', $table_name );
		}

		if ( 'main' === $schema_name ) {
			return $this->sqlite_table_administration_table_exists_in_catalog( 'sqlite_master', $table_name );
		}

		if ( ! $this->sqlite_database_schema_exists( $schema_name ) ) {
			return false;
		}

		return $this->sqlite_table_administration_table_exists_in_catalog(
			$this->connection->quote_identifier( $schema_name ) . '.sqlite_master',
			$table_name
		);
	}

	/**
	 * Check whether a table exists in one SQLite catalog table.
	 *
	 * @param string $catalog_sql SQLite catalog table SQL.
	 * @param string $table_name  Table name.
	 * @return bool Whether the table exists.
	 */
	private function sqlite_table_administration_table_exists_in_catalog( string $catalog_sql, string $table_name ): bool {
		$stmt = $this->connection->query(
			sprintf(
				'SELECT name FROM %s WHERE type = \'table\' AND name = ? LIMIT 1',
				$catalog_sql
			),
			array( $table_name )
		);

		return false !== $stmt->fetchColumn();
	}

	/**
	 * Check whether a SQLite attached database schema exists.
	 *
	 * @param string $schema_name Schema name.
	 * @return bool Whether the schema exists.
	 */
	private function sqlite_database_schema_exists( string $schema_name ): bool {
		$stmt = $this->connection->query( 'PRAGMA database_list' );
		foreach ( $stmt->fetchAll( PDO::FETCH_ASSOC ) as $database ) {
			if ( isset( $database['name'] ) && $schema_name === (string) $database['name'] ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Execute a MySQL DESCRIBE/DESC statement through PostgreSQL catalogs.
	 *
	 * @param string $schema_name         Schema name.
	 * @param string $table_name          Table name.
	 * @param int    $fetch_mode          PDO fetch mode.
	 * @param array  ...$fetch_mode_args  Additional fetch mode arguments.
	 * @return mixed DESCRIBE result rows.
	 */
	private function execute_describe_query( string $schema_name, string $table_name, $fetch_mode, ...$fetch_mode_args ) {
		$this->ensure_mysql_schema_metadata_tables();

		$resolved_schema = $this->resolve_mysql_table_schema_for_introspection( $schema_name, $table_name );
		$cache_key       = $this->get_mysql_introspection_result_cache_key(
			'describe',
			$fetch_mode,
			array( $resolved_schema, $table_name, $fetch_mode, $fetch_mode_args )
		);
		if ( $this->load_mysql_introspection_result_from_cache( $cache_key ) ) {
			return $this->last_result;
		}

		$sql    = $this->get_describe_catalog_query();
		$params = array(
			$resolved_schema,
			$table_name,
		);
		$stmt   = $this->connection->query( $sql, $params );

		$this->last_postgresql_queries[] = array(
			'sql'    => $sql,
			'params' => $params,
		);
		$this->last_column_meta          = $this->normalize_column_meta( $stmt );
		$this->last_result               = $stmt->fetchAll( $fetch_mode, ...$fetch_mode_args );

		$this->store_mysql_introspection_result_in_cache( $cache_key );

		return $this->last_result;
	}

	/**
	 * Execute a MySQL SHOW COLUMNS/SHOW FULL COLUMNS statement through PostgreSQL catalogs.
	 *
	 * @param string      $schema_name         Schema name.
	 * @param string      $table_name          Table name.
	 * @param bool        $is_full             Whether this is SHOW FULL COLUMNS.
	 * @param string|null $like                Optional MySQL LIKE pattern.
	 * @param array|null  $where_filter        Optional MySQL WHERE filters.
	 * @param int         $fetch_mode          PDO fetch mode.
	 * @param array       ...$fetch_mode_args  Additional fetch mode arguments.
	 * @return mixed SHOW COLUMNS result rows.
	 */
	private function execute_show_columns_query( string $schema_name, string $table_name, bool $is_full, ?string $like, ?array $where_filter, $fetch_mode, ...$fetch_mode_args ) {
		$this->ensure_mysql_schema_metadata_tables();

		$resolved_schema = $this->resolve_mysql_table_schema_for_introspection( $schema_name, $table_name );
		if ( 0 === strcasecmp( $resolved_schema, 'information_schema' ) ) {
			return $this->execute_direct_information_schema_show_columns_query(
				$table_name,
				$is_full,
				$like,
				$where_filter,
				$fetch_mode,
				...$fetch_mode_args
			);
		}

		$cache_key = $this->get_mysql_introspection_result_cache_key(
			'show_columns',
			$fetch_mode,
			array( $resolved_schema, $table_name, $is_full, $like, $where_filter, $fetch_mode, $fetch_mode_args )
		);
		if ( $this->load_mysql_introspection_result_from_cache( $cache_key ) ) {
			return $this->last_result;
		}

		$sql    = $this->get_show_columns_catalog_query( $is_full );
		$params = array(
			$resolved_schema,
			$table_name,
		);

		if ( null !== $like ) {
			$sql     .= " AND field_name LIKE ? ESCAPE '\\'";
			$params[] = $like;
		}

		$where_expression_filter = $this->is_mysql_show_where_expression_filter( $where_filter ) ? $where_filter : null;
		if ( null !== $where_filter && null === $where_expression_filter ) {
			foreach ( $where_filter as $filter ) {
				$sql     .= sprintf(
					' AND %s',
					$this->get_mysql_show_where_filter_condition_sql(
						$this->get_show_columns_filter_column_expression( $filter['column'] ),
						$filter
					)
				);
				$params[] = $filter['value'];
			}
		}

		$sql .= '
ORDER BY ordinal_position';

		$stmt = $this->connection->query( $sql, $params );

		$this->last_postgresql_queries[] = array(
			'sql'    => $sql,
			'params' => $params,
		);
		$this->last_column_meta          = $this->normalize_column_meta( $stmt );
		if ( null !== $where_expression_filter ) {
			$rows = $stmt->fetchAll( PDO::FETCH_ASSOC );
			$rows = $this->filter_mysql_static_show_rows( $rows, $where_expression_filter );
			$this->set_mysql_associative_result_rows( $rows, $fetch_mode, ...$fetch_mode_args );
		} else {
			$this->last_result = $stmt->fetchAll( $fetch_mode, ...$fetch_mode_args );
		}

		$this->store_mysql_introspection_result_in_cache( $cache_key );

		return $this->last_result;
	}

	/**
	 * Execute SHOW COLUMNS for a supported MySQL information_schema relation.
	 *
	 * @param string      $table_name         information_schema relation name.
	 * @param bool        $is_full            Whether this is SHOW FULL COLUMNS.
	 * @param string|null $like               Optional MySQL LIKE pattern.
	 * @param array|null  $where_filter       Optional MySQL WHERE filters.
	 * @param int         $fetch_mode         PDO fetch mode.
	 * @param array       ...$fetch_mode_args Additional fetch mode arguments.
	 * @return mixed SHOW COLUMNS result rows.
	 */
	private function execute_direct_information_schema_show_columns_query( string $table_name, bool $is_full, ?string $like, ?array $where_filter, $fetch_mode, ...$fetch_mode_args ) {
		$columns = $this->get_direct_information_schema_relation_columns( $table_name );
		if ( null === $columns ) {
			return $this->set_mysql_static_show_result(
				$this->get_show_columns_output_columns( $is_full ),
				array(),
				$fetch_mode,
				...$fetch_mode_args
			);
		}

		$rows = array();
		foreach ( $columns as $column ) {
			$row = array(
				'Field'   => $column,
				'Type'    => $this->get_direct_information_schema_show_column_type( $column ),
				'Null'    => 'YES',
				'Key'     => '',
				'Default' => null,
				'Extra'   => '',
			);

			if ( $is_full ) {
				$row = array(
					'Field'      => $row['Field'],
					'Type'       => $row['Type'],
					'Collation'  => null,
					'Null'       => $row['Null'],
					'Key'        => $row['Key'],
					'Default'    => $row['Default'],
					'Extra'      => $row['Extra'],
					'Privileges' => 'select',
					'Comment'    => '',
				);
			}

			$rows[] = $row;
		}

		if ( null !== $like ) {
			$rows = $this->filter_mysql_static_show_rows(
				$rows,
				array(
					'type'    => 'like',
					'column'  => 'Field',
					'pattern' => $like,
				)
			);
		}

		if ( null !== $where_filter ) {
			$rows = $this->filter_mysql_static_show_rows(
				$rows,
				$this->is_mysql_show_where_expression_filter( $where_filter )
					? $where_filter
					: array(
						'type'       => 'where',
						'conditions' => $where_filter,
					)
			);
		}

		return $this->set_mysql_static_show_result(
			$this->get_show_columns_output_columns( $is_full ),
			$rows,
			$fetch_mode,
			...$fetch_mode_args
		);
	}

	/**
	 * Get output columns for SHOW COLUMNS or SHOW FULL COLUMNS.
	 *
	 * @param bool $is_full Whether this is SHOW FULL COLUMNS.
	 * @return string[] Output column names.
	 */
	private function get_show_columns_output_columns( bool $is_full ): array {
		if ( $is_full ) {
			return array( 'Field', 'Type', 'Collation', 'Null', 'Key', 'Default', 'Extra', 'Privileges', 'Comment' );
		}

		return array( 'Field', 'Type', 'Null', 'Key', 'Default', 'Extra' );
	}

	/**
	 * Get a SHOW COLUMNS type for an information_schema output column.
	 *
	 * @param string $column Uppercase information_schema column name.
	 * @return string MySQL type.
	 */
	private function get_direct_information_schema_show_column_type( string $column ): string {
		$type = preg_replace(
			'/\s+DEFAULT\s+NULL\z/i',
			'',
			$this->get_direct_information_schema_create_column_type( $column )
		);

		return null === $type ? 'varchar(512)' : $type;
	}

	/**
	 * Get the SQL expression that backs a MySQL SHOW COLUMNS output column.
	 *
	 * @param string $column MySQL output column name.
	 * @return string SQL expression.
	 */
	private function get_show_columns_filter_column_expression( string $column ): string {
		switch ( $column ) {
			case 'Field':
				return 'field_name';
			case 'Type':
				return 'column_type';
			case 'Collation':
				return 'collation_name';
			case 'Null':
				return 'is_nullable';
			case 'Key':
				return 'column_key';
			case 'Default':
				return 'column_default';
			case 'Extra':
				return 'column_extra';
			case 'Privileges':
				return "'select,insert,update,references'";
			case 'Comment':
				return 'column_comment';
		}

		throw new InvalidArgumentException( 'Unsupported SHOW COLUMNS statement.' );
	}

	/**
	 * Get SQL for a parsed simple SHOW WHERE filter.
	 *
	 * @param string $expression   SQL expression for the SHOW output column.
	 * @param array  $where_filter Parsed SHOW WHERE filter.
	 * @return string SQL condition.
	 */
	private function get_mysql_show_where_filter_condition_sql( string $expression, array $where_filter ): string {
		if ( 'like' === ( $where_filter['operator'] ?? '=' ) ) {
			return sprintf( "%s LIKE ? ESCAPE '\\'", $expression );
		}

		return sprintf( '%s = ?', $expression );
	}

	/**
	 * Execute a supported MySQL USE statement in session state.
	 *
	 * @param string $database_name Requested MySQL-facing database name.
	 * @return int MySQL-compatible affected row count.
	 */
	private function execute_mysql_use_statement( string $database_name ): int {
		if ( 0 === strcasecmp( $database_name, $this->main_db_name ) ) {
			$this->db_name     = $this->main_db_name;
			$this->last_result = 0;
			return $this->last_result;
		}

		if ( 0 === strcasecmp( $database_name, 'information_schema' ) ) {
			$this->db_name     = 'information_schema';
			$this->last_result = 0;
			return $this->last_result;
		}

		throw new InvalidArgumentException( 'Unsupported USE statement.' );
	}

	/**
	 * Execute a MySQL SHOW TABLES statement through PostgreSQL catalogs.
	 *
	 * @param bool        $is_full         Whether this is SHOW FULL TABLES.
	 * @param string      $schema_name     Backend schema name.
	 * @param string      $database_name   MySQL-facing database name.
	 * @param string|null $like            Optional MySQL LIKE pattern.
	 * @param array|null  $where_filter    Optional MySQL WHERE filters.
	 * @param int         $fetch_mode      PDO fetch mode.
	 * @param array       ...$fetch_mode_args Additional fetch mode arguments.
	 * @return mixed SHOW TABLES result rows.
	 */
	private function execute_show_tables_query( bool $is_full, string $schema_name, string $database_name, ?string $like, ?array $where_filter, $fetch_mode, ...$fetch_mode_args ) {
		if ( 0 === strcasecmp( $database_name, 'information_schema' ) ) {
			$columns = array( 'Tables_in_information_schema' );
			if ( $is_full ) {
				$columns[] = 'Table_type';
			}

			return $this->set_mysql_static_show_result( $columns, array(), $fetch_mode, ...$fetch_mode_args );
		}

		$table_column = $this->connection->quote_identifier( 'Tables_in_' . $database_name );
		$sql          = sprintf(
			'SELECT table_name AS %s%s
		FROM information_schema.tables
		WHERE table_schema = ?
				AND table_type IN (\'BASE TABLE\', \'VIEW\')
				AND table_name NOT IN (%s, %s, %s, %s, %s, %s)',
			$table_column,
			$is_full ? ', CASE WHEN table_type = \'VIEW\' THEN \'VIEW\' ELSE \'BASE TABLE\' END AS "Table_type"' : '',
			$this->connection->quote( self::MYSQL_COLUMN_METADATA_TABLE ),
			$this->connection->quote( self::MYSQL_INDEX_METADATA_TABLE ),
			$this->connection->quote( self::MYSQL_FOREIGN_KEY_METADATA_TABLE ),
			$this->connection->quote( self::MYSQL_CHECK_METADATA_TABLE ),
			$this->connection->quote( self::MYSQL_CHARSET_METADATA_TABLE ),
			$this->connection->quote( self::MYSQL_TABLE_METADATA_TABLE )
		);
		$params       = array( $schema_name );

		if ( null !== $like ) {
			$sql     .= " AND table_name LIKE ? ESCAPE '\\'";
			$params[] = $like;
		}

		$where_expression_filter = $this->is_mysql_show_where_expression_filter( $where_filter ) ? $where_filter : null;
		if ( null !== $where_filter && null === $where_expression_filter ) {
			foreach ( $where_filter as $filter ) {
				$sql     .= sprintf(
					' AND %s',
					$this->get_mysql_show_where_filter_condition_sql(
						$this->get_show_tables_filter_column_expression( $filter['column'], $table_column ),
						$filter
					)
				);
				$params[] = $filter['value'];
			}
		}

		$sql .= '
ORDER BY table_name';

		$stmt = $this->connection->query( $sql, $params );

		$this->last_postgresql_queries[] = array(
			'sql'    => $sql,
			'params' => $params,
		);
		$this->last_column_meta          = $this->normalize_column_meta( $stmt );
		if ( null !== $where_expression_filter ) {
			$rows = $stmt->fetchAll( PDO::FETCH_ASSOC );
			$rows = $this->filter_mysql_static_show_rows( $rows, $where_expression_filter );
			$this->set_mysql_associative_result_rows( $rows, $fetch_mode, ...$fetch_mode_args );
		} else {
			$this->last_result = $stmt->fetchAll( $fetch_mode, ...$fetch_mode_args );
		}

		return $this->last_result;
	}

	/**
	 * Get the SQL expression that backs a MySQL SHOW TABLES output column.
	 *
	 * @param string $column       MySQL output column name.
	 * @param string $table_column Quoted Tables_in_* output column.
	 * @return string SQL expression.
	 */
	private function get_show_tables_filter_column_expression( string $column, string $table_column ): string {
		if ( $table_column === $this->connection->quote_identifier( $column ) ) {
			return 'table_name';
		}

		if ( 'Table_type' === $column ) {
			return "CASE WHEN table_type = 'VIEW' THEN 'VIEW' ELSE 'BASE TABLE' END";
		}

		throw new InvalidArgumentException( 'Unsupported SHOW TABLES statement.' );
	}

	/**
	 * Execute a MySQL SHOW TABLE STATUS statement through PostgreSQL catalogs.
	 *
	 * @param array $show_table_status_query SHOW TABLE STATUS options.
	 * @param int   $fetch_mode              PDO fetch mode.
	 * @param array ...$fetch_mode_args      Additional fetch mode arguments.
	 * @return mixed SHOW TABLE STATUS result rows.
	 */
	private function execute_show_table_status_query( array $show_table_status_query, $fetch_mode, ...$fetch_mode_args ) {
		$columns = $this->get_show_table_status_result_columns();
		if ( 0 === strcasecmp( $show_table_status_query['database'], 'information_schema' ) ) {
			return $this->set_mysql_static_show_result( $columns, array(), $fetch_mode, ...$fetch_mode_args );
		}

		$rows = array();
		foreach ( $this->get_show_table_status_catalog_rows() as $catalog_row ) {
			$table_name      = (string) $catalog_row['table_name'];
			$identity_column = isset( $catalog_row['identity_column'] ) && null !== $catalog_row['identity_column']
				? (string) $catalog_row['identity_column']
				: null;

			$rows[] = $this->get_show_table_status_result_row(
				$table_name,
				null === $identity_column
					? null
					: $this->get_show_table_status_auto_increment_value( $table_name, $identity_column ),
				(string) ( $catalog_row['table_comment'] ?? '' )
			);
		}

		$rows = $this->filter_show_table_status_rows( $rows, $show_table_status_query );

		return $this->set_mysql_static_show_result(
			$columns,
			$rows,
			$fetch_mode,
			...$fetch_mode_args
		);
	}

	/**
	 * Get MySQL SHOW TABLE STATUS result columns.
	 *
	 * @return string[] Column names.
	 */
	private function get_show_table_status_result_columns(): array {
		return array(
			'Name',
			'Engine',
			'Version',
			'Row_format',
			'Rows',
			'Avg_row_length',
			'Data_length',
			'Max_data_length',
			'Index_length',
			'Data_free',
			'Auto_increment',
			'Create_time',
			'Update_time',
			'Check_time',
			'Collation',
			'Checksum',
			'Create_options',
			'Comment',
		);
	}

	/**
	 * Execute a MySQL SHOW CREATE TABLE statement from stored MySQL schema metadata.
	 *
	 * @param array $show_create_table_query SHOW CREATE TABLE options.
	 * @param int   $fetch_mode              PDO fetch mode.
	 * @param array ...$fetch_mode_args      Additional fetch mode arguments.
	 * @return mixed SHOW CREATE TABLE result rows.
	 */
	private function execute_show_create_table_query( array $show_create_table_query, $fetch_mode, ...$fetch_mode_args ) {
		$this->ensure_mysql_schema_metadata_tables();

		$table_name      = $show_create_table_query['table'];
		$resolved_schema = $this->resolve_mysql_table_schema_for_introspection(
			$show_create_table_query['schema'],
			$table_name
		);

		if ( 0 === strcasecmp( $resolved_schema, 'information_schema' ) ) {
			$create_statement = $this->get_direct_information_schema_create_table_statement( $table_name );
			if ( null === $create_statement ) {
				return $this->set_mysql_static_show_result(
					array( 'Table', 'Create Table' ),
					array(),
					$fetch_mode,
					...$fetch_mode_args
				);
			}

			return $this->set_mysql_static_show_result(
				array( 'Table', 'Create Table' ),
				array(
					array(
						'Table'        => $table_name,
						'Create Table' => $create_statement,
					),
				),
				$fetch_mode,
				...$fetch_mode_args
			);
		}

		$cache_key = $this->get_mysql_introspection_result_cache_key(
			'show_create_table',
			$fetch_mode,
			array( $resolved_schema, $table_name, $fetch_mode, $fetch_mode_args )
		);
		if ( $this->load_mysql_introspection_result_from_cache( $cache_key ) ) {
			return $this->last_result;
		}

		$columns = $this->get_show_create_table_column_metadata_rows( $resolved_schema, $table_name );
		if ( empty( $columns ) ) {
			return $this->set_mysql_static_show_result(
				array( 'Table', 'Create Table' ),
				array(),
				$fetch_mode,
				...$fetch_mode_args
			);
		}

		$indexes          = $this->get_show_create_table_index_metadata_rows( $resolved_schema, $table_name );
		$foreign_keys     = $this->get_show_create_table_foreign_key_metadata_rows( $resolved_schema, $table_name );
		$checks           = $this->get_show_create_table_check_constraint_metadata_rows( $resolved_schema, $table_name );
		$table_comment    = $this->get_show_create_table_table_comment_metadata( $resolved_schema, $table_name );
		$create_statement = $this->get_mysql_create_table_statement_from_metadata(
			$table_name,
			$columns,
			$indexes,
			$foreign_keys,
			$checks,
			$table_comment,
			$this->is_mysql_temporary_schema_name( $resolved_schema )
		);
		$rows             = array(
			array(
				'Table'        => $table_name,
				'Create Table' => $create_statement,
			),
		);

		$result = $this->set_mysql_static_show_result(
			array( 'Table', 'Create Table' ),
			$rows,
			$fetch_mode,
			...$fetch_mode_args
		);

		$this->store_mysql_introspection_result_in_cache( $cache_key );

		return $result;
	}

	/**
	 * Get column metadata rows for SHOW CREATE TABLE.
	 *
	 * @param string $schema_name Backend metadata schema.
	 * @param string $table_name  Table name.
	 * @return array[] Column metadata rows.
	 */
	private function get_show_create_table_column_metadata_rows( string $schema_name, string $table_name ): array {
		$sql    = sprintf(
			'SELECT column_name, ordinal_position, column_type, character_set_name, collation_name, is_nullable, column_default, extra, column_comment
			FROM %s
			WHERE table_schema = ? AND table_name = ?
			ORDER BY ordinal_position',
			$this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE )
		);
		$params = array( $schema_name, $table_name );
		$stmt   = $this->connection->query( $sql, $params );

		$this->last_postgresql_queries[] = array(
			'sql'    => $sql,
			'params' => $params,
		);

		return $stmt->fetchAll( PDO::FETCH_ASSOC );
	}

	/**
	 * Get index metadata rows for SHOW CREATE TABLE.
	 *
	 * @param string $schema_name Backend metadata schema.
	 * @param string $table_name  Table name.
	 * @return array[] Index metadata rows.
	 */
	private function get_show_create_table_index_metadata_rows( string $schema_name, string $table_name ): array {
		$sql    = sprintf(
			'SELECT key_name, index_ordinal, seq_in_index, column_name, non_unique, index_type, "collation" AS "collation", sub_part, index_comment
			FROM %s
			WHERE table_schema = ? AND table_name = ?
			ORDER BY
				key_name = \'PRIMARY\' DESC,
				non_unique = \'0\' DESC,
				index_type = \'SPATIAL\' DESC,
				index_type = \'BTREE\' DESC,
				index_type = \'FULLTEXT\' DESC,
				index_ordinal,
				seq_in_index',
			$this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE )
		);
		$params = array( $schema_name, $table_name );
		$stmt   = $this->connection->query( $sql, $params );

		$this->last_postgresql_queries[] = array(
			'sql'    => $sql,
			'params' => $params,
		);

		return $stmt->fetchAll( PDO::FETCH_ASSOC );
	}

	/**
	 * Get foreign key metadata rows for SHOW CREATE TABLE.
	 *
	 * @param string $schema_name Backend metadata schema.
	 * @param string $table_name  Table name.
	 * @return array[] Foreign key metadata rows.
	 */
	private function get_show_create_table_foreign_key_metadata_rows( string $schema_name, string $table_name ): array {
		$sql    = sprintf(
			'SELECT constraint_name, constraint_ordinal, seq_in_index, column_name, referenced_table_schema, referenced_table_name, referenced_column_name, update_rule, delete_rule
			FROM %s
			WHERE table_schema = ? AND table_name = ?
			ORDER BY constraint_name, seq_in_index',
			$this->connection->quote_identifier( self::MYSQL_FOREIGN_KEY_METADATA_TABLE )
		);
		$params = array( $schema_name, $table_name );
		$stmt   = $this->connection->query( $sql, $params );

		$this->last_postgresql_queries[] = array(
			'sql'    => $sql,
			'params' => $params,
		);

		return $stmt->fetchAll( PDO::FETCH_ASSOC );
	}

	/**
	 * Get CHECK constraint metadata rows for SHOW CREATE TABLE.
	 *
	 * @param string $schema_name Backend metadata schema.
	 * @param string $table_name  Table name.
	 * @return array[] CHECK constraint metadata rows.
	 */
	private function get_show_create_table_check_constraint_metadata_rows( string $schema_name, string $table_name ): array {
		$sql    = sprintf(
			'SELECT constraint_name, constraint_ordinal, check_clause, enforced
			FROM %s
			WHERE table_schema = ? AND table_name = ?
			ORDER BY constraint_ordinal, constraint_name',
			$this->connection->quote_identifier( self::MYSQL_CHECK_METADATA_TABLE )
		);
		$params = array( $schema_name, $table_name );
		$stmt   = $this->connection->query( $sql, $params );

		$metadata_rows = $stmt->fetchAll( PDO::FETCH_ASSOC );

		$this->last_postgresql_queries[] = array(
			'sql'    => $sql,
			'params' => $params,
		);

		if ( ! empty( $metadata_rows ) ) {
			return $metadata_rows;
		}

		$catalog_sql    = 'SELECT
				tc.constraint_name,
				cc.check_clause,
				\'YES\' AS enforced
			FROM information_schema.table_constraints tc
			INNER JOIN information_schema.check_constraints cc
				ON cc.constraint_schema = tc.constraint_schema
				AND cc.constraint_name = tc.constraint_name
			WHERE tc.table_schema = ?
				AND tc.table_name = ?
				AND tc.constraint_type = ?
			ORDER BY tc.constraint_name';
		$catalog_params = array( $schema_name, $table_name, 'CHECK' );

		try {
			$stmt = $this->connection->query( $catalog_sql, $catalog_params );
		} catch ( PDOException $e ) {
			return array();
		}

		$this->last_postgresql_queries[] = array(
			'sql'    => $catalog_sql,
			'params' => $catalog_params,
		);

		return $stmt->fetchAll( PDO::FETCH_ASSOC );
	}

	/**
	 * Get table comment metadata for SHOW CREATE TABLE.
	 *
	 * @param string $schema_name Backend metadata schema.
	 * @param string $table_name  Table name.
	 * @return string Table comment.
	 */
	private function get_show_create_table_table_comment_metadata( string $schema_name, string $table_name ): string {
		$sql    = sprintf(
			'SELECT table_comment
			FROM %s
			WHERE table_schema = ? AND table_name = ?
			LIMIT 1',
			$this->connection->quote_identifier( self::MYSQL_TABLE_METADATA_TABLE )
		);
		$params = array( $schema_name, $table_name );
		$stmt   = $this->connection->query( $sql, $params );

		$this->last_postgresql_queries[] = array(
			'sql'    => $sql,
			'params' => $params,
		);

		$comment = $stmt->fetchColumn();
		return false === $comment ? '' : (string) $comment;
	}

	/**
	 * Build a MySQL CREATE TABLE statement from stored MySQL metadata rows.
	 *
	 * @param string  $table_name    Table name.
	 * @param array[] $columns       Column metadata rows.
	 * @param array[] $indexes       Index metadata rows.
	 * @param array[] $foreign_keys  Foreign key metadata rows.
	 * @param array[] $checks        CHECK constraint metadata rows.
	 * @param string  $table_comment Table comment.
	 * @return string MySQL-compatible CREATE TABLE statement.
	 */
	private function get_mysql_create_table_statement_from_metadata( string $table_name, array $columns, array $indexes, array $foreign_keys, array $checks, string $table_comment = '', bool $temporary = false ): string {
		$definitions = array();
		foreach ( $columns as $column ) {
			$definitions[] = $this->get_mysql_create_table_column_definition_from_metadata( $column );
		}

		foreach ( $this->group_show_create_table_index_metadata_rows( $indexes ) as $index ) {
			$definitions[] = $this->get_mysql_create_table_index_definition_from_metadata( $index );
		}

		foreach ( $this->group_show_create_table_foreign_key_metadata_rows( $foreign_keys ) as $foreign_key ) {
			$definitions[] = $this->get_mysql_create_table_foreign_key_definition_from_metadata( $foreign_key );
		}

		foreach ( $checks as $check ) {
			$definitions[] = $this->get_mysql_create_table_check_constraint_definition_from_metadata( $check );
		}

		$collation = $this->get_mysql_create_table_collation_from_metadata( $columns );
		$charset   = $this->get_mysql_charset_from_collation( $collation );

		$sql = sprintf(
			"CREATE %sTABLE %s (\n%s\n) ENGINE=InnoDB DEFAULT CHARSET=%s COLLATE=%s",
			$temporary ? 'TEMPORARY ' : '',
			$this->quote_mysql_identifier( $table_name ),
			implode( ",\n", $definitions ),
			$charset,
			$collation
		);

		if ( '' !== $table_comment ) {
			$sql .= ' COMMENT=' . $this->quote_mysql_utf8_string_literal( $table_comment );
		}

		return $sql;
	}

	/**
	 * Check whether a backend schema name represents the active temporary table namespace.
	 *
	 * @param string $schema_name Backend schema name.
	 * @return bool Whether the schema is temporary.
	 */
	private function is_mysql_temporary_schema_name( string $schema_name ): bool {
		return 0 === strcasecmp( $schema_name, 'temp' )
			|| 0 === strcasecmp( $schema_name, 'pg_temp' )
			|| 1 === preg_match( '/^pg_temp_[0-9]+$/i', $schema_name );
	}

	/**
	 * Build one MySQL CHECK constraint definition from stored metadata.
	 *
	 * @param array $check CHECK constraint metadata row.
	 * @return string CHECK constraint definition SQL.
	 */
	private function get_mysql_create_table_check_constraint_definition_from_metadata( array $check ): string {
		$sql = sprintf(
			'  CONSTRAINT %s CHECK (%s)',
			$this->quote_mysql_identifier( (string) $check['constraint_name'] ),
			(string) $check['check_clause']
		);

		if ( 'NO' === strtoupper( (string) ( $check['enforced'] ?? 'YES' ) ) ) {
			$sql .= ' /*!80016 NOT ENFORCED */';
		}

		return $sql;
	}

	/**
	 * Build one MySQL column definition from stored metadata.
	 *
	 * @param array $column Column metadata row.
	 * @return string Column definition SQL.
	 */
	private function get_mysql_create_table_column_definition_from_metadata( array $column ): string {
		$extra = (string) ( $column['extra'] ?? '' );
		$sql = sprintf(
			'  %s %s',
			$this->quote_mysql_identifier( (string) $column['column_name'] ),
			(string) $column['column_type']
		);

		if ( 'NO' === strtoupper( (string) $column['is_nullable'] ) ) {
			$sql .= ' NOT NULL';
		}

		if ( false !== stripos( $extra, 'auto_increment' ) ) {
			$sql .= ' AUTO_INCREMENT';
		}

		if ( null !== $column['column_default'] ) {
			$default = (string) $column['column_default'];
			if ( $this->is_mysql_current_timestamp_default_metadata( $default ) ) {
				$sql .= ' DEFAULT ' . $default;
			} elseif ( $this->mysql_column_extra_has_default_generated( $extra ) ) {
				$sql .= ' DEFAULT (' . $default . ')';
			} else {
				$sql .= ' DEFAULT ' . $this->quote_mysql_utf8_string_literal( $default );
			}
		} elseif ( 'NO' !== strtoupper( (string) $column['is_nullable'] ) ) {
			$sql .= ' DEFAULT NULL';
		}

		if ( $this->mysql_column_extra_has_on_update_current_timestamp( $extra ) ) {
			$sql .= ' ON UPDATE CURRENT_TIMESTAMP';
		}

		if ( '' !== (string) ( $column['column_comment'] ?? '' ) ) {
			$sql .= ' COMMENT ' . $this->quote_mysql_utf8_string_literal( (string) $column['column_comment'] );
		}

		return $sql;
	}

	/**
	 * Check whether stored default metadata is a MySQL current timestamp expression.
	 *
	 * @param string $default Default metadata.
	 * @return bool Whether the default should render unquoted.
	 */
	private function is_mysql_current_timestamp_default_metadata( string $default ): bool {
		return in_array( strtolower( $default ), array( 'current_timestamp', 'current_timestamp()' ), true );
	}

	/**
	 * Group stored index metadata rows by index name.
	 *
	 * @param array[] $indexes Index metadata rows.
	 * @return array[] Grouped index metadata rows.
	 */
	private function group_show_create_table_index_metadata_rows( array $indexes ): array {
		$grouped = array();
		foreach ( $indexes as $index ) {
			$key_name = (string) $index['key_name'];
			if ( ! isset( $grouped[ $key_name ] ) ) {
				$grouped[ $key_name ] = array();
			}

			$grouped[ $key_name ][] = $index;
		}

		return array_values( $grouped );
	}

	/**
	 * Build one MySQL key definition from grouped stored metadata.
	 *
	 * @param array[] $index Grouped index metadata rows.
	 * @return string Key definition SQL.
	 */
	private function get_mysql_create_table_index_definition_from_metadata( array $index ): string {
		$first = $index[0];
		if ( 'PRIMARY' === strtoupper( (string) $first['key_name'] ) ) {
			$sql = sprintf(
				'  PRIMARY KEY (%s)',
				implode( ', ', $this->get_mysql_create_table_index_column_definitions( $index ) )
			);
		} else {
			$sql = sprintf(
				'  %s%sKEY %s (%s)',
				'0' === (string) $first['non_unique'] ? 'UNIQUE ' : '',
				'BTREE' !== strtoupper( (string) $first['index_type'] ) ? strtoupper( (string) $first['index_type'] ) . ' ' : '',
				$this->quote_mysql_identifier( (string) $first['key_name'] ),
				implode( ', ', $this->get_mysql_create_table_index_column_definitions( $index ) )
			);
		}

		if ( '' !== (string) ( $first['index_comment'] ?? '' ) ) {
			$sql .= ' COMMENT ' . $this->quote_mysql_utf8_string_literal( (string) $first['index_comment'] );
		}

		return $sql;
	}

	/**
	 * Build quoted MySQL key part definitions from grouped index metadata rows.
	 *
	 * @param array[] $index Grouped index metadata rows.
	 * @return string[] Key part definitions.
	 */
	private function get_mysql_create_table_index_column_definitions( array $index ): array {
		$columns = array();
		foreach ( $index as $column ) {
			$definition = $this->quote_mysql_identifier( (string) $column['column_name'] );
			if ( null !== $column['sub_part'] ) {
				$definition .= sprintf( '(%d)', (int) $column['sub_part'] );
			}
			if ( 'D' === strtoupper( (string) ( $column['collation'] ?? '' ) ) ) {
				$definition .= ' DESC';
			}

			$columns[] = $definition;
		}

		return $columns;
	}

	/**
	 * Group stored foreign key metadata rows by constraint name.
	 *
	 * @param array[] $foreign_keys Foreign key metadata rows.
	 * @return array[] Grouped foreign key metadata rows.
	 */
	private function group_show_create_table_foreign_key_metadata_rows( array $foreign_keys ): array {
		$grouped = array();
		foreach ( $foreign_keys as $foreign_key ) {
			$constraint_name = (string) $foreign_key['constraint_name'];
			if ( ! isset( $grouped[ $constraint_name ] ) ) {
				$grouped[ $constraint_name ] = array();
			}

			$grouped[ $constraint_name ][] = $foreign_key;
		}

		return array_values( $grouped );
	}

	/**
	 * Build one MySQL foreign key definition from grouped stored metadata.
	 *
	 * @param array[] $foreign_key Grouped foreign key metadata rows.
	 * @return string Foreign key definition SQL.
	 */
	private function get_mysql_create_table_foreign_key_definition_from_metadata( array $foreign_key ): string {
		$first              = $foreign_key[0];
		$columns            = array();
		$referenced_columns = array();

		foreach ( $foreign_key as $column ) {
			$columns[]            = $this->quote_mysql_identifier( (string) $column['column_name'] );
			$referenced_columns[] = $this->quote_mysql_identifier( (string) $column['referenced_column_name'] );
		}

		$sql = sprintf(
			'  CONSTRAINT %s FOREIGN KEY (%s) REFERENCES %s (%s)',
			$this->quote_mysql_identifier( (string) $first['constraint_name'] ),
			implode( ', ', $columns ),
			$this->quote_mysql_identifier( (string) $first['referenced_table_name'] ),
			implode( ', ', $referenced_columns )
		);

		if ( 'NO ACTION' !== strtoupper( (string) $first['delete_rule'] ) ) {
			$sql .= ' ON DELETE ' . strtoupper( (string) $first['delete_rule'] );
		}

		if ( 'NO ACTION' !== strtoupper( (string) $first['update_rule'] ) ) {
			$sql .= ' ON UPDATE ' . strtoupper( (string) $first['update_rule'] );
		}

		return $sql;
	}

	/**
	 * Get a table collation for SHOW CREATE TABLE from column metadata.
	 *
	 * @param array[] $columns Column metadata rows.
	 * @return string MySQL collation.
	 */
	private function get_mysql_create_table_collation_from_metadata( array $columns ): string {
		foreach ( $columns as $column ) {
			if ( ! empty( $column['collation_name'] ) ) {
				return (string) $column['collation_name'];
			}
		}

		return $this->collation;
	}

	/**
	 * Get a MySQL charset name from a collation.
	 *
	 * @param string $collation MySQL collation.
	 * @return string MySQL charset.
	 */
	private function get_mysql_charset_from_collation( string $collation ): string {
		$underscore_position = strpos( $collation, '_' );
		if ( false === $underscore_position ) {
			return $collation;
		}

		return substr( $collation, 0, $underscore_position );
	}

	/**
	 * Quote an identifier for use in a MySQL query.
	 *
	 * @param string $identifier Unquoted identifier value.
	 * @return string Quoted identifier.
	 */
	private function quote_mysql_identifier( string $identifier ): string {
		return '`' . str_replace( '`', '``', $identifier ) . '`';
	}

	/**
	 * Quote a MySQL UTF-8 string literal for SHOW CREATE TABLE output.
	 *
	 * @param string $literal Literal value.
	 * @return string Quoted literal.
	 */
	private function quote_mysql_utf8_string_literal( string $literal ): string {
		$backslash    = chr( 92 );
		$replacements = array(
			"'"        => "''",
			$backslash => $backslash . $backslash,
			chr( 0 )   => $backslash . '0',
			chr( 10 )  => $backslash . 'n',
			chr( 13 )  => $backslash . 'r',
		);

		return "'" . strtr( $literal, $replacements ) . "'";
	}

	/**
	 * Get base table rows used by SHOW TABLE STATUS.
	 *
	 * @return array[] Catalog rows.
	 */
	private function get_show_table_status_catalog_rows(): array {
		$this->ensure_mysql_schema_metadata_tables();

		$sql        = sprintf(
			'SELECT
					t.table_name,
					COALESCE(tm.table_comment, \'\') AS table_comment,
					(
						SELECT c.column_name
						FROM information_schema.columns c
						WHERE c.table_schema = t.table_schema
							AND c.table_name = t.table_name
							AND (
								c.is_identity = \'YES\'
								OR LOWER(COALESCE(c.column_default, \'\')) LIKE \'nextval(%%\'
							)
						ORDER BY c.ordinal_position
						LIMIT 1
					) AS identity_column
				FROM information_schema.tables t
				LEFT JOIN %s tm
					ON tm.table_schema = t.table_schema
					AND tm.table_name = t.table_name
				WHERE t.table_schema = ?
					AND t.table_type = ?
					AND t.table_name NOT IN (?, ?, ?, ?, ?, ?)
					ORDER BY t.table_name',
			$this->connection->quote_identifier( self::MYSQL_TABLE_METADATA_TABLE )
		);
		$params = array(
			'public',
			'BASE TABLE',
			self::MYSQL_COLUMN_METADATA_TABLE,
			self::MYSQL_INDEX_METADATA_TABLE,
			self::MYSQL_FOREIGN_KEY_METADATA_TABLE,
			self::MYSQL_CHECK_METADATA_TABLE,
			self::MYSQL_CHARSET_METADATA_TABLE,
			self::MYSQL_TABLE_METADATA_TABLE,
		);
		$stmt = $this->connection->query( $sql, $params );

		$this->last_postgresql_queries[] = array(
			'sql'    => $sql,
			'params' => $params,
		);

		return $stmt->fetchAll( PDO::FETCH_ASSOC );
	}

	/**
	 * Build a MySQL-shaped SHOW TABLE STATUS row.
	 *
	 * @param string      $table_name     Table name.
	 * @param string|null $auto_increment Next auto-increment value, or null.
	 * @param string      $comment        Table comment.
	 * @return array MySQL-shaped row.
	 */
	private function get_show_table_status_result_row( string $table_name, ?string $auto_increment, string $comment = '' ): array {
		return array(
			'Name'            => $table_name,
			'Engine'          => 'InnoDB',
			'Version'         => '10',
			'Row_format'      => 'Dynamic',
			'Rows'            => '0',
			'Avg_row_length'  => '0',
			'Data_length'     => '0',
			'Max_data_length' => '0',
			'Index_length'    => '0',
			'Data_free'       => '0',
			'Auto_increment'  => $auto_increment,
			'Create_time'     => null,
			'Update_time'     => null,
			'Check_time'      => null,
			'Collation'       => $this->collation,
			'Checksum'        => null,
			'Create_options'  => '',
			'Comment'         => $comment,
		);
	}

	/**
	 * Get the next MySQL-compatible AUTO_INCREMENT value for a table.
	 *
	 * @param string $table_name      Table name.
	 * @param string $identity_column Identity column name.
	 * @return string|null Next AUTO_INCREMENT value, or null when unavailable.
	 */
	private function get_show_table_status_auto_increment_value( string $table_name, string $identity_column ): ?string {
		$driver_name = (string) $this->connection->get_pdo()->getAttribute( PDO::ATTR_DRIVER_NAME );
		if ( 'pgsql' === $driver_name ) {
			return $this->get_postgresql_show_table_status_auto_increment_value( $table_name, $identity_column );
		}

		if ( 'sqlite' === $driver_name ) {
			return $this->get_sqlite_show_table_status_auto_increment_value( $table_name );
		}

		return null;
	}

	/**
	 * Get the next AUTO_INCREMENT value from PostgreSQL identity sequence state.
	 *
	 * @param string $table_name      Table name.
	 * @param string $identity_column Identity column name.
	 * @return string|null Next AUTO_INCREMENT value, or null when unavailable.
	 */
	private function get_postgresql_show_table_status_auto_increment_value( string $table_name, string $identity_column ): ?string {
		$sequence_sql                    = 'SELECT
				seq_ns.nspname AS sequence_schema,
				seq.relname AS sequence_name
			FROM (
				SELECT pg_catalog.pg_get_serial_sequence(format(\'%I.%I\', ?, ?), ?)::regclass AS sequence_oid
			) identity_sequence
			LEFT JOIN pg_catalog.pg_class seq
				ON seq.oid = identity_sequence.sequence_oid
			LEFT JOIN pg_catalog.pg_namespace seq_ns
				ON seq_ns.oid = seq.relnamespace';
		$stmt                            = $this->connection->query(
			$sequence_sql,
			array( 'public', $table_name, $identity_column )
		);
		$this->last_postgresql_queries[] = array(
			'sql'    => $sequence_sql,
			'params' => array( 'public', $table_name, $identity_column ),
		);

		$sequence = $stmt->fetch( PDO::FETCH_ASSOC );
		if (
			false === $sequence
			|| empty( $sequence['sequence_schema'] )
			|| empty( $sequence['sequence_name'] )
		) {
			return '1';
		}

		$sequence_identifier             = $this->get_postgresql_qualified_identifier(
			(string) $sequence['sequence_schema'],
			(string) $sequence['sequence_name']
		);
		$table_identifier                = $this->get_postgresql_qualified_identifier( 'public', $table_name );
		$sql                             = sprintf(
			'WITH sequence_state AS (
				SELECT last_value, is_called FROM %1$s
			),
			table_state AS (
				SELECT MAX(%2$s) AS max_identity_value FROM %3$s
			)
			SELECT GREATEST(
				CASE WHEN sequence_state.is_called THEN sequence_state.last_value + 1 ELSE sequence_state.last_value END,
				COALESCE(table_state.max_identity_value + 1, 1)
			) AS auto_increment
			FROM sequence_state, table_state',
			$sequence_identifier,
			$this->connection->quote_identifier( $identity_column ),
			$table_identifier
		);
		$stmt                            = $this->connection->query( $sql );
		$this->last_postgresql_queries[] = array(
			'sql'    => $sql,
			'params' => array(),
		);

		$value = $stmt->fetchColumn();
		return false === $value ? '1' : (string) $value;
	}

	/**
	 * Get the next AUTO_INCREMENT value from SQLite sequence state in tests.
	 *
	 * @param string $table_name Table name.
	 * @return string Next AUTO_INCREMENT value.
	 */
	private function get_sqlite_show_table_status_auto_increment_value( string $table_name ): string {
		$sequence_table_sql              = "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'sqlite_sequence' LIMIT 1";
		$has_sequence_table              = $this->connection->query( $sequence_table_sql )->fetchColumn();
		$this->last_postgresql_queries[] = array(
			'sql'    => $sequence_table_sql,
			'params' => array(),
		);

		if ( false === $has_sequence_table ) {
			return '1';
		}

		$stmt                            = $this->connection->query(
			'SELECT seq + 1 FROM sqlite_sequence WHERE name = ?',
			array( $table_name )
		);
		$this->last_postgresql_queries[] = array(
			'sql'    => 'SELECT seq + 1 FROM sqlite_sequence WHERE name = ?',
			'params' => array( $table_name ),
		);

		$value = $stmt->fetchColumn();
		return false === $value ? '1' : (string) $value;
	}

	/**
	 * Filter SHOW TABLE STATUS rows with a parsed filter.
	 *
	 * @param array[] $rows                    SHOW TABLE STATUS rows.
	 * @param array   $show_table_status_query Parsed SHOW TABLE STATUS options.
	 * @return array[] Filtered rows.
	 */
	private function filter_show_table_status_rows( array $rows, array $show_table_status_query ): array {
		if ( 'all' === $show_table_status_query['filter_type'] ) {
			return $rows;
		}

		if ( 'where' === $show_table_status_query['filter_type'] ) {
			return $this->filter_mysql_static_show_rows(
				$rows,
				array(
					'type'       => 'where',
					'conditions' => $show_table_status_query['conditions'] ?? array(),
				)
			);
		}

		if ( 'where_expression' === $show_table_status_query['filter_type'] ) {
			return $this->filter_mysql_static_show_rows(
				$rows,
				array(
					'type'      => 'where_expression',
					'predicate' => $show_table_status_query['predicate'] ?? null,
				)
			);
		}

		return array_values(
			array_filter(
				$rows,
				function ( array $row ) use ( $show_table_status_query ): bool {
					if ( 'like' === $show_table_status_query['filter_type'] ) {
						$column = $show_table_status_query['filter_column'] ?? 'Name';
						return null !== $show_table_status_query['filter_pattern']
							&& array_key_exists( $column, $row )
							&& null !== $row[ $column ]
							&& $this->matches_mysql_like_pattern( (string) $row[ $column ], $show_table_status_query['filter_pattern'] );
					}

					if ( 'exact' === $show_table_status_query['filter_type'] ) {
						$column  = $show_table_status_query['filter_column'];
						$pattern = $show_table_status_query['filter_pattern'];
						return null !== $column
						&& null !== $pattern
						&& array_key_exists( $column, $row )
						&& null !== $row[ $column ]
						&& 0 === strcasecmp( (string) $row[ $column ], $pattern );
					}

					if ( 'auto_increment_gt' === $show_table_status_query['filter_type'] ) {
						return null !== $row['Auto_increment']
						&& null !== $show_table_status_query['filter_threshold']
						&& $this->is_unsigned_integer_string_greater_than(
							(string) $row['Auto_increment'],
							$show_table_status_query['filter_threshold']
						);
					}

					return 'auto_increment_is_null' === $show_table_status_query['filter_type']
					&& null === $row['Auto_increment'];
				}
			)
		);
	}

	/**
	 * Compare two unsigned integer strings without losing precision.
	 *
	 * @param string $left  Left integer.
	 * @param string $right Right integer.
	 * @return bool Whether left is greater than right.
	 */
	private function is_unsigned_integer_string_greater_than( string $left, string $right ): bool {
		$left  = ltrim( $left, '0' );
		$right = ltrim( $right, '0' );
		$left  = '' === $left ? '0' : $left;
		$right = '' === $right ? '0' : $right;

		if ( strlen( $left ) !== strlen( $right ) ) {
			return strlen( $left ) > strlen( $right );
		}

		return strcmp( $left, $right ) > 0;
	}

	/**
	 * Execute a simple MySQL variable SELECT query from emulated variable state.
	 *
	 * @param array $mysql_variable_select_query Parsed variable SELECT query.
	 * @param int   $fetch_mode                  PDO fetch mode.
	 * @param array ...$fetch_mode_args          Additional fetch mode arguments.
	 * @return mixed Variable SELECT result rows.
	 */
	private function execute_mysql_variable_select_query( array $mysql_variable_select_query, $fetch_mode, ...$fetch_mode_args ) {
		return $this->set_mysql_static_show_result(
			$mysql_variable_select_query['columns'],
			array( $mysql_variable_select_query['row'] ),
			$fetch_mode,
			...$fetch_mode_args
		);
	}

	/**
	 * Execute a MySQL SHOW VARIABLES statement from emulated session state.
	 *
	 * @param array  $show_variables_query SHOW VARIABLES options.
	 * @param int    $fetch_mode         PDO fetch mode.
	 * @param array  ...$fetch_mode_args Additional fetch mode arguments.
	 * @return mixed SHOW VARIABLES result rows.
	 */
	private function execute_show_variables_query( array $show_variables_query, $fetch_mode, ...$fetch_mode_args ) {
		$variables = $this->get_mysql_session_variables();
		$rows      = array();

		foreach ( $variables as $variable_name => $value ) {
			$rows[] = array(
				'Variable_name' => $variable_name,
				'Value'         => $value,
			);
		}

		$rows = $this->filter_mysql_static_show_rows( $rows, $show_variables_query );

		$this->last_column_meta = array(
			array(
				'name'             => 'Variable_name',
				'table'            => '',
				'mysqli:orgtable'  => '',
				'mysqli:orgname'   => 'Variable_name',
				'mysqli:db'        => $this->db_name,
				'mysqli:charsetnr' => 45,
				'mysqli:flags'     => 0,
				'mysqli:type'      => 253,
				'len'              => 64,
				'precision'        => 0,
				'native_type'      => 'string',
			),
			array(
				'name'             => 'Value',
				'table'            => '',
				'mysqli:orgtable'  => '',
				'mysqli:orgname'   => 'Value',
				'mysqli:db'        => $this->db_name,
				'mysqli:charsetnr' => 45,
				'mysqli:flags'     => 0,
				'mysqli:type'      => 253,
				'len'              => 1024,
				'precision'        => 0,
				'native_type'      => 'string',
			),
		);

		if ( PDO::FETCH_ASSOC === $fetch_mode ) {
			$this->last_result = $rows;
			return $this->last_result;
		}

		if ( PDO::FETCH_NUM === $fetch_mode ) {
			$this->last_result = array_map( 'array_values', $rows );
			return $this->last_result;
		}

		$this->last_result = array_map(
			static function ( array $row ) {
				return (object) $row;
			},
			$rows
		);

		return $this->last_result;
	}

