	/**
	 * Execute a MySQL SHOW STATUS statement from bounded static status rows.
	 *
	 * @param array $show_status_query SHOW STATUS options.
	 * @param int   $fetch_mode        PDO fetch mode.
	 * @param array ...$fetch_mode_args Additional fetch mode arguments.
	 * @return mixed SHOW STATUS result rows.
	 */
	private function execute_show_status_query( array $show_status_query, $fetch_mode, ...$fetch_mode_args ) {
		$rows = array();
		foreach ( $this->get_mysql_status_variables() as $variable_name => $value ) {
			$rows[] = array(
				'Variable_name' => $variable_name,
				'Value'         => $value,
			);
		}

		$rows = $this->filter_mysql_static_show_rows( $rows, $show_status_query );

		$this->last_found_rows = count( $rows );
		return $this->set_mysql_static_show_result(
			array( 'Variable_name', 'Value' ),
			$rows,
			$fetch_mode,
			...$fetch_mode_args
		);
	}

	/**
	 * Execute a MySQL SHOW WARNINGS/ERRORS statement.
	 *
	 * PostgreSQL errors are not accumulated in a MySQL diagnostics area. Returning
	 * an empty diagnostics set keeps admin/WP-CLI callers from issuing unsupported
	 * backend SHOW statements while preserving the MySQL result shape.
	 *
	 * @param array $show_diagnostics_query SHOW WARNINGS/ERRORS options.
	 * @param int   $fetch_mode             PDO fetch mode.
	 * @param array ...$fetch_mode_args     Additional fetch mode arguments.
	 * @return mixed SHOW diagnostics result rows.
	 */
	private function execute_show_diagnostics_query( array $show_diagnostics_query, $fetch_mode, ...$fetch_mode_args ) {
		if ( 'count' === $show_diagnostics_query['type'] ) {
			$this->last_found_rows = 1;
			return $this->set_mysql_static_show_result(
				array( $show_diagnostics_query['count_column'] ),
				array(
					array(
						$show_diagnostics_query['count_column'] => '0',
					),
				),
				$fetch_mode,
				...$fetch_mode_args
			);
		}

		$this->last_found_rows = 0;
		return $this->set_mysql_static_show_result(
			array( 'Level', 'Code', 'Message' ),
			array(),
			$fetch_mode,
			...$fetch_mode_args
		);
	}

	/**
	 * Execute a MySQL SHOW PROCESSLIST statement from the current emulated session.
	 *
	 * @param array $show_processlist_query SHOW PROCESSLIST options.
	 * @param int   $fetch_mode             PDO fetch mode.
	 * @param array ...$fetch_mode_args     Additional fetch mode arguments.
	 * @return mixed SHOW PROCESSLIST result rows.
	 */
	private function execute_show_processlist_query( array $show_processlist_query, $fetch_mode, ...$fetch_mode_args ) {
		$info = (string) $this->last_mysql_query;
		if ( ! $show_processlist_query['full'] && strlen( $info ) > 100 ) {
			$info = substr( $info, 0, 100 );
		}

		$this->last_found_rows = 1;
		return $this->set_mysql_static_show_result(
			array( 'Id', 'User', 'Host', 'db', 'Command', 'Time', 'State', 'Info' ),
			array(
				array(
					'Id'      => '1',
					'User'    => 'root',
					'Host'    => 'localhost',
					'db'      => $this->db_name,
					'Command' => 'Query',
					'Time'    => '0',
					'State'   => '',
					'Info'    => $info,
				),
			),
			$fetch_mode,
			...$fetch_mode_args
		);
	}

	/**
	 * Filter static SHOW rows with a parsed MySQL LIKE or WHERE filter.
	 *
	 * @param array[] $rows        Rows keyed by output column names.
	 * @param array   $show_filter Parsed SHOW filter.
	 * @return array[] Filtered rows.
	 */
	private function filter_mysql_static_show_rows( array $rows, array $show_filter ): array {
		if ( 'all' === $show_filter['type'] ) {
			return $rows;
		}

		if ( 'where' === $show_filter['type'] ) {
			$conditions = $show_filter['conditions'] ?? array();
			return array_values(
				array_filter(
					$rows,
					function ( array $row ) use ( $conditions ): bool {
						foreach ( $conditions as $condition ) {
							$column = $condition['column'] ?? null;
							$value  = $condition['value'] ?? null;
							if ( null === $column || null === $value || ! array_key_exists( $column, $row ) ) {
								return false;
							}

							if ( 'like' === ( $condition['operator'] ?? null ) ) {
								if ( ! $this->matches_mysql_like_pattern( (string) $row[ $column ], (string) $value ) ) {
									return false;
								}
								continue;
							}

							if ( 0 !== strcasecmp( (string) $row[ $column ], (string) $value ) ) {
								return false;
							}
						}

						return true;
					}
				)
			);
		}

		if ( 'where_expression' === $show_filter['type'] ) {
			$predicate = $show_filter['predicate'] ?? null;
			if ( ! is_array( $predicate ) ) {
				return array();
			}

			return array_values(
				array_filter(
					$rows,
					function ( array $row ) use ( $predicate ): bool {
						return $this->evaluate_mysql_show_where_predicate( $predicate, $row );
					}
				)
			);
		}

		$column  = $show_filter['column'];
		$pattern = $show_filter['pattern'];

		return array_values(
			array_filter(
				$rows,
				function ( array $row ) use ( $show_filter, $column, $pattern ): bool {
					if ( null === $column || null === $pattern || ! array_key_exists( $column, $row ) ) {
						return false;
					}

					if ( 'like' === $show_filter['type'] ) {
						return $this->matches_mysql_like_pattern( (string) $row[ $column ], $pattern );
					}

					return 0 === strcasecmp( (string) $row[ $column ], $pattern );
				}
			)
		);
	}

	/**
	 * Evaluate a SHOW WHERE predicate against one materialized SHOW row.
	 *
	 * @param array $predicate Predicate AST.
	 * @param array $row       SHOW output row keyed by column names.
	 * @return bool Whether the row matches.
	 */
	private function evaluate_mysql_show_where_predicate( array $predicate, array $row ): bool {
		switch ( $predicate['type'] ?? null ) {
			case 'and':
				return $this->evaluate_mysql_show_where_predicate( $predicate['left'], $row )
					&& $this->evaluate_mysql_show_where_predicate( $predicate['right'], $row );

			case 'or':
				return $this->evaluate_mysql_show_where_predicate( $predicate['left'], $row )
					|| $this->evaluate_mysql_show_where_predicate( $predicate['right'], $row );

			case 'not':
				return ! $this->evaluate_mysql_show_where_predicate( $predicate['expr'], $row );

			case 'truthy':
				return $this->is_mysql_show_where_truthy(
					$this->evaluate_mysql_show_where_value( $predicate['expr'], $row )
				);

			case 'is_null':
				$is_null = null === $this->evaluate_mysql_show_where_value( $predicate['expr'], $row );
				return ! empty( $predicate['not'] ) ? ! $is_null : $is_null;

			case 'comparison':
				$operator = $predicate['operator'] ?? null;
				$left     = $this->evaluate_mysql_show_where_value( $predicate['left'], $row );
				$right    = $this->evaluate_mysql_show_where_value( $predicate['right'], $row );
				return $this->evaluate_mysql_show_where_comparison( $left, $operator, $right );

			case 'in':
				$left = $this->evaluate_mysql_show_where_value( $predicate['expr'], $row );
				if ( null === $left ) {
					return false;
				}

				$has_null = false;
				foreach ( $predicate['values'] ?? array() as $value_expression ) {
					$value = $this->evaluate_mysql_show_where_value( $value_expression, $row );
					if ( null === $value ) {
						$has_null = true;
						continue;
					}

					if ( $this->evaluate_mysql_show_where_comparison( $left, '=', $value ) ) {
						return empty( $predicate['not'] );
					}
				}

				return ! empty( $predicate['not'] ) && ! $has_null;

			case 'between':
				$value = $this->evaluate_mysql_show_where_value( $predicate['expr'], $row );
				$lower = $this->evaluate_mysql_show_where_value( $predicate['lower'], $row );
				$upper = $this->evaluate_mysql_show_where_value( $predicate['upper'], $row );
				if ( null === $value || null === $lower || null === $upper ) {
					return false;
				}

				$matches = $this->compare_mysql_show_where_values( $value, $lower ) >= 0
					&& $this->compare_mysql_show_where_values( $value, $upper ) <= 0;
				return ! empty( $predicate['not'] ) ? ! $matches : $matches;
		}

		return false;
	}

	/**
	 * Evaluate one SHOW WHERE scalar value expression.
	 *
	 * @param array $expression Value expression AST.
	 * @param array $row        SHOW output row keyed by column names.
	 * @return scalar|null Evaluated value.
	 */
	private function evaluate_mysql_show_where_value( array $expression, array $row ) {
		switch ( $expression['type'] ?? null ) {
			case 'column':
				$column = $expression['column'] ?? null;
				return is_string( $column ) && array_key_exists( $column, $row ) ? $row[ $column ] : null;

			case 'literal':
			case 'number':
				return $expression['value'] ?? null;

			case 'null':
				return null;

			case 'function':
				return $this->evaluate_mysql_show_where_function_value( $expression, $row );

			case 'arithmetic':
				$left  = $this->evaluate_mysql_show_where_value( $expression['left'], $row );
				$right = $this->evaluate_mysql_show_where_value( $expression['right'], $row );
				return $this->evaluate_mysql_show_where_arithmetic_value(
					$left,
					$expression['operator'] ?? null,
					$right
				);
		}

		return null;
	}

	/**
	 * Evaluate one SHOW WHERE arithmetic expression.
	 *
	 * @param scalar|null $left     Left value.
	 * @param string|null $operator Arithmetic operator.
	 * @param scalar|null $right    Right value.
	 * @return float|null Evaluated numeric value, or null when not numeric.
	 */
	private function evaluate_mysql_show_where_arithmetic_value( $left, ?string $operator, $right ): ?float {
		$left_number  = $this->coerce_mysql_show_where_numeric_value( $left );
		$right_number = $this->coerce_mysql_show_where_numeric_value( $right );
		if ( null === $left_number || null === $right_number ) {
			return null;
		}

		if ( '+' === $operator ) {
			return $left_number + $right_number;
		}

		if ( '-' === $operator ) {
			return $left_number - $right_number;
		}

		if ( '*' === $operator ) {
			return $left_number * $right_number;
		}

		if ( '/' === $operator ) {
			return 0.0 === $right_number ? null : $left_number / $right_number;
		}

		if ( '%' === $operator ) {
			return 0.0 === $right_number ? null : fmod( $left_number, $right_number );
		}

		return null;
	}

	/**
	 * Coerce one SHOW WHERE value to a numeric operand.
	 *
	 * @param scalar|null $value Value to coerce.
	 * @return float|null Numeric value, or null when not numeric.
	 */
	private function coerce_mysql_show_where_numeric_value( $value ): ?float {
		if ( null === $value ) {
			return null;
		}

		if ( is_bool( $value ) ) {
			return $value ? 1.0 : 0.0;
		}

		if ( is_int( $value ) || is_float( $value ) ) {
			return (float) $value;
		}

		if ( is_string( $value ) && is_numeric( $value ) ) {
			return (float) $value;
		}

		return null;
	}

	/**
	 * Evaluate one supported SHOW WHERE scalar function.
	 *
	 * @param array $expression Function value expression AST.
	 * @param array $row        SHOW output row keyed by column names.
	 * @return scalar|null Evaluated value.
	 */
	private function evaluate_mysql_show_where_function_value( array $expression, array $row ) {
		$function  = $expression['function'] ?? null;
		$arguments = array();
		foreach ( $expression['arguments'] ?? array() as $argument ) {
			$arguments[] = $this->evaluate_mysql_show_where_value( $argument, $row );
		}

		if ( in_array( null, $arguments, true ) ) {
			return null;
		}

		switch ( $function ) {
			case 'lower':
				return strtolower( (string) $arguments[0] );

			case 'upper':
				return strtoupper( (string) $arguments[0] );

			case 'left':
				$length = (int) $arguments[1];
				return $length <= 0 ? '' : substr( (string) $arguments[0], 0, $length );

			case 'right':
				$length = (int) $arguments[1];
				return $length <= 0 ? '' : substr( (string) $arguments[0], -$length );

			case 'substring':
				$value  = (string) $arguments[0];
				$start  = (int) $arguments[1];
				$length = $arguments[2] ?? null;
				if ( 0 === $start ) {
					return '';
				}

				$offset = $start > 0 ? $start - 1 : strlen( $value ) + $start;
				if ( null === $length ) {
					return substr( $value, $offset );
				}

				$length = (int) $length;
				return $length <= 0 ? '' : substr( $value, $offset, $length );

			case 'length':
			case 'char_length':
				return strlen( (string) $arguments[0] );

			case 'mod':
				return $this->evaluate_mysql_show_where_arithmetic_value( $arguments[0], '%', $arguments[1] );
		}

		return null;
	}

	/**
	 * Evaluate a SHOW WHERE comparison.
	 *
	 * @param scalar|null $left     Left value.
	 * @param string|null $operator Comparison operator.
	 * @param scalar|null $right    Right value.
	 * @return bool Whether the comparison matches.
	 */
	private function evaluate_mysql_show_where_comparison( $left, ?string $operator, $right ): bool {
		if ( '<=>' === $operator ) {
			if ( null === $left || null === $right ) {
				return null === $left && null === $right;
			}

			return 0 === $this->compare_mysql_show_where_values( $left, $right );
		}

		if ( null === $left || null === $right ) {
			return false;
		}

		if ( 'like' === $operator || 'not_like' === $operator ) {
			$matches = $this->matches_mysql_like_pattern( (string) $left, (string) $right );
			return 'not_like' === $operator ? ! $matches : $matches;
		}

		$comparison = $this->compare_mysql_show_where_values( $left, $right );
		switch ( $operator ) {
			case '=':
				return 0 === $comparison;
			case '<>':
				return 0 !== $comparison;
			case '>':
				return $comparison > 0;
			case '>=':
				return $comparison >= 0;
			case '<':
				return $comparison < 0;
			case '<=':
				return $comparison <= 0;
		}

		return false;
	}

	/**
	 * Evaluate one scalar SHOW WHERE value using MySQL boolean coercion.
	 *
	 * @param scalar|null $value Value to coerce.
	 * @return bool Whether the value is true in a WHERE predicate.
	 */
	private function is_mysql_show_where_truthy( $value ): bool {
		if ( null === $value ) {
			return false;
		}

		if ( is_bool( $value ) ) {
			return $value;
		}

		if ( is_int( $value ) || is_float( $value ) || is_string( $value ) ) {
			return 0.0 !== (float) $value;
		}

		return false;
	}

	/**
	 * Compare two non-null SHOW WHERE scalar values using MySQL-ish coercion.
	 *
	 * @param scalar $left  Left value.
	 * @param scalar $right Right value.
	 * @return int Negative, zero, or positive comparison result.
	 */
	private function compare_mysql_show_where_values( $left, $right ): int {
		if ( is_numeric( $left ) && is_numeric( $right ) ) {
			$left_number  = (float) $left;
			$right_number = (float) $right;
			if ( $left_number === $right_number ) {
				return 0;
			}

			return $left_number < $right_number ? -1 : 1;
		}

		return strcasecmp( (string) $left, (string) $right );
	}

	/**
	 * Store static SHOW result rows using common MySQL-shaped metadata.
	 *
	 * @param string[] $columns         Result column names.
	 * @param array[]  $rows            Rows keyed by column names.
	 * @param int      $fetch_mode      PDO fetch mode.
	 * @param array    ...$fetch_mode_args Additional fetch mode arguments.
	 * @return mixed Result rows formatted for the requested fetch mode.
	 */
	private function set_mysql_static_show_result( array $columns, array $rows, $fetch_mode, ...$fetch_mode_args ) {
		$this->last_column_meta = array();
		foreach ( $columns as $column ) {
			$this->last_column_meta[] = array(
				'name'             => $column,
				'table'            => '',
				'mysqli:orgtable'  => '',
				'mysqli:orgname'   => $column,
				'mysqli:db'        => $this->db_name,
				'mysqli:charsetnr' => 45,
				'mysqli:flags'     => 0,
				'mysqli:type'      => 253,
				'len'              => 1024,
				'precision'        => 0,
				'native_type'      => 'string',
			);
		}
		$this->last_column_count = count( $this->last_column_meta );

		if ( PDO::FETCH_ASSOC === $fetch_mode ) {
			$this->last_result = $rows;
			return $this->last_result;
		}

		if ( PDO::FETCH_NUM === $fetch_mode ) {
			$this->last_result = array_map( 'array_values', $rows );
			return $this->last_result;
		}

		$this->last_result = array_map(
			static function ( array $row ) {
				return (object) $row;
			},
			$rows
		);

		return $this->last_result;
	}

	/**
	 * Store already-fetched associative SHOW rows using the requested fetch mode.
	 *
	 * @param array[] $rows            Rows keyed by result column names.
	 * @param int     $fetch_mode      PDO fetch mode.
	 * @param array   ...$fetch_mode_args Additional fetch mode arguments.
	 * @return mixed Result rows formatted for the requested fetch mode.
	 */
	private function set_mysql_associative_result_rows( array $rows, $fetch_mode, ...$fetch_mode_args ) {
		if ( PDO::FETCH_ASSOC === $fetch_mode ) {
			$this->last_result = $rows;
			return $this->last_result;
		}

		if ( PDO::FETCH_NUM === $fetch_mode ) {
			$this->last_result = array_map( 'array_values', $rows );
			return $this->last_result;
		}

		$this->last_result = array_map(
			static function ( array $row ) {
				return (object) $row;
			},
			$rows
		);

		return $this->last_result;
	}

	/**
	 * Match a string against a MySQL LIKE pattern.
	 *
	 * @param string $value   Value to check.
	 * @param string $pattern MySQL LIKE pattern.
	 * @return bool Whether the pattern matches.
	 */
	private function matches_mysql_like_pattern( string $value, string $pattern ): bool {
		$regex  = '/^';
		$length = strlen( $pattern );

		for ( $i = 0; $i < $length; $i++ ) {
			$char = $pattern[ $i ];
			if ( '\\' === $char && $i + 1 < $length ) {
				++$i;
				$regex .= preg_quote( $pattern[ $i ], '/' );
				continue;
			}

			if ( '%' === $char ) {
				$regex .= '.*';
				continue;
			}

			if ( '_' === $char ) {
				$regex .= '.';
				continue;
			}

			$regex .= preg_quote( $char, '/' );
		}

		$regex .= '$/i';
		return 1 === preg_match( $regex, $value );
	}

	/**
	 * Get MySQL-compatible session variables exposed by SHOW VARIABLES.
	 *
	 * @return array<string, string> Session variables keyed by lowercase name.
	 */
	private function get_mysql_session_variables(): array {
		return array_replace(
			$this->get_default_mysql_system_variable_values(),
			array(
				'character_set_client'     => $this->charset,
				'character_set_connection' => $this->charset,
				'character_set_results'    => $this->charset,
				'character_set_database'   => $this->charset,
				'character_set_server'     => $this->charset,
				'collation_connection'     => $this->collation,
				'collation_database'       => $this->collation,
				'collation_server'         => $this->collation,
				'sql_mode'                 => $this->get_sql_mode(),
			),
			$this->mysql_session_variable_values
		);
	}

	/**
	 * Get bounded MySQL-compatible status variables.
	 *
	 * These rows are intentionally conservative. They cover common admin and
	 * WP-CLI probes without pretending to expose live server counters.
	 *
	 * @return array<string, string> Status variables keyed by MySQL display name.
	 */
	private function get_mysql_status_variables(): array {
		return array(
			'Aborted_clients'         => '0',
			'Aborted_connects'        => '0',
			'Bytes_received'          => '0',
			'Bytes_sent'              => '0',
			'Connections'             => '1',
			'Created_tmp_disk_tables' => '0',
			'Created_tmp_files'       => '0',
			'Created_tmp_tables'      => '0',
			'Handler_read_first'      => '0',
			'Handler_read_key'        => '0',
			'Handler_read_next'       => '0',
			'Handler_read_prev'       => '0',
			'Handler_read_rnd'        => '0',
			'Handler_read_rnd_next'   => '0',
			'Handler_write'           => '0',
			'Open_tables'             => '0',
			'Opened_tables'           => '0',
			'Questions'               => '0',
			'Slow_queries'            => '0',
			'Threads_cached'          => '0',
			'Threads_connected'       => '1',
			'Threads_created'         => '1',
			'Threads_running'         => '1',
			'Uptime'                  => '0',
		);
	}

	/**
	 * Synchronize SET NAMES/CHARSET state with individual session variables.
	 */
	private function sync_mysql_charset_session_variables(): void {
		foreach (
			array(
				'character_set_client',
				'character_set_connection',
				'character_set_results',
				'character_set_database',
				'character_set_server',
			) as $variable
		) {
			$this->mysql_session_variable_values[ $variable ] = $this->charset;
		}

		foreach (
			array(
				'collation_connection',
				'collation_database',
				'collation_server',
			) as $variable
		) {
			$this->mysql_session_variable_values[ $variable ] = $this->collation;
		}
	}

	/**
	 * Set an emulated MySQL session variable.
	 *
	 * @param string $name  Lowercase variable name.
	 * @param string $value Variable value.
	 */
	private function set_mysql_session_variable_value( string $name, string $value ): void {
		if ( 'sql_mode' === $name ) {
			$this->set_sql_mode( $value );
			return;
		}

		$this->mysql_session_variable_values[ $name ] = $value;
	}

	/**
	 * Get an emulated MySQL system variable value.
	 *
	 * @param string $name Variable name.
	 * @return string|null Variable value, or null when unsupported.
	 */
	private function get_mysql_system_variable_value( string $name ): ?string {
		$name      = strtolower( $name );
		$variables = $this->get_mysql_session_variables();
		if ( array_key_exists( $name, $variables ) ) {
			return $variables[ $name ];
		}

		if ( 'sql_mode' === $name ) {
			return $this->get_sql_mode();
		}

		$read_only_variables = $this->get_read_only_mysql_system_variable_values();
		if ( array_key_exists( $name, $read_only_variables ) ) {
			return $read_only_variables[ $name ];
		}

		$defaults = $this->get_default_mysql_system_variable_values();
		return array_key_exists( $name, $defaults ) ? $defaults[ $name ] : null;
	}

	/**
	 * Get a stored MySQL user variable value.
	 *
	 * @param string $name Normalized user variable name.
	 * @return string|null User variable value, or null when unset.
	 */
	private function get_mysql_user_variable_value( string $name ): ?string {
		return array_key_exists( $name, $this->mysql_user_variables ) ? $this->mysql_user_variables[ $name ] : null;
	}

	/**
	 * Parse a MySQL @@system_variable reference.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current token position, updated on success.
	 * @param string|null      $display  Optional display name, populated when requested.
	 * @return string|null Lowercase system variable name, or null when unsupported.
	 */
	private function parse_mysql_system_variable_reference( array $tokens, int &$position, ?string &$display = null ): ?string {
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::AT_AT_SIGN_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		$display_parts = array( '@@' );
		++$position;

		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			&& in_array(
				$tokens[ $position ]->id,
				array(
					WP_MySQL_Lexer::GLOBAL_SYMBOL,
					WP_MySQL_Lexer::LOCAL_SYMBOL,
					WP_MySQL_Lexer::SESSION_SYMBOL,
				),
				true
			)
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position + 1 ]->id
		) {
			$display_parts[] = $tokens[ $position ]->get_value();
			$display_parts[] = '.';
			$position       += 2;
		}

		if ( ! isset( $tokens[ $position ] ) || ! $this->is_mysql_system_variable_name_token( $tokens[ $position ] ) ) {
			return null;
		}

		$display_parts[] = $tokens[ $position ]->get_value();
		$name            = strtolower( $tokens[ $position++ ]->get_value() );
		$display         = implode( '', $display_parts );
		return $name;
	}

	/**
	 * Check whether a token can be a system variable name.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token can name a supported variable.
	 */
	private function is_mysql_system_variable_name_token( WP_MySQL_Token $token ): bool {
		if (
			in_array(
				$token->id,
				array(
					WP_MySQL_Lexer::AT_AT_SIGN_SYMBOL,
					WP_MySQL_Lexer::AT_SIGN_SYMBOL,
					WP_MySQL_Lexer::AT_TEXT_SUFFIX,
					WP_MySQL_Lexer::CLOSE_PAR_SYMBOL,
					WP_MySQL_Lexer::COMMA_SYMBOL,
					WP_MySQL_Lexer::DOT_SYMBOL,
					WP_MySQL_Lexer::EOF,
					WP_MySQL_Lexer::EQUAL_OPERATOR,
					WP_MySQL_Lexer::OPEN_PAR_SYMBOL,
					WP_MySQL_Lexer::SEMICOLON_SYMBOL,
				),
				true
			)
		) {
			return false;
		}

		return '' !== $token->get_value();
	}

	/**
	 * Normalize a MySQL user variable name for storage.
	 *
	 * @param string $name User variable token value.
	 * @return string Normalized user variable name.
	 */
	private function normalize_mysql_user_variable_name( string $name ): string {
		return strtolower( ltrim( $name, '@' ) );
	}

	/**
	 * Normalize a SET value for a supported system variable.
	 *
	 * @param string $name  Lowercase variable name.
	 * @param string $value Raw assignment value.
	 * @return string|null Normalized value, or null when unsupported.
	 */
	private function normalize_mysql_system_variable_assignment_value( string $name, string $value ): ?string {
		if ( $this->is_mysql_boolean_system_variable( $name ) ) {
			return $this->normalize_mysql_boolean_system_variable_value( $value );
		}

		if ( $this->is_mysql_charset_session_variable( $name ) || $this->is_mysql_collation_session_variable( $name ) ) {
			return strtolower( trim( $value, "'\"` \t\n\r\0\x0B" ) );
		}

		return $value;
	}

	/**
	 * Normalize a MySQL boolean system variable value.
	 *
	 * @param string $value Raw assignment value.
	 * @return string|null Normalized 1/0 value, or null when unsupported.
	 */
	private function normalize_mysql_boolean_system_variable_value( string $value ): ?string {
		$value = strtolower( trim( $value, "'\"` \t\n\r\0\x0B" ) );
		if ( in_array( $value, array( '1', 'on', 'true' ), true ) ) {
			return '1';
		}

		if ( in_array( $value, array( '0', 'off', 'false' ), true ) ) {
			return '0';
		}

		return null;
	}

	/**
	 * Check whether a MySQL system variable is supported by the emulation layer.
	 *
	 * @param string $name Lowercase variable name.
	 * @return bool Whether the variable is supported.
	 */
	private function is_supported_mysql_system_variable( string $name ): bool {
		$name = strtolower( $name );
		if (
			$this->is_mysql_charset_session_variable( $name )
			|| $this->is_mysql_collation_session_variable( $name )
			|| 'sql_mode' === $name
		) {
			return true;
		}

		$defaults = $this->get_default_mysql_system_variable_values();
		return array_key_exists( $name, $defaults );
	}

	/**
	 * Check whether a variable stores a charset name.
	 *
	 * @param string $name Lowercase variable name.
	 * @return bool Whether this is a charset variable.
	 */
	private function is_mysql_charset_session_variable( string $name ): bool {
		return in_array(
			$name,
			array(
				'character_set_client',
				'character_set_connection',
				'character_set_results',
				'character_set_database',
				'character_set_server',
			),
			true
		);
	}

	/**
	 * Check whether a variable stores a collation name.
	 *
	 * @param string $name Lowercase variable name.
	 * @return bool Whether this is a collation variable.
	 */
	private function is_mysql_collation_session_variable( string $name ): bool {
		return in_array(
			$name,
			array(
				'collation_connection',
				'collation_database',
				'collation_server',
			),
			true
		);
	}

	/**
	 * Check whether a variable accepts MySQL boolean values.
	 *
	 * @param string $name Lowercase variable name.
	 * @return bool Whether this is a boolean variable.
	 */
	private function is_mysql_boolean_system_variable( string $name ): bool {
		return in_array(
			$name,
			array(
				'autocommit',
				'big_tables',
				'end_markers_in_json',
				'explicit_defaults_for_timestamp',
				'foreign_key_checks',
				'keep_files_on_create',
				'old_alter_table',
				'print_identified_with_as_hex',
				'require_row_format',
				'select_into_disk_sync',
				'session_track_schema',
				'session_track_state_change',
				'show_create_table_skip_secondary_engine',
				'show_create_table_verbosity',
				'sql_auto_is_null',
				'sql_big_selects',
				'sql_buffer_result',
				'sql_notes',
				'sql_safe_updates',
				'sql_warnings',
				'transaction_read_only',
				'unique_checks',
			),
			true
		);
	}

	/**
	 * Get defaults for supported MySQL system variables.
	 *
	 * @return array<string, string> Default values keyed by lowercase name.
	 */
	private function get_default_mysql_system_variable_values(): array {
		return array(
			'autocommit'                              => '1',
			'big_tables'                              => '0',
			'default_collation_for_utf8mb4'           => 'utf8mb4_0900_ai_ci',
			'default_storage_engine'                  => 'InnoDB',
			'end_markers_in_json'                     => '0',
			'explicit_defaults_for_timestamp'         => '1',
			'foreign_key_checks'                      => '1',
			'keep_files_on_create'                    => '0',
			'max_allowed_packet'                      => '67108864',
			'old_alter_table'                         => '0',
			'print_identified_with_as_hex'            => '0',
			'require_row_format'                      => '0',
			'resultset_metadata'                      => 'FULL',
			'select_into_disk_sync'                   => '0',
			'session_track_gtids'                     => 'OFF',
			'session_track_schema'                    => '1',
			'session_track_state_change'              => '0',
			'session_track_transaction_info'          => 'OFF',
			'show_create_table_skip_secondary_engine' => '0',
			'show_create_table_verbosity'             => '0',
			'sql_auto_is_null'                        => '0',
			'sql_big_selects'                         => '1',
			'sql_buffer_result'                       => '0',
			'sql_notes'                               => '1',
			'sql_safe_updates'                        => '0',
			'sql_warnings'                            => '0',
			'storage_engine'                          => 'InnoDB',
			'time_zone'                               => 'SYSTEM',
			'transaction_isolation'                   => 'REPEATABLE-READ',
			'transaction_read_only'                   => '0',
			'unique_checks'                           => '1',
			'use_secondary_engine'                    => 'ON',
		);
	}

	/**
	 * Get read-only MySQL system variable values.
	 *
	 * @return array<string, string> Read-only values keyed by lowercase name.
	 */
	private function get_read_only_mysql_system_variable_values(): array {
		return array(
			'version'         => $this->get_mysql_version_string(),
			'version_comment' => 'MySQL Community Server - GPL',
		);
	}

	/**
	 * Get the emulated MySQL server version string.
	 *
	 * @return string MySQL-compatible version string.
	 */
	private function get_mysql_version_string(): string {
		$version = (string) $this->mysql_version;
		return sprintf(
			'%d.%d.%d',
			$version[0],
			substr( $version, 1, 2 ),
			substr( $version, 3, 2 )
		);
	}

	/**
	 * Normalize a MySQL charset name.
	 *
	 * @param string $charset Charset name.
	 * @return string Normalized charset.
	 */
	private function normalize_mysql_charset_name( string $charset ): string {
		$charset = strtolower( trim( $charset, "'\"` \t\n\r\0\x0B" ) );
		return 'utf8mb3' === $charset ? 'utf8' : $charset;
	}

	/**
	 * Normalize a MySQL collation name.
	 *
	 * @param string $collation Collation name.
	 * @return string Normalized collation.
	 */
	private function normalize_mysql_collation_name( string $collation ): string {
		$collation = strtolower( trim( $collation, "'\"` \t\n\r\0\x0B" ) );
		if ( 0 === strpos( $collation, 'utf8mb3_' ) ) {
			return 'utf8_' . substr( $collation, strlen( 'utf8mb3_' ) );
		}

		return $collation;
	}

	/**
	 * Get the default MySQL collation for a charset.
	 *
	 * @param string $charset Charset name.
	 * @return string Collation name.
	 */
	private function get_default_mysql_collation_for_charset( string $charset ): string {
		$charset    = $this->normalize_mysql_charset_name( $charset );
		$collations = array(
			'ascii'   => 'ascii_general_ci',
			'big5'    => 'big5_chinese_ci',
			'binary'  => 'binary',
			'cp1251'  => 'cp1251_general_ci',
			'hebrew'  => 'hebrew_general_ci',
			'koi8r'   => 'koi8r_general_ci',
			'latin1'  => 'latin1_swedish_ci',
			'tis620'  => 'tis620_thai_ci',
			'ujis'    => 'ujis_japanese_ci',
			'utf8'    => 'utf8_general_ci',
			'utf8mb4' => 'utf8mb4_unicode_ci',
		);

		return $collations[ $charset ] ?? $charset . '_general_ci';
	}

	/**
	 * Execute a MySQL SHOW INDEX/SHOW INDEXES/SHOW KEYS statement through PostgreSQL catalogs.
	 *
	 * @param string      $table_name          Table name.
	 * @param array|null  $where_filter        Optional MySQL WHERE filters.
	 * @param int         $fetch_mode          PDO fetch mode.
	 * @param array       ...$fetch_mode_args  Additional fetch mode arguments.
	 * @return mixed SHOW INDEX result rows.
	 */
	private function execute_show_index_query( string $schema_name, string $table_name, ?array $where_filter, $fetch_mode, ...$fetch_mode_args ) {
		$this->ensure_mysql_schema_metadata_tables();

		$resolved_schema = $this->resolve_mysql_table_schema_for_introspection( $schema_name, $table_name );
		if ( 0 === strcasecmp( $resolved_schema, 'information_schema' ) ) {
			return $this->set_mysql_static_show_result(
				$this->get_show_index_output_columns(),
				array(),
				$fetch_mode,
				...$fetch_mode_args
			);
		}

		$cache_key = $this->get_mysql_introspection_result_cache_key(
			'show_index',
			$fetch_mode,
			array( $resolved_schema, $table_name, $where_filter, $fetch_mode, $fetch_mode_args )
		);
		if ( $this->load_mysql_introspection_result_from_cache( $cache_key ) ) {
			return $this->last_result;
		}

		$sql    = $this->mysql_index_metadata_has_rows( $resolved_schema, $table_name )
			? $this->get_show_index_metadata_query()
			: $this->get_show_index_catalog_query();
		$params = array(
			$resolved_schema,
			$table_name,
		);

		$where_expression_filter = $this->is_mysql_show_where_expression_filter( $where_filter ) ? $where_filter : null;
		if ( null !== $where_filter && null === $where_expression_filter ) {
			$where_conditions = array();
			foreach ( $where_filter as $filter ) {
				$where_conditions[] = $this->get_mysql_show_where_filter_condition_sql(
					$this->connection->quote_identifier( $filter['column'] ),
					$filter
				);
				$params[]           = $filter['value'];
			}

			$sql .= '
	WHERE ' . implode( ' AND ', $where_conditions );
		}

		$sql .= '
ORDER BY
	"Key_name" = \'PRIMARY\' DESC,
	"Non_unique" = \'0\' DESC,
	"Index_type" = \'SPATIAL\' DESC,
	"Index_type" = \'BTREE\' DESC,
	"Index_type" = \'FULLTEXT\' DESC,
	postgresql_index_oid,
	CAST("Seq_in_index" AS integer)';

		$stmt = $this->connection->query( $sql, $params );

		$this->last_postgresql_queries[] = array(
			'sql'    => $sql,
			'params' => $params,
		);
		$this->last_column_meta          = $this->normalize_column_meta( $stmt );
		if ( null !== $where_expression_filter ) {
			$rows = $stmt->fetchAll( PDO::FETCH_ASSOC );
			$rows = $this->filter_mysql_static_show_rows( $rows, $where_expression_filter );
			$this->set_mysql_associative_result_rows( $rows, $fetch_mode, ...$fetch_mode_args );
		} else {
			$this->last_result = $stmt->fetchAll( $fetch_mode, ...$fetch_mode_args );
		}

		$this->store_mysql_introspection_result_in_cache( $cache_key );

		return $this->last_result;
	}

	/**
	 * Get output columns for SHOW INDEX-family statements.
	 *
	 * @return string[] Output column names.
	 */
	private function get_show_index_output_columns(): array {
		return array(
			'Table',
			'Non_unique',
			'Key_name',
			'Seq_in_index',
			'Column_name',
			'Collation',
			'Cardinality',
			'Sub_part',
			'Packed',
			'Null',
			'Index_type',
			'Comment',
			'Index_comment',
			'Visible',
			'Expression',
		);
	}

	/**
	 * Load a cached MySQL introspection result into the current query state.
	 *
	 * @param string|null $cache_key Cache key, or null when this query shape is not cacheable.
	 * @return bool Whether a cached result was loaded.
	 */
	private function load_mysql_introspection_result_from_cache( ?string $cache_key ): bool {
		if ( null === $cache_key ) {
			return false;
		}

		if ( ! array_key_exists( $cache_key, $this->mysql_introspection_result_cache ) ) {
			return false;
		}

		$cached = $this->mysql_introspection_result_cache[ $cache_key ];
		if (
			! $this->try_copy_mysql_introspection_cache_value( $cached['column_meta'], $column_meta )
			|| ! $this->try_copy_mysql_introspection_cache_value( $cached['result'], $result )
		) {
			unset( $this->mysql_introspection_result_cache[ $cache_key ] );
			return false;
		}

		$this->last_column_meta = $column_meta;
		$this->last_result      = $result;

		return true;
	}

	/**
	 * Store the current MySQL introspection result in the request-local cache.
	 *
	 * @param string|null $cache_key Cache key, or null when this query shape is not cacheable.
	 */
	private function store_mysql_introspection_result_in_cache( ?string $cache_key ): void {
		if ( null === $cache_key ) {
			return;
		}

		if (
			! $this->try_copy_mysql_introspection_cache_value( $this->last_column_meta, $column_meta )
			|| ! $this->try_copy_mysql_introspection_cache_value( $this->last_result, $result )
		) {
			return;
		}

		$this->mysql_introspection_result_cache[ $cache_key ] = array(
			'column_meta' => $column_meta,
			'result'      => $result,
		);
	}

	/**
	 * Get a cache key for a MySQL introspection query shape.
	 *
	 * @param string $query_type Query type.
	 * @param mixed  $fetch_mode PDO fetch mode.
	 * @param array  $parts      Query shape parts.
	 * @return string|null Cache key, or null when the query shape is not cacheable.
	 */
	private function get_mysql_introspection_result_cache_key( string $query_type, $fetch_mode, array $parts ): ?string {
		if ( PDO::FETCH_FUNC === ( (int) $fetch_mode & self::PDO_FETCH_STYLE_MASK ) ) {
			return null;
		}

		if ( ! $this->is_mysql_introspection_cache_key_value_safe( $parts ) ) {
			return null;
		}

		return $query_type . "\0" . serialize( $parts );
	}

	/**
	 * Check whether a value can safely participate in an introspection cache key.
	 *
	 * @param mixed $value Value to inspect.
	 * @param int   $depth Recursion depth guard.
	 * @return bool Whether the value can be safely serialized into a cache key.
	 */
	private function is_mysql_introspection_cache_key_value_safe( $value, int $depth = 0 ): bool {
		if ( 20 < $depth ) {
			return false;
		}

		if ( null === $value || is_scalar( $value ) ) {
			return true;
		}

		if ( ! is_array( $value ) ) {
			return false;
		}

		foreach ( $value as $key => $item ) {
			if ( ! is_int( $key ) && ! is_string( $key ) ) {
				return false;
			}

			if ( ! $this->is_mysql_introspection_cache_key_value_safe( $item, $depth + 1 ) ) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Copy cached introspection data before exposing it to callers.
	 *
	 * @param mixed $value Cached value.
	 * @param mixed $copy  Copied value.
	 * @param int   $depth Recursion depth guard.
	 * @return bool Whether the value could be copied safely.
	 */
	private function try_copy_mysql_introspection_cache_value( $value, &$copy, int $depth = 0 ): bool {
		if ( 20 < $depth ) {
			return false;
		}

		if ( is_array( $value ) ) {
			$copy = array();
			foreach ( $value as $key => $item ) {
				if ( ! $this->try_copy_mysql_introspection_cache_value( $item, $item_copy, $depth + 1 ) ) {
					return false;
				}
				$copy[ $key ] = $item_copy;
			}
			return true;
		}

		if ( is_object( $value ) ) {
			if ( 'stdClass' !== get_class( $value ) ) {
				return false;
			}

			$copy = clone $value;
			return true;
		}

		if ( is_resource( $value ) ) {
			return false;
		}

		$copy = $value;
		return true;
	}

	/**
	 * Resolve the backend schema for an unqualified MySQL table introspection query.
	 *
	 * @param string $schema_name Requested schema name.
	 * @param string $table_name  Requested table name.
	 * @return string Backend schema name.
	 */
	private function resolve_mysql_table_schema_for_introspection( string $schema_name, string $table_name ): string {
		if ( 'public' !== $schema_name ) {
			return $schema_name;
		}

		$cache_key = $this->get_mysql_metadata_cache_key( $schema_name, $table_name );
		if ( isset( $this->mysql_table_schema_introspection_cache[ $cache_key ] ) ) {
			return $this->mysql_table_schema_introspection_cache[ $cache_key ];
		}

		$temporary_schema = $this->get_active_temporary_table_schema( $table_name );
		$resolved_schema  = null === $temporary_schema ? $schema_name : $temporary_schema;

		$this->mysql_table_schema_introspection_cache[ $cache_key ] = $resolved_schema;
		return $resolved_schema;
	}

	/**
	 * Get the active temporary schema for a table name.
	 *
	 * @param string $table_name Table name.
	 * @return string|null Temporary schema name, or null when no active temporary table exists.
	 */
	private function get_active_temporary_table_schema( string $table_name ): ?string {
		$driver_name     = $this->connection->get_driver_name();
		$pdo_driver_name = (string) $this->connection->get_pdo()->getAttribute( PDO::ATTR_DRIVER_NAME );

		if ( 'sqlite' === $driver_name ) {
			return $this->get_active_sqlite_temporary_table_schema( $table_name );
		}

		try {
			$stmt = $this->connection->query(
				'SELECT n.nspname
				FROM pg_catalog.pg_class c
				INNER JOIN pg_catalog.pg_namespace n
					ON n.oid = c.relnamespace
				WHERE n.oid = pg_my_temp_schema()
					AND lower(c.relname) = lower(?)
					AND c.relkind IN (\'r\', \'p\')
				LIMIT 1',
				array( $table_name )
			);
		} catch ( PDOException $e ) {
			if ( 'sqlite' !== $pdo_driver_name ) {
				throw $e;
			}

			return $this->get_active_sqlite_temporary_table_schema( $table_name );
		}

		$schema_name = $stmt->fetchColumn();
		return false === $schema_name ? null : (string) $schema_name;
	}

	/**
	 * Get the active SQLite temporary schema for a table name.
	 *
	 * @param string $table_name Table name.
	 * @return string|null Temporary schema name, or null when no active temporary table exists.
	 */
	private function get_active_sqlite_temporary_table_schema( string $table_name ): ?string {
		$stmt = $this->connection->query(
			"SELECT name FROM sqlite_temp_master WHERE type = 'table' AND LOWER(name) = LOWER(?) LIMIT 1",
			array( $table_name )
		);

		return false === $stmt->fetchColumn() ? null : 'temp';
	}

	/**
	 * Get the PostgreSQL catalog query backing MySQL DESCRIBE/DESC.
	 *
	 * @return string SQL query.
	 */
	private function get_describe_catalog_query(): string {
		$column_metadata_table = $this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE );
		$index_metadata_table  = $this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE );

		return sprintf(
			'WITH requested_table AS (
	SELECT ? AS table_schema, ? AS table_name
),
catalog_columns AS (
	SELECT
		c.column_name AS field_name,
		COALESCE(
			cm.column_type,
			CASE
				WHEN c.data_type = \'character varying\' THEN
					\'varchar\' || CASE
						WHEN c.character_maximum_length IS NULL THEN \'\'
						ELSE \'(\' || CAST(c.character_maximum_length AS text) || \')\'
					END
				WHEN c.data_type = \'character\' THEN
					\'char\' || CASE
						WHEN c.character_maximum_length IS NULL THEN \'\'
						ELSE \'(\' || CAST(c.character_maximum_length AS text) || \')\'
					END
				WHEN c.data_type = \'integer\' THEN \'int\'
				WHEN c.data_type = \'timestamp without time zone\' THEN \'datetime\'
				ELSE c.data_type
			END
		) AS column_type,
		COALESCE(cm.is_nullable, c.is_nullable) AS is_nullable,
		CASE
			WHEN EXISTS (
				SELECT 1
				FROM %2$s im
				WHERE im.table_schema = c.table_schema
					AND im.table_name = c.table_name
					AND im.column_name = c.column_name
					AND UPPER(im.key_name) = \'PRIMARY\'
			) THEN \'PRI\'
			WHEN EXISTS (
				SELECT 1
				FROM %2$s im
				WHERE im.table_schema = c.table_schema
					AND im.table_name = c.table_name
					AND im.column_name = c.column_name
					AND im.non_unique = \'0\'
			) THEN \'UNI\'
			WHEN EXISTS (
				SELECT 1
				FROM %2$s im
				WHERE im.table_schema = c.table_schema
					AND im.table_name = c.table_name
					AND im.column_name = c.column_name
			) THEN \'MUL\'
			WHEN EXISTS (
				SELECT 1
				FROM information_schema.table_constraints tc
				INNER JOIN information_schema.key_column_usage kcu
					ON kcu.constraint_schema = tc.constraint_schema
					AND kcu.constraint_name = tc.constraint_name
					AND kcu.table_schema = tc.table_schema
					AND kcu.table_name = tc.table_name
				WHERE tc.table_schema = c.table_schema
					AND tc.table_name = c.table_name
					AND tc.constraint_type = \'PRIMARY KEY\'
					AND kcu.column_name = c.column_name
			) THEN \'PRI\'
			WHEN EXISTS (
				SELECT 1
				FROM information_schema.table_constraints tc
				INNER JOIN information_schema.key_column_usage kcu
					ON kcu.constraint_schema = tc.constraint_schema
					AND kcu.constraint_name = tc.constraint_name
					AND kcu.table_schema = tc.table_schema
					AND kcu.table_name = tc.table_name
				WHERE tc.table_schema = c.table_schema
					AND tc.table_name = c.table_name
					AND tc.constraint_type = \'UNIQUE\'
					AND kcu.column_name = c.column_name
			) THEN \'UNI\'
			ELSE \'\'
		END AS column_key,
			CASE
				WHEN cm.column_name IS NOT NULL THEN cm.column_default
				ELSE c.column_default
			END AS column_default,
		COALESCE(
			cm.extra,
			CASE
				WHEN c.is_identity = \'YES\' THEN \'auto_increment\'
				WHEN c.column_default LIKE \'nextval(%%\' THEN \'auto_increment\'
				ELSE \'\'
			END
		) AS column_extra,
		c.ordinal_position
	FROM requested_table rt
	INNER JOIN information_schema.columns c
		ON c.table_schema = rt.table_schema
		AND c.table_name = rt.table_name
	LEFT JOIN %1$s cm
		ON cm.table_schema = c.table_schema
		AND cm.table_name = c.table_name
		AND cm.column_name = c.column_name
),
metadata_columns AS (
	SELECT
		cm.column_name AS field_name,
		cm.column_type,
		cm.is_nullable,
		CASE
			WHEN EXISTS (
				SELECT 1
				FROM %2$s im
				WHERE im.table_schema = cm.table_schema
					AND im.table_name = cm.table_name
					AND im.column_name = cm.column_name
					AND UPPER(im.key_name) = \'PRIMARY\'
			) THEN \'PRI\'
			WHEN EXISTS (
				SELECT 1
				FROM %2$s im
				WHERE im.table_schema = cm.table_schema
					AND im.table_name = cm.table_name
					AND im.column_name = cm.column_name
					AND im.non_unique = \'0\'
			) THEN \'UNI\'
			WHEN EXISTS (
				SELECT 1
				FROM %2$s im
				WHERE im.table_schema = cm.table_schema
					AND im.table_name = cm.table_name
					AND im.column_name = cm.column_name
			) THEN \'MUL\'
			ELSE \'\'
		END AS column_key,
		cm.column_default,
		cm.extra AS column_extra,
		cm.ordinal_position
	FROM requested_table rt
	INNER JOIN %1$s cm
		ON cm.table_schema = rt.table_schema
		AND cm.table_name = rt.table_name
	WHERE NOT EXISTS (
		SELECT 1
		FROM information_schema.columns c
		WHERE c.table_schema = cm.table_schema
			AND c.table_name = cm.table_name
			AND c.column_name = cm.column_name
	)
),
describe_rows AS (
	SELECT * FROM catalog_columns
	UNION ALL
	SELECT * FROM metadata_columns
)
SELECT
	field_name AS "Field",
	column_type AS "Type",
	is_nullable AS "Null",
	column_key AS "Key",
	column_default AS "Default",
	column_extra AS "Extra"
FROM describe_rows
ORDER BY ordinal_position',
			$column_metadata_table,
			$index_metadata_table
		);
	}

	/**
	 * Get the PostgreSQL catalog query backing MySQL SHOW COLUMNS/FULL COLUMNS.
	 *
	 * @param bool $is_full Whether the query should emit SHOW FULL COLUMNS fields.
	 * @return string SQL query.
	 */
	private function get_show_columns_catalog_query( bool $is_full ): string {
		$column_metadata_table = $this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE );
		$index_metadata_table  = $this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE );

		$type_expression = 'CASE
		WHEN c.data_type = \'character varying\' THEN
			\'varchar\' || CASE
				WHEN c.character_maximum_length IS NULL THEN \'\'
				ELSE \'(\' || CAST(c.character_maximum_length AS text) || \')\'
			END
		WHEN c.data_type = \'character\' THEN
			\'char\' || CASE
				WHEN c.character_maximum_length IS NULL THEN \'\'
				ELSE \'(\' || CAST(c.character_maximum_length AS text) || \')\'
			END
		WHEN c.data_type = \'integer\' THEN \'int\'
		WHEN c.data_type = \'timestamp without time zone\' THEN \'datetime\'
		ELSE c.data_type
	END';

		$catalog_collation_expression = 'CASE
		WHEN cm.column_type IS NOT NULL THEN
			CASE
				WHEN LOWER(cm.column_type) LIKE \'char%\'
					OR LOWER(cm.column_type) LIKE \'varchar%\'
					OR LOWER(cm.column_type) LIKE \'%text%\' THEN COALESCE(cm.collation_name, c.collation_name, \'utf8mb4_unicode_ci\')
				ELSE NULL
			END
		WHEN c.data_type IN (\'character varying\', \'character\', \'text\') THEN COALESCE(c.collation_name, \'utf8mb4_unicode_ci\')
		ELSE NULL
	END';

		$metadata_collation_expression = 'CASE
		WHEN LOWER(cm.column_type) LIKE \'char%\'
			OR LOWER(cm.column_type) LIKE \'varchar%\'
			OR LOWER(cm.column_type) LIKE \'%text%\' THEN COALESCE(cm.collation_name, \'utf8mb4_unicode_ci\')
		ELSE NULL
	END';

		$catalog_key_expression = sprintf(
			'CASE
		WHEN EXISTS (
			SELECT 1
			FROM %1$s im
			WHERE im.table_schema = c.table_schema
				AND im.table_name = c.table_name
				AND im.column_name = c.column_name
				AND UPPER(im.key_name) = \'PRIMARY\'
		) THEN \'PRI\'
		WHEN EXISTS (
			SELECT 1
			FROM %1$s im
			WHERE im.table_schema = c.table_schema
				AND im.table_name = c.table_name
				AND im.column_name = c.column_name
				AND im.non_unique = \'0\'
		) THEN \'UNI\'
		WHEN EXISTS (
			SELECT 1
			FROM %1$s im
			WHERE im.table_schema = c.table_schema
				AND im.table_name = c.table_name
				AND im.column_name = c.column_name
		) THEN \'MUL\'
		WHEN EXISTS (
			SELECT 1
			FROM information_schema.table_constraints tc
			INNER JOIN information_schema.key_column_usage kcu
				ON kcu.constraint_schema = tc.constraint_schema
				AND kcu.constraint_name = tc.constraint_name
				AND kcu.table_schema = tc.table_schema
				AND kcu.table_name = tc.table_name
			WHERE tc.table_schema = c.table_schema
				AND tc.table_name = c.table_name
				AND tc.constraint_type = \'PRIMARY KEY\'
				AND kcu.column_name = c.column_name
		) THEN \'PRI\'
		WHEN EXISTS (
			SELECT 1
			FROM information_schema.table_constraints tc
			INNER JOIN information_schema.key_column_usage kcu
				ON kcu.constraint_schema = tc.constraint_schema
				AND kcu.constraint_name = tc.constraint_name
				AND kcu.table_schema = tc.table_schema
				AND kcu.table_name = tc.table_name
			WHERE tc.table_schema = c.table_schema
				AND tc.table_name = c.table_name
				AND tc.constraint_type = \'UNIQUE\'
				AND kcu.column_name = c.column_name
		) THEN \'UNI\'
		ELSE \'\'
	END',
			$index_metadata_table
		);

		$metadata_key_expression = sprintf(
			'CASE
		WHEN EXISTS (
			SELECT 1
			FROM %1$s im
			WHERE im.table_schema = cm.table_schema
				AND im.table_name = cm.table_name
				AND im.column_name = cm.column_name
				AND UPPER(im.key_name) = \'PRIMARY\'
		) THEN \'PRI\'
		WHEN EXISTS (
			SELECT 1
			FROM %1$s im
			WHERE im.table_schema = cm.table_schema
				AND im.table_name = cm.table_name
				AND im.column_name = cm.column_name
				AND im.non_unique = \'0\'
		) THEN \'UNI\'
		WHEN EXISTS (
			SELECT 1
			FROM %1$s im
			WHERE im.table_schema = cm.table_schema
				AND im.table_name = cm.table_name
				AND im.column_name = cm.column_name
		) THEN \'MUL\'
		ELSE \'\'
	END',
			$index_metadata_table
		);

		$catalog_extra_expression = 'CASE
		WHEN c.is_identity = \'YES\' THEN \'auto_increment\'
		WHEN c.column_default LIKE \'nextval(%\' THEN \'auto_increment\'
		ELSE \'\'
	END';

		if ( $is_full ) {
			$fields = 'field_name AS "Field",
		column_type AS "Type",
		collation_name AS "Collation",
		is_nullable AS "Null",
		column_key AS "Key",
		column_default AS "Default",
		column_extra AS "Extra",
		\'select,insert,update,references\' AS "Privileges",
		column_comment AS "Comment"';
		} else {
			$fields = 'field_name AS "Field",
	column_type AS "Type",
	is_nullable AS "Null",
	column_key AS "Key",
	column_default AS "Default",
	column_extra AS "Extra"';
		}

		return sprintf(
			'WITH requested_table AS (
	SELECT ? AS table_schema, ? AS table_name
),
catalog_columns AS (
	SELECT
		c.column_name AS field_name,
		COALESCE(cm.column_type, %3$s) AS column_type,
		%4$s AS collation_name,
		COALESCE(cm.is_nullable, c.is_nullable) AS is_nullable,
		%5$s AS column_key,
			CASE
				WHEN cm.column_name IS NOT NULL THEN cm.column_default
				ELSE c.column_default
			END AS column_default,
			COALESCE(cm.extra, %7$s) AS column_extra,
			COALESCE(cm.column_comment, \'\') AS column_comment,
			c.ordinal_position
	FROM requested_table rt
	INNER JOIN information_schema.columns c
		ON c.table_schema = rt.table_schema
		AND c.table_name = rt.table_name
	LEFT JOIN %1$s cm
		ON cm.table_schema = c.table_schema
		AND cm.table_name = c.table_name
		AND cm.column_name = c.column_name
),
metadata_columns AS (
	SELECT
		cm.column_name AS field_name,
		cm.column_type,
		%8$s AS collation_name,
		cm.is_nullable,
		%6$s AS column_key,
			cm.column_default,
			cm.extra AS column_extra,
			cm.column_comment,
			cm.ordinal_position
	FROM requested_table rt
	INNER JOIN %1$s cm
		ON cm.table_schema = rt.table_schema
		AND cm.table_name = rt.table_name
	WHERE NOT EXISTS (
		SELECT 1
		FROM information_schema.columns c
		WHERE c.table_schema = cm.table_schema
			AND c.table_name = cm.table_name
			AND c.column_name = cm.column_name
	)
),
show_columns_rows AS (
	SELECT * FROM catalog_columns
	UNION ALL
	SELECT * FROM metadata_columns
)
SELECT
	%9$s
FROM show_columns_rows
WHERE 1 = 1',
			$column_metadata_table,
			$index_metadata_table,
			$type_expression,
			$catalog_collation_expression,
			$catalog_key_expression,
			$metadata_key_expression,
			$catalog_extra_expression,
			$metadata_collation_expression,
			$fields
		);
	}

	/**
	 * Get the PostgreSQL catalog query backing MySQL SHOW INDEX/SHOW INDEXES/SHOW KEYS.
	 *
	 * @return string SQL query.
	 */
	private function get_show_index_catalog_query(): string {
		$index_metadata_table = $this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE );

		return sprintf(
			'WITH requested_table AS (
	SELECT ? AS table_schema, ? AS table_name
),
metadata_exists AS (
	SELECT EXISTS (
		SELECT 1
		FROM %1$s im
		INNER JOIN requested_table rt
			ON rt.table_schema = im.table_schema
			AND rt.table_name = im.table_name
	) AS has_metadata
),
metadata_index_rows AS (
	SELECT
		im.table_name AS "Table",
		im.non_unique AS "Non_unique",
		im.key_name AS "Key_name",
		CAST(im.seq_in_index AS text) AS "Seq_in_index",
		im.column_name AS "Column_name",
			CASE WHEN im.index_type = \'FULLTEXT\' THEN NULL ELSE COALESCE(im."collation", \'A\') END AS "Collation",
		\'0\' AS "Cardinality",
		im.sub_part AS "Sub_part",
		NULL AS "Packed",
		im.nullable AS "Null",
		im.index_type AS "Index_type",
		\'\' AS "Comment",
		im.index_comment AS "Index_comment",
		\'YES\' AS "Visible",
		NULL AS "Expression",
		im.index_ordinal AS postgresql_index_oid
	FROM %1$s im
	INNER JOIN requested_table rt
		ON rt.table_schema = im.table_schema
		AND rt.table_name = im.table_name
),
index_columns AS (
		SELECT
			t.relname AS table_name,
			CAST(idx.oid AS bigint) AS postgresql_index_oid,
			idx.relname AS postgresql_index_name,
			i.indisunique,
			i.indisprimary,
		am.amname AS access_method,
		k.ordinality AS seq_in_index,
		k.attnum,
		a.attname AS column_name,
		a.attnotnull,
		CASE
			WHEN 0 = k.attnum THEN pg_catalog.pg_get_indexdef(i.indexrelid, CAST(k.ordinality AS integer), true)
			ELSE NULL
		END AS expression
	FROM pg_catalog.pg_class t
	INNER JOIN pg_catalog.pg_namespace n
		ON n.oid = t.relnamespace
	INNER JOIN pg_catalog.pg_index i
		ON i.indrelid = t.oid
	INNER JOIN pg_catalog.pg_class idx
		ON idx.oid = i.indexrelid
	INNER JOIN pg_catalog.pg_am am
		ON am.oid = idx.relam
		CROSS JOIN LATERAL pg_catalog.unnest(i.indkey) WITH ORDINALITY AS k(attnum, ordinality)
		LEFT JOIN pg_catalog.pg_attribute a
			ON a.attrelid = t.oid
			AND a.attnum = k.attnum
		INNER JOIN requested_table rt
			ON rt.table_schema = n.nspname
			AND rt.table_name = t.relname
		WHERE k.ordinality <= i.indnkeyatts
			AND i.indisvalid
			AND i.indislive
),
catalog_index_rows AS (
	SELECT
		table_name AS "Table",
		CASE WHEN indisunique THEN \'0\' ELSE \'1\' END AS "Non_unique",
	CASE
		WHEN indisprimary THEN \'PRIMARY\'
			WHEN postgresql_index_name LIKE table_name || \'__%%\' THEN SUBSTRING(postgresql_index_name FROM CHAR_LENGTH(table_name || \'__\') + 1)
		ELSE postgresql_index_name
	END AS "Key_name",
	CAST(seq_in_index AS text) AS "Seq_in_index",
	column_name AS "Column_name",
	\'A\' AS "Collation",
	\'0\' AS "Cardinality",
	NULL AS "Sub_part",
	NULL AS "Packed",
	CASE
		WHEN 0 = attnum OR attnotnull THEN \'\'
		ELSE \'YES\'
	END AS "Null",
	UPPER(access_method) AS "Index_type",
	\'\' AS "Comment",
	\'\' AS "Index_comment",
		\'YES\' AS "Visible",
		expression AS "Expression",
		postgresql_index_oid
	FROM index_columns
	WHERE NOT (SELECT has_metadata FROM metadata_exists)
),
show_index_rows AS (
	SELECT * FROM metadata_index_rows
	UNION ALL
	SELECT * FROM catalog_index_rows
	)
	SELECT
		"Table",
	"Non_unique",
	"Key_name",
	"Seq_in_index",
	"Column_name",
	"Collation",
	"Cardinality",
	"Sub_part",
	"Packed",
	"Null",
	"Index_type",
	"Comment",
	"Index_comment",
		"Visible",
		"Expression"
	FROM show_index_rows',
			$index_metadata_table
		);
	}

	/**
	 * Get the metadata-only query backing MySQL SHOW INDEX/SHOW INDEXES/SHOW KEYS.
	 *
	 * @return string SQL query.
	 */
	private function get_show_index_metadata_query(): string {
		$index_metadata_table = $this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE );

		return sprintf(
			'SELECT
	"Table",
	"Non_unique",
	"Key_name",
	"Seq_in_index",
	"Column_name",
	"Collation",
	"Cardinality",
	"Sub_part",
	"Packed",
	"Null",
	"Index_type",
	"Comment",
	"Index_comment",
	"Visible",
	"Expression"
FROM (
	SELECT
		im.table_name AS "Table",
		im.non_unique AS "Non_unique",
		im.key_name AS "Key_name",
		CAST(im.seq_in_index AS text) AS "Seq_in_index",
		im.column_name AS "Column_name",
			CASE WHEN im.index_type = \'FULLTEXT\' THEN NULL ELSE COALESCE(im."collation", \'A\') END AS "Collation",
		\'0\' AS "Cardinality",
		im.sub_part AS "Sub_part",
		NULL AS "Packed",
		im.nullable AS "Null",
			im.index_type AS "Index_type",
			\'\' AS "Comment",
			im.index_comment AS "Index_comment",
			\'YES\' AS "Visible",
		NULL AS "Expression",
		im.index_ordinal AS postgresql_index_oid
	FROM %s im
	WHERE im.table_schema = ?
		AND im.table_name = ?
) AS show_index_rows',
			$index_metadata_table
		);
	}

	/**
	 * Get results of the last query.
	 *
	 * @return mixed
	 */
	public function get_query_results() {
		return $this->last_result;
	}

	/**
	 * Get return value of the last query() function call.
	 *
	 * @return mixed
	 */
	public function get_last_return_value() {
		return $this->last_result;
	}

	/**
	 * Get the number of columns returned by the last query.
	 *
	 * @return int
	 */
	public function get_last_column_count(): int {
		if ( null !== $this->last_column_meta_statement ) {
			return $this->last_column_count;
		}

		return count( $this->last_column_meta );
	}

	/**
	 * Get column metadata for results of the last query.
	 *
	 * @return array
	 */
	public function get_last_column_meta(): array {
		$this->materialize_last_column_meta();
		return $this->last_column_meta;
	}

	/**
	 * Begin a transaction.
	 */
	public function beginTransaction(): void { // phpcs:ignore WordPress.NamingConventions.ValidFunctionName.MethodNameInvalid
		$this->connection->get_pdo()->beginTransaction();
		$this->connection->reset_statement_savepoint_state();
	}

	/**
	 * A temporary alias for back compatibility.
	 *
	 * @see self::beginTransaction()
	 */
	public function begin_transaction(): void {
		$this->beginTransaction();
	}

	/**
	 * Commit the current transaction.
	 */
	public function commit(): void {
		$this->connection->get_pdo()->commit();
		$this->connection->reset_statement_savepoint_state();
	}

	/**
	 * Rollback the current transaction.
	 */
	public function rollback(): void {
		$this->connection->get_pdo()->rollBack();
		$this->connection->reset_statement_savepoint_state();
	}

	/**
	 * Reset per-query state.
	 */
	private function reset_query_state(): void {
		$this->last_result                     = null;
		$this->last_column_meta                = array();
		$this->last_column_count               = 0;
		$this->last_column_meta_statement      = null;
		$this->last_column_meta_excluded_names = array();
		$this->last_mysql_query                = null;
		$this->last_postgresql_queries         = array();
	}

	/**
	 * Clear column metadata for a non-result statement.
	 */
	private function clear_last_column_meta(): void {
		$this->last_column_meta                = array();
		$this->last_column_count               = 0;
		$this->last_column_meta_statement      = null;
		$this->last_column_meta_excluded_names = array();
	}

	/**
	 * Store a statement for lazy column metadata normalization.
	 *
	 * @param PDOStatement $stmt         Statement with result columns.
	 * @param int          $column_count Number of result columns.
	 */
	private function set_lazy_last_column_meta( PDOStatement $stmt, int $column_count ): void {
		$this->last_column_meta                = array();
		$this->last_column_count               = $column_count;
		$this->last_column_meta_statement      = $stmt;
		$this->last_column_meta_excluded_names = array();
	}

	/**
	 * Normalize deferred column metadata when a caller actually needs it.
	 */
	private function materialize_last_column_meta(): void {
		if ( null === $this->last_column_meta_statement ) {
			return;
		}

		$this->last_column_meta                = $this->normalize_column_meta(
			$this->last_column_meta_statement,
			$this->last_column_meta_excluded_names
		);
		$this->last_column_count               = count( $this->last_column_meta );
		$this->last_column_meta_statement      = null;
		$this->last_column_meta_excluded_names = array();
	}

	/**
	 * Translate the WordPress options cleanup DELETE ... REGEXP query.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when the query is unsupported.
	 */
	private function translate_wordpress_options_regexp_delete_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0], $tokens[1], $tokens[2], $tokens[3], $tokens[4], $tokens[5], $tokens[6] )
			|| WP_MySQL_Lexer::DELETE_SYMBOL !== $tokens[0]->id
			|| WP_MySQL_Lexer::FROM_SYMBOL !== $tokens[1]->id
			|| WP_MySQL_Lexer::WHERE_SYMBOL !== $tokens[3]->id
			|| WP_MySQL_Lexer::REGEXP_SYMBOL !== $tokens[5]->id
		) {
			return null;
		}

		$table_name = $this->get_mysql_identifier_token_value( $tokens[2] );
		$column     = $this->get_mysql_identifier_token_value( $tokens[4] );
		if ( null === $table_name || null === $column || ! $this->is_wordpress_options_table_name( $table_name ) ) {
			return null;
		}

		if (
			WP_MySQL_Lexer::SINGLE_QUOTED_TEXT !== $tokens[6]->id
			&& WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT !== $tokens[6]->id
		) {
			return null;
		}

		if ( ! $this->is_at_mysql_query_end( $tokens, 7 ) ) {
			return null;
		}

		return sprintf(
			'DELETE FROM %s WHERE %s ~* %s',
			$this->connection->quote_identifier( $table_name ),
			$this->connection->quote_identifier( $column ),
			$this->connection->quote( $tokens[6]->get_value() )
		);
	}

	/**
	 * Translate WordPress expired transient cleanup DELETE statements.
	 *
	 * Core emits a MySQL multi-table DELETE that removes both transient values
	 * and their timeout rows. PostgreSQL does not support that DELETE syntax, so
	 * this rewrites only the exact WordPress options-table shape to a CTE-backed
	 * single-table DELETE.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when the query is unsupported.
	 */
	private function translate_wordpress_expired_transients_delete_query( string $query ): ?string {
		$pattern = '/^\s*DELETE\s+a\s*,\s*b\s+FROM\s+([A-Za-z0-9_]+)\s+a\s*,\s*\1\s+b\s+WHERE\s+a\.option_name\s+LIKE\s+([\'"])([^\'"]+)\\2\s+AND\s+a\.option_name\s+NOT\s+LIKE\s+([\'"])([^\'"]+)\\4\s+AND\s+b\.option_name\s*=\s*CONCAT\s*\(\s*([\'"])([^\'"]+)\\6\s*,\s*SUBSTRING\s*\(\s*a\.option_name\s*,\s*([0-9]+)\s*\)\s*\)\s+AND\s+b\.option_value\s*<\s*([0-9]+)\s*;?\s*$/is';
		if ( ! preg_match( $pattern, $query, $matches ) ) {
			return null;
		}

		$table_name     = $matches[1];
		$value_like     = $matches[3];
		$timeout_like   = $matches[5];
		$timeout_prefix = $matches[7];
		$substring_from = (int) $matches[8];
		$expires_before = $matches[9];

		if (
			! $this->is_wordpress_options_table_name( $table_name )
			|| ! in_array( $timeout_prefix, array( '_transient_timeout_', '_site_transient_timeout_' ), true )
			|| ( '_transient_timeout_' === $timeout_prefix && 12 !== $substring_from )
			|| ( '_site_transient_timeout_' === $timeout_prefix && 17 !== $substring_from )
		) {
			return null;
		}

		return sprintf(
			'WITH expired_transients AS (
	SELECT a.option_name AS value_name, b.option_name AS timeout_name
	FROM %1$s a
	INNER JOIN %1$s b
		ON b.option_name = %2$s || SUBSTR(a.option_name, %3$d)
	WHERE a.option_name LIKE %4$s ESCAPE %5$s
		AND a.option_name NOT LIKE %6$s ESCAPE %5$s
		AND CAST(b.option_value AS BIGINT) < %7$s
)
DELETE FROM %1$s
WHERE option_name IN (
	SELECT value_name FROM expired_transients
	UNION
	SELECT timeout_name FROM expired_transients
)',
			$this->connection->quote_identifier( $table_name ),
			$this->connection->quote( $timeout_prefix ),
			$substring_from,
			$this->connection->quote( $value_like ),
			$this->connection->quote( '\\' ),
			$this->connection->quote( $timeout_like ),
			$expires_before
		);
	}

	/**
	 * Translate MySQL single-target orphan cleanup DELETE statements.
	 *
	 * WooCommerce emits DELETE alias FROM target alias LEFT JOIN related alias
	 * ... WHERE related.id IS NULL to purge orphaned metadata. PostgreSQL does
	 * not support MySQL's DELETE target list, and rewriting the LEFT JOIN to a
	 * PostgreSQL USING join would change the anti-join semantics. Keep this path
	 * constrained to the exact single LEFT JOIN null-rejection shape.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when the query is unsupported.
	 */
	private function translate_mysql_left_join_orphan_delete_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0], $tokens[1], $tokens[2], $tokens[3], $tokens[4], $tokens[5], $tokens[6], $tokens[7], $tokens[8], $tokens[9] )
			|| WP_MySQL_Lexer::DELETE_SYMBOL !== $tokens[0]->id
			|| WP_MySQL_Lexer::FROM_SYMBOL !== $tokens[2]->id
			|| WP_MySQL_Lexer::LEFT_SYMBOL !== $tokens[5]->id
			|| WP_MySQL_Lexer::JOIN_SYMBOL !== $tokens[6]->id
			|| WP_MySQL_Lexer::ON_SYMBOL !== $tokens[9]->id
		) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 10 );
		if ( null === $statement_end ) {
			return null;
		}

		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, 10, $statement_end );
		if ( null === $where_position || 10 >= $where_position || $where_position + 1 >= $statement_end ) {
			return null;
		}

		$delete_alias = $this->get_mysql_identifier_token_value( $tokens[1] );
		$target_table = $this->get_mysql_identifier_token_value( $tokens[3] );
		$target_alias = $this->get_mysql_identifier_token_value( $tokens[4] );
		$joined_table = $this->get_mysql_identifier_token_value( $tokens[7] );
		$joined_alias = $this->get_mysql_identifier_token_value( $tokens[8] );
		if (
			null === $delete_alias
			|| null === $target_table
			|| null === $target_alias
			|| null === $joined_table
			|| null === $joined_alias
			|| strtolower( $delete_alias ) !== strtolower( $target_alias )
		) {
			return null;
		}

		if ( ! $this->is_mysql_null_rejected_join_alias_predicate( $tokens, $where_position + 1, $statement_end, $joined_alias ) ) {
			return null;
		}

		return sprintf(
			'DELETE FROM %s AS %s WHERE NOT EXISTS (SELECT 1 FROM %s AS %s WHERE %s)',
			$this->connection->quote_identifier( $target_table ),
			$this->translate_mysql_identifier_value_to_postgresql( $target_alias ),
			$this->connection->quote_identifier( $joined_table ),
			$this->translate_mysql_identifier_value_to_postgresql( $joined_alias ),
			$this->translate_mysql_token_sequence_to_postgresql( $tokens, 10, $where_position )
		);
	}

	/**
	 * Translate supported MySQL target-list DELETE statements.
	 *
	 * PostgreSQL cannot delete from multiple target tables directly. First
	 * materialize each target row ctid from the MySQL table-reference list, then
	 * delete each target through writable CTEs and return the summed affected row
	 * count. ORDER BY without LIMIT is validated and omitted because it does not
	 * change the affected row set.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_mysql_multi_target_delete_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0], $tokens[1] )
			|| WP_MySQL_Lexer::DELETE_SYMBOL !== $tokens[0]->id
		) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end || ! $this->is_at_mysql_query_end( $tokens, $statement_end ) ) {
			return null;
		}

		if ( WP_MySQL_Lexer::FROM_SYMBOL === $tokens[1]->id ) {
			$using_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::USING_SYMBOL, 2, $statement_end );
			if ( null === $using_position || 2 >= $using_position || $using_position + 1 >= $statement_end ) {
				return null;
			}

			$target_aliases         = $this->parse_mysql_delete_target_aliases( $tokens, 2, $using_position );
			$table_references_start = $using_position + 1;
		} else {
			$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, 1, $statement_end );
			if ( null === $from_position || 1 >= $from_position || $from_position + 1 >= $statement_end ) {
				return null;
			}

			$target_aliases         = $this->parse_mysql_delete_target_aliases( $tokens, 1, $from_position );
			$table_references_start = $from_position + 1;
		}

		if ( null === $target_aliases ) {
			return null;
		}

		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, $table_references_start, $statement_end );
		$order_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::ORDER_SYMBOL, $table_references_start, $statement_end );
		$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, $table_references_start, $statement_end );
		$order_end      = $limit_position ?? $statement_end;
		if (
			( null !== $order_position && null !== $where_position && $order_position < $where_position )
			|| ( null !== $limit_position && null !== $where_position && $limit_position < $where_position )
			|| ( null !== $limit_position && null !== $order_position && $limit_position < $order_position )
			|| ( null !== $order_position && ! $this->is_nonempty_mysql_order_by_clause( $tokens, $order_position, $order_end ) )
		) {
			return null;
		}

		$from_end = $where_position ?? $order_position ?? $limit_position ?? $statement_end;
		if ( $table_references_start >= $from_end ) {
			return null;
		}

		$information_schema_source_translation = null;
		if (
			0 === strcasecmp( $this->db_name, 'information_schema' )
			|| $this->direct_information_schema_source_range_references_information_schema( $tokens, $table_references_start, $from_end )
		) {
			$information_schema_source_translation = $this->get_direct_information_schema_dml_source_translation(
				$query,
				$tokens,
				$table_references_start,
				$from_end
			);
			if ( null === $information_schema_source_translation ) {
				return null;
			}
			$scope      = $information_schema_source_translation['scope'];
			$source_sql = $information_schema_source_translation['sql'];
		} else {
			$scope = $this->get_mysql_select_scope( $tokens, $table_references_start, $from_end );
			if ( null === $scope || ! empty( $scope['unknown'] ) ) {
				return null;
			}
			$source_sql = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $table_references_start, $from_end );
		}

		$target_tables = array();
		$target_groups = array();
		foreach ( $target_aliases as $target_alias ) {
			$target_key = strtolower( $target_alias );
			if ( ! isset( $scope['aliases'][ $target_key ] ) ) {
				return null;
			}

			$target_table         = $scope['aliases'][ $target_key ];
			$this->get_mysql_writable_table_backend_schema(
				array(
					'schema' => $target_table['schema'],
					'table'  => $target_table['table'],
				),
				'DELETE'
			);
			$target_physical_name = strtolower( $target_table['schema'] . '.' . $target_table['table'] );
			if ( ! isset( $target_groups[ $target_physical_name ] ) ) {
				$target_groups[ $target_physical_name ] = array(
					'alias'        => $target_alias,
					'table'        => $target_table['table'],
					'ctid_aliases' => array(),
				);
			}

			$target_tables[] = array(
				'alias'         => $target_alias,
				'table'         => $target_table['table'],
				'physical_name' => $target_physical_name,
			);
		}

		$where_sql = '';
		if ( null !== $where_position ) {
			$where_end = $order_position ?? $limit_position ?? $statement_end;
			if ( $where_position + 1 >= $where_end ) {
				return null;
			}

			if ( null !== $information_schema_source_translation ) {
				$where = $this->translate_direct_information_schema_dml_predicate_to_postgresql(
					$tokens,
					$where_position + 1,
					$where_end,
					$information_schema_source_translation['context']
				);
				if ( null === $where ) {
					return null;
				}
				$where_sql = ' WHERE ' . $where;
			} else {
				if ( ! $this->is_supported_simple_mysql_expression_fragment( $tokens, $where_position + 1, $where_end ) ) {
					return null;
				}

				$where     = $this->translate_mysql_predicate_token_sequence_to_postgresql(
					$tokens,
					$where_position + 1,
					$where_end,
					$scope
				);
				$where_sql = ' WHERE ' . $where['sql'];
			}
		}

		$order_sql = '';
		if ( null !== $order_position && null !== $limit_position ) {
			$order_sql = $this->translate_mysql_joined_dml_order_by_clause_to_postgresql( $tokens, $order_position, $limit_position, $scope );
			if ( null === $order_sql ) {
				return null;
			}
		}

		$limit_sql = '';
		if ( null !== $limit_position ) {
			$limit_sql = $this->translate_simple_dml_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end, true );
			if ( null === $limit_sql ) {
				return null;
			}
		}

		$select_columns = array();
		foreach ( $target_tables as $index => $target_table ) {
			$ctid_alias       = 'mysql_delete_target_' . $index . '_ctid';
			$target_alias_sql = $this->connection->quote_identifier( $target_table['alias'] );

			$select_columns[] = sprintf(
				'%s.ctid AS %s',
				$target_alias_sql,
				$this->connection->quote_identifier( $ctid_alias )
			);
			$target_groups[ $target_table['physical_name'] ]['ctid_aliases'][] = $ctid_alias;
		}

		$delete_ctes = array();
		$count_parts = array();
		foreach ( array_values( $target_groups ) as $index => $target_group ) {
			$delete_cte_name  = 'mysql_delete_target_' . $index;
			$target_alias_sql = $this->connection->quote_identifier( $target_group['alias'] );
			if ( 1 === count( $target_group['ctid_aliases'] ) ) {
				$ctid_predicate = sprintf(
					'%s.ctid = mysql_delete_rows.%s',
					$target_alias_sql,
					$this->connection->quote_identifier( $target_group['ctid_aliases'][0] )
				);
			} else {
				$ctid_selects = array();
				foreach ( $target_group['ctid_aliases'] as $ctid_alias ) {
					$ctid_selects[] = sprintf(
						'SELECT %s FROM mysql_delete_rows',
						$this->connection->quote_identifier( $ctid_alias )
					);
				}
				$ctid_predicate = sprintf(
					'%s.ctid IN (%s)',
					$target_alias_sql,
					implode( ' UNION ', $ctid_selects )
				);
			}

			$delete_ctes[] = sprintf(
				'%s AS (DELETE FROM %s AS %s USING mysql_delete_rows WHERE %s RETURNING 1)',
				$delete_cte_name,
				$this->connection->quote_identifier( $target_group['table'] ),
				$target_alias_sql,
				$ctid_predicate
			);
			$count_parts[] = sprintf( '(SELECT COUNT(*) FROM %s)', $delete_cte_name );
		}

		return sprintf(
			'WITH mysql_delete_rows AS MATERIALIZED (SELECT %s FROM %s%s%s%s), %s SELECT %s AS affected_rows',
			implode( ', ', $select_columns ),
			$source_sql,
			$where_sql,
			$order_sql,
			$limit_sql,
			implode( ', ', $delete_ctes ),
			implode( ' + ', $count_parts )
		);
	}

	/**
	 * Translate a DML source range that reads information_schema relations.
	 *
	 * @param string           $query Original MySQL query.
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $source_start First source token.
	 * @param int              $source_end Final source token, exclusive.
	 * @return array{scope: array, sql: string, context: array}|null Source translation, or null.
	 */
	private function get_direct_information_schema_dml_source_translation( string $query, array $tokens, int $source_start, int $source_end ): ?array {
		$parsed_sources = $this->parse_direct_information_schema_select_sources( $query, $tokens, $source_start, $source_end );
		if ( null === $parsed_sources ) {
			return null;
		}

		$context = array(
			'sources'                     => $parsed_sources['sources'],
			'join_predicate_ranges'       => $parsed_sources['join_predicate_ranges'],
			'join_predicate_replacements' => $parsed_sources['join_predicate_replacements'],
			'using_columns'               => $parsed_sources['using_columns'],
		);

		$scope = array(
			'tables'  => array(),
			'aliases' => array(),
			'unknown' => false,
		);
		foreach ( $context['sources'] as $source ) {
			if ( ! isset( $source['table'] ) ) {
				continue;
			}

			$table = array(
				'schema' => $this->resolve_mysql_table_schema_for_introspection( 'public', $source['table'] ),
				'table'  => $source['table'],
			);
			$alias = strtolower( $source['alias'] );
			if ( isset( $scope['aliases'][ $alias ] ) ) {
				return null;
			}

			$scope['tables'][]          = $table;
			$scope['aliases'][ $alias ] = $table;
		}

		if ( empty( $scope['tables'] ) ) {
			return null;
		}

		$replacements = $this->get_direct_information_schema_dml_source_replacements( $tokens, $context );
		if ( null === $replacements ) {
			return null;
		}

		return array(
			'scope'   => $scope,
			'sql'     => $this->translate_mysql_token_sequence_with_replacements_to_postgresql( $tokens, $source_start, $source_end, $replacements ),
			'context' => $context,
		);
	}

	/**
	 * Get source and JOIN-predicate replacements for an information_schema DML source.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param array            $context Direct information_schema context.
	 * @return array[]|null Replacement ranges, or null when unsupported.
	 */
	private function get_direct_information_schema_dml_source_replacements( array $tokens, array $context ): ?array {
		$replacements = array();
		foreach ( $context['join_predicate_replacements'] as $replacement ) {
			$replacements[] = $replacement;
		}

		foreach ( $context['join_predicate_ranges'] as $range ) {
			$current_database_function_replacements = $this->get_direct_information_schema_current_database_function_replacements(
				$tokens,
				$range['start'],
				$range['end']
			);
			if ( null === $current_database_function_replacements ) {
				return null;
			}

			$column_replacements = $this->get_direct_information_schema_column_replacements(
				$tokens,
				$range['start'],
				$range['end'],
				$context,
				$current_database_function_replacements
			);
			if ( null === $column_replacements ) {
				return null;
			}

			foreach ( array_merge( $current_database_function_replacements, $column_replacements ) as $replacement ) {
				$replacements[] = $replacement;
			}
		}

		$source_replacements = $this->get_direct_information_schema_source_replacements( $context );
		if ( null === $source_replacements ) {
			return null;
		}

		foreach ( $source_replacements as $replacement ) {
			$replacements[] = $replacement;
		}

		usort(
			$replacements,
			static function ( array $left, array $right ): int {
				return $left['start'] <=> $right['start'];
			}
		);

		return $replacements;
	}

	/**
	 * Translate a DML predicate that may reference information_schema sources.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start First predicate token.
	 * @param int              $end Final predicate token, exclusive.
	 * @param array            $context Direct information_schema context.
	 * @return string|null PostgreSQL predicate SQL, or null when unsupported.
	 */
	private function translate_direct_information_schema_dml_predicate_to_postgresql( array $tokens, int $start, int $end, array $context ): ?string {
		if (
			$this->contains_mysql_token(
				$tokens,
				$start,
				$end,
				array(
					WP_MySQL_Lexer::SELECT_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				)
			)
		) {
			return null;
		}

		$current_database_function_replacements = $this->get_direct_information_schema_current_database_function_replacements( $tokens, $start, $end );
		if ( null === $current_database_function_replacements ) {
			return null;
		}

		$column_replacements = $this->get_direct_information_schema_column_replacements(
			$tokens,
			$start,
			$end,
			$context,
			$current_database_function_replacements
		);
		if ( null === $column_replacements ) {
			return null;
		}

		$replacements = array_merge( $current_database_function_replacements, $column_replacements );
		usort(
			$replacements,
			static function ( array $left, array $right ): int {
				return $left['start'] <=> $right['start'];
			}
		);

		return $this->translate_mysql_token_sequence_with_replacements_to_postgresql( $tokens, $start, $end, $replacements );
	}

	/**
	 * Parse a MySQL DELETE target alias list.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First target token.
	 * @param int              $end    Final target token, exclusive.
	 * @return string[]|null Target aliases, or null when unsupported.
	 */
	private function parse_mysql_delete_target_aliases( array $tokens, int $start, int $end ): ?array {
		$aliases  = array();
		$position = $start;

		while ( $position < $end ) {
			$alias = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
			if ( null === $alias ) {
				return null;
			}
			++$position;

			if (
				$position + 1 < $end
				&& WP_MySQL_Lexer::DOT_SYMBOL === ( $tokens[ $position ]->id ?? null )
				&& WP_MySQL_Lexer::MULT_OPERATOR === ( $tokens[ $position + 1 ]->id ?? null )
			) {
				$position += 2;
			}

			$alias_key = strtolower( $alias );
			if ( isset( $aliases[ $alias_key ] ) ) {
				return null;
			}
			$aliases[ $alias_key ] = $alias;

			if ( $position === $end ) {
				break;
			}

			if ( WP_MySQL_Lexer::COMMA_SYMBOL !== ( $tokens[ $position ]->id ?? null ) ) {
				return null;
			}
			++$position;
		}

		return empty( $aliases ) ? null : array_values( $aliases );
	}

	/**
	 * Translate MySQL single-target joined DELETE statements.
	 *
	 * bbPress emits DELETE alias FROM target AS alias LEFT JOIN ... WHERE ...
	 * repair queries. PostgreSQL has no MySQL-style DELETE target list, and a
	 * direct DELETE USING rewrite would collapse LEFT JOIN semantics. Select the
	 * target physical rows through an equivalent joined subquery instead.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_mysql_single_target_join_delete_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0], $tokens[1], $tokens[2] )
			|| WP_MySQL_Lexer::DELETE_SYMBOL !== $tokens[0]->id
			|| WP_MySQL_Lexer::FROM_SYMBOL !== $tokens[2]->id
		) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 3 );
		if ( null === $statement_end || ! $this->is_at_mysql_query_end( $tokens, $statement_end ) ) {
			return null;
		}

		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, 3, $statement_end );
		if ( null === $where_position || 3 >= $where_position || $where_position + 1 >= $statement_end ) {
			return null;
		}

		$order_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::ORDER_SYMBOL, 3, $statement_end );
		$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, 3, $statement_end );
		if (
			( null !== $order_position && $order_position < $where_position )
			|| ( null !== $limit_position && $limit_position < $where_position )
			|| ( null !== $limit_position && null !== $order_position && $limit_position < $order_position )
		) {
			return null;
		}

		$delete_alias = $this->get_mysql_identifier_token_value( $tokens[1] );
		$target_ref   = $this->parse_mysql_table_reference( $tokens, 3, $where_position );
		if ( null === $delete_alias || null === $target_ref ) {
			return null;
		}
		$this->get_mysql_writable_table_backend_schema(
			array(
				'schema' => $target_ref['schema'],
				'table'  => $target_ref['table'],
			),
			'DELETE'
		);

		$target_alias = null === $target_ref['alias'] ? $target_ref['table'] : $target_ref['alias'];
		if (
			strtolower( $delete_alias ) !== strtolower( $target_alias )
			&& strtolower( $delete_alias ) !== strtolower( $target_ref['table'] )
		) {
			return null;
		}

		if ( null === $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::JOIN_SYMBOL, $target_ref['position'], $where_position ) ) {
			return null;
		}

		$scope = $this->get_mysql_select_scope( $tokens, 3, $where_position );
		if ( null === $scope || ! empty( $scope['unknown'] ) ) {
			return null;
		}

		$where_end = $order_position ?? $limit_position ?? $statement_end;
		if ( $where_position + 1 >= $where_end ) {
			return null;
		}

		$where_sql = $this->translate_mysql_predicate_token_sequence_to_postgresql(
			$tokens,
			$where_position + 1,
			$where_end,
			$scope
		);

		$order_sql = '';
		if ( null !== $order_position ) {
			$order_end = $limit_position ?? $statement_end;
			if ( null === $limit_position ) {
				if ( ! $this->is_nonempty_mysql_order_by_clause( $tokens, $order_position, $order_end ) ) {
					return null;
				}
			} else {
				$order_sql = $this->translate_simple_dml_order_by_clause_to_postgresql(
					$tokens,
					$order_position,
					$order_end,
					$target_ref['table'],
					$target_alias
				);
				if ( null === $order_sql ) {
					return null;
				}
			}
		}

		$limit_sql = '';
		if ( null !== $limit_position ) {
			$limit_sql = $this->translate_simple_dml_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end, true );
			if ( null === $limit_sql ) {
				return null;
			}
		}

		$target_alias_sql = $this->connection->quote_identifier( $target_alias );

		return sprintf(
			'DELETE FROM %s AS %s WHERE %s.ctid IN (SELECT %s.ctid FROM %s WHERE %s%s%s)',
			$this->connection->quote_identifier( $target_ref['table'] ),
			$target_alias_sql,
			$target_alias_sql,
			$target_alias_sql,
			$this->translate_mysql_token_sequence_to_postgresql( $tokens, 3, $where_position ),
			$where_sql['sql'],
			$order_sql,
			$limit_sql
		);
	}

	/**
	 * Check whether a WHERE clause is the null-rejected side of a LEFT JOIN.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First WHERE predicate token.
	 * @param int              $end    Final WHERE predicate token, exclusive.
	 * @param string           $alias  Joined table alias.
	 * @return bool Whether the predicate matches "<alias>.<column> IS NULL".
	 */
	private function is_mysql_null_rejected_join_alias_predicate( array $tokens, int $start, int $end, string $alias ): bool {
		if (
			$start + 5 !== $end
			|| WP_MySQL_Lexer::DOT_SYMBOL !== ( $tokens[ $start + 1 ]->id ?? null )
			|| WP_MySQL_Lexer::IS_SYMBOL !== ( $tokens[ $start + 3 ]->id ?? null )
			|| WP_MySQL_Lexer::NULL_SYMBOL !== ( $tokens[ $start + 4 ]->id ?? null )
		) {
			return false;
		}

		$predicate_alias = $this->get_mysql_identifier_token_value( $tokens[ $start ] ?? null );
		$column          = $this->get_mysql_identifier_token_value( $tokens[ $start + 2 ] ?? null );
		return null !== $predicate_alias
			&& null !== $column
			&& strtolower( $predicate_alias ) === strtolower( $alias );
	}

	/**
	 * Translate simple single-table MySQL DELETE statements to PostgreSQL.
	 *
	 * WordPress option deletes emit a single target table and a plain WHERE
		 * clause. Some plugins also use MySQL's single-table alias and ORDER BY
		 * forms. Bounded ORDER/LIMIT deletes are rewritten through PostgreSQL ctid
		 * subqueries; unbounded ORDER BY deletes omit the ordering because the same
		 * matched row set is deleted. Multi-table DELETE variants fall through
		 * unchanged so unsupported SQL still fails visibly in the backend.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when the query is unsupported.
	 */
	private function translate_simple_mysql_delete_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0] )
			|| WP_MySQL_Lexer::DELETE_SYMBOL !== $tokens[0]->id
		) {
			return null;
		}

		$position = 1;
		$this->consume_mysql_delete_modifiers( $tokens, $position );
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::FROM_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		++$position;
		$statement_end = $this->get_mysql_statement_end_position( $tokens, $position );
		if ( null === $statement_end || ! $this->is_at_mysql_query_end( $tokens, $statement_end ) ) {
			return null;
		}

		$table_reference = $this->parse_mysql_main_database_table_reference( $tokens, $position, $statement_end );
		if ( null === $table_reference ) {
			return null;
		}

		$table_name = $table_reference['table'];
		$alias      = $table_reference['alias'];

		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, $position, $statement_end );
		$order_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::ORDER_SYMBOL, $position, $statement_end );
		$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, $position, $statement_end );

		if (
			( null !== $where_position && $where_position !== $position )
				|| ( null !== $order_position && null !== $where_position && $order_position < $where_position )
				|| ( null !== $limit_position && null !== $where_position && $limit_position < $where_position )
				|| ( null !== $limit_position && null !== $order_position && $limit_position < $order_position )
				|| ( null === $where_position && null === $order_position && null !== $limit_position && $limit_position !== $position )
			) {
			return null;
		}

		$unsupported_tokens             = array(
			WP_MySQL_Lexer::COMMA_SYMBOL,
			WP_MySQL_Lexer::JOIN_SYMBOL,
			WP_MySQL_Lexer::REGEXP_SYMBOL,
			WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL,
			WP_MySQL_Lexer::USING_SYMBOL,
		);
			$unsupported_token_scan_end = $order_position ?? $limit_position ?? $statement_end;
		if ( $this->contains_top_level_mysql_token( $tokens, $position, $unsupported_token_scan_end, $unsupported_tokens ) ) {
			return null;
		}

		$where_end = $order_position ?? $limit_position ?? $statement_end;
		$where_sql = null;
		$scope     = $this->get_mysql_single_table_scope( $table_name, $alias );
		if ( null !== $where_position ) {
			if (
				$where_position + 1 >= $where_end
				|| ! $this->is_supported_simple_mysql_expression_fragment( $tokens, $where_position + 1, $where_end )
			) {
				return null;
			}

			$where     = $this->translate_mysql_predicate_token_sequence_to_postgresql(
				$tokens,
				$where_position + 1,
				$where_end,
				$scope
			);
			$where_sql = $where['sql'];
		}

		$order_sql = '';
		if ( null !== $order_position && null !== $limit_position ) {
			$order_end = $limit_position ?? $statement_end;
			$order_sql = $this->translate_simple_dml_order_by_clause_to_postgresql(
				$tokens,
				$order_position,
				$order_end,
				$table_name,
				$alias
			);
			if ( null === $order_sql ) {
				return null;
			}
		} elseif ( null !== $order_position && ! $this->is_nonempty_mysql_order_by_clause( $tokens, $order_position, $statement_end ) ) {
			return null;
		}

		$limit_sql = '';
		if ( null !== $limit_position ) {
			$limit_sql = $this->translate_simple_dml_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end, true );
			if ( null === $limit_sql ) {
				return null;
			}
		}

		$table_sql = $this->get_postgresql_dml_table_reference_sql( $table_name, $alias );
		if ( '' !== $limit_sql ) {
			$subquery_where_sql = null === $where_sql ? '' : ' WHERE ' . $where_sql;
			return sprintf(
				'DELETE FROM %s WHERE %s IN (SELECT %s FROM %s%s%s%s)',
				$table_sql,
				$this->get_postgresql_dml_ctid_reference_sql( $alias ),
				$this->get_postgresql_dml_ctid_reference_sql( $alias ),
				$table_sql,
				$subquery_where_sql,
				$order_sql,
				$limit_sql
			);
		}

		$sql = 'DELETE FROM ' . $table_sql;
		if ( null !== $where_sql ) {
			$sql .= ' WHERE ' . $where_sql;
		}

		return $sql;
	}

	/**
	 * Check whether a top-level DELETE statement reached the unsupported fallback.
	 *
	 * @param string $query MySQL query.
	 * @return bool Whether this is an unsupported DELETE statement.
	 */
	private function is_unsupported_mysql_delete_query( string $query ): bool {
		$tokens = $this->get_mysql_tokens( $query );
		return isset( $tokens[0] ) && WP_MySQL_Lexer::DELETE_SYMBOL === $tokens[0]->id;
	}

	/**
	 * Translate supported INSERT ... ON DUPLICATE KEY UPDATE queries.
	 *
	 * WordPress emits MySQL upserts for a small set of VALUES inserts. Keep this
	 * path structured and metadata-backed: explicit column-list VALUES inserts,
	 * VALUES inserts whose missing column list can be inferred from table
	 * metadata, simple INSERT ... SET assignments, and conservative INSERT ...
	 * SELECT forms are supported. The conflict target must resolve to a known
	 * primary/unique key.
	 *
	 * @param string $query MySQL query.
	 * @return array|null PostgreSQL query data, or null when the query is unsupported.
	 */
	private function translate_mysql_on_duplicate_key_update_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::INSERT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return null;
		}

		$position = 1;
		$this->consume_mysql_insert_priority_modifier( $tokens, $position );
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::IGNORE_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::INTO_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		$table_reference_start = $position;
		$table_name            = $this->parse_mysql_main_database_table_name( $tokens, $position );
		if ( null === $table_name ) {
			return null;
		}
		$table_reference_end = $position;

		$column_metadata             = null;
		$infer_columns_from_metadata = false;
		$insert_select_column_list   = false;
		$value_rows                  = null;
		$value_range_rows            = array();
		$probe_safe_rows             = array();
		$upsert_source_aliases       = array();
		$on_duplicate                = $this->find_on_duplicate_key_update_clause( $tokens, $position );
		if ( null === $on_duplicate ) {
			return null;
		}

		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id
			&& WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[ $position + 1 ]->id
		) {
			$columns                     = array();
			$infer_columns_from_metadata = true;
			$insert_select_column_list   = true;
		} elseif ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[ $position ]->id ) {
			$columns                     = array();
			$infer_columns_from_metadata = true;
			$insert_select_column_list   = true;
		} elseif ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
			$columns = $this->parse_mysql_identifier_list( $tokens, $position );
			if ( null === $columns ) {
				return null;
			}
		} elseif ( $this->is_mysql_values_row_list_keyword_token( $tokens[ $position ] ?? null ) ) {
			$columns                     = array();
			$infer_columns_from_metadata = true;
		} elseif ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::SET_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
			$set_assignments = $this->parse_simple_mysql_insert_set_assignments( $table_name, $tokens, $position, $on_duplicate );
			if ( null === $set_assignments ) {
				return null;
			}

			$columns          = $set_assignments['columns'];
			$value_rows       = array( $set_assignments['values'] );
			$value_range_rows = array( $set_assignments['ranges'] );
			$probe_safe_rows  = array( $set_assignments['probe_safe_values'] );
			$position         = $on_duplicate;
		} else {
			return null;
		}

		if ( $infer_columns_from_metadata ) {
			$column_metadata = $this->get_mysql_dml_column_metadata( $table_name );
			$columns         = $this->get_mysql_dml_column_names_from_metadata( $column_metadata );
			if ( null === $columns ) {
				return null;
			}
		}

		if (
			isset( $tokens[ $position ] )
			&& (
				WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[ $position ]->id
				|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id
			)
		) {
			return $this->translate_mysql_insert_select_on_duplicate_key_update_query(
				$table_name,
				$columns,
				$tokens,
				$position,
				$on_duplicate,
				$statement_end,
				$table_reference_start,
				$table_reference_end,
				$insert_select_column_list
			);
		}

		if ( null === $value_rows ) {
			if ( ! $this->is_mysql_values_row_list_keyword_token( $tokens[ $position ] ?? null ) ) {
				return null;
			}

			++$position;
			$value_rows = $this->parse_mysql_values_rows( $tokens, $position, $on_duplicate, count( $columns ), $probe_safe_rows, $value_range_rows );
			if ( null === $value_rows ) {
				return null;
			}

			$upsert_source_aliases = $this->parse_mysql_upsert_values_alias_clause( $tokens, $position, $on_duplicate, $columns );
			if ( null === $upsert_source_aliases ) {
				return null;
			}
		}

		if ( null === $column_metadata ) {
			$column_metadata = $this->get_mysql_dml_column_metadata( $table_name );
		}
		foreach ( $value_rows as $row_index => &$values ) {
			$value_ranges = $value_range_rows[ $row_index ] ?? array();
			$this->validate_strict_mysql_dml_values_for_columns(
				$columns,
				$value_ranges,
				$tokens,
				$column_metadata
			);
			$this->normalize_mysql_auto_increment_zero_values_for_columns(
				$columns,
				$values,
				$value_ranges,
				$tokens,
				$column_metadata
			);
			$this->normalize_strict_mysql_dml_values_for_columns(
				$columns,
				$values,
				$value_ranges,
				$tokens,
				$column_metadata
			);
			$this->normalize_non_strict_mysql_dml_values_for_columns(
				$columns,
				$values,
				$value_ranges,
				$tokens,
				$column_metadata
			);
		}
		unset( $values );

		$conflict_target = $this->get_mysql_upsert_conflict_target(
			$table_name,
			$columns,
			$value_rows,
			$probe_safe_rows
		);
		if ( null === $conflict_target ) {
			return null;
		}
		$conflict_columns = $conflict_target['columns'];
		$conflict_indexes = $this->get_mysql_upsert_conflict_indexes( $columns, $conflict_target['parts'] );
		if ( null === $conflict_indexes ) {
			return null;
		}

		$column_lookup = array();
		foreach ( $columns as $column ) {
			$column_lookup[ strtolower( $column ) ] = $column;
		}

		$table_column_lookup = $this->get_mysql_dml_column_metadata_lookup( $table_name );
		$position            = $on_duplicate + 4;

		$assignments = $this->parse_upsert_update_assignments( $table_name, $tokens, $position, $statement_end, $column_lookup, $table_column_lookup, $upsert_source_aliases );
		if ( null === $assignments || ! $this->is_at_mysql_query_end( $tokens, $position ) ) {
			return null;
		}

		$inserted_value_rows = $this->get_mysql_upsert_inserted_value_rows(
			$table_name,
			$columns,
			$value_rows,
			$probe_safe_rows,
			$conflict_target['parts']
		);
		if ( null === $inserted_value_rows ) {
			return null;
		}

		$sql_value_rows = array();
		foreach ( $value_rows as $values ) {
			$sql_value_rows[] = '(' . implode( ', ', $values ) . ')';
		}

		$column_sql   = implode( ', ', array_map( array( $this->connection, 'quote_identifier' ), $columns ) );
		$conflict_sql = sprintf(
			'ON CONFLICT (%s) DO UPDATE SET %s',
			implode( ', ', $conflict_target['sql'] ),
			implode( ', ', $assignments )
		);
		$upsert_query = array(
			'action'               => 'upsert',
			'sql'                  => sprintf(
				'INSERT INTO %s (%s) %s %s',
				$this->connection->quote_identifier( $table_name ),
				$column_sql,
				'VALUES ' . implode( ', ', $sql_value_rows ),
				$conflict_sql
			),
			'table_name'           => $table_name,
			'columns'              => $columns,
			'values'               => $inserted_value_rows[0] ?? array(),
			'value_rows'           => $inserted_value_rows,
			'insert_id_value_rows' => $value_rows,
			'conflict_columns'     => $conflict_columns,
			'conflict_indexes'     => $conflict_indexes,
			'inserted_new_row'     => count( $inserted_value_rows ) > 0,
		);

		if ( $this->has_duplicate_mysql_upsert_conflict_value_rows( $value_rows, $probe_safe_rows, $conflict_indexes ) ) {
			$statements = array();
			foreach ( $value_rows as $values ) {
				$statements[] = sprintf(
					'INSERT INTO %s (%s) VALUES (%s) %s',
					$this->connection->quote_identifier( $table_name ),
					$column_sql,
					implode( ', ', $values ),
					$conflict_sql
				);
			}
			$upsert_query['statements'] = $statements;
		}

		return $upsert_query;
	}

	/**
	 * Check whether a query is an unsupported INSERT ... ON DUPLICATE KEY UPDATE statement.
	 *
	 * @param string $query MySQL query.
	 * @return bool Whether the query contains an unsupported upsert clause.
	 */
	private function is_unsupported_mysql_on_duplicate_key_update_query( string $query ): bool {
		$tokens = $this->get_mysql_tokens( $query );
		return isset( $tokens[0] )
			&& WP_MySQL_Lexer::INSERT_SYMBOL === $tokens[0]->id
			&& null !== $this->find_on_duplicate_key_update_clause( $tokens, 1 );
	}

	/**
	 * Translate conservative INSERT ... SELECT ... ON DUPLICATE KEY UPDATE queries.
	 *
	 * SELECT-sourced upserts cannot be preflighted row-by-row without executing
	 * arbitrary SELECT sources twice. Keep AUTO_INCREMENT insert ID and identity
	 * sequence repair constrained to single literal-row SELECTs that can be
	 * checked like VALUES rows. Non-literal SELECT sources are allowed for
	 * AUTO_INCREMENT targets only when the generated column is omitted and the
	 * conflict target is a deterministic non-AUTO_INCREMENT key.
	 *
	 * @param string           $table_name            Target table name.
	 * @param string[]         $columns               Insert target columns.
	 * @param WP_MySQL_Token[] $tokens                MySQL lexer token stream.
	 * @param int              $position              Current token position at SELECT or parenthesized SELECT.
	 * @param int              $on_duplicate          ON DUPLICATE KEY UPDATE token position.
	 * @param int              $statement_end         Final statement token position, exclusive.
	 * @param int              $table_reference_start First target table-reference token.
	 * @param int              $table_reference_end   Final target table-reference token, exclusive.
	 * @param bool             $insert_column_list    Whether to inject an inferred column list.
	 * @return array|null PostgreSQL query data, or null when unsupported.
	 */
	private function translate_mysql_insert_select_on_duplicate_key_update_query(
		string $table_name,
		array $columns,
		array $tokens,
		int $position,
		int $on_duplicate,
		int $statement_end,
		int $table_reference_start,
		int $table_reference_end,
		bool $insert_column_list = false
	): ?array {
		$select_start        = $position;
		$select_end          = $on_duplicate;
		$table_reference_sql = $this->get_mysql_main_database_table_reference_sql(
			$tokens,
			$table_reference_start,
			$table_reference_end
		);
		if ( $insert_column_list ) {
			$table_reference_sql .= ' (' . implode( ', ', array_map( array( $this->connection, 'quote_identifier' ), $columns ) ) . ')';
		}
		$outer_replacements  = array(
			array(
				'start' => 0,
				'end'   => $table_reference_end,
				'sql'   => 'INSERT INTO ' . $table_reference_sql,
			),
		);
		$closing_replacement = array();

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
			$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $on_duplicate );
			if (
				null === $after_close
				|| $after_close !== $on_duplicate
				|| ! isset( $tokens[ $position + 1 ] )
				|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position + 1 ]->id
			) {
				return null;
			}

			$select_start          = $position + 1;
			$select_end            = $on_duplicate - 1;
			$outer_replacements[]  = array(
				'start' => $position,
				'end'   => $position + 1,
				'sql'   => '',
			);
			$closing_replacement[] = array(
				'start' => $on_duplicate - 1,
				'end'   => $on_duplicate,
				'sql'   => '',
			);
		}

		if ( ! isset( $tokens[ $select_start ] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $select_start ]->id ) {
			return null;
		}

		$table_column_lookup   = $this->get_mysql_dml_column_metadata_lookup( $table_name );
		$auto_increment_column = $this->get_mysql_auto_increment_column_from_metadata( $table_column_lookup );
		$literal_value_row     = null;
		$explicit_identity_columns = array();

		$conflict_target = $this->get_mysql_upsert_conflict_target( $table_name, $columns );
		if ( null === $conflict_target ) {
			$literal_value_row = $this->get_mysql_insert_select_upsert_literal_value_row(
				$table_name,
				$columns,
				$tokens,
				$select_start,
				$select_end
			);
			if ( null !== $literal_value_row ) {
				$conflict_target = $this->get_mysql_upsert_conflict_target(
					$table_name,
					$columns,
					array( $literal_value_row['values'] ),
					array( $literal_value_row['probe_safe_values'] )
				);
			}
			if ( null === $conflict_target ) {
				return null;
			}
		}
		$conflict_columns = $conflict_target['columns'];

		$column_lookup = array();
		foreach ( $columns as $column ) {
			$column_lookup[ strtolower( $column ) ] = $column;
		}

		$assignment_position = $on_duplicate + 4;
		$assignments         = $this->parse_upsert_update_assignments(
			$table_name,
			$tokens,
			$assignment_position,
			$statement_end,
			$column_lookup,
			$table_column_lookup
		);
		if ( null === $assignments || ! $this->is_at_mysql_query_end( $tokens, $assignment_position ) ) {
			return null;
		}

		$inserted_value_rows  = null;
		$insert_id_value_rows = null;
		if ( null !== $auto_increment_column ) {
			if ( null === $literal_value_row ) {
				$literal_value_row = $this->get_mysql_insert_select_upsert_literal_value_row(
					$table_name,
					$columns,
					$tokens,
					$select_start,
					$select_end
				);
			}
			if ( null === $literal_value_row ) {
				if (
					! $this->can_mysql_insert_select_upsert_skip_auto_increment_literal_probe(
						$auto_increment_column,
						$columns,
						$conflict_columns
					)
				) {
					if ( ! $this->mysql_dml_column_list_contains_column( $columns, $auto_increment_column ) ) {
						return null;
					}

					$explicit_identity_columns[ strtolower( $auto_increment_column ) ] = true;
				}
			} else {
				$insert_id_value_rows = array( $literal_value_row['insert_id_values'] );
				$inserted_value_rows  = $this->get_mysql_upsert_inserted_value_rows(
					$table_name,
					$columns,
					$insert_id_value_rows,
					array( $literal_value_row['probe_safe_values'] ),
					$conflict_target['parts']
				);
				if ( null === $inserted_value_rows ) {
					return null;
				}
			}
		}

		$replacements = $this->get_mysql_insert_select_projection_replacements(
			$table_name,
			$columns,
			$tokens,
			$select_start,
			$select_end
		);
		if ( null === $replacements ) {
			return null;
		}
		$replacements = array_merge( $outer_replacements, $replacements, $closing_replacement );

		return array(
			'action'               => 'upsert',
			'sql'                  => sprintf(
				'%s ON CONFLICT (%s) DO UPDATE SET %s',
				$this->translate_mysql_token_sequence_with_replacements_to_postgresql(
					$tokens,
					0,
					$on_duplicate,
					$replacements
				),
				implode( ', ', $conflict_target['sql'] ),
				implode( ', ', $assignments )
			),
			'table_name'           => $table_name,
			'columns'              => $columns,
			'conflict_columns'     => $conflict_columns,
			'inserted_new_row'          => null === $inserted_value_rows ? true : count( $inserted_value_rows ) > 0,
			'value_rows'                => $inserted_value_rows,
			'insert_id_value_rows'      => $insert_id_value_rows,
			'insert_id_unknown'         => ! empty( $explicit_identity_columns ),
			'explicit_identity_columns' => $explicit_identity_columns,
		);
	}

	/**
	 * Check whether a DML column list contains a column name.
	 *
	 * @param string[] $columns     DML column names.
	 * @param string   $column_name Column name to find.
	 * @return bool Whether the column list contains the column.
	 */
	private function mysql_dml_column_list_contains_column( array $columns, string $column_name ): bool {
		foreach ( $columns as $column ) {
			if ( 0 === strcasecmp( (string) $column, $column_name ) ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Check whether a non-literal INSERT ... SELECT upsert may skip AUTO_INCREMENT probing.
	 *
	 * @param string   $auto_increment_column AUTO_INCREMENT column name.
	 * @param string[] $columns               Insert target columns.
	 * @param string[] $conflict_columns      Resolved conflict target columns.
	 * @return bool Whether the generated column is outside the insert and conflict targets.
	 */
	private function can_mysql_insert_select_upsert_skip_auto_increment_literal_probe( string $auto_increment_column, array $columns, array $conflict_columns ): bool {
		$auto_increment_key = strtolower( $auto_increment_column );
		foreach ( $columns as $column ) {
			if ( strtolower( (string) $column ) === $auto_increment_key ) {
				return false;
			}
		}

		foreach ( $conflict_columns as $column ) {
			if ( strtolower( (string) $column ) === $auto_increment_key ) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Get a bounded literal row from a supported SELECT-sourced upsert.
	 *
	 * Conflict and identity decisions only consume probe-safe columns. Constant
	 * expressions in other projections may be retained as translated SQL and
	 * flagged as unsafe for probing.
	 *
	 * @param string           $table_name   Target table name.
	 * @param string[]         $columns      Target column names.
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int              $select_start SELECT token position.
	 * @param int              $select_end   Final SELECT token position, exclusive.
	 * @return array{values: string[], insert_id_values: string[], probe_safe_values: bool[]}|null Literal row data, or null when unsupported.
	 */
	private function get_mysql_insert_select_upsert_literal_value_row( string $table_name, array $columns, array $tokens, int $select_start, int $select_end ): ?array {
		$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, $select_start + 1, $select_end );
		if ( null !== $from_position ) {
			if (
				$from_position + 2 !== $select_end
				|| WP_MySQL_Lexer::DUAL_SYMBOL !== ( $tokens[ $from_position + 1 ]->id ?? null )
			) {
				return null;
			}
		}

		$projection_end    = $from_position ?? $select_end;
		$projection_ranges = $this->split_top_level_mysql_arguments( $tokens, $select_start + 1, $projection_end );
		if ( null === $projection_ranges || count( $projection_ranges ) !== count( $columns ) ) {
			return null;
		}

		$target_metadata   = $this->get_mysql_dml_column_metadata_lookup( $table_name );
		$values            = array();
		$insert_id_values  = array();
		$probe_safe_values = array();
		foreach ( $projection_ranges as $index => $range ) {
			$probe_safe                  = $this->is_supported_mysql_upsert_conflict_probe_token_sequence( $tokens, $range['start'], $range['end'] );
			$constant_expression         = false;
			$constant_integer_expression = null;
			if ( ! $probe_safe ) {
				$constant_expression = $this->is_supported_mysql_upsert_literal_select_expression( $tokens, $range['start'], $range['end'] );
				if ( ! $constant_expression ) {
					return null;
				}

				$constant_integer_expression = $this->get_mysql_constant_integer_expression_value( $tokens, $range['start'], $range['end'] );
				$probe_safe                  = true;
			}

			$column_key      = strtolower( (string) $columns[ $index ] );
			$projection_sql  = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $range['start'], $range['end'] );
			$insert_id_sql   = $projection_sql;
			$column_metadata = $target_metadata[ $column_key ] ?? null;
			if ( null !== $column_metadata ) {
				$coerced_sql = $this->get_mysql_insert_select_projection_sql_for_target_column(
					$table_name,
					$column_metadata,
					$tokens,
					$range['start'],
					$range['end'],
					$projection_sql,
					null
				);
				if ( null !== $coerced_sql ) {
					$projection_sql = $coerced_sql;
				}

				if (
					$this->is_mysql_auto_increment_column_metadata( $column_metadata )
				) {
					if ( $this->is_mysql_generated_auto_increment_value_sql( $projection_sql ) ) {
						$insert_id_sql = $projection_sql;
					} else {
						if ( null === $constant_integer_expression && $constant_expression ) {
							return null;
						}

						if ( null !== $constant_integer_expression ) {
							$insert_id_sql = $constant_integer_expression;
						}
					}
				}
			}

			$values[]            = $projection_sql;
			$insert_id_values[]  = $insert_id_sql;
			$probe_safe_values[] = $probe_safe;
		}

		return array(
			'values'            => $values,
			'insert_id_values'  => $insert_id_values,
			'probe_safe_values' => $probe_safe_values,
		);
	}

	/**
	 * Parse a bounded sequence of one or more MySQL VALUES rows.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position       Current token position, updated on success.
	 * @param int             $end            Final token position, exclusive.
	 * @param int             $expected_count Expected number of row values.
	 * @param array           $probe_safe_rows  Updated with conflict-probe safety flags.
	 * @param array           $value_range_rows Updated with original token ranges for each value.
	 * @return array[]|null Translated PostgreSQL VALUES rows, or null when unsupported.
	 */
	private function parse_mysql_values_rows( array $tokens, int &$position, int $end, int $expected_count, array &$probe_safe_rows, array &$value_range_rows ): ?array {
		$rows             = array();
		$probe_safe_rows  = array();
		$value_range_rows = array();

		while ( $position < $end ) {
			$probe_safe_values = array();
			$parsed_values     = $this->parse_mysql_value_list_with_probe_safety( $tokens, $position, $probe_safe_values );
			if ( null === $parsed_values || count( $parsed_values['values'] ) !== $expected_count ) {
				return null;
			}

			$rows[]             = $parsed_values['values'];
			$probe_safe_rows[]  = $probe_safe_values;
			$value_range_rows[] = $parsed_values['ranges'];

			if (
				$position === $end
				|| WP_MySQL_Lexer::AS_SYMBOL === ( $tokens[ $position ]->id ?? null )
			) {
				return $rows;
			}

			if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::COMMA_SYMBOL !== $tokens[ $position ]->id ) {
				return null;
			}

			++$position;
		}

		return count( $rows ) > 0 ? $rows : null;
	}

	/**
	 * Parse an optional MySQL VALUES-row alias for ON DUPLICATE KEY UPDATE.
	 *
	 * MySQL 8 accepts "VALUES (...) AS row_alias" and optional column aliases.
	 * The alias is only meaningful inside the update expressions, where it maps
	 * back to the inserted row represented by PostgreSQL's excluded pseudo-table.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Current token position, updated on success.
	 * @param int             $end      ON DUPLICATE token position.
	 * @param string[]        $columns  Insert target columns in value order.
	 * @return array{row: string, qualified: array<string,string>, unqualified: array<string,string>}|array{}|null Alias map, empty when no alias is present, or null when malformed.
	 */
	private function parse_mysql_upsert_values_alias_clause( array $tokens, int &$position, int $end, array $columns ): ?array {
		if ( $position === $end ) {
			return array();
		}

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::AS_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		$row_alias = $this->get_mysql_dml_identifier_token_value( $tokens[ $position + 1 ] ?? null );
		if ( null === $row_alias ) {
			return null;
		}

		$position += 2;

		$qualified = array();
		foreach ( $columns as $column ) {
			$qualified[ strtolower( $column ) ] = $column;
		}

		$unqualified = array();
		if ( $position < $end && WP_MySQL_Lexer::OPEN_PAR_SYMBOL === ( $tokens[ $position ]->id ?? null ) ) {
			$column_aliases = $this->parse_mysql_identifier_list( $tokens, $position );
			if ( null === $column_aliases || count( $column_aliases ) !== count( $columns ) ) {
				return null;
			}

			$seen_aliases = array();
			foreach ( $column_aliases as $index => $column_alias ) {
				$alias_key = strtolower( $column_alias );
				if ( isset( $seen_aliases[ $alias_key ] ) ) {
					return null;
				}

				$seen_aliases[ $alias_key ] = true;
				$qualified[ $alias_key ]    = $columns[ $index ];
				$unqualified[ $alias_key ]  = $columns[ $index ];
			}
		}

		if ( $position !== $end ) {
			return null;
		}

		return array(
			'row'         => strtolower( $row_alias ),
			'qualified'   => $qualified,
			'unqualified' => $unqualified,
		);
	}

	/**
	 * Parse a parenthesized single-row MySQL VALUES list with probe safety.
	 *
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int             $position     Current token position, updated on success.
	 * @param bool[]          $probe_safety Updated with per-value conflict-probe safety.
	 * @return array{values: string[], ranges: array[]}|null Translated SQL values and token ranges, or null when unsupported.
	 */
	private function parse_mysql_value_list_with_probe_safety( array $tokens, int &$position, array &$probe_safety ): ?array {
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		++$position;
		$values       = array();
		$ranges       = array();
		$probe_safety = array();
		$value_start  = $position;
		$depth        = 0;

		while ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::EOF !== $tokens[ $position ]->id ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
				++$depth;
				++$position;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $position ]->id ) {
				if ( 0 === $depth ) {
					if ( $value_start === $position ) {
						return null;
					}

					$values[]       = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $value_start, $position );
					$ranges[]       = array(
						'start' => $value_start,
						'end'   => $position,
					);
					$probe_safety[] = $this->is_supported_mysql_upsert_conflict_probe_token_sequence( $tokens, $value_start, $position );
					++$position;
					return array(
						'values' => $values,
						'ranges' => $ranges,
					);
				}

				--$depth;
				++$position;
				continue;
			}

			if ( 0 === $depth && WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id ) {
				if ( $value_start === $position ) {
					return null;
				}

				$values[]       = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $value_start, $position );
				$ranges[]       = array(
					'start' => $value_start,
					'end'   => $position,
				);
				$probe_safety[] = $this->is_supported_mysql_upsert_conflict_probe_token_sequence( $tokens, $value_start, $position );
				$value_start    = $position + 1;
			}

			++$position;
		}

		return null;
	}

	/**
	 * Check whether a VALUES item is safe for a conflict preflight probe.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First value token position, inclusive.
	 * @param int             $end    Final value token position, exclusive.
	 * @return bool Whether the value is a deterministic literal.
	 */
	private function is_supported_mysql_upsert_conflict_probe_token_sequence( array $tokens, int $start, int $end ): bool {
		if ( $start + 1 !== $end || ! isset( $tokens[ $start ] ) ) {
			return false;
		}

		return in_array(
			$tokens[ $start ]->id,
			array(
				WP_MySQL_Lexer::BIN_NUMBER,
				WP_MySQL_Lexer::DECIMAL_NUMBER,
				WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT,
				WP_MySQL_Lexer::FALSE_SYMBOL,
				WP_MySQL_Lexer::FLOAT_NUMBER,
				WP_MySQL_Lexer::HEX_NUMBER,
				WP_MySQL_Lexer::INT_NUMBER,
				WP_MySQL_Lexer::LONG_NUMBER,
				WP_MySQL_Lexer::NULL_SYMBOL,
				WP_MySQL_Lexer::SINGLE_QUOTED_TEXT,
				WP_MySQL_Lexer::TRUE_SYMBOL,
				WP_MySQL_Lexer::ULONGLONG_NUMBER,
			),
			true
		);
	}

	/**
	 * Check whether a SELECT-sourced upsert projection is a bounded constant expression.
	 *
	 * These expressions may be translated into the final INSERT ... SELECT, but
	 * they are not safe for conflict preflight probes.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First value token position, inclusive.
	 * @param int             $end    Final value token position, exclusive.
	 * @return bool Whether the expression is a supported constant expression.
	 */
	private function is_supported_mysql_upsert_literal_select_expression( array $tokens, int $start, int $end ): bool {
		if ( $start >= $end ) {
			return false;
		}

		for ( $position = $start; $position < $end; $position++ ) {
			if (
				null !== $this->get_mysql_identifier_token_value( $tokens[ $position ] )
				|| in_array( $tokens[ $position ]->id, array( WP_MySQL_Lexer::COMMA_SYMBOL, WP_MySQL_Lexer::DOT_SYMBOL ), true )
			) {
				return false;
			}

			if ( ! $this->is_supported_simple_mysql_expression_token( $tokens[ $position ] ) ) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Resolve the PostgreSQL upsert conflict target from MySQL index metadata.
	 *
	 * @param string   $table_name      Table name.
	 * @param string[] $columns         Inserted column names.
	 * @param array[]  $value_rows      Optional translated VALUES rows for ambiguous target probing.
	 * @param array[]  $probe_safe_rows Optional per-value conflict-probe safety flags.
	 * @return array{columns: string[], parts: array<int,array{column: string, sub_part: string|null}>, sql: string[]}|null Conflict target, or null when unsupported.
	 */
	private function get_mysql_upsert_conflict_target(
		string $table_name,
		array $columns,
		?array $value_rows = null,
		?array $probe_safe_rows = null
	): ?array {
		$insert_column_lookup = array();
		$insert_columns       = array();
		foreach ( $columns as $column ) {
			$insert_column = strtolower( $column );

			$insert_column_lookup[ $insert_column ] = true;
			$insert_columns[]                       = $insert_column;
		}
		sort( $insert_columns, SORT_STRING );

		$this->ensure_mysql_schema_metadata_tables();

		$table_schema = $this->resolve_mysql_table_schema_for_introspection( 'public', $table_name );
		$cache_key    = $this->get_mysql_metadata_cache_key( $table_schema, $table_name ) . "\0" . serialize( $insert_columns );
		if ( array_key_exists( $cache_key, $this->mysql_upsert_conflict_target_cache ) ) {
			$cached = $this->mysql_upsert_conflict_target_cache[ $cache_key ];
			return null === $cached ? null : $cached;
		}

		$stmt = $this->connection->query(
			sprintf(
				'SELECT key_name, column_name, index_type, sub_part
				FROM %s
				WHERE table_schema = ? AND table_name = ? AND non_unique = \'0\'
				ORDER BY
					CASE WHEN UPPER(key_name) = \'PRIMARY\' THEN 0 ELSE 1 END,
					index_ordinal,
					seq_in_index',
				$this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE )
			),
			array( $table_schema, $table_name )
		);

		$indexes = array();
		foreach ( $stmt->fetchAll( PDO::FETCH_ASSOC ) as $row ) {
			$key_name = (string) ( $row['key_name'] ?? '' );
			if ( '' === $key_name ) {
				continue;
			}

			if ( ! isset( $indexes[ $key_name ] ) ) {
				$indexes[ $key_name ] = array(
					'columns'    => array(),
					'index_type' => strtoupper( (string) ( $row['index_type'] ?? 'BTREE' ) ),
					'parts'      => array(),
				);
			}

			$column_name = (string) ( $row['column_name'] ?? '' );
			if ( '' === $column_name ) {
				continue;
			}

			$indexes[ $key_name ]['columns'][] = $column_name;
			$indexes[ $key_name ]['parts'][]   = array(
				'column'   => $column_name,
				'sub_part' => null !== ( $row['sub_part'] ?? null ) && '' !== (string) $row['sub_part'] ? (string) $row['sub_part'] : null,
			);
		}

		$candidates = array();
		foreach ( $indexes as $index ) {
			if ( empty( $index['columns'] ) ) {
				continue;
			}

			if ( in_array( $index['index_type'], array( 'FULLTEXT', 'SPATIAL' ), true ) ) {
				continue;
			}

			foreach ( $index['columns'] as $column ) {
				if ( ! isset( $insert_column_lookup[ strtolower( $column ) ] ) ) {
					continue 2;
				}
			}

			$candidates[] = array(
				'columns' => $index['columns'],
				'parts'   => $index['parts'],
			);
		}

		if ( 1 !== count( $candidates ) ) {
			if ( null !== $value_rows && null !== $probe_safe_rows && count( $candidates ) > 1 ) {
				return $this->get_mysql_upsert_conflict_target_for_value_rows(
					$table_name,
					$columns,
					$candidates,
					$value_rows,
					$probe_safe_rows
				);
			}

			return null;
		}

		$conflict_target = $this->get_mysql_upsert_conflict_target_from_candidate( $candidates[0] );

		$this->mysql_upsert_conflict_target_cache[ $cache_key ] = $conflict_target;
		return $conflict_target;
	}

	/**
	 * Resolve an ambiguous upsert conflict target from deterministic VALUES rows.
	 *
	 * @param string   $table_name      Table name.
	 * @param string[] $columns         Inserted column names.
	 * @param array[]  $candidates      Candidate unique-key targets.
	 * @param array[]  $value_rows      Translated PostgreSQL VALUES rows.
	 * @param array[]  $probe_safe_rows Per-value conflict-probe safety flags.
	 * @return array{columns: string[], parts: array<int,array{column: string, sub_part: string|null}>, sql: string[]}|null Conflict target, or null when unsupported.
	 */
	private function get_mysql_upsert_conflict_target_for_value_rows(
		string $table_name,
		array $columns,
		array $candidates,
		array $value_rows,
		array $probe_safe_rows
	): ?array {
		$conflicting_candidates = array();

		foreach ( $candidates as $candidate ) {
			$conflict_indexes = $this->get_mysql_upsert_conflict_indexes( $columns, $candidate['parts'] );
			if ( null === $conflict_indexes ) {
				return null;
			}

			$candidate_conflicts = false;
			foreach ( $value_rows as $row_index => $values ) {
				$probe_safety = $probe_safe_rows[ $row_index ] ?? array();
				foreach ( $conflict_indexes as $conflict_index ) {
					if ( ! isset( $probe_safety[ $conflict_index['index'] ] ) || ! $probe_safety[ $conflict_index['index'] ] ) {
						return null;
					}
				}

				$conflict_exists = $this->mysql_upsert_conflict_exists( $table_name, $values, $conflict_indexes );
				if ( null === $conflict_exists ) {
					return null;
				}

				if ( $conflict_exists ) {
					$candidate_conflicts = true;
				}
			}

			if ( $candidate_conflicts ) {
				$conflicting_candidates[] = $candidate;
			}
		}

		if ( 1 === count( $conflicting_candidates ) ) {
			return $this->get_mysql_upsert_conflict_target_from_candidate( $conflicting_candidates[0] );
		}

		if ( 0 === count( $conflicting_candidates ) ) {
			return $this->get_mysql_upsert_conflict_target_from_candidate( $candidates[0] );
		}

		return null;
	}

	/**
	 * Build a normalized conflict target from a unique-key candidate.
	 *
	 * @param array{columns: string[], parts: array<int,array{column: string, sub_part: string|null}>} $candidate Unique-key candidate.
	 * @return array{columns: string[], parts: array<int,array{column: string, sub_part: string|null}>, sql: string[]} Conflict target.
	 */
	private function get_mysql_upsert_conflict_target_from_candidate( array $candidate ): array {
		$conflict_target = array(
			'columns' => array_values( $candidate['columns'] ),
			'parts'   => array_values( $candidate['parts'] ),
			'sql'     => array(),
		);
		foreach ( $conflict_target['parts'] as $part ) {
			$conflict_target['sql'][] = $this->get_mysql_index_key_part_sql( $part['column'], $part['sub_part'] );
		}

		return $conflict_target;
	}

	/**
	 * Get the VALUES rows that will insert rather than update on conflict.
	 *
	 * @param string   $table_name       Table name.
	 * @param string[] $columns          Inserted column names.
	 * @param array[]  $value_rows       Translated PostgreSQL VALUES rows.
	 * @param array[]  $probe_safe_rows  Per-value conflict-probe safety flags.
	 * @param array[]  $conflict_parts   Conflict target key parts.
	 * @return array[]|null Inserted VALUES rows, or null when unsupported.
	 */
	private function get_mysql_upsert_inserted_value_rows( string $table_name, array $columns, array $value_rows, array $probe_safe_rows, array $conflict_parts ): ?array {
		$conflict_indexes = $this->get_mysql_upsert_conflict_indexes( $columns, $conflict_parts );
		if ( null === $conflict_indexes ) {
			return null;
		}

		$inserted_rows = array();
		foreach ( $value_rows as $row_index => $values ) {
			$probe_safety = $probe_safe_rows[ $row_index ] ?? array();
			foreach ( $conflict_indexes as $conflict_index ) {
				if ( ! isset( $probe_safety[ $conflict_index['index'] ] ) || ! $probe_safety[ $conflict_index['index'] ] ) {
					return null;
				}
			}

			$conflict_exists = $this->mysql_upsert_conflict_exists( $table_name, $values, $conflict_indexes );
			if ( null === $conflict_exists ) {
				return null;
			}

			if ( $conflict_exists ) {
				continue;
			}

			$inserted_rows[] = $values;
		}

		return $inserted_rows;
	}

	/**
	 * Resolve conflict key parts to value indexes in an INSERT column list.
	 *
	 * @param string[] $columns        Inserted column names.
	 * @param array[]  $conflict_parts Conflict target key parts.
	 * @return array<int,array{column: string, index: int, sub_part: mixed}>|null Conflict indexes, or null when unsupported.
	 */
	private function get_mysql_upsert_conflict_indexes( array $columns, array $conflict_parts ): ?array {
		$column_indexes = array();
		foreach ( $columns as $index => $column ) {
			$column_indexes[ strtolower( $column ) ] = $index;
		}

		$conflict_indexes = array();
		foreach ( $conflict_parts as $part ) {
			$column     = (string) ( $part['column'] ?? '' );
			$column_key = strtolower( $column );
			if ( ! isset( $column_indexes[ $column_key ] ) ) {
				return null;
			}

			$conflict_indexes[] = array(
				'column'   => $column,
				'index'    => $column_indexes[ $column_key ],
				'sub_part' => $part['sub_part'] ?? null,
			);
		}

		return $conflict_indexes;
	}

	/**
	 * Check whether a VALUES row conflicts with the selected upsert target.
	 *
	 * @param string $table_name       Table name.
	 * @param array  $values           Translated PostgreSQL VALUES row.
	 * @param array  $conflict_indexes Conflict target column/index tuples.
	 * @return bool|null Whether the row currently conflicts, or null when unsupported.
	 */
	private function mysql_upsert_conflict_exists( string $table_name, array $values, array $conflict_indexes ): ?bool {
		$where = array();
		foreach ( $conflict_indexes as $conflict_index ) {
			if ( ! array_key_exists( $conflict_index['index'], $values ) ) {
				return null;
			}

			$value = (string) $values[ $conflict_index['index'] ];
			if ( $this->is_mysql_generated_auto_increment_value_sql( $value ) ) {
				return false;
			}

			if ( null !== ( $conflict_index['sub_part'] ?? null ) && '' !== (string) $conflict_index['sub_part'] ) {
				$where[] = sprintf(
					'%s = SUBSTR(CAST(%s AS text), 1, %d)',
					$this->get_mysql_index_key_part_sql( (string) $conflict_index['column'], $conflict_index['sub_part'] ),
					$value,
					(int) $conflict_index['sub_part']
				);
			} else {
				$where[] = sprintf(
					'%s = %s',
					$this->connection->quote_identifier( (string) $conflict_index['column'] ),
					$value
				);
			}
		}

		$stmt = $this->connection->query(
			sprintf(
				'SELECT 1 FROM %s WHERE %s LIMIT 1',
				$this->connection->quote_identifier( $table_name ),
				implode( ' AND ', $where )
			)
		);

		return false !== $stmt->fetchColumn();
	}

	/**
	 * Check whether an upsert batch contains duplicate deterministic conflict rows.
	 *
	 * PostgreSQL cannot update the same row twice in one INSERT ... ON CONFLICT
	 * statement. MySQL applies VALUES rows sequentially, so duplicate conflict
	 * keys need one PostgreSQL statement per input row.
	 *
	 * @param array[] $value_rows       Translated VALUES rows.
	 * @param array[] $probe_safe_rows  Per-value probe safety.
	 * @param array   $conflict_indexes Conflict target column/index tuples.
	 * @return bool Whether PostgreSQL needs per-row statements.
	 */
	private function has_duplicate_mysql_upsert_conflict_value_rows( array $value_rows, array $probe_safe_rows, array $conflict_indexes ): bool {
		return $this->has_duplicate_mysql_replace_conflict_value_rows( $value_rows, $probe_safe_rows, $conflict_indexes );
	}

	/**
	 * Translate simple MySQL REPLACE statements to PostgreSQL.
	 *
	 * WordPress' wpdb::replace() emits VALUES rows with an explicit column list.
	 * Columnless VALUES rows are supported when stored MySQL metadata can infer
	 * the target columns. LOW_PRIORITY and DELAYED are accepted as compatibility
	 * no-ops. For rows with a known WordPress unique key, use PostgreSQL's ON
	 * CONFLICT update path and synthesize MySQL's affected-row count in query().
	 * Without a known conflict column, fall back to a plain INSERT so PostgreSQL
	 * still reports normal constraint and length errors.
	 *
	 * @param string $query MySQL query.
	 * @return array|null PostgreSQL query data, or null when the query is unsupported.
	 */
	private function translate_simple_mysql_replace_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::REPLACE_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$position = 1;
		$this->consume_mysql_replace_priority_modifier( $tokens, $position );
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::INTO_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		$table_reference_start = $position;
		$table_name            = $this->parse_mysql_main_database_table_name( $tokens, $position );
		if ( null === $table_name ) {
			return null;
		}
		$table_reference_end = $position;

		$column_metadata    = null;
		$insert_column_list = false;
		$value_rows         = null;
		$value_range_rows   = array();
		$probe_safe_rows    = array();
		$statement_end      = null;
		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id
			&& WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[ $position + 1 ]->id
		) {
			$column_metadata    = $this->get_mysql_dml_column_metadata( $table_name );
			$columns            = $this->get_mysql_dml_column_names_from_metadata( $column_metadata );
			$insert_column_list = true;
			if ( null === $columns ) {
				return null;
			}
		} elseif ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
			$columns = $this->parse_mysql_identifier_list( $tokens, $position );
			if ( null === $columns ) {
				return null;
			}
		} elseif ( $this->is_mysql_values_row_list_keyword_token( $tokens[ $position ] ?? null ) ) {
			$column_metadata = $this->get_mysql_dml_column_metadata( $table_name );
			$columns         = $this->get_mysql_dml_column_names_from_metadata( $column_metadata );
			if ( null === $columns ) {
				return null;
			}
		} elseif ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[ $position ]->id ) {
			$column_metadata    = $this->get_mysql_dml_column_metadata( $table_name );
			$columns            = $this->get_mysql_dml_column_names_from_metadata( $column_metadata );
			$insert_column_list = true;
			if ( null === $columns ) {
				return null;
			}
		} elseif ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::SET_SYMBOL === $tokens[ $position ]->id ) {
			$statement_end = $this->get_mysql_statement_end_position( $tokens, $position );
			if ( null === $statement_end ) {
				return null;
			}

			++$position;
			$set_assignments = $this->parse_simple_mysql_insert_set_assignments( $table_name, $tokens, $position, $statement_end );
			if ( null === $set_assignments ) {
				return null;
			}

			$columns          = $set_assignments['columns'];
			$value_rows       = array( $set_assignments['values'] );
			$value_range_rows = array( $set_assignments['ranges'] );
			$probe_safe_rows  = array( $set_assignments['probe_safe_values'] );
			$position         = $statement_end;
		} else {
			return null;
		}

		if (
			isset( $tokens[ $position ] )
			&& (
				WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[ $position ]->id
				|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id
			)
		) {
			return $this->translate_simple_mysql_replace_select_query(
				$query,
				$table_name,
				$columns,
				$tokens,
				$position,
				$table_reference_start,
				$table_reference_end,
				$insert_column_list
			);
		}

		if ( null === $value_rows ) {
			if ( ! $this->is_mysql_values_row_list_keyword_token( $tokens[ $position ] ?? null ) ) {
				return null;
			}

			++$position;
			$statement_end = $this->get_mysql_statement_end_position( $tokens, $position );
			if ( null === $statement_end ) {
				return null;
			}

			$value_rows = $this->parse_mysql_values_rows( $tokens, $position, $statement_end, count( $columns ), $probe_safe_rows, $value_range_rows );
			if ( null === $value_rows || ! $this->is_at_mysql_query_end( $tokens, $position ) ) {
				return null;
			}
		}

		if ( null === $column_metadata ) {
			$column_metadata = $this->get_mysql_dml_column_metadata( $table_name );
		}
		foreach ( $value_rows as $row_index => &$values ) {
			$value_ranges = $value_range_rows[ $row_index ] ?? array();
			$this->validate_strict_mysql_dml_values_for_columns(
				$columns,
				$value_ranges,
				$tokens,
				$column_metadata
			);
			$this->normalize_mysql_auto_increment_zero_values_for_columns(
				$columns,
				$values,
				$value_ranges,
				$tokens,
				$column_metadata
			);
			$this->normalize_strict_mysql_dml_values_for_columns(
				$columns,
				$values,
				$value_ranges,
				$tokens,
				$column_metadata
			);
			$this->normalize_non_strict_mysql_dml_values_for_columns(
				$columns,
				$values,
				$value_ranges,
				$tokens,
				$column_metadata
			);
		}
		unset( $values );
		$this->append_non_strict_dml_defaults_for_omitted_value_rows( $table_name, $columns, $value_rows, $column_metadata );

		$value_sql_rows = array();
		foreach ( $value_rows as $values ) {
			$value_sql_rows[] = '(' . implode( ', ', $values ) . ')';
		}

		$sql = sprintf(
			'INSERT INTO %s (%s) VALUES %s',
			$this->connection->quote_identifier( $table_name ),
			implode( ', ', array_map( array( $this->connection, 'quote_identifier' ), $columns ) ),
			implode( ', ', $value_sql_rows )
		);

		$conflict_target = $this->get_mysql_replace_conflict_target(
			$table_name,
			$columns,
			$value_rows,
			$probe_safe_rows
		);
		$delete_conflict_index_groups = $this->get_mysql_replace_delete_conflict_index_groups(
			$table_name,
			$columns,
			$value_rows,
			$probe_safe_rows
		);
		if ( null === $conflict_target ) {
			if ( ! empty( $delete_conflict_index_groups ) ) {
				$delete_insert_statements = $this->get_mysql_replace_delete_then_insert_statements(
					$table_name,
					$columns,
					$value_rows,
					$probe_safe_rows,
					$delete_conflict_index_groups,
					$this->has_duplicate_mysql_replace_conflict_value_rows_in_groups( $value_rows, $probe_safe_rows, $delete_conflict_index_groups )
				);
				if ( null !== $delete_insert_statements ) {
					return array(
						'action'                   => 'replace',
						'sql'                      => $sql,
						'statements'               => $delete_insert_statements,
						'table_name'               => $table_name,
						'columns'                  => $columns,
						'value_rows'               => $value_rows,
						'conflict_column'          => null,
						'conflict_probe_safe_rows' => $probe_safe_rows,
						'delete_then_insert'       => true,
						'inserted_new_row'         => true,
					);
				}
			}

			return array(
				'action'           => 'replace',
				'sql'              => $sql,
				'table_name'       => $table_name,
				'columns'          => $columns,
				'value_rows'       => $value_rows,
				'conflict_column'  => null,
				'conflict_value'   => null,
				'inserted_new_row' => true,
			);
		}

		$conflict_indexes = $this->get_mysql_upsert_conflict_indexes( $columns, $conflict_target['parts'] );
		if ( null === $conflict_indexes ) {
			return null;
		}
		if ( empty( $delete_conflict_index_groups ) ) {
			$delete_conflict_index_groups = array( $conflict_indexes );
		}

		$assignments = array();
		foreach ( $columns as $column ) {
			$assignments[] = sprintf(
				'%s = excluded.%s',
				$this->connection->quote_identifier( $column ),
				$this->connection->quote_identifier( $column )
			);
		}

		$conflict_sql  = sprintf(
			'ON CONFLICT (%s) DO UPDATE SET %s',
			implode( ', ', $conflict_target['sql'] ),
			implode( ', ', $assignments )
		);
		$conflict_column = $conflict_target['columns'][0] ?? null;
		$replace_query = array(
			'action'                   => 'replace',
			'sql'                      => $sql . ' ' . $conflict_sql,
			'table_name'               => $table_name,
			'columns'                  => $columns,
			'value_rows'               => $value_rows,
			'conflict_column'          => $conflict_column,
			'conflict_target'          => $conflict_target,
			'conflict_indexes'         => $conflict_indexes,
			'conflict_probe_safe_rows' => $probe_safe_rows,
			'inserted_new_row'         => true,
		);

		$has_duplicate_conflict_rows = $this->has_duplicate_mysql_replace_conflict_value_rows_in_groups( $value_rows, $probe_safe_rows, $delete_conflict_index_groups );
		$delete_insert_statements    = $this->get_mysql_replace_delete_then_insert_statements(
			$table_name,
			$columns,
			$value_rows,
			$probe_safe_rows,
			$delete_conflict_index_groups,
			$has_duplicate_conflict_rows
		);
		if ( null !== $delete_insert_statements ) {
			$replace_query['statements']          = $delete_insert_statements;
			$replace_query['delete_then_insert']  = true;
			$replace_query['inserted_new_row']    = true;
		} elseif ( $has_duplicate_conflict_rows ) {
			$statements = array();
			foreach ( $value_rows as $values ) {
				$statements[] = sprintf(
					'INSERT INTO %s (%s) VALUES (%s) %s',
					$this->connection->quote_identifier( $table_name ),
					implode( ', ', array_map( array( $this->connection, 'quote_identifier' ), $columns ) ),
					implode( ', ', $values ),
					$conflict_sql
				);
			}
			$replace_query['statements'] = $statements;
		}

		return $replace_query;
	}

	/**
	 * Build delete-then-insert statements for deterministic REPLACE rows.
	 *
	 * MySQL and SQLite REPLACE delete matching rows before inserting the new
	 * row, which makes DELETE triggers, cascades, and omitted-column defaults
	 * observable. Limit this emulation to conflict keys whose incoming values
	 * are safe to evaluate in both the DELETE predicate and INSERT row.
	 *
	 * @param string   $table_name           Table name.
	 * @param string[] $columns              Inserted column names.
	 * @param array[]  $value_rows           Translated VALUES rows.
	 * @param array[]  $probe_safe_rows      Per-value conflict-probe safety flags.
	 * @param array[]  $conflict_index_groups Conflict target column/index tuple groups.
	 * @param bool     $sequential_statements Whether every row must run as its own DELETE/INSERT pair.
	 * @return string[]|null PostgreSQL statements, or null when delete-then-insert is unsafe.
	 */
	private function get_mysql_replace_delete_then_insert_statements( string $table_name, array $columns, array $value_rows, array $probe_safe_rows, array $conflict_index_groups, bool $sequential_statements ): ?array {
		$quoted_table = $this->connection->quote_identifier( $table_name );
		$column_sql   = implode( ', ', array_map( array( $this->connection, 'quote_identifier' ), $columns ) );

		$row_predicates = array();
		foreach ( $value_rows as $row_index => $values ) {
			$predicate = $this->get_mysql_replace_delete_predicate_for_row(
				$values,
				$probe_safe_rows[ $row_index ] ?? array(),
				$conflict_index_groups
			);
			if ( false === $predicate ) {
				return null;
			}

			$row_predicates[ $row_index ] = $predicate;
		}

		$statements = array();
		if ( $sequential_statements ) {
			foreach ( $value_rows as $row_index => $values ) {
				if ( null !== $row_predicates[ $row_index ] ) {
					$statements[] = sprintf(
						'DELETE FROM %s WHERE %s',
						$quoted_table,
						$row_predicates[ $row_index ]
					);
				}

				$statements[] = sprintf(
					'INSERT INTO %s (%s) VALUES (%s)',
					$quoted_table,
					$column_sql,
					implode( ', ', $values )
				);
			}

			return $statements;
		}

		$delete_predicates = array_values(
			array_filter(
				$row_predicates,
				static function ( $predicate ): bool {
					return null !== $predicate;
				}
			)
		);
		if ( ! empty( $delete_predicates ) ) {
			$statements[] = sprintf(
				'DELETE FROM %s WHERE %s',
				$quoted_table,
				implode(
					' OR ',
					array_map(
						static function ( string $predicate ): string {
							return '(' . $predicate . ')';
						},
						$delete_predicates
					)
				)
			);
		}

		$sql_value_rows = array();
		foreach ( $value_rows as $values ) {
			$sql_value_rows[] = '(' . implode( ', ', $values ) . ')';
		}

		$statements[] = sprintf(
			'INSERT INTO %s (%s) VALUES %s',
			$quoted_table,
			$column_sql,
			implode( ', ', $sql_value_rows )
		);

		return $statements;
	}

	/**
	 * Build a DELETE predicate for one deterministic REPLACE row.
	 *
	 * @param array   $values                Translated VALUES row.
	 * @param array   $probe_safety          Per-value conflict-probe safety flags.
	 * @param array[] $conflict_index_groups Conflict target column/index tuple groups.
	 * @return string|false|null Predicate SQL, false when unsafe, or null when the row cannot conflict.
	 */
	private function get_mysql_replace_delete_predicate_for_row( array $values, array $probe_safety, array $conflict_index_groups ) {
		$predicates = array();
		foreach ( $conflict_index_groups as $conflict_indexes ) {
			$predicate = $this->get_mysql_replace_delete_predicate_for_row_conflict_indexes(
				$values,
				$probe_safety,
				$conflict_indexes
			);
			if ( false === $predicate ) {
				return false;
			}

			if ( null !== $predicate ) {
				$predicates[] = $predicate;
			}
		}

		if ( empty( $predicates ) ) {
			return null;
		}

		if ( 1 === count( $predicates ) ) {
			return $predicates[0];
		}

		return implode(
			' OR ',
			array_map(
				static function ( string $predicate ): string {
					return '(' . $predicate . ')';
				},
				$predicates
			)
		);
	}

	/**
	 * Build a DELETE predicate for one deterministic REPLACE row and one conflict key.
	 *
	 * @param array $values           Translated VALUES row.
	 * @param array $probe_safety     Per-value conflict-probe safety flags.
	 * @param array $conflict_indexes Conflict target column/index tuples.
	 * @return string|false|null Predicate SQL, false when unsafe, or null when the row cannot conflict.
	 */
	private function get_mysql_replace_delete_predicate_for_row_conflict_indexes( array $values, array $probe_safety, array $conflict_indexes ) {
		$where = array();
		foreach ( $conflict_indexes as $conflict_index ) {
			if (
				! array_key_exists( $conflict_index['index'], $values )
				|| ! isset( $probe_safety[ $conflict_index['index'] ] )
				|| ! $probe_safety[ $conflict_index['index'] ]
			) {
				return false;
			}

			$value = trim( (string) $values[ $conflict_index['index'] ] );
			if (
				'' === $value
				|| 'NULL' === strtoupper( $value )
				|| $this->is_mysql_generated_auto_increment_value_sql( $value )
			) {
				return null;
			}

			if ( null !== ( $conflict_index['sub_part'] ?? null ) && '' !== (string) $conflict_index['sub_part'] ) {
				$where[] = sprintf(
					'%s = SUBSTR(CAST(%s AS text), 1, %d)',
					$this->get_mysql_index_key_part_sql( (string) $conflict_index['column'], $conflict_index['sub_part'] ),
					$value,
					(int) $conflict_index['sub_part']
				);
			} else {
				$where[] = sprintf(
					'%s = %s',
					$this->connection->quote_identifier( (string) $conflict_index['column'] ),
					$value
				);
			}
		}

		return empty( $where ) ? null : implode( ' AND ', $where );
	}

	/**
	 * Get metadata-backed unique-key groups usable for deterministic REPLACE deletes.
	 *
	 * @param string  $table_name      Table name.
	 * @param array   $columns         Inserted column names.
	 * @param array[] $value_rows      Translated VALUES rows.
	 * @param array[] $probe_safe_rows Per-value conflict-probe safety flags.
	 * @return array[] Conflict index groups.
	 */
	private function get_mysql_replace_delete_conflict_index_groups( string $table_name, array $columns, array $value_rows, array $probe_safe_rows ): array {
		$this->ensure_mysql_schema_metadata_tables();

		$table_schema = $this->resolve_mysql_table_schema_for_introspection( 'public', $table_name );
		$stmt         = $this->connection->query(
			sprintf(
				'SELECT key_name, column_name, index_type, sub_part
				FROM %s
				WHERE table_schema = ? AND table_name = ? AND non_unique = \'0\'
				ORDER BY
					CASE WHEN UPPER(key_name) = \'PRIMARY\' THEN 0 ELSE 1 END,
					index_ordinal,
					seq_in_index',
				$this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE )
			),
			array( $table_schema, $table_name )
		);

		$indexes = array();
		foreach ( $stmt->fetchAll( PDO::FETCH_ASSOC ) as $row ) {
			$key_name = (string) ( $row['key_name'] ?? '' );
			if ( '' === $key_name ) {
				continue;
			}

			if ( ! isset( $indexes[ $key_name ] ) ) {
				$indexes[ $key_name ] = array(
					'index_type' => strtoupper( (string) ( $row['index_type'] ?? 'BTREE' ) ),
					'parts'      => array(),
				);
			}

			$column_name = (string) ( $row['column_name'] ?? '' );
			if ( '' === $column_name ) {
				continue;
			}

			$indexes[ $key_name ]['parts'][] = array(
				'column'   => $column_name,
				'sub_part' => null !== ( $row['sub_part'] ?? null ) && '' !== (string) $row['sub_part'] ? (string) $row['sub_part'] : null,
			);
		}

		$conflict_index_groups = array();
		foreach ( $indexes as $index ) {
			if ( empty( $index['parts'] ) || in_array( $index['index_type'], array( 'FULLTEXT', 'SPATIAL' ), true ) ) {
				continue;
			}

			$conflict_indexes = $this->get_mysql_upsert_conflict_indexes( $columns, $index['parts'] );
			if ( null === $conflict_indexes ) {
				continue;
			}

			if ( ! $this->mysql_replace_conflict_indexes_are_probe_safe_for_rows( $conflict_indexes, $value_rows, $probe_safe_rows ) ) {
				continue;
			}

			$conflict_index_groups[] = $conflict_indexes;
		}

		return $conflict_index_groups;
	}

	/**
	 * Check whether every incoming row can safely probe one conflict key.
	 *
	 * @param array   $conflict_indexes Conflict target column/index tuples.
	 * @param array[] $value_rows       Translated VALUES rows.
	 * @param array[] $probe_safe_rows  Per-value conflict-probe safety flags.
	 * @return bool Whether the conflict key is safe for all rows.
	 */
	private function mysql_replace_conflict_indexes_are_probe_safe_for_rows( array $conflict_indexes, array $value_rows, array $probe_safe_rows ): bool {
		foreach ( $value_rows as $row_index => $values ) {
			$probe_safety = $probe_safe_rows[ $row_index ] ?? array();
			foreach ( $conflict_indexes as $conflict_index ) {
				if (
					! array_key_exists( $conflict_index['index'], $values )
					|| ! isset( $probe_safety[ $conflict_index['index'] ] )
					|| ! $probe_safety[ $conflict_index['index'] ]
				) {
					return false;
				}
			}
		}

		return true;
	}

	/**
	 * Translate explicit-column MySQL REPLACE ... SELECT statements.
	 *
	 * @param string           $query                 MySQL query.
	 * @param string           $table_name            Target table name.
	 * @param string[]         $columns               Target column names.
	 * @param WP_MySQL_Token[] $tokens                MySQL lexer token stream.
	 * @param int              $position              Current token position at SELECT or parenthesized SELECT.
	 * @param int              $table_reference_start First target table-reference token.
	 * @param int              $table_reference_end   Final target table-reference token, exclusive.
	 * @param bool             $insert_column_list    Whether to inject an inferred column list.
	 * @return array|null PostgreSQL query data, or null when unsupported.
	 */
	private function translate_simple_mysql_replace_select_query(
		string $query,
		string $table_name,
		array $columns,
		array $tokens,
		int $position,
		int $table_reference_start,
		int $table_reference_end,
		bool $insert_column_list = false
	): ?array {
		$statement_end = $this->get_mysql_statement_end_position( $tokens, $position );
		if ( null === $statement_end || ! $this->is_at_mysql_query_end( $tokens, $statement_end ) ) {
			return null;
		}

		$select_columns  = $columns;
		$default_columns = $this->get_non_strict_dml_defaults_for_omitted_columns( $table_name, $columns );
		foreach ( $default_columns as $default_column ) {
			$columns[] = $default_column['column'];
		}

		$table_reference_sql = $this->get_mysql_main_database_table_reference_sql(
			$tokens,
			$table_reference_start,
			$table_reference_end
		);
		if ( $insert_column_list || ! empty( $default_columns ) ) {
			$table_reference_sql .= ' (' . implode( ', ', array_map( array( $this->connection, 'quote_identifier' ), $columns ) ) . ')';
		}
		$select_start        = $position;
		$select_end          = $statement_end;
		$outer_replacements  = array(
			array(
				'start' => 0,
				'end'   => ! empty( $default_columns ) ? $position : $table_reference_end,
				'sql'   => 'INSERT INTO ' . $table_reference_sql,
			),
		);
		$closing_replacement = array();

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
			$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $statement_end );
			if (
				null === $after_close
				|| $after_close !== $statement_end
				|| ! isset( $tokens[ $position + 1 ] )
				|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position + 1 ]->id
			) {
				return null;
			}

			$select_start          = $position + 1;
			$select_end            = $statement_end - 1;
			$outer_replacements[]  = array(
				'start' => $position,
				'end'   => $position + 1,
				'sql'   => '',
			);
			$closing_replacement[] = array(
				'start' => $statement_end - 1,
				'end'   => $statement_end,
				'sql'   => '',
			);
		}

		if ( ! isset( $tokens[ $select_start ] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $select_start ]->id ) {
			return null;
		}

		$select_replacements = $this->get_mysql_insert_select_projection_replacements(
			$table_name,
			$select_columns,
			$tokens,
			$select_start,
			$select_end
		);
		if ( null === $select_replacements ) {
			return null;
		}

		$direct_information_schema_select_sql = $this->get_insert_select_direct_information_schema_select_sql(
			$query,
			$tokens,
			$select_start,
			$select_end
		);
		if ( null !== $direct_information_schema_select_sql ) {
			if ( $this->mysql_replacements_overlap_range( $select_replacements, $select_start, $select_end ) ) {
				return null;
			}

			$select_replacements[] = array(
				'start' => $select_start,
				'end'   => $select_end,
				'sql'   => $direct_information_schema_select_sql,
			);
		} elseif ( $this->mysql_select_range_requires_direct_information_schema_rewrite( $tokens, $select_start, $select_end ) ) {
			return null;
		}

		if ( ! empty( $default_columns ) ) {
			usort(
				$select_replacements,
				static function ( array $left, array $right ): int {
					return $left['start'] <=> $right['start'];
				}
			);

			$select_sql          = $this->translate_mysql_token_sequence_with_replacements_to_postgresql(
				$tokens,
				$select_start,
				$select_end,
				$select_replacements
			);
			$select_replacements = array(
				array(
					'start' => $select_start,
					'end'   => $select_end,
					'sql'   => $this->append_mysql_select_default_projection_sql(
						$select_sql,
						$default_columns,
						'__wp_pg_replace_source'
					),
				),
			);
		}

		$replacements = array_merge( $outer_replacements, $select_replacements, $closing_replacement );
		usort(
			$replacements,
			static function ( array $left, array $right ): int {
				return $left['start'] <=> $right['start'];
			}
		);

		$sql = $this->translate_mysql_token_sequence_with_replacements_to_postgresql(
			$tokens,
			0,
			$statement_end,
			$replacements
		);

		$replace_select_value_rows      = null;
		$replace_select_probe_safe_rows = null;
		$replace_select_literal_row     = $this->get_mysql_insert_select_upsert_literal_value_row(
			$table_name,
			$select_columns,
			$tokens,
			$select_start,
			$select_end
		);
		if ( null !== $replace_select_literal_row && empty( $default_columns ) ) {
			$replace_select_value_rows      = array( $replace_select_literal_row['values'] );
			$replace_select_probe_safe_rows = array( $replace_select_literal_row['probe_safe_values'] );
		}

		$conflict_target         = $this->get_mysql_replace_conflict_target(
			$table_name,
			$columns,
			$replace_select_value_rows,
			$replace_select_probe_safe_rows
		);
		$conflict_column         = null;
		$affected_rows_count_sql = null;
		if ( null !== $conflict_target ) {
			$conflict_column = $conflict_target['columns'][0] ?? null;
			$replace_select_flow = $this->get_mysql_replace_select_delete_then_insert_flow(
				$table_name,
				$columns,
				$select_columns,
				$default_columns,
				$conflict_target,
				$tokens,
				$select_start,
				$select_end
			);
			if ( null === $replace_select_flow ) {
				return null;
			}

			$sql                     = $replace_select_flow['sql'];
			$affected_rows_count_sql = $replace_select_flow['replace_select_affected_rows_sql'];
		}

		$replace_query = array(
			'action'                           => 'replace',
			'sql'                              => $sql,
			'table_name'                       => $table_name,
			'columns'                          => $columns,
			'conflict_column'                  => $conflict_column,
			'conflict_target'                  => $conflict_target,
			'conflict_value'                   => null,
			'replace_select_affected_rows_sql' => $affected_rows_count_sql,
			'inserted_new_row'                 => true,
		);

		if ( null !== $conflict_target ) {
			$replace_query = array_merge( $replace_query, $replace_select_flow );
		}

		return $replace_query;
	}

	/**
	 * Build a materialized delete-then-insert flow for REPLACE ... SELECT.
	 *
	 * @param string           $table_name      Target table name.
	 * @param string[]         $columns         Target column names.
	 * @param string[]         $select_columns  Original SELECT target column names.
	 * @param array[]          $default_columns Metadata-derived default projections.
	 * @param array            $conflict_target Conflict target.
	 * @param WP_MySQL_Token[] $tokens          MySQL lexer token stream.
	 * @param int              $select_start    SELECT token position.
	 * @param int              $select_end      Final SELECT token position, exclusive.
	 * @return array|null Materialized flow metadata, or null when unsupported.
	 */
	private function get_mysql_replace_select_delete_then_insert_flow( string $table_name, array $columns, array $select_columns, array $default_columns, array $conflict_target, array $tokens, int $select_start, int $select_end ): ?array {
		$conflict_indexes = $this->get_mysql_upsert_conflict_indexes( $columns, $conflict_target['parts'] ?? array() );
		if ( null === $conflict_indexes ) {
			return null;
		}
		$conflict_index_groups = $this->get_mysql_replace_select_delete_conflict_index_groups( $table_name, $columns );
		if ( empty( $conflict_index_groups ) ) {
			$conflict_index_groups = array( $conflict_indexes );
		}

		$select_sql = $this->get_mysql_replace_select_source_sql(
			$table_name,
			$select_columns,
			$default_columns,
			$tokens,
			$select_start,
			$select_end
		);
		if ( null === $select_sql ) {
			return null;
		}

		$temp_table_hash      = substr( md5( $table_name . "\0" . $select_start . "\0" . $select_end . "\0" . implode( "\0", $columns ) ), 0, 12 );
		$temp_table_name      = '__wp_pg_replace_select_' . $temp_table_hash;
		$ordinal_table_name   = '__wp_pg_replace_select_ord_' . $temp_table_hash;
		$quoted_temp_table    = $this->connection->quote_identifier( $temp_table_name );
		$quoted_ordinal_table = $this->connection->quote_identifier( $ordinal_table_name );
		$rows_alias           = $this->connection->quote_identifier( '__wp_pg_replace_rows' );
		$target_alias         = $this->connection->quote_identifier( '__wp_pg_replace_target' );
		$quoted_target_table  = $this->connection->quote_identifier( $table_name );
		$delete_predicate_sql = $this->get_mysql_replace_select_delete_predicate_sql(
			$target_alias,
			$rows_alias,
			$conflict_index_groups
		);
		if ( null === $delete_predicate_sql ) {
			return null;
		}

		$insert_projection_sql = array();
		foreach ( $columns as $column ) {
			$insert_projection_sql[] = sprintf(
				'%s.%s',
				$rows_alias,
				$this->connection->quote_identifier( $column )
			);
		}

		$affected_rows_count_sql = $this->get_mysql_replace_select_affected_rows_count_sql(
			$table_name,
			$columns,
			$select_columns,
			$default_columns,
			$conflict_target,
			$tokens,
			$select_start,
			$select_end,
			$quoted_temp_table,
			$conflict_index_groups
		);
		if ( null === $affected_rows_count_sql ) {
			return null;
		}

		$duplicate_conflict_rows_sql = $this->get_mysql_replace_select_duplicate_conflict_rows_sql(
			$quoted_temp_table,
			$rows_alias,
			$conflict_index_groups
		);
		if ( null === $duplicate_conflict_rows_sql ) {
			return null;
		}

		$delete_sql = sprintf(
			'DELETE FROM %s AS %s WHERE EXISTS (SELECT 1 FROM %s AS %s WHERE %s)',
			$quoted_target_table,
			$target_alias,
			$quoted_temp_table,
			$rows_alias,
			$delete_predicate_sql
		);
		$insert_sql = sprintf(
			'INSERT INTO %s (%s) SELECT %s FROM %s AS %s',
			$quoted_target_table,
			implode( ', ', array_map( array( $this->connection, 'quote_identifier' ), $columns ) ),
			implode( ', ', $insert_projection_sql ),
			$quoted_temp_table,
			$rows_alias
		);
		$drop_sql   = sprintf( 'DROP TABLE IF EXISTS %s', $quoted_temp_table );

		return array(
			'sql'                              => $insert_sql,
			'statements'                       => array(
				$drop_sql,
				sprintf( 'CREATE TEMPORARY TABLE %s AS %s', $quoted_temp_table, $select_sql ),
				$delete_sql,
				$insert_sql,
				$drop_sql,
			),
			'materialize_statements'           => array(
				$drop_sql,
				sprintf( 'CREATE TEMPORARY TABLE %s AS %s', $quoted_temp_table, $select_sql ),
			),
			'mutation_statements'              => array(
				$delete_sql,
				$insert_sql,
			),
			'cleanup_statements'               => array(
				$drop_sql,
			),
			'replace_select_materialized'      => true,
			'replace_select_affected_rows_sql' => $affected_rows_count_sql,
			'duplicate_conflict_rows_sql'      => $duplicate_conflict_rows_sql,
			'source_table_sql'                 => $quoted_temp_table,
			'ordinal_source_table_sql'         => $quoted_ordinal_table,
			'conflict_indexes'                 => $conflict_indexes,
			'conflict_index_groups'            => $conflict_index_groups,
		);
	}

	/**
	 * Get metadata-backed unique-key groups usable for materialized REPLACE ... SELECT deletes.
	 *
	 * @param string   $table_name Table name.
	 * @param string[] $columns    Inserted column names.
	 * @return array[] Conflict index groups.
	 */
	private function get_mysql_replace_select_delete_conflict_index_groups( string $table_name, array $columns ): array {
		$this->ensure_mysql_schema_metadata_tables();

		$table_schema = $this->resolve_mysql_table_schema_for_introspection( 'public', $table_name );
		$stmt         = $this->connection->query(
			sprintf(
				'SELECT key_name, column_name, index_type, sub_part
				FROM %s
				WHERE table_schema = ? AND table_name = ? AND non_unique = \'0\'
				ORDER BY
					CASE WHEN UPPER(key_name) = \'PRIMARY\' THEN 0 ELSE 1 END,
					index_ordinal,
					seq_in_index',
				$this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE )
			),
			array( $table_schema, $table_name )
		);

		$indexes = array();
		foreach ( $stmt->fetchAll( PDO::FETCH_ASSOC ) as $row ) {
			$key_name = (string) ( $row['key_name'] ?? '' );
			if ( '' === $key_name ) {
				continue;
			}

			if ( ! isset( $indexes[ $key_name ] ) ) {
				$indexes[ $key_name ] = array(
					'index_type' => strtoupper( (string) ( $row['index_type'] ?? 'BTREE' ) ),
					'parts'      => array(),
				);
			}

			$column_name = (string) ( $row['column_name'] ?? '' );
			if ( '' === $column_name ) {
				continue;
			}

			$indexes[ $key_name ]['parts'][] = array(
				'column'   => $column_name,
				'sub_part' => null !== ( $row['sub_part'] ?? null ) && '' !== (string) $row['sub_part'] ? (string) $row['sub_part'] : null,
			);
		}

		$conflict_index_groups = array();
		foreach ( $indexes as $index ) {
			if ( empty( $index['parts'] ) || in_array( $index['index_type'], array( 'FULLTEXT', 'SPATIAL' ), true ) ) {
				continue;
			}

			$conflict_indexes = $this->get_mysql_upsert_conflict_indexes( $columns, $index['parts'] );
			if ( null !== $conflict_indexes ) {
				$conflict_index_groups[] = $conflict_indexes;
			}
		}

		return $conflict_index_groups;
	}

	/**
	 * Get a projected source SELECT for REPLACE ... SELECT materialization.
	 *
	 * @param string           $table_name      Target table name.
	 * @param string[]         $select_columns  Original SELECT target column names.
	 * @param array[]          $default_columns Metadata-derived default projections.
	 * @param WP_MySQL_Token[] $tokens          MySQL lexer token stream.
	 * @param int              $select_start    SELECT token position.
	 * @param int              $select_end      Final SELECT token position, exclusive.
	 * @return string|null PostgreSQL SELECT SQL, or null when unsupported.
	 */
	private function get_mysql_replace_select_source_sql( string $table_name, array $select_columns, array $default_columns, array $tokens, int $select_start, int $select_end ): ?string {
		if ( $this->mysql_select_range_requires_direct_information_schema_rewrite( $tokens, $select_start, $select_end ) ) {
			return null;
		}

		$from_position     = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, $select_start + 1, $select_end );
		$projection_end    = $from_position ?? $select_end;
		$projection_ranges = $this->split_top_level_mysql_arguments( $tokens, $select_start + 1, $projection_end );
		if ( null === $projection_ranges || count( $projection_ranges ) !== count( $select_columns ) ) {
			return null;
		}

		$target_metadata = $this->get_mysql_dml_column_metadata_lookup( $table_name );
		$scope           = null;
		if ( null !== $from_position ) {
			$first_clause_position = $this->find_first_top_level_mysql_token(
				$tokens,
				array(
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::GROUP_SYMBOL,
					WP_MySQL_Lexer::HAVING_SYMBOL,
					WP_MySQL_Lexer::LIMIT_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::ORDER_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
					WP_MySQL_Lexer::WHERE_SYMBOL,
				),
				$from_position + 1,
				$select_end
			) ?? $select_end;
			$scope                 = $this->get_mysql_select_scope( $tokens, $from_position + 1, $first_clause_position );
		}

		$alias_replacements = array();
		foreach ( $projection_ranges as $index => $range ) {
			$expression_bounds = $this->get_mysql_select_projection_expression_bounds( $tokens, $range['start'], $range['end'] );
			if ( null === $expression_bounds ) {
				return null;
			}

			$expression_start = $expression_bounds['start'];
			$expression_end   = $expression_bounds['end'];
			$projection_sql   = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $expression_start, $expression_end );
			$column_metadata  = $target_metadata[ strtolower( $select_columns[ $index ] ) ] ?? null;
			if ( null !== $column_metadata ) {
				$coerced_sql = $this->get_mysql_insert_select_projection_sql_for_target_column(
					$table_name,
					$column_metadata,
					$tokens,
					$expression_start,
					$expression_end,
					$projection_sql,
					$scope
				);
				if ( null !== $coerced_sql ) {
					$projection_sql = $coerced_sql;
				}
			}

			$alias_replacements[] = array(
				'start' => $range['start'],
				'end'   => $range['end'],
				'sql'   => $projection_sql . ' AS ' . $this->connection->quote_identifier( $select_columns[ $index ] ),
			);
		}

		$select_sql = $this->translate_mysql_token_sequence_with_replacements_to_postgresql(
			$tokens,
			$select_start,
			$select_end,
			$alias_replacements
		);
		if ( ! empty( $default_columns ) ) {
			$select_sql = $this->append_mysql_select_default_projection_sql(
				$select_sql,
				$default_columns,
				'__wp_pg_replace_rows_source'
			);
		}

		return $select_sql;
	}

	/**
	 * Get a preflight affected-row count query for REPLACE ... SELECT.
	 *
	 * @param string           $table_name      Target table name.
	 * @param string[]         $columns         Target column names.
	 * @param string[]         $select_columns  Original SELECT target column names.
	 * @param array[]          $default_columns Metadata-derived default projections.
	 * @param array            $conflict_target Conflict target.
	 * @param WP_MySQL_Token[] $tokens          MySQL lexer token stream.
	 * @param int              $select_start    SELECT token position.
	 * @param int              $select_end      Final SELECT token position, exclusive.
	 * @param string|null      $source_table_sql Optional materialized source table SQL.
	 * @param array[]|null     $conflict_index_groups Optional conflict index groups.
	 * @return string|null PostgreSQL count SQL, or null when unsupported.
	 */
	private function get_mysql_replace_select_affected_rows_count_sql( string $table_name, array $columns, array $select_columns, array $default_columns, array $conflict_target, array $tokens, int $select_start, int $select_end, ?string $source_table_sql = null, ?array $conflict_index_groups = null ): ?string {
		$conflict_indexes = $this->get_mysql_upsert_conflict_indexes( $columns, $conflict_target['parts'] ?? array() );
		if ( null === $conflict_indexes ) {
			return null;
		}
		if ( null === $conflict_index_groups ) {
			$conflict_index_groups = array( $conflict_indexes );
		}

		$select_sql = null;
		if ( null === $source_table_sql ) {
			$select_sql = $this->get_mysql_replace_select_source_sql(
				$table_name,
				$select_columns,
				$default_columns,
				$tokens,
				$select_start,
				$select_end
			);
			if ( null === $select_sql ) {
				return null;
			}
		}

		$rows_alias      = $this->connection->quote_identifier( '__wp_pg_replace_rows' );
		if ( null !== $source_table_sql ) {
			$target_alias         = $this->connection->quote_identifier( '__wp_pg_replace_target' );
			$delete_predicate_sql = $this->get_mysql_replace_select_delete_predicate_sql(
				$target_alias,
				$rows_alias,
				$conflict_index_groups
			);
			if ( null === $delete_predicate_sql ) {
				return null;
			}

			return sprintf(
				'SELECT ((SELECT COUNT(*) FROM %1$s) + (SELECT COUNT(*) FROM %2$s AS %3$s WHERE EXISTS (SELECT 1 FROM %1$s AS %4$s WHERE %5$s))) AS affected_rows, (SELECT COUNT(*) FROM %1$s) AS inserted_rows',
				$source_table_sql,
				$this->connection->quote_identifier( $table_name ),
				$target_alias,
				$rows_alias,
				$delete_predicate_sql
			);
		}

		$conflict_exists = $this->get_mysql_replace_select_conflict_exists_sql(
			$table_name,
			$rows_alias,
			$conflict_index_groups
		);
		if ( null === $conflict_exists ) {
			return null;
		}

		return sprintf(
			'SELECT COALESCE(SUM(CASE WHEN %1$s THEN 2 ELSE 1 END), 0) AS affected_rows, COALESCE(SUM(CASE WHEN %1$s THEN 0 ELSE 1 END), 0) AS inserted_rows FROM (%2$s) AS %3$s',
			$conflict_exists,
			null === $source_table_sql ? $select_sql : 'SELECT * FROM ' . $source_table_sql,
			$rows_alias
		);
	}

	/**
	 * Append constant default projections to a translated SELECT.
	 *
	 * @param string  $select_sql       Translated SELECT SQL.
	 * @param array[] $default_columns  Default column descriptors.
	 * @param string  $source_alias     Unquoted derived-table alias.
	 * @return string SELECT SQL with appended default projections.
	 */
	private function append_mysql_select_default_projection_sql( string $select_sql, array $default_columns, string $source_alias ): string {
		$quoted_source_alias = $this->connection->quote_identifier( $source_alias );
		$projection_sql      = array(
			$quoted_source_alias . '.*',
		);

		foreach ( $default_columns as $default_column ) {
			$projection_sql[] = sprintf(
				'%s AS %s',
				$default_column['sql'],
				$this->connection->quote_identifier( $default_column['column'] )
			);
		}

		return sprintf(
			'SELECT %s FROM (%s) AS %s WHERE 1 = 1',
			implode( ', ', $projection_sql ),
			$select_sql,
			$quoted_source_alias
		);
	}

	/**
	 * Get a REPLACE ... SELECT preflight conflict predicate.
	 *
	 * @param string $table_name       Target table name.
	 * @param string $rows_alias       Quoted derived-table alias for incoming rows.
	 * @param array  $conflict_index_groups Conflict target column/index tuple groups.
	 * @return string|null EXISTS predicate SQL, or null when unsupported.
	 */
	private function get_mysql_replace_select_conflict_exists_sql( string $table_name, string $rows_alias, array $conflict_index_groups ): ?string {
		$group_predicates = array();
		foreach ( $conflict_index_groups as $conflict_indexes ) {
			$where = array();
			foreach ( $conflict_indexes as $conflict_index ) {
				$column = (string) ( $conflict_index['column'] ?? '' );
				if ( '' === $column ) {
					return null;
				}

				$incoming_value = sprintf(
					'%s.%s',
					$rows_alias,
					$this->connection->quote_identifier( $column )
				);
				if ( null !== ( $conflict_index['sub_part'] ?? null ) && '' !== (string) $conflict_index['sub_part'] ) {
					$incoming_value = sprintf(
						'SUBSTR(CAST(%s AS text), 1, %d)',
						$incoming_value,
						(int) $conflict_index['sub_part']
					);
				}

				$where[] = sprintf(
					'%s = %s',
					$this->get_mysql_index_key_part_sql( $column, $conflict_index['sub_part'] ?? null ),
					$incoming_value
				);
			}

			if ( empty( $where ) ) {
				return null;
			}

			$group_predicates[] = '(' . implode( ' AND ', $where ) . ')';
		}

		if ( empty( $group_predicates ) ) {
			return null;
		}

		return sprintf(
			'EXISTS (SELECT 1 FROM %s WHERE %s)',
			$this->connection->quote_identifier( $table_name ),
			implode( ' OR ', $group_predicates )
		);
	}

	/**
	 * Get a materialized REPLACE ... SELECT target/source conflict predicate.
	 *
	 * @param string $target_alias     Quoted target table alias.
	 * @param string $rows_alias       Quoted materialized rows alias.
	 * @param array  $conflict_index_groups Conflict target column/index tuple groups.
	 * @return string|null Predicate SQL, or null when unsupported.
	 */
	private function get_mysql_replace_select_delete_predicate_sql( string $target_alias, string $rows_alias, array $conflict_index_groups ): ?string {
		$group_predicates = array();
		foreach ( $conflict_index_groups as $conflict_indexes ) {
			$where = array();
			foreach ( $conflict_indexes as $conflict_index ) {
				$column = (string) ( $conflict_index['column'] ?? '' );
				if ( '' === $column ) {
					return null;
				}

				$target_value = sprintf(
					'%s.%s',
					$target_alias,
					$this->connection->quote_identifier( $column )
				);
				$incoming_value = sprintf(
					'%s.%s',
					$rows_alias,
					$this->connection->quote_identifier( $column )
				);
				if ( null !== ( $conflict_index['sub_part'] ?? null ) && '' !== (string) $conflict_index['sub_part'] ) {
					$target_value = sprintf(
						'SUBSTR(CAST(%s AS text), 1, %d)',
						$target_value,
						(int) $conflict_index['sub_part']
					);
					$incoming_value = sprintf(
						'SUBSTR(CAST(%s AS text), 1, %d)',
						$incoming_value,
						(int) $conflict_index['sub_part']
					);
				}

				$where[] = sprintf(
					'%s = %s',
					$target_value,
					$incoming_value
				);
			}

			if ( empty( $where ) ) {
				return null;
			}

			$group_predicates[] = '(' . implode( ' AND ', $where ) . ')';
		}

		return empty( $group_predicates ) ? null : implode( ' OR ', $group_predicates );
	}

	/**
	 * Get a duplicate incoming conflict-key probe for materialized REPLACE ... SELECT.
	 *
	 * @param string $source_table_sql Quoted materialized source table SQL.
	 * @param string $rows_alias       Quoted materialized rows alias.
	 * @param array  $conflict_index_groups Conflict target column/index tuple groups.
	 * @return string|null Probe SQL, or null when unsupported.
	 */
	private function get_mysql_replace_select_duplicate_conflict_rows_sql( string $source_table_sql, string $rows_alias, array $conflict_index_groups ): ?string {
		$probes = array();
		foreach ( $conflict_index_groups as $conflict_indexes ) {
			$key_sql      = array();
			$not_null_sql = array();
			foreach ( $conflict_indexes as $conflict_index ) {
				$column = (string) ( $conflict_index['column'] ?? '' );
				if ( '' === $column ) {
					return null;
				}

				$incoming_column = sprintf(
					'%s.%s',
					$rows_alias,
					$this->connection->quote_identifier( $column )
				);
				$not_null_sql[]  = $incoming_column . ' IS NOT NULL';
				if ( null !== ( $conflict_index['sub_part'] ?? null ) && '' !== (string) $conflict_index['sub_part'] ) {
					$key_sql[] = sprintf(
						'SUBSTR(CAST(%s AS text), 1, %d)',
						$incoming_column,
						(int) $conflict_index['sub_part']
					);
				} else {
					$key_sql[] = $incoming_column;
				}
			}

			if ( empty( $key_sql ) ) {
				return null;
			}

			$probes[] = sprintf(
				'SELECT 1 FROM %s AS %s WHERE %s GROUP BY %s HAVING COUNT(*) > 1',
				$source_table_sql,
				$rows_alias,
				implode( ' AND ', $not_null_sql ),
				implode( ', ', $key_sql )
			);
		}

		return empty( $probes ) ? null : implode( ' UNION ALL ', $probes ) . ' LIMIT 1';
	}

	/**
	 * Get the MySQL-compatible affected-row count for a translated REPLACE query.
	 *
	 * @param array $replace_query Translated REPLACE query data.
	 * @return int|null MySQL-compatible row count, or null when the backend row count should be used.
	 */
	private function get_mysql_replace_return_value( array &$replace_query ): ?int {
		if (
			! isset( $replace_query['table_name'], $replace_query['conflict_column'] )
			|| null === $replace_query['conflict_column']
		) {
			return null;
		}

		if ( ! empty( $replace_query['delete_then_insert'] ) ) {
			return null;
		}

		if ( isset( $replace_query['replace_select_affected_rows_sql'] ) && is_string( $replace_query['replace_select_affected_rows_sql'] ) ) {
			$stmt = $this->connection->query( $replace_query['replace_select_affected_rows_sql'] );
			$row  = $stmt->fetch( PDO::FETCH_ASSOC );
			if ( ! is_array( $row ) || ! isset( $row['affected_rows'] ) ) {
				return null;
			}

			$replace_query['inserted_new_row'] = isset( $row['inserted_rows'] ) && (int) $row['inserted_rows'] > 0;
			return (int) $row['affected_rows'];
		}

		if (
			! isset( $replace_query['value_rows'], $replace_query['conflict_indexes'] )
			|| ! is_array( $replace_query['value_rows'] )
			|| ! is_array( $replace_query['conflict_indexes'] )
		) {
			return null;
		}

		$probe_safe_rows = isset( $replace_query['conflict_probe_safe_rows'] ) && is_array( $replace_query['conflict_probe_safe_rows'] )
			? $replace_query['conflict_probe_safe_rows']
			: array();

		$return_value     = 0;
		$inserted_new_row = false;
		$seen_values      = array();
		foreach ( $replace_query['value_rows'] as $row_index => $values ) {
			if ( ! is_array( $values ) ) {
				return null;
			}

			$probe_safety = $probe_safe_rows[ $row_index ] ?? array();
			foreach ( $replace_query['conflict_indexes'] as $conflict_index ) {
				if ( ! isset( $probe_safety[ $conflict_index['index'] ] ) || ! $probe_safety[ $conflict_index['index'] ] ) {
					return null;
				}
			}

			$seen_key                = $this->get_mysql_replace_conflict_seen_key_for_row( $values, $replace_query['conflict_indexes'] );
			$replace_conflict_exists = null !== $seen_key && isset( $seen_values[ $seen_key ] );
			if ( ! $replace_conflict_exists ) {
				$replace_conflict_exists = $this->mysql_upsert_conflict_exists(
					(string) $replace_query['table_name'],
					$values,
					$replace_query['conflict_indexes']
				);
				if ( null === $replace_conflict_exists ) {
					return null;
				}
			}

			$return_value += $replace_conflict_exists ? 2 : 1;
			if ( ! $replace_conflict_exists ) {
				$inserted_new_row = true;
			}
			if ( null !== $seen_key ) {
				$seen_values[ $seen_key ] = true;
			}
		}

		$replace_query['inserted_new_row'] = ! empty( $replace_query['delete_then_insert'] ) ? true : $inserted_new_row;
		return $return_value;
	}

	/**
	 * Resolve the conflict target for a REPLACE statement.
	 *
	 * @param string       $table_name      Table name.
	 * @param string[]     $columns         Inserted column names.
	 * @param array[]|null $value_rows      Optional translated VALUES rows.
	 * @param array[]|null $probe_safe_rows Optional per-value conflict-probe safety flags.
	 * @return array{columns: string[], parts: array<int,array{column: string, sub_part: string|null}>, sql: string[]}|null Conflict target.
	 */
	private function get_mysql_replace_conflict_target( string $table_name, array $columns, ?array $value_rows = null, ?array $probe_safe_rows = null ): ?array {
		$metadata_target = $this->get_mysql_upsert_conflict_target( $table_name, $columns, $value_rows, $probe_safe_rows );
		$heuristic_target = $this->get_simple_replace_conflict_target( $table_name, $columns );
		if ( null === $heuristic_target ) {
			return $metadata_target;
		}

		if ( null === $metadata_target ) {
			return $heuristic_target;
		}

		if (
			$this->is_mysql_replace_conflict_target_backed_by_unique_metadata( $table_name, $heuristic_target )
			&&
			null !== $value_rows
			&& null !== $probe_safe_rows
			&& ! $this->mysql_replace_conflict_target_has_existing_conflict(
				$table_name,
				$columns,
				$value_rows,
				$probe_safe_rows,
				$metadata_target
			)
		) {
			return $heuristic_target;
		}

		return $metadata_target;
	}

	/**
	 * Check whether a REPLACE conflict target corresponds to MySQL unique metadata.
	 *
	 * @param string $table_name      Table name.
	 * @param array  $conflict_target Conflict target.
	 * @return bool Whether the target has a matching unique metadata entry.
	 */
	private function is_mysql_replace_conflict_target_backed_by_unique_metadata( string $table_name, array $conflict_target ): bool {
		$target_parts = $conflict_target['parts'] ?? array();
		if ( empty( $target_parts ) ) {
			return false;
		}

		$this->ensure_mysql_schema_metadata_tables();
		$table_schema = $this->resolve_mysql_table_schema_for_introspection( 'public', $table_name );
		$stmt         = $this->connection->query(
			sprintf(
				'SELECT key_name, column_name, index_type, sub_part
				FROM %s
				WHERE table_schema = ? AND table_name = ? AND non_unique = \'0\'
				ORDER BY
					key_name,
					index_ordinal,
					seq_in_index',
				$this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE )
			),
			array( $table_schema, $table_name )
		);

		$indexes = array();
		foreach ( $stmt->fetchAll( PDO::FETCH_ASSOC ) as $row ) {
			$key_name = (string) ( $row['key_name'] ?? '' );
			if ( '' === $key_name ) {
				continue;
			}

			if ( ! isset( $indexes[ $key_name ] ) ) {
				$indexes[ $key_name ] = array(
					'index_type' => strtoupper( (string) ( $row['index_type'] ?? 'BTREE' ) ),
					'parts'      => array(),
				);
			}

			$indexes[ $key_name ]['parts'][] = array(
				'column'   => (string) ( $row['column_name'] ?? '' ),
				'sub_part' => null !== ( $row['sub_part'] ?? null ) && '' !== (string) $row['sub_part'] ? (string) $row['sub_part'] : null,
			);
		}

		foreach ( $indexes as $index ) {
			if ( in_array( $index['index_type'], array( 'FULLTEXT', 'SPATIAL' ), true ) ) {
				continue;
			}

			if ( count( $index['parts'] ) !== count( $target_parts ) ) {
				continue;
			}

			foreach ( $target_parts as $part_index => $part ) {
				$index_part = $index['parts'][ $part_index ];
				if (
					0 !== strcasecmp( (string) ( $index_part['column'] ?? '' ), (string) ( $part['column'] ?? '' ) )
					|| (string) ( $index_part['sub_part'] ?? '' ) !== (string) ( $part['sub_part'] ?? '' )
				) {
					continue 2;
				}
			}

			return true;
		}

		return false;
	}

	/**
	 * Build a one-column fallback REPLACE conflict target.
	 *
	 * @param string   $table_name Table name.
	 * @param string[] $columns    Inserted column names.
	 * @return array{columns: string[], parts: array<int,array{column: string, sub_part: string|null}>, sql: string[]}|null Conflict target.
	 */
	private function get_simple_replace_conflict_target( string $table_name, array $columns ): ?array {
		$conflict_column = $this->get_simple_replace_conflict_column( $table_name, $columns );
		if ( null === $conflict_column ) {
			return null;
		}

		return array(
			'columns' => array( $conflict_column ),
			'parts'   => array(
				array(
					'column'   => $conflict_column,
					'sub_part' => null,
				),
			),
			'sql'     => array( $this->connection->quote_identifier( $conflict_column ) ),
		);
	}

	/**
	 * Check whether a resolved metadata conflict target currently matches any incoming row.
	 *
	 * @param string   $table_name      Table name.
	 * @param string[] $columns         Inserted column names.
	 * @param array[]  $value_rows      Translated VALUES rows.
	 * @param array[]  $probe_safe_rows Per-value conflict-probe safety flags.
	 * @param array    $conflict_target Conflict target.
	 * @return bool Whether an existing row matches the target.
	 */
	private function mysql_replace_conflict_target_has_existing_conflict( string $table_name, array $columns, array $value_rows, array $probe_safe_rows, array $conflict_target ): bool {
		$conflict_indexes = $this->get_mysql_upsert_conflict_indexes( $columns, $conflict_target['parts'] ?? array() );
		if ( null === $conflict_indexes ) {
			return true;
		}

		foreach ( $value_rows as $row_index => $values ) {
			$probe_safety = $probe_safe_rows[ $row_index ] ?? array();
			foreach ( $conflict_indexes as $conflict_index ) {
				if ( ! isset( $probe_safety[ $conflict_index['index'] ] ) || ! $probe_safety[ $conflict_index['index'] ] ) {
					return true;
				}
			}

			$conflict_exists = $this->mysql_upsert_conflict_exists( $table_name, $values, $conflict_indexes );
			if ( null === $conflict_exists || $conflict_exists ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Check whether a REPLACE batch contains duplicate deterministic conflict rows.
	 *
	 * @param array[] $value_rows       Translated VALUES rows.
	 * @param array[] $probe_safe_rows  Per-value probe safety.
	 * @param array   $conflict_indexes Conflict target column/index tuples.
	 * @return bool Whether PostgreSQL needs per-row statements.
	 */
	private function has_duplicate_mysql_replace_conflict_value_rows( array $value_rows, array $probe_safe_rows, array $conflict_indexes ): bool {
		$seen_values = array();
		foreach ( $value_rows as $row_index => $values ) {
			$probe_safety = $probe_safe_rows[ $row_index ] ?? array();
			foreach ( $conflict_indexes as $conflict_index ) {
				if ( ! isset( $probe_safety[ $conflict_index['index'] ] ) || ! $probe_safety[ $conflict_index['index'] ] ) {
					return false;
				}
			}

			$seen_key = $this->get_mysql_replace_conflict_seen_key_for_row( $values, $conflict_indexes );
			if ( null === $seen_key ) {
				continue;
			}

			if ( isset( $seen_values[ $seen_key ] ) ) {
				return true;
			}

			$seen_values[ $seen_key ] = true;
		}

		return false;
	}

	/**
	 * Check whether a REPLACE batch duplicates any deterministic conflict key.
	 *
	 * @param array[] $value_rows             Translated VALUES rows.
	 * @param array[] $probe_safe_rows        Per-value probe safety.
	 * @param array[] $conflict_index_groups  Conflict target column/index tuple groups.
	 * @return bool Whether PostgreSQL needs per-row statements.
	 */
	private function has_duplicate_mysql_replace_conflict_value_rows_in_groups( array $value_rows, array $probe_safe_rows, array $conflict_index_groups ): bool {
		foreach ( $conflict_index_groups as $conflict_indexes ) {
			if ( $this->has_duplicate_mysql_replace_conflict_value_rows( $value_rows, $probe_safe_rows, $conflict_indexes ) ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Normalize deterministic REPLACE conflict SQL values for in-statement tracking.
	 *
	 * @param array $values           Translated VALUES row.
	 * @param array $conflict_indexes Conflict target column/index tuples.
	 * @return string|null Stable lookup key, or null when the row should not conflict.
	 */
	private function get_mysql_replace_conflict_seen_key_for_row( array $values, array $conflict_indexes ): ?string {
		$parts = array();
		foreach ( $conflict_indexes as $conflict_index ) {
			if ( ! array_key_exists( $conflict_index['index'], $values ) ) {
				return null;
			}

			$value = trim( (string) $values[ $conflict_index['index'] ] );
			if (
				'' === $value
				|| 'NULL' === strtoupper( $value )
				|| $this->is_mysql_generated_auto_increment_value_sql( $value )
			) {
				return null;
			}

			if ( null !== ( $conflict_index['sub_part'] ?? null ) && '' !== (string) $conflict_index['sub_part'] ) {
				$value = $this->get_mysql_replace_conflict_prefix_seen_value( $value, (int) $conflict_index['sub_part'] );
			}

			$parts[] = $value;
		}

		return implode( "\0", $parts );
	}

	/**
	 * Apply a prefix key length to a deterministic SQL literal when possible.
	 *
	 * @param string $value_sql SQL value.
	 * @param int    $length    Prefix character length.
	 * @return string Prefix lookup value.
	 */
	private function get_mysql_replace_conflict_prefix_seen_value( string $value_sql, int $length ): string {
		if ( $length <= 0 || strlen( $value_sql ) < 2 || "'" !== $value_sql[0] || "'" !== $value_sql[ strlen( $value_sql ) - 1 ] ) {
			return $value_sql;
		}

		$value = str_replace( "''", "'", substr( $value_sql, 1, -1 ) );
		$count = preg_match_all( '/./us', $value, $matches );
		if ( false !== $count ) {
			$value = implode( '', array_slice( $matches[0], 0, $length ) );
		} else {
			$value = substr( $value, 0, $length );
		}

		return "'" . str_replace( "'", "''", $value ) . "'";
	}

	/**
	 * Choose the conflict column for a WordPress REPLACE statement.
	 *
	 * @param string   $table_name Table name.
	 * @param string[] $columns    Inserted column names.
	 * @return string|null Conflict column name, or null when unknown.
	 */
	private function get_simple_replace_conflict_column( string $table_name, array $columns ): ?string {
		$column_lookup = array();
		foreach ( $columns as $column ) {
			$column_lookup[ strtolower( $column ) ] = $column;
		}

		if ( $this->is_wordpress_options_table_name( $table_name ) && isset( $column_lookup['option_name'] ) ) {
			return $column_lookup['option_name'];
		}

		if ( $this->is_mysql_wordpress_table_name( $table_name, 'wc_customer_lookup' ) && isset( $column_lookup['customer_id'] ) ) {
			return $column_lookup['customer_id'];
		}

		if ( $this->is_mysql_wordpress_table_name( $table_name, 'wc_product_meta_lookup' ) && isset( $column_lookup['product_id'] ) ) {
			return $column_lookup['product_id'];
		}

		foreach (
			array(
				'id',
				'comment_id',
				'link_id',
				'option_id',
				'meta_id',
				'umeta_id',
				'term_id',
				'term_taxonomy_id',
			) as $candidate
		) {
			if ( isset( $column_lookup[ $candidate ] ) ) {
				return $column_lookup[ $candidate ];
			}
		}

		return null;
	}

	/**
	 * Translate simple MySQL INSERT statements to PostgreSQL.
	 *
	 * WordPress CRUD helpers emit a narrow INSERT INTO table (columns) VALUES
	 * (...) shape. INSERT IGNORE uses PostgreSQL's conflict no-op syntax for
	 * the same VALUES shape. Simple single-row INSERT ... SET assignments are
	 * normalized into that same PostgreSQL INSERT form. MySQL priority
	 * modifiers are accepted as compatibility no-ops. Other trailing clauses
	 * fall through unchanged. Columnless VALUES rows are supported when stored
	 * MySQL metadata can infer target columns.
	 *
	 * @param string $query MySQL query.
	 * @return array|null PostgreSQL query data, or null when the query is unsupported.
	 */
	private function translate_simple_mysql_insert_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::INSERT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$position = 1;
		$ignore   = false;
		$this->consume_mysql_insert_priority_modifier( $tokens, $position );
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::IGNORE_SYMBOL === $tokens[ $position ]->id ) {
			$ignore = true;
			++$position;
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::INTO_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		$table_name = $this->parse_mysql_main_database_table_name( $tokens, $position );
		if ( null === $table_name ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, $position );
		if ( null === $statement_end ) {
			return null;
		}

		$column_metadata  = null;
		$value_rows       = null;
		$value_range_rows = array();
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::SET_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
			$set_assignments = $this->parse_simple_mysql_insert_set_assignments( $table_name, $tokens, $position, $statement_end );
			if ( null === $set_assignments ) {
				return null;
			}

			$columns          = $set_assignments['columns'];
			$value_rows       = array( $set_assignments['values'] );
			$value_range_rows = array( $set_assignments['ranges'] );
		} elseif ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
			$columns = $this->parse_mysql_identifier_list( $tokens, $position );
			if ( null === $columns ) {
				return null;
			}
		} elseif ( $this->is_mysql_values_row_list_keyword_token( $tokens[ $position ] ?? null ) ) {
			$column_metadata = $this->get_mysql_dml_column_metadata( $table_name );
			$columns         = $this->get_mysql_dml_column_names_from_metadata( $column_metadata );
			if ( null === $columns ) {
				return null;
			}
		} else {
			return null;
		}

		if ( null === $value_rows ) {
			if ( ! $this->is_mysql_values_row_list_keyword_token( $tokens[ $position ] ?? null ) ) {
				return null;
			}

			++$position;
			$probe_safe_rows  = array();
			$value_range_rows = array();
			$value_rows       = $this->parse_mysql_values_rows( $tokens, $position, $statement_end, count( $columns ), $probe_safe_rows, $value_range_rows );
			if ( null === $value_rows || ! $this->is_at_mysql_query_end( $tokens, $position ) ) {
				return null;
			}
		}

		if ( null === $column_metadata ) {
			$column_metadata = $this->get_mysql_dml_column_metadata( $table_name );
		}
		foreach ( $value_rows as $row_index => &$values ) {
			$value_ranges = $value_range_rows[ $row_index ] ?? array();
			$this->validate_strict_mysql_dml_values_for_columns(
				$columns,
				$value_ranges,
				$tokens,
				$column_metadata
			);
			$this->normalize_mysql_auto_increment_zero_values_for_columns(
				$columns,
				$values,
				$value_ranges,
				$tokens,
				$column_metadata
			);
			$this->normalize_strict_mysql_dml_values_for_columns(
				$columns,
				$values,
				$value_ranges,
				$tokens,
				$column_metadata
			);
			$this->normalize_non_strict_mysql_dml_values_for_columns(
				$columns,
				$values,
				$value_ranges,
				$tokens,
				$column_metadata
			);
		}
		unset( $values );
		$this->append_non_strict_dml_defaults_for_omitted_value_rows( $table_name, $columns, $value_rows, $column_metadata );

		$sql_value_rows = array();
		foreach ( $value_rows as $values ) {
			$sql_value_rows[] = '(' . implode( ', ', $values ) . ')';
		}

		$sql = sprintf(
			'INSERT INTO %s (%s) VALUES %s',
			$this->connection->quote_identifier( $table_name ),
			implode( ', ', array_map( array( $this->connection, 'quote_identifier' ), $columns ) ),
			implode( ', ', $sql_value_rows )
		);

		return array(
			'action'           => 'insert',
			'sql'              => $ignore ? $sql . ' ON CONFLICT DO NOTHING' : $sql,
			'table_name'       => $table_name,
			'columns'          => $columns,
			'values'           => $value_rows[0] ?? array(),
			'value_rows'       => $value_rows,
			'ignore'           => $ignore,
			'inserted_new_row' => true,
		);
	}

	/**
	 * Check whether a query is a MySQL REPLACE statement.
	 *
	 * @param string $query MySQL query.
	 * @return bool Whether the query starts with REPLACE.
	 */
	private function is_mysql_replace_query( string $query ): bool {
		$tokens = $this->get_mysql_tokens( $query );
		return isset( $tokens[0] ) && WP_MySQL_Lexer::REPLACE_SYMBOL === $tokens[0]->id;
	}

	/**
	 * Check whether a token is a MySQL VALUES/VALUE row-list keyword.
	 *
	 * MySQL accepts singular VALUE as a synonym for VALUES before row lists. Keep
	 * this separate from VALUES(column) upsert-expression handling.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @return bool Whether the token starts a VALUES row list.
	 */
	private function is_mysql_values_row_list_keyword_token( ?WP_MySQL_Token $token ): bool {
		return null !== $token
			&& in_array(
				$token->id,
				array(
					WP_MySQL_Lexer::VALUES_SYMBOL,
					WP_MySQL_Lexer::VALUE_SYMBOL,
				),
				true
			);
	}

	/**
	 * Check whether an unsupported INSERT ... SET query was not translated.
	 *
	 * @param string $query MySQL query.
	 * @return bool Whether the query is an INSERT ... SET shape.
	 */
	private function is_unsupported_mysql_insert_set_query( string $query ): bool {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::INSERT_SYMBOL !== $tokens[0]->id ) {
			return false;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return false;
		}

		return null !== $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::SET_SYMBOL,
			1,
			$statement_end
		);
	}

	/**
	 * Parse a simple single-row MySQL INSERT ... SET assignment list.
	 *
	 * @param string           $table_name Target table name.
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param int              $start      First assignment token position.
	 * @param int              $end        Final assignment token position, exclusive.
	 * @return array{columns: string[], values: string[], ranges: array[], probe_safe_values: bool[]}|null Insert columns and values, or null when unsupported.
	 */
	private function parse_simple_mysql_insert_set_assignments( string $table_name, array $tokens, int $start, int $end ): ?array {
		$on_duplicate = $this->find_on_duplicate_key_update_clause( $tokens, $start );
		if ( $start >= $end || ( null !== $on_duplicate && $on_duplicate < $end ) ) {
			return null;
		}

		$assignments = $this->split_top_level_mysql_arguments( $tokens, $start, $end );
		if ( null === $assignments || empty( $assignments ) ) {
			return null;
		}

		$columns       = array();
		$values        = array();
		$ranges        = array();
		$probe_safe    = array();
		$column_lookup = array();
		foreach ( $assignments as $assignment ) {
			$target = $this->parse_simple_mysql_insert_set_assignment_target(
				$table_name,
				$tokens,
				$assignment['start'],
				$assignment['end']
			);
			if ( null === $target ) {
				return null;
			}

			$column      = $target['column'];
			$value_start = $target['value_start'];

			$column_key = strtolower( $column );
			if ( isset( $column_lookup[ $column_key ] ) ) {
				return null;
			}
			$column_lookup[ $column_key ] = true;

			$columns[]    = $column;
			$values[]     = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $value_start, $assignment['end'] );
			$ranges[]     = array(
				'start' => $value_start,
				'end'   => $assignment['end'],
			);
			$probe_safe[] = $this->is_supported_mysql_upsert_conflict_probe_token_sequence( $tokens, $value_start, $assignment['end'] );
		}

		return array(
			'columns'           => $columns,
			'values'            => $values,
			'ranges'            => $ranges,
			'probe_safe_values' => $probe_safe,
		);
	}

	/**
	 * Parse the target side of a simple INSERT/REPLACE ... SET assignment.
	 *
	 * @param string           $table_name Target table name.
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param int              $start      Assignment start token position.
	 * @param int              $end        Assignment end token position, exclusive.
	 * @return array{column: string, value_start: int}|null Parsed assignment target, or null when unsupported.
	 */
	private function parse_simple_mysql_insert_set_assignment_target( string $table_name, array $tokens, int $start, int $end ): ?array {
		$first = $this->get_mysql_dml_identifier_token_value( $tokens[ $start ] ?? null );
		if ( null === $first ) {
			return null;
		}

		$position = $start + 1;
		if ( WP_MySQL_Lexer::EQUAL_OPERATOR === ( $tokens[ $position ]->id ?? null ) ) {
			return $position + 1 < $end
				? array(
					'column'      => $first,
					'value_start' => $position + 1,
				)
				: null;
		}

		if ( WP_MySQL_Lexer::DOT_SYMBOL !== ( $tokens[ $position ]->id ?? null ) ) {
			return null;
		}

		$second = $this->get_mysql_dml_identifier_token_value( $tokens[ $position + 1 ] ?? null );
		if ( null === $second ) {
			return null;
		}
		$position += 2;

		if ( WP_MySQL_Lexer::DOT_SYMBOL === ( $tokens[ $position ]->id ?? null ) ) {
			$third = $this->get_mysql_dml_identifier_token_value( $tokens[ $position + 1 ] ?? null );
			if (
				null === $third
				|| 0 !== strcasecmp( $first, $this->main_db_name )
				|| 0 !== strcasecmp( $second, $table_name )
			) {
				return null;
			}

			$column    = $third;
			$position += 2;
		} else {
			if ( ! $this->is_mysql_dml_table_qualifier( $first, $table_name, null ) ) {
				return null;
			}

			$column = $second;
		}

		if (
			WP_MySQL_Lexer::EQUAL_OPERATOR !== ( $tokens[ $position ]->id ?? null )
			|| $position + 1 >= $end
		) {
			return null;
		}

		return array(
			'column'      => $column,
			'value_start' => $position + 1,
		);
	}

	/**
	 * Translate simple MySQL INSERT ... SELECT statements to PostgreSQL.
	 *
	 * Action Scheduler uses INSERT ... SELECT FROM DUAL and then reads
	 * insert_id. The generic compatibility rewrite can produce executable SQL,
	 * but it does not mark the statement as insert-like. Keep this parser narrow:
	 * explicit table, optional explicit or metadata-inferred column list, then
	 * a SELECT body.
	 *
	 * @param string $query MySQL query.
	 * @return array|null PostgreSQL query data, or null when unsupported.
	 */
	private function translate_simple_mysql_insert_select_query( string $query ): ?array {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::INSERT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$position = 1;
		$ignore   = false;
		$this->consume_mysql_insert_priority_modifier( $tokens, $position );
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::IGNORE_SYMBOL === $tokens[ $position ]->id ) {
			$ignore = true;
			++$position;
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::INTO_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		$table_reference_start = $position;
		$table_name            = $this->parse_mysql_main_database_table_name( $tokens, $position );
		if ( null === $table_name ) {
			return null;
		}
		$table_reference_end = $position;
		$table_reference_sql = $this->get_mysql_main_database_table_reference_sql(
			$tokens,
			$table_reference_start,
			$table_reference_end
		);

		$insert_column_list = false;
		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id
			&& WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[ $position + 1 ]->id
		) {
			$column_metadata    = $this->get_mysql_dml_column_metadata( $table_name );
			$columns            = $this->get_mysql_dml_column_names_from_metadata( $column_metadata );
			$insert_column_list = true;
			if ( null === $columns ) {
				return null;
			}
		} elseif ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[ $position ]->id ) {
			$column_metadata    = $this->get_mysql_dml_column_metadata( $table_name );
			$columns            = $this->get_mysql_dml_column_names_from_metadata( $column_metadata );
			$insert_column_list = true;
			if ( null === $columns ) {
				return null;
			}
		} else {
			$columns = $this->parse_mysql_identifier_list( $tokens, $position );
			if ( null === $columns ) {
				return null;
			}
		}
		if ( $insert_column_list ) {
			$table_reference_sql .= ' (' . implode( ', ', array_map( array( $this->connection, 'quote_identifier' ), $columns ) ) . ')';
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, $position );
		if ( null === $statement_end || ! $this->is_at_mysql_query_end( $tokens, $statement_end ) ) {
			return null;
		}

		$select_start        = $position;
		$select_end          = $statement_end;
		$outer_replacements  = array(
			array(
				'start' => 0,
				'end'   => $table_reference_end,
				'sql'   => 'INSERT INTO ' . $table_reference_sql,
			),
		);
		$closing_replacement = array();
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
			$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $statement_end );
			if (
				null === $after_close
				|| $after_close !== $statement_end
				|| ! isset( $tokens[ $position + 1 ] )
				|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position + 1 ]->id
			) {
				return null;
			}

			$select_start          = $position + 1;
			$select_end            = $statement_end - 1;
			$outer_replacements[]  = array(
				'start' => $position,
				'end'   => $position + 1,
				'sql'   => '',
			);
			$closing_replacement[] = array(
				'start' => $statement_end - 1,
				'end'   => $statement_end,
				'sql'   => '',
			);
		}

		if ( ! isset( $tokens[ $select_start ] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $select_start ]->id ) {
			return null;
		}

		$replacements = $this->get_mysql_insert_select_projection_replacements(
			$table_name,
			$columns,
			$tokens,
			$select_start,
			$select_end
		);
		if ( null === $replacements ) {
			return null;
		}
		$replacements = array_merge( $outer_replacements, $replacements, $closing_replacement );

		$direct_information_schema_select_sql = $this->get_insert_select_direct_information_schema_select_sql(
			$query,
			$tokens,
			$select_start,
			$select_end
		);
		if ( null !== $direct_information_schema_select_sql ) {
			if ( $this->mysql_replacements_overlap_range( $replacements, $select_start, $select_end ) ) {
				return null;
			}

			$replacements[] = array(
				'start' => $select_start,
				'end'   => $select_end,
				'sql'   => $direct_information_schema_select_sql,
			);
		} elseif ( $this->mysql_select_range_requires_direct_information_schema_rewrite( $tokens, $select_start, $select_end ) ) {
			return null;
		}

		usort(
			$replacements,
			static function ( array $left, array $right ): int {
				return $left['start'] <=> $right['start'];
			}
		);

		$sql = $this->translate_mysql_token_sequence_with_replacements_to_postgresql(
			$tokens,
			0,
			$statement_end,
			$replacements
		);
		if ( $ignore ) {
			$sql .= ' ON CONFLICT DO NOTHING';
		}

		$table_column_lookup       = $this->get_mysql_dml_column_metadata_lookup( $table_name );
		$auto_increment_column     = $this->get_mysql_auto_increment_column_from_metadata( $table_column_lookup );
		$literal_value_row         = null;
		$insert_id_value_rows      = null;
		$value_rows                = null;
		$explicit_identity_columns = array();
		if (
			null !== $auto_increment_column
			&& $this->mysql_dml_column_list_contains_column( $columns, $auto_increment_column )
		) {
			$literal_value_row = $this->get_mysql_insert_select_upsert_literal_value_row(
				$table_name,
				$columns,
				$tokens,
				$select_start,
				$select_end
			);
			if ( null === $literal_value_row ) {
				$explicit_identity_columns[ strtolower( $auto_increment_column ) ] = true;
			} else {
				$value_rows           = array( $literal_value_row['values'] );
				$insert_id_value_rows = array( $literal_value_row['insert_id_values'] );
			}
		}

		return array(
			'action'                    => 'insert',
			'sql'                       => $sql,
			'table_name'                => $table_name,
			'columns'                   => $columns,
			'ignore'                    => $ignore,
			'inserted_new_row'          => true,
			'value_rows'                => $value_rows,
			'insert_id_value_rows'      => $insert_id_value_rows,
			'insert_id_unknown'         => ! empty( $explicit_identity_columns ),
			'explicit_identity_columns' => $explicit_identity_columns,
		);
	}

	/**
	 * Get translated SELECT SQL for INSERT ... SELECT sourcing information_schema.
	 *
	 * @param string           $query        Original MySQL query.
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int              $select_start SELECT token position.
	 * @param int              $select_end   Final SELECT token position, exclusive.
	 * @return string|null PostgreSQL SELECT SQL, or null when not a supported information_schema SELECT.
	 */
	private function get_insert_select_direct_information_schema_select_sql( string $query, array $tokens, int $select_start, int $select_end ): ?string {
		$select_query = $this->get_mysql_token_range_sql( $query, $tokens, $select_start, $select_end );
		if ( null === $select_query ) {
			return null;
		}

		return $this->translate_direct_information_schema_select_query( $select_query );
	}

	/**
	 * Check whether a SELECT range must use the information_schema rewrite path.
	 *
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int              $select_start SELECT token position.
	 * @param int              $select_end   Final SELECT token position, exclusive.
	 * @return bool Whether falling through to the backend would be unsafe.
	 */
	private function mysql_select_range_requires_direct_information_schema_rewrite( array $tokens, int $select_start, int $select_end ): bool {
		if ( $this->select_references_direct_information_schema_relation( $tokens, $select_start + 1, $select_end ) ) {
			return true;
		}

		return 0 === strcasecmp( $this->db_name, 'information_schema' )
			&& null !== $this->find_top_level_mysql_token(
				$tokens,
				WP_MySQL_Lexer::FROM_SYMBOL,
				$select_start + 1,
				$select_end
			);
	}

	/**
	 * Check whether replacement ranges overlap a token range.
	 *
	 * @param array[] $replacements Replacement ranges.
	 * @param int     $start        First token position.
	 * @param int     $end          Final token position, exclusive.
	 * @return bool Whether any replacement overlaps the range.
	 */
	private function mysql_replacements_overlap_range( array $replacements, int $start, int $end ): bool {
		foreach ( $replacements as $replacement ) {
			if ( max( $start, $replacement['start'] ) < min( $end, $replacement['end'] ) ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Get projection replacements for INSERT ... SELECT target compatibility.
	 *
	 * @param string           $table_name   Target table name.
	 * @param string[]         $columns      Target column names.
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int              $select_start SELECT token position.
	 * @param int              $select_end   Final SELECT token position, exclusive.
	 * @return array[]|null Replacement ranges, or null when unsupported.
	 */
	private function get_mysql_insert_select_projection_replacements( string $table_name, array $columns, array $tokens, int $select_start, int $select_end ): ?array {
		$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, $select_start + 1, $select_end );
		if ( null === $from_position || $select_start + 1 >= $from_position ) {
			return array();
		}

		$projection_ranges = $this->split_top_level_mysql_arguments( $tokens, $select_start + 1, $from_position );
		if ( null === $projection_ranges || count( $projection_ranges ) !== count( $columns ) ) {
			return null;
		}

		$target_metadata = $this->get_mysql_dml_column_metadata_lookup( $table_name );
		if ( empty( $target_metadata ) ) {
			return array();
		}

		$first_clause_position = $this->find_first_top_level_mysql_token(
			$tokens,
			array(
				WP_MySQL_Lexer::FOR_SYMBOL,
				WP_MySQL_Lexer::GROUP_SYMBOL,
				WP_MySQL_Lexer::HAVING_SYMBOL,
				WP_MySQL_Lexer::LIMIT_SYMBOL,
				WP_MySQL_Lexer::LOCK_SYMBOL,
				WP_MySQL_Lexer::ORDER_SYMBOL,
				WP_MySQL_Lexer::PROCEDURE_SYMBOL,
				WP_MySQL_Lexer::UNION_SYMBOL,
				WP_MySQL_Lexer::WHERE_SYMBOL,
			),
			$from_position + 1,
			$select_end
		) ?? $select_end;
		$scope                 = $this->get_mysql_select_scope( $tokens, $from_position + 1, $first_clause_position );

		$group_items    = null;
		$group_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::GROUP_SYMBOL, $from_position + 1, $select_end );
		if (
			null !== $group_position
			&& isset( $tokens[ $group_position + 1 ] )
			&& WP_MySQL_Lexer::BY_SYMBOL === $tokens[ $group_position + 1 ]->id
		) {
			$group_end   = $this->find_first_top_level_mysql_token(
				$tokens,
				array(
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::HAVING_SYMBOL,
					WP_MySQL_Lexer::LIMIT_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::ORDER_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				),
				$group_position + 2,
				$select_end
			) ?? $select_end;
			$group_items = $this->split_top_level_mysql_arguments( $tokens, $group_position + 2, $group_end );
			if ( null === $group_items ) {
				return null;
			}
		}

		$replacements = array();
		foreach ( $projection_ranges as $index => $range ) {
			$column_key      = strtolower( $columns[ $index ] );
			$column_metadata = $target_metadata[ $column_key ] ?? null;
			if ( null === $column_metadata ) {
				continue;
			}

			$expression_bounds = $this->get_mysql_select_projection_expression_bounds( $tokens, $range['start'], $range['end'] );
			if ( null === $expression_bounds ) {
				return null;
			}

			$expression_start = $expression_bounds['start'];
			$expression_end   = $expression_bounds['end'];
			$projection_sql   = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $expression_start, $expression_end );
			$changed          = false;
			if (
				null !== $group_items
				&& ! $this->is_mysql_insert_select_grouped_projection_expression( $tokens, $expression_start, $expression_end, $group_items )
			) {
				$projection_sql = sprintf( 'MIN(%s)', $projection_sql );
				$changed        = true;
			}

			$coerced_sql = $this->get_mysql_insert_select_projection_sql_for_target_column(
				$table_name,
				$column_metadata,
				$tokens,
				$expression_start,
				$expression_end,
				$projection_sql,
				$scope
			);
			if ( null !== $coerced_sql ) {
				$projection_sql = $coerced_sql;
				$changed        = true;
			}

			if ( ! $changed ) {
				continue;
			}

			$replacements[] = array(
				'start' => $range['start'],
				'end'   => $range['end'],
				'sql'   => $projection_sql,
			);
		}

		return $replacements;
	}

	/**
	 * Check whether an INSERT ... SELECT projection is already grouped or aggregate-safe.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param int              $start       First projection token.
	 * @param int              $end         Final projection token, exclusive.
	 * @param array            $group_items Parsed GROUP BY item ranges.
	 * @return bool Whether the projection can be selected without an aggregate wrapper.
	 */
	private function is_mysql_insert_select_grouped_projection_expression( array $tokens, int $start, int $end, array $group_items ): bool {
		if ( $this->is_mysql_constant_projection_expression( $tokens, $start, $end ) || $this->contains_mysql_aggregate_call( $tokens, $start, $end ) ) {
			return true;
		}

		foreach ( $group_items as $group_item ) {
			if ( $this->are_mysql_token_ranges_equivalent( $tokens, $start, $end, $group_item['start'], $group_item['end'] ) ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Check whether a projection expression is a simple constant.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First projection token.
	 * @param int              $end    Final projection token, exclusive.
	 * @return bool Whether the expression is constant.
	 */
	private function is_mysql_constant_projection_expression( array $tokens, int $start, int $end ): bool {
		return $start + 1 === $end
			&& isset( $tokens[ $start ] )
			&& (
				$this->is_mysql_string_literal_token( $tokens[ $start ] )
				|| $this->is_mysql_numeric_literal_token( $tokens[ $start ] )
				|| WP_MySQL_Lexer::NULL_SYMBOL === $tokens[ $start ]->id
			);
	}

	/**
	 * Coerce an INSERT ... SELECT projection to the target column type when needed.
	 *
	 * @param string                   $table_name      Target table name.
	 * @param array                    $column_metadata Target column metadata.
	 * @param WP_MySQL_Token[]         $tokens          MySQL lexer token stream.
	 * @param int                      $start           First projection token.
	 * @param int                      $end             Final projection token, exclusive.
	 * @param string                   $projection_sql  Already translated projection SQL.
	 * @param array<string,mixed>|null $scope        Source SELECT table scope.
	 * @return string|null Coerced projection SQL, or null when generic SQL is sufficient.
	 */
	private function get_mysql_insert_select_projection_sql_for_target_column( string $table_name, array $column_metadata, array $tokens, int $start, int $end, string $projection_sql, ?array $scope ): ?string {
		$this->validate_strict_mysql_dml_value_for_column( $column_metadata, $tokens, $start, $end );

		if (
			! $this->is_mysql_sql_mode_active( 'NO_AUTO_VALUE_ON_ZERO' )
			&& $this->is_mysql_auto_increment_column_metadata( $column_metadata )
			&& $this->is_mysql_zero_literal_range( $tokens, $start, $end )
		) {
			return $this->get_mysql_insert_select_auto_increment_generated_value_sql( $table_name, $column_metadata );
		}

		$value_sql = $this->get_strict_mysql_dml_value_sql_for_column( $column_metadata, $tokens, $start, $end );
		if ( null !== $value_sql ) {
			return $value_sql;
		}

		$value_sql = $this->get_non_strict_mysql_dml_value_sql_for_column( $column_metadata, $tokens, $start, $end );
		if ( null !== $value_sql ) {
			return $value_sql;
		}

		$target_type = (string) ( $column_metadata['column_type'] ?? '' );
		if ( $this->is_mysql_integer_family_column_type( $target_type ) ) {
			if ( null !== $scope ) {
				$reference = $this->parse_mysql_column_reference( $tokens, $start, $end );
				if ( null !== $reference && $reference['end'] === $end && $this->is_mysql_integer_column_reference( $reference, $scope ) ) {
					return null;
				}
			}

			if ( $this->is_mysql_integer_numeric_literal_range( $tokens, $start, $end ) ) {
				return null;
			}

			return $this->get_postgresql_mysql_integer_cast_sql( $projection_sql );
		}

		if ( ! $this->is_mysql_text_family_column_type( $target_type ) ) {
			return null;
		}

		if ( $this->is_mysql_string_literal_range( $tokens, $start, $end ) ) {
			return null;
		}

		if ( null !== $scope ) {
			$reference = $this->parse_mysql_column_reference( $tokens, $start, $end );
			if ( null !== $reference && $reference['end'] === $end && $this->is_mysql_text_family_column_reference( $reference, $scope ) ) {
				return null;
			}
		}

		return sprintf( 'CAST(%s AS text)', $projection_sql );
	}

	/**
	 * Store a MySQL-compatible insert ID after a successful insert-like query.
	 *
	 * PostgreSQL PDO exposes the sequence value, which can be stale when the
	 * caller explicitly supplies an AUTO_INCREMENT value. MySQL reports that
	 * explicit value through mysqli_insert_id(), and WordPress relies on it.
	 *
	 * @param array $dml_query     Translated DML query metadata.
	 * @param int   $affected_rows Backend affected row count.
	 */
	private function set_last_insert_id_after_dml_success( array $dml_query, int $affected_rows ): void {
		if ( $affected_rows <= 0 ) {
			$this->last_insert_id = 0;
			return;
		}

		$inserted_new_row = ! isset( $dml_query['inserted_new_row'] ) || $dml_query['inserted_new_row'];

		if (
			! isset( $dml_query['table_name'], $dml_query['columns'] )
			|| ! is_array( $dml_query['columns'] )
		) {
			$this->last_insert_id = $inserted_new_row ? $this->get_connection_last_insert_id() : 0;
			return;
		}

		$metadata_lookup = $this->get_mysql_dml_column_metadata_lookup( (string) $dml_query['table_name'] );
		if ( empty( $metadata_lookup ) ) {
			$this->last_insert_id = $inserted_new_row ? $this->get_connection_last_insert_id() : 0;
			return;
		}

		$auto_increment_column = $this->get_mysql_auto_increment_column_from_metadata( $metadata_lookup );
		if ( null === $auto_increment_column ) {
			$this->last_insert_id = 0;
			return;
		}

		if ( ! empty( $dml_query['insert_id_unknown'] ) ) {
			$this->last_insert_id = 0;
			return;
		}

		$explicit_insert_id = $this->get_explicit_mysql_auto_increment_insert_id(
			$auto_increment_column,
			$dml_query['columns'],
			$this->get_dml_insert_id_value_rows( $dml_query )
		);
		if ( null !== $explicit_insert_id ) {
			$this->last_insert_id = $explicit_insert_id;
			return;
		}

		if ( ! $inserted_new_row ) {
			$this->last_insert_id = 0;
			return;
		}

		$this->last_insert_id = $this->get_connection_last_insert_id();
	}

	/**
	 * Read the backend connection's last insert ID.
	 *
	 * @return int|string Last insert ID, or 0 when unavailable.
	 */
	private function get_connection_last_insert_id() {
		try {
			$insert_id = $this->connection->get_last_insert_id();
		} catch ( Throwable $e ) {
			return 0;
		}

		return is_numeric( $insert_id ) ? (int) $insert_id : $insert_id;
	}

	/**
	 * Get the MySQL AUTO_INCREMENT column from DML metadata.
	 *
	 * @param array<string, array> $metadata_lookup Column metadata lookup.
	 * @return string|null AUTO_INCREMENT column name, or null when absent.
	 */
	private function get_mysql_auto_increment_column_from_metadata( array $metadata_lookup ): ?string {
		foreach ( $metadata_lookup as $column_metadata ) {
			if ( ! $this->is_mysql_auto_increment_column_metadata( $column_metadata ) ) {
				continue;
			}

			$column_name = (string) ( $column_metadata['column_name'] ?? '' );
			if ( '' !== $column_name ) {
				return $column_name;
			}
		}

		return null;
	}

	/**
	 * Get DML value rows from translated insert metadata.
	 *
	 * @param array $dml_query Translated DML query metadata.
	 * @return array[] DML value rows.
	 */
	private function get_dml_insert_value_rows( array $dml_query ): array {
		if ( isset( $dml_query['value_rows'] ) && is_array( $dml_query['value_rows'] ) ) {
			return $dml_query['value_rows'];
		}

		if ( isset( $dml_query['values'] ) && is_array( $dml_query['values'] ) ) {
			return array( $dml_query['values'] );
		}

		return array();
	}

	/**
	 * Get DML value rows used for MySQL insert ID detection.
	 *
	 * @param array $dml_query Translated DML query metadata.
	 * @return array[] DML value rows.
	 */
	private function get_dml_insert_id_value_rows( array $dml_query ): array {
		if ( isset( $dml_query['insert_id_value_rows'] ) && is_array( $dml_query['insert_id_value_rows'] ) ) {
			return $dml_query['insert_id_value_rows'];
		}

		return $this->get_dml_insert_value_rows( $dml_query );
	}

	/**
	 * Get an explicitly supplied AUTO_INCREMENT insert ID from DML values.
	 *
	 * @param string   $auto_increment_column AUTO_INCREMENT column name.
	 * @param string[] $columns               DML column names.
	 * @param array[]  $value_rows            DML value rows.
	 * @return int|string|null Explicit insert ID, or null when not supplied.
	 */
	private function get_explicit_mysql_auto_increment_insert_id( string $auto_increment_column, array $columns, array $value_rows ) {
		$auto_increment_index = null;
		foreach ( $columns as $index => $column ) {
			if ( strtolower( (string) $column ) === strtolower( $auto_increment_column ) ) {
				$auto_increment_index = $index;
				break;
			}
		}

		if ( null === $auto_increment_index ) {
			return null;
		}

		foreach ( $value_rows as $values ) {
			if ( ! is_array( $values ) || ! isset( $values[ $auto_increment_index ] ) ) {
				continue;
			}

			$insert_id = $this->get_mysql_insert_id_from_value_sql( (string) $values[ $auto_increment_index ] );
			if ( null !== $insert_id ) {
				return $insert_id;
			}
		}

		return null;
	}

	/**
	 * Parse a simple integer SQL value as a MySQL insert ID.
	 *
	 * @param string $value_sql Translated SQL value.
	 * @return int|string|null Insert ID, or null for DEFAULT/NULL/unsupported values.
	 */
	private function get_mysql_insert_id_from_value_sql( string $value_sql ) {
		$value_sql = trim( $value_sql );
		if ( '' === $value_sql || in_array( strtoupper( $value_sql ), array( 'DEFAULT', 'NULL' ), true ) ) {
			return null;
		}

		if (
			strlen( $value_sql ) >= 2
			&& (
				( "'" === $value_sql[0] && "'" === $value_sql[ strlen( $value_sql ) - 1 ] )
				|| ( '"' === $value_sql[0] && '"' === $value_sql[ strlen( $value_sql ) - 1 ] )
			)
		) {
			$value_sql = substr( $value_sql, 1, -1 );
		}

		if ( isset( $value_sql[0] ) && '+' === $value_sql[0] ) {
			$value_sql = substr( $value_sql, 1 );
		}

		if ( '' === $value_sql || ! ctype_digit( $value_sql ) ) {
			return null;
		}

		$value_sql = ltrim( $value_sql, '0' );
		if ( '' === $value_sql ) {
			$value_sql = '0';
		}

		return is_numeric( $value_sql ) ? (int) $value_sql : $value_sql;
	}

	/**
	 * Evaluate a bounded MySQL integer constant expression.
	 *
	 * This is only used for MySQL insert-id bookkeeping after the expression has
	 * already passed the no-identifiers upsert literal-expression guard.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First expression token position, inclusive.
	 * @param int              $end    Final expression token position, exclusive.
	 * @return string|null Non-negative integer string, or null when unsupported.
	 */
	private function get_mysql_constant_integer_expression_value( array $tokens, int $start, int $end ): ?string {
		$position = $start;
		$value    = $this->parse_mysql_constant_integer_expression( $tokens, $position, $end );
		if ( null === $value || $position !== $end || $value < 0 ) {
			return null;
		}

		return (string) $value;
	}

	/**
	 * Parse a constant integer expression with + and - operators.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current token position, updated on success.
	 * @param int              $end      Final expression token position, exclusive.
	 * @return int|null Parsed integer, or null when unsupported.
	 */
	private function parse_mysql_constant_integer_expression( array $tokens, int &$position, int $end ): ?int {
		$value = $this->parse_mysql_constant_integer_term( $tokens, $position, $end );
		if ( null === $value ) {
			return null;
		}

		while ( $position < $end && isset( $tokens[ $position ] ) ) {
			$operator = $tokens[ $position ]->id;
			if ( ! in_array( $operator, array( WP_MySQL_Lexer::PLUS_OPERATOR, WP_MySQL_Lexer::MINUS_OPERATOR ), true ) ) {
				break;
			}

			++$position;
			$right = $this->parse_mysql_constant_integer_term( $tokens, $position, $end );
			if ( null === $right ) {
				return null;
			}

			$value = WP_MySQL_Lexer::PLUS_OPERATOR === $operator ? $value + $right : $value - $right;
			if ( ! is_int( $value ) ) {
				return null;
			}
		}

		return $value;
	}

	/**
	 * Parse a constant integer term with multiplication.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current token position, updated on success.
	 * @param int              $end      Final expression token position, exclusive.
	 * @return int|null Parsed integer, or null when unsupported.
	 */
	private function parse_mysql_constant_integer_term( array $tokens, int &$position, int $end ): ?int {
		$value = $this->parse_mysql_constant_integer_factor( $tokens, $position, $end );
		if ( null === $value ) {
			return null;
		}

		while (
			$position < $end
			&& isset( $tokens[ $position ] )
			&& WP_MySQL_Lexer::MULT_OPERATOR === $tokens[ $position ]->id
		) {
			++$position;
			$right = $this->parse_mysql_constant_integer_factor( $tokens, $position, $end );
			if ( null === $right ) {
				return null;
			}

			$value *= $right;
			if ( ! is_int( $value ) ) {
				return null;
			}
		}

		return $value;
	}

	/**
	 * Parse a constant integer factor.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current token position, updated on success.
	 * @param int              $end      Final expression token position, exclusive.
	 * @return int|null Parsed integer, or null when unsupported.
	 */
	private function parse_mysql_constant_integer_factor( array $tokens, int &$position, int $end ): ?int {
		if ( $position >= $end || ! isset( $tokens[ $position ] ) ) {
			return null;
		}

		$sign = 1;
		while (
			$position < $end
			&& isset( $tokens[ $position ] )
			&& in_array( $tokens[ $position ]->id, array( WP_MySQL_Lexer::PLUS_OPERATOR, WP_MySQL_Lexer::MINUS_OPERATOR ), true )
		) {
			if ( WP_MySQL_Lexer::MINUS_OPERATOR === $tokens[ $position ]->id ) {
				$sign *= -1;
			}
			++$position;
		}

		if ( $position >= $end || ! isset( $tokens[ $position ] ) ) {
			return null;
		}

		if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
			$value = $this->parse_mysql_constant_integer_expression( $tokens, $position, $end );
			if (
				null === $value
				|| $position >= $end
				|| ! isset( $tokens[ $position ] )
				|| WP_MySQL_Lexer::CLOSE_PAR_SYMBOL !== $tokens[ $position ]->id
			) {
				return null;
			}
			++$position;
			return $sign * $value;
		}

		if (
			! in_array(
				$tokens[ $position ]->id,
				array(
					WP_MySQL_Lexer::INT_NUMBER,
					WP_MySQL_Lexer::LONG_NUMBER,
					WP_MySQL_Lexer::ULONGLONG_NUMBER,
				),
				true
			)
		) {
			return null;
		}

		$value = ltrim( $tokens[ $position ]->get_bytes(), '+' );
		++$position;
		if ( '' === $value || ! ctype_digit( $value ) ) {
			return null;
		}

		$value = ltrim( $value, '0' );
		if ( '' === $value ) {
			return 0;
		}

		$max = (string) PHP_INT_MAX;
		if ( strlen( $value ) > strlen( $max ) || ( strlen( $value ) === strlen( $max ) && strcmp( $value, $max ) > 0 ) ) {
			return null;
		}

		return $sign * (int) $value;
	}

	/**
	 * Repair PostgreSQL identity sequences for successful explicit identity writes.
	 *
	 * @param array $dml_query     Translated DML query metadata.
	 * @param int   $affected_rows Backend affected row count.
	 */
	private function repair_dml_identity_sequences_after_success( array $dml_query, int $affected_rows ): void {
		if ( $affected_rows <= 0 ) {
			return;
		}

		if ( isset( $dml_query['inserted_new_row'] ) && ! $dml_query['inserted_new_row'] ) {
			return;
		}

		if (
			! isset( $dml_query['table_name'], $dml_query['columns'] )
			|| ! is_array( $dml_query['columns'] )
		) {
			return;
		}

		$explicit_identity_columns = array();
		if (
			isset( $dml_query['explicit_identity_columns'] )
			&& is_array( $dml_query['explicit_identity_columns'] )
		) {
			foreach ( $dml_query['explicit_identity_columns'] as $column => $explicit ) {
				if ( $explicit ) {
					$explicit_identity_columns[ strtolower( (string) $column ) ] = true;
				}
			}
		}

		if ( isset( $dml_query['value_rows'] ) && is_array( $dml_query['value_rows'] ) ) {
			$explicit_identity_columns = $this->get_explicit_dml_identity_column_lookup_from_rows(
				$dml_query['columns'],
				$dml_query['value_rows']
			) + $explicit_identity_columns;
		} elseif ( isset( $dml_query['values'] ) && is_array( $dml_query['values'] ) ) {
			$explicit_identity_columns = $this->get_explicit_dml_identity_column_lookup(
				$dml_query['columns'],
				$dml_query['values']
			) + $explicit_identity_columns;
		} elseif ( empty( $explicit_identity_columns ) ) {
			return;
		}

		if ( empty( $explicit_identity_columns ) || ! $this->is_postgresql_catalog_available_for_dml_identity_repair() ) {
			return;
		}

		$table_name   = (string) $dml_query['table_name'];
		$table_schema = $this->resolve_mysql_table_schema_for_introspection( 'public', $table_name );
		$metadata     = $this->get_dml_identity_column_metadata( $table_schema, $table_name );

		foreach ( $metadata as $column_metadata ) {
			$column_name = (string) ( $column_metadata['column_name'] ?? '' );
			if ( ! isset( $explicit_identity_columns[ strtolower( $column_name ) ] ) ) {
				continue;
			}

			if ( ! $this->is_existing_dbdelta_column_identity( $column_metadata ) ) {
				continue;
			}

			$sequence_schema = (string) ( $column_metadata['sequence_schema'] ?? '' );
			$sequence_name   = (string) ( $column_metadata['sequence_name'] ?? '' );
			if ( '' === $sequence_schema || '' === $sequence_name ) {
				continue;
			}

			$this->repair_postgresql_identity_sequence(
				$table_schema,
				$table_name,
				$column_name,
				$sequence_schema,
				$sequence_name
			);
		}
	}

	/**
	 * Get explicitly supplied non-default DML identity columns.
	 *
	 * @param string[] $columns DML column names.
	 * @param string[] $values  Translated DML value expressions.
	 * @return array<string, bool> Lowercase column lookup.
	 */
	private function get_explicit_dml_identity_column_lookup( array $columns, array $values ): array {
		$explicit_columns = array();

		foreach ( $columns as $index => $column ) {
			if ( ! isset( $values[ $index ] ) || ! $this->is_explicit_dml_identity_value( (string) $values[ $index ] ) ) {
				continue;
			}

			$explicit_columns[ strtolower( (string) $column ) ] = true;
		}

		return $explicit_columns;
	}

	/**
	 * Get explicitly supplied non-default DML identity columns from VALUES rows.
	 *
	 * @param string[] $columns    DML column names.
	 * @param array[]  $value_rows Translated DML value rows.
	 * @return array<string, bool> Lowercase column lookup.
	 */
	private function get_explicit_dml_identity_column_lookup_from_rows( array $columns, array $value_rows ): array {
		$explicit_columns = array();

		foreach ( $value_rows as $values ) {
			if ( ! is_array( $values ) ) {
				continue;
			}

			foreach ( $this->get_explicit_dml_identity_column_lookup( $columns, $values ) as $column => $explicit ) {
				$explicit_columns[ $column ] = $explicit;
			}
		}

		return $explicit_columns;
	}

	/**
	 * Check whether a DML value is an explicit identity value.
	 *
	 * DEFAULT and NULL do not represent caller-supplied auto_increment values.
	 *
	 * @param string $value_sql Translated value SQL.
	 * @return bool Whether the value is explicit.
	 */
	private function is_explicit_dml_identity_value( string $value_sql ): bool {
		$value_sql = trim( $value_sql );
		if ( '' === $value_sql ) {
			return false;
		}

		return ! in_array( strtoupper( $value_sql ), array( 'DEFAULT', 'NULL' ), true );
	}

	/**
	 * Get PostgreSQL/MySQL metadata for DML identity repair.
	 *
	 * @param string $table_schema Backend table schema.
	 * @param string $table_name   Table name.
	 * @return array[] Column metadata rows.
	 */
	private function get_dml_identity_column_metadata( string $table_schema, string $table_name ): array {
		$this->ensure_mysql_schema_metadata_tables();

		$cache_key = $this->get_mysql_metadata_cache_key( $table_schema, $table_name );
		if ( array_key_exists( $cache_key, $this->mysql_dml_identity_column_metadata_cache ) ) {
			return $this->mysql_dml_identity_column_metadata_cache[ $cache_key ];
		}

		try {
			$stmt = $this->connection->query(
				sprintf(
					'SELECT
						c.column_name,
						c.data_type,
						c.is_identity,
						c.column_default,
						cm.column_type AS mysql_column_type,
						cm.extra AS mysql_extra,
						seq_ns.nspname AS sequence_schema,
						seq.relname AS sequence_name
					FROM information_schema.columns c
					LEFT JOIN %s cm
						ON cm.table_schema = c.table_schema
						AND cm.table_name = c.table_name
						AND cm.column_name = c.column_name
					LEFT JOIN LATERAL (
						SELECT pg_catalog.pg_get_serial_sequence(format(\'%%I.%%I\', c.table_schema, c.table_name), c.column_name)::regclass AS sequence_oid
					) identity_sequence ON TRUE
					LEFT JOIN pg_catalog.pg_class seq
						ON seq.oid = identity_sequence.sequence_oid
					LEFT JOIN pg_catalog.pg_namespace seq_ns
						ON seq_ns.oid = seq.relnamespace
					WHERE c.table_schema = ?
						AND c.table_name = ?
					ORDER BY c.ordinal_position',
					$this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE )
				),
				array( $table_schema, $table_name )
			);
			$this->mysql_dml_identity_column_metadata_cache[ $cache_key ] = $stmt->fetchAll( PDO::FETCH_ASSOC );
		} catch ( PDOException $e ) {
			if ( 'pgsql' === (string) $this->connection->get_pdo()->getAttribute( PDO::ATTR_DRIVER_NAME ) ) {
				throw $e;
			}

			$this->mysql_dml_identity_column_metadata_cache[ $cache_key ] = array();
		}

		return $this->mysql_dml_identity_column_metadata_cache[ $cache_key ];
	}

	/**
	 * Check whether PostgreSQL catalog metadata is available for identity repair.
	 *
	 * @return bool Whether catalog-backed identity repair can run.
	 */
	private function is_postgresql_catalog_available_for_dml_identity_repair(): bool {
		$driver_name = (string) $this->connection->get_pdo()->getAttribute( PDO::ATTR_DRIVER_NAME );
		if ( 'pgsql' === $driver_name ) {
			return true;
		}

		if ( 'sqlite' === $driver_name ) {
			return $this->sqlite_information_schema_columns_table_exists();
		}

		return false;
	}

	/**
	 * Check whether the SQLite test shim has an information_schema.columns fixture.
	 *
	 * @return bool Whether the fixture table exists.
	 */
	private function sqlite_information_schema_columns_table_exists(): bool {
		$stmt = $this->connection->query( 'PRAGMA database_list' );
		foreach ( $stmt->fetchAll( PDO::FETCH_ASSOC ) as $database ) {
			if ( isset( $database['name'] ) && 'information_schema' === $database['name'] ) {
				$tables = $this->connection->query(
					"SELECT 1 FROM information_schema.sqlite_master WHERE type = 'table' AND name = 'columns' LIMIT 1"
				);
				return false !== $tables->fetchColumn();
			}
		}

		return false;
	}

	/**
	 * Monotonically synchronize a PostgreSQL identity sequence with its table.
	 *
	 * @param string $table_schema    Backend table schema.
	 * @param string $table_name      Table name.
	 * @param string $column_name     Identity column name.
	 * @param string $sequence_schema Sequence schema.
	 * @param string $sequence_name   Sequence name.
	 */
	private function repair_postgresql_identity_sequence(
		string $table_schema,
		string $table_name,
		string $column_name,
		string $sequence_schema,
		string $sequence_name
	): void {
		$sequence_query = $this->get_postgresql_identity_sequence_repair_query(
			$table_schema,
			$table_name,
			$column_name,
			$sequence_schema,
			$sequence_name
		);

		$this->connection->query( $sequence_query['sql'], $sequence_query['params'] );
		$this->last_postgresql_queries[] = $sequence_query;
	}

	/**
	 * Get PostgreSQL sequence adjustment statements for ALTER TABLE AUTO_INCREMENT.
	 *
	 * @param string $table_name             Target table name.
	 * @param string $auto_increment_column AUTO_INCREMENT column name.
	 * @param int    $minimum_sequence_value Minimum last sequence value.
	 * @return string[] PostgreSQL statements.
	 */
	private function get_postgresql_auto_increment_alter_statements( string $table_name, string $auto_increment_column, int $minimum_sequence_value ): array {
		$table_schema = $this->resolve_mysql_table_schema_for_introspection( 'public', $table_name );
		$metadata     = $this->get_dml_identity_column_metadata( $table_schema, $table_name );

		foreach ( $metadata as $column_metadata ) {
			$column_name = (string) ( $column_metadata['column_name'] ?? '' );
			if ( 0 !== strcasecmp( $column_name, $auto_increment_column ) ) {
				continue;
			}

			if ( ! $this->is_existing_dbdelta_column_identity( $column_metadata ) ) {
				continue;
			}

			$sequence_schema = (string) ( $column_metadata['sequence_schema'] ?? '' );
			$sequence_name   = (string) ( $column_metadata['sequence_name'] ?? '' );
			if ( '' === $sequence_schema || '' === $sequence_name ) {
				continue;
			}

			$sequence_query = $this->get_postgresql_identity_sequence_repair_query(
				$table_schema,
				$table_name,
				$column_name,
				$sequence_schema,
				$sequence_name,
				$minimum_sequence_value
			);

			return array(
				str_replace(
					'CAST(? AS regclass)',
					'CAST(' . $this->connection->quote( $sequence_query['params'][0] ) . ' AS regclass)',
					$sequence_query['sql']
				),
			);
		}

		return array();
	}

	/**
	 * Build a SQLite sequence adjustment statement for ALTER TABLE AUTO_INCREMENT tests.
	 *
	 * @param string $table_name             Target table name.
	 * @param string $auto_increment_column AUTO_INCREMENT column name.
	 * @param int    $minimum_sequence_value Minimum last sequence value.
	 * @return string[] SQLite statements.
	 */
	private function get_sqlite_auto_increment_alter_statements( string $table_schema, string $table_name, string $auto_increment_column, int $minimum_sequence_value ): array {
		$is_temporary    = $this->is_mysql_temporary_schema_name( $table_schema );
		$table_identifier = $is_temporary
			? 'temp.' . $this->connection->quote_identifier( $table_name )
			: $this->connection->quote_identifier( $table_name );
		$sequence_table   = $is_temporary ? 'temp.sqlite_sequence' : 'sqlite_sequence';

		$sequence_value_sql = sprintf(
			'MAX(%d, COALESCE((SELECT MAX(%s) FROM %s), 0))',
			$minimum_sequence_value,
			$this->connection->quote_identifier( $auto_increment_column ),
			$table_identifier
		);

		return array(
			sprintf(
				'DELETE FROM %s WHERE name = %s',
				$sequence_table,
				$this->connection->quote( $table_name )
			),
			sprintf(
				'INSERT INTO %s (name, seq) VALUES (%s, (SELECT %s))',
				$sequence_table,
				$this->connection->quote( $table_name ),
				$sequence_value_sql
			),
		);
	}

	/**
	 * Build a guarded PostgreSQL identity sequence repair query.
	 *
	 * @param string   $table_schema           Backend table schema.
	 * @param string   $table_name             Table name.
	 * @param string   $column_name            Identity column name.
	 * @param string   $sequence_schema        Sequence schema.
	 * @param string   $sequence_name          Sequence name.
	 * @param int|null $minimum_sequence_value Optional minimum last sequence value.
	 * @return array{sql: string, params: array} Query data.
	 */
	private function get_postgresql_identity_sequence_repair_query(
		string $table_schema,
		string $table_name,
		string $column_name,
		string $sequence_schema,
		string $sequence_name,
		?int $minimum_sequence_value = null
	): array {
		$sequence_identifier = $this->get_postgresql_qualified_identifier( $sequence_schema, $sequence_name );
		$table_value_sql     = sprintf(
			'SELECT MAX(%s) AS max_identity_value FROM %s',
			$this->connection->quote_identifier( $column_name ),
			$this->get_postgresql_qualified_identifier( $table_schema, $table_name )
		);
		$positive_guard      = '';
		if ( null !== $minimum_sequence_value ) {
			$table_value_sql = sprintf(
				'SELECT GREATEST(COALESCE(MAX(%s), 0), %d) AS max_identity_value FROM %s',
				$this->connection->quote_identifier( $column_name ),
				max( 0, $minimum_sequence_value ),
				$this->get_postgresql_qualified_identifier( $table_schema, $table_name )
			);
			$positive_guard  = '
				AND table_state.max_identity_value > 0';
		}

		return array(
			'sql'    => sprintf(
				'WITH sequence_state AS (
					SELECT last_value, is_called FROM %1$s
				),
				table_state AS (
					%2$s
				)
				SELECT pg_catalog.setval(CAST(? AS regclass), table_state.max_identity_value, true)
				FROM sequence_state, table_state
				WHERE table_state.max_identity_value IS NOT NULL%3$s
					AND (
						table_state.max_identity_value > sequence_state.last_value
						OR (table_state.max_identity_value = sequence_state.last_value AND NOT sequence_state.is_called)
					)',
				$sequence_identifier,
				$table_value_sql,
				$positive_guard
			),
			'params' => array( $sequence_identifier ),
		);
	}

	/**
	 * Quote a schema-qualified PostgreSQL identifier.
	 *
	 * @param string $schema_name Schema name.
	 * @param string $object_name Object name.
	 * @return string Quoted schema-qualified identifier.
	 */
	private function get_postgresql_qualified_identifier( string $schema_name, string $object_name ): string {
		return $this->connection->quote_identifier( $schema_name ) . '.' . $this->connection->quote_identifier( $object_name );
	}

	/**
	 * Translate simple single-table MySQL UPDATE statements to PostgreSQL.
	 *
	 * WordPress CRUD updates emit a narrow MySQL shape with one table,
	 * backticked identifiers, and plain SET/WHERE clauses. Some plugins use
	 * single-table aliases and ORDER BY forms. Bounded ORDER/LIMIT forms are
	 * rewritten through PostgreSQL ctid subqueries; ORDER BY without LIMIT is
	 * validated but omitted because the same matched row set is updated. Inner
	 * joined UPDATE syntax is rewritten separately to PostgreSQL UPDATE ... FROM.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when the query is unsupported.
	 */
	private function translate_simple_mysql_update_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::UPDATE_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end || ! $this->is_at_mysql_query_end( $tokens, $statement_end ) ) {
			return null;
		}

		$joined_update = $this->translate_mysql_inner_join_update_query( $query, $tokens, $statement_end );
		if ( null !== $joined_update ) {
			return $joined_update;
		}

		$joined_update = $this->translate_mysql_outer_join_update_query( $tokens, $statement_end );
		if ( null !== $joined_update ) {
			return $joined_update;
		}

		$position = 1;
		$this->consume_mysql_update_modifiers( $tokens, $position, $statement_end );

		$table_reference = $this->parse_mysql_main_database_table_reference( $tokens, $position, $statement_end );
		if ( null === $table_reference ) {
			return null;
		}

		$table_name = $table_reference['table'];
		$alias      = $table_reference['alias'];

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::SET_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		++$position;
		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, $position, $statement_end );
		$order_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::ORDER_SYMBOL, $position, $statement_end );
		$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, $position, $statement_end );

		if (
			( null !== $order_position && null !== $where_position && $order_position < $where_position )
			|| ( null !== $limit_position && null !== $where_position && $limit_position < $where_position )
			|| ( null !== $limit_position && null !== $order_position && $limit_position < $order_position )
		) {
			return null;
		}

		$set_end_candidates = array_filter(
			array( $where_position, $order_position, $limit_position ),
			'is_int'
		);
		$set_end            = empty( $set_end_candidates ) ? $statement_end : min( $set_end_candidates );
		if ( ! $this->is_supported_simple_update_set_clause( $table_name, $alias, $tokens, $position, $set_end ) ) {
			return null;
		}

		$unsupported_tokens = array(
			WP_MySQL_Lexer::JOIN_SYMBOL,
			WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL,
		);
		if ( $this->contains_top_level_mysql_token( $tokens, $position, $statement_end, $unsupported_tokens ) ) {
			return null;
		}

		$scope             = $this->get_mysql_single_table_scope( $table_name, $alias );
		$update_set_clause = $this->translate_simple_mysql_update_set_clause( $table_name, $alias, $tokens, $position, $set_end );
		if ( null === $update_set_clause ) {
			return null;
		}

		$table_sql = $this->get_postgresql_dml_table_reference_sql( $table_name, $alias );
		$sql       = sprintf(
			'UPDATE %s SET %s',
			$table_sql,
			$update_set_clause['set_sql']
		);

		$where_end = $order_position ?? $limit_position ?? $statement_end;
		$where_sql = null;
		if ( null !== $where_position ) {
			if (
				$where_position + 1 >= $where_end
				|| ! $this->is_supported_simple_mysql_expression_fragment( $tokens, $where_position + 1, $where_end )
			) {
				return null;
			}

			$where_sql = $this->translate_mysql_predicate_token_sequence_to_postgresql(
				$tokens,
				$where_position + 1,
				$where_end,
				$scope
			);
			$where_sql = $where_sql['sql'];
		}

		$order_sql = '';
		if ( null !== $order_position && null !== $limit_position ) {
			$order_end = $limit_position ?? $statement_end;
			$order_sql = $this->translate_simple_dml_order_by_clause_to_postgresql(
				$tokens,
				$order_position,
				$order_end,
				$table_name,
				$alias
			);
			if ( null === $order_sql ) {
				return null;
			}
		} elseif ( null !== $order_position && ! $this->is_nonempty_mysql_order_by_clause( $tokens, $order_position, $statement_end ) ) {
			return null;
		}

		$limit_sql = '';
		if ( null !== $limit_position ) {
			$limit_sql = $this->translate_simple_dml_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end, true );
			if ( null === $limit_sql ) {
				return null;
			}
		}

		$predicates = array();
		if ( '' !== $limit_sql ) {
			$subquery_where_sql = null === $where_sql ? '' : ' WHERE ' . $where_sql;
			$predicates[]       = sprintf(
				'%s IN (SELECT %s FROM %s%s%s%s)',
				$this->get_postgresql_dml_ctid_reference_sql( $alias ),
				$this->get_postgresql_dml_ctid_reference_sql( $alias ),
				$table_sql,
				$subquery_where_sql,
				$order_sql,
				$limit_sql
			);
		} elseif ( null !== $where_sql ) {
			$predicates[] = $where_sql;
		}
		$predicates[] = $update_set_clause['changed_predicate_sql'];

		if ( count( $predicates ) > 1 ) {
			$sql .= ' WHERE (' . implode( ') AND (', $predicates ) . ')';
		} else {
			$sql .= ' WHERE ' . $predicates[0];
		}

			return $sql;
	}

	/**
	 * Check whether a MySQL multi-table UPDATE was not translated.
	 *
	 * @param string $query MySQL query.
	 * @return bool Whether the query is an unsupported multi-table UPDATE.
	 */
	private function is_unsupported_mysql_multi_table_update_query( string $query ): bool {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::UPDATE_SYMBOL !== $tokens[0]->id ) {
			return false;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end || ! $this->is_at_mysql_query_end( $tokens, $statement_end ) ) {
			return false;
		}

		$set_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::SET_SYMBOL,
			1,
			$statement_end
		);
		if ( null === $set_position ) {
			return false;
		}

		return $this->contains_top_level_mysql_token(
			$tokens,
			1,
			$set_position,
			array(
				WP_MySQL_Lexer::COMMA_SYMBOL,
				WP_MySQL_Lexer::CROSS_SYMBOL,
				WP_MySQL_Lexer::INNER_SYMBOL,
				WP_MySQL_Lexer::JOIN_SYMBOL,
				WP_MySQL_Lexer::LEFT_SYMBOL,
				WP_MySQL_Lexer::NATURAL_SYMBOL,
				WP_MySQL_Lexer::RIGHT_SYMBOL,
				WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL,
			)
		);
	}

	/**
	 * Translate supported MySQL outer-joined UPDATE statements.
	 *
	 * PostgreSQL UPDATE ... FROM does not preserve unmatched outer-join rows.
	 * Select the target row ctid and computed assignment values through the
	 * original joined table reference, then update by ctid from that derived
	 * row set.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $statement_end Final statement token, exclusive.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_mysql_outer_join_update_query( array $tokens, int $statement_end ): ?string {
		$set_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::SET_SYMBOL, 1, $statement_end );
		if ( null === $set_position ) {
			return null;
		}

		$has_left_join  = $this->contains_top_level_mysql_token( $tokens, 1, $set_position, array( WP_MySQL_Lexer::LEFT_SYMBOL ) );
		$has_right_join = $this->contains_top_level_mysql_token( $tokens, 1, $set_position, array( WP_MySQL_Lexer::RIGHT_SYMBOL ) );
		if (
			$has_left_join === $has_right_join
			|| $this->contains_top_level_mysql_token(
				$tokens,
				1,
				$set_position,
				array(
					WP_MySQL_Lexer::NATURAL_SYMBOL,
					WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL,
					WP_MySQL_Lexer::USING_SYMBOL,
				)
			)
		) {
			return null;
		}

		$position = 1;
		$this->consume_mysql_update_modifiers( $tokens, $position, $set_position );

		$target_reference = $this->parse_mysql_main_database_table_reference( $tokens, $position, $set_position );
		if (
			null === $target_reference
			|| $position >= $set_position
		) {
			return null;
		}

		$table_name             = $target_reference['table'];
		$alias                  = $target_reference['alias'];
		$target_reference_alias = null === $alias ? $table_name : $alias;

		$scope = $this->get_mysql_select_scope( $tokens, 1, $set_position );
		if ( null === $scope || ! empty( $scope['unknown'] ) ) {
			return null;
		}

		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, $set_position + 1, $statement_end );
		$order_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::ORDER_SYMBOL, $set_position + 1, $statement_end );
		$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, $set_position + 1, $statement_end );
		$order_end      = $limit_position ?? $statement_end;
		if (
			( null !== $order_position && null !== $where_position && $order_position < $where_position )
			|| ( null !== $limit_position && null !== $where_position && $limit_position < $where_position )
			|| ( null !== $limit_position && null !== $order_position && $limit_position < $order_position )
			|| ( null !== $order_position && ! $this->is_nonempty_mysql_order_by_clause( $tokens, $order_position, $order_end ) )
		) {
			return null;
		}

		$set_end = $where_position ?? $order_position ?? $limit_position ?? $statement_end;
		if ( $set_position + 1 >= $set_end ) {
			return null;
		}

		$update_set_clause = $this->translate_mysql_joined_update_set_clause_for_derived_source(
			$table_name,
			$target_reference_alias,
			$tokens,
			$set_position + 1,
			$set_end,
			$scope
		);
		if ( null === $update_set_clause ) {
			return null;
		}

		$where_sql = '';
		if ( null !== $where_position ) {
			$where_end = $order_position ?? $limit_position ?? $statement_end;
			if (
				$where_position + 1 >= $where_end
				|| ! $this->is_supported_simple_mysql_expression_fragment( $tokens, $where_position + 1, $where_end )
			) {
				return null;
			}

			$where     = $this->translate_mysql_predicate_token_sequence_to_postgresql(
				$tokens,
				$where_position + 1,
				$where_end,
				$scope
			);
			$where_sql = ' WHERE ' . $where['sql'];
		}

		$order_sql = '';
		if ( null !== $order_position && null !== $limit_position ) {
			$order_sql = $this->translate_mysql_joined_dml_order_by_clause_to_postgresql( $tokens, $order_position, $limit_position, $scope );
			if ( null === $order_sql ) {
				return null;
			}
		}

		$limit_sql = '';
		if ( null !== $limit_position ) {
			$limit_sql = $this->translate_simple_dml_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end, true );
			if ( null === $limit_sql ) {
				return null;
			}
		}

		$source_alias      = 'mysql_update_values';
		$source_alias_sql  = $this->connection->quote_identifier( $source_alias );
		$target_ctid_alias = 'mysql_update_target_ctid';
		$target_alias_sql  = $this->connection->quote_identifier( $target_reference_alias );
		$select_values     = array_merge(
			array(
				sprintf(
					'%s.ctid AS %s',
					$target_alias_sql,
					$this->connection->quote_identifier( $target_ctid_alias )
				),
			),
			$update_set_clause['select_sql']
		);
		$source_sql        = sprintf(
			'(SELECT %s FROM %s%s%s%s) AS %s',
			implode( ', ', $select_values ),
			$this->translate_mysql_token_sequence_to_postgresql( $tokens, 1, $set_position ),
			$where_sql,
			$order_sql,
			$limit_sql,
			$source_alias_sql
		);

		return sprintf(
			'UPDATE %s SET %s FROM %s WHERE (%s = %s.%s) AND (%s)',
			$this->get_postgresql_dml_table_reference_sql( $table_name, $alias ),
			$update_set_clause['set_sql'],
			$source_sql,
			$this->get_postgresql_dml_ctid_reference_sql( $alias ),
			$source_alias_sql,
			$this->connection->quote_identifier( $target_ctid_alias ),
			$update_set_clause['changed_predicate_sql']
		);
	}

		/**
		 * Translate a joined UPDATE SET clause for a derived source rewrite.
		 *
		 * @param string           $table_name Table name.
		 * @param string|null      $alias      Target alias.
		 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
		 * @param int              $start      First SET-clause token position.
		 * @param int              $end        Final SET-clause token position, exclusive.
		 * @param array            $scope      Statement table scope.
		 * @param array|null       $information_schema_context Optional direct information_schema context.
		 * @return array{set_sql: string, select_sql: string[], changed_predicate_sql: string}|null PostgreSQL SET data, or null when unsupported.
		 */
	private function translate_mysql_joined_update_set_clause_for_derived_source( string $table_name, ?string $alias, array $tokens, int $start, int $end, array $scope, ?array $information_schema_context = null ): ?array {
		$column_metadata    = $this->get_mysql_dml_column_metadata_lookup( $table_name );
		$assignments        = array();
		$select_expressions = array();
		$changed_predicates = array();
		$source_alias_sql   = $this->connection->quote_identifier( 'mysql_update_values' );
		$value_index        = 0;

		for ( $position = $start; $position < $end; ) {
			$target = $this->parse_simple_mysql_update_assignment_target( $table_name, $alias, $tokens, $position, $end );
			if ( null === $target ) {
				return null;
			}

			$target_column = $target['column'];
			if ( ! isset( $tokens[ $target['end'] ] ) || WP_MySQL_Lexer::EQUAL_OPERATOR !== $tokens[ $target['end'] ]->id ) {
				return null;
			}

			$value_start    = $target['end'] + 1;
			$assignment_end = $this->find_top_level_mysql_token(
				$tokens,
				WP_MySQL_Lexer::COMMA_SYMBOL,
				$value_start,
				$end
			) ?? $end;

			if ( $value_start >= $assignment_end ) {
				return null;
			}

			$target_column_key   = strtolower( $target_column );
			$target_metadata     = $column_metadata[ $target_column_key ] ?? null;
			$coerced_default_sql = null;

			if ( null !== $target_metadata ) {
				$this->validate_strict_mysql_dml_value_for_column( $target_metadata, $tokens, $value_start, $assignment_end );
			}

			if (
				null !== $target_metadata
				&& ! $this->is_mysql_strict_sql_mode_active()
				&& $this->is_mysql_null_token_sequence( $tokens, $value_start, $assignment_end )
			) {
				$coerced_default_sql = $this->get_non_strict_dml_default_sql_for_column( $target_metadata );
			}

			$value_sql = $coerced_default_sql;
			if ( null === $value_sql && null !== $target_metadata ) {
				$value_sql = $this->get_strict_mysql_dml_value_sql_for_column( $target_metadata, $tokens, $value_start, $assignment_end );
			}
			if ( null === $value_sql && null !== $target_metadata ) {
				$value_sql = $this->get_non_strict_mysql_dml_value_sql_for_column( $target_metadata, $tokens, $value_start, $assignment_end );
			}
			if ( null === $value_sql && null !== $information_schema_context ) {
				$value_sql = $this->translate_direct_information_schema_dml_predicate_to_postgresql(
					$tokens,
					$value_start,
					$assignment_end,
					$information_schema_context
				);
				if ( null === $value_sql ) {
					return null;
				}
			}
			if ( null === $value_sql ) {
				$expression_sql = $this->translate_mysql_expression_token_sequence_to_postgresql(
					$tokens,
					$value_start,
					$assignment_end,
					$scope
				);
				$value_sql      = $expression_sql['sql'];
				if (
					$expression_sql['changed']
					&& null !== $target_metadata
					&& $this->is_mysql_text_family_column_type( (string) ( $target_metadata['column_type'] ?? '' ) )
				) {
					$value_sql = sprintf( 'CAST(%s AS text)', $value_sql );
				}
			}

			$value_alias     = 'mysql_update_value_' . $value_index;
			$value_alias_sql = $this->connection->quote_identifier( $value_alias );

			$select_expressions[] = sprintf( '%s AS %s', $value_sql, $value_alias_sql );
			$assignments[]        = sprintf(
				'%s = %s.%s',
				$this->connection->quote_identifier( $target_column ),
				$source_alias_sql,
				$value_alias_sql
			);
			$changed_predicates[] = sprintf(
				'%s IS DISTINCT FROM (%s.%s)',
				$this->get_postgresql_dml_column_reference_sql( $target_column, $alias ),
				$source_alias_sql,
				$value_alias_sql
			);

			++$value_index;
			$position = $assignment_end;
			if ( $position === $end ) {
				break;
			}

			++$position;
		}

		if ( 0 === count( $assignments ) ) {
			return null;
		}

		return array(
			'set_sql'               => implode( ', ', $assignments ),
			'select_sql'            => $select_expressions,
			'changed_predicate_sql' => implode( ' OR ', $changed_predicates ),
		);
	}

	/**
	 * Translate supported MySQL joined and multi-source UPDATE statements.
	 *
	 * PostgreSQL UPDATE ... FROM can represent MySQL single-target UPDATE
	 * statements whose extra table references only qualify the target rows.
	 * Assignments to any non-target table and NATURAL/RIGHT joins remain
	 * unsupported. Bounded single-target joined updates select target ctids
	 * through a derived source before updating; ORDER BY without LIMIT is
	 * validated and omitted because it does not change the affected row set.
	 *
	 * @param string           $query         MySQL query.
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $statement_end Final statement token, exclusive.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_mysql_inner_join_update_query( string $query, array $tokens, int $statement_end ): ?string {
		$set_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::SET_SYMBOL, 1, $statement_end );
		if ( null === $set_position ) {
			return null;
		}

		$position = 1;
		$this->consume_mysql_update_modifiers( $tokens, $position, $set_position );

		$source_start    = $position;
		$first_reference = $this->parse_mysql_main_database_table_reference( $tokens, $position, $set_position );
		if (
			null === $first_reference
			|| $position >= $set_position
		) {
			return null;
		}

		if (
			0 === strcasecmp( $this->db_name, 'information_schema' )
			|| $this->direct_information_schema_source_range_references_information_schema( $tokens, $source_start, $set_position )
		) {
			return $this->translate_mysql_information_schema_join_update_query(
				$query,
				$tokens,
				$statement_end,
				$source_start,
				$set_position,
				$first_reference
			);
		}

		$first_table             = $first_reference['table'];
		$first_alias             = $first_reference['alias'];
		$first_reference_alias   = null === $first_alias ? $first_table : $first_alias;
		$scope                   = $this->get_mysql_single_table_scope( $first_table, $first_alias );
		$from_parts              = array();
		$join_predicates         = array();
		$current_join_left_alias = $first_reference_alias;
		$table_references        = array(
			array(
				'alias'     => $first_reference_alias,
				'alias_key' => strtolower( $first_reference_alias ),
				'table'     => $first_table,
				'table_as'  => $first_alias,
				'derived'   => false,
				'sql'       => $this->get_postgresql_dml_table_reference_sql( $first_table, $first_alias ),
			),
		);

		while ( $position < $set_position ) {
			if ( WP_MySQL_Lexer::COMMA_SYMBOL === ( $tokens[ $position ]->id ?? null ) ) {
				++$position;
				$source_alias     = null;
				$source_reference = null;
				if ( ! $this->append_mysql_joined_update_source_table( $tokens, $position, $set_position, $scope, $from_parts, $source_alias, $source_reference ) ) {
					return null;
				}
				if ( null === $source_reference ) {
					return null;
				}
				$table_references[]     = $source_reference;
				$current_join_left_alias = $source_alias;
				continue;
			}

			if (
				! $this->is_mysql_supported_inner_join_separator_at( $tokens, $position, $set_position )
				|| ! $this->append_mysql_joined_update_inner_join(
					$tokens,
					$position,
					$set_position,
					$scope,
					$from_parts,
					$join_predicates,
					$current_join_left_alias,
					$table_references
				)
			) {
				return null;
			}
		}

		if ( empty( $from_parts ) ) {
			return null;
		}

		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, $set_position + 1, $statement_end );
		$order_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::ORDER_SYMBOL, $set_position + 1, $statement_end );
		$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, $set_position + 1, $statement_end );
		if (
			( null !== $order_position && null !== $where_position && $order_position < $where_position )
			|| ( null !== $limit_position && null !== $where_position && $limit_position < $where_position )
			|| ( null !== $limit_position && null !== $order_position && $limit_position < $order_position )
			|| ( null !== $order_position && ! $this->is_nonempty_mysql_order_by_clause( $tokens, $order_position, $statement_end ) )
		) {
			return null;
		}

		$set_end = $where_position ?? $order_position ?? $limit_position ?? $statement_end;
		if ( $set_position + 1 >= $set_end ) {
			return null;
		}

		$target_reference = $this->get_mysql_joined_update_target_reference(
			$tokens,
			$set_position + 1,
			$set_end,
			$table_references
		);
		if ( null === $target_reference ) {
			return null;
		}

		$table_name             = $target_reference['table'];
		$alias                  = $target_reference['table_as'];
		$target_reference_alias = $target_reference['alias'];
		$from_parts             = array();
		foreach ( $table_references as $table_reference ) {
			if ( $table_reference['alias_key'] === $target_reference['alias_key'] ) {
				continue;
			}
			$from_parts[] = $table_reference['sql'];
		}
		if ( empty( $from_parts ) ) {
			return null;
		}

		$predicates = $join_predicates;
		if ( null !== $where_position ) {
			$where_end = $order_position ?? $limit_position ?? $statement_end;
			if (
				$where_position + 1 >= $where_end
				|| ! $this->is_supported_simple_mysql_expression_fragment( $tokens, $where_position + 1, $where_end )
			) {
				return null;
			}

			$where_sql    = $this->translate_mysql_predicate_token_sequence_to_postgresql(
				$tokens,
				$where_position + 1,
				$where_end,
				$scope
			);
			$predicates[] = $where_sql['sql'];
		}

		if ( null !== $limit_position ) {
			$update_set_clause = $this->translate_mysql_joined_update_set_clause_for_derived_source(
				$table_name,
				$target_reference_alias,
				$tokens,
				$set_position + 1,
				$set_end,
				$scope
			);
			if ( null === $update_set_clause ) {
				return null;
			}

			$order_sql = '';
			if ( null !== $order_position ) {
				$order_sql = $this->translate_mysql_joined_dml_order_by_clause_to_postgresql(
					$tokens,
					$order_position,
					$limit_position,
					$scope
				);
				if ( null === $order_sql ) {
					return null;
				}
			}

			$limit_sql = $this->translate_simple_dml_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end, true );
			if ( null === $limit_sql ) {
				return null;
			}

			$source_alias      = 'mysql_update_values';
			$source_alias_sql  = $this->connection->quote_identifier( $source_alias );
			$target_ctid_alias = 'mysql_update_target_ctid';
			$target_alias_sql  = $this->connection->quote_identifier( $target_reference_alias );
			$select_values     = array_merge(
				array(
					sprintf(
						'%s.ctid AS %s',
						$target_alias_sql,
						$this->connection->quote_identifier( $target_ctid_alias )
					),
				),
				$update_set_clause['select_sql']
			);
			$source_where_sql  = empty( $predicates ) ? '' : ' WHERE (' . implode( ') AND (', $predicates ) . ')';
			$source_sql        = sprintf(
				'(SELECT %s FROM %s%s%s%s) AS %s',
				implode( ', ', $select_values ),
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $source_start, $set_position ),
				$source_where_sql,
				$order_sql,
				$limit_sql,
				$source_alias_sql
			);

			return sprintf(
				'UPDATE %s SET %s FROM %s WHERE (%s = %s.%s) AND (%s)',
				$this->get_postgresql_dml_table_reference_sql( $table_name, $alias ),
				$update_set_clause['set_sql'],
				$source_sql,
				$this->get_postgresql_dml_ctid_reference_sql( $alias ),
				$source_alias_sql,
				$this->connection->quote_identifier( $target_ctid_alias ),
				$update_set_clause['changed_predicate_sql']
			);
		}

		$update_set_clause = $this->translate_simple_mysql_update_set_clause(
			$table_name,
			$target_reference_alias,
			$tokens,
			$set_position + 1,
			$set_end,
			$scope
		);
		if ( null === $update_set_clause ) {
			return null;
		}

		$predicates[] = $update_set_clause['changed_predicate_sql'];

		return sprintf(
			'UPDATE %s SET %s FROM %s WHERE (%s)',
			$this->get_postgresql_dml_table_reference_sql( $table_name, $alias ),
			$update_set_clause['set_sql'],
			implode( ', ', $from_parts ),
			implode( ') AND (', $predicates )
		);
	}

	/**
	 * Translate a joined UPDATE that reads information_schema sources.
	 *
	 * @param string           $query            MySQL query.
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int              $statement_end    Final statement token, exclusive.
	 * @param int              $source_start     First table-reference token after UPDATE modifiers.
	 * @param int              $source_end       SET token position.
	 * @param array            $target_reference Parsed first, writable target reference.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_mysql_information_schema_join_update_query( string $query, array $tokens, int $statement_end, int $source_start, int $source_end, array $target_reference ): ?string {
		$source_translation = $this->get_direct_information_schema_dml_source_translation(
			$query,
			$tokens,
			$source_start,
			$source_end
		);
		if ( null === $source_translation ) {
			return null;
		}

		$table_name             = $target_reference['table'];
		$alias                  = $target_reference['alias'];
		$target_reference_alias = null === $alias ? $table_name : $alias;
		$target_alias_key       = strtolower( $target_reference_alias );
		if (
			! isset( $source_translation['scope']['aliases'][ $target_alias_key ] )
			|| 0 !== strcasecmp( $table_name, (string) $source_translation['scope']['aliases'][ $target_alias_key ]['table'] )
		) {
			return null;
		}

		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, $source_end + 1, $statement_end );
		$order_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::ORDER_SYMBOL, $source_end + 1, $statement_end );
		$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, $source_end + 1, $statement_end );
		if (
			null !== $limit_position
			|| ( null !== $order_position && null !== $where_position && $order_position < $where_position )
			|| ( null !== $order_position && ! $this->is_nonempty_mysql_order_by_clause( $tokens, $order_position, $statement_end ) )
		) {
			return null;
		}

		$set_end = $where_position ?? $order_position ?? $statement_end;
		if ( $source_end + 1 >= $set_end ) {
			return null;
		}

		$update_set_clause = $this->translate_mysql_joined_update_set_clause_for_derived_source(
			$table_name,
			$target_reference_alias,
			$tokens,
			$source_end + 1,
			$set_end,
			$source_translation['scope'],
			$source_translation['context']
		);
		if ( null === $update_set_clause ) {
			return null;
		}

		$where_sql = '';
		if ( null !== $where_position ) {
			$where_end = $order_position ?? $statement_end;
			if ( $where_position + 1 >= $where_end ) {
				return null;
			}

			$where = $this->translate_direct_information_schema_dml_predicate_to_postgresql(
				$tokens,
				$where_position + 1,
				$where_end,
				$source_translation['context']
			);
			if ( null === $where ) {
				return null;
			}

			$where_sql = ' WHERE ' . $where;
		}

		$source_alias      = 'mysql_update_values';
		$source_alias_sql  = $this->connection->quote_identifier( $source_alias );
		$target_ctid_alias = 'mysql_update_target_ctid';
		$target_alias_sql  = $this->connection->quote_identifier( $target_reference_alias );
		$select_values     = array_merge(
			array(
				sprintf(
					'%s.ctid AS %s',
					$target_alias_sql,
					$this->connection->quote_identifier( $target_ctid_alias )
				),
			),
			$update_set_clause['select_sql']
		);
		$source_sql        = sprintf(
			'(SELECT %s FROM %s%s) AS %s',
			implode( ', ', $select_values ),
			$source_translation['sql'],
			$where_sql,
			$source_alias_sql
		);

		return sprintf(
			'UPDATE %s SET %s FROM %s WHERE (%s = %s.%s) AND (%s)',
			$this->get_postgresql_dml_table_reference_sql( $table_name, $alias ),
			$update_set_clause['set_sql'],
			$source_sql,
			$this->get_postgresql_dml_ctid_reference_sql( $alias ),
			$source_alias_sql,
			$this->connection->quote_identifier( $target_ctid_alias ),
			$update_set_clause['changed_predicate_sql']
		);
	}

	/**
	 * Translate supported MySQL multi-target UPDATE statements.
	 *
	 * MySQL can update more than one table in a joined UPDATE. PostgreSQL cannot
	 * express that as one UPDATE ... FROM, so compute the original joined row set
	 * and assignment values once, then update each physical target by ctid.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL writable-CTE query, or null when unsupported.
	 */
	private function translate_mysql_multi_target_update_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::UPDATE_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end || ! $this->is_at_mysql_query_end( $tokens, $statement_end ) ) {
			return null;
		}

		$set_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::SET_SYMBOL, 1, $statement_end );
		if ( null === $set_position ) {
			return null;
		}

		$position = 1;
		$this->consume_mysql_update_modifiers( $tokens, $position, $set_position );

		$first_reference = $this->parse_mysql_main_database_table_reference( $tokens, $position, $set_position );
		if (
			null === $first_reference
			|| $position >= $set_position
		) {
			return null;
		}

		$first_table             = $first_reference['table'];
		$first_alias             = $first_reference['alias'];
		$first_reference_alias   = null === $first_alias ? $first_table : $first_alias;
		$scope                   = $this->get_mysql_single_table_scope( $first_table, $first_alias );
		$from_parts              = array();
		$join_predicates         = array();
		$current_join_left_alias = $first_reference_alias;
		$table_references        = array(
			array(
				'alias'     => $first_reference_alias,
				'alias_key' => strtolower( $first_reference_alias ),
				'table'     => $first_table,
				'table_as'  => $first_alias,
				'derived'   => false,
				'sql'       => $this->get_postgresql_dml_table_reference_sql( $first_table, $first_alias ),
			),
		);

		while ( $position < $set_position ) {
			if ( WP_MySQL_Lexer::COMMA_SYMBOL === ( $tokens[ $position ]->id ?? null ) ) {
				++$position;
				$source_alias     = null;
				$source_reference = null;
				if ( ! $this->append_mysql_joined_update_source_table( $tokens, $position, $set_position, $scope, $from_parts, $source_alias, $source_reference ) ) {
					return null;
				}
				if ( null === $source_reference ) {
					return null;
				}
				$table_references[]     = $source_reference;
				$current_join_left_alias = $source_alias;
				continue;
			}

			if (
				! $this->is_mysql_supported_inner_join_separator_at( $tokens, $position, $set_position )
				|| ! $this->append_mysql_joined_update_inner_join(
					$tokens,
					$position,
					$set_position,
					$scope,
					$from_parts,
					$join_predicates,
					$current_join_left_alias,
					$table_references
				)
			) {
				return null;
			}
		}

		if ( empty( $from_parts ) ) {
			return null;
		}

		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, $set_position + 1, $statement_end );
		$order_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::ORDER_SYMBOL, $set_position + 1, $statement_end );
		$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, $set_position + 1, $statement_end );
		$order_end      = $limit_position ?? $statement_end;
		if (
			( null !== $order_position && null !== $where_position && $order_position < $where_position )
			|| ( null !== $limit_position && null !== $where_position && $limit_position < $where_position )
			|| ( null !== $limit_position && null !== $order_position && $limit_position < $order_position )
			|| ( null !== $order_position && ! $this->is_nonempty_mysql_order_by_clause( $tokens, $order_position, $order_end ) )
		) {
			return null;
		}

		$set_end = $where_position ?? $order_position ?? $limit_position ?? $statement_end;
		if ( $set_position + 1 >= $set_end ) {
			return null;
		}

		$update_set_clause = $this->translate_mysql_multi_target_update_set_clause_for_derived_source(
			$tokens,
			$set_position + 1,
			$set_end,
			$table_references,
			$scope
		);
		if ( null === $update_set_clause || count( $update_set_clause['targets'] ) < 2 ) {
			return null;
		}

		$predicates = $join_predicates;
		if ( null !== $where_position ) {
			$where_end = $order_position ?? $limit_position ?? $statement_end;
			if (
				$where_position + 1 >= $where_end
				|| ! $this->is_supported_simple_mysql_expression_fragment( $tokens, $where_position + 1, $where_end )
			) {
				return null;
			}

			$where_sql    = $this->translate_mysql_predicate_token_sequence_to_postgresql(
				$tokens,
				$where_position + 1,
				$where_end,
				$scope
			);
			$predicates[] = $where_sql['sql'];
		}

		$source_where_sql = empty( $predicates ) ? '' : ' WHERE (' . implode( ') AND (', $predicates ) . ')';
		$order_sql        = '';
		if ( null !== $order_position && null !== $limit_position ) {
			$order_sql = $this->translate_mysql_joined_dml_order_by_clause_to_postgresql( $tokens, $order_position, $limit_position, $scope );
			if ( null === $order_sql ) {
				return null;
			}
		}

		$limit_sql = '';
		if ( null !== $limit_position ) {
			$limit_sql = $this->translate_simple_dml_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end, true );
			if ( null === $limit_sql ) {
				return null;
			}
		}

		$source_sql       = sprintf(
			'mysql_update_rows AS MATERIALIZED (SELECT %s FROM %s%s%s%s)',
			implode( ', ', $update_set_clause['select_sql'] ),
			implode( ', ', array_column( $table_references, 'sql' ) ),
			$source_where_sql,
			$order_sql,
			$limit_sql
		);

		$update_ctes = array();
		$count_parts = array();
		$index       = 0;
		foreach ( $update_set_clause['targets'] as $target ) {
			$cte_name              = 'mysql_update_target_' . $index;
			$target_table_sql      = $this->get_postgresql_dml_table_reference_sql( $target['table'], $target['table_as'] );
			$target_ctid_sql       = $this->get_postgresql_dml_ctid_reference_sql( $target['table_as'] );
			$source_ctid_alias_sql = 'mysql_update_rows.' . $this->connection->quote_identifier( $target['ctid_alias'] );
			$update_ctes[]         = sprintf(
				'%s AS (UPDATE %s SET %s FROM mysql_update_rows WHERE (%s = %s) AND (%s) RETURNING 1)',
				$cte_name,
				$target_table_sql,
				implode( ', ', $target['assignments'] ),
				$target_ctid_sql,
				$source_ctid_alias_sql,
				implode( ' OR ', $target['changed_predicates'] )
			);
			$count_parts[]         = sprintf( '(SELECT COUNT(*) FROM %s)', $cte_name );
			++$index;
		}

		return sprintf(
			'WITH %s, %s SELECT %s AS affected_rows',
			$source_sql,
			implode( ', ', $update_ctes ),
			implode( ' + ', $count_parts )
		);
	}

	/**
	 * Translate a multi-target joined UPDATE SET clause for a writable-CTE rewrite.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int              $start            First SET-clause token position.
	 * @param int              $end              Final SET-clause token position, exclusive.
	 * @param array[]          $table_references Joined table references.
	 * @param array            $scope            Statement table scope.
	 * @return array{select_sql: string[], targets: array<string,array{table: string, table_as: string|null, ctid_alias: string, assignments: string[], changed_predicates: string[]}>}|null PostgreSQL SET data, or null when unsupported.
	 */
	private function translate_mysql_multi_target_update_set_clause_for_derived_source( array $tokens, int $start, int $end, array $table_references, array $scope ): ?array {
		$targets              = array();
		$target_physical_keys = array();
		$select_expressions   = array();
		$value_index          = 0;

		for ( $position = $start; $position < $end; ) {
			$target = $this->parse_mysql_joined_update_assignment_target( $tokens, $position, $end, $table_references );
			if ( null === $target ) {
				return null;
			}

			$target_reference = null;
			foreach ( $table_references as $table_reference ) {
				if ( $target['alias_key'] === $table_reference['alias_key'] ) {
					$target_reference = $table_reference;
					break;
				}
			}

			if (
				null === $target_reference
				|| ! empty( $target_reference['derived'] )
				|| empty( $target_reference['table'] )
			) {
				return null;
			}

			if ( ! isset( $tokens[ $target['end'] ] ) || WP_MySQL_Lexer::EQUAL_OPERATOR !== $tokens[ $target['end'] ]->id ) {
				return null;
			}

			$value_start    = $target['end'] + 1;
			$assignment_end = $this->find_top_level_mysql_token(
				$tokens,
				WP_MySQL_Lexer::COMMA_SYMBOL,
				$value_start,
				$end
			) ?? $end;

			if ( $value_start >= $assignment_end ) {
				return null;
			}

			$table_name          = (string) $target_reference['table'];
			$target_column       = $target['column'];
			$column_metadata     = $this->get_mysql_dml_column_metadata_lookup( $table_name );
			$target_metadata     = $column_metadata[ strtolower( $target_column ) ] ?? null;
			$coerced_default_sql = null;

			if ( null !== $target_metadata ) {
				$this->validate_strict_mysql_dml_value_for_column( $target_metadata, $tokens, $value_start, $assignment_end );
			}

			if (
				null !== $target_metadata
				&& ! $this->is_mysql_strict_sql_mode_active()
				&& $this->is_mysql_null_token_sequence( $tokens, $value_start, $assignment_end )
			) {
				$coerced_default_sql = $this->get_non_strict_dml_default_sql_for_column( $target_metadata );
			}

			$value_sql = $coerced_default_sql;
			if ( null === $value_sql && null !== $target_metadata ) {
				$value_sql = $this->get_strict_mysql_dml_value_sql_for_column( $target_metadata, $tokens, $value_start, $assignment_end );
			}
			if ( null === $value_sql && null !== $target_metadata ) {
				$value_sql = $this->get_non_strict_mysql_dml_value_sql_for_column( $target_metadata, $tokens, $value_start, $assignment_end );
			}
			if ( null === $value_sql ) {
				$expression_sql = $this->translate_mysql_expression_token_sequence_to_postgresql(
					$tokens,
					$value_start,
					$assignment_end,
					$scope
				);
				$value_sql      = $expression_sql['sql'];
				if (
					$expression_sql['changed']
					&& null !== $target_metadata
					&& $this->is_mysql_text_family_column_type( (string) ( $target_metadata['column_type'] ?? '' ) )
				) {
					$value_sql = sprintf( 'CAST(%s AS text)', $value_sql );
				}
			}

			$target_alias_key = $target_reference['alias_key'];
			if ( ! isset( $targets[ $target_alias_key ] ) ) {
				$physical_key = strtolower( 'public.' . $table_name );
				if ( isset( $target_physical_keys[ $physical_key ] ) ) {
					return null;
				}
				$target_physical_keys[ $physical_key ] = true;

				$ctid_alias     = 'mysql_update_' . count( $targets ) . '_ctid';
				$targets[ $target_alias_key ] = array(
					'table'              => $table_name,
					'table_as'           => $target_reference['table_as'],
					'ctid_alias'         => $ctid_alias,
					'assignments'        => array(),
					'changed_predicates' => array(),
				);
				$select_expressions[] = sprintf(
					'%s.ctid AS %s',
					$this->connection->quote_identifier( $target_reference['alias'] ),
					$this->connection->quote_identifier( $ctid_alias )
				);
			}

			$value_alias     = 'mysql_update_value_' . $value_index;
			$value_alias_sql = $this->connection->quote_identifier( $value_alias );
			$source_value_sql = 'mysql_update_rows.' . $value_alias_sql;

			$select_expressions[] = sprintf( '%s AS %s', $value_sql, $value_alias_sql );
			$targets[ $target_alias_key ]['assignments'][] = sprintf(
				'%s = %s',
				$this->connection->quote_identifier( $target_column ),
				$source_value_sql
			);
			$targets[ $target_alias_key ]['changed_predicates'][] = sprintf(
				'%s IS DISTINCT FROM (%s)',
				$this->get_postgresql_dml_column_reference_sql( $target_column, $target_reference['table_as'] ),
				$source_value_sql
			);

			++$value_index;
			$position = $assignment_end;
			if ( $position === $end ) {
				break;
			}

			++$position;
		}

		if ( 0 === count( $targets ) ) {
			return null;
		}

		return array(
			'select_sql' => $select_expressions,
			'targets'    => $targets,
		);
	}

	/**
	 * Consume MySQL UPDATE modifiers that do not change row targeting.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current token position, updated on success.
	 * @param int              $end      Final token position, exclusive.
	 */
	private function consume_mysql_update_modifiers( array $tokens, int &$position, int $end ): void {
		while (
			$position < $end
			&& isset( $tokens[ $position ] )
			&& (
				WP_MySQL_Lexer::LOW_PRIORITY_SYMBOL === $tokens[ $position ]->id
				|| WP_MySQL_Lexer::IGNORE_SYMBOL === $tokens[ $position ]->id
			)
		) {
			++$position;
		}
	}

	/**
	 * Consume MySQL DELETE modifiers that do not change row targeting.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current token position, updated on success.
	 */
	private function consume_mysql_delete_modifiers( array $tokens, int &$position ): void {
		while (
			isset( $tokens[ $position ] )
			&& in_array(
				$tokens[ $position ]->id,
				array(
					WP_MySQL_Lexer::LOW_PRIORITY_SYMBOL,
					WP_MySQL_Lexer::QUICK_SYMBOL,
					WP_MySQL_Lexer::IGNORE_SYMBOL,
				),
				true
			)
		) {
			++$position;
		}
	}

	/**
	 * Consume one MySQL INSERT priority modifier that does not change row values.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current token position, updated on success.
	 */
	private function consume_mysql_insert_priority_modifier( array $tokens, int &$position ): void {
		if (
			isset( $tokens[ $position ] )
			&& in_array(
				$tokens[ $position ]->id,
				array(
					WP_MySQL_Lexer::LOW_PRIORITY_SYMBOL,
					WP_MySQL_Lexer::DELAYED_SYMBOL,
					WP_MySQL_Lexer::HIGH_PRIORITY_SYMBOL,
				),
				true
			)
		) {
			++$position;
		}
	}

	/**
	 * Consume one MySQL REPLACE priority modifier that does not change row values.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current token position, updated on success.
	 */
	private function consume_mysql_replace_priority_modifier( array $tokens, int &$position ): void {
		if (
			isset( $tokens[ $position ] )
			&& in_array(
				$tokens[ $position ]->id,
				array(
					WP_MySQL_Lexer::LOW_PRIORITY_SYMBOL,
					WP_MySQL_Lexer::DELAYED_SYMBOL,
				),
				true
			)
		) {
			++$position;
		}
	}

	/**
	 * Resolve the single target table referenced by a joined UPDATE SET clause.
	 *
	 * @param WP_MySQL_Token[] $tokens                MySQL lexer token stream.
	 * @param int              $start                 First SET-clause token position.
	 * @param int              $end                   Final SET-clause token position, exclusive.
	 * @param array[]          $table_references      Joined table references.
	 * @return array|null Target table reference, or null when unsupported.
	 */
	private function get_mysql_joined_update_target_reference( array $tokens, int $start, int $end, array $table_references ): ?array {
		$target_alias_key = null;

		for ( $position = $start; $position < $end; ) {
			$target = $this->parse_mysql_joined_update_assignment_target( $tokens, $position, $end, $table_references );
			if ( null === $target ) {
				return null;
			}

			if ( null === $target_alias_key ) {
				$target_alias_key = $target['alias_key'];
			} elseif ( $target_alias_key !== $target['alias_key'] ) {
				return null;
			}

			if ( ! isset( $tokens[ $target['end'] ] ) || WP_MySQL_Lexer::EQUAL_OPERATOR !== $tokens[ $target['end'] ]->id ) {
				return null;
			}

			$value_start    = $target['end'] + 1;
			$assignment_end = $this->find_top_level_mysql_token(
				$tokens,
				WP_MySQL_Lexer::COMMA_SYMBOL,
				$value_start,
				$end
			) ?? $end;
			if ( $value_start >= $assignment_end ) {
				return null;
			}

			$position = $assignment_end;
			if ( $position === $end ) {
				break;
			}

			++$position;
		}

		if ( null === $target_alias_key ) {
			return null;
		}

		foreach ( $table_references as $table_reference ) {
			if ( $target_alias_key !== $table_reference['alias_key'] ) {
				continue;
			}

			return empty( $table_reference['derived'] ) ? $table_reference : null;
		}

		return null;
	}

	/**
	 * Parse a joined UPDATE assignment target and resolve its table reference.
	 *
	 * @param WP_MySQL_Token[] $tokens                MySQL lexer token stream.
	 * @param int              $position              Assignment target start.
	 * @param int              $end                   Final SET-clause token position, exclusive.
	 * @param array[]          $table_references      Joined table references.
	 * @return array{alias_key: string, column: string, end: int}|null Target data, or null when unsupported.
	 */
	private function parse_mysql_joined_update_assignment_target( array $tokens, int $position, int $end, array $table_references ): ?array {
		$first_identifier = $this->get_mysql_dml_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $first_identifier ) {
			return null;
		}

		if ( $position + 2 < $end && WP_MySQL_Lexer::DOT_SYMBOL === ( $tokens[ $position + 1 ]->id ?? null ) ) {
			$column = $this->get_mysql_dml_identifier_token_value( $tokens[ $position + 2 ] ?? null );
			if ( null === $column ) {
				return null;
			}

			$target_reference = $this->get_mysql_joined_update_reference_for_qualifier( $first_identifier, $table_references );
			if ( null === $target_reference ) {
				return null;
			}

			return array(
				'alias_key' => $target_reference['alias_key'],
				'column'    => $column,
				'end'       => $position + 3,
			);
		}

		$target_reference = $this->get_mysql_joined_update_reference_for_unqualified_column(
			$first_identifier,
			$table_references
		);
		if ( null === $target_reference ) {
			return null;
		}

		return array(
			'alias_key' => $target_reference['alias_key'],
			'column'    => $first_identifier,
			'end'       => $position + 1,
		);
	}

	/**
	 * Resolve a joined UPDATE table qualifier to a table reference.
	 *
	 * @param string  $qualifier        MySQL table qualifier.
	 * @param array[] $table_references Joined table references.
	 * @return array|null Table reference, or null when ambiguous or unknown.
	 */
	private function get_mysql_joined_update_reference_for_qualifier( string $qualifier, array $table_references ): ?array {
		$qualifier_key = strtolower( $qualifier );
		foreach ( $table_references as $table_reference ) {
			if ( $qualifier_key === $table_reference['alias_key'] ) {
				return $table_reference;
			}
		}

		$matched_reference = null;
		foreach ( $table_references as $table_reference ) {
			if (
				! empty( $table_reference['derived'] )
				|| null === $table_reference['table']
				|| 0 !== strcasecmp( $qualifier, $table_reference['table'] )
			) {
				continue;
			}

			if ( null !== $matched_reference ) {
				return null;
			}

			$matched_reference = $table_reference;
		}

		return $matched_reference;
	}

	/**
	 * Resolve an unqualified joined UPDATE assignment column to one table reference.
	 *
	 * @param string  $column_name      MySQL column name.
	 * @param array[] $table_references Joined table references.
	 * @return array|null Table reference, or null when ambiguous, derived, or unknown.
	 */
	private function get_mysql_joined_update_reference_for_unqualified_column( string $column_name, array $table_references ): ?array {
		$real_table_references = array();
		foreach ( $table_references as $table_reference ) {
			if (
				empty( $table_reference['derived'] )
				&& ! empty( $table_reference['table'] )
			) {
				$real_table_references[] = $table_reference;
			}
		}

		if ( 1 === count( $real_table_references ) ) {
			return $real_table_references[0];
		}

		$matched_reference = null;
		foreach ( $real_table_references as $table_reference ) {
			$table_name   = (string) $table_reference['table'];
			$table_schema = $this->resolve_mysql_table_schema_for_introspection( 'public', $table_name );
			if ( ! $this->mysql_table_has_column_for_translation( $table_schema, $table_name, $column_name ) ) {
				continue;
			}

			if ( null !== $matched_reference ) {
				return null;
			}

			$matched_reference = $table_reference;
		}

		return $matched_reference;
	}

	/**
	 * Check whether a table contains a column for SQL translation decisions.
	 *
	 * @param string $table_schema Backend schema name.
	 * @param string $table_name   Table name.
	 * @param string $column_name  MySQL column name.
	 * @return bool Whether the table contains the column.
	 */
	private function mysql_table_has_column_for_translation( string $table_schema, string $table_name, string $column_name ): bool {
		if ( $this->mysql_table_has_column_metadata( $table_schema, $table_name ) ) {
			return null !== $this->get_mysql_table_column_type( $table_schema, $table_name, $column_name );
		}

		$driver_name = (string) $this->connection->get_pdo()->getAttribute( PDO::ATTR_DRIVER_NAME );
		if ( 'sqlite' === $driver_name ) {
			$schema_prefix = 'temp' === $table_schema ? 'temp.' : '';
			$stmt          = $this->connection->query(
				sprintf(
					'PRAGMA %stable_info(%s)',
					$schema_prefix,
					$this->connection->quote_identifier( $table_name )
				)
			);

			foreach ( $stmt->fetchAll( PDO::FETCH_ASSOC ) as $column ) {
				if ( 0 === strcasecmp( $column_name, (string) ( $column['name'] ?? '' ) ) ) {
					return true;
				}
			}

			return false;
		}

		$stmt = $this->connection->query(
			'SELECT 1
			FROM information_schema.columns
			WHERE table_schema = ?
				AND table_name = ?
				AND LOWER(column_name) = LOWER(?)
			LIMIT 1',
			array( $table_schema, $table_name, $column_name )
		);

		return false !== $stmt->fetchColumn();
	}

	/**
	 * Append a joined UPDATE source table to the UPDATE ... FROM list.
	 *
	 * @param WP_MySQL_Token[] $tokens         MySQL lexer token stream.
	 * @param int              $position       Current source table position, updated on success.
	 * @param int              $end            Final UPDATE table-reference-list token, exclusive.
	 * @param array            $scope          Statement table scope, mutated on success.
	 * @param string[]         $from_parts     PostgreSQL FROM items, mutated on success.
	 * @param string|null      $appended_alias Joined table alias, mutated on success.
	 * @return bool Whether a table source was appended.
	 */
	private function append_mysql_joined_update_source_table( array $tokens, int &$position, int $end, array &$scope, array &$from_parts, ?string &$appended_alias, ?array &$appended_reference = null ): bool {
		$derived_reference = $this->parse_mysql_joined_update_derived_table_source( $tokens, $position, $end );
		if ( null !== $derived_reference ) {
			$joined_alias_key = strtolower( $derived_reference['alias'] );
			if ( isset( $scope['aliases'][ $joined_alias_key ] ) ) {
				return false;
			}

			$scope['aliases'][ $joined_alias_key ] = array(
				'schema'  => null,
				'table'   => null,
				'derived' => true,
			);
			$scope['unknown']                    = true;
			$from_parts[]                        = $derived_reference['sql'];
			$appended_alias                      = $derived_reference['alias'];
			$appended_reference                  = array(
				'alias'     => $derived_reference['alias'],
				'alias_key' => $joined_alias_key,
				'table'     => null,
				'table_as'  => null,
				'derived'   => true,
				'sql'       => $derived_reference['sql'],
			);

			return true;
		}

		$joined_reference = $this->parse_mysql_main_database_table_reference( $tokens, $position, $end );
		if ( null === $joined_reference ) {
			return false;
		}

		$joined_alias     = null === $joined_reference['alias'] ? $joined_reference['table'] : $joined_reference['alias'];
		$joined_alias_key = strtolower( $joined_alias );
		if ( isset( $scope['aliases'][ $joined_alias_key ] ) ) {
			return false;
		}

		$joined_table = array(
			'schema' => $this->resolve_mysql_table_schema_for_introspection( 'public', $joined_reference['table'] ),
			'table'  => $joined_reference['table'],
		);

		$scope['tables'][]                     = $joined_table;
		$scope['aliases'][ $joined_alias_key ] = $joined_table;

		$source_sql = $this->get_postgresql_dml_table_reference_sql(
			$joined_reference['table'],
			$joined_reference['alias']
		);
		$from_parts[]        = $source_sql;
		$appended_alias      = $joined_alias;
		$appended_reference  = array(
			'alias'     => $joined_alias,
			'alias_key' => $joined_alias_key,
			'table'     => $joined_reference['table'],
			'table_as'  => $joined_reference['alias'],
			'derived'   => false,
			'sql'       => $source_sql,
		);

		return true;
	}

	/**
	 * Parse a parenthesized SELECT source for a joined UPDATE.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Current source table position, updated on success.
	 * @param int              $end      Final UPDATE table-reference-list token, exclusive.
	 * @return array{alias: string, sql: string}|null Derived source data, or null when unsupported.
	 */
	private function parse_mysql_joined_update_derived_table_source( array $tokens, int &$position, int $end ): ?array {
		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position ]->id
			|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return null;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
		if ( null === $after_close ) {
			return null;
		}

		$select_start  = $position + 1;
		$select_end    = $after_close - 1;
		$locking_start = $this->find_mysql_select_row_locking_clause_start( $tokens, $select_start + 1, $select_end );
		if ( null !== $locking_start ) {
			$select_end = $locking_start;
		}
		if ( $this->mysql_select_range_requires_direct_information_schema_rewrite( $tokens, $select_start, $select_end ) ) {
			return null;
		}

		$alias_position = $after_close;
		if ( $alias_position < $end && WP_MySQL_Lexer::AS_SYMBOL === ( $tokens[ $alias_position ]->id ?? null ) ) {
			++$alias_position;
		}

		$alias = $this->get_mysql_identifier_token_value( $tokens[ $alias_position ] ?? null );
		if ( null === $alias ) {
			return null;
		}

		$position = $alias_position + 1;

		return array(
			'alias' => $alias,
			'sql'   => sprintf(
				'(%s) AS %s',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $select_start, $select_end ),
				$this->connection->quote_identifier( $alias )
			),
		);
	}

	/**
	 * Append a joined UPDATE inner join source and ON/USING predicate.
	 *
	 * @param WP_MySQL_Token[] $tokens          MySQL lexer token stream.
	 * @param int              $position        Current join separator position, updated on success.
	 * @param int              $end             Final UPDATE table-reference-list token, exclusive.
	 * @param array            $scope           Statement table scope, mutated on success.
	 * @param string[]         $from_parts      PostgreSQL FROM items, mutated on success.
	 * @param string[]         $join_predicates PostgreSQL join predicates, mutated on success.
	 * @param string           $left_alias      Alias for the joined table expression's left side, mutated on success.
	 * @param array[]          $table_references Joined table references, mutated on success.
	 * @return bool Whether an inner join source was appended.
	 */
	private function append_mysql_joined_update_inner_join( array $tokens, int &$position, int $end, array &$scope, array &$from_parts, array &$join_predicates, string &$left_alias, array &$table_references ): bool {
		$predicate_optional = false;
		if ( WP_MySQL_Lexer::INNER_SYMBOL === ( $tokens[ $position ]->id ?? null ) ) {
			++$position;
			if ( WP_MySQL_Lexer::JOIN_SYMBOL !== ( $tokens[ $position ]->id ?? null ) ) {
				return false;
			}
			++$position;
		} elseif ( WP_MySQL_Lexer::CROSS_SYMBOL === ( $tokens[ $position ]->id ?? null ) ) {
			++$position;
			if ( WP_MySQL_Lexer::JOIN_SYMBOL !== ( $tokens[ $position ]->id ?? null ) ) {
				return false;
			}
			++$position;
			$predicate_optional = true;
		} elseif ( WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL === ( $tokens[ $position ]->id ?? null ) ) {
			++$position;
			$predicate_optional = true;
		} else {
			if ( WP_MySQL_Lexer::JOIN_SYMBOL !== ( $tokens[ $position ]->id ?? null ) ) {
				return false;
			}
			++$position;
		}

		$joined_alias     = null;
		$joined_reference = null;
		if ( ! $this->append_mysql_joined_update_source_table( $tokens, $position, $end, $scope, $from_parts, $joined_alias, $joined_reference ) ) {
			return false;
		}
		if ( null === $joined_reference ) {
			return false;
		}
		$table_references[] = $joined_reference;

		if ( WP_MySQL_Lexer::ON_SYMBOL === ( $tokens[ $position ]->id ?? null ) ) {
			$predicate_start = $position + 1;
			$predicate_end   = $this->find_mysql_join_separator( $tokens, $predicate_start, $end ) ?? $end;
			if (
				$predicate_start >= $predicate_end
				|| ! $this->is_supported_simple_mysql_expression_fragment( $tokens, $predicate_start, $predicate_end )
			) {
				return false;
			}

			$predicate_sql     = $this->translate_mysql_predicate_token_sequence_to_postgresql(
				$tokens,
				$predicate_start,
				$predicate_end,
				$scope
			);
			$join_predicates[] = $predicate_sql['sql'];
			$position          = $predicate_end;
			$left_alias        = $joined_alias;

			return true;
		}

		if ( WP_MySQL_Lexer::USING_SYMBOL !== ( $tokens[ $position ]->id ?? null ) ) {
			if ( $predicate_optional ) {
				$left_alias = $joined_alias;
				return true;
			}
			return false;
		}

		$using_position = $position + 1;
		$using_columns  = $this->parse_mysql_identifier_list( $tokens, $using_position );
		if ( null === $using_columns ) {
			return false;
		}

		foreach ( $using_columns as $using_column ) {
			$left_alias_sql    = $this->translate_mysql_identifier_value_to_postgresql( $left_alias );
			$joined_alias_sql  = $this->translate_mysql_identifier_value_to_postgresql( $joined_alias );
			$using_column_sql  = $this->translate_mysql_identifier_value_to_postgresql( $using_column );
			$join_predicates[] = sprintf(
				'%s.%s = %s.%s',
				$left_alias_sql,
				$using_column_sql,
				$joined_alias_sql,
				$using_column_sql
			);
		}

		$position   = $using_position;
		$left_alias = $joined_alias;

		return true;
	}

		/**
		 * Find the next top-level MySQL join separator.
		 *
		 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
		 * @param int              $start  First token position.
		 * @param int              $end    Final token position, exclusive.
		 * @return int|null Join separator position, or null when none exists.
		 */
	private function find_mysql_join_separator( array $tokens, int $start, int $end ): ?int {
		return $this->find_first_top_level_mysql_token(
			$tokens,
			array(
				WP_MySQL_Lexer::COMMA_SYMBOL,
				WP_MySQL_Lexer::CROSS_SYMBOL,
				WP_MySQL_Lexer::INNER_SYMBOL,
				WP_MySQL_Lexer::JOIN_SYMBOL,
				WP_MySQL_Lexer::LEFT_SYMBOL,
				WP_MySQL_Lexer::NATURAL_SYMBOL,
				WP_MySQL_Lexer::RIGHT_SYMBOL,
				WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL,
			),
			$start,
			$end
		);
	}

	/**
	 * Check whether a position starts a supported inner join separator.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Candidate token position.
	 * @param int              $end      Final token position, exclusive.
	 * @return bool Whether the separator is a supported inner-style join.
	 */
	private function is_mysql_supported_inner_join_separator_at( array $tokens, int $position, int $end ): bool {
		if ( $position >= $end ) {
			return false;
		}

		if (
			WP_MySQL_Lexer::JOIN_SYMBOL === ( $tokens[ $position ]->id ?? null )
			|| WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL === ( $tokens[ $position ]->id ?? null )
		) {
			return true;
		}

		return $position + 1 < $end
			&& (
				WP_MySQL_Lexer::INNER_SYMBOL === ( $tokens[ $position ]->id ?? null )
				|| WP_MySQL_Lexer::CROSS_SYMBOL === ( $tokens[ $position ]->id ?? null )
			)
			&& WP_MySQL_Lexer::JOIN_SYMBOL === ( $tokens[ $position + 1 ]->id ?? null );
	}

	/**
	 * Get metadata-derived defaults for omitted NOT NULL columns in non-strict DML.
	 *
	 * @param string     $table_name      Table name.
	 * @param string[]   $columns         Supplied DML columns.
	 * @param array|null $column_metadata Optional ordered column metadata rows.
	 * @return array[] Default column descriptors.
	 */
	private function get_non_strict_dml_defaults_for_omitted_columns( string $table_name, array $columns, ?array $column_metadata = null ): array {
		if ( $this->is_mysql_strict_sql_mode_active() ) {
			return array();
		}

		$supplied_columns = array();
		foreach ( $columns as $column ) {
			$supplied_columns[ strtolower( (string) $column ) ] = true;
		}

		if ( null === $column_metadata ) {
			$column_metadata = $this->get_mysql_dml_column_metadata( $table_name );
		}

		$defaults = array();
		foreach ( $column_metadata as $column_metadata_row ) {
			$column_name = (string) ( $column_metadata_row['column_name'] ?? '' );
			if ( '' === $column_name || isset( $supplied_columns[ strtolower( $column_name ) ] ) ) {
				continue;
			}

			$default_sql = $this->get_non_strict_dml_default_sql_for_column( $column_metadata_row );
			if ( null === $default_sql ) {
				continue;
			}

			$defaults[] = array(
				'column' => $column_name,
				'sql'    => $default_sql,
			);

			$supplied_columns[ strtolower( $column_name ) ] = true;
		}

		return $defaults;
	}

	/**
	 * Append metadata-derived defaults for omitted NOT NULL columns in non-strict DML.
	 *
	 * @param string     $table_name      Table name.
	 * @param string[]   $columns         DML columns, mutated when defaults are appended.
	 * @param string[]   $values          DML values, mutated when defaults are appended.
	 * @param array|null $column_metadata Optional ordered column metadata rows.
	 */
	private function append_non_strict_dml_defaults_for_omitted_columns( string $table_name, array &$columns, array &$values, ?array $column_metadata = null ): void {
		if ( $this->is_mysql_strict_sql_mode_active() ) {
			return;
		}

		$supplied_columns = array();
		foreach ( $columns as $column ) {
			$supplied_columns[ strtolower( (string) $column ) ] = true;
		}

		if ( null === $column_metadata ) {
			if ( null === $column_metadata ) {
				$column_metadata = $this->get_mysql_dml_column_metadata( $table_name );
			}
		}

		foreach ( $column_metadata as $column_metadata_row ) {
			$column_name = (string) ( $column_metadata_row['column_name'] ?? '' );
			if ( '' === $column_name || isset( $supplied_columns[ strtolower( $column_name ) ] ) ) {
				continue;
			}

			$default_sql = $this->get_non_strict_dml_default_sql_for_column( $column_metadata_row );
			if ( null === $default_sql ) {
				continue;
			}

			$columns[] = $column_name;
			$values[]  = $default_sql;

			$supplied_columns[ strtolower( $column_name ) ] = true;
		}
	}

	/**
	 * Append metadata-derived defaults to every VALUES row for omitted NOT NULL columns.
	 *
	 * @param string     $table_name      Table name.
	 * @param string[]   $columns         DML columns, mutated when defaults are appended.
	 * @param array[]    $value_rows      DML value rows, mutated when defaults are appended.
	 * @param array|null $column_metadata Optional ordered column metadata rows.
	 */
	private function append_non_strict_dml_defaults_for_omitted_value_rows( string $table_name, array &$columns, array &$value_rows, ?array $column_metadata = null ): void {
		if ( $this->is_mysql_strict_sql_mode_active() ) {
			return;
		}

		$supplied_columns = array();
		foreach ( $columns as $column ) {
			$supplied_columns[ strtolower( (string) $column ) ] = true;
		}

		if ( null === $column_metadata ) {
			$column_metadata = $this->get_mysql_dml_column_metadata( $table_name );
		}

		$default_sql_values = array();
		foreach ( $column_metadata as $column_metadata_row ) {
			$column_name = (string) ( $column_metadata_row['column_name'] ?? '' );
			if ( '' === $column_name || isset( $supplied_columns[ strtolower( $column_name ) ] ) ) {
				continue;
			}

			$default_sql = $this->get_non_strict_dml_default_sql_for_column( $column_metadata_row );
			if ( null === $default_sql ) {
				continue;
			}

			$columns[]            = $column_name;
			$default_sql_values[] = $default_sql;

			$supplied_columns[ strtolower( $column_name ) ] = true;
		}

		if ( empty( $default_sql_values ) ) {
			return;
		}

		foreach ( $value_rows as &$values ) {
			foreach ( $default_sql_values as $default_sql ) {
				$values[] = $default_sql;
			}
		}
		unset( $values );
	}

	/**
	 * Translate a supported simple UPDATE SET clause with non-strict NULL coercion.
	 *
	 * @param string           $table_name Table name.
	 * @param string|null      $alias      Optional table alias.
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param int              $start      First SET-clause token position.
	 * @param int              $end        Final SET-clause token position, exclusive.
	 * @return array{set_sql: string, changed_predicate_sql: string}|null PostgreSQL SET data, or null when unsupported.
	 */
	private function translate_simple_mysql_update_set_clause( string $table_name, ?string $alias, array $tokens, int $start, int $end, ?array $scope = null ): ?array {
		$column_metadata    = $this->get_mysql_dml_column_metadata_lookup( $table_name );
		$assignments        = array();
		$changed_predicates = array();
		$scope              = $scope ?? $this->get_mysql_single_table_scope( $table_name, $alias );

		for ( $position = $start; $position < $end; ) {
			$target = $this->parse_simple_mysql_update_assignment_target( $table_name, $alias, $tokens, $position, $end );
			if ( null === $target ) {
				return null;
			}

			$target_column = $target['column'];
			if ( ! isset( $tokens[ $target['end'] ] ) || WP_MySQL_Lexer::EQUAL_OPERATOR !== $tokens[ $target['end'] ]->id ) {
				return null;
			}

			$value_start    = $target['end'] + 1;
			$assignment_end = $this->find_top_level_mysql_token(
				$tokens,
				WP_MySQL_Lexer::COMMA_SYMBOL,
				$value_start,
				$end
			) ?? $end;

			if ( $value_start >= $assignment_end ) {
				return null;
			}

			$target_column_key   = strtolower( $target_column );
			$target_metadata     = $column_metadata[ $target_column_key ] ?? null;
			$coerced_default_sql = null;

			if ( null !== $target_metadata ) {
				$this->validate_strict_mysql_dml_value_for_column( $target_metadata, $tokens, $value_start, $assignment_end );
			}

			if (
				null !== $target_metadata
				&& ! $this->is_mysql_strict_sql_mode_active()
				&& $this->is_mysql_null_token_sequence( $tokens, $value_start, $assignment_end )
			) {
				$coerced_default_sql = $this->get_non_strict_dml_default_sql_for_column( $target_metadata );
			}

			$value_sql = $coerced_default_sql;
			if ( null === $value_sql && null !== $target_metadata ) {
				$value_sql = $this->get_strict_mysql_dml_value_sql_for_column( $target_metadata, $tokens, $value_start, $assignment_end );
			}
			if ( null === $value_sql && null !== $target_metadata ) {
				$value_sql = $this->get_non_strict_mysql_dml_value_sql_for_column( $target_metadata, $tokens, $value_start, $assignment_end );
			}
			if ( null === $value_sql ) {
				$expression_sql = $this->translate_mysql_expression_token_sequence_to_postgresql(
					$tokens,
					$value_start,
					$assignment_end,
					$scope
				);
				$value_sql      = $expression_sql['sql'];
				if (
					$expression_sql['changed']
					&& null !== $target_metadata
					&& $this->is_mysql_text_family_column_type( (string) ( $target_metadata['column_type'] ?? '' ) )
				) {
					$value_sql = sprintf( 'CAST(%s AS text)', $value_sql );
				}
			}

			$quoted_target_column = $this->connection->quote_identifier( $target_column );
			$assignments[]        = sprintf(
				'%s = %s',
				$quoted_target_column,
				$value_sql
			);
			$changed_predicates[] = sprintf(
				'%s IS DISTINCT FROM (%s)',
				$this->get_postgresql_dml_column_reference_sql( $target_column, $alias ),
				$value_sql
			);

			$position = $assignment_end;
			if ( $position === $end ) {
				break;
			}

			++$position;
		}

		if ( 0 === count( $assignments ) ) {
			return null;
		}

		return array(
			'set_sql'               => implode( ', ', $assignments ),
			'changed_predicate_sql' => implode( ' OR ', $changed_predicates ),
		);
	}

	/**
	 * Parse the target column for a simple UPDATE assignment.
	 *
	 * @param string           $table_name Table name.
	 * @param string|null      $alias      Optional table alias.
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param int              $position   Assignment target start.
	 * @param int              $end        Final SET-clause token position, exclusive.
	 * @return array{column: string, end: int}|null Assignment target, or null when unsupported.
	 */
	private function parse_simple_mysql_update_assignment_target( string $table_name, ?string $alias, array $tokens, int $position, int $end ): ?array {
		$first_identifier = $this->get_mysql_dml_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $first_identifier ) {
			return null;
		}

		if ( $position + 2 < $end && WP_MySQL_Lexer::DOT_SYMBOL === ( $tokens[ $position + 1 ]->id ?? null ) ) {
			$column = $this->get_mysql_dml_identifier_token_value( $tokens[ $position + 2 ] ?? null );
			if ( null === $column || ! $this->is_mysql_dml_table_qualifier( $first_identifier, $table_name, $alias ) ) {
				return null;
			}

			return array(
				'column' => $column,
				'end'    => $position + 3,
			);
		}

		return array(
			'column' => $first_identifier,
			'end'    => $position + 1,
		);
	}

	/**
	 * Rewrite MySQL AUTO_INCREMENT zero literals to generated values when the mode permits it.
	 *
	 * @param string[]         $columns      DML columns.
	 * @param string[]         $values       Translated DML values, mutated when needed.
	 * @param array[]          $value_ranges Original token ranges for each value.
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param array[]          $metadata     Ordered column metadata rows.
	 */
	private function normalize_mysql_auto_increment_zero_values_for_columns( array $columns, array &$values, array $value_ranges, array $tokens, array $metadata ): void {
		if ( $this->is_mysql_sql_mode_active( 'NO_AUTO_VALUE_ON_ZERO' ) ) {
			return;
		}

		$column_metadata = $this->get_mysql_dml_column_metadata_lookup_from_rows( $metadata );
		foreach ( $columns as $index => $column ) {
			$column_key = strtolower( (string) $column );
			if (
				! isset( $column_metadata[ $column_key ], $value_ranges[ $index ] )
				|| ! $this->is_mysql_auto_increment_column_metadata( $column_metadata[ $column_key ] )
				|| ! isset( $value_ranges[ $index ]['start'], $value_ranges[ $index ]['end'] )
				|| ! isset( $values[ $index ] )
			) {
				continue;
			}

			if ( ! $this->is_mysql_zero_literal_range( $tokens, (int) $value_ranges[ $index ]['start'], (int) $value_ranges[ $index ]['end'] ) ) {
				continue;
			}

			$values[ $index ] = $this->get_mysql_auto_increment_generated_value_sql();
		}
	}

	/**
	 * Get the SQL value that asks the backend to generate an AUTO_INCREMENT value.
	 *
	 * @return string Backend-compatible generated value marker.
	 */
	private function get_mysql_auto_increment_generated_value_sql(): string {
		$driver_name = (string) $this->connection->get_pdo()->getAttribute( PDO::ATTR_DRIVER_NAME );
		return 'sqlite' === $driver_name ? 'NULL' : 'DEFAULT';
	}

	/**
	 * Get the SQL expression that generates an AUTO_INCREMENT value in INSERT ... SELECT.
	 *
	 * @param string $table_name      Target table name.
	 * @param array  $column_metadata Target column metadata.
	 * @return string Backend-compatible generated value expression.
	 */
	private function get_mysql_insert_select_auto_increment_generated_value_sql( string $table_name, array $column_metadata ): string {
		$driver_name = (string) $this->connection->get_pdo()->getAttribute( PDO::ATTR_DRIVER_NAME );
		if ( 'sqlite' === $driver_name ) {
			return 'NULL';
		}

		$column_name  = (string) ( $column_metadata['column_name'] ?? '' );
		$table_schema = $this->resolve_mysql_table_schema_for_introspection( 'public', $table_name );

		return sprintf(
			'nextval(pg_get_serial_sequence(%s, %s))',
			$this->connection->quote( $table_schema . '.' . $table_name ),
			$this->connection->quote( $column_name )
		);
	}

	/**
	 * Check whether SQL asks the backend to generate an AUTO_INCREMENT value.
	 *
	 * @param string $value_sql Translated value SQL.
	 * @return bool Whether this value has no explicit conflict key.
	 */
	private function is_mysql_generated_auto_increment_value_sql( string $value_sql ): bool {
		return in_array( strtoupper( trim( $value_sql ) ), array( 'DEFAULT', 'NULL' ), true );
	}

	/**
	 * Validate strict-mode DML values using MySQL column metadata.
	 *
	 * @param string[]         $columns      DML columns.
	 * @param array[]          $value_ranges Original token ranges for each value.
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param array[]          $metadata     Ordered column metadata rows.
	 */
	private function validate_strict_mysql_dml_values_for_columns( array $columns, array $value_ranges, array $tokens, array $metadata ): void {
		if ( ! $this->is_mysql_strict_sql_mode_active() ) {
			return;
		}

		$column_metadata = $this->get_mysql_dml_column_metadata_lookup_from_rows( $metadata );
		foreach ( $columns as $index => $column ) {
			$column_key = strtolower( (string) $column );
			if (
				! isset( $column_metadata[ $column_key ], $value_ranges[ $index ] )
				|| ! isset( $value_ranges[ $index ]['start'], $value_ranges[ $index ]['end'] )
			) {
				continue;
			}

			$this->validate_strict_mysql_dml_value_for_column(
				$column_metadata[ $column_key ],
				$tokens,
				(int) $value_ranges[ $index ]['start'],
				(int) $value_ranges[ $index ]['end']
			);
		}
	}

	/**
	 * Validate a strict-mode DML value for one column.
	 *
	 * @param array            $column_metadata Column metadata row.
	 * @param WP_MySQL_Token[] $tokens          MySQL lexer token stream.
	 * @param int              $start           First value token position.
	 * @param int              $end             Final value token position, exclusive.
	 */
	private function validate_strict_mysql_dml_value_for_column( array $column_metadata, array $tokens, int $start, int $end ): void {
		if ( ! $this->is_mysql_strict_sql_mode_active() ) {
			return;
		}

		$this->get_strict_mysql_dml_value_sql_for_column( $column_metadata, $tokens, $start, $end );
	}

	/**
	 * Get strict-mode SQL for a MySQL-compatible DML literal when normalization is needed.
	 *
	 * @param array            $column_metadata Column metadata row.
	 * @param WP_MySQL_Token[] $tokens          MySQL lexer token stream.
	 * @param int              $start           First value token position.
	 * @param int              $end             Final value token position, exclusive.
	 * @return string|null PostgreSQL value SQL, or null when generic translation is sufficient.
	 */
	private function get_strict_mysql_dml_value_sql_for_column( array $column_metadata, array $tokens, int $start, int $end ): ?string {
		if ( ! $this->is_mysql_strict_sql_mode_active() ) {
			return null;
		}

		$this->validate_strict_mysql_dml_text_length_for_column( $column_metadata, $tokens, $start, $end );
		$text_hex_sql = $this->get_mysql_text_hex_literal_sql_for_column( $column_metadata, $tokens, $start, $end );
		if ( null !== $text_hex_sql ) {
			return $text_hex_sql;
		}

		$base_type = $this->get_base_mysql_dml_column_type( (string) ( $column_metadata['column_type'] ?? '' ) );

		if ( in_array( $base_type, array( 'date', 'datetime', 'timestamp' ), true ) ) {
			return $this->get_strict_mysql_dml_date_time_literal_sql_for_column( $base_type, $tokens, $start, $end );
		}

		if ( 'year' === $base_type ) {
			return $this->get_mysql_dml_year_literal_sql_for_column( $tokens, $start, $end );
		}

		return $this->get_strict_mysql_dml_integer_literal_sql_for_column( $column_metadata, $tokens, $start, $end );
	}

	/**
	 * Get strict-mode SQL for DATE/DATETIME/TIMESTAMP literals.
	 *
	 * @param string           $base_type Base MySQL column type.
	 * @param WP_MySQL_Token[] $tokens    MySQL lexer token stream.
	 * @param int              $start     First value token position.
	 * @param int              $end       Final value token position, exclusive.
	 * @return string|null PostgreSQL value SQL, or null when the token range is not a simple literal.
	 */
	private function get_strict_mysql_dml_date_time_literal_sql_for_column( string $base_type, array $tokens, int $start, int $end ): ?string {
		$literal = $this->get_mysql_dml_literal_value( $tokens, $start, $end );
		if ( null === $literal || null === $literal['value'] ) {
			return null;
		}

		$value = $literal['value'];
		if ( 'string' !== $literal['type'] ) {
			$this->throw_mysql_incorrect_temporal_value( $base_type, $value );
		}

		if ( 'date' === $base_type ) {
			$storage_value = $this->get_strict_mysql_dml_date_storage_value( $value );
		} else {
			$storage_value = $this->get_strict_mysql_dml_datetime_storage_value( $base_type, $value );
		}

		if ( $storage_value === $value ) {
			return null;
		}

		return $this->connection->quote( $storage_value );
	}

	/**
	 * Get strict-mode storage value for a MySQL DATE literal.
	 *
	 * @param string $value Unquoted literal value.
	 * @return string Normalized storage value.
	 */
	private function get_strict_mysql_dml_date_storage_value( string $value ): string {
		$date_value = $this->normalize_mysql_dml_date_literal_format( $value );
		$parts      = $this->get_mysql_dml_date_parts( $date_value );
		if ( null === $parts ) {
			$this->throw_mysql_incorrect_temporal_value( 'date', $value );
		}

		$this->validate_strict_mysql_dml_date_parts( 'date', $value, $parts['year'], $parts['month'], $parts['day'] );
		return $date_value;
	}

	/**
	 * Validate a strict-mode MySQL DATE literal.
	 *
	 * @param string $value Unquoted literal value.
	 */
	private function validate_strict_mysql_dml_date_value( string $value ): void {
		$this->get_strict_mysql_dml_date_storage_value( $value );
	}

	/**
	 * Get strict-mode storage value for a MySQL DATETIME/TIMESTAMP literal.
	 *
	 * @param string $base_type Base MySQL column type.
	 * @param string $value     Unquoted literal value.
	 * @return string Normalized storage value.
	 */
	private function get_strict_mysql_dml_datetime_storage_value( string $base_type, string $value ): string {
		$normalized_value = $this->normalize_mysql_dml_datetime_literal_format( $value );
		$parts            = $this->get_mysql_dml_datetime_parts( $normalized_value );
		if ( null === $parts ) {
			$date_parts = $this->get_mysql_dml_date_parts( $normalized_value );
			if ( null === $date_parts ) {
				$this->throw_mysql_incorrect_temporal_value( $base_type, $value );
			}

			$this->validate_strict_mysql_dml_date_parts( $base_type, $value, $date_parts['year'], $date_parts['month'], $date_parts['day'] );
			return $normalized_value . ' 00:00:00';
		}

		if ( ! $this->is_mysql_dml_time_value_valid( $parts['hour'], $parts['minute'], $parts['second'] ) ) {
			$this->throw_mysql_incorrect_temporal_value( $base_type, $value );
		}

		$this->validate_strict_mysql_dml_date_parts( $base_type, $value, $parts['year'], $parts['month'], $parts['day'] );
		return $normalized_value;
	}

	/**
	 * Validate a strict-mode MySQL DATETIME/TIMESTAMP literal.
	 *
	 * @param string $base_type Base MySQL column type.
	 * @param string $value     Unquoted literal value.
	 */
	private function validate_strict_mysql_dml_datetime_value( string $base_type, string $value ): void {
		$this->get_strict_mysql_dml_datetime_storage_value( $base_type, $value );
	}

	/**
	 * Validate strict-mode MySQL date parts for zero-date modes and calendar validity.
	 *
	 * @param string $type  MySQL temporal type label.
	 * @param string $value Original unquoted literal value.
	 * @param string $year  Four-digit year.
	 * @param string $month Two-digit month.
	 * @param string $day   Two-digit day.
	 */
	private function validate_strict_mysql_dml_date_parts( string $type, string $value, string $year, string $month, string $day ): void {
		if ( '0000' === $year && '00' === $month && '00' === $day ) {
			if ( $this->is_mysql_sql_mode_active( 'NO_ZERO_DATE' ) ) {
				$this->throw_mysql_incorrect_temporal_value( $type, $value );
			}

			return;
		}

		if ( '0000' !== $year && ( '00' === $month || '00' === $day ) ) {
			if ( $this->is_mysql_sql_mode_active( 'NO_ZERO_IN_DATE' ) ) {
				$this->throw_mysql_incorrect_temporal_value( $type, $value );
			}

			return;
		}

		if ( ! checkdate( (int) $month, (int) $day, (int) $year ) ) {
			$this->throw_mysql_incorrect_temporal_value( $type, $value );
		}
	}

	/**
	 * Throw a MySQL-compatible incorrect temporal value error.
	 *
	 * @param string $type  MySQL temporal type label.
	 * @param string $value Original unquoted literal value.
	 */
	private function throw_mysql_incorrect_temporal_value( string $type, string $value ): void {
		throw new InvalidArgumentException( sprintf( "Incorrect %s value: '%s'", $type, $value ) );
	}

	/**
	 * Throw a MySQL-compatible incorrect integer value error.
	 *
	 * @param string $value Original literal value.
	 */
	private function throw_mysql_incorrect_integer_value( string $value ): void {
		throw new InvalidArgumentException( sprintf( "Incorrect integer value: '%s'", $value ) );
	}

	/**
	 * Throw a MySQL-compatible out-of-range value error.
	 *
	 * @param string $value Original literal value.
	 */
	private function throw_mysql_out_of_range_value( string $value ): void {
		throw new InvalidArgumentException( sprintf( "Out of range value: '%s'", $value ) );
	}

	/**
	 * Throw a MySQL-compatible string truncation error.
	 *
	 * @param string $column_name Column name.
	 */
	private function throw_mysql_data_too_long_for_column( string $column_name ): void {
		throw new InvalidArgumentException( sprintf( "Data too long for column '%s'", $column_name ) );
	}

	/**
	 * Validate strict-mode text-family literal lengths.
	 *
	 * @param array            $column_metadata Column metadata row.
	 * @param WP_MySQL_Token[] $tokens          MySQL lexer token stream.
	 * @param int              $start           First value token position.
	 * @param int              $end             Final value token position, exclusive.
	 */
	private function validate_strict_mysql_dml_text_length_for_column( array $column_metadata, array $tokens, int $start, int $end ): void {
		$column_type = (string) ( $column_metadata['column_type'] ?? '' );
		$max_length  = $this->get_mysql_text_column_max_length( $column_type );
		if ( null === $max_length ) {
			return;
		}

		$value = $this->get_mysql_text_hex_literal_value( $tokens, $start, $end );
		if ( null === $value ) {
			$literal = $this->get_mysql_dml_literal_value( $tokens, $start, $end );
			if ( null === $literal || null === $literal['value'] ) {
				return;
			}

			$value = $literal['value'];
		}

		$length = function_exists( 'mb_strlen' ) ? mb_strlen( $value, 'UTF-8' ) : strlen( $value );
		if ( $length > $max_length ) {
			$this->throw_mysql_data_too_long_for_column( (string) ( $column_metadata['column_name'] ?? '' ) );
		}
	}

	/**
	 * Get the maximum character length for a MySQL text-family type.
	 *
	 * @param string $column_type MySQL column type metadata.
	 * @return int|null Maximum length, or null when the type is unbounded for this check.
	 */
	private function get_mysql_text_column_max_length( string $column_type ): ?int {
		$base_type = $this->get_base_mysql_dml_column_type( $column_type );
		if ( in_array( $base_type, array( 'char', 'varchar' ), true ) ) {
			return $this->get_mysql_column_type_display_width( $column_type );
		}

		if ( 'tinytext' === $base_type ) {
			return 255;
		}

		if ( 'text' === $base_type ) {
			return 65535;
		}

		if ( 'mediumtext' === $base_type ) {
			return 16777215;
		}

		if ( 'longtext' === $base_type ) {
			return 4294967295;
		}

		return null;
	}

	/**
	 * Get a literal value from a simple DML value token range.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First value token position.
	 * @param int              $end    Final value token position, exclusive.
	 * @return array{type: string, value: string|null}|null Literal metadata, or null for expressions.
	 */
	private function get_mysql_dml_literal_value( array $tokens, int $start, int $end ): ?array {
		if ( $this->is_mysql_string_literal_range( $tokens, $start, $end ) ) {
			return array(
				'type'  => 'string',
				'value' => $tokens[ $start ]->get_value(),
			);
		}

		if ( $start + 1 === $end && isset( $tokens[ $start ] ) ) {
			if ( WP_MySQL_Lexer::NULL_SYMBOL === $tokens[ $start ]->id ) {
				return array(
					'type'  => 'null',
					'value' => null,
				);
			}

			if ( WP_MySQL_Lexer::FALSE_SYMBOL === $tokens[ $start ]->id ) {
				return array(
					'type'  => 'boolean',
					'value' => '0',
				);
			}

			if ( WP_MySQL_Lexer::TRUE_SYMBOL === $tokens[ $start ]->id ) {
				return array(
					'type'  => 'boolean',
					'value' => '1',
				);
			}
		}

		$literal = $this->parse_mysql_numeric_literal( $tokens, $start, $end );
		if ( null !== $literal && $literal['start'] === $start && $literal['end'] === $end ) {
			return array(
				'type'  => 'numeric',
				'value' => $this->get_mysql_token_sequence_bytes( $tokens, $start, $end ),
			);
		}

		return null;
	}

	/**
	 * Get the original byte sequence for a token range.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token position.
	 * @param int              $end    Final token position, exclusive.
	 * @return string Token byte sequence.
	 */
	private function get_mysql_token_sequence_bytes( array $tokens, int $start, int $end ): string {
		$bytes = '';
		for ( $i = $start; $i < $end; $i++ ) {
			$bytes .= $tokens[ $i ]->get_bytes();
		}

		return $bytes;
	}

	/**
	 * Normalize strict-mode literals that MySQL accepts but PostgreSQL rejects.
	 *
	 * @param string[]         $columns      DML columns.
	 * @param string[]         $values       Translated DML values, mutated when needed.
	 * @param array[]          $value_ranges Original token ranges for each value.
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param array[]          $metadata     Ordered column metadata rows.
	 */
	private function normalize_strict_mysql_dml_values_for_columns( array $columns, array &$values, array $value_ranges, array $tokens, array $metadata ): void {
		if ( ! $this->is_mysql_strict_sql_mode_active() ) {
			return;
		}

		$column_metadata = $this->get_mysql_dml_column_metadata_lookup_from_rows( $metadata );
		foreach ( $columns as $index => $column ) {
			$column_key = strtolower( (string) $column );
			if (
				! isset( $column_metadata[ $column_key ], $value_ranges[ $index ] )
				|| ! isset( $value_ranges[ $index ]['start'], $value_ranges[ $index ]['end'] )
			) {
				continue;
			}

			$value_sql = $this->get_strict_mysql_dml_value_sql_for_column(
				$column_metadata[ $column_key ],
				$tokens,
				(int) $value_ranges[ $index ]['start'],
				(int) $value_ranges[ $index ]['end']
			);
			if ( null !== $value_sql ) {
				$values[ $index ] = $value_sql;
			}
		}
	}

	/**
	 * Get strict-mode SQL for MySQL-compatible integer literals.
	 *
	 * @param array            $column_metadata Column metadata row.
	 * @param WP_MySQL_Token[] $tokens          MySQL lexer token stream.
	 * @param int              $start           First value token position.
	 * @param int              $end             Final value token position, exclusive.
	 * @return string|null PostgreSQL value SQL, or null when generic translation is sufficient.
	 */
	private function get_strict_mysql_dml_integer_literal_sql_for_column( array $column_metadata, array $tokens, int $start, int $end ): ?string {
		if (
			! $this->is_mysql_strict_sql_mode_active()
			|| ! $this->is_mysql_integer_family_column_type( (string) ( $column_metadata['column_type'] ?? '' ) )
		) {
			return null;
		}

		$literal = $this->get_mysql_dml_literal_value( $tokens, $start, $end );
		if ( null === $literal || null === $literal['value'] ) {
			return null;
		}

		$value   = trim( $literal['value'] );
		$integer = $this->get_strict_mysql_dml_integer_literal_value( $value );
		if ( null === $integer ) {
			$this->throw_mysql_incorrect_integer_value( $value );
		}

		if ( ! $this->is_mysql_integer_value_in_column_range( $integer, (string) ( $column_metadata['column_type'] ?? '' ) ) ) {
			$this->throw_mysql_out_of_range_value( $value );
		}

		if (
			'' === $value
			|| 1 === preg_match( '/^[+-]?[0-9]+$/', $value )
			|| 1 !== preg_match( '/^[+-]?(?:[0-9]+\.0+|[0-9]*\.0+)$/', $value )
		) {
			if ( 'boolean' === $literal['type'] ) {
				return $integer;
			}

			return null;
		}

		return $this->get_postgresql_mysql_integer_cast_sql(
			$this->translate_mysql_token_sequence_to_postgresql( $tokens, $start, $end )
		);
	}

	/**
	 * Get a normalized strict integer literal value.
	 *
	 * @param string $value Literal value.
	 * @return string|null Normalized integer value, or null when the value is not an integer literal.
	 */
	private function get_strict_mysql_dml_integer_literal_value( string $value ): ?string {
		$value = trim( $value );
		if ( '' === $value ) {
			return null;
		}

		if ( 1 !== preg_match( '/^[+-]?(?:(?:[0-9]+)(?:\.0+)?|(?:[0-9]*\.0+))$/', $value ) ) {
			return null;
		}

		$integer = $value;
		$dot     = strpos( $integer, '.' );
		if ( false !== $dot ) {
			$integer = substr( $integer, 0, $dot );
		}

		if ( '' === $integer || '+' === $integer || '-' === $integer ) {
			$integer .= '0';
		}

		return $this->normalize_mysql_integer_string( $integer );
	}

	/**
	 * Normalize a signed integer string for comparisons.
	 *
	 * @param string $value Integer string.
	 * @return string Normalized integer string.
	 */
	private function normalize_mysql_integer_string( string $value ): string {
		$value    = trim( $value );
		$negative = false;
		if ( isset( $value[0] ) && ( '+' === $value[0] || '-' === $value[0] ) ) {
			$negative = '-' === $value[0];
			$value    = substr( $value, 1 );
		}

		$value = ltrim( $value, '0' );
		if ( '' === $value ) {
			return '0';
		}

		return $negative ? '-' . $value : $value;
	}

	/**
	 * Check whether an integer value fits the MySQL column type range.
	 *
	 * @param string $value       Normalized integer string.
	 * @param string $column_type MySQL column type metadata.
	 * @return bool Whether the value is in range.
	 */
	private function is_mysql_integer_value_in_column_range( string $value, string $column_type ): bool {
		$bounds = $this->get_mysql_integer_column_bounds( $column_type );
		if ( null === $bounds ) {
			return true;
		}

		return $this->compare_mysql_integer_strings( $value, $bounds['min'] ) >= 0
			&& $this->compare_mysql_integer_strings( $value, $bounds['max'] ) <= 0;
	}

	/**
	 * Get MySQL integer column bounds.
	 *
	 * @param string $column_type MySQL column type metadata.
	 * @return array{min: string, max: string}|null Integer bounds, or null for unknown integer types.
	 */
	private function get_mysql_integer_column_bounds( string $column_type ): ?array {
		$base_type = $this->get_base_mysql_dml_column_type( $column_type );
		$unsigned  = false !== stripos( $column_type, 'unsigned' );

		$signed_bounds = array(
			'tinyint'   => array( '-128', '127' ),
			'smallint'  => array( '-32768', '32767' ),
			'mediumint' => array( '-8388608', '8388607' ),
			'int'       => array( '-2147483648', '2147483647' ),
			'integer'   => array( '-2147483648', '2147483647' ),
			'bigint'    => array( '-9223372036854775808', '9223372036854775807' ),
		);
		$unsigned_max  = array(
			'tinyint'   => '255',
			'smallint'  => '65535',
			'mediumint' => '16777215',
			'int'       => '4294967295',
			'integer'   => '4294967295',
			'bigint'    => '18446744073709551615',
		);

		if ( ! isset( $signed_bounds[ $base_type ] ) ) {
			return null;
		}

		if ( $unsigned ) {
			return array(
				'min' => '0',
				'max' => $unsigned_max[ $base_type ],
			);
		}

		return array(
			'min' => $signed_bounds[ $base_type ][0],
			'max' => $signed_bounds[ $base_type ][1],
		);
	}

	/**
	 * Compare two normalized integer strings.
	 *
	 * @param string $left  Left integer.
	 * @param string $right Right integer.
	 * @return int Less than zero, zero, or greater than zero.
	 */
	private function compare_mysql_integer_strings( string $left, string $right ): int {
		$left  = $this->normalize_mysql_integer_string( $left );
		$right = $this->normalize_mysql_integer_string( $right );

		$left_negative  = isset( $left[0] ) && '-' === $left[0];
		$right_negative = isset( $right[0] ) && '-' === $right[0];
		if ( $left_negative !== $right_negative ) {
			return $left_negative ? -1 : 1;
		}

		$left_digits  = $left_negative ? substr( $left, 1 ) : $left;
		$right_digits = $right_negative ? substr( $right, 1 ) : $right;

		if ( strlen( $left_digits ) !== strlen( $right_digits ) ) {
			$result = strlen( $left_digits ) <=> strlen( $right_digits );
			return $left_negative ? -$result : $result;
		}

		$result = strcmp( $left_digits, $right_digits );
		return $left_negative ? -$result : $result;
	}

	/**
	 * Get strict/non-strict SQL for a MySQL YEAR literal.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First value token position.
	 * @param int              $end    Final value token position, exclusive.
	 * @return string|null PostgreSQL value SQL, or null when the token range is not a simple literal.
	 */
	private function get_mysql_dml_year_literal_sql_for_column( array $tokens, int $start, int $end ): ?string {
		$literal = $this->get_mysql_dml_literal_value( $tokens, $start, $end );
		if ( null === $literal || null === $literal['value'] ) {
			return null;
		}

		$value        = trim( $literal['value'] );
		$storage_year = $this->get_mysql_dml_year_storage_value( $value );
		if ( null === $storage_year ) {
			$this->throw_mysql_incorrect_temporal_value( 'year', $value );
		}

		return $this->connection->quote( $storage_year );
	}

	/**
	 * Get a normalized MySQL YEAR storage value.
	 *
	 * @param string $value Literal value.
	 * @return string|null Four-digit YEAR value, or null when invalid.
	 */
	private function get_mysql_dml_year_storage_value( string $value ): ?string {
		$value = trim( $value );
		if ( '' === $value ) {
			return null;
		}

		if ( 1 === preg_match( '/^([+-]?[0-9]+)(?:\.0+)?$/', $value, $matches ) ) {
			$year = $this->normalize_mysql_integer_string( $matches[1] );
		} elseif ( 1 === preg_match( '/^([0-9]{4})-(?:[0-9]{2})-(?:[0-9]{2})(?:[ T][0-9]{2}:[0-9]{2}:[0-9]{2}(?:\.[0-9]+)?Z?)?$/', $value, $matches ) ) {
			$year = $this->normalize_mysql_integer_string( $matches[1] );
		} else {
			return null;
		}

		if ( $this->compare_mysql_integer_strings( $year, '0' ) < 0 ) {
			$this->throw_mysql_out_of_range_value( $value );
		}

		if ( '0' === $year ) {
			return '0000';
		}

		if ( $this->compare_mysql_integer_strings( $year, '1' ) >= 0 && $this->compare_mysql_integer_strings( $year, '69' ) <= 0 ) {
			return sprintf( '%04d', 2000 + (int) $year );
		}

		if ( $this->compare_mysql_integer_strings( $year, '70' ) >= 0 && $this->compare_mysql_integer_strings( $year, '99' ) <= 0 ) {
			return (string) ( 1900 + (int) $year );
		}

		if ( $this->compare_mysql_integer_strings( $year, '1901' ) < 0 || $this->compare_mysql_integer_strings( $year, '2155' ) > 0 ) {
			$this->throw_mysql_out_of_range_value( $value );
		}

		return sprintf( '%04d', (int) $year );
	}

	/**
	 * Normalize non-strict DML values using MySQL column metadata.
	 *
	 * @param string[]         $columns      DML columns.
	 * @param string[]         $values       Translated DML values, mutated when needed.
	 * @param array[]          $value_ranges Original token ranges for each value.
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param array[]          $metadata     Ordered column metadata rows.
	 */
	private function normalize_non_strict_mysql_dml_values_for_columns( array $columns, array &$values, array $value_ranges, array $tokens, array $metadata ): void {
		if ( $this->is_mysql_strict_sql_mode_active() ) {
			return;
		}

		$column_metadata = $this->get_mysql_dml_column_metadata_lookup_from_rows( $metadata );
		foreach ( $columns as $index => $column ) {
			$column_key = strtolower( (string) $column );
			if (
				! isset( $column_metadata[ $column_key ], $value_ranges[ $index ] )
				|| ! isset( $value_ranges[ $index ]['start'], $value_ranges[ $index ]['end'] )
			) {
				continue;
			}

			$value_sql = $this->get_non_strict_mysql_dml_value_sql_for_column(
				$column_metadata[ $column_key ],
				$tokens,
				(int) $value_ranges[ $index ]['start'],
				(int) $value_ranges[ $index ]['end']
			);
			if ( null !== $value_sql ) {
				$values[ $index ] = $value_sql;
			}
		}
	}

	/**
	 * Get a non-strict MySQL-compatible DML value for a column when special handling is needed.
	 *
	 * @param array            $column_metadata Column metadata row.
	 * @param WP_MySQL_Token[] $tokens          MySQL lexer token stream.
	 * @param int              $start           First value token position.
	 * @param int              $end             Final value token position, exclusive.
	 * @return string|null PostgreSQL value SQL, or null when generic translation is sufficient.
	 */
	private function get_non_strict_mysql_dml_value_sql_for_column( array $column_metadata, array $tokens, int $start, int $end ): ?string {
		$text_hex_sql = $this->get_mysql_text_hex_literal_sql_for_column( $column_metadata, $tokens, $start, $end );
		if ( null !== $text_hex_sql ) {
			return $text_hex_sql;
		}

		$value_sql = $this->get_non_strict_mysql_dml_date_time_literal_sql_for_column( $column_metadata, $tokens, $start, $end );
		if ( null !== $value_sql ) {
			return $value_sql;
		}

		return $this->get_non_strict_mysql_dml_integer_literal_sql_for_column( $column_metadata, $tokens, $start, $end );
	}

	/**
	 * Get a text SQL literal for a MySQL hex literal assigned to a text column.
	 *
	 * @param array            $column_metadata Column metadata row.
	 * @param WP_MySQL_Token[] $tokens          MySQL lexer token stream.
	 * @param int              $start           First value token position.
	 * @param int              $end             Final value token position, exclusive.
	 * @return string|null PostgreSQL value SQL, or null when this is not a text hex literal.
	 */
	private function get_mysql_text_hex_literal_sql_for_column( array $column_metadata, array $tokens, int $start, int $end ): ?string {
		if ( ! $this->is_mysql_text_family_column_type( (string) ( $column_metadata['column_type'] ?? '' ) ) ) {
			return null;
		}

		$value = $this->get_mysql_text_hex_literal_value( $tokens, $start, $end );
		return null === $value ? null : $this->connection->quote( $value );
	}

	/**
	 * Decode a single MySQL hex literal token as bytes.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First value token position.
	 * @param int              $end    Final value token position, exclusive.
	 * @return string|null Decoded bytes, or null when the range is not a hex literal.
	 */
	private function get_mysql_text_hex_literal_value( array $tokens, int $start, int $end ): ?string {
		if (
			$start + 1 !== $end
			|| ! isset( $tokens[ $start ] )
			|| WP_MySQL_Lexer::HEX_NUMBER !== $tokens[ $start ]->id
		) {
			return null;
		}

		$bytes = $tokens[ $start ]->get_bytes();
		if ( 1 === preg_match( '/^0x([0-9a-fA-F]+)$/', $bytes, $matches ) ) {
			$hex = $matches[1];
		} elseif ( 1 === preg_match( "/^[xX]'([0-9a-fA-F]*)'$/", $bytes, $matches ) ) {
			$hex = $matches[1];
		} else {
			return null;
		}

		if ( 1 === strlen( $hex ) % 2 ) {
			$hex = '0' . $hex;
		}

		$decoded = hex2bin( $hex );
		return false === $decoded ? null : $decoded;
	}

	/**
	 * Get a non-strict MySQL-compatible integer literal for a column.
	 *
	 * @param array            $column_metadata Column metadata row.
	 * @param WP_MySQL_Token[] $tokens          MySQL lexer token stream.
	 * @param int              $start           First value token position.
	 * @param int              $end             Final value token position, exclusive.
	 * @return string|null PostgreSQL value SQL, or null when the literal does not need normalization.
	 */
	private function get_non_strict_mysql_dml_integer_literal_sql_for_column( array $column_metadata, array $tokens, int $start, int $end ): ?string {
		if ( ! $this->is_mysql_integer_family_column_type( (string) ( $column_metadata['column_type'] ?? '' ) ) ) {
			return null;
		}

		if ( $this->is_mysql_string_literal_range( $tokens, $start, $end ) ) {
			if ( 1 === preg_match( '/^[[:space:]]*[+-]?[0-9]+[[:space:]]*$/', $tokens[ $start ]->get_value() ) ) {
				return null;
			}

			return $this->get_postgresql_mysql_integer_cast_sql(
				$this->translate_mysql_token_to_postgresql( $tokens[ $start ] )
			);
		}

		$literal = $this->parse_mysql_numeric_literal( $tokens, $start, $end );
		if ( null === $literal || $literal['start'] !== $start || $literal['end'] !== $end ) {
			return null;
		}
		if ( $this->is_mysql_integer_numeric_literal_range( $tokens, $start, $end ) ) {
			return null;
		}

		return $this->get_postgresql_mysql_integer_cast_sql(
			$this->translate_mysql_token_sequence_to_postgresql( $tokens, $start, $end )
		);
	}

	/**
	 * Get a non-strict MySQL-compatible date/time literal for a column.
	 *
	 * @param array            $column_metadata Column metadata row.
	 * @param WP_MySQL_Token[] $tokens          MySQL lexer token stream.
	 * @param int              $start           First value token position.
	 * @param int              $end             Final value token position, exclusive.
	 * @return string|null PostgreSQL value SQL, or null when the literal does not need normalization.
	 */
	private function get_non_strict_mysql_dml_date_time_literal_sql_for_column( array $column_metadata, array $tokens, int $start, int $end ): ?string {
		$base_type = $this->get_base_mysql_dml_column_type( (string) ( $column_metadata['column_type'] ?? '' ) );
		if ( ! in_array( $base_type, array( 'date', 'datetime', 'timestamp' ), true ) ) {
			return null;
		}

		$literal = $this->get_mysql_dml_literal_value( $tokens, $start, $end );
		if ( null === $literal || null === $literal['value'] ) {
			return null;
		}

		if ( 'string' === $literal['type'] ) {
			$value         = $literal['value'];
			$storage_value = $this->get_non_strict_mysql_dml_date_time_storage_value( $base_type, $value );
			if ( null === $storage_value || $storage_value === $value ) {
				return null;
			}

			return $this->connection->quote( $storage_value );
		}

		if (
			'boolean' !== $literal['type']
			&& ( 'numeric' !== $literal['type'] || ! $this->is_mysql_zero_numeric_literal_value( $literal['value'] ) )
		) {
			return null;
		}

		return $this->connection->quote( $this->get_mysql_zero_date_time_storage_value_for_type( $base_type ) );
	}

	/**
	 * Get the MySQL zero storage value for a date/time type.
	 *
	 * @param string $base_type Base MySQL date/time column type.
	 * @return string Zero storage value.
	 */
	private function get_mysql_zero_date_time_storage_value_for_type( string $base_type ): string {
		if ( 'date' === $base_type ) {
			return '0000-00-00';
		}

		return '0000-00-00 00:00:00';
	}

	/**
	 * Check whether a parsed numeric literal represents MySQL zero.
	 *
	 * @param string $value Original numeric literal bytes.
	 * @return bool Whether the value is numerically zero.
	 */
	private function is_mysql_zero_numeric_literal_value( string $value ): bool {
		$value = trim( $value );
		if ( '' === $value ) {
			return false;
		}

		if ( isset( $value[0] ) && '+' === $value[0] ) {
			$value = substr( $value, 1 );
		}

		return 1 === preg_match( '/^-?(?:0+)(?:\.0+)?(?:[eE][+-]?0+)?$/', $value );
	}

	/**
	 * Get the non-strict MySQL storage value for a date/time literal.
	 *
	 * @param string $base_type Base MySQL date/time column type.
	 * @param string $value     Unquoted literal value.
	 * @return string|null Storage value, or null when the literal is not date/time-shaped.
	 */
	private function get_non_strict_mysql_dml_date_time_storage_value( string $base_type, string $value ): ?string {
		if ( 'date' === $base_type ) {
			return $this->get_non_strict_mysql_dml_date_storage_value( $value );
		}

		return $this->get_non_strict_mysql_dml_datetime_storage_value( $value );
	}

	/**
	 * Get the non-strict MySQL storage value for a DATE literal.
	 *
	 * @param string $value Unquoted literal value.
	 * @return string|null Storage value, or null when the literal is not date-shaped.
	 */
	private function get_non_strict_mysql_dml_date_storage_value( string $value ): ?string {
		$storage_value = $this->normalize_mysql_dml_date_literal_format( $value );
		$parts         = $this->get_mysql_dml_date_parts( $storage_value );
		if ( null === $parts ) {
			return null;
		}

		if ( $this->is_non_strict_mysql_dml_zero_date_allowed( $parts['year'], $parts['month'], $parts['day'] ) ) {
			return $storage_value;
		}

		if ( checkdate( (int) $parts['month'], (int) $parts['day'], (int) $parts['year'] ) ) {
			return $storage_value;
		}

		return '0000-00-00';
	}

	/**
	 * Get the non-strict MySQL storage value for a DATETIME/TIMESTAMP literal.
	 *
	 * @param string $value Unquoted literal value.
	 * @return string|null Storage value, or null when the literal is not datetime-shaped.
	 */
	private function get_non_strict_mysql_dml_datetime_storage_value( string $value ): ?string {
		$normalized_value = $this->normalize_mysql_dml_datetime_literal_format( $value );
		$parts            = $this->get_mysql_dml_datetime_parts( $normalized_value );
		if ( null === $parts ) {
			$date_parts = $this->get_mysql_dml_date_parts( $normalized_value );
			if ( null === $date_parts ) {
				return null;
			}

			if ( $this->is_non_strict_mysql_dml_zero_date_allowed( $date_parts['year'], $date_parts['month'], $date_parts['day'] ) ) {
				return $normalized_value . ' 00:00:00';
			}

			if ( checkdate( (int) $date_parts['month'], (int) $date_parts['day'], (int) $date_parts['year'] ) ) {
				return $normalized_value . ' 00:00:00';
			}

			return '0000-00-00 00:00:00';
		}

		$is_valid_time = $this->is_mysql_dml_time_value_valid( $parts['hour'], $parts['minute'], $parts['second'] );
		if (
			$is_valid_time
			&& $this->is_non_strict_mysql_dml_zero_date_allowed( $parts['year'], $parts['month'], $parts['day'] )
		) {
			return $normalized_value;
		}

		if (
			$is_valid_time
			&& checkdate( (int) $parts['month'], (int) $parts['day'], (int) $parts['year'] )
		) {
			return $normalized_value;
		}

		return '0000-00-00 00:00:00';
	}

	/**
	 * Normalize MySQL-accepted date/datetime literals to the stored MySQL DATE shape.
	 *
	 * @param string $value Unquoted literal value.
	 * @return string Normalized literal value.
	 */
	private function normalize_mysql_dml_date_literal_format( string $value ): string {
		if ( 1 === preg_match( '/^([0-9]{4}-[0-9]{2}-[0-9]{2})(?:[ T][0-9]{2}:[0-9]{2}:[0-9]{2}(?:\.[0-9]+)?Z?)?$/', $value, $matches ) ) {
			return $matches[1];
		}

		return $value;
	}

	/**
	 * Normalize MySQL-accepted ISO datetime literals to the stored MySQL text shape.
	 *
	 * @param string $value Unquoted literal value.
	 * @return string Normalized literal value.
	 */
	private function normalize_mysql_dml_datetime_literal_format( string $value ): string {
		if ( 1 === preg_match( '/^([0-9]{4}-[0-9]{2}-[0-9]{2})[ T]([0-9]{2}:[0-9]{2}:[0-9]{2})(?:\.[0-9]+)?Z?$/', $value, $matches ) ) {
			return $matches[1] . ' ' . $matches[2];
		}

		return $value;
	}

	/**
	 * Check whether a zero or partial-zero date is permitted in non-strict mode.
	 *
	 * @param string $year  Four-digit year.
	 * @param string $month Two-digit month.
	 * @param string $day   Two-digit day.
	 * @return bool Whether MySQL permits storing the zero date parts.
	 */
	private function is_non_strict_mysql_dml_zero_date_allowed( string $year, string $month, string $day ): bool {
		if ( '0000' === $year && '00' === $month && '00' === $day ) {
			return true;
		}

		return '0000' !== $year
			&& ( '00' === $month || '00' === $day )
			&& ! $this->is_mysql_sql_mode_active( 'NO_ZERO_IN_DATE' );
	}

	/**
	 * Get date parts from a MySQL DATE literal.
	 *
	 * @param string $value Unquoted literal value.
	 * @return array{year: string, month: string, day: string}|null Date parts, or null when not date-shaped.
	 */
	private function get_mysql_dml_date_parts( string $value ): ?array {
		if ( 1 !== preg_match( '/^([0-9]{4})-([0-9]{2})-([0-9]{2})$/', $value, $matches ) ) {
			return null;
		}

		return array(
			'year'  => $matches[1],
			'month' => $matches[2],
			'day'   => $matches[3],
		);
	}

	/**
	 * Get date and time parts from a MySQL DATETIME/TIMESTAMP literal.
	 *
	 * @param string $value Unquoted literal value.
	 * @return array{year: string, month: string, day: string, hour: string, minute: string, second: string}|null Date/time parts, or null when not datetime-shaped.
	 */
	private function get_mysql_dml_datetime_parts( string $value ): ?array {
		if ( 1 !== preg_match( '/^([0-9]{4})-([0-9]{2})-([0-9]{2}) ([0-9]{2}):([0-9]{2}):([0-9]{2})$/', $value, $matches ) ) {
			return null;
		}

		return array(
			'year'   => $matches[1],
			'month'  => $matches[2],
			'day'    => $matches[3],
			'hour'   => $matches[4],
			'minute' => $matches[5],
			'second' => $matches[6],
		);
	}

	/**
	 * Check whether a MySQL DATETIME/TIMESTAMP time part is valid.
	 *
	 * @param string $hour   Two-digit hour.
	 * @param string $minute Two-digit minute.
	 * @param string $second Two-digit second.
	 * @return bool Whether the time part is valid.
	 */
	private function is_mysql_dml_time_value_valid( string $hour, string $minute, string $second ): bool {
		return (int) $hour <= 23
			&& (int) $minute <= 59
			&& (int) $second <= 59;
	}

	/**
	 * Get DML column metadata keyed by lowercase column name.
	 *
	 * @param string $table_name Table name.
	 * @return array<string, array> Column metadata lookup.
	 */
	private function get_mysql_dml_column_metadata_lookup( string $table_name ): array {
		return $this->get_mysql_dml_column_metadata_lookup_from_rows(
			$this->get_mysql_dml_column_metadata( $table_name )
		);
	}

	/**
	 * Get DML column metadata keyed by lowercase column name from existing rows.
	 *
	 * @param array[] $metadata Column metadata rows.
	 * @return array<string, array> Column metadata lookup.
	 */
	private function get_mysql_dml_column_metadata_lookup_from_rows( array $metadata ): array {
		$lookup = array();
		foreach ( $metadata as $column_metadata ) {
			$column_name = (string) ( $column_metadata['column_name'] ?? '' );
			if ( '' !== $column_name ) {
				$lookup[ strtolower( $column_name ) ] = $column_metadata;
			}
		}

		return $lookup;
	}

	/**
	 * Get ordered DML column names from table metadata.
	 *
	 * @param array[] $metadata Ordered column metadata rows.
	 * @return string[]|null Column names, or null when metadata is unavailable.
	 */
	private function get_mysql_dml_column_names_from_metadata( array $metadata ): ?array {
		$columns = array();
		$seen    = array();

		foreach ( $metadata as $column_metadata ) {
			$column_name = (string) ( $column_metadata['column_name'] ?? '' );
			if ( '' === $column_name ) {
				return null;
			}

			$column_key = strtolower( $column_name );
			if ( isset( $seen[ $column_key ] ) ) {
				return null;
			}

			$columns[]           = $column_name;
			$seen[ $column_key ] = true;
		}

		return count( $columns ) > 0 ? $columns : null;
	}

	/**
	 * Get ordered MySQL column metadata for a DML target table.
	 *
	 * @param string $table_name Table name.
	 * @return array[] Column metadata rows.
	 */
	private function get_mysql_dml_column_metadata( string $table_name ): array {
		$this->ensure_mysql_schema_metadata_tables();

		$table_schema = $this->resolve_mysql_table_schema_for_introspection( 'public', $table_name );
		$cache_key    = $this->get_mysql_metadata_cache_key( $table_schema, $table_name );
		if ( array_key_exists( $cache_key, $this->mysql_dml_column_metadata_cache ) ) {
			return $this->mysql_dml_column_metadata_cache[ $cache_key ];
		}

		$stmt = $this->connection->query(
			sprintf(
				'SELECT column_name, ordinal_position, column_type, is_nullable, column_default, extra
				FROM %s
				WHERE table_schema = ? AND table_name = ?
				ORDER BY ordinal_position',
				$this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE )
			),
			array( $table_schema, $table_name )
		);

		$this->mysql_dml_column_metadata_cache[ $cache_key ] = $stmt->fetchAll( PDO::FETCH_ASSOC );
		return $this->mysql_dml_column_metadata_cache[ $cache_key ];
	}

	/**
	 * Get the default SQL expression for a non-strict NOT NULL DML column.
	 *
	 * @param array $column_metadata Column metadata row.
	 * @return string|null Default SQL, or null when the column should not be coerced.
	 */
	private function get_non_strict_dml_default_sql_for_column( array $column_metadata ): ?string {
		if ( 'NO' !== strtoupper( (string) ( $column_metadata['is_nullable'] ?? '' ) ) ) {
			return null;
		}

		if ( $this->is_mysql_auto_increment_column_metadata( $column_metadata ) ) {
			return null;
		}

		if ( null !== ( $column_metadata['column_default'] ?? null ) ) {
			return $this->connection->quote( (string) $column_metadata['column_default'] );
		}

		return $this->get_mysql_implicit_dml_default_sql( (string) ( $column_metadata['column_type'] ?? '' ) );
	}

	/**
	 * Check whether column metadata describes a MySQL AUTO_INCREMENT column.
	 *
	 * @param array $column_metadata Column metadata row.
	 * @return bool Whether the column is AUTO_INCREMENT.
	 */
	private function is_mysql_auto_increment_column_metadata( array $column_metadata ): bool {
		return 'auto_increment' === strtolower( (string) ( $column_metadata['extra'] ?? '' ) );
	}

	/**
	 * Get a MySQL-compatible implicit default for a column type.
	 *
	 * @param string $column_type MySQL column type metadata.
	 * @return string|null SQL default expression, or null for unsupported type metadata.
	 */
	private function get_mysql_implicit_dml_default_sql( string $column_type ): ?string {
		$base_type = $this->get_base_mysql_dml_column_type( $column_type );

		if (
			in_array(
				$base_type,
				array(
					'char',
					'varchar',
					'binary',
					'varbinary',
					'tinyblob',
					'blob',
					'mediumblob',
					'longblob',
					'tinytext',
					'text',
					'mediumtext',
					'longtext',
					'enum',
					'set',
				),
				true
			)
		) {
			return $this->connection->quote( '' );
		}

		if (
			in_array(
				$base_type,
				array(
					'bit',
					'tinyint',
					'smallint',
					'mediumint',
					'int',
					'integer',
					'bigint',
					'decimal',
					'numeric',
					'float',
					'double',
					'real',
				),
				true
			)
		) {
			return '0';
		}

		if ( 'date' === $base_type ) {
			return $this->connection->quote( '0000-00-00' );
		}

		if ( 'datetime' === $base_type || 'timestamp' === $base_type ) {
			return $this->connection->quote( '0000-00-00 00:00:00' );
		}

		if ( 'time' === $base_type ) {
			return $this->connection->quote( '00:00:00' );
		}

		if ( 'year' === $base_type ) {
			return $this->connection->quote( '0000' );
		}

		return null;
	}

	/**
	 * Get the base MySQL column type from metadata.
	 *
	 * @param string $column_type MySQL column type metadata.
	 * @return string Base type.
	 */
	private function get_base_mysql_dml_column_type( string $column_type ): string {
		$column_type = strtolower( trim( $column_type ) );
		$type_end    = strlen( $column_type );

		$length_position = strpos( $column_type, '(' );
		if ( false !== $length_position ) {
			$type_end = min( $type_end, $length_position );
		}

		$space_position = strpos( $column_type, ' ' );
		if ( false !== $space_position ) {
			$type_end = min( $type_end, $space_position );
		}

		return substr( $column_type, 0, $type_end );
	}

	/**
	 * Get a MySQL column type display width or length.
	 *
	 * @param string $column_type MySQL column type metadata.
	 * @return int|null Width, or null when absent.
	 */
	private function get_mysql_column_type_display_width( string $column_type ): ?int {
		if ( 1 !== preg_match( '/\(([0-9]+)\)/', $column_type, $matches ) ) {
			return null;
		}

		return (int) $matches[1];
	}

	/**
	 * Check whether a token sequence is exactly the NULL literal.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token position.
	 * @param int              $end    Final token position, exclusive.
	 * @return bool Whether the token sequence is NULL.
	 */
	private function is_mysql_null_token_sequence( array $tokens, int $start, int $end ): bool {
		return $start + 1 === $end
			&& isset( $tokens[ $start ] )
			&& WP_MySQL_Lexer::NULL_SYMBOL === $tokens[ $start ]->id;
	}

	/**
	 * Check whether the emulated MySQL session is using a strict SQL mode.
	 *
	 * @return bool Whether strict DML behavior should be preserved.
	 */
	private function is_mysql_strict_sql_mode_active(): bool {
		return $this->is_mysql_sql_mode_active( 'STRICT_TRANS_TABLES' )
			|| $this->is_mysql_sql_mode_active( 'STRICT_ALL_TABLES' );
	}

	/**
	 * Check whether a MySQL session SQL mode is active.
	 *
	 * @param string $mode SQL mode name.
	 * @return bool Whether the mode is active.
	 */
	private function is_mysql_sql_mode_active( string $mode ): bool {
		return $this->is_sql_mode_active( $mode );
	}

	/**
	 * Translate SELECT VERSION() while preserving MySQL's visible output label.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_mysql_version_function_select_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return null;
		}

		$projection_ranges = $this->split_top_level_mysql_arguments( $tokens, 1, $statement_end );
		if ( null === $projection_ranges || 1 !== count( $projection_ranges ) ) {
			return null;
		}

		$projection = $projection_ranges[0];
		$bounds     = $this->get_mysql_common_function_bounds( $tokens, $projection['start'], $projection['end'] );
		if (
			null === $bounds
			|| 'version' !== $bounds['function']
			|| $bounds['close'] + 1 !== $projection['end']
		) {
			return null;
		}

		return sprintf(
			'SELECT %s AS %s',
			$this->connection->quote( $this->get_mysql_version_string() ),
			$this->connection->quote_identifier( 'VERSION()' )
		);
	}

	/**
	 * Translate WordPress's distinct postmeta-key lookup that uses HAVING without GROUP BY.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_wordpress_postmeta_distinct_meta_key_having_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0], $tokens[1] )
			|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id
			|| WP_MySQL_Lexer::DISTINCT_SYMBOL !== $tokens[1]->id
		) {
			return null;
		}

		$projection_start = 2;
		$statement_end    = $this->get_mysql_statement_end_position( $tokens, $projection_start );
		if ( null === $statement_end ) {
			return null;
		}

		$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, $projection_start, $statement_end );
		$select_end     = $limit_position ?? $statement_end;
		if ( null !== $limit_position && ! $this->is_supported_simple_select_limit_clause( $tokens, $limit_position, $statement_end ) ) {
			return null;
		}

		$order_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::ORDER_SYMBOL, $projection_start, $select_end );
		if (
			null === $order_position
			|| ! isset( $tokens[ $order_position + 1 ] )
			|| WP_MySQL_Lexer::BY_SYMBOL !== $tokens[ $order_position + 1 ]->id
			|| $order_position + 2 >= $select_end
		) {
			return null;
		}

		$having_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::HAVING_SYMBOL, $projection_start, $order_position );
		if ( null === $having_position || $having_position + 1 >= $order_position ) {
			return null;
		}

		if (
			null !== $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::GROUP_SYMBOL, $projection_start, $having_position )
			|| $this->contains_top_level_mysql_token(
				$tokens,
				$projection_start,
				$select_end,
				array(
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::INTO_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::SELECT_SYMBOL,
					WP_MySQL_Lexer::SQL_CALC_FOUND_ROWS_SYMBOL,
					WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				)
			)
		) {
			return null;
		}

		$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, $projection_start, $having_position );
		if ( null === $from_position || $projection_start === $from_position ) {
			return null;
		}

		$projection_items = $this->parse_mysql_select_projection_items( $tokens, $projection_start, $from_position );
		if ( null === $projection_items || 1 !== count( $projection_items ) ) {
			return null;
		}

		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, $from_position + 1, $having_position );
		$from_end       = $where_position ?? $having_position;
		$table          = $this->parse_mysql_table_reference( $tokens, $from_position + 1, $from_end );
		if (
			null === $table
			|| $table['position'] !== $from_end
			|| 'public' !== $table['schema']
			|| ! $this->is_mysql_wordpress_table_name( $table['table'], 'postmeta' )
			|| ! $this->is_mysql_postmeta_meta_key_reference(
				$tokens,
				$projection_items[0]['expression_start'],
				$projection_items[0]['expression_end'],
				$table
			)
			|| ! $this->is_mysql_postmeta_meta_key_not_like_predicate( $tokens, $having_position + 1, $order_position, $table )
			|| ! $this->is_mysql_postmeta_meta_key_order_by_clause( $tokens, $order_position + 2, $select_end, $table )
		) {
			return null;
		}

		$from_sql   = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $from_position, $from_end );
		$having_sql = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $having_position + 1, $order_position );
		$order_sql  = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $order_position, $select_end );

		if ( null !== $where_position ) {
			$where_sql = sprintf(
				'(%s) AND (%s)',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $where_position + 1, $having_position ),
				$having_sql
			);
		} else {
			$where_sql = $having_sql;
		}

		$sql = sprintf(
			'SELECT DISTINCT %s %s WHERE %s %s',
			$this->translate_mysql_token_sequence_to_postgresql( $tokens, $projection_start, $from_position ),
			$from_sql,
			$where_sql,
			$order_sql
		);

		if ( null !== $limit_position ) {
			$sql .= $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end );
		}

		return $sql;
	}

	/**
	 * Check whether a token range is a postmeta.meta_key reference.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token position.
	 * @param int              $end    Final token position, exclusive.
	 * @param array            $table  Parsed postmeta table reference.
	 * @return bool Whether the range references meta_key.
	 */
	private function is_mysql_postmeta_meta_key_reference( array $tokens, int $start, int $end, array $table ): bool {
		$bounds    = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$reference = $this->parse_mysql_column_reference( $tokens, $bounds['start'], $bounds['end'] );
		if (
			null === $reference
			|| $reference['end'] !== $bounds['end']
			|| 0 !== strcasecmp( $reference['column'], 'meta_key' )
		) {
			return false;
		}

		return null === $reference['qualifier']
			|| $this->is_mysql_dml_table_qualifier( $reference['qualifier'], $table['table'], $table['alias'] );
	}

	/**
	 * Check whether a HAVING predicate is meta_key NOT LIKE pattern.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First HAVING predicate token.
	 * @param int              $end    Final HAVING predicate token, exclusive.
	 * @param array            $table  Parsed postmeta table reference.
	 * @return bool Whether the predicate is supported.
	 */
	private function is_mysql_postmeta_meta_key_not_like_predicate( array $tokens, int $start, int $end, array $table ): bool {
		$reference = $this->parse_mysql_column_reference( $tokens, $start, $end );
		if (
			null === $reference
			|| ! $this->is_mysql_postmeta_meta_key_reference( $tokens, $reference['start'], $reference['end'], $table )
			|| ! isset( $tokens[ $reference['end'] ], $tokens[ $reference['end'] + 1 ] )
			|| WP_MySQL_Lexer::NOT_SYMBOL !== $tokens[ $reference['end'] ]->id
			|| WP_MySQL_Lexer::LIKE_SYMBOL !== $tokens[ $reference['end'] + 1 ]->id
			|| $reference['end'] + 2 >= $end
		) {
			return false;
		}

		return ! $this->contains_top_level_mysql_token(
			$tokens,
			$reference['end'] + 2,
			$end,
			array(
				WP_MySQL_Lexer::AND_SYMBOL,
				WP_MySQL_Lexer::OR_SYMBOL,
				WP_MySQL_Lexer::SELECT_SYMBOL,
			)
		);
	}

	/**
	 * Check whether an ORDER BY clause sorts by meta_key.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First ORDER BY item token.
	 * @param int              $end    Final ORDER BY token, exclusive.
	 * @param array            $table  Parsed postmeta table reference.
	 * @return bool Whether the ORDER BY clause is supported.
	 */
	private function is_mysql_postmeta_meta_key_order_by_clause( array $tokens, int $start, int $end, array $table ): bool {
		$order_items = $this->split_top_level_mysql_arguments( $tokens, $start, $end );
		if ( null === $order_items || 1 !== count( $order_items ) ) {
			return false;
		}

		$item_end = $order_items[0]['end'];
		if (
			isset( $tokens[ $item_end - 1 ] )
			&& (
				WP_MySQL_Lexer::ASC_SYMBOL === $tokens[ $item_end - 1 ]->id
				|| WP_MySQL_Lexer::DESC_SYMBOL === $tokens[ $item_end - 1 ]->id
			)
		) {
			--$item_end;
		}

		return $this->is_mysql_postmeta_meta_key_reference( $tokens, $order_items[0]['start'], $item_end, $table );
	}

	/**
	 * Translate simple single-table MySQL SELECT statements to PostgreSQL.
	 *
	 * This intentionally covers only the WordPress read shapes that need
	 * identifier quoting for PostgreSQL. Joins, grouping, subqueries, most
	 * functions, and MySQL-only SELECT modifiers fall through unchanged.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when the query is unsupported.
	 */
	private function translate_simple_mysql_select_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return null;
		}

		$unsupported_tokens = array(
			WP_MySQL_Lexer::DISTINCT_SYMBOL,
			WP_MySQL_Lexer::FOR_SYMBOL,
			WP_MySQL_Lexer::GROUP_SYMBOL,
			WP_MySQL_Lexer::HAVING_SYMBOL,
			WP_MySQL_Lexer::HIGH_PRIORITY_SYMBOL,
			WP_MySQL_Lexer::INTO_SYMBOL,
			WP_MySQL_Lexer::JOIN_SYMBOL,
			WP_MySQL_Lexer::LOCK_SYMBOL,
			WP_MySQL_Lexer::PROCEDURE_SYMBOL,
			WP_MySQL_Lexer::SELECT_SYMBOL,
			WP_MySQL_Lexer::SQL_CALC_FOUND_ROWS_SYMBOL,
			WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL,
			WP_MySQL_Lexer::UNION_SYMBOL,
		);
		if ( $this->contains_top_level_mysql_token( $tokens, 1, $statement_end, $unsupported_tokens ) ) {
			return null;
		}

		$select_end     = $statement_end;
		$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, 1, $statement_end );
		if ( null !== $limit_position ) {
			if ( ! $this->is_supported_simple_select_limit_clause( $tokens, $limit_position, $statement_end ) ) {
				return null;
			}

			$select_end = $limit_position;
		}

		$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, 1, $select_end );
		if ( null === $from_position || 1 === $from_position ) {
			return null;
		}

		if ( ! $this->is_supported_simple_select_projection( $tokens, 1, $from_position ) ) {
			return null;
		}

		$table_reference_start = $from_position + 1;
		$position              = $table_reference_start;
		$table_name            = $this->parse_mysql_main_database_table_name( $tokens, $position );
		if ( null === $table_name ) {
			return null;
		}
		$table_reference_sql = $this->get_mysql_main_database_table_reference_sql(
			$tokens,
			$table_reference_start,
			$position
		);

		$where_position = null;
		$where_end      = null;
		$order_position = null;

		if ( $position < $select_end && WP_MySQL_Lexer::WHERE_SYMBOL === $tokens[ $position ]->id ) {
			$where_position = $position;
			$order_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::ORDER_SYMBOL, $position + 1, $select_end );
			$where_end      = $order_position ?? $select_end;

			if (
				$where_position + 1 >= $where_end
				|| ! $this->is_supported_simple_mysql_expression_fragment( $tokens, $where_position + 1, $where_end )
			) {
				return null;
			}

			$position = $where_end;
		}

		if ( $position < $select_end && WP_MySQL_Lexer::ORDER_SYMBOL === $tokens[ $position ]->id ) {
			$order_position = $position;
			if ( ! $this->is_supported_simple_select_order_by_clause( $tokens, $order_position, $select_end ) ) {
				return null;
			}

			$position = $select_end;
		}

		if ( $position !== $select_end ) {
			return null;
		}

		$sql = sprintf(
			'SELECT %s FROM %s',
			$this->translate_simple_select_projection_to_postgresql( $tokens, 1, $from_position ),
			$table_reference_sql
		);

		$scope = $this->get_mysql_single_table_scope( $table_name );
		if ( null !== $where_position ) {
			$where_sql = $this->translate_mysql_predicate_token_sequence_to_postgresql(
				$tokens,
				$where_position + 1,
				$where_end,
				$scope
			);
			$sql      .= ' WHERE ' . $where_sql['sql'];
		}

		if ( null !== $order_position ) {
			$order_sql = $this->translate_mysql_order_by_token_sequence_to_postgresql(
				$tokens,
				$order_position + 2,
				$select_end,
				$scope,
				false
			);
			$sql      .= ' ORDER BY ' . $order_sql['sql'];

			$tiebreaker_sql = $this->get_simple_wordpress_posts_post_date_desc_order_id_tiebreaker_sql(
				$tokens,
				$table_name,
				$order_position,
				$select_end
			);
			if ( null !== $tiebreaker_sql ) {
				$sql .= ', ' . $tiebreaker_sql;
			}

			$tiebreaker_sql = $this->get_simple_wordpress_approved_comments_order_tiebreaker_sql(
				$tokens,
				$table_name,
				$where_position,
				$where_end,
				$order_position,
				$select_end
			);
			if ( null !== $tiebreaker_sql ) {
				$sql .= ', ' . $tiebreaker_sql;
			}
		}

		if ( null !== $limit_position ) {
			$sql .= $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end );
		}

		return $sql;
	}

	/**
	 * Translate WordPress Site Health's MySQL information_schema.TABLES query.
	 *
	 * WordPress asks MySQL for TABLE_ROWS and data/index lengths, which
	 * PostgreSQL's information_schema.tables does not expose. Keep this rewrite
	 * constrained to the Site Health projection and predicates so other catalog
	 * shapes continue to fail visibly.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when the query is unsupported.
	 */
	private function translate_information_schema_tables_site_health_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return null;
		}

		$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, 1, $statement_end );
		if ( null === $from_position || 1 === $from_position ) {
			return null;
		}

		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, $from_position + 1, $statement_end );
		$group_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::GROUP_SYMBOL, $from_position + 1, $statement_end );
		if (
			null === $where_position
			|| null === $group_position
			|| $where_position > $group_position
			|| ! isset( $tokens[ $group_position + 1 ] )
			|| WP_MySQL_Lexer::BY_SYMBOL !== $tokens[ $group_position + 1 ]->id
		) {
			return null;
		}

		if (
			$this->contains_top_level_mysql_token(
				$tokens,
				1,
				$statement_end,
				array(
					WP_MySQL_Lexer::DISTINCT_SYMBOL,
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::HAVING_SYMBOL,
					WP_MySQL_Lexer::HIGH_PRIORITY_SYMBOL,
					WP_MySQL_Lexer::INTO_SYMBOL,
					WP_MySQL_Lexer::JOIN_SYMBOL,
					WP_MySQL_Lexer::LIMIT_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::ORDER_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::SELECT_SYMBOL,
					WP_MySQL_Lexer::SQL_CALC_FOUND_ROWS_SYMBOL,
					WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				)
			)
		) {
			return null;
		}

		if ( ! $this->is_information_schema_tables_reference( $tokens, $from_position + 1, $where_position ) ) {
			return null;
		}

		$projection_items = $this->parse_mysql_select_projection_items( $tokens, 1, $from_position );
		if ( null === $projection_items ) {
			return null;
		}

		$projection_sql = $this->get_information_schema_tables_site_health_projection_sql( $tokens, $projection_items );
		if ( null === $projection_sql ) {
			return null;
		}

		$where_clause = $this->parse_information_schema_tables_site_health_where_clause( $tokens, $where_position + 1, $group_position );
		if ( null === $where_clause ) {
			return null;
		}

		if ( ! $this->is_information_schema_tables_site_health_group_by_clause( $tokens, $group_position + 2, $statement_end ) ) {
			return null;
		}

		$existing_table_names = $this->get_information_schema_tables_site_health_existing_table_names( $where_clause['table_names'] );

		return sprintf(
			'SELECT %s FROM (%s) AS %s WHERE %s GROUP BY %s',
			implode( ', ', $projection_sql ),
			$this->get_information_schema_tables_site_health_relation_sql( $existing_table_names ),
			$this->connection->quote_identifier( '__wp_pg_information_schema_tables' ),
			$this->translate_mysql_token_sequence_to_postgresql( $tokens, $where_position + 1, $group_position ),
			$this->connection->quote_identifier( 'table_name' )
		);
	}

	/**
	 * Check whether a token range is exactly information_schema.TABLES.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First table-reference token position.
	 * @param int             $end    Final table-reference token position, exclusive.
	 * @return bool Whether the range references information_schema.TABLES.
	 */
	private function is_information_schema_tables_reference( array $tokens, int $start, int $end ): bool {
		return $start + 3 === $end
			&& $this->is_mysql_identifier_like_token_value( $tokens[ $start ] ?? null, 'information_schema' )
			&& isset( $tokens[ $start + 1 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $start + 1 ]->id
			&& $this->is_mysql_identifier_like_token_value( $tokens[ $start + 2 ] ?? null, 'tables' );
	}

	/**
	 * Build Site Health's supported information_schema.TABLES projection list.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param array           $projection_items Parsed projection items.
	 * @return string[]|null PostgreSQL projection SQL, or null when unsupported.
	 */
	private function get_information_schema_tables_site_health_projection_sql( array $tokens, array $projection_items ): ?array {
		if ( 3 !== count( $projection_items ) ) {
			return null;
		}

		$expected = array(
			array(
				'alias' => 'table',
				'type'  => 'table_name',
			),
			array(
				'alias' => 'rows',
				'type'  => 'table_rows',
			),
			array(
				'alias' => 'bytes',
				'type'  => 'data_index_sum',
			),
		);

		$projection_sql = array();
		foreach ( $expected as $index => $expected_projection ) {
			$projection_item = $projection_items[ $index ];
			if ( strtolower( $projection_item['alias'] ) !== $expected_projection['alias'] ) {
				return null;
			}

			if (
				'table_name' === $expected_projection['type']
				&& $this->is_information_schema_tables_column_expression(
					$tokens,
					$projection_item['expression_start'],
					$projection_item['expression_end'],
					'table_name'
				)
			) {
				$projection_sql[] = sprintf(
					'%s AS %s',
					$this->connection->quote_identifier( 'table_name' ),
					$this->connection->quote_identifier( $projection_item['alias'] )
				);
				continue;
			}

			if (
				'table_rows' === $expected_projection['type']
				&& $this->is_information_schema_tables_column_expression(
					$tokens,
					$projection_item['expression_start'],
					$projection_item['expression_end'],
					'table_rows'
				)
			) {
				$projection_sql[] = sprintf(
					'MAX(%s) AS %s',
					$this->connection->quote_identifier( 'TABLE_ROWS' ),
					$this->connection->quote_identifier( $projection_item['alias'] )
				);
				continue;
			}

			if (
				'data_index_sum' === $expected_projection['type']
				&& $this->is_information_schema_tables_data_index_sum_expression(
					$tokens,
					$projection_item['expression_start'],
					$projection_item['expression_end']
				)
			) {
				$projection_sql[] = sprintf(
					'SUM(%s + %s) AS %s',
					$this->connection->quote_identifier( 'data_length' ),
					$this->connection->quote_identifier( 'index_length' ),
					$this->connection->quote_identifier( $projection_item['alias'] )
				);
				continue;
			}

			return null;
		}

		return $projection_sql;
	}

	/**
	 * Check whether a projection expression is a supported information_schema.TABLES column.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token position.
	 * @param int             $end    Final expression token position, exclusive.
	 * @param string          $column Expected column name.
	 * @return bool Whether the expression is the expected column.
	 */
	private function is_information_schema_tables_column_expression( array $tokens, int $start, int $end, string $column ): bool {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		return $bounds['start'] + 1 === $bounds['end']
			&& $this->is_mysql_identifier_like_token_value( $tokens[ $bounds['start'] ] ?? null, $column );
	}

	/**
	 * Check whether a projection expression is SUM(data_length + index_length).
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token position.
	 * @param int             $end    Final expression token position, exclusive.
	 * @return bool Whether the expression is the supported size aggregate.
	 */
	private function is_information_schema_tables_data_index_sum_expression( array $tokens, int $start, int $end ): bool {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start  = $bounds['start'];
		$end    = $bounds['end'];

		return $start + 6 === $end
			&& isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ], $tokens[ $start + 3 ], $tokens[ $start + 4 ], $tokens[ $start + 5 ] )
			&& WP_MySQL_Lexer::SUM_SYMBOL === $tokens[ $start ]->id
			&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $start + 1 ]->id
			&& $this->is_mysql_identifier_like_token_value( $tokens[ $start + 2 ], 'data_length' )
			&& WP_MySQL_Lexer::PLUS_OPERATOR === $tokens[ $start + 3 ]->id
			&& $this->is_mysql_identifier_like_token_value( $tokens[ $start + 4 ], 'index_length' )
			&& WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $start + 5 ]->id;
	}

	/**
	 * Parse a supported Site Health information_schema.TABLES WHERE clause.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First WHERE predicate token position.
	 * @param int             $end    Final WHERE predicate token position, exclusive.
	 * @return array{table_names: string[]}|null Parsed WHERE data, or null when unsupported.
	 */
	private function parse_information_schema_tables_site_health_where_clause( array $tokens, int $start, int $end ): ?array {
		if ( $start >= $end ) {
			return null;
		}

		$position      = $start;
		$seen_columns  = array();
		$table_names   = array();
		$required_seen = array(
			'table_schema' => false,
			'table_name'   => false,
		);

		while ( $position < $end ) {
			$term = $this->parse_information_schema_tables_site_health_where_term( $tokens, $position, $end );
			if ( null === $term || isset( $seen_columns[ $term['column'] ] ) ) {
				return null;
			}

			$seen_columns[ $term['column'] ] = true;
			if ( isset( $required_seen[ $term['column'] ] ) ) {
				$required_seen[ $term['column'] ] = true;
			}
			if ( 'table_name' === $term['column'] ) {
				$table_names = $term['table_names'];
			}
			$position = $term['position'];

			if ( $position === $end ) {
				break;
			}

			if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::AND_SYMBOL !== $tokens[ $position ]->id ) {
				return null;
			}
			++$position;
		}

		if ( ! $required_seen['table_schema'] || ! $required_seen['table_name'] || empty( $table_names ) ) {
			return null;
		}

		return array(
			'table_names' => array_values( array_unique( $table_names ) ),
		);
	}

	/**
	 * Parse one supported information_schema.TABLES WHERE term.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Current token position.
	 * @param int             $end      Final WHERE predicate token position, exclusive.
	 * @return array{column: string, position: int, table_names: string[]}|null Parsed term, or null when unsupported.
	 */
	private function parse_information_schema_tables_site_health_where_term( array $tokens, int $position, int $end ): ?array {
		if ( $this->is_mysql_identifier_like_token_value( $tokens[ $position ] ?? null, 'table_schema' ) ) {
			if (
				! isset( $tokens[ $position + 1 ], $tokens[ $position + 2 ] )
				|| WP_MySQL_Lexer::EQUAL_OPERATOR !== $tokens[ $position + 1 ]->id
				|| ! $this->is_mysql_string_literal_token( $tokens[ $position + 2 ] )
			) {
				return null;
			}

			return array(
				'column'      => 'table_schema',
				'position'    => $position + 3,
				'table_names' => array(),
			);
		}

		if ( ! $this->is_mysql_identifier_like_token_value( $tokens[ $position ] ?? null, 'table_name' ) ) {
			return null;
		}

		if (
			isset( $tokens[ $position + 1 ], $tokens[ $position + 2 ] )
			&& WP_MySQL_Lexer::EQUAL_OPERATOR === $tokens[ $position + 1 ]->id
			&& $this->is_mysql_string_literal_token( $tokens[ $position + 2 ] )
		) {
			return array(
				'column'      => 'table_name',
				'position'    => $position + 3,
				'table_names' => array( $tokens[ $position + 2 ]->get_value() ),
			);
		}

		if (
			! isset( $tokens[ $position + 1 ], $tokens[ $position + 2 ] )
			|| WP_MySQL_Lexer::IN_SYMBOL !== $tokens[ $position + 1 ]->id
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position + 2 ]->id
		) {
			return null;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position + 2, $end );
		if ( null === $after_close ) {
			return null;
		}

		$items = $this->split_top_level_mysql_arguments( $tokens, $position + 3, $after_close - 1 );
		if ( null === $items || count( $items ) < 1 ) {
			return null;
		}

		$table_names = array();
		foreach ( $items as $item ) {
			if ( ! $this->is_mysql_string_literal_range( $tokens, $item['start'], $item['end'] ) ) {
				return null;
			}
			$table_names[] = $tokens[ $item['start'] ]->get_value();
		}

		return array(
			'column'      => 'table_name',
			'position'    => $after_close,
			'table_names' => $table_names,
		);
	}

	/**
	 * Check whether the GROUP BY clause is exactly GROUP BY TABLE_NAME.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First GROUP BY expression token position.
	 * @param int             $end    Final GROUP BY token position, exclusive.
	 * @return bool Whether the grouping shape is supported.
	 */
	private function is_information_schema_tables_site_health_group_by_clause( array $tokens, int $start, int $end ): bool {
		return $start + 1 === $end
			&& $this->is_mysql_identifier_like_token_value( $tokens[ $start ] ?? null, 'table_name' );
	}

	/**
	 * Get requested Site Health table names that exist in the PostgreSQL catalog.
	 *
	 * @param string[] $table_names Table names from the validated TABLE_NAME predicate.
	 * @return string[] Existing table names in requested order.
	 */
	private function get_information_schema_tables_site_health_existing_table_names( array $table_names ): array {
		if ( empty( $table_names ) ) {
			return array();
		}

		$placeholders = implode( ', ', array_fill( 0, count( $table_names ), '?' ) );
		$stmt         = $this->connection->query(
			sprintf(
				'SELECT %1$s FROM %2$s WHERE %3$s = ? AND %4$s IN (?, ?) AND %1$s NOT IN (?, ?, ?, ?, ?, ?) AND %1$s IN (%5$s)',
				$this->connection->quote_identifier( 'table_name' ),
				$this->get_postgresql_qualified_identifier( 'information_schema', 'tables' ),
				$this->connection->quote_identifier( 'table_schema' ),
				$this->connection->quote_identifier( 'table_type' ),
				$placeholders
			),
			array_merge(
				array(
					'public',
					'BASE TABLE',
					'VIEW',
					self::MYSQL_COLUMN_METADATA_TABLE,
					self::MYSQL_INDEX_METADATA_TABLE,
					self::MYSQL_FOREIGN_KEY_METADATA_TABLE,
					self::MYSQL_CHECK_METADATA_TABLE,
					self::MYSQL_CHARSET_METADATA_TABLE,
					self::MYSQL_TABLE_METADATA_TABLE,
				),
				$table_names
			)
		);

		$existing_table_names = array();
		foreach ( $stmt->fetchAll( PDO::FETCH_COLUMN, 0 ) as $table_name ) {
			$existing_table_names[ (string) $table_name ] = true;
		}

		return array_values(
			array_filter(
				$table_names,
				static function ( string $table_name ) use ( $existing_table_names ): bool {
					return isset( $existing_table_names[ $table_name ] );
				}
			)
		);
	}

	/**
	 * Build the derived relation that emulates MySQL information_schema.TABLES columns.
	 *
	 * @param string[] $existing_table_names Table names validated against information_schema.tables.
	 * @return string PostgreSQL relation SQL.
	 */
	private function get_information_schema_tables_site_health_relation_sql( array $existing_table_names ): string {
		return sprintf(
			'SELECT %1$s AS %1$s, %2$s AS %3$s, %4$s, 0 AS %5$s, 0 AS %6$s FROM %7$s WHERE %8$s = %9$s AND %10$s IN (%11$s, %12$s) AND %1$s NOT IN (%13$s, %14$s, %15$s, %16$s, %17$s, %18$s)',
			$this->connection->quote_identifier( 'table_name' ),
			$this->connection->quote( $this->db_name ),
			$this->connection->quote_identifier( 'TABLE_SCHEMA' ),
			$this->get_information_schema_tables_site_health_table_rows_sql( $existing_table_names ),
			$this->connection->quote_identifier( 'data_length' ),
			$this->connection->quote_identifier( 'index_length' ),
			$this->get_postgresql_qualified_identifier( 'information_schema', 'tables' ),
			$this->connection->quote_identifier( 'table_schema' ),
			$this->connection->quote( 'public' ),
			$this->connection->quote_identifier( 'table_type' ),
			$this->connection->quote( 'BASE TABLE' ),
			$this->connection->quote( 'VIEW' ),
			$this->connection->quote( self::MYSQL_COLUMN_METADATA_TABLE ),
			$this->connection->quote( self::MYSQL_INDEX_METADATA_TABLE ),
			$this->connection->quote( self::MYSQL_FOREIGN_KEY_METADATA_TABLE ),
			$this->connection->quote( self::MYSQL_CHECK_METADATA_TABLE ),
			$this->connection->quote( self::MYSQL_CHARSET_METADATA_TABLE ),
			$this->connection->quote( self::MYSQL_TABLE_METADATA_TABLE )
		);
	}

	/**
	 * Build a Site Health TABLE_ROWS expression for existing catalog tables.
	 *
	 * @param string[] $existing_table_names Table names validated against information_schema.tables.
	 * @return string PostgreSQL row-count expression SQL.
	 */
	private function get_information_schema_tables_site_health_table_rows_sql( array $existing_table_names ): string {
		if ( empty( $existing_table_names ) ) {
			return sprintf(
				'0 AS %s',
				$this->connection->quote_identifier( 'TABLE_ROWS' )
			);
		}

		$cases = array();
		foreach ( $existing_table_names as $table_name ) {
			$cases[] = sprintf(
				'WHEN %s THEN (SELECT COUNT(*) FROM %s)',
				$this->connection->quote( $table_name ),
				$this->get_postgresql_qualified_identifier( 'public', $table_name )
			);
		}

		return sprintf(
			'CASE %s %s ELSE 0 END AS %s',
			$this->connection->quote_identifier( 'table_name' ),
			implode( ' ', $cases ),
			$this->connection->quote_identifier( 'TABLE_ROWS' )
		);
	}

	/**
	 * Translate supported CTE SELECTs over direct MySQL information_schema relations.
	 *
	 * @param string $query MySQL WITH ... SELECT query.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_direct_information_schema_cte_select_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::WITH_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return null;
		}

		$position = 1;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::RECURSIVE_SYMBOL === $tokens[ $position ]->id ) {
			return null;
		}

		$replacements = array();
		$cte_sources  = array();
		while ( $position < $statement_end ) {
			$cte_name_position = $position;
			$cte_name = $this->get_direct_information_schema_identifier_token_value( $tokens[ $position ] ?? null );
			if ( null === $cte_name ) {
				return null;
			}

			$replacements[] = array(
				'start' => $cte_name_position,
				'end'   => $cte_name_position + 1,
				'sql'   => $this->connection->quote_identifier( $cte_name ),
			);

			++$position;
			$column_list_insert_position = $position;
			$has_column_list            = false;
			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
				$after_column_list = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $statement_end );
				if ( null === $after_column_list ) {
					return null;
				}
				$columns = $this->get_direct_information_schema_cte_column_list( $tokens, $position + 1, $after_column_list - 1 );
				if ( empty( $columns ) ) {
					return null;
				}
				$has_column_list = true;
				$position        = $after_column_list;
			}

			if (
				! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
				|| WP_MySQL_Lexer::AS_SYMBOL !== $tokens[ $position ]->id
				|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position + 1 ]->id
			) {
				return null;
			}

			$after_select_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position + 1, $statement_end );
			if ( null === $after_select_close ) {
				return null;
			}

			$select_start = $position + 2;
			$select_end   = $after_select_close - 1;
			if ( ! isset( $tokens[ $select_start ] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $select_start ]->id ) {
				return null;
			}

			$select_query = $this->get_mysql_token_range_bytes( $query, $tokens, $select_start, $select_end );
			if ( '' === $select_query ) {
				return null;
			}

			$translated_select = $this->translate_direct_information_schema_select_query( $select_query );
			if ( null === $translated_select ) {
				return null;
			}

			if ( ! $has_column_list ) {
				$select_tokens        = $this->get_mysql_tokens( $select_query );
				$select_statement_end = $this->get_mysql_statement_end_position( $select_tokens, 1 );
				if ( null === $select_statement_end ) {
					return null;
				}

				$columns = $this->get_direct_information_schema_cte_output_columns( $select_query, $select_tokens, $select_statement_end );
				if ( empty( $columns ) ) {
					return null;
				}

				$replacements[] = array(
					'start' => $column_list_insert_position,
					'end'   => $column_list_insert_position,
					'sql'   => '(' . implode( ', ', array_map( array( $this->connection, 'quote_identifier' ), $columns ) ) . ')',
				);
			}

			$cte_sources[ strtolower( $cte_name ) ] = array(
				'name'    => $cte_name,
				'columns' => $columns,
			);

			$replacements[] = array(
				'start' => $select_start,
				'end'   => $select_end,
				'sql'   => $translated_select,
			);

			$position = $after_select_close;
			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
				continue;
			}

			break;
		}

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		$final_select_needs_direct_translation = $this->select_references_direct_information_schema_relation( $tokens, $position + 1, $statement_end )
			|| (
				0 === strcasecmp( $this->db_name, 'information_schema' )
				&& $this->information_schema_cte_final_select_has_non_cte_table_reference( $tokens, $position, $statement_end, $cte_sources )
			);

		if ( $final_select_needs_direct_translation ) {
			$select_query = $this->get_mysql_token_range_bytes( $query, $tokens, $position, $statement_end );
			if ( '' === $select_query ) {
				return null;
			}

			$translated_select = $this->translate_direct_information_schema_select_query( $select_query, $cte_sources );
			if ( null === $translated_select ) {
				return null;
			}

			$replacements[] = array(
				'start' => $position,
				'end'   => $statement_end,
				'sql'   => $translated_select,
			);
		}

		usort(
			$replacements,
			static function ( array $left, array $right ): int {
				return $left['start'] <=> $right['start'];
			}
		);

		return $this->translate_mysql_token_sequence_with_replacements_to_postgresql(
			$tokens,
			0,
			$statement_end,
			$replacements
		);
	}

	/**
	 * Check whether a final CTE SELECT under USE information_schema reads outside known CTEs.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param int              $start       SELECT token position.
	 * @param int              $end         Final statement token, exclusive.
	 * @param array            $cte_sources Known CTE sources keyed by lowercase name.
	 * @return bool Whether the final SELECT must use direct information_schema routing.
	 */
	private function information_schema_cte_final_select_has_non_cte_table_reference( array $tokens, int $start, int $end, array $cte_sources ): bool {
		$position = $start;
		while ( $position < $end ) {
			if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position ]->id ) {
				return true;
			}

			$segment_end = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::UNION_SYMBOL, $position + 1, $end ) ?? $end;
			if ( $this->information_schema_cte_select_segment_has_non_cte_table_reference( $tokens, $position, $segment_end, $cte_sources ) ) {
				return true;
			}

			if ( $segment_end >= $end ) {
				return false;
			}

			$position = $segment_end + 1;
			if (
				isset( $tokens[ $position ] )
				&& (
					WP_MySQL_Lexer::ALL_SYMBOL === $tokens[ $position ]->id
					|| WP_MySQL_Lexer::DISTINCT_SYMBOL === $tokens[ $position ]->id
				)
			) {
				++$position;
			}
		}

		return false;
	}

	/**
	 * Check whether one SELECT segment reads a non-CTE source.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param int              $start       SELECT token position.
	 * @param int              $end         Segment end, exclusive.
	 * @param array            $cte_sources Known CTE sources keyed by lowercase name.
	 * @return bool Whether the segment has a non-CTE table source.
	 */
	private function information_schema_cte_select_segment_has_non_cte_table_reference( array $tokens, int $start, int $end, array $cte_sources ): bool {
		$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, $start + 1, $end );
		if ( null === $from_position ) {
			return false;
		}

		$source_end = $this->find_direct_information_schema_source_end( $tokens, $from_position + 1, $end );
		$position   = $from_position + 1;
		while ( $position < $source_end ) {
			if ( ! isset( $tokens[ $position ] ) ) {
				return true;
			}

			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
				return true;
			}

			$identifier = $this->get_direct_information_schema_identifier_token_value( $tokens[ $position ] );
			if ( null === $identifier ) {
				++$position;
				continue;
			}

			if ( ! isset( $cte_sources[ strtolower( $identifier ) ] ) ) {
				return true;
			}

			++$position;
			while ( $position < $source_end ) {
				if (
					WP_MySQL_Lexer::COMMA_SYMBOL === ( $tokens[ $position ]->id ?? null )
					|| WP_MySQL_Lexer::JOIN_SYMBOL === ( $tokens[ $position ]->id ?? null )
				) {
					++$position;
					break;
				}

				if (
					WP_MySQL_Lexer::INNER_SYMBOL === ( $tokens[ $position ]->id ?? null )
					|| WP_MySQL_Lexer::CROSS_SYMBOL === ( $tokens[ $position ]->id ?? null )
					|| WP_MySQL_Lexer::LEFT_SYMBOL === ( $tokens[ $position ]->id ?? null )
					|| WP_MySQL_Lexer::RIGHT_SYMBOL === ( $tokens[ $position ]->id ?? null )
				) {
					while ( $position < $source_end && WP_MySQL_Lexer::JOIN_SYMBOL !== ( $tokens[ $position ]->id ?? null ) ) {
						++$position;
					}
					if ( $position < $source_end ) {
						++$position;
					}
					break;
				}

				++$position;
			}
		}

		return false;
	}

	/**
	 * Get explicit CTE output columns from a parenthesized column list.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First column token.
	 * @param int              $end    Final column token, exclusive.
	 * @return string[]|null Column names, or null when unsupported.
	 */
	private function get_direct_information_schema_cte_column_list( array $tokens, int $start, int $end ): ?array {
		$ranges = $this->split_top_level_mysql_arguments( $tokens, $start, $end );
		if ( null === $ranges || array() === $ranges ) {
			return null;
		}

		$columns = array();
		$seen    = array();
		foreach ( $ranges as $range ) {
			if ( $range['start'] + 1 !== $range['end'] || ! isset( $tokens[ $range['start'] ] ) ) {
				return null;
			}

			$column = $this->get_direct_information_schema_identifier_token_value( $tokens[ $range['start'] ] );
			if ( null === $column ) {
				return null;
			}

			$column_key = strtolower( $column );
			if ( isset( $seen[ $column_key ] ) ) {
				return null;
			}

			$seen[ $column_key ] = true;
			$columns[]          = $column;
		}

		return $columns;
	}

	/**
	 * Get CTE output columns for a supported direct information_schema SELECT body.
	 *
	 * @param string           $query         MySQL SELECT query.
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $statement_end Final statement token position, exclusive.
	 * @return string[]|null Output column names, or null when unsupported.
	 */
	private function get_direct_information_schema_cte_output_columns( string $query, array $tokens, int $statement_end ): ?array {
		if ( $this->contains_top_level_mysql_token( $tokens, 1, $statement_end, array( WP_MySQL_Lexer::UNION_SYMBOL ) ) ) {
			return $this->get_direct_information_schema_select_or_union_output_columns( $query, $tokens, $statement_end );
		}

		$context = $this->get_direct_information_schema_select_context( $query, $tokens, $statement_end );
		if ( null === $context ) {
			return null;
		}

		$projection_start = 1;
		if ( isset( $tokens[ $projection_start ] ) && WP_MySQL_Lexer::DISTINCT_SYMBOL === $tokens[ $projection_start ]->id ) {
			++$projection_start;
		}

		$ranges = $this->split_top_level_mysql_arguments( $tokens, $projection_start, $context['from_position'] );
		if ( null === $ranges || array() === $ranges ) {
			return null;
		}

		$columns = array();
		foreach ( $ranges as $range ) {
			$expression_bounds = $this->get_mysql_select_projection_expression_bounds( $tokens, $range['start'], $range['end'] );
			if ( null === $expression_bounds ) {
				return null;
			}

			$star_columns = $this->get_direct_information_schema_star_projection_output_columns(
				$tokens,
				$expression_bounds['start'],
				$expression_bounds['end'],
				$context
			);
			if ( null !== $star_columns ) {
				if ( null !== $this->get_mysql_select_projection_explicit_or_implicit_alias( $tokens, $range['start'], $range['end'] ) ) {
					return null;
				}
				$columns = array_merge( $columns, $star_columns );
				continue;
			}

			$alias = $this->get_mysql_select_projection_explicit_or_implicit_alias( $tokens, $range['start'], $range['end'] );
			if ( null !== $alias ) {
				$columns[] = $alias;
				continue;
			}

			if ( $this->is_direct_information_schema_count_star_projection( $tokens, $expression_bounds['start'], $expression_bounds['end'] ) ) {
				$columns[] = 'COUNT(*)';
				continue;
			}

			$column = $this->get_direct_information_schema_cte_projection_column_name(
				$tokens,
				$expression_bounds['start'],
				$expression_bounds['end'],
				$context
			);
			if ( null === $column ) {
				return null;
			}
			$columns[] = $column;
		}

		return $columns;
	}

	/**
	 * Get a projection column name preserving the original token spelling.
	 *
	 * @param WP_MySQL_Token[] $tokens  MySQL lexer token stream.
	 * @param int              $start   First expression token.
	 * @param int              $end     Final expression token, exclusive.
	 * @param array            $context Direct information_schema SELECT context.
	 * @return string|null Output column name, or null.
	 */
	private function get_direct_information_schema_cte_projection_column_name( array $tokens, int $start, int $end, array $context ): ?string {
		if ( $start + 1 === $end && isset( $tokens[ $start ] ) ) {
			return null === $this->get_direct_information_schema_unqualified_column_name( $tokens[ $start ], $context )
				? null
				: $this->get_direct_information_schema_identifier_token_value( $tokens[ $start ] );
		}

		if (
			$start + 3 === $end
			&& isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $start + 1 ]->id
		) {
			$qualifier = $this->get_direct_information_schema_identifier_token_value( $tokens[ $start ] );
			$source    = null === $qualifier ? null : $this->get_direct_information_schema_source_for_qualifier( $qualifier, $context );
			if ( null === $source || null === $this->get_direct_information_schema_column_name_for_token( $tokens[ $start + 2 ], $source['column_map'] ) ) {
				return null;
			}

			return $this->get_direct_information_schema_identifier_token_value( $tokens[ $start + 2 ] );
		}

		if (
			$start + 5 === $end
			&& isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ], $tokens[ $start + 3 ], $tokens[ $start + 4 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $start + 1 ]->id
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $start + 3 ]->id
		) {
			$schema = $this->get_direct_information_schema_identifier_token_value( $tokens[ $start ] );
			if ( null === $schema || 0 !== strcasecmp( $schema, 'information_schema' ) ) {
				return null;
			}

			$qualifier = $this->get_direct_information_schema_identifier_token_value( $tokens[ $start + 2 ] );
			$source    = null === $qualifier ? null : $this->get_direct_information_schema_source_for_qualifier( $qualifier, $context );
			if ( null === $source || null === $this->get_direct_information_schema_column_name_for_token( $tokens[ $start + 4 ], $source['column_map'] ) ) {
				return null;
			}

			return $this->get_direct_information_schema_identifier_token_value( $tokens[ $start + 4 ] );
		}

		return null;
	}

	/**
	 * Translate common direct MySQL information_schema SELECT statements.
	 *
	 * This is intentionally limited to supported information_schema relations as
	 * FROM/JOIN sources, main-database tables with MySQL metadata, and derived
	 * subqueries that themselves use supported direct information_schema shapes,
	 * and caller-provided CTE sources. Unsupported relation shapes and nested
	 * application-table subqueries fail closed rather than receiving a partial
	 * rewrite.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when the shape is unsupported.
	 */
	private function translate_direct_information_schema_select_query( string $query, array $cte_sources = array() ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return null;
		}

		if ( $this->contains_top_level_mysql_token( $tokens, 1, $statement_end, array( WP_MySQL_Lexer::UNION_SYMBOL ) ) ) {
			return $this->translate_direct_information_schema_union_select_query( $query, $tokens, $statement_end );
		}

		$context = $this->get_direct_information_schema_select_context( $query, $tokens, $statement_end, $cte_sources );
		if ( null === $context ) {
			return null;
		}

		$source_cover_ranges = array();
		foreach ( $context['sources'] as $source ) {
			$source_cover_ranges[] = array(
				'start' => $source['source_start'],
				'end'   => $source['source_end'],
			);
		}

		$nested_select_replacements = $this->get_direct_information_schema_nested_select_replacements(
			$query,
			$tokens,
			$context['clause_ranges']
		);
		if ( null === $nested_select_replacements ) {
			return null;
		}

		if (
			! $this->direct_information_schema_nested_selects_are_covered(
				$tokens,
				1,
				$statement_end,
				array_merge( $source_cover_ranges, $nested_select_replacements )
			)
		) {
			return null;
		}

		$replacements = array();

		$projection_start = 1;
		if ( isset( $tokens[ $projection_start ] ) && WP_MySQL_Lexer::DISTINCT_SYMBOL === $tokens[ $projection_start ]->id ) {
			++$projection_start;
		}

		$projection_ranges = $this->split_top_level_mysql_arguments( $tokens, $projection_start, $context['from_position'] );
		if ( null === $projection_ranges || array() === $projection_ranges ) {
			return null;
		}

		foreach ( $projection_ranges as $range ) {
			$expression_bounds = $this->get_mysql_select_projection_expression_bounds( $tokens, $range['start'], $range['end'] );
			if ( null === $expression_bounds ) {
				return null;
			}

			$star_select_list = $this->get_direct_information_schema_star_projection_select_list(
				$tokens,
				$expression_bounds['start'],
				$expression_bounds['end'],
				$context
			);
			if ( null !== $star_select_list ) {
				$replacements[] = array(
					'start' => $expression_bounds['start'],
					'end'   => $expression_bounds['end'],
					'sql'   => $star_select_list,
				);
				continue;
			}

			if (
				$range['start'] === $expression_bounds['start']
				&& $range['end'] === $expression_bounds['end']
				&& $this->is_direct_information_schema_count_star_projection( $tokens, $expression_bounds['start'], $expression_bounds['end'] )
			) {
				$replacements[] = array(
					'start' => $expression_bounds['start'],
					'end'   => $expression_bounds['end'],
					'sql'   => 'COUNT(*) AS ' . $this->connection->quote_identifier( 'COUNT(*)' ),
				);
				continue;
			}

			$current_database_function_replacements = $this->get_direct_information_schema_current_database_function_replacements(
				$tokens,
				$expression_bounds['start'],
				$expression_bounds['end']
			);
			if ( null === $current_database_function_replacements ) {
				return null;
			}

			$column_replacements = $this->get_direct_information_schema_column_replacements(
				$tokens,
				$expression_bounds['start'],
				$expression_bounds['end'],
				$context,
				$current_database_function_replacements
			);
			if ( null === $column_replacements ) {
				return null;
			}

			foreach ( $current_database_function_replacements as $replacement ) {
				$replacements[] = $replacement;
			}

			foreach ( $column_replacements as $replacement ) {
				$replacements[] = $replacement;
			}
		}

		foreach ( $context['join_predicate_replacements'] as $replacement ) {
			$replacements[] = $replacement;
		}

		foreach ( array_merge( $context['join_predicate_ranges'], $context['clause_ranges'] ) as $range ) {
			$current_database_function_replacements = $this->get_direct_information_schema_current_database_function_replacements(
				$tokens,
				$range['start'],
				$range['end'],
				$nested_select_replacements
			);
			if ( null === $current_database_function_replacements ) {
				return null;
			}

			$column_replacements = $this->get_direct_information_schema_column_replacements(
				$tokens,
				$range['start'],
				$range['end'],
				$context,
				array_merge( $nested_select_replacements, $current_database_function_replacements )
			);
			if ( null === $column_replacements ) {
				return null;
			}

			foreach ( $current_database_function_replacements as $replacement ) {
				$replacements[] = $replacement;
			}

			foreach ( $column_replacements as $replacement ) {
				$replacements[] = $replacement;
			}
		}

		$source_replacements = $this->get_direct_information_schema_source_replacements( $context );
		if ( null === $source_replacements ) {
			return null;
		}

		foreach ( array_merge( $source_replacements, $nested_select_replacements ) as $replacement ) {
			$replacements[] = $replacement;
		}

		usort(
			$replacements,
			static function ( array $left, array $right ): int {
				return $left['start'] <=> $right['start'];
			}
		);

		return 'SELECT ' . $this->translate_mysql_token_sequence_with_replacements_to_postgresql(
			$tokens,
			1,
			$statement_end,
			$replacements
		);
	}

	/**
	 * Translate direct information_schema UNION SELECT statements.
	 *
	 * @param string           $query         MySQL query.
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $statement_end Final statement token position, exclusive.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_direct_information_schema_union_select_query( string $query, array $tokens, int $statement_end ): ?string {
		$segments  = array();
		$operators = array();
		$position  = 0;
		$tail_start = $statement_end;

		while ( $position < $statement_end ) {
			if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position ]->id ) {
				return null;
			}

			$union_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::UNION_SYMBOL, $position + 1, $statement_end );
			$select_end     = $union_position ?? $this->get_direct_information_schema_union_tail_start( $tokens, $position + 1, $statement_end );
			if ( null === $union_position ) {
				$tail_start = $select_end;
			}
			if (
				$this->contains_top_level_mysql_token(
					$tokens,
					$position + 1,
					$select_end,
					array(
						WP_MySQL_Lexer::LIMIT_SYMBOL,
						WP_MySQL_Lexer::ORDER_SYMBOL,
					)
				)
			) {
				return null;
			}

			$select_query = $this->get_mysql_token_range_bytes( $query, $tokens, $position, $select_end );
			if ( '' === $select_query ) {
				return null;
			}

			$translated_select = $this->translate_direct_information_schema_select_query( $select_query );
			if ( null === $translated_select ) {
				return null;
			}
			$segments[] = $translated_select;

			if ( null === $union_position ) {
				break;
			}

			$operator_position = $union_position + 1;
			if ( ! isset( $tokens[ $operator_position ] ) ) {
				return null;
			}

			if ( WP_MySQL_Lexer::ALL_SYMBOL === $tokens[ $operator_position ]->id ) {
				$operators[] = 'UNION ALL';
				$position    = $operator_position + 1;
			} elseif ( WP_MySQL_Lexer::DISTINCT_SYMBOL === $tokens[ $operator_position ]->id ) {
				$operators[] = 'UNION';
				$position    = $operator_position + 1;
			} else {
				$operators[] = 'UNION';
				$position    = $operator_position;
			}
		}

		if ( count( $segments ) < 2 || count( $operators ) + 1 !== count( $segments ) ) {
			return null;
		}

		$sql = $segments[0];
		foreach ( $operators as $index => $operator ) {
			$sql .= ' ' . $operator . ' ' . $segments[ $index + 1 ];
		}

		if ( $tail_start < $statement_end ) {
			$columns = $this->get_direct_information_schema_union_select_output_columns( $query, $tokens, $tail_start );
			if ( null === $columns || array() === $columns ) {
				return null;
			}

			$tail_sql = $this->translate_direct_information_schema_union_tail_to_postgresql(
				$tokens,
				$tail_start,
				$statement_end,
				$columns
			);
			if ( null === $tail_sql ) {
				return null;
			}

			$sql .= $tail_sql;
		}

		return $sql;
	}

	/**
	 * Get the start of a top-level ORDER BY/LIMIT tail for an information_schema UNION.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token to inspect.
	 * @param int              $end    Final token, exclusive.
	 * @return int Tail start, or $end when absent.
	 */
	private function get_direct_information_schema_union_tail_start( array $tokens, int $start, int $end ): int {
		$tail_start = $end;
		foreach ( array( WP_MySQL_Lexer::ORDER_SYMBOL, WP_MySQL_Lexer::LIMIT_SYMBOL ) as $token_id ) {
			$position = $this->find_top_level_mysql_token( $tokens, $token_id, $start, $end );
			if ( null !== $position ) {
				$tail_start = min( $tail_start, $position );
			}
		}

		return $tail_start;
	}

	/**
	 * Translate a top-level ORDER BY/LIMIT tail for an information_schema UNION.
	 *
	 * @param WP_MySQL_Token[] $tokens  MySQL lexer token stream.
	 * @param int              $start   First tail token.
	 * @param int              $end     Final tail token, exclusive.
	 * @param string[]         $columns UNION output column names.
	 * @return string|null PostgreSQL tail SQL, or null when unsupported.
	 */
	private function translate_direct_information_schema_union_tail_to_postgresql( array $tokens, int $start, int $end, array $columns ): ?string {
		$position = $start;
		$sql      = '';

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::ORDER_SYMBOL === $tokens[ $position ]->id ) {
			$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, $position + 1, $end );
			$order_end      = $limit_position ?? $end;
			$order_sql      = $this->translate_direct_information_schema_union_order_by_clause_to_postgresql(
				$tokens,
				$position,
				$order_end,
				$columns
			);
			if ( null === $order_sql ) {
				return null;
			}

			$sql     .= $order_sql;
			$position = $order_end;
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::LIMIT_SYMBOL === $tokens[ $position ]->id ) {
			$limit_sql = $this->translate_simple_dml_limit_clause_to_postgresql( $tokens, $position, $end, true );
			if ( null === $limit_sql ) {
				return null;
			}

			$sql     .= $limit_sql;
			$position = $end;
		}

		return $position === $end && '' !== $sql ? $sql : null;
	}

	/**
	 * Translate an information_schema UNION ORDER BY clause.
	 *
	 * PostgreSQL UNION ORDER BY can only reference output columns. Keep this
	 * intentionally bounded to MySQL output aliases/ordinals and simple
	 * directions so unsupported expressions still fail explicitly.
	 *
	 * @param WP_MySQL_Token[] $tokens  MySQL lexer token stream.
	 * @param int              $start   ORDER token position.
	 * @param int              $end     Final ORDER BY token, exclusive.
	 * @param string[]         $columns UNION output column names.
	 * @return string|null PostgreSQL ORDER BY clause, or null when unsupported.
	 */
	private function translate_direct_information_schema_union_order_by_clause_to_postgresql( array $tokens, int $start, int $end, array $columns ): ?string {
		if (
			$start + 2 >= $end
			|| WP_MySQL_Lexer::ORDER_SYMBOL !== ( $tokens[ $start ]->id ?? null )
			|| WP_MySQL_Lexer::BY_SYMBOL !== ( $tokens[ $start + 1 ]->id ?? null )
		) {
			return null;
		}

		$ranges = $this->split_top_level_mysql_arguments( $tokens, $start + 2, $end );
		if ( null === $ranges || array() === $ranges ) {
			return null;
		}

		$column_lookup = array();
		foreach ( $columns as $column ) {
			$column_lookup[ strtolower( $column ) ] = $column;
		}

		$items = array();
		foreach ( $ranges as $range ) {
			$item_start = $range['start'];
			$item_end   = $range['end'];
			$direction  = '';
			if (
				$item_start < $item_end
				&& (
					WP_MySQL_Lexer::ASC_SYMBOL === ( $tokens[ $item_end - 1 ]->id ?? null )
					|| WP_MySQL_Lexer::DESC_SYMBOL === ( $tokens[ $item_end - 1 ]->id ?? null )
				)
			) {
				$direction = ' ' . strtoupper( $tokens[ $item_end - 1 ]->get_bytes() );
				--$item_end;
			}

			if ( $item_start >= $item_end ) {
				return null;
			}

			if (
				$item_start + 1 === $item_end
				&& isset( $tokens[ $item_start ] )
				&& $this->is_mysql_unsigned_integer_token( $tokens[ $item_start ] )
			) {
				$ordinal = (int) $tokens[ $item_start ]->get_value();
				if ( $ordinal < 1 || $ordinal > count( $columns ) ) {
					return null;
				}

				$items[] = $tokens[ $item_start ]->get_bytes() . $direction;
				continue;
			}

			if ( $item_start + 1 !== $item_end || ! isset( $tokens[ $item_start ] ) ) {
				return null;
			}

			$column = $this->get_direct_information_schema_identifier_token_value( $tokens[ $item_start ] );
			if ( null === $column ) {
				return null;
			}

			$column_key = strtolower( $column );
			if ( ! isset( $column_lookup[ $column_key ] ) ) {
				return null;
			}

			$items[] = $this->connection->quote_identifier( $column_lookup[ $column_key ] ) . $direction;
		}

		return empty( $items ) ? null : ' ORDER BY ' . implode( ', ', $items );
	}

	/**
	 * Get the direct information_schema SELECT context for supported sources.
	 *
	 * @param string           $query         Original MySQL query.
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $statement_end Final statement token position, exclusive.
	 * @return array{sources: array[], from_position: int, source_start: int, source_end: int, join_predicate_ranges: array[], join_predicate_replacements: array[], using_columns: array[], clause_ranges: array[]}|null Context, or null.
	 */
	private function get_direct_information_schema_select_context( string $query, array $tokens, int $statement_end, array $cte_sources = array() ): ?array {
		$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, 1, $statement_end );
		if ( null === $from_position || 1 === $from_position ) {
			return null;
		}

		$source_start = $from_position + 1;
		$source_end   = $this->find_direct_information_schema_source_end( $tokens, $source_start, $statement_end );
		if ( $source_start >= $source_end ) {
			return null;
		}

		$sources = $this->parse_direct_information_schema_select_sources( $query, $tokens, $source_start, $source_end, $cte_sources );
		if ( null === $sources ) {
			return null;
		}

		$clause_ranges = array();
		$clause_starts = array_filter(
			array(
				$this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, $source_end, $statement_end ),
				$this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::GROUP_SYMBOL, $source_end, $statement_end ),
				$this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::HAVING_SYMBOL, $source_end, $statement_end ),
				$this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::ORDER_SYMBOL, $source_end, $statement_end ),
				$this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, $source_end, $statement_end ),
			),
			'is_int'
		);
		sort( $clause_starts );
		foreach ( $clause_starts as $index => $start ) {
			$end             = $clause_starts[ $index + 1 ] ?? $statement_end;
			$clause_ranges[] = array(
				'start' => $start,
				'end'   => $end,
			);
		}

		return array(
			'sources'                     => $sources['sources'],
			'from_position'               => $from_position,
			'source_start'                => $source_start,
			'source_end'                  => $source_end,
			'join_predicate_ranges'       => $sources['join_predicate_ranges'],
			'join_predicate_replacements' => $sources['join_predicate_replacements'],
			'using_columns'               => $sources['using_columns'],
			'clause_ranges'               => $clause_ranges,
		);
	}

	/**
	 * Find the end of the information_schema FROM source range.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $start         First source token position.
	 * @param int              $statement_end Final statement token position, exclusive.
	 * @return int Source end position, exclusive.
	 */
	private function find_direct_information_schema_source_end( array $tokens, int $start, int $statement_end ): int {
		$source_end = $statement_end;
		foreach (
			array(
				WP_MySQL_Lexer::WHERE_SYMBOL,
				WP_MySQL_Lexer::GROUP_SYMBOL,
				WP_MySQL_Lexer::HAVING_SYMBOL,
				WP_MySQL_Lexer::ORDER_SYMBOL,
				WP_MySQL_Lexer::LIMIT_SYMBOL,
				WP_MySQL_Lexer::FOR_SYMBOL,
				WP_MySQL_Lexer::LOCK_SYMBOL,
			) as $token_id
		) {
			$position = $this->find_top_level_mysql_token( $tokens, $token_id, $start, $statement_end );
			if ( null !== $position ) {
				$source_end = min( $source_end, $position );
			}
		}

		return $source_end;
	}

	/**
	 * Parse supported direct information_schema FROM/JOIN sources.
	 *
	 * @param string           $query  Original MySQL query.
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First source token position.
	 * @param int              $end    Source end position, exclusive.
	 * @return array{sources: array[], join_predicate_ranges: array[], join_predicate_replacements: array[], using_columns: array[]}|null Parsed sources, or null.
	 */
	private function parse_direct_information_schema_select_sources( string $query, array $tokens, int $start, int $end, array $cte_sources = array() ): ?array {
		if (
			0 !== strcasecmp( $this->db_name, 'information_schema' )
			&& ! $this->direct_information_schema_source_range_references_information_schema( $tokens, $start, $end )
		) {
			return null;
		}

		$sources                     = array();
		$aliases                     = array();
		$join_predicate_ranges       = array();
		$join_predicate_replacements = array();
		$using_columns               = array();
		$position                    = $start;

		while ( $position < $end ) {
			$source_start = $position;
			$source       = $this->parse_direct_information_schema_select_source( $query, $tokens, $position, $end, $cte_sources );
			if ( null === $source ) {
				return null;
			}

			$alias_key = strtolower( $source['alias'] );
			if ( isset( $aliases[ $alias_key ] ) ) {
				return null;
			}

			$columns = $source['columns'] ?? $this->get_direct_information_schema_relation_columns( $source['view'] );
			if ( null === $columns ) {
				return null;
			}

			$source['columns']      = $columns;
			$source['column_map']   = $this->get_direct_information_schema_relation_column_map( $columns );
			$source['source_start'] = $source_start;
			$source['source_end']   = $source['position'];
			$sources[]              = $source;
			$aliases[ $alias_key ]  = true;
			$position               = $source['position'];

			if ( count( $sources ) > 6 ) {
				return null;
			}

			$separator = $this->find_next_direct_information_schema_source_separator( $tokens, $position, $end );
			if ( null === $separator ) {
				$predicate = $this->get_direct_information_schema_join_predicate_range_data(
					$tokens,
					$position,
					$end,
					$sources,
					$using_columns
				);
				if ( null === $predicate ) {
					return null;
				}
				if ( isset( $predicate['range'] ) ) {
					$join_predicate_ranges[] = $predicate['range'];
				}
				if ( isset( $predicate['replacement'] ) ) {
					$join_predicate_replacements[] = $predicate['replacement'];
				}
				if ( isset( $predicate['using_columns'] ) ) {
					$using_columns = $this->merge_direct_information_schema_using_columns( $using_columns, $predicate['using_columns'] );
				}
				$position = $end;
				break;
			}

			if ( 'comma' === $separator['type'] ) {
				if ( $position !== $separator['start'] ) {
					return null;
				}

				$position = $separator['source_start'];
				continue;
			}

			$predicate = $this->get_direct_information_schema_join_predicate_range_data(
				$tokens,
				$position,
				$separator['start'],
				$sources,
				$using_columns
			);
			if ( null === $predicate ) {
				return null;
			}
			if ( isset( $predicate['range'] ) ) {
				$join_predicate_ranges[] = $predicate['range'];
			}
			if ( isset( $predicate['replacement'] ) ) {
				$join_predicate_replacements[] = $predicate['replacement'];
			}
			if ( isset( $predicate['using_columns'] ) ) {
				$using_columns = $this->merge_direct_information_schema_using_columns( $using_columns, $predicate['using_columns'] );
			}

			$position = $separator['source_start'];
		}

		if ( empty( $sources ) ) {
			return null;
		}

		if ( ! $this->direct_information_schema_sources_include_information_schema_relation( $sources ) ) {
			return null;
		}

		if ( count( $sources ) > 1 && ! $this->direct_information_schema_sources_are_joinable( $sources ) ) {
			return null;
		}

		return array(
			'sources'                     => $sources,
			'join_predicate_ranges'       => $join_predicate_ranges,
			'join_predicate_replacements' => $join_predicate_replacements,
			'using_columns'               => $using_columns,
		);
	}

	/**
	 * Parse one supported direct information_schema source at the current token.
	 *
	 * @param string           $query    Original MySQL query.
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Source token position.
	 * @param int              $end      Source range end position, exclusive.
	 * @return array{view?: string, alias: string, position: int, relation_sql?: string, columns?: string[]}|null Parsed source, or null.
	 */
	private function parse_direct_information_schema_select_source( string $query, array $tokens, int $position, int $end, array $cte_sources = array() ): ?array {
		if ( isset( $tokens[ $position ], $tokens[ $position + 1 ] ) && WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
			return $this->parse_direct_information_schema_derived_select_source( $query, $tokens, $position, $end );
		}

		$source_start = $position;
		$first        = $this->get_direct_information_schema_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $first ) {
			return null;
		}

		if ( isset( $cte_sources[ strtolower( $first ) ] ) ) {
			return $this->parse_direct_information_schema_cte_select_source( $tokens, $position, $end, $cte_sources[ strtolower( $first ) ] );
		}

		++$position;
		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position ]->id
		) {
			if ( 0 !== strcasecmp( $first, 'information_schema' ) ) {
				if ( 0 === strcasecmp( $first, $this->main_db_name ) ) {
					return $this->parse_direct_information_schema_main_table_source( $tokens, $source_start, $end );
				}

				return null;
			}

			$view = $this->get_direct_information_schema_identifier_token_value( $tokens[ $position + 1 ] );
			if ( null === $view ) {
				return null;
			}
			$position += 2;
		} else {
			if ( 0 !== strcasecmp( $this->db_name, 'information_schema' ) ) {
				return $this->parse_direct_information_schema_main_table_source( $tokens, $source_start, $end );
			}

			$view = $first;
		}

		$view = strtolower( $view );
		if ( null === $this->get_direct_information_schema_relation_columns( $view ) ) {
			return null;
		}

		$alias = $view;
		if ( $position < $end ) {
			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::AS_SYMBOL === $tokens[ $position ]->id ) {
				++$position;

				$parsed_alias = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
				if ( null === $parsed_alias ) {
					return null;
				}

				$alias = $parsed_alias;
				++$position;
			} else {
				$parsed_alias = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
				if ( null !== $parsed_alias ) {
					$alias = $parsed_alias;
					++$position;
				}
			}
		}

		return array(
			'view'     => $view,
			'alias'    => $alias,
			'position' => $position,
		);
	}

	/**
	 * Parse a CTE source used by a final direct information_schema SELECT.
	 *
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param int              $position   Source token position.
	 * @param int              $end        Source range end position, exclusive.
	 * @param array            $cte_source CTE source metadata.
	 * @return array{cte:string,alias:string,position:int,columns:string[]}|null Parsed source, or null.
	 */
	private function parse_direct_information_schema_cte_select_source( array $tokens, int $position, int $end, array $cte_source ): ?array {
		if ( ! isset( $cte_source['name'], $cte_source['columns'] ) || ! is_array( $cte_source['columns'] ) ) {
			return null;
		}

		$cte_name = (string) $cte_source['name'];
		$alias    = $cte_name;
		++$position;

		if ( $position < $end ) {
			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::AS_SYMBOL === $tokens[ $position ]->id ) {
				++$position;

				$parsed_alias = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
				if ( null === $parsed_alias ) {
					return null;
				}

				$alias = $parsed_alias;
				++$position;
			} else {
				$parsed_alias = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
				if ( null !== $parsed_alias ) {
					$alias = $parsed_alias;
					++$position;
				}
			}
		}

		return array(
			'cte'      => $cte_name,
			'alias'    => $alias,
			'position' => $position,
			'columns'  => $cte_source['columns'],
		);
	}

	/**
	 * Parse a main-database table source used in a mixed information_schema SELECT.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Source token position.
	 * @param int              $end      Source range end position, exclusive.
	 * @return array{table:string,alias:string,position:int,columns:string[]}|null Parsed source, or null.
	 */
	private function parse_direct_information_schema_main_table_source( array $tokens, int $position, int $end ): ?array {
		$reference = $this->parse_mysql_main_database_table_reference( $tokens, $position, $end );
		if ( null === $reference ) {
			return null;
		}

		$columns = $this->get_direct_information_schema_main_table_columns( $reference['table'] );
		if ( null === $columns ) {
			return null;
		}

		return array(
			'table'    => $reference['table'],
			'alias'    => null === $reference['alias'] ? $reference['table'] : $reference['alias'],
			'position' => $position,
			'columns'  => $columns,
		);
	}

	/**
	 * Get MySQL-facing column names for a main-database table source.
	 *
	 * @param string $table_name Table name.
	 * @return string[]|null Ordered column names, or null when unavailable.
	 */
	private function get_direct_information_schema_main_table_columns( string $table_name ): ?array {
		$columns = array();
		foreach ( $this->get_mysql_dml_column_metadata( $table_name ) as $column ) {
			if ( ! isset( $column['column_name'] ) ) {
				return null;
			}
			$columns[] = (string) $column['column_name'];
		}

		return empty( $columns ) ? null : $columns;
	}

	/**
	 * Parse a derived information_schema SELECT source.
	 *
	 * @param string           $query    Original MySQL query.
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Source token position.
	 * @param int              $end      Source range end position, exclusive.
	 * @return array{alias:string,position:int,relation_sql:string,columns:string[]}|null Parsed source, or null.
	 */
	private function parse_direct_information_schema_derived_select_source( string $query, array $tokens, int $position, int $end ): ?array {
		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
		if (
			null === $after_close
			|| ! isset( $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return null;
		}

		$select_start = $position + 1;
		$select_end   = $after_close - 1;
		$select_query = $this->get_mysql_token_range_bytes( $query, $tokens, $select_start, $select_end );
		if ( '' === $select_query ) {
			return null;
		}

		$translated_select = $this->translate_direct_information_schema_select_query( $select_query );
		if ( null === $translated_select ) {
			return null;
		}

		$select_tokens        = $this->get_mysql_tokens( $select_query );
		$select_statement_end = $this->get_mysql_statement_end_position( $select_tokens, 1 );
		if ( null === $select_statement_end ) {
			return null;
		}

		$columns = $this->get_direct_information_schema_select_or_union_output_columns(
			$select_query,
			$select_tokens,
			$select_statement_end
		);
		if ( null === $columns || array() === $columns ) {
			return null;
		}

		$position = $after_close;
		$alias    = 'derived';
		if ( $position < $end ) {
			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::AS_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
				$parsed_alias = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
				if ( null === $parsed_alias ) {
					return null;
				}
				$alias = $parsed_alias;
				++$position;
			} else {
				$parsed_alias = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
				if ( null !== $parsed_alias ) {
					$alias = $parsed_alias;
					++$position;
				}
			}
		}

		return array(
			'alias'        => $alias,
			'position'     => $position,
			'relation_sql' => $translated_select,
			'columns'      => $columns,
		);
	}

	/**
	 * Get output column names for a supported information_schema SELECT or UNION SELECT.
	 *
	 * @param string           $query         MySQL SELECT query.
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $statement_end Final statement token position, exclusive.
	 * @return string[]|null Output column names, or null when unsupported.
	 */
	private function get_direct_information_schema_select_or_union_output_columns( string $query, array $tokens, int $statement_end ): ?array {
		if ( ! $this->contains_top_level_mysql_token( $tokens, 1, $statement_end, array( WP_MySQL_Lexer::UNION_SYMBOL ) ) ) {
			$context = $this->get_direct_information_schema_select_context( $query, $tokens, $statement_end );
			return null === $context ? null : $this->get_direct_information_schema_select_output_columns( $tokens, $context );
		}

		return $this->get_direct_information_schema_union_select_output_columns( $query, $tokens, $statement_end );
	}

	/**
	 * Get output column names for a supported information_schema UNION SELECT.
	 *
	 * MySQL exposes the first SELECT branch's output names for a UNION result.
	 * Each branch still has to be a supported direct information_schema SELECT
	 * with the same number of columns.
	 *
	 * @param string           $query         MySQL UNION query.
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $statement_end Final statement token position, exclusive.
	 * @return string[]|null Output column names, or null when unsupported.
	 */
	private function get_direct_information_schema_union_select_output_columns( string $query, array $tokens, int $statement_end ): ?array {
		$columns        = null;
		$position       = 0;
		$segment_count  = 0;

		while ( $position < $statement_end ) {
			if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position ]->id ) {
				return null;
			}

			$union_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::UNION_SYMBOL, $position + 1, $statement_end );
			$select_end     = $union_position ?? $statement_end;
			if (
				$this->contains_top_level_mysql_token(
					$tokens,
					$position + 1,
					$select_end,
					array(
						WP_MySQL_Lexer::LIMIT_SYMBOL,
						WP_MySQL_Lexer::ORDER_SYMBOL,
					)
				)
			) {
				return null;
			}

			$select_query = $this->get_mysql_token_range_bytes( $query, $tokens, $position, $select_end );
			if ( '' === $select_query ) {
				return null;
			}

			$select_tokens        = $this->get_mysql_tokens( $select_query );
			$select_statement_end = $this->get_mysql_statement_end_position( $select_tokens, 1 );
			if ( null === $select_statement_end ) {
				return null;
			}

			$context = $this->get_direct_information_schema_select_context( $select_query, $select_tokens, $select_statement_end );
			if ( null === $context ) {
				return null;
			}

			$branch_columns = $this->get_direct_information_schema_select_output_columns( $select_tokens, $context );
			if ( null === $branch_columns || array() === $branch_columns ) {
				return null;
			}

			if ( null === $columns ) {
				$columns = $branch_columns;
			} elseif ( count( $columns ) !== count( $branch_columns ) ) {
				return null;
			}

			++$segment_count;
			if ( null === $union_position ) {
				break;
			}

			$operator_position = $union_position + 1;
			if ( ! isset( $tokens[ $operator_position ] ) ) {
				return null;
			}

			if (
				WP_MySQL_Lexer::ALL_SYMBOL === $tokens[ $operator_position ]->id
				|| WP_MySQL_Lexer::DISTINCT_SYMBOL === $tokens[ $operator_position ]->id
			) {
				$position = $operator_position + 1;
			} else {
				$position = $operator_position;
			}
		}

		return 2 <= $segment_count ? $columns : null;
	}

	/**
	 * Build source replacement ranges for a direct information_schema context.
	 *
	 * @param array $context Direct information_schema SELECT context.
	 * @return array[]|null Replacement ranges, or null when a source is unsupported.
	 */
	private function get_direct_information_schema_source_replacements( array $context ): ?array {
		$replacements = array();
		foreach ( $context['sources'] as $source ) {
			if ( isset( $source['cte'] ) ) {
				$replacements[] = array(
					'start' => $source['source_start'],
					'end'   => $source['source_end'],
					'sql'   => sprintf(
						'%s AS %s',
						$this->connection->quote_identifier( $source['cte'] ),
						$this->connection->quote_identifier( $source['alias'] )
					),
				);
				continue;
			}

			if ( isset( $source['table'] ) ) {
				$replacements[] = array(
					'start' => $source['source_start'],
					'end'   => $source['source_end'],
					'sql'   => $this->get_postgresql_dml_table_reference_sql( $source['table'], $source['alias'] ),
				);
				continue;
			}

			$relation_sql = $source['relation_sql'] ?? $this->get_direct_information_schema_relation_sql( $source['view'] ?? '' );
			if ( null === $relation_sql ) {
				return null;
			}

			$replacements[] = array(
				'start' => $source['source_start'],
				'end'   => $source['source_end'],
				'sql'   => sprintf(
					'(%s) AS %s',
					$relation_sql,
					$this->connection->quote_identifier( $source['alias'] )
				),
			);
		}

		return $replacements;
	}

	/**
	 * Get output column names for a supported direct information_schema SELECT.
	 *
	 * @param WP_MySQL_Token[] $tokens  MySQL lexer token stream.
	 * @param array            $context Direct information_schema SELECT context.
	 * @return string[]|null Output column names, or null when unsupported.
	 */
	private function get_direct_information_schema_select_output_columns( array $tokens, array $context ): ?array {
		$projection_start = 1;
		if ( isset( $tokens[ $projection_start ] ) && WP_MySQL_Lexer::DISTINCT_SYMBOL === $tokens[ $projection_start ]->id ) {
			++$projection_start;
		}

		$ranges = $this->split_top_level_mysql_arguments( $tokens, $projection_start, $context['from_position'] );
		if ( null === $ranges || array() === $ranges ) {
			return null;
		}

		$columns = array();
		foreach ( $ranges as $range ) {
			$expression_bounds = $this->get_mysql_select_projection_expression_bounds( $tokens, $range['start'], $range['end'] );
			if ( null === $expression_bounds ) {
				return null;
			}

			$star_columns = $this->get_direct_information_schema_star_projection_output_columns(
				$tokens,
				$expression_bounds['start'],
				$expression_bounds['end'],
				$context
			);
			if ( null !== $star_columns ) {
				if ( null !== $this->get_mysql_select_projection_explicit_or_implicit_alias( $tokens, $range['start'], $range['end'] ) ) {
					return null;
				}
				$columns = array_merge( $columns, $star_columns );
				continue;
			}

			$alias = $this->get_mysql_select_projection_explicit_or_implicit_alias( $tokens, $range['start'], $range['end'] );
			if ( null !== $alias ) {
				$columns[] = $alias;
				continue;
			}

			if ( $this->is_direct_information_schema_count_star_projection( $tokens, $expression_bounds['start'], $expression_bounds['end'] ) ) {
				$columns[] = 'COUNT(*)';
				continue;
			}

			$column = $this->get_direct_information_schema_projection_column_name(
				$tokens,
				$expression_bounds['start'],
				$expression_bounds['end'],
				$context
			);
			if ( null === $column ) {
				return null;
			}
			$columns[] = $column;
		}

		return $columns;
	}

	/**
	 * Get an explicit or implicit SELECT projection alias.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First projection token.
	 * @param int              $end    Final projection token, exclusive.
	 * @return string|null Alias, or null.
	 */
	private function get_mysql_select_projection_explicit_or_implicit_alias( array $tokens, int $start, int $end ): ?string {
		$as_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::AS_SYMBOL, $start, $end );
		if ( null !== $as_position ) {
			if ( $as_position <= $start || $as_position + 2 !== $end ) {
				return null;
			}

			return $this->get_mysql_projection_alias_token_value( $tokens[ $as_position + 1 ] ?? null );
		}

		return $this->get_mysql_implicit_projection_alias( $tokens, $start, $end );
	}

	/**
	 * Get output columns for a star projection.
	 *
	 * @param WP_MySQL_Token[] $tokens  MySQL lexer token stream.
	 * @param int              $start   First expression token.
	 * @param int              $end     Final expression token, exclusive.
	 * @param array            $context Direct information_schema SELECT context.
	 * @return string[]|null Output columns, or null when not a supported star.
	 */
	private function get_direct_information_schema_star_projection_output_columns( array $tokens, int $start, int $end, array $context ): ?array {
		if ( $start + 1 === $end && isset( $tokens[ $start ] ) && '*' === $tokens[ $start ]->get_bytes() ) {
			$columns = array();
			foreach ( $context['sources'] as $source ) {
				$columns = array_merge( $columns, $source['columns'] );
			}
			return $columns;
		}

		if (
			$start + 3 === $end
			&& isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $start + 1 ]->id
			&& '*' === $tokens[ $start + 2 ]->get_bytes()
		) {
			$qualifier = $this->get_direct_information_schema_identifier_token_value( $tokens[ $start ] );
			$source    = null === $qualifier ? null : $this->get_direct_information_schema_source_for_qualifier( $qualifier, $context );
			return null === $source ? null : $source['columns'];
		}

		if (
			$start + 5 === $end
			&& isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ], $tokens[ $start + 3 ], $tokens[ $start + 4 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $start + 1 ]->id
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $start + 3 ]->id
			&& '*' === $tokens[ $start + 4 ]->get_bytes()
		) {
			$schema = $this->get_direct_information_schema_identifier_token_value( $tokens[ $start ] );
			if ( null === $schema || 0 !== strcasecmp( $schema, 'information_schema' ) ) {
				return null;
			}

			$qualifier = $this->get_direct_information_schema_identifier_token_value( $tokens[ $start + 2 ] );
			$source    = null === $qualifier ? null : $this->get_direct_information_schema_source_for_qualifier( $qualifier, $context );
			return null === $source ? null : $source['columns'];
		}

		return null;
	}

	/**
	 * Get the visible column name for a simple information_schema projection.
	 *
	 * @param WP_MySQL_Token[] $tokens  MySQL lexer token stream.
	 * @param int              $start   First expression token.
	 * @param int              $end     Final expression token, exclusive.
	 * @param array            $context Direct information_schema SELECT context.
	 * @return string|null Output column name, or null.
	 */
	private function get_direct_information_schema_projection_column_name( array $tokens, int $start, int $end, array $context ): ?string {
		if ( $start + 1 === $end && isset( $tokens[ $start ] ) ) {
			return $this->get_direct_information_schema_unqualified_column_name( $tokens[ $start ], $context );
		}

		if (
			$start + 3 === $end
			&& isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $start + 1 ]->id
		) {
			$qualifier = $this->get_direct_information_schema_identifier_token_value( $tokens[ $start ] );
			$source    = null === $qualifier ? null : $this->get_direct_information_schema_source_for_qualifier( $qualifier, $context );
			return null === $source ? null : $this->get_direct_information_schema_column_name_for_token( $tokens[ $start + 2 ], $source['column_map'] );
		}

		if (
			$start + 5 === $end
			&& isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ], $tokens[ $start + 3 ], $tokens[ $start + 4 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $start + 1 ]->id
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $start + 3 ]->id
		) {
			$schema = $this->get_direct_information_schema_identifier_token_value( $tokens[ $start ] );
			if ( null === $schema || 0 !== strcasecmp( $schema, 'information_schema' ) ) {
				return null;
			}

			$qualifier = $this->get_direct_information_schema_identifier_token_value( $tokens[ $start + 2 ] );
			$source    = null === $qualifier ? null : $this->get_direct_information_schema_source_for_qualifier( $qualifier, $context );
			return null === $source ? null : $this->get_direct_information_schema_column_name_for_token( $tokens[ $start + 4 ], $source['column_map'] );
		}

		return null;
	}

	/**
	 * Find the next supported explicit source separator in a FROM source range.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token position.
	 * @param int              $end    Final token position, exclusive.
	 * @return array{type: string, start: int, source_start: int}|null Separator bounds, or null.
	 */
	private function find_next_direct_information_schema_source_separator( array $tokens, int $start, int $end ): ?array {
		$depth = 0;
		for ( $position = $start; $position < $end; $position++ ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
				++$depth;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $position ]->id ) {
				--$depth;
				if ( $depth < 0 ) {
					return null;
				}
				continue;
			}

			if ( 0 !== $depth ) {
				continue;
			}

			if ( WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id ) {
				return array(
					'type'         => 'comma',
					'start'        => $position,
					'source_start' => $position + 1,
				);
			}

			if ( WP_MySQL_Lexer::JOIN_SYMBOL === $tokens[ $position ]->id ) {
				return array(
					'type'         => 'join',
					'start'        => $position,
					'source_start' => $position + 1,
				);
			}

			if (
				isset( $tokens[ $position + 1 ] )
				&& (
					WP_MySQL_Lexer::INNER_SYMBOL === $tokens[ $position ]->id
					|| WP_MySQL_Lexer::CROSS_SYMBOL === $tokens[ $position ]->id
				)
				&& WP_MySQL_Lexer::JOIN_SYMBOL === $tokens[ $position + 1 ]->id
			) {
				return array(
					'type'         => 'join',
					'start'        => $position,
					'source_start' => $position + 2,
				);
			}

			if (
				WP_MySQL_Lexer::LEFT_SYMBOL !== $tokens[ $position ]->id
				&& WP_MySQL_Lexer::RIGHT_SYMBOL !== $tokens[ $position ]->id
			) {
				continue;
			}

			$join_position = $position + 1;
			if ( isset( $tokens[ $join_position ] ) && WP_MySQL_Lexer::OUTER_SYMBOL === $tokens[ $join_position ]->id ) {
				++$join_position;
			}

			if ( isset( $tokens[ $join_position ] ) && WP_MySQL_Lexer::JOIN_SYMBOL === $tokens[ $join_position ]->id ) {
				return array(
					'type'         => 'join',
					'start'        => $position,
					'source_start' => $join_position + 1,
				);
			}
		}

		return null;
	}

	/**
	 * Check whether a JOIN predicate range is simple enough for source rewriting.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token position.
	 * @param int              $end    Final token position, exclusive.
	 * @return bool Whether the range is supported.
	 */
	private function is_direct_information_schema_join_predicate_range_supported( array $tokens, int $start, int $end ): bool {
		return null !== $this->get_direct_information_schema_join_predicate_range_data( $tokens, $start, $end, array(), array() );
	}

	/**
	 * Get validation and replacement data for a supported information_schema JOIN predicate.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $start         First token position.
	 * @param int              $end           Final token position, exclusive.
	 * @param array[]          $sources       Parsed sources through the right-hand join source.
	 * @param array            $using_columns Previously merged USING columns.
	 * @return array{range?: array{start:int,end:int}, replacement?: array{start:int,end:int,sql:string}, using_columns?: array}|null Predicate data, or null when unsupported.
	 */
	private function get_direct_information_schema_join_predicate_range_data( array $tokens, int $start, int $end, array $sources, array $using_columns ): ?array {
		if ( $start === $end ) {
			return array();
		}

		if (
			isset( $tokens[ $start ] )
			&& WP_MySQL_Lexer::USING_SYMBOL === $tokens[ $start ]->id
		) {
			$using = $this->get_direct_information_schema_join_using_replacement( $tokens, $start, $end, $sources, $using_columns );
			if ( null === $using ) {
				return null;
			}

			return $using;
		}

		if (
			! isset( $tokens[ $start ] )
			|| WP_MySQL_Lexer::ON_SYMBOL !== $tokens[ $start ]->id
		) {
			return null;
		}

		$using = $this->get_direct_information_schema_join_on_using_replacement( $tokens, $start, $end, $sources, $using_columns );
		if ( null !== $using ) {
			return $using;
		}

		if ( $this->contains_mysql_token(
			$tokens,
			$start + 1,
			$end,
			array(
				WP_MySQL_Lexer::SELECT_SYMBOL,
				WP_MySQL_Lexer::UNION_SYMBOL,
			)
		) ) {
			return null;
		}

		return array(
			'range' => array(
				'start' => $start,
				'end'   => $end,
			),
		);
	}

	/**
	 * Get a PostgreSQL USING predicate replacement for an information_schema JOIN.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $start         USING token position.
	 * @param int              $end           Final token position, exclusive.
	 * @param array[]          $sources       Parsed sources through the right-hand join source.
	 * @param array            $using_columns Previously merged USING columns.
	 * @return array{replacement: array{start:int,end:int,sql:string}, using_columns: array}|null Replacement data, or null when unsupported.
	 */
	private function get_direct_information_schema_join_using_replacement( array $tokens, int $start, int $end, array $sources, array $using_columns ): ?array {
		if (
			count( $sources ) < 2
			|| ! isset( $tokens[ $start ], $tokens[ $start + 1 ] )
			|| WP_MySQL_Lexer::USING_SYMBOL !== $tokens[ $start ]->id
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $start + 1 ]->id
		) {
			return null;
		}

		$current_source   = $sources[ count( $sources ) - 1 ];
		$previous_sources = array_slice( $sources, 0, -1 );
		$position         = $start + 2;
		$columns          = array();
		$seen_columns     = array();
		$new_using        = array();

		while ( $position < $end && isset( $tokens[ $position ] ) ) {
			$current_column = $this->get_direct_information_schema_column_name_for_token( $tokens[ $position ], $current_source['column_map'] );
			if ( null === $current_column ) {
				return null;
			}

			$column_key = strtolower( $current_column );
			if ( isset( $seen_columns[ $column_key ] ) ) {
				return null;
			}
			$seen_columns[ $column_key ] = true;

			$previous_matches = array();
			foreach ( $previous_sources as $source ) {
				if ( isset( $source['column_map'][ $column_key ] ) ) {
					$previous_matches[] = $source;
				}
			}

			if ( empty( $previous_matches ) ) {
				return null;
			}

			$matched_aliases = array();
			foreach ( $previous_matches as $source ) {
				$matched_aliases[ strtolower( $source['alias'] ) ] = true;
			}

			if ( count( $previous_matches ) > 1 ) {
				$merged_aliases = $using_columns[ $column_key ]['aliases'] ?? array();
				foreach ( $matched_aliases as $alias => $_ ) {
					if ( ! isset( $merged_aliases[ $alias ] ) ) {
						return null;
					}
				}
			}

			$matched_aliases[ strtolower( $current_source['alias'] ) ] = true;
			if ( isset( $using_columns[ $column_key ]['aliases'] ) ) {
				$matched_aliases = array_merge( $using_columns[ $column_key ]['aliases'], $matched_aliases );
			}

			$new_using[ $column_key ] = array(
				'column'  => $current_column,
				'aliases' => $matched_aliases,
			);
			$columns[]               = $this->connection->quote_identifier( $current_column );
			++$position;

			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
				continue;
			}

			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
				return $position === $end && ! empty( $columns )
					? array(
						'replacement'   => array(
							'start' => $start,
							'end'   => $end,
							'sql'   => 'USING (' . implode( ', ', $columns ) . ')',
						),
						'using_columns' => $new_using,
					)
					: null;
			}

			return null;
		}

		return null;
	}

	/**
	 * Get a PostgreSQL USING replacement for same-name information_schema ON predicates.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $start         ON token position.
	 * @param int              $end           Final token position, exclusive.
	 * @param array[]          $sources       Parsed sources through the right-hand join source.
	 * @param array            $using_columns Previously merged USING columns.
	 * @return array{replacement: array{start:int,end:int,sql:string}, using_columns: array}|null Replacement data, or null when unsupported.
	 */
	private function get_direct_information_schema_join_on_using_replacement( array $tokens, int $start, int $end, array $sources, array $using_columns ): ?array {
		if (
			count( $sources ) < 2
			|| ! isset( $tokens[ $start ] )
			|| WP_MySQL_Lexer::ON_SYMBOL !== $tokens[ $start ]->id
		) {
			return null;
		}

		$current_source = $sources[ count( $sources ) - 1 ];
		$current_alias  = strtolower( $current_source['alias'] );
		$position       = $start + 1;
		$columns        = array();
		$seen_columns   = array();
		$new_using      = array();

		while ( $position < $end ) {
			$left = $this->parse_direct_information_schema_qualified_column_reference( $tokens, $position, $end, $sources );
			if ( null === $left || ! isset( $tokens[ $left['end'] ] ) || WP_MySQL_Lexer::EQUAL_OPERATOR !== $tokens[ $left['end'] ]->id ) {
				return null;
			}

			$right = $this->parse_direct_information_schema_qualified_column_reference( $tokens, $left['end'] + 1, $end, $sources );
			if ( null === $right ) {
				return null;
			}

			$left_alias  = strtolower( $left['source']['alias'] );
			$right_alias = strtolower( $right['source']['alias'] );
			if ( 0 !== strcasecmp( $left['column'], $right['column'] ) ) {
				return null;
			}

			if ( $left_alias === $current_alias && $right_alias !== $current_alias ) {
				$previous_source = $right['source'];
				$column          = $left['column'];
			} elseif ( $right_alias === $current_alias && $left_alias !== $current_alias ) {
				$previous_source = $left['source'];
				$column          = $right['column'];
			} else {
				return null;
			}

			$column_key = strtolower( $column );
			if ( isset( $seen_columns[ $column_key ] ) ) {
				return null;
			}
			$seen_columns[ $column_key ] = true;

			$matched_aliases = array(
				strtolower( $previous_source['alias'] ) => true,
				$current_alias                         => true,
			);
			if ( isset( $using_columns[ $column_key ]['aliases'] ) ) {
				$matched_aliases = array_merge( $using_columns[ $column_key ]['aliases'], $matched_aliases );
			}

			$new_using[ $column_key ] = array(
				'column'  => $column,
				'aliases' => $matched_aliases,
			);
			$columns[]               = $this->connection->quote_identifier( $column );
			$position                = $right['end'];

			if ( $position === $end ) {
				return ! empty( $columns )
					? array(
						'replacement'   => array(
							'start' => $start,
							'end'   => $end,
							'sql'   => 'USING (' . implode( ', ', $columns ) . ')',
						),
						'using_columns' => $new_using,
					)
					: null;
			}

			if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::AND_SYMBOL !== $tokens[ $position ]->id ) {
				return null;
			}
			++$position;
		}

		return null;
	}

	/**
	 * Parse a qualified information_schema source column reference.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Reference start position.
	 * @param int              $end      Final token position, exclusive.
	 * @param array[]          $sources  Parsed direct information_schema sources.
	 * @return array{source: array, column: string, end: int}|null Parsed reference, or null.
	 */
	private function parse_direct_information_schema_qualified_column_reference( array $tokens, int $position, int $end, array $sources ): ?array {
		if (
			$position + 2 >= $end
			|| ! isset( $tokens[ $position ], $tokens[ $position + 1 ], $tokens[ $position + 2 ] )
			|| WP_MySQL_Lexer::DOT_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return null;
		}

		$qualifier = $this->get_direct_information_schema_identifier_token_value( $tokens[ $position ] );
		if ( null === $qualifier ) {
			return null;
		}

		$source = $this->get_direct_information_schema_source_for_qualifier(
			$qualifier,
			array(
				'sources' => $sources,
			)
		);
		if ( null === $source ) {
			return null;
		}

		$column = $this->get_direct_information_schema_column_name_for_token( $tokens[ $position + 2 ], $source['column_map'] );
		if ( null === $column ) {
			return null;
		}

		return array(
			'source' => $source,
			'column' => $column,
			'end'    => $position + 3,
		);
	}

	/**
	 * Merge newly parsed USING columns into the direct information_schema context.
	 *
	 * @param array $columns Existing USING column metadata.
	 * @param array $new     New USING column metadata.
	 * @return array Merged USING column metadata.
	 */
	private function merge_direct_information_schema_using_columns( array $columns, array $new ): array {
		foreach ( $new as $key => $metadata ) {
			if ( isset( $columns[ $key ] ) ) {
				$metadata['aliases'] = array_merge( $columns[ $key ]['aliases'], $metadata['aliases'] );
			}
			$columns[ $key ] = $metadata;
		}

		return $columns;
	}

	/**
	 * Check whether parsed sources include at least one information_schema relation.
	 *
	 * @param array[] $sources Parsed direct information_schema sources.
	 * @return bool Whether at least one source is a catalog source.
	 */
	private function direct_information_schema_sources_include_information_schema_relation( array $sources ): bool {
		foreach ( $sources as $source ) {
			if ( isset( $source['view'] ) || isset( $source['relation_sql'] ) ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Check whether a FROM source range directly names information_schema.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First source token.
	 * @param int              $end    Final source token, exclusive.
	 * @return bool Whether the source range directly references information_schema.
	 */
	private function direct_information_schema_source_range_references_information_schema( array $tokens, int $start, int $end ): bool {
		for ( $position = $start; $position + 1 < $end; $position++ ) {
			$identifier = $this->get_direct_information_schema_identifier_token_value( $tokens[ $position ] ?? null );
			if (
				null !== $identifier
				&& 0 === strcasecmp( $identifier, 'information_schema' )
				&& WP_MySQL_Lexer::DOT_SYMBOL === ( $tokens[ $position + 1 ]->id ?? null )
			) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Check whether direct information_schema sources are safe for a multi-source rewrite.
	 *
	 * @param array[] $sources Parsed direct information_schema sources.
	 * @return bool Whether the sources are safe to rewrite together.
	 */
	private function direct_information_schema_sources_are_joinable( array $sources ): bool {
		$has_information_schema_source = false;
		$main_table_count              = 0;

		foreach ( $sources as $source ) {
			if (
				isset( $source['relation_sql'] )
				|| ( isset( $source['view'] ) && $this->is_direct_information_schema_join_relation( $source['view'] ) )
			) {
				$has_information_schema_source = true;
				continue;
			}

			if ( isset( $source['cte'] ) ) {
				continue;
			}

			if ( isset( $source['table'] ) ) {
				++$main_table_count;
				if ( $main_table_count > 1 ) {
					return false;
				}
				continue;
			}

			return false;
		}

		return $has_information_schema_source;
	}

	/**
	 * Check whether a relation is allowed in multi-source direct information_schema rewrites.
	 *
	 * @param string $view Information schema view name.
	 * @return bool Whether the view may be used in a JOIN rewrite.
	 */
	private function is_direct_information_schema_join_relation( string $view ): bool {
		return in_array(
			strtolower( $view ),
			array(
				'tables',
				'columns',
				'schemata',
				'statistics',
				'table_constraints',
				'key_column_usage',
				'referential_constraints',
				'check_constraints',
				'character_sets',
				'collations',
				'engines',
				'session_variables',
				'global_variables',
				'session_status',
				'global_status',
				'processlist',
				'views',
				'triggers',
				'routines',
				'parameters',
			),
			true
		);
	}

	/**
	 * Get an identifier-ish token value for information_schema sources/columns.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @return string|null Identifier value, or null.
	 */
	private function get_direct_information_schema_identifier_token_value( ?WP_MySQL_Token $token ): ?string {
		if ( null === $token ) {
			return null;
		}

		$identifier = $this->get_mysql_identifier_token_value( $token );
		if ( null !== $identifier ) {
			return $identifier;
		}

		if (
			in_array(
				$token->id,
				array(
					WP_MySQL_Lexer::CLOSE_PAR_SYMBOL,
					WP_MySQL_Lexer::COMMA_SYMBOL,
					WP_MySQL_Lexer::DOT_SYMBOL,
					WP_MySQL_Lexer::EOF,
					WP_MySQL_Lexer::EQUAL_OPERATOR,
					WP_MySQL_Lexer::OPEN_PAR_SYMBOL,
					WP_MySQL_Lexer::SEMICOLON_SYMBOL,
				),
				true
			)
		) {
			return null;
		}

		$value = $token->get_value();
		return 1 === preg_match( '/^[A-Za-z_][A-Za-z0-9_]*$/', $value ) ? $value : null;
	}

	/**
	 * Get MySQL information_schema columns for a supported relation.
	 *
	 * @param string $view Information schema view name.
	 * @return string[]|null Uppercase MySQL column names, or null.
	 */
	private function get_direct_information_schema_relation_columns( string $view ): ?array {
		switch ( strtolower( $view ) ) {
			case 'schemata':
				return array(
					'CATALOG_NAME',
					'SCHEMA_NAME',
					'DEFAULT_CHARACTER_SET_NAME',
					'DEFAULT_COLLATION_NAME',
					'SQL_PATH',
					'DEFAULT_ENCRYPTION',
				);

			case 'tables':
				return array(
					'TABLE_CATALOG',
					'TABLE_SCHEMA',
					'TABLE_NAME',
					'TABLE_TYPE',
					'ENGINE',
					'VERSION',
					'ROW_FORMAT',
					'TABLE_ROWS',
					'AVG_ROW_LENGTH',
					'DATA_LENGTH',
					'MAX_DATA_LENGTH',
					'INDEX_LENGTH',
					'DATA_FREE',
					'AUTO_INCREMENT',
					'CREATE_TIME',
					'UPDATE_TIME',
					'CHECK_TIME',
					'TABLE_COLLATION',
					'CHECKSUM',
					'CREATE_OPTIONS',
					'TABLE_COMMENT',
				);

			case 'columns':
				return array(
					'TABLE_CATALOG',
					'TABLE_SCHEMA',
					'TABLE_NAME',
					'COLUMN_NAME',
					'ORDINAL_POSITION',
					'COLUMN_DEFAULT',
					'IS_NULLABLE',
					'DATA_TYPE',
					'CHARACTER_MAXIMUM_LENGTH',
					'CHARACTER_OCTET_LENGTH',
					'NUMERIC_PRECISION',
					'NUMERIC_SCALE',
					'DATETIME_PRECISION',
					'CHARACTER_SET_NAME',
					'COLLATION_NAME',
					'COLUMN_TYPE',
					'COLUMN_KEY',
					'EXTRA',
					'PRIVILEGES',
					'COLUMN_COMMENT',
					'GENERATION_EXPRESSION',
					'SRS_ID',
				);

			case 'statistics':
				return array(
					'TABLE_CATALOG',
					'TABLE_SCHEMA',
					'TABLE_NAME',
					'NON_UNIQUE',
					'INDEX_SCHEMA',
					'INDEX_NAME',
					'SEQ_IN_INDEX',
					'COLUMN_NAME',
					'COLLATION',
					'CARDINALITY',
					'SUB_PART',
					'PACKED',
					'NULLABLE',
					'INDEX_TYPE',
					'COMMENT',
					'INDEX_COMMENT',
					'IS_VISIBLE',
					'EXPRESSION',
				);

			case 'table_constraints':
				return array(
					'CONSTRAINT_CATALOG',
					'CONSTRAINT_SCHEMA',
					'CONSTRAINT_NAME',
					'TABLE_SCHEMA',
					'TABLE_NAME',
					'CONSTRAINT_TYPE',
					'ENFORCED',
				);

			case 'key_column_usage':
				return array(
					'CONSTRAINT_CATALOG',
					'CONSTRAINT_SCHEMA',
					'CONSTRAINT_NAME',
					'TABLE_CATALOG',
					'TABLE_SCHEMA',
					'TABLE_NAME',
					'COLUMN_NAME',
					'ORDINAL_POSITION',
					'POSITION_IN_UNIQUE_CONSTRAINT',
					'REFERENCED_TABLE_SCHEMA',
					'REFERENCED_TABLE_NAME',
					'REFERENCED_COLUMN_NAME',
				);

			case 'referential_constraints':
				return array(
					'CONSTRAINT_CATALOG',
					'CONSTRAINT_SCHEMA',
					'CONSTRAINT_NAME',
					'UNIQUE_CONSTRAINT_CATALOG',
					'UNIQUE_CONSTRAINT_SCHEMA',
					'UNIQUE_CONSTRAINT_NAME',
					'MATCH_OPTION',
					'UPDATE_RULE',
					'DELETE_RULE',
					'TABLE_NAME',
					'REFERENCED_TABLE_NAME',
				);

			case 'check_constraints':
				return array(
					'CONSTRAINT_CATALOG',
					'CONSTRAINT_SCHEMA',
					'CONSTRAINT_NAME',
					'CHECK_CLAUSE',
				);

			case 'character_sets':
				return array(
					'CHARACTER_SET_NAME',
					'DEFAULT_COLLATE_NAME',
					'DESCRIPTION',
					'MAXLEN',
				);

			case 'collations':
				return array(
					'COLLATION_NAME',
					'CHARACTER_SET_NAME',
					'ID',
					'IS_DEFAULT',
					'IS_COMPILED',
					'SORTLEN',
					'PAD_ATTRIBUTE',
				);

			case 'engines':
				return array(
					'ENGINE',
					'SUPPORT',
					'COMMENT',
					'TRANSACTIONS',
					'XA',
					'SAVEPOINTS',
				);

			case 'session_variables':
			case 'global_variables':
			case 'session_status':
			case 'global_status':
				return array(
					'VARIABLE_NAME',
					'VARIABLE_VALUE',
				);

			case 'processlist':
				return array(
					'ID',
					'USER',
					'HOST',
					'DB',
					'COMMAND',
					'TIME',
					'STATE',
					'INFO',
				);

			case 'views':
				return array(
					'TABLE_CATALOG',
					'TABLE_SCHEMA',
					'TABLE_NAME',
					'VIEW_DEFINITION',
					'CHECK_OPTION',
					'IS_UPDATABLE',
					'DEFINER',
					'SECURITY_TYPE',
					'CHARACTER_SET_CLIENT',
					'COLLATION_CONNECTION',
				);

			case 'triggers':
				return array(
					'TRIGGER_CATALOG',
					'TRIGGER_SCHEMA',
					'TRIGGER_NAME',
					'EVENT_MANIPULATION',
					'EVENT_OBJECT_CATALOG',
					'EVENT_OBJECT_SCHEMA',
					'EVENT_OBJECT_TABLE',
					'ACTION_ORDER',
					'ACTION_CONDITION',
					'ACTION_STATEMENT',
					'ACTION_ORIENTATION',
					'ACTION_TIMING',
					'ACTION_REFERENCE_OLD_TABLE',
					'ACTION_REFERENCE_NEW_TABLE',
					'ACTION_REFERENCE_OLD_ROW',
					'ACTION_REFERENCE_NEW_ROW',
					'CREATED',
					'SQL_MODE',
					'DEFINER',
					'CHARACTER_SET_CLIENT',
					'COLLATION_CONNECTION',
					'DATABASE_COLLATION',
				);

			case 'routines':
				return array(
					'SPECIFIC_NAME',
					'ROUTINE_CATALOG',
					'ROUTINE_SCHEMA',
					'ROUTINE_NAME',
					'ROUTINE_TYPE',
					'DATA_TYPE',
					'CHARACTER_MAXIMUM_LENGTH',
					'CHARACTER_OCTET_LENGTH',
					'NUMERIC_PRECISION',
					'NUMERIC_SCALE',
					'DATETIME_PRECISION',
					'CHARACTER_SET_NAME',
					'COLLATION_NAME',
					'DTD_IDENTIFIER',
					'ROUTINE_BODY',
					'ROUTINE_DEFINITION',
					'EXTERNAL_NAME',
					'EXTERNAL_LANGUAGE',
					'PARAMETER_STYLE',
					'IS_DETERMINISTIC',
					'SQL_DATA_ACCESS',
					'SQL_PATH',
					'SECURITY_TYPE',
					'CREATED',
					'LAST_ALTERED',
					'SQL_MODE',
					'ROUTINE_COMMENT',
					'DEFINER',
					'CHARACTER_SET_CLIENT',
					'COLLATION_CONNECTION',
					'DATABASE_COLLATION',
				);

			case 'parameters':
				return array(
					'SPECIFIC_CATALOG',
					'SPECIFIC_SCHEMA',
					'SPECIFIC_NAME',
					'ORDINAL_POSITION',
					'PARAMETER_MODE',
					'PARAMETER_NAME',
					'DATA_TYPE',
					'CHARACTER_MAXIMUM_LENGTH',
					'CHARACTER_OCTET_LENGTH',
					'NUMERIC_PRECISION',
					'NUMERIC_SCALE',
					'DATETIME_PRECISION',
					'CHARACTER_SET_NAME',
					'COLLATION_NAME',
					'DTD_IDENTIFIER',
					'ROUTINE_TYPE',
				);
		}

		return null;
	}

	/**
	 * Get a lookup map keyed by lowercase information_schema column name.
	 *
	 * @param string[] $columns Uppercase column names.
	 * @return array<string, string> Column map.
	 */
	private function get_direct_information_schema_relation_column_map( array $columns ): array {
		$map = array();
		foreach ( $columns as $column ) {
			$map[ strtolower( $column ) ] = $column;
		}
		return $map;
	}

	/**
	 * Build a MySQL-shaped SHOW CREATE TABLE statement for a supported information_schema view.
	 *
	 * @param string $view Information schema view name.
	 * @return string|null CREATE TABLE statement, or null when unsupported.
	 */
	private function get_direct_information_schema_create_table_statement( string $view ): ?string {
		$columns = $this->get_direct_information_schema_relation_columns( $view );
		if ( null === $columns ) {
			return null;
		}

		$definitions = array();
		foreach ( $columns as $column ) {
			$definitions[] = sprintf(
				'  %s %s',
				$this->quote_mysql_identifier( $column ),
				$this->get_direct_information_schema_create_column_type( $column )
			);
		}

		return sprintf(
			"CREATE TEMPORARY TABLE %s (\n%s\n) ENGINE=MEMORY DEFAULT CHARSET=%s COLLATE=%s",
			$this->quote_mysql_identifier( strtolower( $view ) ),
			implode( ",\n", $definitions ),
			self::DEFAULT_MYSQL_CHARSET,
			self::DEFAULT_MYSQL_COLLATION
		);
	}

	/**
	 * Get a MySQL column definition type for an information_schema output column.
	 *
	 * @param string $column Uppercase information_schema column name.
	 * @return string MySQL column definition fragment.
	 */
	private function get_direct_information_schema_create_column_type( string $column ): string {
		if (
			in_array(
				$column,
				array(
					'VERSION',
					'TABLE_ROWS',
					'AVG_ROW_LENGTH',
					'DATA_LENGTH',
					'MAX_DATA_LENGTH',
					'INDEX_LENGTH',
					'DATA_FREE',
					'AUTO_INCREMENT',
					'ORDINAL_POSITION',
					'CHARACTER_MAXIMUM_LENGTH',
					'CHARACTER_OCTET_LENGTH',
					'NUMERIC_PRECISION',
					'NUMERIC_SCALE',
					'DATETIME_PRECISION',
					'SRS_ID',
					'NON_UNIQUE',
					'SEQ_IN_INDEX',
					'CARDINALITY',
					'SUB_PART',
					'POSITION_IN_UNIQUE_CONSTRAINT',
					'MAXLEN',
					'ID',
					'SORTLEN',
					'TIME',
					'ACTION_ORDER',
				),
				true
			)
		) {
			return 'bigint DEFAULT NULL';
		}

		if ( in_array( $column, array( 'COLUMN_DEFAULT', 'CHECK_CLAUSE', 'GENERATION_EXPRESSION', 'EXPRESSION', 'VIEW_DEFINITION', 'ACTION_CONDITION', 'ACTION_STATEMENT', 'ROUTINE_DEFINITION' ), true ) ) {
			return 'longtext DEFAULT NULL';
		}

		if ( in_array( $column, array( 'CREATE_TIME', 'UPDATE_TIME', 'CHECK_TIME', 'CREATED', 'LAST_ALTERED' ), true ) ) {
			return 'datetime DEFAULT NULL';
		}

		return 'varchar(512) DEFAULT NULL';
	}

	/**
	 * Get relation SQL for a supported direct information_schema view.
	 *
	 * @param string $view Information schema view name.
	 * @return string|null Relation SQL, or null.
	 */
	private function get_direct_information_schema_relation_sql( string $view ): ?string {
		switch ( strtolower( $view ) ) {
			case 'schemata':
				return $this->get_direct_information_schema_schemata_relation_sql();
			case 'tables':
				return $this->get_direct_information_schema_tables_relation_sql();
			case 'columns':
				return $this->get_direct_information_schema_columns_relation_sql();
			case 'statistics':
				return $this->get_direct_information_schema_statistics_relation_sql();
			case 'table_constraints':
				return $this->get_direct_information_schema_table_constraints_relation_sql();
			case 'key_column_usage':
				return $this->get_direct_information_schema_key_column_usage_relation_sql();
			case 'referential_constraints':
				return $this->get_direct_information_schema_referential_constraints_relation_sql();
			case 'check_constraints':
				return $this->get_direct_information_schema_check_constraints_relation_sql();
			case 'character_sets':
				return $this->get_direct_information_schema_character_sets_relation_sql();
			case 'collations':
				return $this->get_direct_information_schema_collations_relation_sql();
			case 'engines':
				return $this->get_direct_information_schema_engines_relation_sql();
			case 'session_variables':
			case 'global_variables':
				return $this->get_direct_information_schema_variables_relation_sql();
			case 'session_status':
			case 'global_status':
				return $this->get_direct_information_schema_status_relation_sql();
			case 'processlist':
				return $this->get_direct_information_schema_processlist_relation_sql();
			case 'views':
			case 'triggers':
			case 'routines':
			case 'parameters':
				return $this->get_direct_information_schema_empty_relation_sql( $view );
		}

		return null;
	}

	/**
	 * Get an explicit SELECT list for a supported information_schema star.
	 *
	 * @param WP_MySQL_Token[] $tokens  MySQL lexer token stream.
	 * @param int              $start   First expression token.
	 * @param int              $end     Final expression token, exclusive.
	 * @param array            $context Direct information_schema SELECT context.
	 * @return string|null SELECT list SQL, or null when the expression is not a rewritable star.
	 */
	private function get_direct_information_schema_star_projection_select_list( array $tokens, int $start, int $end, array $context ): ?string {
		if ( $start + 1 === $end && isset( $tokens[ $start ] ) && '*' === $tokens[ $start ]->get_bytes() ) {
			$select_lists = array();
			foreach ( $context['sources'] as $source ) {
				$select_lists[] = $this->get_direct_information_schema_column_select_list( $source['columns'], $source['alias'] );
			}
			return implode( ', ', $select_lists );
		}

		if (
			$start + 3 === $end
			&& isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $start + 1 ]->id
			&& '*' === $tokens[ $start + 2 ]->get_bytes()
		) {
			$qualifier = $this->get_direct_information_schema_identifier_token_value( $tokens[ $start ] );
			$source    = null === $qualifier ? null : $this->get_direct_information_schema_source_for_qualifier( $qualifier, $context );
			return null === $source ? null : $this->get_direct_information_schema_column_select_list( $source['columns'], $source['alias'] );
		}

		if (
			$start + 5 === $end
			&& isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ], $tokens[ $start + 3 ], $tokens[ $start + 4 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $start + 1 ]->id
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $start + 3 ]->id
			&& '*' === $tokens[ $start + 4 ]->get_bytes()
		) {
			$schema = $this->get_direct_information_schema_identifier_token_value( $tokens[ $start ] );
			if ( null === $schema || 0 !== strcasecmp( $schema, 'information_schema' ) ) {
				return null;
			}

			$qualifier = $this->get_direct_information_schema_identifier_token_value( $tokens[ $start + 2 ] );
			$source    = null === $qualifier ? null : $this->get_direct_information_schema_source_for_qualifier( $qualifier, $context );
			return null === $source ? null : $this->get_direct_information_schema_column_select_list( $source['columns'], $source['alias'] );
		}

		return null;
	}

	/**
	 * Check whether a projection expression is unaliased COUNT(*).
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First expression token.
	 * @param int              $end    Final expression token, exclusive.
	 * @return bool Whether this is COUNT(*).
	 */
	private function is_direct_information_schema_count_star_projection( array $tokens, int $start, int $end ): bool {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start  = $bounds['start'];
		$end    = $bounds['end'];

		return $start + 4 === $end
			&& isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ], $tokens[ $start + 3 ] )
			&& $this->is_mysql_token_value( $tokens[ $start ], 'count' )
			&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $start + 1 ]->id
			&& '*' === $tokens[ $start + 2 ]->get_bytes()
			&& WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $start + 3 ]->id;
	}

	/**
	 * Get DATABASE()/SCHEMA() replacements for a direct information_schema range.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int              $start            First token.
	 * @param int              $end              Final token, exclusive.
	 * @param array[]          $protected_ranges Ranges already handled by larger replacements.
	 * @return array[]|null Replacement ranges, or null when a current-database function has unsupported arguments.
	 */
	private function get_direct_information_schema_current_database_function_replacements( array $tokens, int $start, int $end, array $protected_ranges = array() ): ?array {
		$replacements = array();
		for ( $position = $start; $position < $end; $position++ ) {
			$protected_end = $this->get_covering_mysql_replacement_range_end( $position, $protected_ranges );
			if ( null !== $protected_end ) {
				$position = $protected_end - 1;
				continue;
			}

			$bounds = $this->get_mysql_common_function_bounds( $tokens, $position, $end );
			if ( null === $bounds || ! in_array( $bounds['function'], array( 'database', 'schema' ), true ) ) {
				continue;
			}

			$arguments = $this->split_top_level_mysql_arguments( $tokens, $bounds['arguments_start'], $bounds['arguments_end'] );
			if ( null === $arguments || array() !== $arguments ) {
				return null;
			}

			$replacements[] = array(
				'start' => $position,
				'end'   => $bounds['close'] + 1,
				'sql'   => $this->connection->quote( $this->db_name ),
			);
			$position       = $bounds['close'];
		}

		return $replacements;
	}

	/**
	 * Get column-reference replacements for a direct information_schema range.
	 *
	 * @param WP_MySQL_Token[] $tokens  MySQL lexer token stream.
	 * @param int              $start   First token.
	 * @param int              $end     Final token, exclusive.
	 * @param array            $context Direct information_schema SELECT context.
	 * @return array[]|null Replacement ranges, or null when a source-qualified reference is unsupported.
	 */
	private function get_direct_information_schema_column_replacements( array $tokens, int $start, int $end, array $context, array $protected_ranges = array() ): ?array {
		$replacements = array();
		for ( $position = $start; $position < $end; $position++ ) {
			$protected_end = $this->get_covering_mysql_replacement_range_end( $position, $protected_ranges );
			if ( null !== $protected_end ) {
				$position = $protected_end - 1;
				continue;
			}

			if (
				isset( $tokens[ $position + 1 ], $tokens[ $position + 2 ], $tokens[ $position + 3 ], $tokens[ $position + 4 ] )
				&& $position + 4 < $end
				&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position + 1 ]->id
				&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position + 3 ]->id
			) {
				$schema = $this->get_direct_information_schema_identifier_token_value( $tokens[ $position ] );
				if ( null !== $schema && 0 === strcasecmp( $schema, 'information_schema' ) ) {
					$qualifier = $this->get_direct_information_schema_identifier_token_value( $tokens[ $position + 2 ] );
					$source    = null === $qualifier ? null : $this->get_direct_information_schema_source_for_qualifier( $qualifier, $context );
					$column    = null === $source ? null : $this->get_direct_information_schema_column_name_for_token( $tokens[ $position + 4 ], $source['column_map'] );
					if ( null === $source || null === $column ) {
						return null;
					}

					$replacements[] = array(
						'start' => $position,
						'end'   => $position + 5,
						'sql'   => $this->get_direct_information_schema_qualified_column_sql( $source, $column ),
					);
					$position      += 4;
					continue;
				}
			}

			if (
				isset( $tokens[ $position + 1 ], $tokens[ $position + 2 ] )
				&& $position + 2 < $end
				&& ( ! isset( $tokens[ $position - 1 ] ) || WP_MySQL_Lexer::DOT_SYMBOL !== $tokens[ $position - 1 ]->id )
				&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position + 1 ]->id
			) {
				$qualifier = $this->get_direct_information_schema_identifier_token_value( $tokens[ $position ] );
				$source    = null === $qualifier ? null : $this->get_direct_information_schema_source_for_qualifier( $qualifier, $context );
				if ( null !== $source ) {
					$column = $this->get_direct_information_schema_column_name_for_token( $tokens[ $position + 2 ], $source['column_map'] );
					if ( null === $column ) {
						return null;
					}

					$replacements[] = array(
						'start' => $position,
						'end'   => $position + 3,
						'sql'   => $this->get_direct_information_schema_qualified_column_sql( $source, $column ),
					);
					$position      += 2;
					continue;
				}
			}

			if (
				( isset( $tokens[ $position - 1 ] ) && WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position - 1 ]->id )
				|| ( isset( $tokens[ $position + 1 ] ) && WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position + 1 ]->id )
			) {
				continue;
			}

			$column_sql = $this->get_direct_information_schema_unqualified_column_sql( $tokens[ $position ], $context );
			if ( false === $column_sql ) {
				return null;
			}
			if ( null === $column_sql ) {
				continue;
			}

			$replacements[] = array(
				'start' => $position,
				'end'   => $position + 1,
				'sql'   => $column_sql,
			);
		}

		return $replacements;
	}

	/**
	 * Get the end of a replacement range that covers a token position.
	 *
	 * @param int     $position     Token position.
	 * @param array[] $replacements Replacement ranges.
	 * @return int|null Range end, or null.
	 */
	private function get_covering_mysql_replacement_range_end( int $position, array $replacements ): ?int {
		foreach ( $replacements as $replacement ) {
			if ( $position >= $replacement['start'] && $position < $replacement['end'] ) {
				return $replacement['end'];
			}
		}

		return null;
	}

	/**
	 * Get nested SELECT replacements for supported direct information_schema clause subqueries.
	 *
	 * @param string           $query         Original MySQL query.
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param array[]          $clause_ranges Clause token ranges.
	 * @return array[]|null Replacement ranges, or null when a nested SELECT is unsupported.
	 */
	private function get_direct_information_schema_nested_select_replacements( string $query, array $tokens, array $clause_ranges ): ?array {
		$replacements = array();
		foreach ( $clause_ranges as $range ) {
			for ( $position = $range['start']; $position < $range['end']; $position++ ) {
				if (
					! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
					|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position ]->id
					|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position + 1 ]->id
				) {
					continue;
				}

				$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $range['end'] );
				if ( null === $after_close ) {
					return null;
				}

				$select_start = $position + 1;
				$select_end   = $after_close - 1;
				$select_query = $this->get_mysql_token_range_bytes( $query, $tokens, $select_start, $select_end );
				if ( '' === $select_query ) {
					return null;
				}

				$translated_select = $this->translate_direct_information_schema_select_query( $select_query );
				if ( null === $translated_select ) {
					if ( $this->mysql_select_range_requires_direct_information_schema_rewrite( $tokens, $select_start, $select_end ) ) {
						return null;
					}

					$translated_select = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $select_start, $select_end );
				}

				$replacements[] = array(
					'start' => $select_start,
					'end'   => $select_end,
					'sql'   => $translated_select,
				);
				$position       = $after_close - 1;
			}
		}

		return $replacements;
	}

	/**
	 * Check whether every nested SELECT is covered by a complete replacement range.
	 *
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int              $start        First token position.
	 * @param int              $end          Final token position, exclusive.
	 * @param array[]          $replacements Replacement ranges.
	 * @return bool Whether nested SELECTs are fully handled.
	 */
	private function direct_information_schema_nested_selects_are_covered( array $tokens, int $start, int $end, array $replacements ): bool {
		for ( $position = $start; $position < $end; $position++ ) {
			if ( WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $position ]->id ) {
				continue;
			}

			if ( null === $this->get_covering_mysql_replacement_range_end( $position, $replacements ) ) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Get a direct information_schema source for a qualifier.
	 *
	 * @param string $qualifier Qualifier token value.
	 * @param array  $context   Direct information_schema SELECT context.
	 * @return array|null Source, or null when the qualifier is not unique.
	 */
	private function get_direct_information_schema_source_for_qualifier( string $qualifier, array $context ): ?array {
		$matches = array();
		foreach ( $context['sources'] as $source ) {
			if ( 0 === strcasecmp( $qualifier, $source['alias'] ) ) {
				return $source;
			}

			if ( isset( $source['view'] ) && 0 === strcasecmp( $qualifier, $source['view'] ) ) {
				$matches[] = $source;
			}
		}

		return 1 === count( $matches ) ? $matches[0] : null;
	}

	/**
	 * Get SQL for an unqualified information_schema column token.
	 *
	 * @param WP_MySQL_Token $token   MySQL token.
	 * @param array          $context Direct information_schema SELECT context.
	 * @return string|false|null SQL, false when ambiguous, or null when not a known column.
	 */
	private function get_direct_information_schema_unqualified_column_sql( WP_MySQL_Token $token, array $context ) {
		$column = $this->get_direct_information_schema_unqualified_column_name( $token, $context );
		if ( false === $column ) {
			return false;
		}
		if ( null === $column ) {
			return null;
		}

		if ( isset( $context['using_columns'][ strtolower( $column ) ] ) ) {
			return $this->connection->quote_identifier( $column );
		}

		if ( 1 === count( $context['sources'] ) ) {
			return $this->connection->quote_identifier( $column );
		}

		foreach ( $context['sources'] as $source ) {
			if ( isset( $source['column_map'][ strtolower( $column ) ] ) ) {
				return $this->get_direct_information_schema_qualified_column_sql( $source, $column );
			}
		}

		return false;
	}

	/**
	 * Get an unqualified information_schema column name.
	 *
	 * @param WP_MySQL_Token $token   MySQL token.
	 * @param array          $context Direct information_schema SELECT context.
	 * @return string|false|null Column name, false when ambiguous, or null when unknown.
	 */
	private function get_direct_information_schema_unqualified_column_name( WP_MySQL_Token $token, array $context ) {
		$value = $this->get_direct_information_schema_identifier_token_value( $token );
		if ( null === $value ) {
			return null;
		}

		$matches = array();
		$key     = strtolower( $value );
		foreach ( $context['sources'] as $source ) {
			if ( isset( $source['column_map'][ $key ] ) ) {
				$matches[] = array(
					'source' => $source,
					'column' => $source['column_map'][ $key ],
				);
			}
		}

		if ( 0 === count( $matches ) ) {
			return null;
		}

		if ( count( $matches ) > 1 ) {
			$using_column = $context['using_columns'][ $key ] ?? null;
			if ( is_array( $using_column ) && isset( $using_column['column'], $using_column['aliases'] ) ) {
				foreach ( $matches as $match ) {
					if ( ! isset( $using_column['aliases'][ strtolower( $match['source']['alias'] ) ] ) ) {
						return false;
					}
				}

				return $using_column['column'];
			}

			return false;
		}

		return $matches[0]['column'];
	}

	/**
	 * Get SQL for a source-qualified information_schema column.
	 *
	 * @param array  $source Direct information_schema source.
	 * @param string $column Uppercase column name.
	 * @return string SQL expression.
	 */
	private function get_direct_information_schema_qualified_column_sql( array $source, string $column ): string {
		return $this->connection->quote_identifier( $source['alias'] ) . '.' . $this->connection->quote_identifier( $column );
	}

	/**
	 * Get a supported information_schema column name for a token.
	 *
	 * @param WP_MySQL_Token      $token      MySQL token.
	 * @param array<string,string> $column_map Supported columns keyed by lowercase name.
	 * @return string|null Uppercase column name, or null.
	 */
	private function get_direct_information_schema_column_name_for_token( WP_MySQL_Token $token, array $column_map ): ?string {
		$value = $this->get_direct_information_schema_identifier_token_value( $token );
		if ( null === $value ) {
			return null;
		}

		return $column_map[ strtolower( $value ) ] ?? null;
	}

	/**
	 * Build an explicit SELECT list for information_schema star expansion.
	 *
	 * @param string[] $columns Uppercase column names.
	 * @param string   $alias   Relation alias.
	 * @return string SELECT list SQL.
	 */
	private function get_direct_information_schema_column_select_list( array $columns, string $alias ): string {
		$select = array();
		foreach ( $columns as $column ) {
			$select[] = $this->connection->quote_identifier( $alias ) . '.' . $this->connection->quote_identifier( $column ) . ' AS ' . $this->connection->quote_identifier( $column );
		}
		return implode( ', ', $select );
	}

	/**
	 * Build a literal relation from PHP-computed information_schema rows.
	 *
	 * @param string[] $columns Uppercase column names.
	 * @param array[]  $rows    Rows keyed by uppercase column name.
	 * @return string Relation SQL.
	 */
	private function get_direct_information_schema_literal_relation_sql( array $columns, array $rows ): string {
		if ( empty( $rows ) ) {
			$select = array();
			foreach ( $columns as $column ) {
				$select[] = 'NULL AS ' . $this->connection->quote_identifier( $column );
			}
			return 'SELECT ' . implode( ', ', $select ) . ' WHERE 1 = 0';
		}

		$selects = array();
		foreach ( $rows as $row ) {
			$select = array();
			foreach ( $columns as $column ) {
				$select[] = $this->get_direct_information_schema_literal_sql( $row[ $column ] ?? null ) . ' AS ' . $this->connection->quote_identifier( $column );
			}
			$selects[] = 'SELECT ' . implode( ', ', $select );
		}

		return implode( ' UNION ALL ', $selects );
	}

	/**
	 * Convert a PHP value into relation-literal SQL.
	 *
	 * @param mixed $value Value.
	 * @return string SQL literal.
	 */
	private function get_direct_information_schema_literal_sql( $value ): string {
		if ( null === $value ) {
			return 'NULL';
		}

		if ( is_int( $value ) || is_float( $value ) || ( is_string( $value ) && 1 === preg_match( '/^-?[0-9]+(?:\.[0-9]+)?$/', $value ) ) ) {
			return (string) $value;
		}

		return $this->connection->quote( (string) $value );
	}

	/**
	 * Get MySQL-facing display schema SQL for a backend schema expression.
	 *
	 * @param string $schema_sql SQL expression returning a backend schema.
	 * @return string SQL expression returning a MySQL-facing schema.
	 */
	private function get_direct_information_schema_display_schema_sql( string $schema_sql ): string {
		return sprintf(
			'CASE WHEN %1$s = %2$s THEN %3$s ELSE %1$s END',
			$schema_sql,
			$this->connection->quote( 'public' ),
			$this->connection->quote( $this->main_db_name )
		);
	}

	/**
	 * Get MySQL-facing display schema for a backend schema value.
	 *
	 * @param string $schema Backend schema.
	 * @return string MySQL-facing schema.
	 */
	private function get_direct_information_schema_display_schema( string $schema ): string {
		return 0 === strcasecmp( $schema, 'public' ) ? $this->main_db_name : $schema;
	}

	/**
	 * Get hidden PostgreSQL metadata table names.
	 *
	 * @return string[] Table names.
	 */
	private function get_direct_information_schema_hidden_table_names(): array {
		return array(
			self::MYSQL_COLUMN_METADATA_TABLE,
			self::MYSQL_INDEX_METADATA_TABLE,
			self::MYSQL_FOREIGN_KEY_METADATA_TABLE,
			self::MYSQL_CHECK_METADATA_TABLE,
			self::MYSQL_CHARSET_METADATA_TABLE,
			self::MYSQL_TABLE_METADATA_TABLE,
		);
	}

	/**
	 * Get SQL for the hidden metadata table exclusion list.
	 *
	 * @return string SQL literal list.
	 */
	private function get_direct_information_schema_hidden_table_list_sql(): string {
		return implode(
			', ',
			array_map(
				array( $this->connection, 'quote' ),
				$this->get_direct_information_schema_hidden_table_names()
			)
		);
	}

	/**
	 * Build the MySQL-shaped information_schema.SCHEMATA relation.
	 *
	 * @return string Relation SQL.
	 */
	private function get_direct_information_schema_schemata_relation_sql(): string {
		$columns = $this->get_direct_information_schema_relation_columns( 'schemata' );
		return $this->get_direct_information_schema_literal_relation_sql(
			$columns,
			array(
				array(
					'CATALOG_NAME'               => 'def',
					'SCHEMA_NAME'                => 'information_schema',
					'DEFAULT_CHARACTER_SET_NAME' => self::DEFAULT_MYSQL_CHARSET,
					'DEFAULT_COLLATION_NAME'     => self::DEFAULT_MYSQL_COLLATION,
					'SQL_PATH'                   => null,
					'DEFAULT_ENCRYPTION'         => 'NO',
				),
				array(
					'CATALOG_NAME'               => 'def',
					'SCHEMA_NAME'                => $this->main_db_name,
					'DEFAULT_CHARACTER_SET_NAME' => self::DEFAULT_MYSQL_CHARSET,
					'DEFAULT_COLLATION_NAME'     => self::DEFAULT_MYSQL_COLLATION,
					'SQL_PATH'                   => null,
					'DEFAULT_ENCRYPTION'         => 'NO',
				),
			)
		);
	}

	/**
	 * Build the MySQL-shaped information_schema.CHARACTER_SETS relation.
	 *
	 * @return string Relation SQL.
	 */
	private function get_direct_information_schema_character_sets_relation_sql(): string {
		return $this->get_direct_information_schema_literal_relation_sql(
			$this->get_direct_information_schema_relation_columns( 'character_sets' ),
			$this->get_mysql_static_character_set_rows()
		);
	}

	/**
	 * Build the MySQL-shaped information_schema.COLLATIONS relation.
	 *
	 * @return string Relation SQL.
	 */
	private function get_direct_information_schema_collations_relation_sql(): string {
		return $this->get_direct_information_schema_literal_relation_sql(
			$this->get_direct_information_schema_relation_columns( 'collations' ),
			$this->get_mysql_static_collation_rows()
		);
	}

	/**
	 * Build the MySQL-shaped information_schema.ENGINES relation.
	 *
	 * @return string Relation SQL.
	 */
	private function get_direct_information_schema_engines_relation_sql(): string {
		$rows = array();
		foreach ( $this->get_mysql_static_show_engine_rows() as $row ) {
			$rows[] = array(
				'ENGINE'       => $row['Engine'],
				'SUPPORT'      => $row['Support'],
				'COMMENT'      => $row['Comment'],
				'TRANSACTIONS' => $row['Transactions'],
				'XA'           => $row['XA'],
				'SAVEPOINTS'   => $row['Savepoints'],
			);
		}

		return $this->get_direct_information_schema_literal_relation_sql(
			$this->get_direct_information_schema_relation_columns( 'engines' ),
			$rows
		);
	}

	/**
	 * Build the MySQL-shaped information_schema.SESSION_VARIABLES/GLOBAL_VARIABLES relation.
	 *
	 * @return string Relation SQL.
	 */
	private function get_direct_information_schema_variables_relation_sql(): string {
		$rows = array();
		foreach ( $this->get_mysql_session_variables() as $name => $value ) {
			$rows[] = array(
				'VARIABLE_NAME'  => $name,
				'VARIABLE_VALUE' => $value,
			);
		}

		return $this->get_direct_information_schema_literal_relation_sql(
			$this->get_direct_information_schema_relation_columns( 'session_variables' ),
			$rows
		);
	}

	/**
	 * Build the MySQL-shaped information_schema.SESSION_STATUS/GLOBAL_STATUS relation.
	 *
	 * @return string Relation SQL.
	 */
	private function get_direct_information_schema_status_relation_sql(): string {
		$rows = array();
		foreach ( $this->get_mysql_status_variables() as $name => $value ) {
			$rows[] = array(
				'VARIABLE_NAME'  => $name,
				'VARIABLE_VALUE' => $value,
			);
		}

		return $this->get_direct_information_schema_literal_relation_sql(
			$this->get_direct_information_schema_relation_columns( 'session_status' ),
			$rows
		);
	}

	/**
	 * Build the MySQL-shaped information_schema.PROCESSLIST relation.
	 *
	 * @return string Relation SQL.
	 */
	private function get_direct_information_schema_processlist_relation_sql(): string {
		return $this->get_direct_information_schema_literal_relation_sql(
			$this->get_direct_information_schema_relation_columns( 'processlist' ),
			array(
				array(
					'ID'      => '1',
					'USER'    => 'root',
					'HOST'    => 'localhost',
					'DB'      => $this->db_name,
					'COMMAND' => 'Query',
					'TIME'    => '0',
					'STATE'   => '',
					'INFO'    => (string) $this->last_mysql_query,
				),
			)
		);
	}

	/**
	 * Build an empty MySQL-shaped information_schema relation.
	 *
	 * @param string $view information_schema relation name.
	 * @return string Relation SQL.
	 */
	private function get_direct_information_schema_empty_relation_sql( string $view ): string {
		return $this->get_direct_information_schema_literal_relation_sql(
			$this->get_direct_information_schema_relation_columns( $view ),
			array()
		);
	}

	/**
	 * Build the MySQL-shaped information_schema.TABLES relation.
	 *
	 * @return string Relation SQL.
	 */
	private function get_direct_information_schema_tables_relation_sql(): string {
		$columns = $this->get_direct_information_schema_relation_columns( 'tables' );
		return $this->get_direct_information_schema_literal_relation_sql(
			$columns,
			$this->get_direct_information_schema_table_rows()
		);
	}

	/**
	 * Get MySQL-shaped information_schema.TABLES rows.
	 *
	 * @return array[] Rows keyed by uppercase column name.
	 */
	private function get_direct_information_schema_table_rows(): array {
		$this->ensure_mysql_schema_metadata_tables();

		$sql = sprintf(
			'SELECT
					t.table_schema,
					t.table_name,
					t.table_type,
					COALESCE(tm.table_comment, \'\') AS table_comment,
					(
						SELECT c.column_name
						FROM information_schema.columns c
						WHERE c.table_schema = t.table_schema
							AND c.table_name = t.table_name
							AND (
								c.is_identity = \'YES\'
								OR LOWER(COALESCE(c.column_default, \'\')) LIKE \'nextval(%%\'
							)
						ORDER BY c.ordinal_position
						LIMIT 1
					) AS identity_column
				FROM information_schema.tables t
				LEFT JOIN %s tm
					ON tm.table_schema = t.table_schema
					AND tm.table_name = t.table_name
				WHERE t.table_schema NOT IN (\'information_schema\', \'pg_catalog\')
					AND t.table_type IN (\'BASE TABLE\', \'VIEW\')
					AND t.table_name NOT IN (' . $this->get_direct_information_schema_hidden_table_list_sql() . ')
				ORDER BY t.table_schema, t.table_name',
			$this->connection->quote_identifier( self::MYSQL_TABLE_METADATA_TABLE )
		);

		try {
			$stmt = $this->connection->query( $sql );
		} catch ( PDOException $e ) {
			return array();
		}

		$rows        = array();
		$create_time = gmdate( 'Y-m-d H:i:s' );
		foreach ( $stmt->fetchAll( PDO::FETCH_ASSOC ) as $row ) {
			$table_schema    = (string) $row['table_schema'];
			$table_name      = (string) $row['table_name'];
			$table_type      = 'VIEW' === strtoupper( (string) $row['table_type'] ) ? 'VIEW' : 'BASE TABLE';
			$identity_column = null === $row['identity_column'] ? null : (string) $row['identity_column'];
			$auto_increment  = null;

			if ( null !== $identity_column && 0 === strcasecmp( $table_schema, 'public' ) ) {
				try {
					$auto_increment = $this->get_show_table_status_auto_increment_value( $table_name, $identity_column );
				} catch ( PDOException $e ) {
					$auto_increment = null;
				}
			}

			$rows[] = array(
				'TABLE_CATALOG'   => 'def',
				'TABLE_SCHEMA'    => $this->get_direct_information_schema_display_schema( $table_schema ),
				'TABLE_NAME'      => $table_name,
				'TABLE_TYPE'      => $table_type,
				'ENGINE'          => 'InnoDB',
				'VERSION'         => 10,
				'ROW_FORMAT'      => 'Dynamic',
				'TABLE_ROWS'      => $this->get_direct_information_schema_table_row_count( $table_schema, $table_name ),
				'AVG_ROW_LENGTH'  => 0,
				'DATA_LENGTH'     => 0,
				'MAX_DATA_LENGTH' => 0,
				'INDEX_LENGTH'    => 0,
				'DATA_FREE'       => 0,
				'AUTO_INCREMENT'  => $auto_increment,
				'CREATE_TIME'     => $create_time,
				'UPDATE_TIME'     => null,
				'CHECK_TIME'      => null,
				'TABLE_COLLATION' => $this->collation,
				'CHECKSUM'        => null,
				'CREATE_OPTIONS'  => '',
				'TABLE_COMMENT'   => (string) ( $row['table_comment'] ?? '' ),
			);
		}

		return $rows;
	}

	/**
	 * Count rows for an information_schema.TABLES row.
	 *
	 * @param string $table_schema Backend schema.
	 * @param string $table_name   Table name.
	 * @return int Row count, or zero when unavailable.
	 */
	private function get_direct_information_schema_table_row_count( string $table_schema, string $table_name ): int {
		try {
			$stmt = $this->connection->query(
				'SELECT COUNT(*) FROM ' . $this->get_postgresql_schema_identifier( $table_schema, $table_name )
			);
			return (int) $stmt->fetchColumn();
		} catch ( PDOException $e ) {
			return 0;
		}
	}

	/**
	 * Build the MySQL-shaped information_schema.COLUMNS relation.
	 *
	 * @return string Relation SQL.
	 */
	private function get_direct_information_schema_columns_relation_sql(): string {
		$this->ensure_mysql_schema_metadata_tables();

		$column_metadata_table = $this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE );
		$type_expression       = $this->get_direct_information_schema_catalog_data_type_expression( 'c' );
		$column_type           = $this->get_direct_information_schema_column_type_expression( 'c', 'cm' );
		$data_type             = $this->get_direct_information_schema_metadata_data_type_expression( 'cm.column_type', $type_expression );
		$charset               = $this->get_direct_information_schema_character_set_expression( $column_type, 'cm.character_set_name' );
		$collation             = $this->get_direct_information_schema_collation_expression( $column_type, 'COALESCE(cm.collation_name, c.collation_name)' );
		$column_key            = $this->get_direct_information_schema_column_key_expression( 'c.table_schema', 'c.table_name', 'c.column_name' );
		$metadata_type         = $this->get_direct_information_schema_metadata_data_type_expression( 'cm.column_type', 'cm.column_type' );
		$metadata_charset      = $this->get_direct_information_schema_character_set_expression( 'cm.column_type', 'cm.character_set_name' );
		$metadata_collation    = $this->get_direct_information_schema_collation_expression( 'cm.column_type', 'cm.collation_name' );
		$metadata_key          = $this->get_direct_information_schema_column_key_expression( 'cm.table_schema', 'cm.table_name', 'cm.column_name' );

		return sprintf(
			'WITH catalog_columns AS (
	SELECT
		\'def\' AS "TABLE_CATALOG",
		%1$s AS "TABLE_SCHEMA",
		c.table_name AS "TABLE_NAME",
		c.column_name AS "COLUMN_NAME",
		c.ordinal_position AS "ORDINAL_POSITION",
		CASE WHEN cm.column_name IS NOT NULL THEN cm.column_default ELSE c.column_default END AS "COLUMN_DEFAULT",
		COALESCE(cm.is_nullable, c.is_nullable) AS "IS_NULLABLE",
		%2$s AS "DATA_TYPE",
		c.character_maximum_length AS "CHARACTER_MAXIMUM_LENGTH",
		CASE WHEN c.character_maximum_length IS NULL THEN NULL ELSE c.character_maximum_length * 4 END AS "CHARACTER_OCTET_LENGTH",
		c.numeric_precision AS "NUMERIC_PRECISION",
		c.numeric_scale AS "NUMERIC_SCALE",
		c.datetime_precision AS "DATETIME_PRECISION",
		%3$s AS "CHARACTER_SET_NAME",
			%4$s AS "COLLATION_NAME",
			%5$s AS "COLUMN_TYPE",
			%6$s AS "COLUMN_KEY",
			COALESCE(cm.extra, %7$s) AS "EXTRA",
			\'select,insert,update,references\' AS "PRIVILEGES",
			COALESCE(cm.column_comment, \'\') AS "COLUMN_COMMENT",
			\'\' AS "GENERATION_EXPRESSION",
		NULL AS "SRS_ID"
	FROM information_schema.columns c
	LEFT JOIN %8$s cm
		ON cm.table_schema = c.table_schema
		AND cm.table_name = c.table_name
		AND cm.column_name = c.column_name
	WHERE c.table_schema NOT IN (\'information_schema\', \'pg_catalog\')
		AND c.table_name NOT IN (%9$s)
),
metadata_columns AS (
	SELECT
		\'def\' AS "TABLE_CATALOG",
		%10$s AS "TABLE_SCHEMA",
		cm.table_name AS "TABLE_NAME",
		cm.column_name AS "COLUMN_NAME",
		cm.ordinal_position AS "ORDINAL_POSITION",
		cm.column_default AS "COLUMN_DEFAULT",
		cm.is_nullable AS "IS_NULLABLE",
		%11$s AS "DATA_TYPE",
		NULL AS "CHARACTER_MAXIMUM_LENGTH",
		NULL AS "CHARACTER_OCTET_LENGTH",
		NULL AS "NUMERIC_PRECISION",
		NULL AS "NUMERIC_SCALE",
		NULL AS "DATETIME_PRECISION",
		%12$s AS "CHARACTER_SET_NAME",
			%13$s AS "COLLATION_NAME",
			cm.column_type AS "COLUMN_TYPE",
			%14$s AS "COLUMN_KEY",
			cm.extra AS "EXTRA",
			\'select,insert,update,references\' AS "PRIVILEGES",
			cm.column_comment AS "COLUMN_COMMENT",
			\'\' AS "GENERATION_EXPRESSION",
		NULL AS "SRS_ID"
	FROM %8$s cm
	WHERE NOT %15$s
		AND NOT EXISTS (
		SELECT 1
		FROM information_schema.columns c
		WHERE c.table_schema = cm.table_schema
			AND c.table_name = cm.table_name
			AND c.column_name = cm.column_name
	)
)
SELECT * FROM catalog_columns
UNION ALL
SELECT * FROM metadata_columns',
			$this->get_direct_information_schema_display_schema_sql( 'c.table_schema' ),
			$data_type,
			$charset,
			$collation,
			$column_type,
			$column_key,
			$this->get_direct_information_schema_column_extra_expression( 'c' ),
			$column_metadata_table,
			$this->get_direct_information_schema_hidden_table_list_sql(),
			$this->get_direct_information_schema_display_schema_sql( 'cm.table_schema' ),
			$metadata_type,
			$metadata_charset,
			$metadata_collation,
			$metadata_key,
			$this->get_mysql_temporary_schema_sql_condition( 'cm.table_schema' )
		);
	}

	/**
	 * Get a SQL condition that matches temporary metadata schemas.
	 *
	 * @param string $schema_sql SQL expression for a backend schema name.
	 * @return string SQL condition.
	 */
	private function get_mysql_temporary_schema_sql_condition( string $schema_sql ): string {
		return sprintf(
			'(LOWER(%1$s) IN (\'temp\', \'pg_temp\') OR LOWER(%1$s) LIKE \'pg_temp_%%\')',
			$schema_sql
		);
	}

	/**
	 * Get a MySQL data type expression from PostgreSQL catalog metadata.
	 *
	 * @param string $alias Catalog column table alias.
	 * @return string SQL expression.
	 */
	private function get_direct_information_schema_catalog_data_type_expression( string $alias ): string {
		return sprintf(
			'CASE
	WHEN %1$s.data_type = \'character varying\' THEN \'varchar\'
	WHEN %1$s.data_type = \'character\' THEN \'char\'
	WHEN %1$s.data_type = \'integer\' THEN \'int\'
	WHEN %1$s.data_type = \'timestamp without time zone\' THEN \'datetime\'
	ELSE %1$s.data_type
END',
			$alias
		);
	}

	/**
	 * Get a MySQL column type expression.
	 *
	 * @param string $catalog_alias  Catalog column table alias.
	 * @param string $metadata_alias MySQL metadata table alias.
	 * @return string SQL expression.
	 */
	private function get_direct_information_schema_column_type_expression( string $catalog_alias, string $metadata_alias ): string {
		return sprintf(
			'COALESCE(%2$s.column_type, CASE
	WHEN %1$s.data_type = \'character varying\' THEN
		\'varchar\' || CASE WHEN %1$s.character_maximum_length IS NULL THEN \'\' ELSE \'(\' || CAST(%1$s.character_maximum_length AS text) || \')\' END
	WHEN %1$s.data_type = \'character\' THEN
		\'char\' || CASE WHEN %1$s.character_maximum_length IS NULL THEN \'\' ELSE \'(\' || CAST(%1$s.character_maximum_length AS text) || \')\' END
	WHEN %1$s.data_type = \'integer\' THEN \'int\'
	WHEN %1$s.data_type = \'timestamp without time zone\' THEN \'datetime\'
	ELSE %1$s.data_type
END)',
			$catalog_alias,
			$metadata_alias
		);
	}

	/**
	 * Get a MySQL DATA_TYPE expression from MySQL column_type metadata.
	 *
	 * @param string $column_type_sql SQL expression for column_type.
	 * @param string $fallback_sql    Fallback SQL expression.
	 * @return string SQL expression.
	 */
	private function get_direct_information_schema_metadata_data_type_expression( string $column_type_sql, string $fallback_sql ): string {
		return sprintf(
			'CASE
	WHEN %1$s IS NULL THEN %2$s
	WHEN LOWER(%1$s) LIKE \'bigint%%\' THEN \'bigint\'
	WHEN LOWER(%1$s) LIKE \'mediumint%%\' THEN \'mediumint\'
	WHEN LOWER(%1$s) LIKE \'smallint%%\' THEN \'smallint\'
	WHEN LOWER(%1$s) LIKE \'tinyint%%\' THEN \'tinyint\'
	WHEN LOWER(%1$s) LIKE \'int%%\' THEN \'int\'
	WHEN LOWER(%1$s) LIKE \'integer%%\' THEN \'int\'
	WHEN LOWER(%1$s) LIKE \'varchar%%\' THEN \'varchar\'
	WHEN LOWER(%1$s) LIKE \'char%%\' THEN \'char\'
	WHEN LOWER(%1$s) LIKE \'decimal%%\' THEN \'decimal\'
	WHEN LOWER(%1$s) LIKE \'numeric%%\' THEN \'decimal\'
	WHEN LOWER(%1$s) LIKE \'datetime%%\' THEN \'datetime\'
	WHEN LOWER(%1$s) LIKE \'timestamp%%\' THEN \'timestamp\'
	WHEN LOWER(%1$s) LIKE \'double%%\' THEN \'double\'
	WHEN LOWER(%1$s) LIKE \'float%%\' THEN \'float\'
	WHEN LOWER(%1$s) LIKE \'longtext%%\' THEN \'longtext\'
	WHEN LOWER(%1$s) LIKE \'mediumtext%%\' THEN \'mediumtext\'
	WHEN LOWER(%1$s) LIKE \'tinytext%%\' THEN \'tinytext\'
	WHEN LOWER(%1$s) LIKE \'text%%\' THEN \'text\'
	ELSE LOWER(%1$s)
END',
			$column_type_sql,
			$fallback_sql
		);
	}

	/**
	 * Get CHARACTER_SET_NAME expression for a MySQL column type.
	 *
	 * @param string $column_type_sql SQL expression for column_type.
	 * @param string $metadata_sql    SQL expression for stored charset.
	 * @return string SQL expression.
	 */
	private function get_direct_information_schema_character_set_expression( string $column_type_sql, string $metadata_sql ): string {
		return sprintf(
			'CASE
	WHEN LOWER(%1$s) LIKE \'char%%\'
		OR LOWER(%1$s) LIKE \'varchar%%\'
		OR LOWER(%1$s) LIKE \'%%text%%\' THEN COALESCE(%2$s, %3$s)
	ELSE NULL
END',
			$column_type_sql,
			$metadata_sql,
			$this->connection->quote( $this->charset )
		);
	}

	/**
	 * Get COLLATION_NAME expression for a MySQL column type.
	 *
	 * @param string $column_type_sql SQL expression for column_type.
	 * @param string $metadata_sql    SQL expression for stored collation.
	 * @return string SQL expression.
	 */
	private function get_direct_information_schema_collation_expression( string $column_type_sql, string $metadata_sql ): string {
		return sprintf(
			'CASE
	WHEN LOWER(%1$s) LIKE \'char%%\'
		OR LOWER(%1$s) LIKE \'varchar%%\'
		OR LOWER(%1$s) LIKE \'%%text%%\' THEN COALESCE(%2$s, %3$s)
	ELSE NULL
END',
			$column_type_sql,
			$metadata_sql,
			$this->connection->quote( $this->collation )
		);
	}

	/**
	 * Get COLUMN_KEY expression for a table column.
	 *
	 * @param string $schema_sql SQL expression for backend schema.
	 * @param string $table_sql  SQL expression for table name.
	 * @param string $column_sql SQL expression for column name.
	 * @return string SQL expression.
	 */
	private function get_direct_information_schema_column_key_expression( string $schema_sql, string $table_sql, string $column_sql ): string {
		$index_metadata_table = $this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE );

		return sprintf(
			'CASE
	WHEN EXISTS (
		SELECT 1 FROM %1$s im
		WHERE im.table_schema = %2$s
			AND im.table_name = %3$s
			AND im.column_name = %4$s
			AND UPPER(im.key_name) = \'PRIMARY\'
	) THEN \'PRI\'
	WHEN EXISTS (
		SELECT 1 FROM %1$s im
		WHERE im.table_schema = %2$s
			AND im.table_name = %3$s
			AND im.column_name = %4$s
			AND im.non_unique = \'0\'
	) THEN \'UNI\'
	WHEN EXISTS (
		SELECT 1 FROM %1$s im
		WHERE im.table_schema = %2$s
			AND im.table_name = %3$s
			AND im.column_name = %4$s
	) THEN \'MUL\'
	WHEN EXISTS (
		SELECT 1
		FROM information_schema.table_constraints tc
		INNER JOIN information_schema.key_column_usage kcu
			ON kcu.constraint_schema = tc.constraint_schema
			AND kcu.constraint_name = tc.constraint_name
			AND kcu.table_schema = tc.table_schema
			AND kcu.table_name = tc.table_name
		WHERE tc.table_schema = %2$s
			AND tc.table_name = %3$s
			AND tc.constraint_type = \'PRIMARY KEY\'
			AND kcu.column_name = %4$s
	) THEN \'PRI\'
	WHEN EXISTS (
		SELECT 1
		FROM information_schema.table_constraints tc
		INNER JOIN information_schema.key_column_usage kcu
			ON kcu.constraint_schema = tc.constraint_schema
			AND kcu.constraint_name = tc.constraint_name
			AND kcu.table_schema = tc.table_schema
			AND kcu.table_name = tc.table_name
		WHERE tc.table_schema = %2$s
			AND tc.table_name = %3$s
			AND tc.constraint_type = \'UNIQUE\'
			AND kcu.column_name = %4$s
	) THEN \'UNI\'
	ELSE \'\'
END',
			$index_metadata_table,
			$schema_sql,
			$table_sql,
			$column_sql
		);
	}

	/**
	 * Get EXTRA expression for a catalog column.
	 *
	 * @param string $alias Catalog column table alias.
	 * @return string SQL expression.
	 */
	private function get_direct_information_schema_column_extra_expression( string $alias ): string {
		return sprintf(
			'CASE
	WHEN %1$s.is_identity = \'YES\' THEN \'auto_increment\'
	WHEN LOWER(COALESCE(%1$s.column_default, \'\')) LIKE \'nextval(%%\' THEN \'auto_increment\'
	ELSE \'\'
END',
			$alias
		);
	}

	/**
	 * Build the MySQL-shaped information_schema.STATISTICS relation.
	 *
	 * @return string Relation SQL.
	 */
	private function get_direct_information_schema_statistics_relation_sql(): string {
		$this->ensure_mysql_schema_metadata_tables();

		$index_metadata_table = $this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE );

		return sprintf(
			'SELECT
	\'def\' AS "TABLE_CATALOG",
	%1$s AS "TABLE_SCHEMA",
	im.table_name AS "TABLE_NAME",
	CAST(im.non_unique AS integer) AS "NON_UNIQUE",
	%1$s AS "INDEX_SCHEMA",
	im.key_name AS "INDEX_NAME",
	im.seq_in_index AS "SEQ_IN_INDEX",
	im.column_name AS "COLUMN_NAME",
	CASE WHEN im.index_type = \'FULLTEXT\' THEN NULL ELSE COALESCE(im."collation", \'A\') END AS "COLLATION",
	0 AS "CARDINALITY",
	im.sub_part AS "SUB_PART",
	NULL AS "PACKED",
	im.nullable AS "NULLABLE",
	im.index_type AS "INDEX_TYPE",
	\'\' AS "COMMENT",
	im.index_comment AS "INDEX_COMMENT",
	\'YES\' AS "IS_VISIBLE",
	NULL AS "EXPRESSION"
FROM %2$s im',
			$this->get_direct_information_schema_display_schema_sql( 'im.table_schema' ),
			$index_metadata_table
		);
	}

	/**
	 * Build the MySQL-shaped information_schema.TABLE_CONSTRAINTS relation.
	 *
	 * @return string Relation SQL.
	 */
	private function get_direct_information_schema_table_constraints_relation_sql(): string {
		$this->ensure_mysql_schema_metadata_tables();

		$index_metadata_table       = $this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE );
		$foreign_key_metadata_table = $this->connection->quote_identifier( self::MYSQL_FOREIGN_KEY_METADATA_TABLE );
		$check_metadata_table       = $this->connection->quote_identifier( self::MYSQL_CHECK_METADATA_TABLE );

		return sprintf(
			'WITH index_constraints AS (
	SELECT DISTINCT
		im.table_schema,
		im.table_name,
		im.key_name AS constraint_name,
		CASE WHEN UPPER(im.key_name) = \'PRIMARY\' THEN \'PRIMARY KEY\' ELSE \'UNIQUE\' END AS constraint_type
	FROM %1$s im
	WHERE im.non_unique = \'0\'
),
foreign_key_constraints AS (
	SELECT DISTINCT
		fk.table_schema,
		fk.table_name,
		fk.constraint_name,
		\'FOREIGN KEY\' AS constraint_type
	FROM %2$s fk
),
check_constraints AS (
	SELECT
		cm.table_schema,
		cm.table_name,
		cm.constraint_name,
		\'CHECK\' AS constraint_type,
		cm.enforced
	FROM %3$s cm
),
catalog_constraints AS (
	SELECT
		tc.table_schema,
		tc.table_name,
		CASE WHEN tc.constraint_type = \'PRIMARY KEY\' THEN \'PRIMARY\' ELSE tc.constraint_name END AS constraint_name,
		tc.constraint_type,
		\'YES\' AS enforced
	FROM information_schema.table_constraints tc
	WHERE tc.table_schema NOT IN (\'information_schema\', \'pg_catalog\')
		AND tc.table_name NOT IN (%4$s)
		AND tc.constraint_type IN (\'PRIMARY KEY\', \'UNIQUE\', \'FOREIGN KEY\', \'CHECK\')
		AND NOT EXISTS (
			SELECT 1
			FROM index_constraints ic
			WHERE ic.table_schema = tc.table_schema
				AND ic.table_name = tc.table_name
				AND ic.constraint_type = tc.constraint_type
		)
		AND NOT EXISTS (
			SELECT 1
			FROM foreign_key_constraints fkc
			WHERE fkc.table_schema = tc.table_schema
				AND fkc.table_name = tc.table_name
				AND fkc.constraint_name = tc.constraint_name
		)
		AND NOT EXISTS (
			SELECT 1
			FROM check_constraints cc
			WHERE cc.table_schema = tc.table_schema
				AND cc.table_name = tc.table_name
				AND cc.constraint_name = tc.constraint_name
		)
)
SELECT
	\'def\' AS "CONSTRAINT_CATALOG",
	%5$s AS "CONSTRAINT_SCHEMA",
	constraint_name AS "CONSTRAINT_NAME",
	%5$s AS "TABLE_SCHEMA",
	table_name AS "TABLE_NAME",
	constraint_type AS "CONSTRAINT_TYPE",
	enforced AS "ENFORCED"
FROM (
	SELECT table_schema, table_name, constraint_name, constraint_type, \'YES\' AS enforced FROM index_constraints
	UNION ALL
	SELECT table_schema, table_name, constraint_name, constraint_type, \'YES\' AS enforced FROM foreign_key_constraints
	UNION ALL
	SELECT * FROM check_constraints
	UNION ALL
	SELECT * FROM catalog_constraints
) constraints',
			$index_metadata_table,
			$foreign_key_metadata_table,
			$check_metadata_table,
			$this->get_direct_information_schema_hidden_table_list_sql(),
			$this->get_direct_information_schema_display_schema_sql( 'table_schema' )
		);
	}

	/**
	 * Build the MySQL-shaped information_schema.KEY_COLUMN_USAGE relation.
	 *
	 * @return string Relation SQL.
	 */
	private function get_direct_information_schema_key_column_usage_relation_sql(): string {
		$this->ensure_mysql_schema_metadata_tables();

		$index_metadata_table       = $this->connection->quote_identifier( self::MYSQL_INDEX_METADATA_TABLE );
		$foreign_key_metadata_table = $this->connection->quote_identifier( self::MYSQL_FOREIGN_KEY_METADATA_TABLE );

		return sprintf(
			'SELECT
	\'def\' AS "CONSTRAINT_CATALOG",
	%1$s AS "CONSTRAINT_SCHEMA",
	im.key_name AS "CONSTRAINT_NAME",
	\'def\' AS "TABLE_CATALOG",
	%1$s AS "TABLE_SCHEMA",
	im.table_name AS "TABLE_NAME",
	im.column_name AS "COLUMN_NAME",
	im.seq_in_index AS "ORDINAL_POSITION",
	NULL AS "POSITION_IN_UNIQUE_CONSTRAINT",
	NULL AS "REFERENCED_TABLE_SCHEMA",
	NULL AS "REFERENCED_TABLE_NAME",
	NULL AS "REFERENCED_COLUMN_NAME"
FROM %2$s im
WHERE im.non_unique = \'0\'
UNION ALL
SELECT
	\'def\' AS "CONSTRAINT_CATALOG",
	%3$s AS "CONSTRAINT_SCHEMA",
	fk.constraint_name AS "CONSTRAINT_NAME",
	\'def\' AS "TABLE_CATALOG",
	%3$s AS "TABLE_SCHEMA",
	fk.table_name AS "TABLE_NAME",
	fk.column_name AS "COLUMN_NAME",
	fk.seq_in_index AS "ORDINAL_POSITION",
	fk.seq_in_index AS "POSITION_IN_UNIQUE_CONSTRAINT",
	%4$s AS "REFERENCED_TABLE_SCHEMA",
	fk.referenced_table_name AS "REFERENCED_TABLE_NAME",
	fk.referenced_column_name AS "REFERENCED_COLUMN_NAME"
FROM %5$s fk',
			$this->get_direct_information_schema_display_schema_sql( 'im.table_schema' ),
			$index_metadata_table,
			$this->get_direct_information_schema_display_schema_sql( 'fk.table_schema' ),
			$this->get_direct_information_schema_display_schema_sql( 'fk.referenced_table_schema' ),
			$foreign_key_metadata_table
		) . sprintf(
			'
UNION ALL
SELECT
	\'def\' AS "CONSTRAINT_CATALOG",
	%1$s AS "CONSTRAINT_SCHEMA",
	CASE WHEN tc.constraint_type = \'PRIMARY KEY\' THEN \'PRIMARY\' ELSE kcu.constraint_name END AS "CONSTRAINT_NAME",
	\'def\' AS "TABLE_CATALOG",
	%1$s AS "TABLE_SCHEMA",
	kcu.table_name AS "TABLE_NAME",
	kcu.column_name AS "COLUMN_NAME",
	kcu.ordinal_position AS "ORDINAL_POSITION",
	kcu.position_in_unique_constraint AS "POSITION_IN_UNIQUE_CONSTRAINT",
	%2$s AS "REFERENCED_TABLE_SCHEMA",
	ccu.table_name AS "REFERENCED_TABLE_NAME",
	ccu.column_name AS "REFERENCED_COLUMN_NAME"
FROM information_schema.key_column_usage kcu
LEFT JOIN information_schema.table_constraints tc
	ON tc.constraint_schema = kcu.constraint_schema
	AND tc.constraint_name = kcu.constraint_name
	AND tc.table_schema = kcu.table_schema
	AND tc.table_name = kcu.table_name
LEFT JOIN information_schema.constraint_column_usage ccu
	ON ccu.constraint_schema = kcu.constraint_schema
	AND ccu.constraint_name = kcu.constraint_name
WHERE kcu.table_schema NOT IN (\'information_schema\', \'pg_catalog\')
	AND kcu.table_name NOT IN (%3$s)
	AND NOT EXISTS (
		SELECT 1
		FROM %4$s im
		WHERE im.table_schema = kcu.table_schema
			AND im.table_name = kcu.table_name
			AND im.column_name = kcu.column_name
			AND im.seq_in_index = kcu.ordinal_position
			AND im.non_unique = \'0\'
	)
	AND NOT EXISTS (
		SELECT 1
		FROM %5$s fk
		WHERE fk.table_schema = kcu.table_schema
			AND fk.table_name = kcu.table_name
			AND fk.constraint_name = kcu.constraint_name
			AND fk.column_name = kcu.column_name
	)',
			$this->get_direct_information_schema_display_schema_sql( 'kcu.table_schema' ),
			$this->get_direct_information_schema_display_schema_sql( 'ccu.table_schema' ),
			$this->get_direct_information_schema_hidden_table_list_sql(),
			$index_metadata_table,
			$foreign_key_metadata_table
		);
	}

	/**
	 * Build the MySQL-shaped information_schema.REFERENTIAL_CONSTRAINTS relation.
	 *
	 * @return string Relation SQL.
	 */
	private function get_direct_information_schema_referential_constraints_relation_sql(): string {
		$this->ensure_mysql_schema_metadata_tables();

		$foreign_key_metadata_table = $this->connection->quote_identifier( self::MYSQL_FOREIGN_KEY_METADATA_TABLE );

		return sprintf(
			'WITH metadata_constraints AS (
	SELECT
		fk.table_schema,
		fk.constraint_name,
		MIN(fk.constraint_ordinal) AS constraint_ordinal,
		MIN(fk.referenced_table_schema) AS referenced_table_schema,
		MIN(fk.referenced_table_name) AS referenced_table_name,
		MIN(fk.update_rule) AS update_rule,
		MIN(fk.delete_rule) AS delete_rule,
		MIN(fk.table_name) AS table_name
	FROM %1$s fk
	GROUP BY fk.table_schema, fk.constraint_name
),
catalog_constraints AS (
	SELECT
		rc.constraint_schema AS table_schema,
		rc.constraint_name,
		0 AS constraint_ordinal,
		rc.unique_constraint_schema AS referenced_table_schema,
		ccu.table_name AS referenced_table_name,
		rc.update_rule,
		rc.delete_rule,
		tc.table_name
	FROM information_schema.referential_constraints rc
	LEFT JOIN information_schema.table_constraints tc
		ON tc.constraint_schema = rc.constraint_schema
		AND tc.constraint_name = rc.constraint_name
	LEFT JOIN information_schema.constraint_column_usage ccu
		ON ccu.constraint_schema = rc.unique_constraint_schema
		AND ccu.constraint_name = rc.unique_constraint_name
	WHERE rc.constraint_schema NOT IN (\'information_schema\', \'pg_catalog\')
		AND NOT EXISTS (
			SELECT 1
			FROM metadata_constraints mc
			WHERE mc.table_schema = rc.constraint_schema
				AND mc.constraint_name = rc.constraint_name
		)
)
SELECT
	\'def\' AS "CONSTRAINT_CATALOG",
	%2$s AS "CONSTRAINT_SCHEMA",
	constraint_name AS "CONSTRAINT_NAME",
	\'def\' AS "UNIQUE_CONSTRAINT_CATALOG",
	%3$s AS "UNIQUE_CONSTRAINT_SCHEMA",
	\'PRIMARY\' AS "UNIQUE_CONSTRAINT_NAME",
	\'NONE\' AS "MATCH_OPTION",
	update_rule AS "UPDATE_RULE",
	delete_rule AS "DELETE_RULE",
	table_name AS "TABLE_NAME",
	referenced_table_name AS "REFERENCED_TABLE_NAME"
FROM (
	SELECT * FROM metadata_constraints
	UNION ALL
	SELECT * FROM catalog_constraints
) constraints',
			$foreign_key_metadata_table,
			$this->get_direct_information_schema_display_schema_sql( 'table_schema' ),
			$this->get_direct_information_schema_display_schema_sql( 'referenced_table_schema' )
		);
	}

	/**
	 * Build the MySQL-shaped information_schema.CHECK_CONSTRAINTS relation.
	 *
	 * @return string Relation SQL.
	 */
	private function get_direct_information_schema_check_constraints_relation_sql(): string {
		$this->ensure_mysql_schema_metadata_tables();

		$check_metadata_table = $this->connection->quote_identifier( self::MYSQL_CHECK_METADATA_TABLE );

		return sprintf(
			'WITH metadata_checks AS (
	SELECT
		cm.table_schema AS constraint_schema,
		cm.constraint_name,
		cm.check_clause
	FROM %2$s cm
),
catalog_checks AS (
	SELECT
		cc.constraint_schema,
		cc.constraint_name,
		cc.check_clause
	FROM information_schema.check_constraints cc
	WHERE cc.constraint_schema NOT IN (\'information_schema\', \'pg_catalog\')
		AND NOT EXISTS (
			SELECT 1
			FROM metadata_checks mc
			WHERE mc.constraint_schema = cc.constraint_schema
				AND mc.constraint_name = cc.constraint_name
		)
)
SELECT
	\'def\' AS "CONSTRAINT_CATALOG",
	%1$s AS "CONSTRAINT_SCHEMA",
	constraint_name AS "CONSTRAINT_NAME",
	check_clause AS "CHECK_CLAUSE"
FROM (
	SELECT * FROM metadata_checks
	UNION ALL
	SELECT * FROM catalog_checks
) checks',
			$this->get_direct_information_schema_display_schema_sql( 'constraint_schema' ),
			$check_metadata_table
		);
	}

	/**
	 * Translate SELECT DISTINCT queries whose ORDER BY expression is not selected.
	 *
	 * PostgreSQL requires ORDER BY expressions in SELECT DISTINCT statements to
	 * appear in the projection. Grouping by the visible projection and ordering
	 * by a hidden aggregate keeps the MySQL-visible result shape and avoids
	 * changing DISTINCT cardinality.
	 *
	 * @param string $query         MySQL query.
	 * @param bool   $include_limit Whether to preserve the LIMIT/OFFSET clause.
	 * @return string|null PostgreSQL query, or null when the query is unsupported.
	 */
	private function translate_distinct_order_by_query( string $query, bool $include_limit = true ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0], $tokens[1] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$position = 1;
		if ( WP_MySQL_Lexer::DISTINCT_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		++$position;
		$has_sql_calc_found_rows = false;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::SQL_CALC_FOUND_ROWS_SYMBOL === $tokens[ $position ]->id ) {
			$has_sql_calc_found_rows = true;
			++$position;
		}

		if ( isset( $tokens[ $position ] ) && $this->is_unsupported_distinct_select_modifier( $tokens[ $position ] ) ) {
			return null;
		}

		$projection_start = $position;
		$statement_end    = $this->get_mysql_statement_end_position( $tokens, $projection_start );
		if ( null === $statement_end ) {
			return null;
		}

		$limit_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::LIMIT_SYMBOL,
			$projection_start,
			$statement_end
		);
		$select_end     = $limit_position ?? $statement_end;
		if ( null !== $limit_position && ! $this->is_supported_simple_select_limit_clause( $tokens, $limit_position, $statement_end ) ) {
			return null;
		}

		$order_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::ORDER_SYMBOL,
			$projection_start,
			$select_end
		);
		if ( null === $order_position ) {
			if ( ! $has_sql_calc_found_rows ) {
				return null;
			}

			$sql = 'SELECT DISTINCT ' . $this->translate_mysql_token_sequence_to_postgresql( $tokens, $projection_start, $select_end );
			if ( $include_limit && null !== $limit_position ) {
				$sql .= $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end );
			}

			return $sql;
		}

		$from_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::FROM_SYMBOL,
			$projection_start,
			$order_position
		);
		if (
			null === $from_position
			|| null === $order_position
			|| $order_position + 2 >= $statement_end
			|| ! isset( $tokens[ $order_position + 1 ] )
			|| WP_MySQL_Lexer::BY_SYMBOL !== $tokens[ $order_position + 1 ]->id
		) {
			return null;
		}

		if (
			$this->contains_top_level_mysql_token(
				$tokens,
				$projection_start,
				$select_end,
				array(
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::GROUP_SYMBOL,
					WP_MySQL_Lexer::HAVING_SYMBOL,
					WP_MySQL_Lexer::INTO_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				)
			)
		) {
			return null;
		}

		if (
			$this->contains_mysql_token(
				$tokens,
				$projection_start,
				$select_end,
				array(
					WP_MySQL_Lexer::SELECT_SYMBOL,
					WP_MySQL_Lexer::AVG_SYMBOL,
					WP_MySQL_Lexer::COUNT_SYMBOL,
					WP_MySQL_Lexer::GROUP_CONCAT_SYMBOL,
					WP_MySQL_Lexer::MAX_SYMBOL,
					WP_MySQL_Lexer::MIN_SYMBOL,
					WP_MySQL_Lexer::SUM_SYMBOL,
				)
			)
		) {
			return null;
		}

		$projection_items = $this->parse_mysql_select_projection_items( $tokens, $projection_start, $from_position );
		if ( null === $projection_items ) {
			return null;
		}

		$scope_end = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::WHERE_SYMBOL,
			$from_position + 1,
			$order_position
		) ?? $order_position;
		$scope     = $this->get_mysql_select_scope( $tokens, $from_position + 1, $scope_end );
		if ( null === $scope ) {
			return null;
		}

		$order_items = $this->parse_mysql_select_order_by_items(
			$tokens,
			$order_position + 2,
			$select_end,
			$projection_items,
			$scope
		);
		if ( null === $order_items ) {
			return null;
		}

		$has_hidden_order_expression = false;
		foreach ( $order_items as $order_item ) {
			if ( null === $order_item['projection_index'] ) {
				$has_hidden_order_expression = true;
				break;
			}
		}

		if ( ! $has_hidden_order_expression ) {
			if ( ! $has_sql_calc_found_rows ) {
				return null;
			}

			$sql = 'SELECT DISTINCT ' . $this->translate_mysql_token_sequence_to_postgresql( $tokens, $projection_start, $select_end );
			if ( $include_limit && null !== $limit_position ) {
				$sql .= $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end );
			}

			return $sql;
		}

		return $this->build_distinct_order_by_grouped_query(
			$tokens,
			$projection_items,
			$order_items,
			$from_position,
			$order_position,
			$limit_position,
			$statement_end,
			$include_limit
		);
	}

	/**
	 * Translate WordPress's available post MIME type lookup with MySQL order.
	 *
	 * WordPress issues this query without ORDER BY, but MySQL returns MIME types
	 * in first matching posts.ID order for the posts table shape. Keep this
	 * constrained to the exact get_available_post_mime_types() query so generic
	 * unordered DISTINCT queries remain unchanged.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_wordpress_available_post_mime_types_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0], $tokens[1], $tokens[12] )
			|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id
			|| WP_MySQL_Lexer::DISTINCT_SYMBOL !== $tokens[1]->id
		) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 2 );
		if ( 13 !== $statement_end ) {
			return null;
		}

		if (
			! $this->is_mysql_identifier_like_token_value( $tokens[2], 'post_mime_type' )
			|| WP_MySQL_Lexer::FROM_SYMBOL !== $tokens[3]->id
			|| WP_MySQL_Lexer::WHERE_SYMBOL !== $tokens[5]->id
			|| ! $this->is_mysql_identifier_like_token_value( $tokens[6], 'post_type' )
			|| WP_MySQL_Lexer::EQUAL_OPERATOR !== $tokens[7]->id
			|| ! $this->is_mysql_string_literal_token( $tokens[8] )
			|| WP_MySQL_Lexer::AND_SYMBOL !== $tokens[9]->id
			|| ! $this->is_mysql_identifier_like_token_value( $tokens[10], 'post_mime_type' )
			|| WP_MySQL_Lexer::NOT_EQUAL_OPERATOR !== $tokens[11]->id
			|| ! $this->is_mysql_string_literal_token( $tokens[12] )
			|| '' !== $tokens[12]->get_value()
		) {
			return null;
		}

		$table_name = $this->get_mysql_identifier_token_value( $tokens[4] );
		if ( null === $table_name || ! $this->is_mysql_wordpress_table_name( $table_name, 'posts' ) ) {
			return null;
		}

		$scope = $this->get_mysql_single_table_scope( $table_name );
		$table = $scope['tables'][0];
		foreach ( array( 'ID', 'post_mime_type', 'post_type' ) as $column_name ) {
			if ( null === $this->get_mysql_table_column_type( $table['schema'], $table['table'], $column_name ) ) {
				return null;
			}
		}

		$projection_sql = $this->translate_mysql_token_to_postgresql( $tokens[2] );
		$where_sql      = $this->translate_mysql_predicate_token_sequence_to_postgresql(
			$tokens,
			6,
			$statement_end,
			$scope
		);

		return sprintf(
			'SELECT %1$s %2$s WHERE %3$s GROUP BY %1$s ORDER BY MIN(%4$s) ASC',
			$projection_sql,
			'FROM ' . $this->translate_mysql_token_to_postgresql( $tokens[4] ),
			$where_sql['sql'],
			$this->connection->quote_identifier( 'ID' )
		);
	}

	/**
	 * Translate WordPress term cache priming with MySQL-compatible shared-term order.
	 *
	 * WordPress primes term objects with a join query that has no ORDER BY. The
	 * cache is keyed by term_id, so legacy shared terms rely on MySQL returning
	 * rows in term_taxonomy_id order and letting the last taxonomy row win.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_wordpress_term_cache_priming_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return null;
		}

		if (
			$this->contains_top_level_mysql_token(
				$tokens,
				1,
				$statement_end,
				array(
					WP_MySQL_Lexer::DISTINCT_SYMBOL,
					WP_MySQL_Lexer::GROUP_SYMBOL,
					WP_MySQL_Lexer::HAVING_SYMBOL,
					WP_MySQL_Lexer::LIMIT_SYMBOL,
					WP_MySQL_Lexer::ORDER_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				)
			)
		) {
			return null;
		}

		$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, 1, $statement_end );
		if ( null === $from_position || 1 === $from_position ) {
			return null;
		}

		$projection_ranges = $this->split_top_level_mysql_arguments( $tokens, 1, $from_position );
		if (
			null === $projection_ranges
			|| 2 !== count( $projection_ranges )
			|| ! $this->is_mysql_qualified_star_projection( $tokens, $projection_ranges[0]['start'], $projection_ranges[0]['end'], 't' )
			|| ! $this->is_mysql_qualified_star_projection( $tokens, $projection_ranges[1]['start'], $projection_ranges[1]['end'], 'tt' )
		) {
			return null;
		}

		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, $from_position + 1, $statement_end );
		if (
			null === $where_position
			|| ! $this->is_mysql_distinct_term_taxonomy_from_shape( $tokens, $from_position, $where_position )
			|| ! $this->is_mysql_term_cache_priming_where_clause( $tokens, $where_position + 1, $statement_end )
		) {
			return null;
		}

		return $this->translate_mysql_token_sequence_to_postgresql( $tokens, 0, $statement_end ) . ' ORDER BY tt.term_taxonomy_id ASC';
	}

	/**
	 * Translate WordPress's approved comments lookup with MySQL-compatible ties.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_wordpress_approved_comments_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0] )
			|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id
		) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 2 );
		if ( null === $statement_end ) {
			return null;
		}

		$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, 2, $statement_end );
		if ( null !== $limit_position && ! $this->is_supported_simple_select_limit_clause( $tokens, $limit_position, $statement_end ) ) {
			return null;
		}

		$select_end     = $limit_position ?? $statement_end;
		$from_position  = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, 2, $select_end );
		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, 2, $select_end );
		$order_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::ORDER_SYMBOL, 2, $select_end );
		if (
			null === $from_position
			|| null === $where_position
			|| null === $order_position
			|| $from_position + 2 !== $where_position
			|| $where_position >= $order_position
			|| $order_position + 2 >= $select_end
			|| ! isset( $tokens[ $order_position + 1 ] )
			|| WP_MySQL_Lexer::BY_SYMBOL !== $tokens[ $order_position + 1 ]->id
		) {
			return null;
		}

		$table_token = $tokens[ $from_position + 1 ] ?? null;
		$table_name  = $this->get_mysql_identifier_token_value( $table_token );
		if (
			null === $table_name
			|| ! $this->is_mysql_wordpress_table_name( $table_name, 'comments' )
			|| ! $this->is_supported_wordpress_approved_comments_select_projection( $tokens, 1, $from_position, $table_name )
		) {
			return null;
		}

		$tiebreaker_sql = $this->get_simple_wordpress_approved_comments_order_tiebreaker_sql(
			$tokens,
			$table_name,
			$where_position,
			$order_position,
			$order_position,
			$select_end
		);
		if ( null === $tiebreaker_sql ) {
			return null;
		}

		$scope     = $this->get_mysql_single_table_scope( $table_name );
		$where_sql = $this->translate_mysql_predicate_token_sequence_to_postgresql(
			$tokens,
			$where_position + 1,
			$order_position,
			$scope
		);
		$order_sql = $this->translate_mysql_order_by_token_sequence_to_postgresql(
			$tokens,
			$order_position + 2,
			$select_end,
			$scope,
			false
		);

		$sql = sprintf(
			'SELECT %s FROM %s WHERE %s ORDER BY %s, %s',
			$this->translate_mysql_token_sequence_to_postgresql( $tokens, 1, $from_position ),
			$this->translate_mysql_identifier_token_to_postgresql( $table_token ),
			$where_sql['sql'],
			$order_sql['sql'],
			$tiebreaker_sql
		);
		if ( null !== $limit_position ) {
			$sql .= $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end );
		}

		return $sql;
	}

	/**
	 * Validate the approved-comments SELECT projection.
	 *
	 * This translator appends comment_ID to ORDER BY, so it must stay limited
	 * to row-returning projections. Aggregate/function/expression projections
	 * can become invalid when the tie-breaker is appended.
	 *
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param int              $start      First projection token position.
	 * @param int              $end        Final projection token position, exclusive.
	 * @param string           $table_name Selected comments table name.
	 * @return bool Whether the projection is supported.
	 */
	private function is_supported_wordpress_approved_comments_select_projection(
		array $tokens,
		int $start,
		int $end,
		string $table_name
	): bool {
		if ( $start + 1 === $end && WP_MySQL_Lexer::MULT_OPERATOR === $tokens[ $start ]->id ) {
			return true;
		}

		$projection_ranges = $this->split_top_level_mysql_arguments( $tokens, $start, $end );
		if ( null === $projection_ranges ) {
			return false;
		}

		foreach ( $projection_ranges as $projection_range ) {
			$reference = $this->parse_mysql_column_reference(
				$tokens,
				$projection_range['start'],
				$projection_range['end']
			);
			if (
				null === $reference
				|| $reference['end'] !== $projection_range['end']
				|| (
					null !== $reference['qualifier']
					&& strtolower( $reference['qualifier'] ) !== strtolower( $table_name )
				)
			) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Check whether a projection item is alias.*.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection token.
	 * @param int             $end    Final projection token, exclusive.
	 * @param string          $alias  Expected table alias.
	 * @return bool Whether the projection item is the qualified star.
	 */
	private function is_mysql_qualified_star_projection( array $tokens, int $start, int $end, string $alias ): bool {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start  = $bounds['start'];
		$end    = $bounds['end'];

		return $start + 3 === $end
			&& $this->is_mysql_identifier_like_token_value( $tokens[ $start ] ?? null, $alias )
			&& isset( $tokens[ $start + 1 ], $tokens[ $start + 2 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $start + 1 ]->id
			&& WP_MySQL_Lexer::MULT_OPERATOR === $tokens[ $start + 2 ]->id;
	}

	/**
	 * Check whether a WHERE clause is t.term_id IN (integer list).
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First WHERE predicate token.
	 * @param int             $end    Final WHERE predicate token, exclusive.
	 * @return bool Whether the WHERE clause matches term cache priming.
	 */
	private function is_mysql_term_cache_priming_where_clause( array $tokens, int $start, int $end ): bool {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start  = $bounds['start'];
		$end    = $bounds['end'];

		$reference = $this->parse_mysql_column_reference( $tokens, $start, $end );
		if (
			null === $reference
			|| $reference['end'] + 3 > $end
			|| 't' !== strtolower( (string) $reference['qualifier'] )
			|| 'term_id' !== strtolower( $reference['column'] )
			|| ! isset( $tokens[ $reference['end'] ], $tokens[ $reference['end'] + 1 ] )
			|| WP_MySQL_Lexer::IN_SYMBOL !== $tokens[ $reference['end'] ]->id
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $reference['end'] + 1 ]->id
		) {
			return false;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $reference['end'] + 1, $end );
		if ( $after_close !== $end ) {
			return false;
		}

		$items = $this->split_top_level_mysql_arguments( $tokens, $reference['end'] + 2, $end - 1 );
		if ( null === $items || empty( $items ) ) {
			return false;
		}

		foreach ( $items as $item ) {
			if (
				$item['start'] + 1 !== $item['end']
				|| ! isset( $tokens[ $item['start'] ] )
				|| ! in_array(
					$tokens[ $item['start'] ]->id,
					array(
						WP_MySQL_Lexer::INT_NUMBER,
						WP_MySQL_Lexer::LONG_NUMBER,
						WP_MySQL_Lexer::ULONGLONG_NUMBER,
					),
					true
				)
			) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Check whether a token is an unsupported SELECT modifier for this rewrite.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token is an unsupported modifier.
	 */
	private function is_unsupported_distinct_select_modifier( WP_MySQL_Token $token ): bool {
		return in_array(
			$token->id,
			array(
				WP_MySQL_Lexer::HIGH_PRIORITY_SYMBOL,
				WP_MySQL_Lexer::SQL_BIG_RESULT_SYMBOL,
				WP_MySQL_Lexer::SQL_BUFFER_RESULT_SYMBOL,
				WP_MySQL_Lexer::SQL_CACHE_SYMBOL,
				WP_MySQL_Lexer::SQL_NO_CACHE_SYMBOL,
				WP_MySQL_Lexer::SQL_SMALL_RESULT_SYMBOL,
				WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL,
			),
			true
		);
	}

	/**
	 * Parse SELECT projection items with expression bounds and visible aliases.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection token position.
	 * @param int             $end    Final projection token position, exclusive.
	 * @return array<int, array{expression_start: int, expression_end: int, sql: string, alias: string}>|null Projection items.
	 */
	private function parse_mysql_select_projection_items( array $tokens, int $start, int $end ): ?array {
		$ranges = $this->split_top_level_mysql_arguments( $tokens, $start, $end );
		if ( null === $ranges || count( $ranges ) < 1 ) {
			return null;
		}

		$items        = array();
		$alias_lookup = array();
		foreach ( $ranges as $range ) {
			$item = $this->parse_mysql_select_projection_item( $tokens, $range['start'], $range['end'] );
			if ( null === $item ) {
				return null;
			}

			$alias_key = strtolower( $item['alias'] );
			if ( isset( $alias_lookup[ $alias_key ] ) ) {
				return null;
			}

			$alias_lookup[ $alias_key ] = true;
			$items[]                    = $item;
		}

		return $items;
	}

	/**
	 * Parse one SELECT projection item.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection item token position.
	 * @param int             $end    Final projection item token position, exclusive.
	 * @return array{expression_start: int, expression_end: int, sql: string, alias: string}|null Projection item.
	 */
	private function parse_mysql_select_projection_item( array $tokens, int $start, int $end ): ?array {
		if ( $start >= $end ) {
			return null;
		}

		$expression_start = $start;
		$expression_end   = $end;
		$alias            = null;
		$as_position      = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::AS_SYMBOL, $start, $end );

		if ( null !== $as_position ) {
			if ( $as_position <= $start || $as_position + 2 !== $end ) {
				return null;
			}

			$alias = $this->get_mysql_projection_alias_token_value( $tokens[ $as_position + 1 ] ?? null );
			if ( null === $alias ) {
				return null;
			}

			$expression_end = $as_position;
		} else {
			$implicit_alias = $this->get_mysql_implicit_projection_alias( $tokens, $start, $end );
			if ( null !== $implicit_alias ) {
				$alias          = $implicit_alias;
				$expression_end = $end - 1;
			}
		}

		if ( $expression_start >= $expression_end ) {
			return null;
		}

		if ( null === $alias ) {
			$alias = $this->get_mysql_select_expression_default_output_name( $tokens, $expression_start, $expression_end );
			if ( null === $alias ) {
				return null;
			}
		}

		return array(
			'expression_start' => $expression_start,
			'expression_end'   => $expression_end,
			'sql'              => $this->translate_mysql_token_sequence_to_postgresql( $tokens, $expression_start, $expression_end ),
			'alias'            => $alias,
		);
	}

	/**
	 * Get an explicit projection alias token value.
	 *
	 * MySQL permits string-literal aliases in projection context. Keep that
	 * context local so predicate string literals continue to render as values.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @return string|null Alias value, or null when unsupported.
	 */
	private function get_mysql_projection_alias_token_value( ?WP_MySQL_Token $token ): ?string {
		if ( null === $token ) {
			return null;
		}

		$identifier = $this->get_mysql_identifier_token_value( $token );
		if ( null !== $identifier ) {
			return $identifier;
		}

		if ( WP_MySQL_Lexer::SINGLE_QUOTED_TEXT === $token->id || WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT === $token->id ) {
			return $token->get_value();
		}

		$value = $token->get_value();
		if ( $this->is_mysql_unquoted_projection_alias_value( $value ) ) {
			return $value;
		}

		return null;
	}

	/**
	 * Check whether a token value is safe as an unquoted MySQL projection alias.
	 *
	 * @param string $value Token value.
	 * @return bool Whether the value is identifier-shaped.
	 */
	private function is_mysql_unquoted_projection_alias_value( string $value ): bool {
		if ( '' === $value ) {
			return false;
		}

		$first_character = $value[0];
		if ( '_' !== $first_character && ! ctype_alpha( $first_character ) ) {
			return false;
		}

		for ( $i = 1, $length = strlen( $value ); $i < $length; $i++ ) {
			$character = $value[ $i ];
			if ( '_' !== $character && '$' !== $character && ! ctype_alnum( $character ) ) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Get an implicit projection alias when a complex expression is followed by a name.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection item token position.
	 * @param int             $end    Final projection item token position, exclusive.
	 * @return string|null Alias value, or null when absent.
	 */
	private function get_mysql_implicit_projection_alias( array $tokens, int $start, int $end ): ?string {
		if ( $start + 1 >= $end ) {
			return null;
		}

		$alias = $this->get_mysql_identifier_token_value( $tokens[ $end - 1 ] ?? null );
		if ( null === $alias ) {
			return null;
		}

		if ( isset( $tokens[ $end - 2 ] ) && WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $end - 2 ]->id ) {
			return null;
		}

		return $alias;
	}

	/**
	 * Infer the default visible name for a projected expression.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token position.
	 * @param int             $end    Final expression token position, exclusive.
	 * @return string|null Output column name, or null when unsupported.
	 */
	private function get_mysql_select_expression_default_output_name( array $tokens, int $start, int $end ): ?string {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start  = $bounds['start'];
		$end    = $bounds['end'];

		if ( $start + 1 === $end ) {
			return $this->get_mysql_identifier_token_value( $tokens[ $start ] ?? null );
		}

		if (
			$start + 3 <= $end
			&& isset( $tokens[ $end - 2 ], $tokens[ $end - 1 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $end - 2 ]->id
		) {
			return $this->get_mysql_identifier_token_value( $tokens[ $end - 1 ] );
		}

		return null;
	}

	/**
	 * Parse ORDER BY items and connect them to projected expressions when possible.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int             $start            First ORDER BY item token position.
	 * @param int             $end              Final ORDER BY token position, exclusive.
	 * @param array           $projection_items Parsed projection items.
	 * @param array|null      $scope            Optional statement table scope for contextual expression coercions.
	 * @return array<int, array{expression_start: int, expression_end: int, sql: string, direction: string, direction_explicit: bool, projection_index: int|null, changed: bool}>|null
	 * ORDER BY items.
	 */
	private function parse_mysql_select_order_by_items(
		array $tokens,
		int $start,
		int $end,
		array $projection_items,
		?array $scope = null
	): ?array {
		$ranges = $this->split_top_level_mysql_arguments( $tokens, $start, $end );
		if ( null === $ranges || count( $ranges ) < 1 ) {
			return null;
		}

		$items = array();
		foreach ( $ranges as $range ) {
			$expression_end     = $range['end'];
			$direction          = 'ASC';
			$direction_explicit = false;

			if (
				isset( $tokens[ $expression_end - 1 ] )
				&& (
					WP_MySQL_Lexer::ASC_SYMBOL === $tokens[ $expression_end - 1 ]->id
					|| WP_MySQL_Lexer::DESC_SYMBOL === $tokens[ $expression_end - 1 ]->id
				)
			) {
				$direction          = WP_MySQL_Lexer::DESC_SYMBOL === $tokens[ $expression_end - 1 ]->id ? 'DESC' : 'ASC';
				$direction_explicit = true;
				--$expression_end;
			}

			if ( $range['start'] >= $expression_end ) {
				return null;
			}

			$expression_sql = null === $scope
				? array(
					'sql'     => $this->translate_mysql_token_sequence_to_postgresql(
						$tokens,
						$range['start'],
						$expression_end
					),
					'changed' => false,
				)
				: $this->translate_mysql_expression_token_sequence_to_postgresql(
					$tokens,
					$range['start'],
					$expression_end,
					$scope
				);

			$items[] = array(
				'expression_start'   => $range['start'],
				'expression_end'     => $expression_end,
				'sql'                => $expression_sql['sql'],
				'direction'          => $direction,
				'direction_explicit' => $direction_explicit,
				'projection_index'   => $this->find_mysql_projection_for_order_expression(
					$tokens,
					$range['start'],
					$expression_end,
					$projection_items
				),
				'changed'            => $expression_sql['changed'],
			);
		}

		return $items;
	}

	/**
	 * Find a projection item that satisfies an ORDER BY expression.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int             $start            First ORDER BY expression token.
	 * @param int             $end              Final ORDER BY expression token, exclusive.
	 * @param array           $projection_items Parsed projection items.
	 * @return int|null Projection item index, or null when not projected.
	 */
	private function find_mysql_projection_for_order_expression( array $tokens, int $start, int $end, array $projection_items ): ?int {
		foreach ( $projection_items as $index => $projection_item ) {
			if (
				$this->are_mysql_token_ranges_equivalent(
					$tokens,
					$start,
					$end,
					$projection_item['expression_start'],
					$projection_item['expression_end']
				)
			) {
				return $index;
			}
		}

		if ( $start + 1 === $end ) {
			$ordinal = $this->get_mysql_order_by_ordinal_projection_index( $tokens[ $start ], count( $projection_items ) );
			if ( null !== $ordinal ) {
				return $ordinal;
			}

			$alias = $this->get_mysql_order_by_alias_token_value( $tokens[ $start ] );
			if ( null !== $alias ) {
				foreach ( $projection_items as $index => $projection_item ) {
					if ( strtolower( $alias ) === strtolower( $projection_item['alias'] ) ) {
						return $index;
					}
				}
			}
		}

		return null;
	}

	/**
	 * Get a one-token ORDER BY alias reference.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @return string|null Alias value, or null when unsupported.
	 */
	private function get_mysql_order_by_alias_token_value( ?WP_MySQL_Token $token ): ?string {
		if ( null === $token ) {
			return null;
		}

		$identifier = $this->get_mysql_identifier_token_value( $token );
		if ( null !== $identifier ) {
			return $identifier;
		}

		if ( WP_MySQL_Lexer::SINGLE_QUOTED_TEXT === $token->id || WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT === $token->id ) {
			return null;
		}

		$value = $token->get_value();
		if ( $this->is_mysql_unquoted_projection_alias_value( $value ) ) {
			return $value;
		}

		return null;
	}

	/**
	 * Resolve a positional ORDER BY item to a projection index.
	 *
	 * @param WP_MySQL_Token $token            ORDER BY token.
	 * @param int            $projection_count Number of projected columns.
	 * @return int|null Zero-based projection index, or null when unsupported.
	 */
	private function get_mysql_order_by_ordinal_projection_index( WP_MySQL_Token $token, int $projection_count ): ?int {
		if (
			! in_array( $token->id, array( WP_MySQL_Lexer::INT_NUMBER, WP_MySQL_Lexer::LONG_NUMBER ), true )
			|| ! ctype_digit( $token->get_value() )
		) {
			return null;
		}

		$ordinal = (int) $token->get_value();
		if ( $ordinal < 1 || $ordinal > $projection_count ) {
			return null;
		}

		return $ordinal - 1;
	}

	/**
	 * Check whether a bounded token range contains any token IDs.
	 *
	 * @param WP_MySQL_Token[] $tokens    MySQL lexer token stream.
	 * @param int             $start     First token position, inclusive.
	 * @param int             $end       Final token position, exclusive.
	 * @param int[]           $token_ids Token IDs to detect.
	 * @return bool Whether any token ID was found.
	 */
	private function contains_mysql_token( array $tokens, int $start, int $end, array $token_ids ): bool {
		$lookup = array();
		foreach ( $token_ids as $token_id ) {
			$lookup[ $token_id ] = true;
		}

		for ( $i = $start; $i < $end; $i++ ) {
			if ( isset( $lookup[ $tokens[ $i ]->id ] ) ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Build a grouped derived-table rewrite for DISTINCT ORDER BY queries.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param array           $projection_items Parsed projection items.
	 * @param array           $order_items      Parsed ORDER BY items.
	 * @param int             $from_position    FROM token position.
	 * @param int             $order_position   ORDER token position.
	 * @param int|null        $limit_position   LIMIT token position, or null.
	 * @param int             $statement_end    Final statement token position, exclusive.
	 * @param bool            $include_limit    Whether to preserve the LIMIT/OFFSET clause.
	 * @return string PostgreSQL query.
	 */
	private function build_distinct_order_by_grouped_query(
		array $tokens,
		array $projection_items,
		array $order_items,
		int $from_position,
		int $order_position,
		?int $limit_position,
		int $statement_end,
		bool $include_limit = true
	): string {
		$derived_table_alias        = '__wp_pg_distinct';
		$quoted_derived_table_alias = $this->connection->quote_identifier( $derived_table_alias );
		$inner_projection_sql       = array();
		$outer_projection_sql       = array();
		$group_by_sql               = array();

		foreach ( $projection_items as $projection_item ) {
			$quoted_alias           = $this->connection->quote_identifier( $projection_item['alias'] );
			$inner_projection_sql[] = $projection_item['sql'] . ' AS ' . $quoted_alias;
			$outer_projection_sql[] = sprintf(
				'%s.%s AS %s',
				$quoted_derived_table_alias,
				$quoted_alias,
				$quoted_alias
			);
			$group_by_sql[]         = $projection_item['sql'];
		}

		foreach ( $order_items as $index => $order_item ) {
			if ( null !== $order_item['projection_index'] ) {
				continue;
			}

			$aggregate_function     = 'DESC' === $order_item['direction'] ? 'MAX' : 'MIN';
			$quoted_order_alias     = $this->connection->quote_identifier( $this->get_distinct_order_by_hidden_alias( $index ) );
			$inner_projection_sql[] = sprintf(
				'%s(%s) AS %s',
				$aggregate_function,
				$order_item['sql'],
				$quoted_order_alias
			);
		}

		$sql = sprintf(
			'SELECT %s FROM (SELECT %s %s GROUP BY %s) AS %s ORDER BY %s',
			implode( ', ', $outer_projection_sql ),
			implode( ', ', $inner_projection_sql ),
			$this->translate_mysql_token_sequence_to_postgresql( $tokens, $from_position, $order_position ),
			implode( ', ', $group_by_sql ),
			$quoted_derived_table_alias,
			$this->get_distinct_order_by_outer_order_sql( $projection_items, $order_items, $quoted_derived_table_alias )
		);

		if ( $include_limit && null !== $limit_position ) {
			$sql .= $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end );
		}

		return $sql;
	}

	/**
	 * Get the hidden ORDER BY alias for a parsed order item.
	 *
	 * @param int $index ORDER BY item index.
	 * @return string Hidden alias.
	 */
	private function get_distinct_order_by_hidden_alias( int $index ): string {
		return '__wp_pg_order_' . $index;
	}

	/**
	 * Build the outer ORDER BY clause for a grouped DISTINCT rewrite.
	 *
	 * @param array  $projection_items           Parsed projection items.
	 * @param array  $order_items                Parsed ORDER BY items.
	 * @param string $quoted_derived_table_alias Quoted derived table alias.
	 * @return string Outer ORDER BY SQL.
	 */
	private function get_distinct_order_by_outer_order_sql( array $projection_items, array $order_items, string $quoted_derived_table_alias ): string {
		$order_sql = array();

		foreach ( $order_items as $index => $order_item ) {
			if ( null !== $order_item['projection_index'] ) {
				$order_alias = $projection_items[ $order_item['projection_index'] ]['alias'];
			} else {
				$order_alias = $this->get_distinct_order_by_hidden_alias( $index );
			}

			$order_sql[] = sprintf(
				'%s.%s %s',
				$quoted_derived_table_alias,
				$this->connection->quote_identifier( $order_alias ),
				$order_item['direction']
			);
		}

		return implode( ', ', $order_sql );
	}

	/**
	 * Translate aggregate/grouped SELECT ORDER BY clauses that PostgreSQL rejects.
	 *
	 * MySQL permits non-grouped ORDER BY expressions in grouped queries. Keep
	 * this rewrite limited to WordPress's scalar count and grouped archive/comment
	 * ID query shapes so unsupported grouping semantics still fail visibly.
	 *
	 * @param string $query         MySQL query.
	 * @param bool   $include_limit Whether to preserve the LIMIT/OFFSET clause.
	 * @return string|null PostgreSQL query, or null when the query is unsupported.
	 */
	private function translate_strict_aggregate_grouped_order_by_query( string $query, bool $include_limit = true ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return null;
		}

		$projection_start = 1;
		$has_distinct     = false;
		if ( isset( $tokens[ $projection_start ] ) && WP_MySQL_Lexer::DISTINCT_SYMBOL === $tokens[ $projection_start ]->id ) {
			$has_distinct = true;
			++$projection_start;
		}

		if ( isset( $tokens[ $projection_start ] ) && WP_MySQL_Lexer::SQL_CALC_FOUND_ROWS_SYMBOL === $tokens[ $projection_start ]->id ) {
			++$projection_start;
		}

		$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, $projection_start, $statement_end );
		$select_end     = $limit_position ?? $statement_end;
		if ( null !== $limit_position && ! $this->is_supported_simple_select_limit_clause( $tokens, $limit_position, $statement_end ) ) {
			return null;
		}

		$order_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::ORDER_SYMBOL, $projection_start, $select_end );
		if (
			null === $order_position
			|| ! isset( $tokens[ $order_position + 1 ] )
			|| WP_MySQL_Lexer::BY_SYMBOL !== $tokens[ $order_position + 1 ]->id
			|| $order_position + 2 >= $select_end
		) {
			return null;
		}

		if (
			$this->contains_top_level_mysql_token(
				$tokens,
				$projection_start,
				$select_end,
				array(
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::HAVING_SYMBOL,
					WP_MySQL_Lexer::INTO_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				)
			)
		) {
			return null;
		}

		$group_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::GROUP_SYMBOL, $projection_start, $order_position );
		if ( null === $group_position ) {
			return $this->translate_strict_aggregate_only_order_by_query(
				$tokens,
				$projection_start,
				$order_position,
				$limit_position,
				$statement_end,
				$include_limit
			);
		}

		if (
			! isset( $tokens[ $group_position + 1 ] )
			|| WP_MySQL_Lexer::BY_SYMBOL !== $tokens[ $group_position + 1 ]->id
			|| $group_position + 2 >= $order_position
		) {
			return null;
		}

		return $this->translate_strict_grouped_order_by_query(
			$tokens,
			$projection_start,
			$group_position,
			$order_position,
			$limit_position,
			$statement_end,
			$has_distinct,
			$include_limit
		);
	}

	/**
	 * Drop ORDER BY from scalar COUNT-only aggregate queries.
	 *
	 * @param WP_MySQL_Token[] $tokens         MySQL lexer token stream.
	 * @param int             $projection_start First projection token position.
	 * @param int             $order_position ORDER token position.
	 * @param int|null        $limit_position LIMIT token position, or null.
	 * @param int             $statement_end  Final statement token position, exclusive.
	 * @param bool            $include_limit  Whether to preserve the LIMIT/OFFSET clause.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_strict_aggregate_only_order_by_query(
		array $tokens,
		int $projection_start,
		int $order_position,
		?int $limit_position,
		int $statement_end,
		bool $include_limit = true
	): ?string {
		$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, $projection_start, $order_position );
		if ( null === $from_position || $projection_start === $from_position ) {
			return null;
		}

		if ( ! $this->is_mysql_count_only_projection( $tokens, $projection_start, $from_position ) ) {
			return null;
		}

		$sql = 'SELECT ' . $this->translate_mysql_token_sequence_to_postgresql( $tokens, $projection_start, $order_position );
		if ( $include_limit && null !== $limit_position ) {
			$sql .= $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end );
		}

		return $sql;
	}

	/**
	 * Translate targeted grouped ORDER BY expressions to aggregate-safe forms.
	 *
	 * @param WP_MySQL_Token[] $tokens         MySQL lexer token stream.
	 * @param int             $projection_start First projection token position.
	 * @param int             $group_position GROUP token position.
	 * @param int             $order_position ORDER token position.
	 * @param int|null        $limit_position LIMIT token position, or null.
	 * @param int             $statement_end  Final statement token position, exclusive.
	 * @param bool            $has_distinct   Whether the original SELECT used DISTINCT.
	 * @param bool            $include_limit  Whether to preserve the LIMIT/OFFSET clause.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_strict_grouped_order_by_query(
		array $tokens,
		int $projection_start,
		int $group_position,
		int $order_position,
		?int $limit_position,
		int $statement_end,
		bool $has_distinct,
		bool $include_limit = true
	): ?string {
		$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, $projection_start, $group_position );
		if ( null === $from_position || $projection_start === $from_position ) {
			return null;
		}

		$projection_items = $this->parse_mysql_select_projection_items( $tokens, $projection_start, $from_position );
		if ( null === $projection_items ) {
			return null;
		}

		$group_items = $this->split_top_level_mysql_arguments( $tokens, $group_position + 2, $order_position );
		if ( null === $group_items || count( $group_items ) < 1 ) {
			return null;
		}

		$scope_end = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::WHERE_SYMBOL,
			$from_position + 1,
			$group_position
		) ?? $group_position;
		$scope     = $this->get_mysql_select_scope( $tokens, $from_position + 1, $scope_end );
		if ( null === $scope ) {
			return null;
		}

		$select_end  = $limit_position ?? $statement_end;
		$order_items = $this->parse_mysql_select_order_by_items(
			$tokens,
			$order_position + 2,
			$select_end,
			$projection_items,
			$scope
		);
		if ( null === $order_items ) {
			return null;
		}

		$archive_date_expression = $this->get_mysql_archive_grouped_date_expression_bounds( $tokens, $group_items );
		$is_comment_id_group     = $this->is_mysql_comment_id_grouped_select_shape( $tokens, $projection_items, $group_items );
		$is_post_id_group        = $this->is_mysql_post_id_grouped_select_shape( $tokens, $projection_items, $group_items );

		if (
			$has_distinct
			&& (
				null === $archive_date_expression
				|| ! $this->is_mysql_redundant_distinct_week_archive_select_shape(
					$tokens,
					$projection_items,
					$group_items,
					$archive_date_expression
				)
			)
		) {
			return $this->translate_distinct_strict_grouped_order_by_query(
				$tokens,
				$projection_start,
				$projection_items,
				$group_items,
				$order_items,
				$from_position,
				$group_position,
				$order_position,
				$limit_position,
				$statement_end,
				$include_limit
			);
		}

		if ( null === $archive_date_expression && ! $is_comment_id_group && ! $is_post_id_group ) {
			return null;
		}

		$order_sql = array();
		$rewritten = false;
		foreach ( $order_items as $order_item ) {
			if (
				null !== $order_item['projection_index']
				|| $this->is_mysql_grouped_order_expression( $tokens, $order_item, $group_items )
			) {
				$order_sql[] = $order_item['sql'] . ' ' . $order_item['direction'];
				continue;
			}

			if (
				null !== $archive_date_expression
				&& $this->is_mysql_archive_post_date_order_expression( $tokens, $order_item, $archive_date_expression )
			) {
				$order_sql[] = $this->get_strict_grouped_aggregate_order_sql( $order_item );
				$rewritten   = true;
				continue;
			}

			if (
				(
					$is_comment_id_group
					&& $this->is_mysql_comment_id_grouped_order_expression( $tokens, $order_item )
				)
				|| (
					$is_post_id_group
					&& $this->is_mysql_post_id_grouped_order_expression( $tokens, $order_item )
				)
			) {
				$order_sql[] = $this->get_strict_grouped_aggregate_order_sql( $order_item );
				$rewritten   = true;
				continue;
			}

			return null;
		}

		$tiebreaker_sql = $this->get_strict_grouped_posts_post_date_desc_order_id_tiebreaker_sql(
			$tokens,
			$order_items,
			$group_items,
			$is_post_id_group
		);
		if ( null !== $tiebreaker_sql ) {
			$order_sql[] = $tiebreaker_sql;
			$rewritten   = true;
		}

		if ( ! $rewritten ) {
			return null;
		}

		$replacements   = array();
		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, $projection_start, $group_position );
		if ( null !== $archive_date_expression ) {
			$replacements = array_merge(
				$replacements,
				$this->get_mysql_archive_grouped_projection_replacements(
					$tokens,
					$projection_items,
					$archive_date_expression
				)
			);
		}

		if ( null !== $where_position ) {
			$where_sql = $this->translate_mysql_predicate_token_sequence_to_postgresql(
				$tokens,
				$where_position + 1,
				$group_position,
				$scope
			);
			if ( $where_sql['changed'] ) {
				$replacements[] = array(
					'start' => $where_position + 1,
					'end'   => $group_position,
					'sql'   => $where_sql['sql'],
				);
			}
		}

		$sql = 'SELECT ' . $this->translate_mysql_token_sequence_with_replacements_to_postgresql(
			$tokens,
			$projection_start,
			$order_position,
			$replacements
		)
			. ' ORDER BY ' . implode( ', ', $order_sql );
		if ( $include_limit && null !== $limit_position ) {
			$sql .= $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end );
		}

		return $sql;
	}

	/**
	 * Translate DISTINCT grouped queries that need hidden ORDER BY projections.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int             $projection_start First projection token position.
	 * @param array           $projection_items Parsed projection items.
	 * @param array           $group_items      Parsed GROUP BY item ranges.
	 * @param array           $order_items      Parsed ORDER BY items.
	 * @param int             $from_position    FROM token position.
	 * @param int             $group_position   GROUP token position.
	 * @param int             $order_position   ORDER token position.
	 * @param int|null        $limit_position   LIMIT token position, or null.
	 * @param int             $statement_end    Final statement token position, exclusive.
	 * @param bool            $include_limit    Whether to preserve the LIMIT/OFFSET clause.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_distinct_strict_grouped_order_by_query(
		array $tokens,
		int $projection_start,
		array $projection_items,
		array $group_items,
		array $order_items,
		int $from_position,
		int $group_position,
		int $order_position,
		?int $limit_position,
		int $statement_end,
		bool $include_limit = true
	): ?string {
		$select_end = $limit_position ?? $statement_end;
		if (
			$this->contains_mysql_token(
				$tokens,
				$projection_start,
				$select_end,
				array(
					WP_MySQL_Lexer::SELECT_SYMBOL,
				)
			)
		) {
			return null;
		}

		$has_hidden_order_expression = false;
		foreach ( $order_items as $order_item ) {
			if ( null === $order_item['projection_index'] ) {
				$has_hidden_order_expression = true;
				break;
			}
		}

		if ( ! $has_hidden_order_expression ) {
			return null;
		}

		if (
			! $this->contains_mysql_aggregate_call( $tokens, $projection_start, $select_end )
			&& $this->is_mysql_distinct_grouped_projection_shape( $tokens, $projection_items, $group_items )
		) {
			return $this->build_distinct_strict_grouped_order_by_query(
				$tokens,
				$projection_items,
				$this->get_mysql_group_by_item_sql( $tokens, $group_items ),
				$order_items,
				$from_position,
				$group_position,
				$order_position,
				$limit_position,
				$statement_end,
				$include_limit
			);
		}

		$group_by_sql = $this->get_mysql_distinct_term_taxonomy_group_by_sql(
			$tokens,
			$projection_items,
			$group_items,
			$order_items,
			$from_position,
			$group_position
		);
		if ( null === $group_by_sql ) {
			return null;
		}

		return $this->build_distinct_strict_grouped_order_by_query(
			$tokens,
			$projection_items,
			$group_by_sql,
			$order_items,
			$from_position,
			$group_position,
			$order_position,
			$limit_position,
			$statement_end,
			$include_limit
		);
	}

	/**
	 * Translate parsed GROUP BY items to PostgreSQL SQL.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param array           $group_items Parsed GROUP BY item ranges.
	 * @return string[] PostgreSQL GROUP BY expressions.
	 */
	private function get_mysql_group_by_item_sql( array $tokens, array $group_items ): array {
		$group_by_sql = array();
		foreach ( $group_items as $group_item ) {
			$group_by_sql[] = $this->translate_mysql_token_sequence_to_postgresql(
				$tokens,
				$group_item['start'],
				$group_item['end']
			);
		}

		return $group_by_sql;
	}

	/**
	 * Check whether DISTINCT projection expressions exactly match GROUP BY.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param array           $projection_items Parsed projection items.
	 * @param array           $group_items      Parsed GROUP BY item ranges.
	 * @return bool Whether grouping already preserves DISTINCT cardinality.
	 */
	private function is_mysql_distinct_grouped_projection_shape( array $tokens, array $projection_items, array $group_items ): bool {
		if ( count( $projection_items ) !== count( $group_items ) ) {
			return false;
		}

		$matched_group_items = array();
		foreach ( $projection_items as $projection_item ) {
			$matched = false;
			foreach ( $group_items as $group_index => $group_item ) {
				if ( isset( $matched_group_items[ $group_index ] ) ) {
					continue;
				}

				if (
					$this->are_mysql_token_ranges_equivalent(
						$tokens,
						$projection_item['expression_start'],
						$projection_item['expression_end'],
						$group_item['start'],
						$group_item['end']
					)
				) {
					$matched_group_items[ $group_index ] = true;
					$matched                             = true;
					break;
				}
			}

			if ( ! $matched ) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Get GROUP BY expressions for the supported single-taxonomy term query.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param array           $projection_items Parsed projection items.
	 * @param array           $group_items      Parsed GROUP BY item ranges.
	 * @param array           $order_items      Parsed ORDER BY items.
	 * @param int             $from_position    FROM token position.
	 * @param int             $group_position   GROUP token position.
	 * @return string[]|null PostgreSQL GROUP BY expressions, or null when unsupported.
	 */
	private function get_mysql_distinct_term_taxonomy_group_by_sql(
		array $tokens,
		array $projection_items,
		array $group_items,
		array $order_items,
		int $from_position,
		int $group_position
	): ?array {
		if (
			! $this->is_mysql_distinct_term_taxonomy_projection_shape( $tokens, $projection_items )
			|| ! $this->is_mysql_distinct_term_taxonomy_group_shape( $tokens, $group_items )
			|| ! $this->is_mysql_distinct_term_taxonomy_order_shape( $tokens, $order_items )
		) {
			return null;
		}

		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, $from_position + 1, $group_position );
		if (
			null === $where_position
			|| ! $this->is_mysql_distinct_term_taxonomy_from_shape( $tokens, $from_position, $where_position )
			|| ! $this->has_mysql_single_term_taxonomy_predicate( $tokens, $where_position + 1, $group_position )
		) {
			return null;
		}

		return array(
			't.term_id',
			'tt.term_taxonomy_id',
			'tt.taxonomy',
			'tt.description',
			'tt.parent',
		);
	}

	/**
	 * Check whether the projection is WordPress's term query result shape.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param array           $projection_items Parsed projection items.
	 * @return bool Whether the projection shape is supported.
	 */
	private function is_mysql_distinct_term_taxonomy_projection_shape( array $tokens, array $projection_items ): bool {
		if ( 6 !== count( $projection_items ) ) {
			return false;
		}

		$expected_columns = array(
			array( 't', 'term_id', 'term_id' ),
			array( 'tt', 'term_taxonomy_id', 'term_taxonomy_id' ),
			array( 'tt', 'taxonomy', 'taxonomy' ),
			array( 'tt', 'description', 'description' ),
			array( 'tt', 'parent', 'parent' ),
		);
		foreach ( $expected_columns as $index => $expected_column ) {
			if (
				! $this->is_mysql_projection_item_qualified_column(
					$tokens,
					$projection_items[ $index ],
					$expected_column[0],
					$expected_column[1],
					$expected_column[2]
				)
			) {
				return false;
			}
		}

		return $this->is_mysql_count_post_type_projection_item( $tokens, $projection_items[5] );
	}

	/**
	 * Check whether a projection item is a specific qualified column.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param array           $item   Parsed projection item.
	 * @param string          $alias  Expected table alias.
	 * @param string          $column Expected column name.
	 * @param string          $name   Expected output name.
	 * @return bool Whether the projection item matches.
	 */
	private function is_mysql_projection_item_qualified_column( array $tokens, array $item, string $alias, string $column, string $name ): bool {
		return strtolower( $item['alias'] ) === $name
			&& $this->is_mysql_exact_qualified_column_expression(
				$tokens,
				$item['expression_start'],
				$item['expression_end'],
				$alias,
				$column
			);
	}

	/**
	 * Check whether a projection item is COUNT(p.post_type) AS count.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param array           $item   Parsed projection item.
	 * @return bool Whether the projection item matches.
	 */
	private function is_mysql_count_post_type_projection_item( array $tokens, array $item ): bool {
		if ( 'count' !== strtolower( $item['alias'] ) ) {
			return false;
		}

		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $item['expression_start'], $item['expression_end'] );
		if (
			! isset( $tokens[ $bounds['start'] ], $tokens[ $bounds['start'] + 1 ] )
			|| ! $this->is_mysql_token_value( $tokens[ $bounds['start'] ], 'count' )
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $bounds['start'] + 1 ]->id
			|| $this->get_mysql_parenthesized_sequence_end( $tokens, $bounds['start'] + 1, $bounds['end'] ) !== $bounds['end']
		) {
			return false;
		}

		return $this->is_mysql_exact_qualified_column_expression(
			$tokens,
			$bounds['start'] + 2,
			$bounds['end'] - 1,
			'p',
			'post_type'
		);
	}

	/**
	 * Check whether GROUP BY is exactly t.term_id.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param array           $group_items Parsed GROUP BY item ranges.
	 * @return bool Whether the group shape is supported.
	 */
	private function is_mysql_distinct_term_taxonomy_group_shape( array $tokens, array $group_items ): bool {
		return 1 === count( $group_items )
			&& $this->is_mysql_exact_qualified_column_expression(
				$tokens,
				$group_items[0]['start'],
				$group_items[0]['end'],
				't',
				'term_id'
			);
	}

	/**
	 * Check whether ORDER BY can be hidden for the supported term query.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param array           $order_items Parsed ORDER BY items.
	 * @return bool Whether the order shape is supported.
	 */
	private function is_mysql_distinct_term_taxonomy_order_shape( array $tokens, array $order_items ): bool {
		if ( 1 !== count( $order_items ) || null !== $order_items[0]['projection_index'] ) {
			return false;
		}

		return $this->is_mysql_exact_qualified_column_expression(
			$tokens,
			$order_items[0]['expression_start'],
			$order_items[0]['expression_end'],
			't',
			'name'
		);
	}

	/**
	 * Check whether FROM begins with terms t joined to term_taxonomy tt.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int             $from_position FROM token position.
	 * @param int             $from_end      Final FROM-clause token, exclusive.
	 * @return bool Whether the FROM shape is supported.
	 */
	private function is_mysql_distinct_term_taxonomy_from_shape( array $tokens, int $from_position, int $from_end ): bool {
		$terms_reference = $this->parse_mysql_table_reference( $tokens, $from_position + 1, $from_end );
		if (
			null === $terms_reference
			|| ! $this->is_mysql_wordpress_table_reference( $terms_reference, 'terms', 't' )
		) {
			return false;
		}

		$position = $terms_reference['position'];
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::INNER_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::JOIN_SYMBOL !== $tokens[ $position ]->id ) {
			return false;
		}

		$term_taxonomy_reference = $this->parse_mysql_table_reference( $tokens, $position + 1, $from_end );
		if (
			null === $term_taxonomy_reference
			|| ! $this->is_mysql_wordpress_table_reference( $term_taxonomy_reference, 'term_taxonomy', 'tt' )
		) {
			return false;
		}

		$position = $term_taxonomy_reference['position'];
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::ON_SYMBOL !== $tokens[ $position ]->id ) {
			return false;
		}

		$predicate_end = $this->find_mysql_join_predicate_end( $tokens, $position + 1, $from_end );
		$pair          = $this->get_mysql_top_level_simple_column_equality_pair( $tokens, $position + 1, $predicate_end );
		return null !== $pair && $this->is_mysql_wordpress_term_split_column_equality_pair( $pair );
	}

	/**
	 * Check whether WHERE constrains tt.taxonomy to one string literal.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First WHERE predicate token.
	 * @param int             $end    Final WHERE predicate token, exclusive.
	 * @return bool Whether a single taxonomy predicate is present.
	 */
	private function has_mysql_single_term_taxonomy_predicate( array $tokens, int $start, int $end ): bool {
		$conjuncts = $this->split_mysql_top_level_boolean_conjuncts( $tokens, $start, $end );
		if ( null === $conjuncts ) {
			return false;
		}

		$matched = false;
		foreach ( $conjuncts as $conjunct ) {
			if ( ! $this->is_mysql_single_term_taxonomy_predicate( $tokens, $conjunct['start'], $conjunct['end'] ) ) {
				continue;
			}

			if ( $matched ) {
				return false;
			}

			$matched = true;
		}

		return $matched;
	}

	/**
	 * Check whether a predicate is tt.taxonomy = literal or IN (single literal).
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First predicate token.
	 * @param int             $end    Final predicate token, exclusive.
	 * @return bool Whether the predicate constrains one taxonomy value.
	 */
	private function is_mysql_single_term_taxonomy_predicate( array $tokens, int $start, int $end ): bool {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start  = $bounds['start'];
		$end    = $bounds['end'];

		$reference = $this->parse_mysql_column_reference( $tokens, $start, $end );
		if (
			null === $reference
			|| $reference['end'] >= $end
			|| 'tt' !== strtolower( (string) $reference['qualifier'] )
			|| 'taxonomy' !== strtolower( $reference['column'] )
		) {
			return false;
		}

		if (
			WP_MySQL_Lexer::EQUAL_OPERATOR === $tokens[ $reference['end'] ]->id
			&& $this->is_mysql_string_literal_range( $tokens, $reference['end'] + 1, $end )
		) {
			return true;
		}

		if (
			WP_MySQL_Lexer::IN_SYMBOL !== $tokens[ $reference['end'] ]->id
			|| ! isset( $tokens[ $reference['end'] + 1 ] )
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $reference['end'] + 1 ]->id
		) {
			return false;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $reference['end'] + 1, $end );
		if ( $after_close !== $end ) {
			return false;
		}

		$items = $this->split_top_level_mysql_arguments( $tokens, $reference['end'] + 2, $end - 1 );
		return null !== $items
			&& 1 === count( $items )
			&& $this->is_mysql_string_literal_range( $tokens, $items[0]['start'], $items[0]['end'] );
	}

	/**
	 * Check whether an expression is exactly a qualified column reference.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token.
	 * @param int             $end    Final expression token, exclusive.
	 * @param string          $alias  Expected table alias.
	 * @param string          $column Expected column name.
	 * @return bool Whether the expression matches.
	 */
	private function is_mysql_exact_qualified_column_expression( array $tokens, int $start, int $end, string $alias, string $column ): bool {
		$column_expression = $this->get_mysql_simple_qualified_column_expression( $tokens, $start, $end );
		return null !== $column_expression
			&& strtolower( $alias ) === $column_expression['qualifier']
			&& strtolower( $column ) === $column_expression['column'];
	}

	/**
	 * Build a derived-table rewrite for DISTINCT grouped ORDER BY queries.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param array           $projection_items Parsed projection items.
	 * @param string[]        $group_by_sql     PostgreSQL GROUP BY expressions.
	 * @param array           $order_items      Parsed ORDER BY items.
	 * @param int             $from_position    FROM token position.
	 * @param int             $group_position   GROUP token position.
	 * @param int             $order_position   ORDER token position.
	 * @param int|null        $limit_position   LIMIT token position, or null.
	 * @param int             $statement_end    Final statement token position, exclusive.
	 * @param bool            $include_limit    Whether to preserve the LIMIT/OFFSET clause.
	 * @return string PostgreSQL query.
	 */
	private function build_distinct_strict_grouped_order_by_query(
		array $tokens,
		array $projection_items,
		array $group_by_sql,
		array $order_items,
		int $from_position,
		int $group_position,
		int $order_position,
		?int $limit_position,
		int $statement_end,
		bool $include_limit = true
	): string {
		$derived_table_alias        = '__wp_pg_distinct';
		$quoted_derived_table_alias = $this->connection->quote_identifier( $derived_table_alias );
		$inner_projection_sql       = array();
		$outer_projection_sql       = array();

		foreach ( $projection_items as $projection_item ) {
			$quoted_alias           = $this->connection->quote_identifier( $projection_item['alias'] );
			$inner_projection_sql[] = $projection_item['sql'] . ' AS ' . $quoted_alias;
			$outer_projection_sql[] = sprintf(
				'%s.%s AS %s',
				$quoted_derived_table_alias,
				$quoted_alias,
				$quoted_alias
			);
		}

		foreach ( $order_items as $index => $order_item ) {
			if ( null !== $order_item['projection_index'] ) {
				continue;
			}

			$aggregate_function     = 'DESC' === $order_item['direction'] ? 'MAX' : 'MIN';
			$quoted_order_alias     = $this->connection->quote_identifier( $this->get_distinct_order_by_hidden_alias( $index ) );
			$inner_projection_sql[] = sprintf(
				'%s(%s) AS %s',
				$aggregate_function,
				$order_item['sql'],
				$quoted_order_alias
			);
		}

		$sql = sprintf(
			'SELECT %s FROM (SELECT DISTINCT %s %s GROUP BY %s) AS %s ORDER BY %s',
			implode( ', ', $outer_projection_sql ),
			implode( ', ', $inner_projection_sql ),
			$this->translate_mysql_token_sequence_to_postgresql( $tokens, $from_position, $group_position ),
			implode( ', ', $group_by_sql ),
			$quoted_derived_table_alias,
			$this->get_distinct_order_by_outer_order_sql( $projection_items, $order_items, $quoted_derived_table_alias )
		);

		if ( $include_limit && null !== $limit_position ) {
			$sql .= $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end );
		}

		return $sql;
	}

	/**
	 * Translate grouped SELECT queries that reference projection aliases in HAVING.
	 *
	 * MySQL resolves SELECT aliases in HAVING, but PostgreSQL does not. Keep this
	 * rewrite limited to aliases whose projected expression is valid in a grouped
	 * HAVING clause so unsupported grouping shapes still fail visibly.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_grouped_having_alias_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return null;
		}

		if (
			$this->contains_top_level_mysql_token(
				$tokens,
				1,
				$statement_end,
				array(
					WP_MySQL_Lexer::DISTINCT_SYMBOL,
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::HIGH_PRIORITY_SYMBOL,
					WP_MySQL_Lexer::INTO_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::SELECT_SYMBOL,
					WP_MySQL_Lexer::SQL_CALC_FOUND_ROWS_SYMBOL,
					WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				)
			)
		) {
			return null;
		}

		$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, 1, $statement_end );
		$select_end     = $limit_position ?? $statement_end;
		if ( null !== $limit_position && ! $this->is_supported_simple_select_limit_clause( $tokens, $limit_position, $statement_end ) ) {
			return null;
		}

		$order_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::ORDER_SYMBOL, 1, $select_end );
		if (
			null !== $order_position
			&& (
				! isset( $tokens[ $order_position + 1 ] )
				|| WP_MySQL_Lexer::BY_SYMBOL !== $tokens[ $order_position + 1 ]->id
				|| $order_position + 2 >= $select_end
			)
		) {
			return null;
		}

		$having_end      = $order_position ?? $select_end;
		$having_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::HAVING_SYMBOL, 1, $having_end );
		if ( null === $having_position || $having_position + 1 >= $having_end ) {
			return null;
		}

		$group_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::GROUP_SYMBOL, 1, $having_position );
		if (
			null === $group_position
			|| ! isset( $tokens[ $group_position + 1 ] )
			|| WP_MySQL_Lexer::BY_SYMBOL !== $tokens[ $group_position + 1 ]->id
			|| $group_position + 2 >= $having_position
		) {
			return null;
		}

		$from_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::FROM_SYMBOL, 1, $group_position );
		if ( null === $from_position || 1 === $from_position ) {
			return null;
		}

		$group_items = $this->split_top_level_mysql_arguments( $tokens, $group_position + 2, $having_position );
		if ( null === $group_items || count( $group_items ) < 1 ) {
			return null;
		}

		$alias_expressions = $this->get_mysql_grouped_having_projection_alias_expressions(
			$tokens,
			1,
			$from_position,
			$group_items
		);
		if ( null === $alias_expressions || empty( $alias_expressions ) ) {
			return null;
		}

		$having_sql = $this->translate_mysql_having_alias_predicate_to_postgresql(
			$tokens,
			$having_position + 1,
			$having_end,
			$alias_expressions
		);
		if ( null === $having_sql ) {
			return null;
		}

		$replacements   = array();
		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, $from_position + 1, $group_position );
		if ( null !== $where_position ) {
			$scope_end = $where_position;
		} else {
			$scope_end = $group_position;
		}

		$scope = $this->get_mysql_select_scope( $tokens, $from_position + 1, $scope_end );
		if ( null === $scope ) {
			return null;
		}

		if ( null !== $where_position ) {
			$where_sql = $this->translate_mysql_predicate_token_sequence_to_postgresql(
				$tokens,
				$where_position + 1,
				$group_position,
				$scope
			);
			if ( $where_sql['changed'] ) {
				$replacements[] = array(
					'start' => $where_position + 1,
					'end'   => $group_position,
					'sql'   => $where_sql['sql'],
				);
			}
		}

		$group_by_extensions = $this->get_mysql_grouped_having_group_by_projection_extensions(
			$tokens,
			1,
			$from_position,
			$group_position,
			$having_position,
			$group_items
		);
		if ( null === $group_by_extensions ) {
			return null;
		}

		if ( ! empty( $group_by_extensions ) ) {
			$replacements[] = array(
				'start' => $group_position + 2,
				'end'   => $having_position,
				'sql'   => $this->translate_mysql_token_sequence_to_postgresql( $tokens, $group_position + 2, $having_position )
					. ', ' . implode( ', ', $group_by_extensions ),
			);
		}

		$replacements[] = array(
			'start' => $having_position + 1,
			'end'   => $having_end,
			'sql'   => $having_sql,
		);

		return 'SELECT ' . $this->translate_mysql_token_sequence_with_replacements_to_postgresql(
			$tokens,
			1,
			$statement_end,
			$replacements
		);
	}

	/**
	 * Get projection aliases that can be substituted safely in grouped HAVING.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param int             $start       First projection token position.
	 * @param int             $end         Final projection token position, exclusive.
	 * @param array           $group_items Parsed GROUP BY items.
	 * @return array<string, array{sql: string}>|null Alias expressions keyed by lowercase alias.
	 */
	private function get_mysql_grouped_having_projection_alias_expressions( array $tokens, int $start, int $end, array $group_items ): ?array {
		$ranges = $this->split_top_level_mysql_arguments( $tokens, $start, $end );
		if ( null === $ranges || count( $ranges ) < 1 ) {
			return null;
		}

		$aliases = array();
		foreach ( $ranges as $range ) {
			$item = $this->parse_mysql_aliased_projection_expression( $tokens, $range['start'], $range['end'] );
			if ( null === $item ) {
				continue;
			}

			$alias_key = strtolower( $item['alias'] );
			if ( isset( $aliases[ $alias_key ] ) ) {
				return null;
			}

			if (
				! $this->contains_mysql_aggregate_call( $tokens, $item['expression_start'], $item['expression_end'] )
				&& ! $this->is_mysql_grouped_projection_expression( $tokens, $item, $group_items )
			) {
				continue;
			}

			$aliases[ $alias_key ] = array(
				'sql' => $this->translate_mysql_token_sequence_to_postgresql(
					$tokens,
					$item['expression_start'],
					$item['expression_end']
				),
			);
		}

		return $aliases;
	}

	/**
	 * Get GROUP BY extensions for selected columns equivalent to grouped columns.
	 *
	 * @param WP_MySQL_Token[] $tokens         MySQL lexer token stream.
	 * @param int             $projection_start First projection token position.
	 * @param int             $from_position  FROM token position.
	 * @param int             $group_position GROUP token position.
	 * @param int             $having_position HAVING token position.
	 * @param array           $group_items    Parsed GROUP BY items.
	 * @return string[]|null PostgreSQL GROUP BY expressions to append, or null when unsupported.
	 */
	private function get_mysql_grouped_having_group_by_projection_extensions(
		array $tokens,
		int $projection_start,
		int $from_position,
		int $group_position,
		int $having_position,
		array $group_items
	): ?array {
		$projection_items = $this->split_top_level_mysql_arguments( $tokens, $projection_start, $from_position );
		if ( null === $projection_items ) {
			return null;
		}

		$grouped_columns = array();
		foreach ( $group_items as $group_item ) {
			$grouped_column = $this->get_mysql_simple_qualified_column_expression(
				$tokens,
				$group_item['start'],
				$group_item['end']
			);
			if ( null !== $grouped_column ) {
				$grouped_columns[] = $grouped_column;
			}
		}

		if ( empty( $grouped_columns ) ) {
			return array();
		}

		$extensions         = array();
		$extension_keys     = array();
		$equivalent_columns = null;
		foreach ( $projection_items as $projection_item ) {
			$bounds = $this->get_mysql_projection_expression_bounds( $tokens, $projection_item['start'], $projection_item['end'] );
			if ( null === $bounds ) {
				continue;
			}

			$projection_column = $this->get_mysql_simple_qualified_column_expression( $tokens, $bounds['start'], $bounds['end'] );
			if ( null === $projection_column ) {
				continue;
			}

			if ( $this->is_mysql_projection_column_grouped( $projection_column, $grouped_columns ) ) {
				continue;
			}

			if ( null === $equivalent_columns ) {
				$equivalent_columns = $this->get_mysql_safe_grouped_having_column_equality_pairs(
					$tokens,
					$from_position,
					$group_position
				);
				if ( null === $equivalent_columns || empty( $equivalent_columns ) ) {
					return null;
				}
			}

			$extended = false;
			foreach ( $grouped_columns as $grouped_column ) {
				if ( ! $this->are_mysql_simple_columns_equivalent( $projection_column, $grouped_column, $equivalent_columns ) ) {
					continue;
				}

				$extension_key = $projection_column['key'];
				if ( isset( $extension_keys[ $extension_key ] ) ) {
					$extended = true;
					break;
				}

				$extensions[]                     = $projection_column['sql'];
				$extension_keys[ $extension_key ] = true;
				$extended                         = true;
				break;
			}

			if ( ! $extended ) {
				return null;
			}
		}

		return $extensions;
	}

	/**
	 * Get expression bounds for a SELECT projection item.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection item token position.
	 * @param int             $end    Final projection item token position, exclusive.
	 * @return array{start: int, end: int}|null Expression bounds, or null when malformed.
	 */
	private function get_mysql_projection_expression_bounds( array $tokens, int $start, int $end ): ?array {
		if ( $start >= $end ) {
			return null;
		}

		$expression_end = $end;
		$as_position    = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::AS_SYMBOL, $start, $end );
		if ( null !== $as_position ) {
			if ( $as_position <= $start || $as_position + 2 !== $end ) {
				return null;
			}

			$expression_end = $as_position;
		} elseif ( null !== $this->get_mysql_implicit_projection_alias( $tokens, $start, $end ) ) {
			$expression_end = $end - 1;
		}

		return $start >= $expression_end
			? null
			: array(
				'start' => $start,
				'end'   => $expression_end,
			);
	}

	/**
	 * Parse a simple qualified column expression.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token position.
	 * @param int             $end    Final expression token position, exclusive.
	 * @return array{qualifier: string, column: string, key: string, sql: string}|null Column data, or null when unsupported.
	 */
	private function get_mysql_simple_qualified_column_expression( array $tokens, int $start, int $end ): ?array {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		return $this->get_mysql_unwrapped_simple_qualified_column_expression( $tokens, $bounds['start'], $bounds['end'] );
	}

	/**
	 * Parse a simple qualified column expression without removing wrapper parentheses.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token position.
	 * @param int             $end    Final expression token position, exclusive.
	 * @return array{qualifier: string, column: string, key: string, sql: string}|null Column data, or null when unsupported.
	 */
	private function get_mysql_unwrapped_simple_qualified_column_expression( array $tokens, int $start, int $end ): ?array {
		if (
			$start + 3 !== $end
			|| ! isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ] )
			|| WP_MySQL_Lexer::DOT_SYMBOL !== $tokens[ $start + 1 ]->id
		) {
			return null;
		}

		$qualifier = $this->get_mysql_identifier_token_value( $tokens[ $start ] );
		$column    = $this->get_mysql_identifier_token_value( $tokens[ $start + 2 ] );
		if ( null === $qualifier || null === $column ) {
			return null;
		}

		$key = strtolower( $qualifier ) . '.' . strtolower( $column );
		return array(
			'qualifier' => strtolower( $qualifier ),
			'column'    => strtolower( $column ),
			'key'       => $key,
			'sql'       => $this->translate_mysql_token_sequence_to_postgresql( $tokens, $start, $end ),
		);
	}

	/**
	 * Get safe qualified column equality pairs for grouped HAVING rewrites.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $from_position  FROM token position.
	 * @param int             $group_position GROUP token position.
	 * @return array<string, array<string, true>>|null Column equality adjacency map, or null when unsupported.
	 */
	private function get_mysql_safe_grouped_having_column_equality_pairs( array $tokens, int $from_position, int $group_position ): ?array {
		$where_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::WHERE_SYMBOL, $from_position + 1, $group_position );
		$from_end       = $where_position ?? $group_position;

		$pairs = $this->get_mysql_inner_join_column_equality_pairs( $tokens, $from_position + 1, $from_end );
		if ( null === $pairs ) {
			return null === $where_position
				? $this->get_mysql_wordpress_term_split_left_join_column_equality_pairs( $tokens, $from_position + 1, $from_end )
				: null;
		}

		if ( null === $where_position ) {
			return $pairs;
		}

		$where_pairs = $this->get_mysql_top_level_conjunct_column_equality_pairs( $tokens, $where_position + 1, $group_position );
		if ( null === $where_pairs ) {
			return null;
		}

		$this->merge_mysql_column_equality_pairs( $pairs, $where_pairs );
		return $pairs;
	}

	/**
	 * Get qualified column equality pairs from supported inner JOIN predicates.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First FROM-clause token position.
	 * @param int             $end    Final FROM-clause token position, exclusive.
	 * @return array<string, array<string, true>>|null Column equality adjacency map, or null when unsupported.
	 */
	private function get_mysql_inner_join_column_equality_pairs( array $tokens, int $start, int $end ): ?array {
		$pairs = array();

		for ( $position = $start; $position < $end; $position++ ) {
			$token_id = $tokens[ $position ]->id;
			if (
				WP_MySQL_Lexer::LEFT_SYMBOL === $token_id
				|| WP_MySQL_Lexer::NATURAL_SYMBOL === $token_id
				|| WP_MySQL_Lexer::OUTER_SYMBOL === $token_id
				|| WP_MySQL_Lexer::RIGHT_SYMBOL === $token_id
				|| WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL === $token_id
				|| WP_MySQL_Lexer::USING_SYMBOL === $token_id
			) {
				return null;
			}

			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $token_id ) {
				return null;
			}

			if ( WP_MySQL_Lexer::ON_SYMBOL !== $token_id ) {
				continue;
			}

			$predicate_end = $this->find_mysql_join_predicate_end( $tokens, $position + 1, $end );
			$join_pairs    = $this->get_mysql_top_level_conjunct_column_equality_pairs( $tokens, $position + 1, $predicate_end );
			if ( null === $join_pairs ) {
				return null;
			}

			$this->merge_mysql_column_equality_pairs( $pairs, $join_pairs );
			$position = $predicate_end - 1;
		}

		return $pairs;
	}

	/**
	 * Get equality pairs for WordPress core's legacy shared-term split query.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First FROM-clause token position.
	 * @param int             $end    Final FROM-clause token position, exclusive.
	 * @return array<string, array<string, true>>|null Column equality adjacency map, or null when unsupported.
	 */
	private function get_mysql_wordpress_term_split_left_join_column_equality_pairs( array $tokens, int $start, int $end ): ?array {
		$term_taxonomy_reference = $this->parse_mysql_table_reference( $tokens, $start, $end );
		if (
			null === $term_taxonomy_reference
			|| ! $this->is_mysql_wordpress_table_reference( $term_taxonomy_reference, 'term_taxonomy', 'tt' )
		) {
			return null;
		}

		$position = $term_taxonomy_reference['position'];
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::LEFT_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		++$position;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::OUTER_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::JOIN_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		$terms_reference = $this->parse_mysql_table_reference( $tokens, $position + 1, $end );
		if (
			null === $terms_reference
			|| ! $this->is_mysql_wordpress_table_reference( $terms_reference, 'terms', 't' )
		) {
			return null;
		}

		$position = $terms_reference['position'];
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::ON_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		$predicate_end = $this->find_mysql_join_predicate_end( $tokens, $position + 1, $end );
		if ( $predicate_end !== $end ) {
			return null;
		}

		$pair = $this->get_mysql_top_level_simple_column_equality_pair( $tokens, $position + 1, $predicate_end );
		if ( null === $pair || ! $this->is_mysql_wordpress_term_split_column_equality_pair( $pair ) ) {
			return null;
		}

		return array(
			't.term_id'  => array(
				'tt.term_id' => true,
			),
			'tt.term_id' => array(
				't.term_id' => true,
			),
		);
	}

	/**
	 * Check whether a table reference matches a WordPress core table and alias.
	 *
	 * @param array  $reference Parsed table reference.
	 * @param string $table_base Expected unprefixed table name.
	 * @param string $alias      Expected alias.
	 * @return bool Whether the reference matches.
	 */
	private function is_mysql_wordpress_table_reference( array $reference, string $table_base, string $alias ): bool {
		$reference_alias = strtolower( null === $reference['alias'] ? $reference['table'] : $reference['alias'] );
		if ( $alias !== $reference_alias ) {
			return false;
		}

		return $this->is_mysql_wordpress_table_name( $reference['table'], $table_base );
	}

	/**
	 * Check whether a table name matches a WordPress core table base name.
	 *
	 * @param string $table_name Table name.
	 * @param string $table_base Expected unprefixed table name.
	 * @return bool Whether the table name matches.
	 */
	private function is_mysql_wordpress_table_name( string $table_name, string $table_base ): bool {
		$table_name = strtolower( $table_name );
		$table_base = strtolower( $table_base );
		return $table_base === $table_name
			|| substr( $table_name, -strlen( '_' . $table_base ) ) === '_' . $table_base;
	}

	/**
	 * Check whether an equality pair is t.term_id = tt.term_id.
	 *
	 * @param array $pair Parsed equality pair.
	 * @return bool Whether this is the WordPress shared-term split equality.
	 */
	private function is_mysql_wordpress_term_split_column_equality_pair( array $pair ): bool {
		return (
			't.term_id' === $pair['left']['key']
			&& 'tt.term_id' === $pair['right']['key']
		) || (
			'tt.term_id' === $pair['left']['key']
			&& 't.term_id' === $pair['right']['key']
		);
	}

	/**
	 * Find the end of a JOIN ON predicate.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First ON predicate token position.
	 * @param int             $end    Final FROM-clause token position, exclusive.
	 * @return int Final ON predicate token position, exclusive.
	 */
	private function find_mysql_join_predicate_end( array $tokens, int $start, int $end ): int {
		$depth = 0;
		for ( $position = $start; $position < $end; $position++ ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
				++$depth;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $position ]->id ) {
				--$depth;
				continue;
			}

			if (
				0 === $depth
				&& (
					WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id
					|| WP_MySQL_Lexer::INNER_SYMBOL === $tokens[ $position ]->id
					|| WP_MySQL_Lexer::JOIN_SYMBOL === $tokens[ $position ]->id
					|| WP_MySQL_Lexer::LEFT_SYMBOL === $tokens[ $position ]->id
					|| WP_MySQL_Lexer::NATURAL_SYMBOL === $tokens[ $position ]->id
					|| WP_MySQL_Lexer::RIGHT_SYMBOL === $tokens[ $position ]->id
					|| WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL === $tokens[ $position ]->id
				)
			) {
				return $position;
			}
		}

		return $end;
	}

	/**
	 * Get column equality pairs from a top-level AND predicate.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First predicate token position.
	 * @param int             $end    Final predicate token position, exclusive.
	 * @return array<string, array<string, true>>|null Column equality adjacency map, or null when unsupported.
	 */
	private function get_mysql_top_level_conjunct_column_equality_pairs( array $tokens, int $start, int $end ): ?array {
		$conjuncts = $this->split_mysql_top_level_boolean_conjuncts( $tokens, $start, $end );
		if ( null === $conjuncts ) {
			return null;
		}

		$pairs = array();
		foreach ( $conjuncts as $conjunct ) {
			$pair = $this->get_mysql_top_level_simple_column_equality_pair(
				$tokens,
				$conjunct['start'],
				$conjunct['end']
			);
			if ( null === $pair ) {
				continue;
			}

			$pairs[ $pair['left']['key'] ][ $pair['right']['key'] ] = true;
			$pairs[ $pair['right']['key'] ][ $pair['left']['key'] ] = true;
		}

		return $pairs;
	}

	/**
	 * Split a boolean predicate into top-level AND conjuncts.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First predicate token position.
	 * @param int             $end    Final predicate token position, exclusive.
	 * @return array<int, array{start: int, end: int}>|null Conjunct bounds, or null when unsupported.
	 */
	private function split_mysql_top_level_boolean_conjuncts( array $tokens, int $start, int $end ): ?array {
		if ( $start >= $end ) {
			return null;
		}

		$conjuncts      = array();
		$conjunct_start = $start;
		$depth          = 0;

		for ( $position = $start; $position < $end; $position++ ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
				++$depth;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $position ]->id ) {
				--$depth;
				if ( $depth < 0 ) {
					return null;
				}
				continue;
			}

			if ( 0 !== $depth ) {
				continue;
			}

			if ( WP_MySQL_Lexer::OR_SYMBOL === $tokens[ $position ]->id || WP_MySQL_Lexer::XOR_SYMBOL === $tokens[ $position ]->id ) {
				return null;
			}

			if ( WP_MySQL_Lexer::AND_SYMBOL !== $tokens[ $position ]->id ) {
				continue;
			}

			if ( $conjunct_start === $position ) {
				return null;
			}

			$conjuncts[]    = array(
				'start' => $conjunct_start,
				'end'   => $position,
			);
			$conjunct_start = $position + 1;
		}

		if ( 0 !== $depth || $conjunct_start >= $end ) {
			return null;
		}

		$conjuncts[] = array(
			'start' => $conjunct_start,
			'end'   => $end,
		);

		return $conjuncts;
	}

	/**
	 * Parse a top-level simple qualified-column equality predicate.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First predicate token position.
	 * @param int             $end    Final predicate token position, exclusive.
	 * @return array{left: array, right: array}|null Equality pair, or null when unsupported.
	 */
	private function get_mysql_top_level_simple_column_equality_pair( array $tokens, int $start, int $end ): ?array {
		$equal_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::EQUAL_OPERATOR, $start, $end );
		if (
			null === $equal_position
			|| null !== $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::EQUAL_OPERATOR, $equal_position + 1, $end )
		) {
			return null;
		}

		$left_column  = $this->get_mysql_unwrapped_simple_qualified_column_expression( $tokens, $start, $equal_position );
		$right_column = $this->get_mysql_unwrapped_simple_qualified_column_expression( $tokens, $equal_position + 1, $end );
		if ( null === $left_column || null === $right_column ) {
			return null;
		}

		return array(
			'left'  => $left_column,
			'right' => $right_column,
		);
	}

	/**
	 * Merge column equality adjacency maps.
	 *
	 * @param array $target Target adjacency map.
	 * @param array $source Source adjacency map.
	 */
	private function merge_mysql_column_equality_pairs( array &$target, array $source ): void {
		foreach ( $source as $left_key => $right_columns ) {
			foreach ( $right_columns as $right_key => $_ ) {
				$target[ $left_key ][ $right_key ] = true;
			}
		}
	}

	/**
	 * Check whether a selected column is already grouped.
	 *
	 * @param array $projection_column Selected column data.
	 * @param array $grouped_columns   Grouped column data.
	 * @return bool Whether the selected column is grouped.
	 */
	private function is_mysql_projection_column_grouped( array $projection_column, array $grouped_columns ): bool {
		foreach ( $grouped_columns as $grouped_column ) {
			if ( $projection_column['key'] === $grouped_column['key'] ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Check whether two simple columns are connected by a parsed equality.
	 *
	 * @param array $left_column        Left column data.
	 * @param array $right_column       Right column data.
	 * @param array $equivalent_columns Column equality adjacency map.
	 * @return bool Whether the columns are equivalent.
	 */
	private function are_mysql_simple_columns_equivalent( array $left_column, array $right_column, array $equivalent_columns ): bool {
		return $left_column['key'] === $right_column['key']
			|| isset( $equivalent_columns[ $left_column['key'] ][ $right_column['key'] ] );
	}

	/**
	 * Parse a projection item that has an explicit or implicit alias.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection item token position.
	 * @param int             $end    Final projection item token position, exclusive.
	 * @return array{expression_start: int, expression_end: int, alias: string}|null Parsed alias expression, or null when absent.
	 */
	private function parse_mysql_aliased_projection_expression( array $tokens, int $start, int $end ): ?array {
		if ( $start >= $end ) {
			return null;
		}

		$expression_end = $end;
		$alias          = null;
		$as_position    = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::AS_SYMBOL, $start, $end );

		if ( null !== $as_position ) {
			if ( $as_position <= $start || $as_position + 2 !== $end ) {
				return null;
			}

			$alias = $this->get_mysql_projection_alias_token_value( $tokens[ $as_position + 1 ] ?? null );
			if ( null === $alias ) {
				return null;
			}

			$expression_end = $as_position;
		} else {
			$alias = $this->get_mysql_implicit_projection_alias( $tokens, $start, $end );
			if ( null === $alias ) {
				return null;
			}

			$expression_end = $end - 1;
		}

		if ( $start >= $expression_end ) {
			return null;
		}

		return array(
			'expression_start' => $start,
			'expression_end'   => $expression_end,
			'alias'            => $alias,
		);
	}

	/**
	 * Check whether a projection expression is already present in GROUP BY.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param array           $item        Parsed projection item.
	 * @param array           $group_items Parsed GROUP BY items.
	 * @return bool Whether the projection expression is grouped.
	 */
	private function is_mysql_grouped_projection_expression( array $tokens, array $item, array $group_items ): bool {
		foreach ( $group_items as $group_item ) {
			if (
				$this->are_mysql_token_ranges_equivalent(
					$tokens,
					$item['expression_start'],
					$item['expression_end'],
					$group_item['start'],
					$group_item['end']
				)
			) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Check whether a token range contains a MySQL aggregate function call.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token position.
	 * @param int             $end    Final expression token position, exclusive.
	 * @return bool Whether an aggregate call is present.
	 */
	private function contains_mysql_aggregate_call( array $tokens, int $start, int $end ): bool {
		$aggregate_token_ids = array(
			WP_MySQL_Lexer::AVG_SYMBOL,
			WP_MySQL_Lexer::BIT_AND_SYMBOL,
			WP_MySQL_Lexer::BIT_OR_SYMBOL,
			WP_MySQL_Lexer::BIT_XOR_SYMBOL,
			WP_MySQL_Lexer::COUNT_SYMBOL,
			WP_MySQL_Lexer::GROUP_CONCAT_SYMBOL,
			WP_MySQL_Lexer::MAX_SYMBOL,
			WP_MySQL_Lexer::MIN_SYMBOL,
			WP_MySQL_Lexer::STD_SYMBOL,
			WP_MySQL_Lexer::STDDEV_POP_SYMBOL,
			WP_MySQL_Lexer::STDDEV_SAMP_SYMBOL,
			WP_MySQL_Lexer::STDDEV_SYMBOL,
			WP_MySQL_Lexer::SUM_SYMBOL,
			WP_MySQL_Lexer::VAR_POP_SYMBOL,
			WP_MySQL_Lexer::VAR_SAMP_SYMBOL,
			WP_MySQL_Lexer::VARIANCE_SYMBOL,
		);

		for ( $position = $start; $position < $end; $position++ ) {
			if (
				isset( $tokens[ $position ], $tokens[ $position + 1 ] )
				&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id
				&& WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[ $position + 1 ]->id
			) {
				$after_subquery = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
				if ( null !== $after_subquery ) {
					$position = $after_subquery - 1;
					continue;
				}
			}

			if (
				isset( $tokens[ $position + 1 ] )
				&& in_array( $tokens[ $position ]->id, $aggregate_token_ids, true )
				&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position + 1 ]->id
			) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Translate HAVING predicate aliases to their projection expressions.
	 *
	 * @param WP_MySQL_Token[] $tokens            MySQL lexer token stream.
	 * @param int             $start             First HAVING predicate token.
	 * @param int             $end               Final HAVING predicate token, exclusive.
	 * @param array           $alias_expressions Projection alias SQL keyed by lowercase alias.
	 * @return string|null Translated HAVING SQL, or null when no alias was changed.
	 */
	private function translate_mysql_having_alias_predicate_to_postgresql( array $tokens, int $start, int $end, array $alias_expressions ): ?string {
		$chunks        = array();
		$segment_start = $start;
		$changed       = false;

		for ( $position = $start; $position < $end; $position++ ) {
			if (
				isset( $tokens[ $position ], $tokens[ $position + 1 ] )
				&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id
				&& WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[ $position + 1 ]->id
			) {
				$after_subquery = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
				if ( null !== $after_subquery ) {
					$position = $after_subquery - 1;
					continue;
				}
			}

			$alias = $this->get_mysql_order_by_alias_token_value( $tokens[ $position ] ?? null );
			if (
				null === $alias
				|| ! $this->is_unqualified_mysql_having_alias_reference( $tokens, $position, $end )
				|| ! isset( $alias_expressions[ strtolower( $alias ) ] )
			) {
				continue;
			}

			if ( $segment_start < $position ) {
				$chunks[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $segment_start, $position );
			}

			$chunks[]      = '(' . $alias_expressions[ strtolower( $alias ) ]['sql'] . ')';
			$segment_start = $position + 1;
			$changed       = true;
		}

		if ( ! $changed ) {
			return null;
		}

		if ( $segment_start < $end ) {
			$chunks[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $segment_start, $end );
		}

		return implode( ' ', array_filter( $chunks, 'strlen' ) );
	}

	/**
	 * Check whether a HAVING token is an unqualified alias reference.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate alias token position.
	 * @param int             $end      Final HAVING predicate token, exclusive.
	 * @return bool Whether the token can be replaced as an alias.
	 */
	private function is_unqualified_mysql_having_alias_reference( array $tokens, int $position, int $end ): bool {
		if ( isset( $tokens[ $position - 1 ] ) && WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position - 1 ]->id ) {
			return false;
		}

		if (
			isset( $tokens[ $position + 1 ] )
			&& (
				WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position + 1 ]->id
				|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position + 1 ]->id
			)
		) {
			return false;
		}

		return $position < $end;
	}

	/**
	 * Get projection replacements needed by grouped archive queries.
	 *
	 * @param WP_MySQL_Token[] $tokens                  MySQL lexer token stream.
	 * @param array           $projection_items        Parsed projection items.
	 * @param array           $archive_date_expression Shared date expression bounds.
	 * @return array<int, array{start: int, end: int, sql: string}> Replacement ranges.
	 */
	private function get_mysql_archive_grouped_projection_replacements( array $tokens, array $projection_items, array $archive_date_expression ): array {
		$replacements = array();

		foreach ( $projection_items as $projection_item ) {
			$bounds = $this->get_mysql_date_format_bounds(
				$tokens,
				$projection_item['expression_start'],
				$projection_item['expression_end']
			);
			if (
				null === $bounds
				|| '%Y-%m-%d' !== $bounds['format']
				|| $bounds['close'] + 1 !== $projection_item['expression_end']
				|| ! $this->are_mysql_token_ranges_equivalent(
					$tokens,
					$archive_date_expression['start'],
					$archive_date_expression['end'],
					$bounds['expression_start'],
					$bounds['expression_end']
				)
			) {
				continue;
			}

			$expression_sql = $this->translate_mysql_token_sequence_to_postgresql(
				$tokens,
				$bounds['expression_start'],
				$bounds['expression_end']
			);
			$sql            = $this->get_postgresql_mysql_date_format_sql(
				$bounds['format'],
				sprintf( 'MAX(%s)', $expression_sql )
			);
			if ( null === $sql ) {
				continue;
			}

			$replacements[] = array(
				'start' => $projection_item['expression_start'],
				'end'   => $projection_item['expression_end'],
				'sql'   => $sql,
			);
		}

		return $replacements;
	}

	/**
	 * Check whether DISTINCT is redundant for the supported weekly archive shape.
	 *
	 * @param WP_MySQL_Token[] $tokens                  MySQL lexer token stream.
	 * @param array           $projection_items        Parsed projection items.
	 * @param array           $group_items             Parsed GROUP BY item ranges.
	 * @param array           $archive_date_expression Shared date expression bounds.
	 * @return bool Whether this is the supported weekly archive projection.
	 */
	private function is_mysql_redundant_distinct_week_archive_select_shape(
		array $tokens,
		array $projection_items,
		array $group_items,
		array $archive_date_expression
	): bool {
		if ( 4 !== count( $projection_items ) || 2 !== count( $group_items ) ) {
			return false;
		}

		$expected_aliases = array( 'week', 'yr', 'yyyymmdd', 'posts' );
		foreach ( $expected_aliases as $index => $alias ) {
			if ( strtolower( $projection_items[ $index ]['alias'] ) !== $alias ) {
				return false;
			}
		}

		return $this->is_mysql_week_expression_for_archive_date(
			$tokens,
			$projection_items[0]['expression_start'],
			$projection_items[0]['expression_end'],
			$archive_date_expression
		)
			&& $this->is_mysql_year_expression_for_archive_date(
				$tokens,
				$projection_items[1]['expression_start'],
				$projection_items[1]['expression_end'],
				$archive_date_expression
			)
			&& $this->is_mysql_year_month_day_format_expression_for_archive_date(
				$tokens,
				$projection_items[2]['expression_start'],
				$projection_items[2]['expression_end'],
				$archive_date_expression
			)
			&& $this->is_mysql_count_aggregate_expression(
				$tokens,
				$projection_items[3]['expression_start'],
				$projection_items[3]['expression_end']
			)
			&& $this->do_mysql_group_items_include_week_and_year_for_archive_date(
				$tokens,
				$group_items,
				$archive_date_expression
			);
	}

	/**
	 * Check whether an expression is WEEK(archive_date, 1).
	 *
	 * @param WP_MySQL_Token[] $tokens                  MySQL lexer token stream.
	 * @param int             $start                   First expression token.
	 * @param int             $end                     Final expression token, exclusive.
	 * @param array           $archive_date_expression Shared date expression bounds.
	 * @return bool Whether the expression matches the archive week.
	 */
	private function is_mysql_week_expression_for_archive_date( array $tokens, int $start, int $end, array $archive_date_expression ): bool {
		$expression = $this->get_mysql_week_argument_expression_bounds( $tokens, $start, $end );

		return null !== $expression
			&& $this->are_mysql_token_ranges_equivalent(
				$tokens,
				$archive_date_expression['start'],
				$archive_date_expression['end'],
				$expression['start'],
				$expression['end']
			);
	}

	/**
	 * Check whether an expression is YEAR(archive_date).
	 *
	 * @param WP_MySQL_Token[] $tokens                  MySQL lexer token stream.
	 * @param int             $start                   First expression token.
	 * @param int             $end                     Final expression token, exclusive.
	 * @param array           $archive_date_expression Shared date expression bounds.
	 * @return bool Whether the expression matches the archive year.
	 */
	private function is_mysql_year_expression_for_archive_date( array $tokens, int $start, int $end, array $archive_date_expression ): bool {
		$expression = $this->get_mysql_extract_argument_expression_bounds( $tokens, $start, $end, 'YEAR' );

		return null !== $expression
			&& $this->are_mysql_token_ranges_equivalent(
				$tokens,
				$archive_date_expression['start'],
				$archive_date_expression['end'],
				$expression['start'],
				$expression['end']
			);
	}

	/**
	 * Check whether an expression is DATE_FORMAT(archive_date, '%Y-%m-%d').
	 *
	 * @param WP_MySQL_Token[] $tokens                  MySQL lexer token stream.
	 * @param int             $start                   First expression token.
	 * @param int             $end                     Final expression token, exclusive.
	 * @param array           $archive_date_expression Shared date expression bounds.
	 * @return bool Whether the expression matches the archive date format.
	 */
	private function is_mysql_year_month_day_format_expression_for_archive_date( array $tokens, int $start, int $end, array $archive_date_expression ): bool {
		$bounds = $this->get_mysql_date_format_bounds( $tokens, $start, $end );

		return null !== $bounds
			&& '%Y-%m-%d' === $bounds['format']
			&& $bounds['close'] + 1 === $end
			&& $this->are_mysql_token_ranges_equivalent(
				$tokens,
				$archive_date_expression['start'],
				$archive_date_expression['end'],
				$bounds['expression_start'],
				$bounds['expression_end']
			);
	}

	/**
	 * Check whether GROUP BY contains WEEK(archive_date, 1) and YEAR(archive_date).
	 *
	 * @param WP_MySQL_Token[] $tokens                  MySQL lexer token stream.
	 * @param array           $group_items             Parsed GROUP BY item ranges.
	 * @param array           $archive_date_expression Shared date expression bounds.
	 * @return bool Whether both grouped date keys are present.
	 */
	private function do_mysql_group_items_include_week_and_year_for_archive_date( array $tokens, array $group_items, array $archive_date_expression ): bool {
		$has_week = false;
		$has_year = false;

		foreach ( $group_items as $group_item ) {
			$has_week = $has_week || $this->is_mysql_week_expression_for_archive_date(
				$tokens,
				$group_item['start'],
				$group_item['end'],
				$archive_date_expression
			);
			$has_year = $has_year || $this->is_mysql_year_expression_for_archive_date(
				$tokens,
				$group_item['start'],
				$group_item['end'],
				$archive_date_expression
			);
		}

		return $has_week && $has_year;
	}

	/**
	 * Check whether a projection is exactly one COUNT aggregate.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection token position.
	 * @param int             $end    Final projection token position, exclusive.
	 * @return bool Whether the projection is COUNT-only.
	 */
	private function is_mysql_count_only_projection( array $tokens, int $start, int $end ): bool {
		$ranges = $this->split_top_level_mysql_arguments( $tokens, $start, $end );
		if ( null === $ranges || 1 !== count( $ranges ) ) {
			return false;
		}

		$expression_bounds = $this->get_mysql_select_projection_expression_bounds(
			$tokens,
			$ranges[0]['start'],
			$ranges[0]['end']
		);
		if ( null === $expression_bounds ) {
			return false;
		}

		return $this->is_mysql_count_aggregate_expression(
			$tokens,
			$expression_bounds['start'],
			$expression_bounds['end']
		);
	}

	/**
	 * Get expression bounds for a projection item, excluding any alias.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection item token position.
	 * @param int             $end    Final projection item token position, exclusive.
	 * @return array{start: int, end: int}|null Expression bounds, or null when malformed.
	 */
	private function get_mysql_select_projection_expression_bounds( array $tokens, int $start, int $end ): ?array {
		if ( $start >= $end ) {
			return null;
		}

		$expression_end = $end;
		$as_position    = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::AS_SYMBOL, $start, $end );
		if ( null !== $as_position ) {
			if (
				$as_position <= $start
				|| $as_position + 2 !== $end
				|| null === $this->get_mysql_projection_alias_token_value( $tokens[ $as_position + 1 ] ?? null )
			) {
				return null;
			}

			$expression_end = $as_position;
		} else {
			$implicit_alias = $this->get_mysql_implicit_projection_alias( $tokens, $start, $end );
			if ( null !== $implicit_alias ) {
				$expression_end = $end - 1;
			}
		}

		if ( $start >= $expression_end ) {
			return null;
		}

		return array(
			'start' => $start,
			'end'   => $expression_end,
		);
	}

	/**
	 * Check whether an expression is a COUNT aggregate call.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token.
	 * @param int             $end    Final expression token, exclusive.
	 * @return bool Whether the expression is COUNT(...).
	 */
	private function is_mysql_count_aggregate_expression( array $tokens, int $start, int $end ): bool {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start  = $bounds['start'];
		$end    = $bounds['end'];

		return isset( $tokens[ $start ], $tokens[ $start + 1 ] )
			&& $this->is_mysql_token_value( $tokens[ $start ], 'count' )
			&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $start + 1 ]->id
			&& $this->get_mysql_parenthesized_sequence_end( $tokens, $start + 1, $end ) === $end;
	}

	/**
	 * Get the shared post_date expression from archive date grouping.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param array           $group_items Parsed GROUP BY item ranges.
	 * @return array{start: int, end: int}|null Shared post_date expression bounds, or null.
	 */
	private function get_mysql_archive_grouped_date_expression_bounds( array $tokens, array $group_items ): ?array {
		$group_count = count( $group_items );
		if ( 1 > $group_count || 3 < $group_count ) {
			return null;
		}

		$year_expression       = null;
		$week_expression       = null;
		$month_expression      = null;
		$dayofmonth_expression = null;
		$supported_expressions = 0;
		foreach ( $group_items as $group_item ) {
			$expression = $this->get_mysql_extract_argument_expression_bounds(
				$tokens,
				$group_item['start'],
				$group_item['end'],
				'YEAR'
			);
			if ( null !== $expression ) {
				$year_expression = $expression;
				++$supported_expressions;
				continue;
			}

			$expression = $this->get_mysql_week_argument_expression_bounds(
				$tokens,
				$group_item['start'],
				$group_item['end']
			);
			if ( null !== $expression ) {
				$week_expression = $expression;
				++$supported_expressions;
				continue;
			}

			$expression = $this->get_mysql_extract_argument_expression_bounds(
				$tokens,
				$group_item['start'],
				$group_item['end'],
				'MONTH'
			);
			if ( null !== $expression ) {
				$month_expression = $expression;
				++$supported_expressions;
				continue;
			}

			$expression = $this->get_mysql_extract_argument_expression_bounds(
				$tokens,
				$group_item['start'],
				$group_item['end'],
				'DAY'
			);
			if ( null !== $expression ) {
				$dayofmonth_expression = $expression;
				++$supported_expressions;
			}
		}

		if (
			$group_count !== $supported_expressions
			|| null === $year_expression
		) {
			return null;
		}

		if ( null !== $week_expression ) {
			if (
				2 !== $group_count
				|| null !== $month_expression
				|| null !== $dayofmonth_expression
				|| ! $this->are_mysql_token_ranges_equivalent(
					$tokens,
					$year_expression['start'],
					$year_expression['end'],
					$week_expression['start'],
					$week_expression['end']
				)
			) {
				return null;
			}
		} elseif (
			(
				2 <= $group_count
				&& null === $month_expression
			)
			|| (
				3 === $group_count
				&& null === $dayofmonth_expression
			)
			|| (
				null !== $month_expression
				&& ! $this->are_mysql_token_ranges_equivalent(
					$tokens,
					$year_expression['start'],
					$year_expression['end'],
					$month_expression['start'],
					$month_expression['end']
				)
			)
			|| (
				null !== $dayofmonth_expression
				&& ! $this->are_mysql_token_ranges_equivalent(
					$tokens,
					$year_expression['start'],
					$year_expression['end'],
					$dayofmonth_expression['start'],
					$dayofmonth_expression['end']
				)
			)
		) {
			return null;
		}

		if (
			! $this->is_mysql_column_reference_expression(
				$tokens,
				$year_expression['start'],
				$year_expression['end'],
				'post_date',
				'posts',
				true
			)
		) {
			return null;
		}

		return $year_expression;
	}

	/**
	 * Get the argument expression for a supported date/time extract function.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token.
	 * @param int             $end    Final expression token, exclusive.
	 * @param string          $unit   Expected date/time unit.
	 * @return array{start: int, end: int}|null Argument bounds, or null.
	 */
	private function get_mysql_extract_argument_expression_bounds( array $tokens, int $start, int $end, string $unit ): ?array {
		$expression_bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$bounds            = $this->get_mysql_extract_function_bounds(
			$tokens,
			$expression_bounds['start'],
			$expression_bounds['end']
		);
		if (
			null === $bounds
			|| $bounds['unit'] !== $unit
			|| $bounds['close'] + 1 !== $expression_bounds['end']
		) {
			return null;
		}

		return array(
			'start' => $bounds['expression_start'],
			'end'   => $bounds['expression_end'],
		);
	}

	/**
	 * Get the argument expression for a supported WEEK() function.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token.
	 * @param int             $end    Final expression token, exclusive.
	 * @return array{start: int, end: int}|null Argument bounds, or null.
	 */
	private function get_mysql_week_argument_expression_bounds( array $tokens, int $start, int $end ): ?array {
		$expression_bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$bounds            = $this->get_mysql_week_function_bounds(
			$tokens,
			$expression_bounds['start'],
			$expression_bounds['end']
		);
		if (
			null === $bounds
			|| $bounds['close'] + 1 !== $expression_bounds['end']
		) {
			return null;
		}

		return array(
			'start' => $bounds['expression_start'],
			'end'   => $bounds['expression_end'],
		);
	}

	/**
	 * Check whether ORDER BY references the archive post_date expression.
	 *
	 * @param WP_MySQL_Token[] $tokens                  MySQL lexer token stream.
	 * @param array           $order_item              Parsed ORDER BY item.
	 * @param array           $archive_date_expression Shared date expression bounds.
	 * @return bool Whether the ORDER BY expression is supported.
	 */
	private function is_mysql_archive_post_date_order_expression( array $tokens, array $order_item, array $archive_date_expression ): bool {
		return $this->are_mysql_token_ranges_equivalent(
			$tokens,
			$order_item['expression_start'],
			$order_item['expression_end'],
			$archive_date_expression['start'],
			$archive_date_expression['end']
		) || $this->is_mysql_column_reference_expression(
			$tokens,
			$order_item['expression_start'],
			$order_item['expression_end'],
			'post_date',
			'posts',
			true
		);
	}

	/**
	 * Check whether a SELECT is grouped by the selected comments.comment_ID.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param array           $projection_items Parsed projection items.
	 * @param array           $group_items      Parsed GROUP BY item ranges.
	 * @return bool Whether this is the supported comment ID grouped shape.
	 */
	private function is_mysql_comment_id_grouped_select_shape( array $tokens, array $projection_items, array $group_items ): bool {
		return 1 === count( $projection_items )
			&& 1 === count( $group_items )
			&& $this->is_mysql_comment_id_expression(
				$tokens,
				$projection_items[0]['expression_start'],
				$projection_items[0]['expression_end']
			)
			&& $this->is_mysql_comment_id_expression(
				$tokens,
				$group_items[0]['start'],
				$group_items[0]['end']
			);
	}

	/**
	 * Check whether an expression references comments.comment_ID.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token.
	 * @param int             $end    Final expression token, exclusive.
	 * @return bool Whether the expression is comments.comment_ID.
	 */
	private function is_mysql_comment_id_expression( array $tokens, int $start, int $end ): bool {
		return $this->is_mysql_column_reference_expression( $tokens, $start, $end, 'comment_ID', 'comments', true );
	}

	/**
	 * Check whether a grouped comment ID ORDER BY expression can be aggregated.
	 *
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param array           $order_item Parsed ORDER BY item.
	 * @return bool Whether the ORDER BY expression is supported.
	 */
	private function is_mysql_comment_id_grouped_order_expression( array $tokens, array $order_item ): bool {
		if (
			$this->is_mysql_column_reference_expression(
				$tokens,
				$order_item['expression_start'],
				$order_item['expression_end'],
				'comment_date',
				'comments',
				false
			)
			|| $this->is_mysql_column_reference_expression(
				$tokens,
				$order_item['expression_start'],
				$order_item['expression_end'],
				'comment_date_gmt',
				'comments',
				false
			)
			|| $this->is_mysql_qualified_column_reference_expression(
				$tokens,
				$order_item['expression_start'],
				$order_item['expression_end'],
				'meta_value'
			)
		) {
			return true;
		}

		$cast_bounds = $this->get_mysql_character_cast_bounds(
			$tokens,
			$order_item['expression_start'],
			$order_item['expression_end']
		);
		if ( null === $cast_bounds || $cast_bounds['close'] + 1 !== $order_item['expression_end'] ) {
			return false;
		}

		return $this->is_mysql_qualified_column_reference_expression(
			$tokens,
			$cast_bounds['expression_start'],
			$cast_bounds['expression_end'],
			'meta_value'
		);
	}

	/**
	 * Check whether a SELECT is grouped by the selected posts.ID.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param array           $projection_items Parsed projection items.
	 * @param array           $group_items      Parsed GROUP BY item ranges.
	 * @return bool Whether this is the supported post ID grouped shape.
	 */
	private function is_mysql_post_id_grouped_select_shape( array $tokens, array $projection_items, array $group_items ): bool {
		return 1 === count( $projection_items )
			&& 1 === count( $group_items )
			&& $this->is_mysql_post_id_expression(
				$tokens,
				$projection_items[0]['expression_start'],
				$projection_items[0]['expression_end']
			)
			&& $this->is_mysql_post_id_expression(
				$tokens,
				$group_items[0]['start'],
				$group_items[0]['end']
			);
	}

	/**
	 * Check whether an expression references posts.ID.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token.
	 * @param int             $end    Final expression token, exclusive.
	 * @return bool Whether the expression is posts.ID.
	 */
	private function is_mysql_post_id_expression( array $tokens, int $start, int $end ): bool {
		return $this->is_mysql_column_reference_expression( $tokens, $start, $end, 'ID', 'posts', true );
	}

	/**
	 * Check whether a grouped post ID ORDER BY expression can be aggregated.
	 *
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param array           $order_item Parsed ORDER BY item.
	 * @return bool Whether the ORDER BY expression is supported.
	 */
	private function is_mysql_post_id_grouped_order_expression( array $tokens, array $order_item ): bool {
		if (
			$this->is_mysql_column_reference_expression(
				$tokens,
				$order_item['expression_start'],
				$order_item['expression_end'],
				'post_date',
				'posts',
				false
			)
			|| $this->is_mysql_column_reference_expression(
				$tokens,
				$order_item['expression_start'],
				$order_item['expression_end'],
				'post_date_gmt',
				'posts',
				false
			)
			|| $this->is_mysql_qualified_column_reference_expression(
				$tokens,
				$order_item['expression_start'],
				$order_item['expression_end'],
				'meta_value'
			)
		) {
			return true;
		}

		return $this->is_mysql_meta_value_cast_expression(
			$tokens,
			$order_item['expression_start'],
			$order_item['expression_end']
		) || $this->is_mysql_meta_value_plus_zero_expression(
			$tokens,
			$order_item['expression_start'],
			$order_item['expression_end']
		);
	}

	/**
	 * Check whether an expression is a supported metadata value CAST.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token.
	 * @param int             $end    Final expression token, exclusive.
	 * @return bool Whether the expression casts a qualified meta_value reference.
	 */
	private function is_mysql_meta_value_cast_expression( array $tokens, int $start, int $end ): bool {
		$cast_bounds = $this->get_mysql_character_cast_bounds( $tokens, $start, $end );
		if ( null === $cast_bounds ) {
			$cast_bounds = $this->get_mysql_integer_cast_bounds( $tokens, $start, $end );
		}
		if ( null === $cast_bounds ) {
			$cast_bounds = $this->get_mysql_decimal_cast_bounds( $tokens, $start, $end );
		}
		if ( null === $cast_bounds ) {
			$cast_bounds = $this->get_mysql_date_time_cast_bounds( $tokens, $start, $end );
		}

		return null !== $cast_bounds
			&& $cast_bounds['close'] + 1 === $end
			&& $this->is_mysql_qualified_column_reference_expression(
				$tokens,
				$cast_bounds['expression_start'],
				$cast_bounds['expression_end'],
				'meta_value'
			);
	}

	/**
	 * Check whether an expression is metadata value plus zero numeric ordering.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token.
	 * @param int             $end    Final expression token, exclusive.
	 * @return bool Whether the expression numerically orders meta_value.
	 */
	private function is_mysql_meta_value_plus_zero_expression( array $tokens, int $start, int $end ): bool {
		$reference = $this->parse_mysql_column_reference( $tokens, $start, $end );
		if (
			null !== $reference
			&& null !== $reference['qualifier']
			&& isset( $tokens[ $reference['end'] ] )
			&& WP_MySQL_Lexer::PLUS_OPERATOR === $tokens[ $reference['end'] ]->id
		) {
			$literal = $this->parse_mysql_numeric_literal( $tokens, $reference['end'] + 1, $end );
			return null !== $literal
				&& $literal['end'] === $end
				&& $this->is_mysql_zero_numeric_literal_range( $tokens, $literal['start'], $literal['end'] )
				&& $this->is_mysql_qualified_column_reference_expression( $tokens, $start, $reference['end'], 'meta_value' );
		}

		$literal = $this->parse_mysql_numeric_literal( $tokens, $start, $end );
		if (
			null === $literal
			|| ! $this->is_mysql_zero_numeric_literal_range( $tokens, $literal['start'], $literal['end'] )
			|| ! isset( $tokens[ $literal['end'] ] )
			|| WP_MySQL_Lexer::PLUS_OPERATOR !== $tokens[ $literal['end'] ]->id
		) {
			return false;
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $literal['end'] + 1, $end );
		return null !== $reference
			&& $reference['end'] === $end
			&& null !== $reference['qualifier']
			&& $this->is_mysql_qualified_column_reference_expression( $tokens, $reference['start'], $reference['end'], 'meta_value' );
	}

	/**
	 * Check whether an ORDER BY expression is already valid for the GROUP BY.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param array           $order_item  Parsed ORDER BY item.
	 * @param array           $group_items Parsed GROUP BY item ranges.
	 * @return bool Whether the expression is grouped.
	 */
	private function is_mysql_grouped_order_expression( array $tokens, array $order_item, array $group_items ): bool {
		foreach ( $group_items as $group_item ) {
			if (
				$this->are_mysql_token_ranges_equivalent(
					$tokens,
					$order_item['expression_start'],
					$order_item['expression_end'],
					$group_item['start'],
					$group_item['end']
				)
			) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Build an aggregate-safe ORDER BY item for grouped SELECTs.
	 *
	 * @param array $order_item Parsed ORDER BY item.
	 * @return string PostgreSQL ORDER BY item SQL.
	 */
	private function get_strict_grouped_aggregate_order_sql( array $order_item ): string {
		$aggregate_function = 'DESC' === $order_item['direction'] ? 'MAX' : 'MIN';

		return sprintf(
			'%s(%s) %s',
			$aggregate_function,
			$order_item['sql'],
			$order_item['direction']
		);
	}

	/**
	 * Get the MySQL-compatible ID tie-breaker for grouped posts date ordering.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param array           $order_items      Parsed ORDER BY items.
	 * @param array           $group_items      Parsed GROUP BY item ranges.
	 * @param bool            $is_post_id_group Whether the query groups by posts.ID.
	 * @return string|null PostgreSQL ORDER BY item SQL, or null when not applicable.
	 */
	private function get_strict_grouped_posts_post_date_desc_order_id_tiebreaker_sql(
		array $tokens,
		array $order_items,
		array $group_items,
		bool $is_post_id_group
	): ?string {
		if (
			! $is_post_id_group
			|| 1 !== count( $order_items )
			|| 1 !== count( $group_items )
			|| 'DESC' !== $order_items[0]['direction']
			|| ! $this->is_mysql_column_reference_expression(
				$tokens,
				$order_items[0]['expression_start'],
				$order_items[0]['expression_end'],
				'post_date',
				'posts',
				false
			)
		) {
			return null;
		}

		return $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$group_items[0]['start'],
			$group_items[0]['end']
		) . ' DESC';
	}

	/**
	 * Check whether an expression is a supported column reference.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int             $start            First expression token.
	 * @param int             $end              Final expression token, exclusive.
	 * @param string          $column_name      Expected column name.
	 * @param string|null     $qualifier_suffix Optional table-name suffix for qualified references.
	 * @param bool            $allow_bare       Whether unqualified references are allowed.
	 * @return bool Whether the expression is a supported column reference.
	 */
	private function is_mysql_column_reference_expression(
		array $tokens,
		int $start,
		int $end,
		string $column_name,
		?string $qualifier_suffix,
		bool $allow_bare
	): bool {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start  = $bounds['start'];
		$end    = $bounds['end'];

		if ( $allow_bare && $start + 1 === $end ) {
			$identifier = $this->get_mysql_identifier_token_value( $tokens[ $start ] ?? null );
			return null !== $identifier && strtolower( $identifier ) === strtolower( $column_name );
		}

		if (
			$start + 3 !== $end
			|| ! isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ] )
			|| WP_MySQL_Lexer::DOT_SYMBOL !== $tokens[ $start + 1 ]->id
		) {
			return false;
		}

		$qualifier = $this->get_mysql_identifier_token_value( $tokens[ $start ] );
		$column    = $this->get_mysql_identifier_token_value( $tokens[ $start + 2 ] );
		if ( null === $qualifier || null === $column || strtolower( $column ) !== strtolower( $column_name ) ) {
			return false;
		}

		return null === $qualifier_suffix
			|| strtolower( $qualifier ) === strtolower( $qualifier_suffix )
			|| '_' . strtolower( $qualifier_suffix ) === substr( strtolower( $qualifier ), -1 * ( strlen( $qualifier_suffix ) + 1 ) );
	}

	/**
	 * Check whether an expression is a qualified column reference.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param int             $start       First expression token.
	 * @param int             $end         Final expression token, exclusive.
	 * @param string          $column_name Expected column name.
	 * @return bool Whether the expression is a qualified column reference.
	 */
	private function is_mysql_qualified_column_reference_expression( array $tokens, int $start, int $end, string $column_name ): bool {
		return $this->is_mysql_column_reference_expression( $tokens, $start, $end, $column_name, null, false );
	}

	/**
	 * Check whether two expression token ranges are structurally equivalent.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param int             $left_start  First left expression token.
	 * @param int             $left_end    Final left expression token, exclusive.
	 * @param int             $right_start First right expression token.
	 * @param int             $right_end   Final right expression token, exclusive.
	 * @return bool Whether the token ranges are equivalent.
	 */
	private function are_mysql_token_ranges_equivalent(
		array $tokens,
		int $left_start,
		int $left_end,
		int $right_start,
		int $right_end
	): bool {
		$left_bounds  = $this->normalize_mysql_expression_bounds( $tokens, $left_start, $left_end );
		$right_bounds = $this->normalize_mysql_expression_bounds( $tokens, $right_start, $right_end );

		$left_start  = $left_bounds['start'];
		$left_end    = $left_bounds['end'];
		$right_start = $right_bounds['start'];
		$right_end   = $right_bounds['end'];

		if ( $left_end - $left_start !== $right_end - $right_start ) {
			return false;
		}

		for ( $left = $left_start, $right = $right_start; $left < $left_end; $left++, $right++ ) {
			if ( ! $this->are_mysql_tokens_equivalent( $tokens[ $left ], $tokens[ $right ] ) ) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Normalize expression bounds by removing full-range wrapper parentheses.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token.
	 * @param int             $end    Final expression token, exclusive.
	 * @return array{start: int, end: int} Normalized bounds.
	 */
	private function normalize_mysql_expression_bounds( array $tokens, int $start, int $end ): array {
		while (
			$start + 2 <= $end
			&& isset( $tokens[ $start ] )
			&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $start ]->id
			&& $this->get_mysql_parenthesized_sequence_end( $tokens, $start, $end ) === $end
		) {
			++$start;
			--$end;
		}

		return array(
			'start' => $start,
			'end'   => $end,
		);
	}

	/**
	 * Check whether two individual MySQL tokens are structurally equivalent.
	 *
	 * @param WP_MySQL_Token $left  Left token.
	 * @param WP_MySQL_Token $right Right token.
	 * @return bool Whether the tokens are equivalent.
	 */
	private function are_mysql_tokens_equivalent( WP_MySQL_Token $left, WP_MySQL_Token $right ): bool {
		$left_identifier  = $this->get_mysql_identifier_token_value( $left );
		$right_identifier = $this->get_mysql_identifier_token_value( $right );
		if ( null !== $left_identifier || null !== $right_identifier ) {
			return null !== $left_identifier
				&& null !== $right_identifier
				&& strtolower( $left_identifier ) === strtolower( $right_identifier );
		}

		if ( $left->id !== $right->id ) {
			return false;
		}

		if ( WP_MySQL_Lexer::SINGLE_QUOTED_TEXT === $left->id || WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT === $left->id ) {
			return $left->get_value() === $right->get_value();
		}

		return strtolower( $left->get_bytes() ) === strtolower( $right->get_bytes() );
	}

	/**
	 * Check whether a SELECT query uses the MySQL SQL_CALC_FOUND_ROWS modifier.
	 *
	 * @param string $query MySQL query.
	 * @return bool Whether the query asks for FOUND_ROWS tracking.
	 */
	private function is_sql_calc_found_rows_select_query( string $query ): bool {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0], $tokens[1] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return false;
		}

		if ( null === $this->get_mysql_statement_end_position( $tokens, 1 ) ) {
			return false;
		}

		if ( WP_MySQL_Lexer::SQL_CALC_FOUND_ROWS_SYMBOL === $tokens[1]->id ) {
			return true;
		}

		return isset( $tokens[2] )
			&& WP_MySQL_Lexer::DISTINCT_SYMBOL === $tokens[1]->id
			&& WP_MySQL_Lexer::SQL_CALC_FOUND_ROWS_SYMBOL === $tokens[2]->id;
	}

	/**
	 * Translate WordPress SELECT SQL_CALC_FOUND_ROWS queries.
	 *
	 * PostgreSQL has no SQL_CALC_FOUND_ROWS modifier. WordPress issues these
	 * queries for pagination, followed by SELECT FOUND_ROWS(); this first pass
	 * executes the paginated query itself while preserving compatible clauses.
	 *
	 * @param string $query MySQL query.
	 * @param bool   $include_limit Whether to preserve the LIMIT/OFFSET clause.
	 * @return string|null PostgreSQL query, or null when the query is unsupported.
	 */
	private function translate_sql_calc_found_rows_select_query( string $query, bool $include_limit = true ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if (
			! isset( $tokens[0], $tokens[1] )
			|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id
			|| WP_MySQL_Lexer::SQL_CALC_FOUND_ROWS_SYMBOL !== $tokens[1]->id
		) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 2 );
		if ( null === $statement_end ) {
			return null;
		}

		$select_end     = $statement_end;
		$limit_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::LIMIT_SYMBOL, 2, $statement_end );
		if ( null !== $limit_position ) {
			if ( ! $this->is_supported_simple_select_limit_clause( $tokens, $limit_position, $statement_end ) ) {
				return null;
			}
			$select_end = $limit_position;
		}

		$contextual_sql = $this->translate_mysql_select_statement_with_integer_string_coercion(
			$tokens,
			2,
			$select_end,
			false
		);
		if ( null !== $contextual_sql ) {
			if ( $include_limit && null !== $limit_position ) {
				$contextual_sql .= $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end );
			}

			return $contextual_sql;
		}

		$sql = 'SELECT ' . $this->translate_mysql_token_sequence_to_postgresql( $tokens, 2, $select_end );
		if ( $include_limit && null !== $limit_position ) {
			$sql .= $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $statement_end );
		}

		return $sql;
	}

	/**
	 * Apply conservative MySQL-to-PostgreSQL token compatibility rewrites.
	 *
	 * Complex WordPress queries often use PostgreSQL-compatible SQL except for
	 * MySQL identifier casing. This fallback quotes backticked and mixed-case
	 * identifiers without trying to emulate unsupported MySQL-only syntax.
	 *
	 * @param string $query MySQL query.
	 * @return string|null PostgreSQL query, or null when no compatibility rewrite applies.
	 */
	private function translate_mysql_compatible_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) ) {
			return null;
		}

		if (
			! in_array(
				$tokens[0]->id,
				array(
					WP_MySQL_Lexer::DELETE_SYMBOL,
					WP_MySQL_Lexer::INSERT_SYMBOL,
					WP_MySQL_Lexer::REPLACE_SYMBOL,
					WP_MySQL_Lexer::SELECT_SYMBOL,
					WP_MySQL_Lexer::UPDATE_SYMBOL,
				),
				true
			)
		) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return null;
		}

		if ( WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[0]->id ) {
			$contextual_sql = $this->translate_mysql_select_statement_with_integer_string_coercion(
				$tokens,
				1,
				$statement_end,
				true
			);
			if ( null !== $contextual_sql ) {
				return $contextual_sql;
			}

			$contextual_sql = $this->translate_mysql_count_aggregate_projection_alias_query(
				$tokens,
				1,
				$statement_end
			);
			if ( null !== $contextual_sql ) {
				return $contextual_sql;
			}
		}

		if ( $this->contains_unsupported_mysql_date_arithmetic_function( $tokens, 0, $statement_end ) ) {
			return null;
		}

		if ( $this->contains_unsupported_mysql_week_function( $tokens, 0, $statement_end ) ) {
			return null;
		}

		if ( ! $this->needs_mysql_compatible_rewrite( $tokens, 0, $statement_end ) ) {
			return null;
		}

		return $this->translate_mysql_token_sequence_to_postgresql( $tokens, 0, $statement_end );
	}

	/**
	 * Check whether a query must fail closed while information_schema is selected.
	 *
	 * The PostgreSQL backend does not use MySQL database state for unqualified
	 * names. Without broad information_schema routing, table-scoped statements
	 * under USE information_schema would otherwise target public tables.
	 *
	 * @param string $query MySQL query.
	 * @return bool Whether the query should be rejected before backend execution.
	 */
	private function should_reject_information_schema_backend_query( string $query ): bool {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) ) {
			return false;
		}

		if ( WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[0]->id ) {
			$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
			if ( null !== $statement_end ) {
				if ( null !== $this->translate_direct_information_schema_select_query( $query ) ) {
					return false;
				}

				if ( $this->select_references_direct_information_schema_relation( $tokens, 1, $statement_end ) ) {
					return true;
				}
			}

			return 0 === strcasecmp( $this->db_name, 'information_schema' )
				&& $this->information_schema_select_has_table_reference( $tokens );
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if (
			null !== $statement_end
			&& WP_MySQL_Lexer::INSERT_SYMBOL === $tokens[0]->id
			&& $this->select_references_direct_information_schema_relation( $tokens, 1, $statement_end )
		) {
			if ( null !== $this->translate_simple_mysql_insert_select_query( $query ) ) {
				return false;
			}

			return true;
		}

		if ( 0 !== strcasecmp( $this->db_name, 'information_schema' ) ) {
			return false;
		}

		if (
			in_array(
				$tokens[0]->id,
				array(
					WP_MySQL_Lexer::EXPLAIN_SYMBOL,
					WP_MySQL_Lexer::WITH_SYMBOL,
				),
				true
			)
		) {
			return true;
		}

		return in_array(
			$tokens[0]->id,
			array(
				WP_MySQL_Lexer::ALTER_SYMBOL,
				WP_MySQL_Lexer::ANALYZE_SYMBOL,
				WP_MySQL_Lexer::CHECK_SYMBOL,
				WP_MySQL_Lexer::CREATE_SYMBOL,
				WP_MySQL_Lexer::DESCRIBE_SYMBOL,
				WP_MySQL_Lexer::DELETE_SYMBOL,
				WP_MySQL_Lexer::DESC_SYMBOL,
				WP_MySQL_Lexer::DROP_SYMBOL,
				WP_MySQL_Lexer::INSERT_SYMBOL,
				WP_MySQL_Lexer::LOCK_SYMBOL,
				WP_MySQL_Lexer::OPTIMIZE_SYMBOL,
				WP_MySQL_Lexer::REPLACE_SYMBOL,
				WP_MySQL_Lexer::REPAIR_SYMBOL,
				WP_MySQL_Lexer::TRUNCATE_SYMBOL,
				WP_MySQL_Lexer::UPDATE_SYMBOL,
			),
			true
		);
	}

	/**
	 * Check whether an untranslated SELECT must not fall through to PostgreSQL.
	 *
	 * @param string $query MySQL query.
	 * @return bool Whether the query names information_schema in a table-scoped way.
	 */
	private function should_reject_unsupported_direct_information_schema_select_query( string $query ): bool {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return false;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return false;
		}

		if ( $this->select_references_direct_information_schema_relation( $tokens, 1, $statement_end ) ) {
			return true;
		}

		return 0 === strcasecmp( $this->db_name, 'information_schema' )
			&& $this->information_schema_select_has_table_reference( $tokens );
	}

	/**
	 * Check whether a SELECT under USE information_schema reaches a table source.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @return bool Whether the SELECT should be rejected.
	 */
	private function information_schema_select_has_table_reference( array $tokens ): bool {
		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return true;
		}

		return null !== $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::FROM_SYMBOL,
			1,
			$statement_end
		);
	}

	/**
	 * Check whether a SELECT token range names information_schema directly.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token position.
	 * @param int              $end    Final token position, exclusive.
	 * @return bool Whether the range references an information_schema relation.
	 */
	private function select_references_direct_information_schema_relation( array $tokens, int $start, int $end ): bool {
		for ( $position = $start; $position + 2 < $end; $position++ ) {
			if (
				WP_MySQL_Lexer::DOT_SYMBOL !== ( $tokens[ $position + 1 ]->id ?? null )
				|| 0 !== strcasecmp(
					(string) $this->get_direct_information_schema_identifier_token_value( $tokens[ $position ] ?? null ),
					'information_schema'
				)
			) {
				continue;
			}

			$relation = $this->get_direct_information_schema_identifier_token_value( $tokens[ $position + 2 ] ?? null );
			if ( null !== $relation ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Add explicit aliases to multi-expression COUNT aggregate projections.
	 *
	 * PostgreSQL labels every unaliased COUNT expression as "count". WordPress
	 * later converts fetched objects to ARRAY_N by reading object properties, so
	 * duplicate labels collapse the result row before ARRAY_N can preserve order.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int              $projection_start First projection token position.
	 * @param int              $statement_end    Final statement token position, exclusive.
	 * @return string|null PostgreSQL query, or null when unsupported.
	 */
	private function translate_mysql_count_aggregate_projection_alias_query( array $tokens, int $projection_start, int $statement_end ): ?string {
		if (
			! isset( $tokens[0] )
			|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id
			|| $this->contains_top_level_mysql_token(
				$tokens,
				$projection_start,
				$statement_end,
				array(
					WP_MySQL_Lexer::DISTINCT_SYMBOL,
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::GROUP_SYMBOL,
					WP_MySQL_Lexer::HAVING_SYMBOL,
					WP_MySQL_Lexer::HIGH_PRIORITY_SYMBOL,
					WP_MySQL_Lexer::INTO_SYMBOL,
					WP_MySQL_Lexer::LIMIT_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::ORDER_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::SELECT_SYMBOL,
					WP_MySQL_Lexer::SQL_CALC_FOUND_ROWS_SYMBOL,
					WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				)
			)
		) {
			return null;
		}

		$from_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::FROM_SYMBOL,
			$projection_start,
			$statement_end
		);
		if ( null === $from_position || $projection_start === $from_position ) {
			return null;
		}

		$projection_ranges = $this->split_top_level_mysql_arguments( $tokens, $projection_start, $from_position );
		if ( null === $projection_ranges || count( $projection_ranges ) < 2 ) {
			return null;
		}

		$projection_sql = array();
		$alias_lookup   = array();
		foreach ( $projection_ranges as $range ) {
			$expression_bounds = $this->get_mysql_select_projection_expression_bounds(
				$tokens,
				$range['start'],
				$range['end']
			);
			if (
				null === $expression_bounds
				|| $expression_bounds['start'] !== $range['start']
				|| $expression_bounds['end'] !== $range['end']
				|| ! $this->is_mysql_count_aggregate_expression(
					$tokens,
					$expression_bounds['start'],
					$expression_bounds['end']
				)
			) {
				return null;
			}

			$expression_sql = $this->translate_mysql_token_sequence_to_postgresql(
				$tokens,
				$expression_bounds['start'],
				$expression_bounds['end']
			);
			$alias_key      = strtolower( $expression_sql );
			if ( isset( $alias_lookup[ $alias_key ] ) ) {
				return null;
			}

			$alias_lookup[ $alias_key ] = true;
			$projection_sql[]           = sprintf(
				'%s AS %s',
				$expression_sql,
				$this->connection->quote_identifier( $expression_sql )
			);
		}

		return sprintf(
			'SELECT %s %s',
			implode( ', ', $projection_sql ),
			$this->translate_mysql_token_sequence_to_postgresql( $tokens, $from_position, $statement_end )
		);
	}

	/**
	 * Tokenize a MySQL query with the configured lexer implementation.
	 *
	 * @param string $query MySQL query.
	 * @return WP_MySQL_Token[] MySQL lexer token stream.
	 */
	private function get_mysql_tokens( string $query ): array {
		$sql_mode = $this->get_sql_mode();
		if ( $query === $this->mysql_token_cache_query && $sql_mode === $this->mysql_token_cache_sql_mode ) {
			return $this->mysql_token_cache_tokens;
		}

		$lexer  = new WP_MySQL_Lexer( $query, $this->mysql_version, $this->active_sql_modes );
		$tokens = $lexer instanceof WP_MySQL_Native_Lexer ? $lexer->native_token_stream() : $lexer->remaining_tokens();

		$this->mysql_token_cache_query    = $query;
		$this->mysql_token_cache_sql_mode = $sql_mode;
		$this->mysql_token_cache_tokens   = $tokens;

		return $tokens;
	}

	/**
	 * Check whether a table name is a WordPress options table.
	 *
	 * @param string $table_name Table identifier value.
	 * @return bool Whether the table is an options table.
	 */
	private function is_wordpress_options_table_name( string $table_name ): bool {
		$table_name = strtolower( $table_name );
		return 'options' === $table_name || '_options' === substr( $table_name, -8 );
	}

	/**
	 * Parse a parenthesized MySQL identifier list.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Current token position, updated on success.
	 * @return string[]|null Identifier values, or null when unsupported.
	 */
	private function parse_mysql_identifier_list( array $tokens, int &$position ): ?array {
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		++$position;
		$identifiers = array();

		while ( isset( $tokens[ $position ] ) ) {
			$identifier = $this->get_mysql_dml_identifier_token_value( $tokens[ $position ] );
			if ( null === $identifier ) {
				return null;
			}

			$identifiers[] = $identifier;
			++$position;

			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
				continue;
			}

			if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $position ]->id ) {
				++$position;
				return $identifiers;
			}

			return null;
		}

		return null;
	}

	/**
	 * Parse a parenthesized single-row MySQL VALUES list.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Current token position, updated on success.
	 * @return array{values: string[], ranges: array[]}|null Translated SQL values and token ranges, or null when unsupported.
	 */
	private function parse_mysql_value_list_with_ranges( array $tokens, int &$position ): ?array {
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		++$position;
		$values      = array();
		$ranges      = array();
		$value_start = $position;
		$depth       = 0;

		while ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::EOF !== $tokens[ $position ]->id ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
				++$depth;
				++$position;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $position ]->id ) {
				if ( 0 === $depth ) {
					if ( $value_start === $position ) {
						return null;
					}

					$values[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $value_start, $position );
					$ranges[] = array(
						'start' => $value_start,
						'end'   => $position,
					);
					++$position;
					return array(
						'values' => $values,
						'ranges' => $ranges,
					);
				}

				--$depth;
				++$position;
				continue;
			}

			if ( 0 === $depth && WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id ) {
				if ( $value_start === $position ) {
					return null;
				}

				$values[]    = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $value_start, $position );
				$ranges[]    = array(
					'start' => $value_start,
					'end'   => $position,
				);
				$value_start = $position + 1;
			}

			++$position;
		}

		return null;
	}

	/**
	 * Locate the top-level ON DUPLICATE KEY UPDATE clause.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Token position where scanning starts.
	 * @return int|null Token position of ON, or null when not found.
	 */
	private function find_on_duplicate_key_update_clause( array $tokens, int $position ): ?int {
		$depth = 0;
		for ( $i = $position; isset( $tokens[ $i ] ) && WP_MySQL_Lexer::EOF !== $tokens[ $i ]->id; $i++ ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $i ]->id ) {
				++$depth;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $i ]->id ) {
				--$depth;
				if ( $depth < 0 ) {
					return null;
				}
				continue;
			}

			if (
				0 === $depth
				&& WP_MySQL_Lexer::ON_SYMBOL === $tokens[ $i ]->id
				&& isset( $tokens[ $i + 3 ] )
				&& WP_MySQL_Lexer::DUPLICATE_SYMBOL === $tokens[ $i + 1 ]->id
				&& WP_MySQL_Lexer::KEY_SYMBOL === $tokens[ $i + 2 ]->id
				&& WP_MySQL_Lexer::UPDATE_SYMBOL === $tokens[ $i + 3 ]->id
			) {
				return $i;
			}
		}

		return null;
	}

	/**
	 * Parse ON DUPLICATE KEY UPDATE assignments for the supported upsert shape.
	 *
	 * @param string           $table_name           Target table name.
	 * @param WP_MySQL_Token[] $tokens              MySQL lexer token stream.
	 * @param int             $position            Current token position, updated on success.
	 * @param int              $end                 Final assignment token position, exclusive.
	 * @param array           $column_lookup       Insert-column lookup by lowercase name.
	 * @param array           $table_column_lookup Table-column metadata lookup by lowercase name.
	 * @param array           $source_aliases      Optional VALUES-row alias lookup.
	 * @return string[]|null PostgreSQL SET assignments, or null when unsupported.
	 */
	private function parse_upsert_update_assignments( string $table_name, array $tokens, int &$position, int $end, array $column_lookup, array $table_column_lookup, array $source_aliases = array() ): ?array {
		$assignments          = array();
		$scope                = $this->get_mysql_single_table_scope( $table_name );
		$values_column_lookup = $this->get_mysql_upsert_values_column_lookup( $column_lookup, $table_column_lookup );

		while ( $position < $end ) {
			$target = $this->parse_mysql_upsert_assignment_target( $table_name, $tokens, $position, $end );
			if (
				null === $target
				|| ! isset( $table_column_lookup[ strtolower( $target['column'] ) ] )
			) {
				return null;
			}

			$target_column = $target['column'];
			$position      = $target['end'];
			if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::EQUAL_OPERATOR !== $tokens[ $position ]->id ) {
				return null;
			}

			++$position;
			$value_start    = $position;
			$assignment_end = $this->find_top_level_mysql_token(
				$tokens,
				WP_MySQL_Lexer::COMMA_SYMBOL,
				$value_start,
				$end
			) ?? $end;

			if ( $value_start >= $assignment_end ) {
				return null;
			}

			$target_metadata = $table_column_lookup[ strtolower( $target_column ) ];
			$source_column   = $this->get_mysql_upsert_values_assignment_source_column( $tokens, $value_start, $assignment_end, $values_column_lookup, $source_aliases );
			if ( $this->is_mysql_default_keyword_expression( $tokens, $value_start, $assignment_end ) ) {
				$value_sql = $this->get_mysql_dml_default_assignment_sql_for_column( $target_metadata );
			} elseif ( null !== $source_column ) {
				$value_sql = sprintf(
					'excluded.%s',
					$this->connection->quote_identifier( $source_column )
				);
			} else {
				$scalar_subquery_sql = null;
				$values_replacements = $this->get_mysql_upsert_values_expression_replacements(
					$tokens,
					$value_start,
					$assignment_end,
					$values_column_lookup,
					$source_aliases
				);
				if (
					null === $values_replacements
					|| ! $this->is_supported_simple_mysql_upsert_expression_fragment(
						$tokens,
						$value_start,
						$assignment_end,
						$values_replacements
					)
				) {
					$scalar_subquery_sql = $this->get_mysql_upsert_scalar_subquery_assignment_sql(
						$tokens,
						$value_start,
						$assignment_end,
						$scope
					);
					if ( null === $scalar_subquery_sql ) {
						return null;
					}
					$values_replacements = array();
				}

				$this->validate_strict_mysql_dml_value_for_column( $target_metadata, $tokens, $value_start, $assignment_end );

				$value_sql = $scalar_subquery_sql ?? null;
				if (
					null !== $value_sql
					&& $this->is_mysql_text_family_column_type( (string) ( $target_metadata['column_type'] ?? '' ) )
				) {
					$value_sql = sprintf( 'CAST(%s AS text)', $value_sql );
				}
				if ( null === $value_sql ) {
					$value_sql = $this->get_strict_mysql_dml_value_sql_for_column( $target_metadata, $tokens, $value_start, $assignment_end );
				}
				if ( null === $value_sql ) {
					$value_sql = $this->get_non_strict_mysql_dml_value_sql_for_column( $target_metadata, $tokens, $value_start, $assignment_end );
				}
				if ( null === $value_sql ) {
					if ( empty( $values_replacements ) ) {
						$expression_sql = $this->translate_mysql_expression_token_sequence_to_postgresql(
							$tokens,
							$value_start,
							$assignment_end,
							$scope
						);
						$value_sql      = $expression_sql['sql'];
						$changed        = $expression_sql['changed'];
					} else {
						$value_sql = $this->translate_mysql_token_sequence_with_replacements_to_postgresql(
							$tokens,
							$value_start,
							$assignment_end,
							$values_replacements
						);
						$changed   = true;
					}
					if (
						$changed
						&& $this->is_mysql_text_family_column_type( (string) ( $target_metadata['column_type'] ?? '' ) )
					) {
						$value_sql = sprintf( 'CAST(%s AS text)', $value_sql );
					}
				}
			}

			$assignments[] = sprintf(
				'%s = %s',
				$this->connection->quote_identifier( $target_column ),
				$value_sql
			);
			$position      = $assignment_end;

			if ( $position === $end ) {
				break;
			}

			++$position;
		}

		return count( $assignments ) > 0 ? $assignments : null;
	}

	/**
	 * Parse the target column for an ON DUPLICATE KEY UPDATE assignment.
	 *
	 * @param string           $table_name Target table name.
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param int              $position   Assignment target start.
	 * @param int              $end        Final assignment token position, exclusive.
	 * @return array{column: string, end: int}|null Assignment target, or null when unsupported.
	 */
	private function parse_mysql_upsert_assignment_target( string $table_name, array $tokens, int $position, int $end ): ?array {
		$first_identifier = $this->get_mysql_dml_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $first_identifier ) {
			return null;
		}

		if ( $position + 2 >= $end || WP_MySQL_Lexer::DOT_SYMBOL !== ( $tokens[ $position + 1 ]->id ?? null ) ) {
			return array(
				'column' => $first_identifier,
				'end'    => $position + 1,
			);
		}

		$second_identifier = $this->get_mysql_dml_identifier_token_value( $tokens[ $position + 2 ] ?? null );
		if ( null === $second_identifier ) {
			return null;
		}

		if ( $position + 4 < $end && WP_MySQL_Lexer::DOT_SYMBOL === ( $tokens[ $position + 3 ]->id ?? null ) ) {
			$third_identifier = $this->get_mysql_dml_identifier_token_value( $tokens[ $position + 4 ] ?? null );
			if (
				null === $third_identifier
				|| 0 !== strcasecmp( $first_identifier, $this->main_db_name )
				|| ! $this->is_mysql_dml_table_qualifier( $second_identifier, $table_name, null )
			) {
				return null;
			}

			return array(
				'column' => $third_identifier,
				'end'    => $position + 5,
			);
		}

		if ( ! $this->is_mysql_dml_table_qualifier( $first_identifier, $table_name, null ) ) {
			return null;
		}

		return array(
			'column' => $second_identifier,
			'end'    => $position + 3,
		);
	}

	/**
	 * Check whether an expression is exactly the DEFAULT keyword.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First expression token.
	 * @param int              $end    Final expression token, exclusive.
	 * @return bool Whether this is DEFAULT.
	 */
	private function is_mysql_default_keyword_expression( array $tokens, int $start, int $end ): bool {
		return $start + 1 === $end
			&& isset( $tokens[ $start ] )
			&& WP_MySQL_Lexer::DEFAULT_SYMBOL === $tokens[ $start ]->id;
	}

	/**
	 * Get SQL for a MySQL DEFAULT assignment expression.
	 *
	 * @param array $column_metadata Column metadata row.
	 * @return string PostgreSQL SQL expression.
	 */
	private function get_mysql_dml_default_assignment_sql_for_column( array $column_metadata ): string {
		if ( null !== ( $column_metadata['column_default'] ?? null ) ) {
			return $this->connection->quote( (string) $column_metadata['column_default'] );
		}

		return 'NULL';
	}

	/**
	 * Get PostgreSQL SQL for a supported scalar subquery upsert assignment.
	 *
	 * This supports constant/no-table scalar SELECTs, optional MySQL FROM DUAL,
	 * and uncorrelated COUNT(*)/COUNT(column) from a single current-database table.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First expression token.
	 * @param int              $end    Final expression token, exclusive.
	 * @param array            $scope  Statement table scope.
	 * @return string|null PostgreSQL scalar subquery SQL, or null when unsupported.
	 */
	private function get_mysql_upsert_scalar_subquery_assignment_sql( array $tokens, int $start, int $end, array $scope ): ?string {
		$after_subquery = $this->get_mysql_parenthesized_sequence_end( $tokens, $start, $end );
		if (
			null === $after_subquery
			|| $after_subquery !== $end
			|| ! isset( $tokens[ $start + 1 ] )
			|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $start + 1 ]->id
		) {
			return null;
		}

		$select_start     = $start + 1;
		$projection_start = $select_start + 1;
		$select_end       = $end - 1;
		if ( $projection_start >= $select_end ) {
			return null;
		}

		if (
			$this->contains_top_level_mysql_token(
				$tokens,
				$projection_start,
				$select_end,
				array(
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::GROUP_SYMBOL,
					WP_MySQL_Lexer::HAVING_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::SELECT_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				)
			)
		) {
			return null;
		}

		$from_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::FROM_SYMBOL,
			$projection_start,
			$select_end
		);
		if ( null !== $from_position ) {
			$limit_position = $this->find_top_level_mysql_token(
				$tokens,
				WP_MySQL_Lexer::LIMIT_SYMBOL,
				$from_position + 1,
				$select_end
			);
			$order_position = $this->find_top_level_mysql_token(
				$tokens,
				WP_MySQL_Lexer::ORDER_SYMBOL,
				$from_position + 1,
				null === $limit_position ? $select_end : $limit_position
			);
			if (
				null !== $limit_position
				&& null !== $this->find_top_level_mysql_token(
					$tokens,
					WP_MySQL_Lexer::ORDER_SYMBOL,
					$limit_position + 1,
					$select_end
				)
			) {
				return null;
			}

			$tail_start = $order_position ?? $limit_position ?? $select_end;
			$where_position = $this->find_top_level_mysql_token(
				$tokens,
				WP_MySQL_Lexer::WHERE_SYMBOL,
				$from_position + 1,
				$tail_start
			);
			$source_end     = $where_position ?? $tail_start;
			if ( $from_position + 2 === $source_end && WP_MySQL_Lexer::DUAL_SYMBOL === ( $tokens[ $from_position + 1 ]->id ?? null ) ) {
				if ( null !== $where_position ) {
					return null;
				}
				$projection_end = $from_position;
			} else {
				$reference_position = $from_position + 1;
				$reference          = $this->parse_mysql_main_database_table_reference( $tokens, $reference_position, $source_end );
				if ( null === $reference || $reference_position !== $source_end ) {
					return null;
				}

				$projection = $this->split_top_level_mysql_arguments( $tokens, $projection_start, $from_position );
				if ( null === $projection || 1 !== count( $projection ) ) {
					return null;
				}

				$subquery_scope = $this->get_mysql_single_table_scope( $reference['table'], $reference['alias'] );
				$projection_sql = $this->get_mysql_upsert_table_scalar_subquery_projection_sql(
					$tokens,
					$projection[0]['start'],
					$projection[0]['end'],
					$reference['table'],
					$reference['alias'],
					$subquery_scope
				);
				if ( null === $projection_sql ) {
					return null;
				}

				$where_sql = '';
				if ( null !== $where_position ) {
					$where_end = $order_position ?? $limit_position ?? $select_end;
					if (
						$where_position + 1 >= $where_end
						|| ! $this->is_supported_simple_mysql_expression_fragment( $tokens, $where_position + 1, $where_end )
						|| ! $this->mysql_expression_column_references_resolve_to_scope( $tokens, $where_position + 1, $where_end, $subquery_scope )
					) {
						return null;
					}

					$translated_where = $this->translate_mysql_predicate_token_sequence_to_postgresql(
						$tokens,
						$where_position + 1,
						$where_end,
						$subquery_scope
					);
					$where_sql        = ' WHERE ' . $translated_where['sql'];
				}

				$order_sql = '';
				if ( null !== $order_position ) {
					$order_end   = $limit_position ?? $select_end;
					$order_items = $this->split_top_level_mysql_arguments( $tokens, $order_position + 2, $order_end );
					if ( null === $order_items || empty( $order_items ) ) {
						return null;
					}
					foreach ( $order_items as $order_item ) {
						$order_item_end = $order_item['end'];
						if (
							$order_item['start'] < $order_item_end
							&& (
								WP_MySQL_Lexer::ASC_SYMBOL === ( $tokens[ $order_item_end - 1 ]->id ?? null )
								|| WP_MySQL_Lexer::DESC_SYMBOL === ( $tokens[ $order_item_end - 1 ]->id ?? null )
							)
						) {
							--$order_item_end;
						}
						if (
							$order_item['start'] >= $order_item_end
							|| ! $this->mysql_expression_column_references_resolve_to_scope( $tokens, $order_item['start'], $order_item_end, $subquery_scope )
						) {
							return null;
						}
					}

					$order_sql = $this->translate_mysql_joined_dml_order_by_clause_to_postgresql(
						$tokens,
						$order_position,
						$order_end,
						$subquery_scope
					);
					if ( null === $order_sql ) {
						return null;
					}
				}

				$limit_sql = '';
				if ( null !== $limit_position ) {
					if ( ! $this->is_supported_simple_select_limit_clause( $tokens, $limit_position, $select_end ) ) {
						return null;
					}

					$limit_sql = $this->translate_simple_select_limit_clause_to_postgresql( $tokens, $limit_position, $select_end );
				}

				return sprintf(
					'(SELECT %s FROM %s%s%s%s)',
					$projection_sql,
					$this->get_postgresql_dml_table_reference_sql( $reference['table'], $reference['alias'] ),
					$where_sql,
					$order_sql,
					$limit_sql
				);
			}
		} else {
			$projection_end = $select_end;
		}

		$projection = $this->split_top_level_mysql_arguments( $tokens, $projection_start, $projection_end );
		if ( null === $projection || 1 !== count( $projection ) ) {
			return null;
		}

		if ( ! $this->is_supported_simple_mysql_expression_fragment( $tokens, $projection[0]['start'], $projection[0]['end'] ) ) {
			return null;
		}

		$expression_sql = $this->translate_mysql_expression_token_sequence_to_postgresql(
			$tokens,
			$projection[0]['start'],
			$projection[0]['end'],
			$scope
		);

		return sprintf(
			'(SELECT %s)',
			$expression_sql['sql']
		);
	}

	/**
	 * Get PostgreSQL SQL for a supported table-backed scalar subquery projection.
	 *
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param int              $start      First projection token.
	 * @param int              $end        Final projection token, exclusive.
	 * @param string           $table_name Subquery source table name.
	 * @param string|null      $alias      Optional subquery source alias.
	 * @param array            $scope      Subquery source table scope.
	 * @return string|null PostgreSQL projection SQL, or null when unsupported.
	 */
	private function get_mysql_upsert_table_scalar_subquery_projection_sql( array $tokens, int $start, int $end, string $table_name, ?string $alias, array $scope ): ?string {
		$count_sql = $this->get_mysql_upsert_count_subquery_projection_sql( $tokens, $start, $end, $table_name, $alias );
		if ( null !== $count_sql ) {
			return $count_sql;
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $start, $end );
		if (
			null === $reference
			|| $reference['end'] !== $end
			|| null === $this->get_mysql_column_type_for_reference( $reference, $scope )
		) {
			return null;
		}

		return $this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] );
	}

	/**
	 * Get PostgreSQL SQL for a supported table-backed COUNT() scalar subquery projection.
	 *
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param int              $start      First projection token.
	 * @param int              $end        Final projection token, exclusive.
	 * @param string           $table_name Subquery source table name.
	 * @param string|null      $alias      Optional subquery source alias.
	 * @return string|null PostgreSQL COUNT() SQL, or null when unsupported.
	 */
	private function get_mysql_upsert_count_subquery_projection_sql( array $tokens, int $start, int $end, string $table_name, ?string $alias ): ?string {
		if (
			! isset( $tokens[ $start ], $tokens[ $start + 1 ] )
			|| WP_MySQL_Lexer::COUNT_SYMBOL !== $tokens[ $start ]->id
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $start + 1 ]->id
		) {
			return null;
		}

		$after_count = $this->get_mysql_parenthesized_sequence_end( $tokens, $start + 1, $end );
		if ( null === $after_count || $after_count !== $end ) {
			return null;
		}

		$argument_start = $start + 2;
		$argument_end   = $after_count - 1;
		if (
			$argument_start + 1 === $argument_end
			&& WP_MySQL_Lexer::MULT_OPERATOR === ( $tokens[ $argument_start ]->id ?? null )
		) {
			return 'COUNT(*)';
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $argument_start, $argument_end );
		if ( null === $reference || $reference['end'] !== $argument_end ) {
			return null;
		}

		if ( null === $this->get_mysql_table_column_type( 'public', $table_name, $reference['column'] ) ) {
			return null;
		}

		$qualifier = null;
		if ( null !== $reference['qualifier'] ) {
			if ( null !== $alias ) {
				if ( 0 !== strcasecmp( $reference['qualifier'], $alias ) ) {
					return null;
				}

				$qualifier = $alias;
			} else {
				if ( 0 !== strcasecmp( $reference['qualifier'], $table_name ) ) {
					return null;
				}

				$qualifier = $table_name;
			}
		}

		return sprintf(
			'COUNT(%s)',
			$this->get_postgresql_dml_column_reference_sql( $reference['column'], $qualifier )
		);
	}

	/**
	 * Get the columns accepted by MySQL VALUES(column) in an upsert assignment.
	 *
	 * MySQL permits VALUES(column) for omitted table columns; PostgreSQL's
	 * excluded row has those defaulted/null values as well. VALUES-row aliases
	 * remain constrained separately to the explicit INSERT column list.
	 *
	 * @param array $column_lookup       Insert-column lookup by lowercase name.
	 * @param array $table_column_lookup Table-column metadata lookup by lowercase name.
	 * @return array<string,string> Lookup of lowercase column name to canonical column name.
	 */
	private function get_mysql_upsert_values_column_lookup( array $column_lookup, array $table_column_lookup ): array {
		$values_column_lookup = array();
		foreach ( $column_lookup as $column_key => $column_name ) {
			$values_column_lookup[ strtolower( (string) $column_key ) ] = is_string( $column_name )
				? $column_name
				: (string) $column_key;
		}

		foreach ( $table_column_lookup as $column_key => $column_metadata ) {
			if ( isset( $values_column_lookup[ strtolower( (string) $column_key ) ] ) ) {
				continue;
			}

			$column_name = (string) ( $column_metadata['column_name'] ?? '' );
			if ( '' === $column_name ) {
				continue;
			}

			$values_column_lookup[ strtolower( $column_name ) ] = $column_name;
		}

		return $values_column_lookup;
	}

	/**
	 * Get the source column from a supported VALUES(column) upsert assignment expression.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $start         First expression token.
	 * @param int              $end           Final expression token, exclusive.
	 * @param array            $column_lookup VALUES-column lookup by lowercase name.
	 * @param array            $source_aliases Optional VALUES-row alias lookup.
	 * @return string|null Source column name, or null when the expression is not VALUES(column).
	 */
	private function get_mysql_upsert_values_assignment_source_column( array $tokens, int $start, int $end, array $column_lookup, array $source_aliases = array() ): ?string {
		if (
			$start + 4 === $end
			&& isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ], $tokens[ $start + 3 ] )
			&& WP_MySQL_Lexer::VALUES_SYMBOL === $tokens[ $start ]->id
			&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $start + 1 ]->id
			&& WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $start + 3 ]->id
		) {
			$source_column = $this->get_mysql_dml_identifier_token_value( $tokens[ $start + 2 ] );
			$source_key    = null === $source_column ? null : strtolower( $source_column );
			if ( null === $source_key || ! isset( $column_lookup[ $source_key ] ) ) {
				return null;
			}

			return is_string( $column_lookup[ $source_key ] ) ? $column_lookup[ $source_key ] : $source_column;
		}

		return $this->get_mysql_upsert_alias_assignment_source_column( $tokens, $start, $end, $source_aliases );
	}

	/**
	 * Get replacements for supported VALUES(column) references in an upsert expression.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $start         First expression token.
	 * @param int              $end           Final expression token, exclusive.
	 * @param array            $column_lookup VALUES-column lookup by lowercase name.
	 * @param array            $source_aliases Optional VALUES-row alias lookup.
	 * @return array[]|null Replacement ranges, or null when VALUES() is malformed/unsupported.
	 */
	private function get_mysql_upsert_values_expression_replacements( array $tokens, int $start, int $end, array $column_lookup, array $source_aliases = array() ): ?array {
		$replacements = array();

		for ( $position = $start; $position < $end; $position++ ) {
			if ( WP_MySQL_Lexer::VALUES_SYMBOL === $tokens[ $position ]->id ) {
				if (
					$position + 4 > $end
					|| ! isset( $tokens[ $position + 1 ], $tokens[ $position + 2 ], $tokens[ $position + 3 ] )
					|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position + 1 ]->id
					|| WP_MySQL_Lexer::CLOSE_PAR_SYMBOL !== $tokens[ $position + 3 ]->id
				) {
					return null;
				}

				$source_column = $this->get_mysql_dml_identifier_token_value( $tokens[ $position + 2 ] );
				$source_key    = null === $source_column ? null : strtolower( $source_column );
				if ( null === $source_key || ! isset( $column_lookup[ $source_key ] ) ) {
					return null;
				}
				$source_column = is_string( $column_lookup[ $source_key ] ) ? $column_lookup[ $source_key ] : $source_column;

				$replacements[] = array(
					'start' => $position,
					'end'   => $position + 4,
					'sql'   => sprintf(
						'excluded.%s',
						$this->connection->quote_identifier( $source_column )
					),
				);
				$position      += 3;
				continue;
			}

			$alias_reference = $this->get_mysql_upsert_alias_expression_reference( $tokens, $position, $start, $end, $source_aliases );
			if ( null === $alias_reference ) {
				continue;
			}

			if ( false === $alias_reference ) {
				return null;
			}

			$replacements[] = array(
				'start' => $position,
				'end'   => $alias_reference['end'],
				'sql'   => sprintf(
					'excluded.%s',
					$this->connection->quote_identifier( $alias_reference['column'] )
				),
			);
			$position      = $alias_reference['end'] - 1;
		}

		return $replacements;
	}

	/**
	 * Get an exact alias source column from an upsert assignment expression.
	 *
	 * @param WP_MySQL_Token[] $tokens         MySQL lexer token stream.
	 * @param int              $start          First expression token.
	 * @param int              $end            Final expression token, exclusive.
	 * @param array            $source_aliases Optional VALUES-row alias lookup.
	 * @return string|null Source column name, or null when the expression is not an alias reference.
	 */
	private function get_mysql_upsert_alias_assignment_source_column( array $tokens, int $start, int $end, array $source_aliases ): ?string {
		$reference = $this->get_mysql_upsert_alias_expression_reference( $tokens, $start, $start, $end, $source_aliases );
		if ( ! is_array( $reference ) || $reference['end'] !== $end ) {
			return null;
		}

		return $reference['column'];
	}

	/**
	 * Resolve a VALUES-row alias reference inside an upsert expression.
	 *
	 * @param WP_MySQL_Token[] $tokens         MySQL lexer token stream.
	 * @param int              $position       Candidate reference position.
	 * @param int              $start          First expression token.
	 * @param int              $end            Final expression token, exclusive.
	 * @param array            $source_aliases Optional VALUES-row alias lookup.
	 * @return array{column: string, end: int}|false|null Reference data, false for malformed alias use, or null when not an alias reference.
	 */
	private function get_mysql_upsert_alias_expression_reference( array $tokens, int $position, int $start, int $end, array $source_aliases ) {
		if ( empty( $source_aliases ) || ! isset( $tokens[ $position ] ) ) {
			return null;
		}

		$identifier = $this->get_mysql_dml_identifier_token_value( $tokens[ $position ] );
		if ( null === $identifier ) {
			return null;
		}

		$identifier_key = strtolower( $identifier );
		if ( $identifier_key === ( $source_aliases['row'] ?? null ) ) {
			if (
				$position + 2 >= $end
				|| WP_MySQL_Lexer::DOT_SYMBOL !== ( $tokens[ $position + 1 ]->id ?? null )
			) {
				return false;
			}

			$source_column = $this->get_mysql_dml_identifier_token_value( $tokens[ $position + 2 ] ?? null );
			if ( null === $source_column ) {
				return false;
			}

			$source_key = strtolower( $source_column );
			if ( ! isset( $source_aliases['qualified'][ $source_key ] ) ) {
				return false;
			}

			return array(
				'column' => $source_aliases['qualified'][ $source_key ],
				'end'    => $position + 3,
			);
		}

		if (
			isset( $source_aliases['unqualified'][ $identifier_key ] )
			&& ( $position <= $start || WP_MySQL_Lexer::DOT_SYMBOL !== ( $tokens[ $position - 1 ]->id ?? null ) )
			&& ( $position + 1 >= $end || WP_MySQL_Lexer::DOT_SYMBOL !== ( $tokens[ $position + 1 ]->id ?? null ) )
			&& ( $position + 1 >= $end || WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== ( $tokens[ $position + 1 ]->id ?? null ) )
		) {
			return array(
				'column' => $source_aliases['unqualified'][ $identifier_key ],
				'end'    => $position + 1,
			);
		}

		return null;
	}

	/**
	 * Check whether an upsert expression is simple after removing VALUES(column) ranges.
	 *
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int              $start        First expression token.
	 * @param int              $end          Final expression token, exclusive.
	 * @param array[]          $replacements VALUES(column) replacement ranges.
	 * @return bool Whether the expression is supported.
	 */
	private function is_supported_simple_mysql_upsert_expression_fragment( array $tokens, int $start, int $end, array $replacements ): bool {
		$segment_start = $start;
		foreach ( $replacements as $replacement ) {
			if (
				$segment_start < $replacement['start']
				&& ! $this->is_supported_simple_mysql_upsert_expression_segment( $tokens, $segment_start, $replacement['start'] )
			) {
				return false;
			}

			$segment_start = $replacement['end'];
		}

		return $segment_start >= $end
			|| $this->is_supported_simple_mysql_upsert_expression_segment( $tokens, $segment_start, $end );
	}

	/**
	 * Check whether an upsert expression segment contains supported tokens.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First segment token.
	 * @param int              $end    Final segment token, exclusive.
	 * @return bool Whether the segment is supported.
	 */
	private function is_supported_simple_mysql_upsert_expression_segment( array $tokens, int $start, int $end ): bool {
		for ( $position = $start; $position < $end; $position++ ) {
			if ( WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT === $tokens[ $position ]->id ) {
				continue;
			}

			if ( ! $this->is_supported_simple_mysql_expression_token( $tokens[ $position ] ) ) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Validate the narrow SET clause supported by the simple UPDATE translator.
	 *
	 * @param string           $table_name Table name.
	 * @param string|null      $alias      Optional table alias.
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param int              $start      First SET-clause token position.
	 * @param int              $end        Final SET-clause token position, exclusive.
	 * @return bool Whether the SET clause is supported.
	 */
	private function is_supported_simple_update_set_clause( string $table_name, ?string $alias, array $tokens, int $start, int $end ): bool {
		for ( $position = $start; $position < $end; ) {
			$target = $this->parse_simple_mysql_update_assignment_target( $table_name, $alias, $tokens, $position, $end );
			if ( null === $target || ! isset( $tokens[ $target['end'] ] ) || WP_MySQL_Lexer::EQUAL_OPERATOR !== $tokens[ $target['end'] ]->id ) {
				return false;
			}

			$value_start    = $target['end'] + 1;
			$assignment_end = $this->find_top_level_mysql_token(
				$tokens,
				WP_MySQL_Lexer::COMMA_SYMBOL,
				$value_start,
				$end
			) ?? $end;

			if (
				$value_start >= $assignment_end
				|| ! $this->is_supported_simple_mysql_expression_fragment( $tokens, $value_start, $assignment_end )
			) {
				return false;
			}

			$position = $assignment_end;
			if ( $position === $end ) {
				return true;
			}

			++$position;
		}

		return false;
	}

	/**
	 * Validate a simple SELECT projection list.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection token position.
	 * @param int             $end    Final projection token position, exclusive.
	 * @return bool Whether the projection is supported.
	 */
	private function is_supported_simple_select_projection( array $tokens, int $start, int $end ): bool {
		if ( $start + 1 === $end && WP_MySQL_Lexer::MULT_OPERATOR === $tokens[ $start ]->id ) {
			return true;
		}

		if ( $this->is_supported_simple_select_count_projection( $tokens, $start, $end ) ) {
			return true;
		}

		for ( $i = $start; $i < $end; $i++ ) {
			if ( null === $this->get_mysql_identifier_token_value( $tokens[ $i ] ?? null ) ) {
				return false;
			}

			++$i;
			if ( $i >= $end ) {
				return true;
			}

			if ( WP_MySQL_Lexer::COMMA_SYMBOL !== $tokens[ $i ]->id ) {
				return false;
			}
		}

		return false;
	}

	/**
	 * Validate the supported COUNT(identifier) projection shape.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection token position.
	 * @param int             $end    Final projection token position, exclusive.
	 * @return bool Whether the aggregate projection is supported.
	 */
	private function is_supported_simple_select_count_projection( array $tokens, int $start, int $end ): bool {
		if (
			! isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ], $tokens[ $start + 3 ] )
			|| WP_MySQL_Lexer::COUNT_SYMBOL !== $tokens[ $start ]->id
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $start + 1 ]->id
			|| null === $this->get_mysql_identifier_token_value( $tokens[ $start + 2 ] )
			|| WP_MySQL_Lexer::CLOSE_PAR_SYMBOL !== $tokens[ $start + 3 ]->id
		) {
			return false;
		}

		if ( $start + 4 === $end ) {
			return true;
		}

		return $start + 6 === $end
			&& WP_MySQL_Lexer::AS_SYMBOL === $tokens[ $start + 4 ]->id
			&& null !== $this->get_mysql_identifier_token_value( $tokens[ $start + 5 ] );
	}

	/**
	 * Translate a supported simple SELECT projection to PostgreSQL.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First projection token position.
	 * @param int             $end    Final projection token position, exclusive.
	 * @return string PostgreSQL projection SQL.
	 */
	private function translate_simple_select_projection_to_postgresql( array $tokens, int $start, int $end ): string {
		if ( $this->is_supported_simple_select_count_projection( $tokens, $start, $end ) ) {
			$sql = sprintf(
				'COUNT(%s)',
				$this->translate_mysql_identifier_token_to_postgresql( $tokens[ $start + 2 ] )
			);

			if ( $start + 6 === $end ) {
				$sql .= ' ' . $tokens[ $start + 4 ]->get_bytes() . ' ' . $this->translate_mysql_identifier_token_to_postgresql( $tokens[ $start + 5 ] );
			}

			return $sql;
		}

		return $this->translate_mysql_token_sequence_to_postgresql( $tokens, $start, $end );
	}

	/**
	 * Translate a SELECT while applying metadata-backed expression coercions.
	 *
	 * @param WP_MySQL_Token[] $tokens                   MySQL lexer token stream.
	 * @param int             $projection_start         First token after SELECT modifiers to render.
	 * @param int             $statement_end            Final statement token position, exclusive.
	 * @param bool            $require_contextual_change Whether unchanged statements should fall through.
	 * @return string|null PostgreSQL SELECT SQL, or null when no safe contextual translation applies.
	 */
	private function translate_mysql_select_statement_with_integer_string_coercion(
		array $tokens,
		int $projection_start,
		int $statement_end,
		bool $require_contextual_change
	): ?string {
		$replacements = $this->get_mysql_select_statement_contextual_replacements(
			$tokens,
			$projection_start,
			$statement_end
		);
		if ( null === $replacements ) {
			return null;
		}

		if ( $require_contextual_change && empty( $replacements ) ) {
			return null;
		}

		return 'SELECT ' . $this->translate_mysql_token_sequence_with_replacements_to_postgresql(
			$tokens,
			$projection_start,
			$statement_end,
			$replacements
		);
	}

	/**
	 * Get metadata-backed replacements for SELECT WHERE and ORDER BY clauses.
	 *
	 * @param WP_MySQL_Token[] $tokens           MySQL lexer token stream.
	 * @param int              $projection_start First token after SELECT modifiers to render.
	 * @param int              $statement_end    Final statement token position, exclusive.
	 * @return array[]|null Replacement ranges, or null when contextual rewriting is unavailable.
	 */
	private function get_mysql_select_statement_contextual_replacements(
		array $tokens,
		int $projection_start,
		int $statement_end
	): ?array {
		$where_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::WHERE_SYMBOL,
			$projection_start,
			$statement_end
		);
		$order_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::ORDER_SYMBOL,
			$projection_start,
			$statement_end
		);
		if ( null === $where_position && null === $order_position ) {
			return null;
		}

		$first_clause_position = min( array_filter( array( $where_position, $order_position ), 'is_int' ) );
		$from_position         = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::FROM_SYMBOL,
			$projection_start,
			$first_clause_position
		);
		if ( null === $from_position ) {
			return null;
		}

		$from_end = $this->find_first_top_level_mysql_token(
			$tokens,
			array(
				WP_MySQL_Lexer::FOR_SYMBOL,
				WP_MySQL_Lexer::GROUP_SYMBOL,
				WP_MySQL_Lexer::HAVING_SYMBOL,
				WP_MySQL_Lexer::LIMIT_SYMBOL,
				WP_MySQL_Lexer::LOCK_SYMBOL,
				WP_MySQL_Lexer::ORDER_SYMBOL,
				WP_MySQL_Lexer::PROCEDURE_SYMBOL,
				WP_MySQL_Lexer::UNION_SYMBOL,
				WP_MySQL_Lexer::WHERE_SYMBOL,
			),
			$from_position + 1,
			$statement_end
		) ?? $statement_end;

		$scope = $this->get_mysql_select_scope( $tokens, $from_position + 1, $from_end );
		if ( null === $scope ) {
			return null;
		}

		$replacements = $this->get_mysql_select_projection_contextual_replacements(
			$tokens,
			$projection_start,
			$from_position,
			$scope
		);
		if ( null === $replacements ) {
			return null;
		}

		if ( null !== $where_position ) {
			$where_end = $this->find_first_top_level_mysql_token(
				$tokens,
				array(
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::GROUP_SYMBOL,
					WP_MySQL_Lexer::HAVING_SYMBOL,
					WP_MySQL_Lexer::LIMIT_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::ORDER_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				),
				$where_position + 1,
				$statement_end
			) ?? $statement_end;

			$where_sql = $this->translate_mysql_predicate_token_sequence_to_postgresql(
				$tokens,
				$where_position + 1,
				$where_end,
				$scope
			);
			if ( $where_sql['changed'] ) {
				$replacements[] = array(
					'start' => $where_position + 1,
					'end'   => $where_end,
					'sql'   => $where_sql['sql'],
				);
			}
		}

		if (
			null !== $order_position
			&& isset( $tokens[ $order_position + 1 ] )
			&& WP_MySQL_Lexer::BY_SYMBOL === $tokens[ $order_position + 1 ]->id
		) {
			$order_end = $this->find_first_top_level_mysql_token(
				$tokens,
				array(
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::LIMIT_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				),
				$order_position + 2,
				$statement_end
			) ?? $statement_end;

			$order_sql = $this->translate_mysql_order_by_token_sequence_to_postgresql(
				$tokens,
				$order_position + 2,
				$order_end,
				$scope,
				! $this->contains_top_level_mysql_token(
					$tokens,
					$projection_start,
					$statement_end,
					array(
						WP_MySQL_Lexer::DISTINCT_SYMBOL,
						WP_MySQL_Lexer::GROUP_SYMBOL,
						WP_MySQL_Lexer::HAVING_SYMBOL,
					)
				)
			);
			if ( $order_sql['changed'] ) {
				$replacements[] = array(
					'start' => $order_position + 2,
					'end'   => $order_end,
					'sql'   => $order_sql['sql'],
				);
			}
		}

		return $replacements;
	}

	/**
	 * Get metadata-backed replacements for SELECT projection expressions.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First projection token position.
	 * @param int              $end    FROM token position.
	 * @param array            $scope  Statement table scope.
	 * @return array[]|null Replacement ranges, or null when projection parsing fails.
	 */
	private function get_mysql_select_projection_contextual_replacements( array $tokens, int $start, int $end, array $scope ): ?array {
		$ranges = $this->split_top_level_mysql_arguments( $tokens, $start, $end );
		if ( null === $ranges ) {
			return null;
		}

		$replacements = array();
		foreach ( $ranges as $range ) {
			$expression_start = $range['start'];
			$expression_end   = $range['end'];
			$projection_item  = $this->parse_mysql_select_projection_item( $tokens, $range['start'], $range['end'] );
			if ( null !== $projection_item ) {
				$expression_start = $projection_item['expression_start'];
				$expression_end   = $projection_item['expression_end'];
			}

			$replacement_sql = $this->translate_mysql_sum_text_column_aggregate_to_postgresql(
				$tokens,
				$expression_start,
				$expression_end,
				$scope
			);
			if ( null === $replacement_sql ) {
				continue;
			}

			$replacements[] = array(
				'start' => $expression_start,
				'end'   => $expression_end,
				'sql'   => $replacement_sql,
			);
		}

		return $replacements;
	}

	/**
	 * Translate SUM(text_column) with MySQL numeric text coercion.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First projection expression token.
	 * @param int              $end    Final projection expression token, exclusive.
	 * @param array            $scope  Statement table scope.
	 * @return string|null PostgreSQL aggregate SQL, or null when unsupported.
	 */
	private function translate_mysql_sum_text_column_aggregate_to_postgresql( array $tokens, int $start, int $end, array $scope ): ?string {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start  = $bounds['start'];
		$end    = $bounds['end'];

		if (
			$start + 4 > $end
			|| ! isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $end - 1 ] )
			|| WP_MySQL_Lexer::SUM_SYMBOL !== $tokens[ $start ]->id
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $start + 1 ]->id
			|| WP_MySQL_Lexer::CLOSE_PAR_SYMBOL !== $tokens[ $end - 1 ]->id
		) {
			return null;
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $start + 2, $end - 1 );
		if (
			null === $reference
			|| $reference['end'] !== $end - 1
			|| ! $this->is_mysql_text_family_column_reference( $reference, $scope )
		) {
			return null;
		}

		return sprintf(
			'SUM(%s)',
			$this->get_postgresql_mysql_numeric_cast_sql(
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] )
			)
		);
	}

	/**
	 * Translate tokens while replacing known bounded token ranges.
	 *
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int             $start        First token position.
	 * @param int             $end          Final token position, exclusive.
	 * @param array[]         $replacements Replacement ranges with translated SQL.
	 * @return string PostgreSQL SQL fragment.
	 */
	private function translate_mysql_token_sequence_with_replacements_to_postgresql(
		array $tokens,
		int $start,
		int $end,
		array $replacements
	): string {
		$chunks   = array();
		$position = $start;

		foreach ( $replacements as $replacement ) {
			if ( $position < $replacement['start'] ) {
				$chunks[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $position, $replacement['start'] );
			}

			$chunks[] = $replacement['sql'];
			$position = $replacement['end'];
		}

		if ( $position < $end ) {
			$chunks[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $position, $end );
		}

		return implode( ' ', array_filter( $chunks, 'strlen' ) );
	}

	/**
	 * Get the original SQL text for a token range.
	 *
	 * @param string           $query  Original MySQL query.
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token position.
	 * @param int              $end    Final token position, exclusive.
	 * @return string|null Query slice, or null when the range is invalid.
	 */
	private function get_mysql_token_range_sql( string $query, array $tokens, int $start, int $end ): ?string {
		if ( $start >= $end || ! isset( $tokens[ $start ], $tokens[ $end - 1 ] ) ) {
			return null;
		}

		$range_start = $tokens[ $start ]->start;
		$last_token  = $tokens[ $end - 1 ];
		$range_end   = $last_token->start + $last_token->length;

		return substr( $query, $range_start, $range_end - $range_start );
	}

	/**
	 * Translate ORDER BY items with metadata-backed expression coercions.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First ORDER BY item token position.
	 * @param int             $end    Final ORDER BY token position, exclusive.
	 * @param array           $scope  Statement table scope.
	 * @param bool            $allow_wordpress_posts_id_tiebreaker Whether to add WordPress posts ID tie-breakers.
	 * @return array{sql: string, changed: bool} Translated ORDER BY SQL and change flag.
	 */
	private function translate_mysql_order_by_token_sequence_to_postgresql(
		array $tokens,
		int $start,
		int $end,
		array $scope,
		bool $allow_wordpress_posts_id_tiebreaker
	): array {
		$order_items = $this->parse_mysql_select_order_by_items( $tokens, $start, $end, array(), $scope );
		if ( null === $order_items ) {
			return array(
				'sql'     => $this->translate_mysql_token_sequence_to_postgresql( $tokens, $start, $end ),
				'changed' => false,
			);
		}

		$changed   = false;
		$order_sql = array();
		foreach ( $order_items as $order_item ) {
			$changed = $changed || $order_item['changed'];

			$item_sql = $order_item['sql'];
			if ( $order_item['direction_explicit'] ) {
				$item_sql .= ' ' . $order_item['direction'];
			}

			$order_sql[] = $item_sql;
		}

		$tiebreaker_sql = null;
		if ( $allow_wordpress_posts_id_tiebreaker ) {
			$tiebreaker_sql = $this->get_wordpress_posts_post_date_desc_order_id_tiebreaker_sql( $tokens, $order_items, $scope );
			if ( null === $tiebreaker_sql ) {
				$tiebreaker_sql = $this->get_wordpress_posts_menu_order_title_order_id_tiebreaker_sql( $tokens, $order_items, $scope );
			}
		}
		if ( null !== $tiebreaker_sql ) {
			$order_sql[] = $tiebreaker_sql;
			$changed     = true;
		}

		return array(
			'sql'     => $changed
				? implode( ', ', $order_sql )
				: $this->translate_mysql_token_sequence_to_postgresql( $tokens, $start, $end ),
			'changed' => $changed,
		);
	}

	/**
	 * Get the MySQL-compatible posts date tie-breaker for a simple SELECT.
	 *
	 * WordPress's posts table has the MySQL type_status_date index ending in ID.
	 * MySQL scans that index backward for default post_date DESC queries, so rows
	 * with equal post_date values are returned by descending ID.
	 *
	 * @param WP_MySQL_Token[] $tokens         MySQL lexer token stream.
	 * @param string          $table_name     Selected table name.
	 * @param int             $order_position ORDER token position.
	 * @param int             $end            Final ORDER BY token position, exclusive.
	 * @return string|null PostgreSQL ORDER BY item SQL, or null when not applicable.
	 */
	private function get_simple_wordpress_posts_post_date_desc_order_id_tiebreaker_sql(
		array $tokens,
		string $table_name,
		int $order_position,
		int $end
	): ?string {
		if (
			! $this->is_mysql_wordpress_table_name( $table_name, 'posts' )
			|| $order_position + 4 !== $end
			|| ! $this->is_mysql_identifier_like_token_value( $tokens[ $order_position + 2 ] ?? null, 'post_date' )
			|| ! isset( $tokens[ $order_position + 3 ] )
			|| WP_MySQL_Lexer::DESC_SYMBOL !== $tokens[ $order_position + 3 ]->id
		) {
			return null;
		}

		return $this->connection->quote_identifier( 'ID' ) . ' DESC';
	}

	/**
	 * Get the MySQL-compatible approved-comments date tie-breaker.
	 *
	 * get_approved_comments() orders by comment_date_gmt only. MySQL returns
	 * equal-date rows in comment_ID order for WordPress's comments table shape,
	 * so make that ordering explicit for PostgreSQL.
	 *
	 * @param WP_MySQL_Token[] $tokens         MySQL lexer token stream.
	 * @param string           $table_name     Selected table name.
	 * @param int|null         $where_position WHERE token position, or null.
	 * @param int|null         $where_end      Final WHERE token position, exclusive.
	 * @param int              $order_position ORDER token position.
	 * @param int              $end            Final ORDER BY token position, exclusive.
	 * @return string|null PostgreSQL ORDER BY item SQL, or null when not applicable.
	 */
	private function get_simple_wordpress_approved_comments_order_tiebreaker_sql(
		array $tokens,
		string $table_name,
		?int $where_position,
		?int $where_end,
		int $order_position,
		int $end
	): ?string {
		if (
			! $this->is_mysql_wordpress_table_name( $table_name, 'comments' )
			|| null === $where_position
			|| null === $where_end
			|| ! $this->is_simple_wordpress_approved_comments_where_clause( $tokens, $where_position + 1, $where_end )
		) {
			return null;
		}

		$order_items = $this->split_top_level_mysql_arguments( $tokens, $order_position + 2, $end );
		if ( null === $order_items || 1 !== count( $order_items ) ) {
			return null;
		}

		$order_item = $order_items[0];
		$direction  = 'ASC';
		$item_end   = $order_item['end'];
		if ( isset( $tokens[ $item_end - 1 ] ) ) {
			if ( WP_MySQL_Lexer::DESC_SYMBOL === $tokens[ $item_end - 1 ]->id ) {
				return null;
			}
			if ( WP_MySQL_Lexer::ASC_SYMBOL === $tokens[ $item_end - 1 ]->id ) {
				$item_end  = $item_end - 1;
				$direction = 'ASC';
			}
		}

		if (
			'ASC' !== $direction
			|| ! $this->is_mysql_column_reference_expression(
				$tokens,
				$order_item['start'],
				$item_end,
				'comment_date_gmt',
				'comments',
				true
			)
		) {
			return null;
		}

		return $this->connection->quote_identifier( 'comment_ID' ) . ' ASC';
	}

	/**
	 * Check for get_approved_comments()'s single-post approved comments filter.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First WHERE predicate token.
	 * @param int              $end    Final WHERE predicate token, exclusive.
	 * @return bool Whether the WHERE clause matches the approved-comments shape.
	 */
	private function is_simple_wordpress_approved_comments_where_clause( array $tokens, int $start, int $end ): bool {
		$conjuncts = $this->split_mysql_top_level_boolean_conjuncts( $tokens, $start, $end );
		if ( null === $conjuncts ) {
			return false;
		}

		$has_post_id  = false;
		$has_approved = false;
		foreach ( $conjuncts as $conjunct ) {
			$match = $this->get_simple_wordpress_comments_literal_equality(
				$tokens,
				$conjunct['start'],
				$conjunct['end']
			);
			if ( null === $match ) {
				continue;
			}

			if ( 'comment_post_id' === $match['column'] ) {
				$has_post_id = true;
				continue;
			}

			if ( 'comment_approved' === $match['column'] && '1' === $match['value'] ) {
				$has_approved = true;
			}
		}

		return $has_post_id && $has_approved;
	}

	/**
	 * Parse a comments-table column = literal predicate.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First predicate token.
	 * @param int              $end    Final predicate token, exclusive.
	 * @return array{column: string, value: string}|null Parsed column and literal value.
	 */
	private function get_simple_wordpress_comments_literal_equality( array $tokens, int $start, int $end ): ?array {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start  = $bounds['start'];
		$end    = $bounds['end'];

		$equal_position = $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::EQUAL_OPERATOR, $start, $end );
		if (
			null === $equal_position
			|| null !== $this->find_top_level_mysql_token( $tokens, WP_MySQL_Lexer::EQUAL_OPERATOR, $equal_position + 1, $end )
		) {
			return null;
		}

		$match = $this->get_simple_wordpress_comments_literal_equality_side(
			$tokens,
			$start,
			$equal_position,
			$equal_position + 1,
			$end
		);
		if ( null !== $match ) {
			return $match;
		}

		return $this->get_simple_wordpress_comments_literal_equality_side(
			$tokens,
			$equal_position + 1,
			$end,
			$start,
			$equal_position
		);
	}

	/**
	 * Parse one column/literal side of a comments-table equality predicate.
	 *
	 * @param WP_MySQL_Token[] $tokens        MySQL lexer token stream.
	 * @param int              $column_start  First column token.
	 * @param int              $column_end    Final column token, exclusive.
	 * @param int              $literal_start First literal token.
	 * @param int              $literal_end   Final literal token, exclusive.
	 * @return array{column: string, value: string}|null Parsed column and literal value.
	 */
	private function get_simple_wordpress_comments_literal_equality_side(
		array $tokens,
		int $column_start,
		int $column_end,
		int $literal_start,
		int $literal_end
	): ?array {
		$reference = $this->parse_mysql_column_reference( $tokens, $column_start, $column_end );
		if (
			null === $reference
			|| $reference['end'] !== $column_end
			|| (
				null !== $reference['qualifier']
				&& ! $this->is_mysql_wordpress_table_name( $reference['qualifier'], 'comments' )
			)
		) {
			return null;
		}

		$literal = $this->get_simple_wordpress_comments_literal_value( $tokens, $literal_start, $literal_end );
		if ( null === $literal ) {
			return null;
		}

		return array(
			'column' => strtolower( $reference['column'] ),
			'value'  => $literal,
		);
	}

	/**
	 * Get a supported literal value for the approved-comments WHERE predicate.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First literal token.
	 * @param int              $end    Final literal token, exclusive.
	 * @return string|null Literal value, "literal" for unconstrained post IDs, or null.
	 */
	private function get_simple_wordpress_comments_literal_value( array $tokens, int $start, int $end ): ?string {
		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		$start  = $bounds['start'];
		$end    = $bounds['end'];

		if ( $this->is_mysql_string_literal_range( $tokens, $start, $end ) ) {
			return $tokens[ $start ]->get_value();
		}

		$literal = $this->parse_mysql_numeric_literal( $tokens, $start, $end );
		if ( null !== $literal && $literal['end'] === $end ) {
			return 'literal';
		}

		return null;
	}

	/**
	 * Get the MySQL-compatible posts date tie-breaker for a parsed ORDER BY.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param array           $order_items Parsed ORDER BY items.
	 * @param array           $scope       Statement table scope.
	 * @return string|null PostgreSQL ORDER BY item SQL, or null when not applicable.
	 */
	private function get_wordpress_posts_post_date_desc_order_id_tiebreaker_sql( array $tokens, array $order_items, array $scope ): ?string {
		if (
			1 !== count( $order_items )
			|| ! empty( $scope['unknown'] )
			|| 1 !== count( $scope['tables'] )
			|| 'DESC' !== $order_items[0]['direction']
		) {
			return null;
		}

		$order_item = $order_items[0];
		$reference  = $this->parse_mysql_column_reference(
			$tokens,
			$order_item['expression_start'],
			$order_item['expression_end']
		);
		if (
			null === $reference
			|| $reference['end'] !== $order_item['expression_end']
			|| 'post_date' !== strtolower( $reference['column'] )
		) {
			return null;
		}

		$table = $this->get_mysql_single_scope_table_for_column_reference( $reference, $scope );
		if ( null === $table || ! $this->is_mysql_wordpress_table_name( $table['table'], 'posts' ) ) {
			return null;
		}

		if ( null !== $reference['qualifier'] ) {
			return sprintf(
				'%s.%s DESC',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['start'] + 1 ),
				$this->connection->quote_identifier( 'ID' )
			);
		}

		return $this->connection->quote_identifier( 'ID' ) . ' DESC';
	}

	/**
	 * Get the MySQL-compatible posts title tie-breaker for admin page searches.
	 *
	 * MySQL returns tied page rows for WordPress's menu_order/title ordering in
	 * primary-key order. PostgreSQL may return those ties in physical order,
	 * which changes the parent group selected by WP_Posts_List_Table paging.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param array           $order_items Parsed ORDER BY items.
	 * @param array           $scope       Statement table scope.
	 * @return string|null PostgreSQL ORDER BY item SQL, or null when not applicable.
	 */
	private function get_wordpress_posts_menu_order_title_order_id_tiebreaker_sql( array $tokens, array $order_items, array $scope ): ?string {
		if (
			2 !== count( $order_items )
			|| ! empty( $scope['unknown'] )
			|| 1 !== count( $scope['tables'] )
		) {
			return null;
		}

		$expected_columns = array( 'menu_order', 'post_title' );
		$references       = array();
		$matched_table    = null;
		foreach ( $expected_columns as $index => $expected_column ) {
			if ( 'ASC' !== $order_items[ $index ]['direction'] ) {
				return null;
			}

			$reference = $this->parse_mysql_column_reference(
				$tokens,
				$order_items[ $index ]['expression_start'],
				$order_items[ $index ]['expression_end']
			);
			if (
				null === $reference
				|| $reference['end'] !== $order_items[ $index ]['expression_end']
				|| strtolower( $reference['column'] ) !== $expected_column
			) {
				return null;
			}

			$table = $this->get_mysql_single_scope_table_for_column_reference( $reference, $scope );
			if ( null === $table || ! $this->is_mysql_wordpress_table_name( $table['table'], 'posts' ) ) {
				return null;
			}

			if ( null !== $matched_table && $matched_table !== $table ) {
				return null;
			}

			$matched_table = $table;
			$references[]  = $reference;
		}

		$qualifier_reference = null !== $references[0]['qualifier'] ? $references[0] : $references[1];
		if ( null !== $qualifier_reference['qualifier'] ) {
			return sprintf(
				'%s.%s ASC',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $qualifier_reference['start'], $qualifier_reference['start'] + 1 ),
				$this->connection->quote_identifier( 'ID' )
			);
		}

		return $this->connection->quote_identifier( 'ID' ) . ' ASC';
	}

	/**
	 * Translate expression tokens with metadata-backed numeric text coercions.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First expression token position.
	 * @param int             $end    Final expression token position, exclusive.
	 * @param array           $scope  Statement table scope.
	 * @return array{sql: string, changed: bool} Translated expression SQL and change flag.
	 */
	private function translate_mysql_expression_token_sequence_to_postgresql(
		array $tokens,
		int $start,
		int $end,
		array $scope
	): array {
		$chunks        = array();
		$segment_start = $start;
		$changed       = false;

		for ( $position = $start; $position < $end; $position++ ) {
			if (
				isset( $tokens[ $position ], $tokens[ $position + 1 ] )
				&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id
				&& WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[ $position + 1 ]->id
			) {
				$after_subquery = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
				if ( null !== $after_subquery ) {
					$position = $after_subquery - 1;
					continue;
				}
			}

			$translated_expression = $this->translate_mysql_text_column_numeric_arithmetic_to_postgresql(
				$tokens,
				$position,
				$end,
				$scope
			);
			if ( null === $translated_expression ) {
				$translated_expression = $this->translate_mysql_wordpress_text_order_expression_to_postgresql(
					$tokens,
					$position,
					$start,
					$end,
					$scope
				);
			}
			if ( null === $translated_expression ) {
				$translated_expression = $this->translate_mysql_wordpress_text_expression_predicate_to_postgresql(
					$tokens,
					$position,
					$start,
					$end,
					$scope
				);
			}
			if ( null === $translated_expression ) {
				continue;
			}

			if ( $segment_start < $position ) {
				$chunks[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $segment_start, $position );
			}

			$chunks[]      = $translated_expression['sql'];
			$segment_start = $translated_expression['position'] + 1;
			$position      = $translated_expression['position'];
			$changed       = true;
		}

		if ( ! $changed ) {
			return array(
				'sql'     => $this->translate_mysql_token_sequence_to_postgresql( $tokens, $start, $end ),
				'changed' => false,
			);
		}

		if ( $segment_start < $end ) {
			$chunks[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $segment_start, $end );
		}

		return array(
			'sql'     => implode( ' ', array_filter( $chunks, 'strlen' ) ),
			'changed' => true,
		);
	}

	/**
	 * Translate WordPress text ORDER BY expressions with MySQL collation semantics.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate expression start position.
	 * @param int             $start    First expression token position.
	 * @param int             $end      Final expression token position, exclusive.
	 * @param array           $scope    Statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_wordpress_text_order_expression_to_postgresql(
		array $tokens,
		int $position,
		int $start,
		int $end,
		array $scope
	): ?array {
		if ( $position !== $start ) {
			return null;
		}

		$bounds = $this->normalize_mysql_expression_bounds( $tokens, $start, $end );
		if ( $bounds['start'] !== $start || $bounds['end'] !== $end ) {
			return null;
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $bounds['start'], $bounds['end'] );
		if (
			null === $reference
			|| $reference['end'] !== $bounds['end']
			|| ! $this->is_mysql_case_insensitive_wordpress_text_column_reference( $reference, $scope )
		) {
			return null;
		}

		return array(
			'sql'      => sprintf(
				'LOWER(%s)',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] )
			),
			'position' => $bounds['end'] - 1,
		);
	}

	/**
	 * Translate WordPress text predicates embedded in expressions.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate start position.
	 * @param int             $start    First expression token position.
	 * @param int             $end      Final expression token position, exclusive.
	 * @param array           $scope    Statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_wordpress_text_expression_predicate_to_postgresql(
		array $tokens,
		int $position,
		int $start,
		int $end,
		array $scope
	): ?array {
		if ( ! $this->is_mysql_expression_predicate_start_context( $tokens, $position, $start ) ) {
			return null;
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $position, $end );
		if (
			null === $reference
			|| ! $this->is_mysql_case_insensitive_wordpress_text_column_reference( $reference, $scope )
		) {
			return null;
		}

		return $this->translate_mysql_wordpress_text_like_predicate_to_postgresql(
			$tokens,
			$reference,
			$reference['end'],
			$end
		);
	}

	/**
	 * Check whether an expression position starts a boolean predicate.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate start position.
	 * @param int             $start    First expression token position.
	 * @return bool Whether the candidate follows a boolean expression boundary.
	 */
	private function is_mysql_expression_predicate_start_context( array $tokens, int $position, int $start ): bool {
		if ( $position <= $start ) {
			return false;
		}

		$previous_token_id = $tokens[ $position - 1 ]->id ?? null;
		if ( $this->is_mysql_expression_predicate_left_boundary_token_id( $previous_token_id ) ) {
			return true;
		}

		return WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $previous_token_id
			&& $position - 1 > $start
			&& $this->is_mysql_expression_predicate_left_boundary_token_id( $tokens[ $position - 2 ]->id ?? null );
	}

	/**
	 * Check whether a token can precede a predicate inside an expression.
	 *
	 * @param int|null $token_id MySQL token ID.
	 * @return bool Whether the token is a predicate boundary.
	 */
	private function is_mysql_expression_predicate_left_boundary_token_id( ?int $token_id ): bool {
		return in_array(
			$token_id,
			array(
				WP_MySQL_Lexer::AND_SYMBOL,
				WP_MySQL_Lexer::OR_SYMBOL,
				WP_MySQL_Lexer::WHEN_SYMBOL,
				WP_MySQL_Lexer::XOR_SYMBOL,
			),
			true
		);
	}

	/**
	 * Translate predicate tokens with metadata-backed integer string coercion.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First predicate token position.
	 * @param int             $end    Final predicate token position, exclusive.
	 * @param array           $scope  Statement table scope.
	 * @return array{sql: string, changed: bool} Translated predicate SQL and change flag.
	 */
	private function translate_mysql_predicate_token_sequence_to_postgresql(
		array $tokens,
		int $start,
		int $end,
		array $scope
	): array {
		$chunks        = array();
		$segment_start = $start;
		$changed       = false;

		for ( $position = $start; $position < $end; $position++ ) {
			if ( $this->is_mysql_qualified_reference_suffix_position( $tokens, $position, $start ) ) {
				continue;
			}

			if (
				isset( $tokens[ $position ], $tokens[ $position + 1 ] )
				&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id
				&& WP_MySQL_Lexer::SELECT_SYMBOL === $tokens[ $position + 1 ]->id
			) {
				$after_subquery = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
				if ( null !== $after_subquery ) {
					$translated_subquery = $this->translate_mysql_parenthesized_select_predicate_to_postgresql(
						$tokens,
						$position,
						$after_subquery,
						$scope
					);
					if ( null !== $translated_subquery ) {
						if ( $segment_start < $position ) {
							$chunks[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $segment_start, $position );
						}

						$chunks[]      = $translated_subquery['sql'];
						$segment_start = $translated_subquery['position'] + 1;
						$position      = $translated_subquery['position'];
						$changed       = true;
						continue;
					}

					$position = $after_subquery - 1;
					continue;
				}
			}

			$translated_predicate = $this->translate_mysql_integer_column_string_predicate_to_postgresql(
				$tokens,
				$position,
				$end,
				$scope
			);
			if ( null === $translated_predicate ) {
				continue;
			}

			if ( $segment_start < $position ) {
				$chunks[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $segment_start, $position );
			}

			$chunks[]      = $translated_predicate['sql'];
			$segment_start = $translated_predicate['position'] + 1;
			$position      = $translated_predicate['position'];
			$changed       = true;
		}

		if ( ! $changed ) {
			return array(
				'sql'     => $this->translate_mysql_token_sequence_to_postgresql( $tokens, $start, $end ),
				'changed' => false,
			);
		}

		if ( $segment_start < $end ) {
			$chunks[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $segment_start, $end );
		}

		return array(
			'sql'     => implode( ' ', array_filter( $chunks, 'strlen' ) ),
			'changed' => true,
		);
	}

	/**
	 * Translate one integer-column predicate against string literals.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate start position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @param array           $scope    Statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_integer_column_string_predicate_to_postgresql(
		array $tokens,
		int $position,
		int $end,
		array $scope
	): ?array {
		$truthiness = $this->translate_mysql_numeric_literal_truthiness_predicate_to_postgresql(
			$tokens,
			$position,
			$end
		);
		if ( null !== $truthiness ) {
			return $truthiness;
		}

		$decimal_like = $this->translate_mysql_decimal_cast_like_predicate_to_postgresql(
			$tokens,
			$position,
			$end
		);
		if ( null !== $decimal_like ) {
			return $decimal_like;
		}

		$wordpress_text_predicate = $this->translate_mysql_wordpress_text_predicate_to_postgresql(
			$tokens,
			$position,
			$end,
			$scope
		);
		if ( null !== $wordpress_text_predicate ) {
			return $wordpress_text_predicate;
		}

		$in_predicate = $this->translate_mysql_integer_column_string_in_predicate_to_postgresql(
			$tokens,
			$position,
			$end,
			$scope
		);
		if ( null !== $in_predicate ) {
			return $in_predicate;
		}

		$comparison = $this->translate_mysql_integer_column_string_comparison_to_postgresql(
			$tokens,
			$position,
			$end,
			$scope
		);
		if ( null !== $comparison ) {
			return $comparison;
		}

		$numeric_comparison = $this->translate_mysql_text_column_numeric_comparison_to_postgresql(
			$tokens,
			$position,
			$end,
			$scope
		);
		if ( null !== $numeric_comparison ) {
			return $numeric_comparison;
		}

		return $this->translate_mysql_metadata_column_reference_to_postgresql(
			$tokens,
			$position,
			$end,
			$scope
		);
	}

	/**
	 * Check whether a scanner position is inside a qualified reference suffix.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate start position.
	 * @param int             $start    First predicate token position.
	 * @return bool Whether the position follows a dot in the same predicate.
	 */
	private function is_mysql_qualified_reference_suffix_position( array $tokens, int $position, int $start ): bool {
		return $position > $start
			&& isset( $tokens[ $position - 1 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position - 1 ]->id;
	}

	/**
	 * Translate WordPress text predicates with MySQL case-insensitive collation semantics.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate start position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @param array           $scope    Statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_wordpress_text_predicate_to_postgresql(
		array $tokens,
		int $position,
		int $end,
		array $scope
	): ?array {
		$reference = $this->parse_mysql_column_reference( $tokens, $position, $end );
		if (
			null !== $reference
			&& $this->is_mysql_case_insensitive_wordpress_text_column_reference( $reference, $scope )
		) {
			$like = $this->translate_mysql_wordpress_text_like_predicate_to_postgresql(
				$tokens,
				$reference,
				$reference['end'],
				$end
			);
			if ( null !== $like ) {
				return $like;
			}

			$in = $this->translate_mysql_wordpress_text_in_predicate_to_postgresql(
				$tokens,
				$reference,
				$reference['end'],
				$end
			);
			if ( null !== $in ) {
				return $in;
			}

			$comparison = $this->translate_mysql_wordpress_text_comparison_to_postgresql(
				$tokens,
				$reference,
				$reference['end'],
				$end
			);
			if ( null !== $comparison ) {
				return $comparison;
			}
		}

		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			|| ! $this->is_mysql_string_literal_token( $tokens[ $position ] )
			|| ! $this->is_mysql_case_insensitive_equality_operator_token( $tokens[ $position + 1 ] )
		) {
			return null;
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $position + 2, $end );
		if (
			null === $reference
			|| ! $this->is_mysql_case_insensitive_wordpress_text_column_reference( $reference, $scope )
		) {
			return null;
		}

		return array(
			'sql'      => sprintf(
				'LOWER(%s) %s LOWER(%s)',
				$this->translate_mysql_token_to_postgresql( $tokens[ $position ] ),
				$tokens[ $position + 1 ]->get_bytes(),
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] )
			),
			'position' => $reference['end'] - 1,
		);
	}

	/**
	 * Translate a WordPress text LIKE predicate with case-insensitive semantics.
	 *
	 * @param WP_MySQL_Token[] $tokens            MySQL lexer token stream.
	 * @param array           $reference         Parsed column reference.
	 * @param int             $operator_position Candidate LIKE or NOT position.
	 * @param int             $end               Final predicate token position, exclusive.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_wordpress_text_like_predicate_to_postgresql(
		array $tokens,
		array $reference,
		int $operator_position,
		int $end
	): ?array {
		$not_sql = '';
		if (
			isset( $tokens[ $operator_position ], $tokens[ $operator_position + 1 ] )
			&& WP_MySQL_Lexer::NOT_SYMBOL === $tokens[ $operator_position ]->id
			&& WP_MySQL_Lexer::LIKE_SYMBOL === $tokens[ $operator_position + 1 ]->id
		) {
			$not_sql = ' NOT';
			++$operator_position;
		}

		if (
			! isset( $tokens[ $operator_position ], $tokens[ $operator_position + 1 ] )
			|| WP_MySQL_Lexer::LIKE_SYMBOL !== $tokens[ $operator_position ]->id
		) {
			return null;
		}

		$pattern = $this->get_mysql_string_like_pattern_sql( $tokens, $operator_position + 1, $end );
		if ( null === $pattern ) {
			return null;
		}

		return array(
			'sql'      => sprintf(
				'LOWER(%s)%s LIKE LOWER(%s)%s',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] ),
				$not_sql,
				$pattern['pattern_sql'],
				$pattern['escape_sql']
			),
			'position' => $pattern['end'] - 1,
		);
	}

	/**
	 * Translate a WordPress text equality predicate with case-insensitive semantics.
	 *
	 * @param WP_MySQL_Token[] $tokens            MySQL lexer token stream.
	 * @param array           $reference         Parsed column reference.
	 * @param int             $operator_position Candidate comparison operator position.
	 * @param int             $end               Final predicate token position, exclusive.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_wordpress_text_comparison_to_postgresql(
		array $tokens,
		array $reference,
		int $operator_position,
		int $end
	): ?array {
		if (
			! isset( $tokens[ $operator_position ], $tokens[ $operator_position + 1 ] )
			|| $operator_position + 1 >= $end
			|| ! $this->is_mysql_case_insensitive_equality_operator_token( $tokens[ $operator_position ] )
			|| ! $this->is_mysql_string_literal_token( $tokens[ $operator_position + 1 ] )
		) {
			return null;
		}

		return array(
			'sql'      => sprintf(
				'LOWER(%s) %s LOWER(%s)',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] ),
				$tokens[ $operator_position ]->get_bytes(),
				$this->translate_mysql_token_to_postgresql( $tokens[ $operator_position + 1 ] )
			),
			'position' => $operator_position + 1,
		);
	}

	/**
	 * Translate a WordPress text IN predicate with case-insensitive semantics.
	 *
	 * @param WP_MySQL_Token[] $tokens            MySQL lexer token stream.
	 * @param array           $reference         Parsed column reference.
	 * @param int             $operator_position Candidate IN or NOT position.
	 * @param int             $end               Final predicate token position, exclusive.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_wordpress_text_in_predicate_to_postgresql(
		array $tokens,
		array $reference,
		int $operator_position,
		int $end
	): ?array {
		$not_sql = '';
		if (
			isset( $tokens[ $operator_position ], $tokens[ $operator_position + 1 ] )
			&& WP_MySQL_Lexer::NOT_SYMBOL === $tokens[ $operator_position ]->id
			&& WP_MySQL_Lexer::IN_SYMBOL === $tokens[ $operator_position + 1 ]->id
		) {
			$not_sql = ' NOT';
			++$operator_position;
		}

		if (
			! isset( $tokens[ $operator_position ], $tokens[ $operator_position + 1 ] )
			|| WP_MySQL_Lexer::IN_SYMBOL !== $tokens[ $operator_position ]->id
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $operator_position + 1 ]->id
		) {
			return null;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $operator_position + 1, $end );
		if ( null === $after_close ) {
			return null;
		}

		$items = $this->split_top_level_mysql_arguments( $tokens, $operator_position + 2, $after_close - 1 );
		if ( empty( $items ) ) {
			return null;
		}

		$item_sql = array();
		foreach ( $items as $item ) {
			if ( ! $this->is_mysql_string_literal_range( $tokens, $item['start'], $item['end'] ) ) {
				return null;
			}

			$item_sql[] = 'LOWER(' . $this->translate_mysql_token_to_postgresql( $tokens[ $item['start'] ] ) . ')';
		}

		return array(
			'sql'      => sprintf(
				'LOWER(%s)%s IN (%s)',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] ),
				$not_sql,
				implode( ', ', $item_sql )
			),
			'position' => $after_close - 1,
		);
	}

	/**
	 * Get a simple string LIKE pattern SQL fragment.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Pattern token position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @return array{pattern_sql: string, escape_sql: string, end: int}|null Pattern SQL, or null when unsupported.
	 */
	private function get_mysql_string_like_pattern_sql( array $tokens, int $position, int $end ): ?array {
		if (
			! isset( $tokens[ $position ] )
			|| $position >= $end
			|| ! $this->is_mysql_string_literal_token( $tokens[ $position ] )
		) {
			return null;
		}

		$pattern_sql = $this->translate_mysql_token_to_postgresql( $tokens[ $position ] );
		$escape_sql  = '';
		$pattern_end = $position + 1;

		if ( isset( $tokens[ $pattern_end ] ) && WP_MySQL_Lexer::ESCAPE_SYMBOL === $tokens[ $pattern_end ]->id ) {
			if (
				! isset( $tokens[ $pattern_end + 1 ] )
				|| $pattern_end + 1 >= $end
				|| ! $this->is_mysql_string_literal_token( $tokens[ $pattern_end + 1 ] )
			) {
				return null;
			}

			$escape_sql   = ' ESCAPE ' . $this->translate_mysql_token_to_postgresql( $tokens[ $pattern_end + 1 ] );
			$pattern_end += 2;
		}

		return array(
			'pattern_sql' => $pattern_sql,
			'escape_sql'  => $escape_sql,
			'end'         => $pattern_end,
		);
	}

	/**
	 * Check whether a column is a case-insensitive WordPress text lookup column.
	 *
	 * @param array $reference Parsed column reference.
	 * @param array $scope     Statement table scope.
	 * @return bool Whether the reference should use MySQL case-insensitive text predicates.
	 */
	private function is_mysql_case_insensitive_wordpress_text_column_reference( array $reference, array $scope ): bool {
		$table = $this->get_mysql_table_for_column_reference( $reference, $scope );
		if ( null === $table || ! $this->is_mysql_wordpress_case_insensitive_text_column( $table['table'], $reference['column'] ) ) {
			return false;
		}

		if (
			$this->is_mysql_wordpress_table_name( $table['table'], 'postmeta' )
			&& null === $reference['qualifier']
		) {
			return false;
		}

		$column_type = $this->get_mysql_column_type_for_reference( $reference, $scope );
		if ( null === $column_type || ! $this->is_mysql_text_family_column_type( $column_type ) ) {
			return false;
		}

		$collation = $this->get_mysql_column_collation_for_reference( $reference, $scope );
		return null !== $collation && $this->is_mysql_case_insensitive_collation( $collation );
	}

	/**
	 * Resolve a column reference to one table in the statement scope.
	 *
	 * @param array $reference Parsed column reference.
	 * @param array $scope     Statement table scope.
	 * @return array|null Table metadata, or null when missing/ambiguous.
	 */
	private function get_mysql_table_for_column_reference( array $reference, array $scope ): ?array {
		if ( null !== $reference['qualifier'] ) {
			$alias = strtolower( $reference['qualifier'] );
			$table = $scope['aliases'][ $alias ] ?? null;
			if ( null === $table || ! empty( $table['derived'] ) || null === ( $table['table'] ?? null ) ) {
				return null;
			}

			return $table;
		}

		if ( ! empty( $scope['unknown'] ) ) {
			return null;
		}

		$matched_table = null;
		foreach ( $scope['tables'] as $table ) {
			if (
				count( $scope['tables'] ) > 1
				&& ! $this->mysql_table_has_column_metadata( $table['schema'], $table['table'] )
			) {
				return null;
			}

			if ( null === $this->get_mysql_table_column_type( $table['schema'], $table['table'], $reference['column'] ) ) {
				continue;
			}

			if ( null !== $matched_table ) {
				return null;
			}

			$matched_table = $table;
		}

		return $matched_table;
	}

	/**
	 * Resolve a column reference when a statement scope has exactly one table.
	 *
	 * @param array $reference Parsed column reference.
	 * @param array $scope     Statement table scope.
	 * @return array|null Table metadata, or null when missing/ambiguous.
	 */
	private function get_mysql_single_scope_table_for_column_reference( array $reference, array $scope ): ?array {
		if ( null !== $reference['qualifier'] ) {
			$alias = strtolower( $reference['qualifier'] );
			$table = $scope['aliases'][ $alias ] ?? null;
			if ( null === $table || ! empty( $table['derived'] ) || null === ( $table['table'] ?? null ) ) {
				return null;
			}

			return $table;
		}

		if ( ! empty( $scope['unknown'] ) || 1 !== count( $scope['tables'] ) ) {
			return null;
		}

		return $scope['tables'][0];
	}

	/**
	 * Check whether a table/column pair is in a WordPress text lookup surface.
	 *
	 * @param string $table_name  Table name.
	 * @param string $column_name Column name.
	 * @return bool Whether this is a supported text lookup column.
	 */
	private function is_mysql_wordpress_case_insensitive_text_column( string $table_name, string $column_name ): bool {
		$column_name = strtolower( $column_name );

		if ( $this->is_mysql_wordpress_table_name( $table_name, 'posts' ) ) {
			return in_array( $column_name, array( 'post_content', 'post_excerpt', 'post_title' ), true );
		}

		if ( $this->is_mysql_wordpress_table_name( $table_name, 'terms' ) ) {
			return in_array( $column_name, array( 'name', 'slug' ), true );
		}

		if ( $this->is_mysql_wordpress_table_name( $table_name, 'term_taxonomy' ) ) {
			return in_array( $column_name, array( 'description', 'taxonomy' ), true );
		}

		if ( $this->is_mysql_wordpress_table_name( $table_name, 'postmeta' ) ) {
			return 'meta_value' === $column_name;
		}

		if ( $this->is_mysql_wordpress_table_name( $table_name, 'users' ) ) {
			return in_array(
				$column_name,
				array(
					'display_name',
					'user_email',
					'user_login',
					'user_nicename',
					'user_url',
				),
				true
			);
		}

		return false;
	}

	/**
	 * Check whether a MySQL collation is explicitly case-insensitive.
	 *
	 * @param string $collation MySQL collation name.
	 * @return bool Whether the collation is case-insensitive.
	 */
	private function is_mysql_case_insensitive_collation( string $collation ): bool {
		$collation = strtolower( trim( $collation ) );
		return 1 === preg_match( '/(^|_)ci($|_)/', $collation );
	}

	/**
	 * Check whether a token is a case-insensitive equality operator candidate.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token is an equality or inequality operator.
	 */
	private function is_mysql_case_insensitive_equality_operator_token( WP_MySQL_Token $token ): bool {
		return in_array(
			$token->id,
			array(
				WP_MySQL_Lexer::EQUAL_OPERATOR,
				WP_MySQL_Lexer::NOT_EQUAL_OPERATOR,
			),
			true
		);
	}

	/**
	 * Translate a parenthesized SELECT predicate with inner and outer metadata scope.
	 *
	 * @param WP_MySQL_Token[] $tokens         MySQL lexer token stream.
	 * @param int             $position       Opening parenthesis position.
	 * @param int             $after_subquery Position after the closing parenthesis.
	 * @param array           $outer_scope    Outer statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unchanged/unsupported.
	 */
	private function translate_mysql_parenthesized_select_predicate_to_postgresql(
		array $tokens,
		int $position,
		int $after_subquery,
		array $outer_scope
	): ?array {
		$select_position = $position + 1;
		$statement_end   = $after_subquery - 1;
		if (
			! isset( $tokens[ $select_position ] )
			|| WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[ $select_position ]->id
		) {
			return null;
		}

		$projection_start = $select_position + 1;
		$from_position    = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::FROM_SYMBOL,
			$projection_start,
			$statement_end
		);
		if ( null === $from_position ) {
			return null;
		}

		$from_end = $this->find_first_top_level_mysql_token(
			$tokens,
			array(
				WP_MySQL_Lexer::FOR_SYMBOL,
				WP_MySQL_Lexer::GROUP_SYMBOL,
				WP_MySQL_Lexer::HAVING_SYMBOL,
				WP_MySQL_Lexer::LIMIT_SYMBOL,
				WP_MySQL_Lexer::LOCK_SYMBOL,
				WP_MySQL_Lexer::ORDER_SYMBOL,
				WP_MySQL_Lexer::PROCEDURE_SYMBOL,
				WP_MySQL_Lexer::UNION_SYMBOL,
				WP_MySQL_Lexer::WHERE_SYMBOL,
			),
			$from_position + 1,
			$statement_end
		) ?? $statement_end;

		$inner_scope = $this->get_mysql_select_scope( $tokens, $from_position + 1, $from_end );
		if ( null === $inner_scope ) {
			return null;
		}

		$scope          = $this->merge_mysql_inner_and_outer_scopes( $inner_scope, $outer_scope );
		$replacements   = array();
		$where_position = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::WHERE_SYMBOL,
			$projection_start,
			$statement_end
		);
		if ( null !== $where_position ) {
			$where_end = $this->find_first_top_level_mysql_token(
				$tokens,
				array(
					WP_MySQL_Lexer::FOR_SYMBOL,
					WP_MySQL_Lexer::GROUP_SYMBOL,
					WP_MySQL_Lexer::HAVING_SYMBOL,
					WP_MySQL_Lexer::LIMIT_SYMBOL,
					WP_MySQL_Lexer::LOCK_SYMBOL,
					WP_MySQL_Lexer::ORDER_SYMBOL,
					WP_MySQL_Lexer::PROCEDURE_SYMBOL,
					WP_MySQL_Lexer::UNION_SYMBOL,
				),
				$where_position + 1,
				$statement_end
			) ?? $statement_end;

			$where_sql = $this->translate_mysql_predicate_token_sequence_to_postgresql(
				$tokens,
				$where_position + 1,
				$where_end,
				$scope
			);
			if ( $where_sql['changed'] ) {
				$replacements[] = array(
					'start' => $where_position + 1,
					'end'   => $where_end,
					'sql'   => $where_sql['sql'],
				);
			}
		}

		if ( empty( $replacements ) ) {
			return null;
		}

		return array(
			'sql'      => '(' . $this->translate_mysql_token_sequence_with_replacements_to_postgresql( $tokens, $select_position, $statement_end, $replacements ) . ')',
			'position' => $after_subquery - 1,
		);
	}

	/**
	 * Merge SELECT scopes so inner aliases shadow correlated outer aliases.
	 *
	 * @param array $inner_scope Inner SELECT table scope.
	 * @param array $outer_scope Outer SELECT table scope.
	 * @return array Combined scope.
	 */
	private function merge_mysql_inner_and_outer_scopes( array $inner_scope, array $outer_scope ): array {
		$scope = $inner_scope;
		foreach ( $outer_scope['aliases'] as $alias => $table ) {
			if ( ! isset( $scope['aliases'][ $alias ] ) ) {
				$scope['aliases'][ $alias ] = $table;
			}
		}

		if ( ! empty( $outer_scope['unknown'] ) ) {
			$scope['unknown'] = true;
		}

		return $scope;
	}

	/**
	 * Translate a numeric literal used as a standalone boolean predicate.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_numeric_literal_truthiness_predicate_to_postgresql(
		array $tokens,
		int $position,
		int $end
	): ?array {
		$literal = $this->parse_mysql_numeric_literal( $tokens, $position, $end );
		if ( null === $literal || ! $this->is_mysql_boolean_predicate_literal_context( $tokens, $literal['start'], $literal['end'], $end ) ) {
			return null;
		}

		return array(
			'sql'      => sprintf(
				'(%s <> 0)',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $literal['start'], $literal['end'] )
			),
			'position' => $literal['end'] - 1,
		);
	}

	/**
	 * Check whether a numeric literal is a standalone boolean predicate operand.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First literal token.
	 * @param int             $end    Final literal token, exclusive.
	 * @param int             $limit  Final predicate token position, exclusive.
	 * @return bool Whether the literal is in predicate truthiness context.
	 */
	private function is_mysql_boolean_predicate_literal_context( array $tokens, int $start, int $end, int $limit ): bool {
		if ( $this->is_mysql_between_bound_literal_context( $tokens, $start ) ) {
			return false;
		}

		$previous_token_id = $tokens[ $start - 1 ]->id ?? null;
		$next_token_id     = $tokens[ $end ]->id ?? null;

		$left_boundary = 0 === $start
			|| $this->is_mysql_boolean_predicate_left_boundary_token_id( $previous_token_id )
			|| (
				WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $previous_token_id
				&& $this->is_mysql_boolean_predicate_left_boundary_token_id( $tokens[ $start - 2 ]->id ?? null )
			);
		if ( ! $left_boundary ) {
			return false;
		}

		return $end >= $limit || in_array(
			$next_token_id,
			array(
				WP_MySQL_Lexer::AND_SYMBOL,
				WP_MySQL_Lexer::CLOSE_PAR_SYMBOL,
				WP_MySQL_Lexer::OR_SYMBOL,
				WP_MySQL_Lexer::XOR_SYMBOL,
			),
			true
		);
	}

	/**
	 * Check whether a numeric literal belongs to a BETWEEN range.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First literal token.
	 * @return bool Whether the literal is a BETWEEN bound.
	 */
	private function is_mysql_between_bound_literal_context( array $tokens, int $start ): bool {
		$previous_token_id = $tokens[ $start - 1 ]->id ?? null;

		if ( WP_MySQL_Lexer::BETWEEN_SYMBOL === $previous_token_id ) {
			return true;
		}

		if (
			WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $previous_token_id
			&& WP_MySQL_Lexer::BETWEEN_SYMBOL === ( $tokens[ $start - 2 ]->id ?? null )
		) {
			return true;
		}

		$and_position = null;
		if ( WP_MySQL_Lexer::AND_SYMBOL === $previous_token_id ) {
			$and_position = $start - 1;
		} elseif (
			WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $previous_token_id
			&& WP_MySQL_Lexer::AND_SYMBOL === ( $tokens[ $start - 2 ]->id ?? null )
		) {
			$and_position = $start - 2;
		}

		return null !== $and_position && $this->is_mysql_between_upper_bound_separator( $tokens, $and_position );
	}

	/**
	 * Check whether an AND token separates the lower and upper BETWEEN bounds.
	 *
	 * @param WP_MySQL_Token[] $tokens       MySQL lexer token stream.
	 * @param int             $and_position Candidate AND token position.
	 * @return bool Whether the AND token belongs to BETWEEN.
	 */
	private function is_mysql_between_upper_bound_separator( array $tokens, int $and_position ): bool {
		if ( ! isset( $tokens[ $and_position ] ) || WP_MySQL_Lexer::AND_SYMBOL !== $tokens[ $and_position ]->id ) {
			return false;
		}

		$depth = 0;
		for ( $i = $and_position - 1; $i >= 0; $i-- ) {
			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $i ]->id ) {
				++$depth;
				continue;
			}

			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $i ]->id ) {
				--$depth;
				if ( $depth < 0 ) {
					return false;
				}
				continue;
			}

			if ( 0 !== $depth ) {
				continue;
			}

			if ( WP_MySQL_Lexer::BETWEEN_SYMBOL === $tokens[ $i ]->id ) {
				return true;
			}

			if (
				$this->is_mysql_boolean_predicate_left_boundary_token_id( $tokens[ $i ]->id )
				|| WP_MySQL_Lexer::HAVING_SYMBOL === $tokens[ $i ]->id
				|| WP_MySQL_Lexer::ON_SYMBOL === $tokens[ $i ]->id
				|| WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $i ]->id
			) {
				return false;
			}
		}

		return false;
	}

	/**
	 * Check whether a token can precede a standalone boolean predicate operand.
	 *
	 * @param int|null $token_id MySQL token ID.
	 * @return bool Whether the token is a boolean left boundary.
	 */
	private function is_mysql_boolean_predicate_left_boundary_token_id( ?int $token_id ): bool {
		return in_array(
			$token_id,
			array(
				WP_MySQL_Lexer::AND_SYMBOL,
				WP_MySQL_Lexer::NOT_SYMBOL,
				WP_MySQL_Lexer::OR_SYMBOL,
				WP_MySQL_Lexer::WHERE_SYMBOL,
				WP_MySQL_Lexer::XOR_SYMBOL,
			),
			true
		);
	}

	/**
	 * Translate DECIMAL casts used with string-pattern operators.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_decimal_cast_like_predicate_to_postgresql(
		array $tokens,
		int $position,
		int $end
	): ?array {
		$cast_bounds = $this->get_mysql_decimal_cast_bounds( $tokens, $position, $end );
		if ( null === $cast_bounds ) {
			return null;
		}

		$operator_position = $cast_bounds['close'] + 1;
		$not_sql           = '';
		if (
			isset( $tokens[ $operator_position ], $tokens[ $operator_position + 1 ] )
			&& WP_MySQL_Lexer::NOT_SYMBOL === $tokens[ $operator_position ]->id
			&& WP_MySQL_Lexer::LIKE_SYMBOL === $tokens[ $operator_position + 1 ]->id
		) {
			$not_sql            = ' NOT';
			$operator_position += 1;
		}

		if (
			! isset( $tokens[ $operator_position ], $tokens[ $operator_position + 1 ] )
			|| WP_MySQL_Lexer::LIKE_SYMBOL !== $tokens[ $operator_position ]->id
		) {
			return null;
		}

		$pattern_end = $this->get_mysql_like_pattern_end( $tokens, $operator_position + 1, $end );
		if ( null === $pattern_end ) {
			return null;
		}

		return array(
			'sql'      => sprintf(
				'CAST(%s AS text)%s LIKE %s',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $position, $cast_bounds['close'] + 1 ),
				$not_sql,
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $operator_position + 1, $pattern_end )
			),
			'position' => $pattern_end - 1,
		);
	}

	/**
	 * Get the end of a simple LIKE pattern expression.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Pattern token position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @return int|null Pattern end position, exclusive.
	 */
	private function get_mysql_like_pattern_end( array $tokens, int $position, int $end ): ?int {
		if ( ! isset( $tokens[ $position ] ) || $position >= $end ) {
			return null;
		}

		$pattern_end = $position + 1;
		if (
			isset( $tokens[ $pattern_end ], $tokens[ $pattern_end + 1 ] )
			&& WP_MySQL_Lexer::ESCAPE_SYMBOL === $tokens[ $pattern_end ]->id
			&& $pattern_end + 1 < $end
		) {
			$pattern_end += 2;
		}

		return $pattern_end;
	}

	/**
	 * Translate metadata-backed qualified column casing when MySQL casing differs.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @param array           $scope    Statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unchanged/unsupported.
	 */
	private function translate_mysql_metadata_column_reference_to_postgresql(
		array $tokens,
		int $position,
		int $end,
		array $scope
	): ?array {
		$reference = $this->parse_mysql_column_reference( $tokens, $position, $end );
		if ( null === $reference || null === $reference['qualifier'] ) {
			return null;
		}

		$resolved_column = $this->get_mysql_column_name_for_reference( $reference, $scope );
		if ( null === $resolved_column || $resolved_column === $reference['column'] ) {
			return null;
		}

		return array(
			'sql'      => sprintf(
				'%s.%s',
				$this->translate_mysql_token_to_postgresql( $tokens[ $reference['start'] ], $tokens[ $reference['start'] + 1 ] ?? null ),
				$this->translate_mysql_identifier_value_to_postgresql( $resolved_column )
			),
			'position' => $reference['end'] - 1,
		);
	}

	/**
	 * Resolve the stored MySQL column name for a scoped column reference.
	 *
	 * @param array $reference Parsed column reference.
	 * @param array $scope     Statement table scope.
	 * @return string|null Stored column name, or null when missing/ambiguous.
	 */
	private function get_mysql_column_name_for_reference( array $reference, array $scope ): ?string {
		if ( null === $reference['qualifier'] ) {
			return null;
		}

		$alias = strtolower( $reference['qualifier'] );
		if ( ! isset( $scope['aliases'][ $alias ] ) ) {
			return null;
		}

		$table = $scope['aliases'][ $alias ];
		if ( ! empty( $table['derived'] ) || null === ( $table['table'] ?? null ) ) {
			return null;
		}

		return $this->get_mysql_table_column_name( $table['schema'], $table['table'], $reference['column'] );
	}

	/**
	 * Get the metadata-backed stored column name for a MySQL column reference.
	 *
	 * @param string $table_schema Metadata schema.
	 * @param string $table_name   Table name.
	 * @param string $column_name  Referenced column name.
	 * @return string|null Stored column name, or null when no safe casing rewrite exists.
	 */
	private function get_mysql_table_column_name(
		string $table_schema,
		string $table_name,
		string $column_name
	): ?string {
		$this->ensure_mysql_schema_metadata_tables();

		$table_cache_key  = $this->get_mysql_metadata_cache_key( $table_schema, $table_name );
		$column_cache_key = $column_name;
		if (
			isset( $this->mysql_table_column_name_cache[ $table_cache_key ] )
			&& array_key_exists( $column_cache_key, $this->mysql_table_column_name_cache[ $table_cache_key ] )
		) {
			return $this->mysql_table_column_name_cache[ $table_cache_key ][ $column_cache_key ];
		}

		$stmt = $this->connection->query(
			sprintf(
				'SELECT column_name FROM %s
				WHERE table_schema = ?
					AND table_name = ?
					AND column_name = ?
				LIMIT 1',
				$this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE )
			),
			array( $table_schema, $table_name, $column_name )
		);

		$stored_column_name = $stmt->fetchColumn();
		if ( false !== $stored_column_name ) {
			$this->mysql_table_column_name_cache[ $table_cache_key ][ $column_cache_key ] = (string) $stored_column_name;
			return $this->mysql_table_column_name_cache[ $table_cache_key ][ $column_cache_key ];
		}

		$lowercase_column_name = strtolower( $column_name );
		$stmt                  = $this->connection->query(
			sprintf(
				'SELECT column_name FROM %s
				WHERE table_schema = ?
					AND table_name = ?
					AND column_name = ?
				LIMIT 1',
				$this->connection->quote_identifier( self::MYSQL_COLUMN_METADATA_TABLE )
			),
			array( $table_schema, $table_name, $lowercase_column_name )
		);

		$stored_column_name = $stmt->fetchColumn();
		$this->mysql_table_column_name_cache[ $table_cache_key ][ $column_cache_key ] = false === $stored_column_name
			? null
			: (string) $stored_column_name;
		return $this->mysql_table_column_name_cache[ $table_cache_key ][ $column_cache_key ];
	}

	/**
	 * Translate a stored identifier value for PostgreSQL.
	 *
	 * @param string $identifier Identifier value.
	 * @return string PostgreSQL identifier SQL.
	 */
	private function translate_mysql_identifier_value_to_postgresql( string $identifier ): string {
		return $this->should_quote_bare_mysql_identifier( $identifier )
			? $this->connection->quote_identifier( $identifier )
			: $identifier;
	}

	/**
	 * Get token bounds for a DECIMAL/NUMERIC CAST expression.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position CAST token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{expression_start: int, expression_end: int, close: int}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_decimal_cast_bounds( array $tokens, int $position, int $end ): ?array {
		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::CAST_SYMBOL !== $tokens[ $position ]->id
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return null;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position + 1, $end );
		if ( null === $after_close ) {
			return null;
		}

		$close_position = $after_close - 1;
		$as_position    = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::AS_SYMBOL,
			$position + 2,
			$close_position
		);
		if (
			null === $as_position
			|| $as_position <= $position + 2
			|| ! $this->is_mysql_decimal_cast_type( $tokens, $as_position + 1, $close_position )
		) {
			return null;
		}

		return array(
			'expression_start' => $position + 2,
			'expression_end'   => $as_position,
			'close'            => $close_position,
		);
	}

	/**
	 * Check whether a CAST type is MySQL DECIMAL/NUMERIC.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First cast type token.
	 * @param int             $end    Final cast type token, exclusive.
	 * @return bool Whether the type is supported.
	 */
	private function is_mysql_decimal_cast_type( array $tokens, int $start, int $end ): bool {
		if (
			! isset( $tokens[ $start ] )
			|| ! in_array(
				$tokens[ $start ]->id,
				array(
					WP_MySQL_Lexer::DECIMAL_SYMBOL,
					WP_MySQL_Lexer::NUMERIC_SYMBOL,
				),
				true
			)
		) {
			return false;
		}

		if ( $start + 1 === $end ) {
			return true;
		}

		return isset( $tokens[ $start + 1 ] )
			&& WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $start + 1 ]->id
			&& $this->get_mysql_parenthesized_sequence_end( $tokens, $start + 1, $end ) === $end;
	}

	/**
	 * Translate an integer-column IN list containing string literals.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate start position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @param array           $scope    Statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_integer_column_string_in_predicate_to_postgresql(
		array $tokens,
		int $position,
		int $end,
		array $scope
	): ?array {
		$reference = $this->parse_mysql_column_reference( $tokens, $position, $end );
		if ( null === $reference ) {
			return null;
		}

		$in_position = $reference['end'];
		$not_sql     = '';
		if (
			isset( $tokens[ $in_position ], $tokens[ $in_position + 1 ] )
			&& WP_MySQL_Lexer::NOT_SYMBOL === $tokens[ $in_position ]->id
			&& WP_MySQL_Lexer::IN_SYMBOL === $tokens[ $in_position + 1 ]->id
		) {
			$not_sql      = ' NOT';
			$in_position += 1;
		}

		if (
			! isset( $tokens[ $in_position ], $tokens[ $in_position + 1 ] )
			|| WP_MySQL_Lexer::IN_SYMBOL !== $tokens[ $in_position ]->id
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $in_position + 1 ]->id
		) {
			return null;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $in_position + 1, $end );
		if ( null === $after_close ) {
			return null;
		}

		$items = $this->split_top_level_mysql_arguments( $tokens, $in_position + 2, $after_close - 1 );
		if ( null === $items ) {
			return null;
		}

		$changed  = false;
		$item_sql = array();
		foreach ( $items as $item ) {
			if ( $this->is_mysql_string_literal_range( $tokens, $item['start'], $item['end'] ) ) {
				$item_sql[] = $this->get_postgresql_mysql_integer_cast_sql(
					$this->translate_mysql_token_to_postgresql( $tokens[ $item['start'] ] )
				);
				$changed    = true;
				continue;
			}

			$item_sql[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $item['start'], $item['end'] );
		}

		if ( ! $changed ) {
			return null;
		}

		if ( ! $this->is_mysql_integer_column_reference( $reference, $scope ) ) {
			return null;
		}

		return array(
			'sql'      => sprintf(
				'%s%s IN (%s)',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] ),
				$not_sql,
				implode( ', ', $item_sql )
			),
			'position' => $after_close - 1,
		);
	}

	/**
	 * Translate an integer-column comparison against a string literal.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate start position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @param array           $scope    Statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_integer_column_string_comparison_to_postgresql(
		array $tokens,
		int $position,
		int $end,
		array $scope
	): ?array {
		$reference = $this->parse_mysql_column_reference( $tokens, $position, $end );
		if (
			null !== $reference
			&& isset( $tokens[ $reference['end'] ], $tokens[ $reference['end'] + 1 ] )
			&& $reference['end'] + 1 < $end
			&& $this->is_mysql_comparison_operator_token( $tokens[ $reference['end'] ] )
			&& $this->is_mysql_string_literal_token( $tokens[ $reference['end'] + 1 ] )
			&& $this->is_mysql_integer_column_reference( $reference, $scope )
		) {
			return array(
				'sql'      => sprintf(
					'%s %s %s',
					$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] ),
					$tokens[ $reference['end'] ]->get_bytes(),
					$this->get_postgresql_mysql_integer_cast_sql(
						$this->translate_mysql_token_to_postgresql( $tokens[ $reference['end'] + 1 ] )
					)
				),
				'position' => $reference['end'] + 1,
			);
		}

		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			|| ! $this->is_mysql_string_literal_token( $tokens[ $position ] )
			|| ! $this->is_mysql_comparison_operator_token( $tokens[ $position + 1 ] )
		) {
			return null;
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $position + 2, $end );
		if ( null === $reference || ! $this->is_mysql_integer_column_reference( $reference, $scope ) ) {
			return null;
		}

		return array(
			'sql'      => sprintf(
				'%s %s %s',
				$this->get_postgresql_mysql_integer_cast_sql(
					$this->translate_mysql_token_to_postgresql( $tokens[ $position ] )
				),
				$tokens[ $position + 1 ]->get_bytes(),
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] )
			),
			'position' => $reference['end'] - 1,
		);
	}

	/**
	 * Translate a text-column comparison against a numeric literal.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate predicate start position.
	 * @param int             $end      Final predicate token position, exclusive.
	 * @param array           $scope    Statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_text_column_numeric_comparison_to_postgresql(
		array $tokens,
		int $position,
		int $end,
		array $scope
	): ?array {
		$reference = $this->parse_mysql_column_reference( $tokens, $position, $end );
		if (
			null !== $reference
			&& isset( $tokens[ $reference['end'] ] )
			&& $this->is_mysql_comparison_operator_token( $tokens[ $reference['end'] ] )
			&& $this->is_mysql_text_family_column_reference( $reference, $scope )
		) {
			$literal = $this->parse_mysql_numeric_literal( $tokens, $reference['end'] + 1, $end );
			if ( null !== $literal ) {
				return array(
					'sql'      => sprintf(
						'%s %s %s',
						$this->get_postgresql_mysql_numeric_cast_sql(
							$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] )
						),
						$tokens[ $reference['end'] ]->get_bytes(),
						$this->translate_mysql_token_sequence_to_postgresql( $tokens, $literal['start'], $literal['end'] )
					),
					'position' => $literal['end'] - 1,
				);
			}
		}

		$literal = $this->parse_mysql_numeric_literal( $tokens, $position, $end );
		if (
			null === $literal
			|| ! isset( $tokens[ $literal['end'] ] )
			|| ! $this->is_mysql_comparison_operator_token( $tokens[ $literal['end'] ] )
		) {
			return null;
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $literal['end'] + 1, $end );
		if ( null === $reference || ! $this->is_mysql_text_family_column_reference( $reference, $scope ) ) {
			return null;
		}

		return array(
			'sql'      => sprintf(
				'%s %s %s',
				$this->translate_mysql_token_sequence_to_postgresql( $tokens, $literal['start'], $literal['end'] ),
				$tokens[ $literal['end'] ]->get_bytes(),
				$this->get_postgresql_mysql_numeric_cast_sql(
					$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] )
				)
			),
			'position' => $reference['end'] - 1,
		);
	}

	/**
	 * Translate a text-column numeric arithmetic expression.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Candidate expression position.
	 * @param int             $end      Final expression token position, exclusive.
	 * @param array           $scope    Statement table scope.
	 * @return array{sql: string, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_text_column_numeric_arithmetic_to_postgresql(
		array $tokens,
		int $position,
		int $end,
		array $scope
	): ?array {
		$reference = $this->parse_mysql_column_reference( $tokens, $position, $end );
		if (
				null !== $reference
				&& isset( $tokens[ $reference['end'] ] )
				&& in_array(
					$tokens[ $reference['end'] ]->id,
					array(
						WP_MySQL_Lexer::MINUS_OPERATOR,
						WP_MySQL_Lexer::PLUS_OPERATOR,
					),
					true
				)
				&& $this->is_mysql_text_family_column_reference( $reference, $scope )
			) {
			$literal = $this->parse_mysql_numeric_literal( $tokens, $reference['end'] + 1, $end );
			if ( null !== $literal ) {
				$reference_sql = $this->get_postgresql_mysql_numeric_cast_sql(
					$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] )
				);
				if ( $this->is_mysql_zero_numeric_literal_range( $tokens, $literal['start'], $literal['end'] ) ) {
					return array(
						'sql'      => $reference_sql,
						'position' => $literal['end'] - 1,
					);
				}

				return array(
					'sql'      => sprintf(
						'%s %s %s',
						$reference_sql,
						$tokens[ $reference['end'] ]->get_bytes(),
						$this->translate_mysql_token_sequence_to_postgresql( $tokens, $literal['start'], $literal['end'] )
					),
					'position' => $literal['end'] - 1,
				);
			}
		}

		$literal = $this->parse_mysql_numeric_literal( $tokens, $position, $end );
		if (
				null === $literal
				|| ! isset( $tokens[ $literal['end'] ] )
				|| ! in_array(
					$tokens[ $literal['end'] ]->id,
					array(
						WP_MySQL_Lexer::MINUS_OPERATOR,
						WP_MySQL_Lexer::PLUS_OPERATOR,
					),
					true
				)
			) {
			return null;
		}

		$reference = $this->parse_mysql_column_reference( $tokens, $literal['end'] + 1, $end );
		if ( null === $reference || ! $this->is_mysql_text_family_column_reference( $reference, $scope ) ) {
			return null;
		}

		$reference_sql = $this->get_postgresql_mysql_numeric_cast_sql(
			$this->translate_mysql_token_sequence_to_postgresql( $tokens, $reference['start'], $reference['end'] )
		);
		if (
				WP_MySQL_Lexer::PLUS_OPERATOR === $tokens[ $literal['end'] ]->id
				&& $this->is_mysql_zero_numeric_literal_range( $tokens, $literal['start'], $literal['end'] )
			) {
			return array(
				'sql'      => $reference_sql,
				'position' => $reference['end'] - 1,
			);
		}

			return array(
				'sql'      => sprintf(
					'%s %s %s',
					$this->translate_mysql_token_sequence_to_postgresql( $tokens, $literal['start'], $literal['end'] ),
					$tokens[ $literal['end'] ]->get_bytes(),
					$reference_sql
				),
				'position' => $reference['end'] - 1,
			);
	}

	/**
	 * Build a single-table statement scope.
	 *
	 * @param string      $table_name Table name.
	 * @param string|null $alias      Optional table alias.
	 * @param string      $schema     Metadata schema.
	 * @return array Statement scope.
	 */
	private function get_mysql_single_table_scope(
		string $table_name,
		?string $alias = null,
		string $schema = 'public'
	): array {
		$table = array(
			'schema' => $this->resolve_mysql_table_schema_for_introspection( $schema, $table_name ),
			'table'  => $table_name,
		);

		return array(
			'tables'  => array( $table ),
			'aliases' => array(
				strtolower( null === $alias ? $table_name : $alias ) => $table,
			),
		);
	}

	/**
	 * Parse top-level SELECT table references into a metadata lookup scope.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First FROM-clause token after FROM.
	 * @param int             $end    Final FROM-clause token, exclusive.
	 * @return array|null Statement scope, or null when ambiguous/unsupported.
	 */
	private function get_mysql_select_scope( array $tokens, int $start, int $end ): ?array {
		$scope       = array(
			'tables'  => array(),
			'aliases' => array(),
			'unknown' => false,
		);
		$position    = $start;
		$expect_next = true;

		while ( $position < $end ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $position ]->id ) {
				$after_parentheses = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
				if ( null === $after_parentheses ) {
					return null;
				}

				$position = $after_parentheses;
				if ( $expect_next ) {
					$scope['unknown'] = true;
					$position         = $this->skip_mysql_table_alias( $tokens, $position, $end );
					$expect_next      = false;
				}
				continue;
			}

			if ( $expect_next ) {
				$reference = $this->parse_mysql_table_reference( $tokens, $position, $end );
				if ( null === $reference ) {
					return null;
				}

				$table = array(
					'schema' => $this->resolve_mysql_table_schema_for_introspection( $reference['schema'], $reference['table'] ),
					'table'  => $reference['table'],
				);
				$alias = strtolower( null === $reference['alias'] ? $reference['table'] : $reference['alias'] );
				if ( isset( $scope['aliases'][ $alias ] ) ) {
					return null;
				}

				$scope['tables'][]          = $table;
				$scope['aliases'][ $alias ] = $table;
				$position                   = $reference['position'];
				$expect_next                = false;
				continue;
			}

			if (
				WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id
				|| $this->is_mysql_join_token( $tokens[ $position ] )
			) {
				$expect_next = true;
			}

			++$position;
		}

		return empty( $scope['tables'] ) || $expect_next ? null : $scope;
	}

	/**
	 * Parse an unqualified or main database-qualified MySQL table target.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Table-name start position, updated on success.
	 * @return string|null Table name, or null when unsupported.
	 */
	private function parse_mysql_main_database_table_name( array $tokens, int &$position ): ?string {
		$first_identifier = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $first_identifier ) {
			return null;
		}

		++$position;
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::DOT_SYMBOL !== $tokens[ $position ]->id ) {
			return $first_identifier;
		}

		$table_name = $this->get_mysql_identifier_token_value( $tokens[ $position + 1 ] ?? null );
		if ( null === $table_name || 0 !== strcasecmp( $first_identifier, $this->main_db_name ) ) {
			return null;
		}

		$position += 2;
		return $table_name;
	}

	/**
	 * Parse an unqualified or main database-qualified MySQL table reference.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position Table-reference start position, updated on success.
	 * @param int              $end      Final token position, exclusive.
	 * @return array{table: string, alias: string|null}|null Parsed table reference, or null when unsupported.
	 */
	private function parse_mysql_main_database_table_reference( array $tokens, int &$position, int $end ): ?array {
		$table_name = $this->parse_mysql_main_database_table_name( $tokens, $position );
		if ( null === $table_name ) {
			return null;
		}

		$alias = null;
		if ( $position + 1 < $end && WP_MySQL_Lexer::AS_SYMBOL === ( $tokens[ $position ]->id ?? null ) ) {
			$alias = $this->get_mysql_identifier_token_value( $tokens[ $position + 1 ] ?? null );
			if ( null === $alias ) {
				return null;
			}

			$position += 2;
		} else {
			$implicit_alias = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
			if ( null !== $implicit_alias ) {
				$alias = $implicit_alias;
				++$position;
			}
		}

		return array(
			'table' => $table_name,
			'alias' => $alias,
		);
	}

	/**
	 * Render a PostgreSQL DML table reference with optional alias.
	 *
	 * @param string      $table_name Table name.
	 * @param string|null $alias      Optional table alias.
	 * @return string PostgreSQL table reference SQL.
	 */
	private function get_postgresql_dml_table_reference_sql( string $table_name, ?string $alias ): string {
		$sql = $this->connection->quote_identifier( $table_name );
		if ( null !== $alias ) {
			$sql .= ' AS ' . $this->connection->quote_identifier( $alias );
		}

		return $sql;
	}

	/**
	 * Render a PostgreSQL target ctid reference for bounded UPDATE/DELETE rewrites.
	 *
	 * @param string|null $alias Optional table alias.
	 * @return string PostgreSQL ctid reference SQL.
	 */
	private function get_postgresql_dml_ctid_reference_sql( ?string $alias ): string {
		if ( null === $alias ) {
			return 'ctid';
		}

		return $this->connection->quote_identifier( $alias ) . '.ctid';
	}

	/**
	 * Render a PostgreSQL target-column reference for DML predicates.
	 *
	 * @param string      $column Column name.
	 * @param string|null $alias  Optional table alias.
	 * @return string PostgreSQL column reference SQL.
	 */
	private function get_postgresql_dml_column_reference_sql( string $column, ?string $alias ): string {
		$column_sql = $this->connection->quote_identifier( $column );
		if ( null === $alias ) {
			return $column_sql;
		}

		return $this->connection->quote_identifier( $alias ) . '.' . $column_sql;
	}

	/**
	 * Check whether a MySQL table qualifier names the current DML target.
	 *
	 * @param string      $qualifier  MySQL qualifier.
	 * @param string      $table_name Table name.
	 * @param string|null $alias      Optional table alias.
	 * @return bool Whether the qualifier is supported.
	 */
	private function is_mysql_dml_table_qualifier( string $qualifier, string $table_name, ?string $alias ): bool {
		return 0 === strcasecmp( $qualifier, $table_name )
			|| ( null !== $alias && 0 === strcasecmp( $qualifier, $alias ) );
	}

	/**
	 * Get PostgreSQL SQL for an unqualified or main database-qualified table target.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First table-reference token position.
	 * @param int              $end    Final table-reference token position, exclusive.
	 * @return string PostgreSQL table reference SQL.
	 */
	private function get_mysql_main_database_table_reference_sql( array $tokens, int $start, int $end ): string {
		if (
			$start + 3 === $end
			&& isset( $tokens[ $start + 1 ], $tokens[ $start + 2 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $start + 1 ]->id
		) {
			return $this->translate_mysql_identifier_token_to_postgresql( $tokens[ $start + 2 ] );
		}

		return $this->translate_mysql_identifier_token_to_postgresql( $tokens[ $start ] ?? null );
	}

	/**
	 * Parse a simple table reference and optional alias.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Table reference start position.
	 * @param int             $end      Final FROM-clause token, exclusive.
	 * @return array{schema: string, table: string, alias: string|null, position: int}|null Parsed table reference.
	 */
	private function parse_mysql_table_reference( array $tokens, int $position, int $end ): ?array {
		$first_identifier = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $first_identifier ) {
			return null;
		}

		$schema = 'public';
		$table  = $first_identifier;
		++$position;

		if ( $position + 1 < $end && WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position ]->id ) {
			$second_identifier = $this->get_mysql_identifier_token_value( $tokens[ $position + 1 ] ?? null );
			if ( null === $second_identifier ) {
				return null;
			}

			$schema    = $first_identifier;
			$table     = $second_identifier;
			$position += 2;
		}

		$alias = null;
		if ( $position + 1 < $end && WP_MySQL_Lexer::AS_SYMBOL === $tokens[ $position ]->id ) {
			$alias = $this->get_mysql_identifier_token_value( $tokens[ $position + 1 ] ?? null );
			if ( null === $alias ) {
				return null;
			}

			$position += 2;
		} else {
			$implicit_alias = $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null );
			if ( null !== $implicit_alias ) {
				$alias = $implicit_alias;
				++$position;
			}
		}

		return array(
			'schema'   => $schema,
			'table'    => $table,
			'alias'    => $alias,
			'position' => $position,
		);
	}

	/**
	 * Skip a derived-table alias when one is present.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Current token position.
	 * @param int             $end      Final FROM-clause token, exclusive.
	 * @return int Position after the alias.
	 */
	private function skip_mysql_table_alias( array $tokens, int $position, int $end ): int {
		if ( $position + 1 < $end && WP_MySQL_Lexer::AS_SYMBOL === $tokens[ $position ]->id ) {
			return null === $this->get_mysql_identifier_token_value( $tokens[ $position + 1 ] ?? null )
				? $position
				: $position + 2;
		}

		return null === $this->get_mysql_identifier_token_value( $tokens[ $position ] ?? null )
			? $position
			: $position + 1;
	}

	/**
	 * Check whether a token starts a JOIN table operand.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token is a JOIN separator.
	 */
	private function is_mysql_join_token( WP_MySQL_Token $token ): bool {
		return WP_MySQL_Lexer::JOIN_SYMBOL === $token->id || WP_MySQL_Lexer::STRAIGHT_JOIN_SYMBOL === $token->id;
	}

	/**
	 * Parse a simple column reference.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Column reference start position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{start: int, end: int, qualifier: string|null, column: string}|null Parsed reference.
	 */
	private function parse_mysql_column_reference( array $tokens, int $position, int $end ): ?array {
		$first_identifier = $this->get_mysql_dml_identifier_token_value( $tokens[ $position ] ?? null );
		if ( null === $first_identifier ) {
			return null;
		}

		if ( $position + 2 < $end && WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position + 1 ]->id ) {
			$column = $this->get_mysql_dml_identifier_token_value( $tokens[ $position + 2 ] ?? null );
			if ( null === $column ) {
				return null;
			}

			return array(
				'start'     => $position,
				'end'       => $position + 3,
				'qualifier' => $first_identifier,
				'column'    => $column,
			);
		}

		return array(
			'start'     => $position,
			'end'       => $position + 1,
			'qualifier' => null,
			'column'    => $first_identifier,
		);
	}

	/**
	 * Check whether a column reference resolves to one integer-family MySQL column.
	 *
	 * @param array $reference Parsed column reference.
	 * @param array $scope     Statement table scope.
	 * @return bool Whether the reference is a known integer column.
	 */
	private function is_mysql_integer_column_reference( array $reference, array $scope ): bool {
		$column_type = $this->get_mysql_column_type_for_reference( $reference, $scope );
		return null !== $column_type && $this->is_mysql_integer_family_column_type( $column_type );
	}

	/**
	 * Check whether a column reference resolves to one text-family MySQL column.
	 *
	 * @param array $reference Parsed column reference.
	 * @param array $scope     Statement table scope.
	 * @return bool Whether the reference is a known text column.
	 */
	private function is_mysql_text_family_column_reference( array $reference, array $scope ): bool {
		$column_type = $this->get_mysql_column_type_for_reference( $reference, $scope );
		return null !== $column_type && $this->is_mysql_text_family_column_type( $column_type );
	}

	/**
	 * Check whether a MySQL column type belongs to the text family.
	 *
	 * @param string $column_type MySQL column type metadata.
	 * @return bool Whether the type stores textual data.
	 */
	private function is_mysql_text_family_column_type( string $column_type ): bool {
		return in_array(
			$this->get_base_mysql_dml_column_type( $column_type ),
			array(
				'char',
				'longtext',
				'mediumtext',
				'text',
				'tinytext',
				'varchar',
			),
			true
		);
	}

	/**
	 * Resolve a column reference to stored MySQL column type metadata.
	 *
	 * @param array $reference Parsed column reference.
	 * @param array $scope     Statement table scope.
	 * @return string|null MySQL column type, or null when missing/ambiguous.
	 */
	private function get_mysql_column_type_for_reference( array $reference, array $scope ): ?string {
		if ( null !== $reference['qualifier'] ) {
			$alias = strtolower( $reference['qualifier'] );
			if ( ! isset( $scope['aliases'][ $alias ] ) ) {
				return null;
			}

			$table = $scope['aliases'][ $alias ];
			if ( ! empty( $table['derived'] ) || null === ( $table['table'] ?? null ) ) {
				return null;
			}

			return $this->get_mysql_table_column_type( $table['schema'], $table['table'], $reference['column'] );
		}

		if ( ! empty( $scope['unknown'] ) ) {
			return null;
		}

		$matched_type = null;
		foreach ( $scope['tables'] as $table ) {
			if ( ! empty( $table['derived'] ) || null === ( $table['table'] ?? null ) ) {
				return null;
			}

			if (
				count( $scope['tables'] ) > 1
				&& ! $this->mysql_table_has_column_metadata( $table['schema'], $table['table'] )
			) {
				return null;
			}

			$column_type = $this->get_mysql_table_column_type( $table['schema'], $table['table'], $reference['column'] );
			if ( null === $column_type ) {
				continue;
			}

			if ( null !== $matched_type ) {
				return null;
			}

			$matched_type = $column_type;
		}

		return $matched_type;
	}

	/**
	 * Resolve a column reference to stored MySQL collation metadata.
	 *
	 * @param array $reference Parsed column reference.
	 * @param array $scope     Statement table scope.
	 * @return string|null MySQL collation, or null when missing/ambiguous.
	 */
	private function get_mysql_column_collation_for_reference( array $reference, array $scope ): ?string {
		if ( null !== $reference['qualifier'] ) {
			$alias = strtolower( $reference['qualifier'] );
			if ( ! isset( $scope['aliases'][ $alias ] ) ) {
				return null;
			}

			$table = $scope['aliases'][ $alias ];
			if ( ! empty( $table['derived'] ) || null === ( $table['table'] ?? null ) ) {
				return null;
			}

			return $this->get_mysql_table_column_collation( $table['schema'], $table['table'], $reference['column'] );
		}

		if ( ! empty( $scope['unknown'] ) ) {
			return null;
		}

		$matched_collation = null;
		foreach ( $scope['tables'] as $table ) {
			if ( ! empty( $table['derived'] ) || null === ( $table['table'] ?? null ) ) {
				return null;
			}

			if (
				count( $scope['tables'] ) > 1
				&& ! $this->mysql_table_has_column_metadata( $table['schema'], $table['table'] )
			) {
				return null;
			}

			$collation = $this->get_mysql_table_column_collation( $table['schema'], $table['table'], $reference['column'] );
			if ( null === $collation ) {
				continue;
			}

			if ( null !== $matched_collation ) {
				return null;
			}

			$matched_collation = $collation;
		}

		return $matched_collation;
	}

	/**
	 * Check whether a token range is exactly one string literal.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First token position.
	 * @param int             $end    Final token position, exclusive.
	 * @return bool Whether the range is one string literal.
	 */
	private function is_mysql_string_literal_range( array $tokens, int $start, int $end ): bool {
		return $start + 1 === $end && isset( $tokens[ $start ] ) && $this->is_mysql_string_literal_token( $tokens[ $start ] );
	}

	/**
	 * Check whether a token range is a literal zero value.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First literal token.
	 * @param int             $end    Final literal token, exclusive.
	 * @return bool Whether the literal is zero.
	 */
	private function is_mysql_zero_literal_range( array $tokens, int $start, int $end ): bool {
		if ( $this->is_mysql_string_literal_range( $tokens, $start, $end ) ) {
			return 1 === preg_match( '/^[[:space:]]*[+]?0+[[:space:]]*$/', $tokens[ $start ]->get_value() );
		}

		$literal = $this->parse_mysql_numeric_literal( $tokens, $start, $end );
		return null !== $literal
			&& $literal['start'] === $start
			&& $literal['end'] === $end
			&& $this->is_mysql_zero_numeric_literal_range( $tokens, $start, $end );
	}

	/**
	 * Parse a numeric literal, including an optional unary sign.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Literal start position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{start: int, end: int}|null Numeric literal bounds.
	 */
	private function parse_mysql_numeric_literal( array $tokens, int $position, int $end ): ?array {
		if ( ! isset( $tokens[ $position ] ) || $position >= $end ) {
			return null;
		}

		if (
			(
				WP_MySQL_Lexer::PLUS_OPERATOR === $tokens[ $position ]->id
				|| WP_MySQL_Lexer::MINUS_OPERATOR === $tokens[ $position ]->id
			)
			&& isset( $tokens[ $position + 1 ] )
			&& $position + 1 < $end
			&& $this->is_mysql_numeric_literal_token( $tokens[ $position + 1 ] )
		) {
			return array(
				'start' => $position,
				'end'   => $position + 2,
			);
		}

		if ( $this->is_mysql_numeric_literal_token( $tokens[ $position ] ) ) {
			return array(
				'start' => $position,
				'end'   => $position + 1,
			);
		}

		return null;
	}

	/**
	 * Check whether a numeric literal range represents zero.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First literal token.
	 * @param int             $end    Final literal token, exclusive.
	 * @return bool Whether the literal is numeric zero.
	 */
	private function is_mysql_zero_numeric_literal_range( array $tokens, int $start, int $end ): bool {
		if ( ! isset( $tokens[ $start ] ) ) {
			return false;
		}

		if (
			$start + 2 === $end
			&& (
				WP_MySQL_Lexer::PLUS_OPERATOR === $tokens[ $start ]->id
				|| WP_MySQL_Lexer::MINUS_OPERATOR === $tokens[ $start ]->id
			)
		) {
			++$start;
		}

		return $start + 1 === $end
			&& $this->is_mysql_numeric_literal_token( $tokens[ $start ] )
			&& 0.0 === (float) $tokens[ $start ]->get_value();
	}

	/**
	 * Check whether a numeric literal range is an integer token.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First literal token.
	 * @param int             $end    Final literal token, exclusive.
	 * @return bool Whether the literal is a signed or unsigned integer token.
	 */
	private function is_mysql_integer_numeric_literal_range( array $tokens, int $start, int $end ): bool {
		if ( ! isset( $tokens[ $start ] ) ) {
			return false;
		}

		if (
			$start + 2 === $end
			&& (
				WP_MySQL_Lexer::PLUS_OPERATOR === $tokens[ $start ]->id
				|| WP_MySQL_Lexer::MINUS_OPERATOR === $tokens[ $start ]->id
			)
		) {
			++$start;
		}

		return $start + 1 === $end
			&& in_array(
				$tokens[ $start ]->id,
				array(
					WP_MySQL_Lexer::INT_NUMBER,
					WP_MySQL_Lexer::LONG_NUMBER,
					WP_MySQL_Lexer::ULONGLONG_NUMBER,
				),
				true
			);
	}

	/**
	 * Check whether a token is a numeric literal.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token is a numeric literal.
	 */
	private function is_mysql_numeric_literal_token( WP_MySQL_Token $token ): bool {
		return in_array(
			$token->id,
			array(
				WP_MySQL_Lexer::DECIMAL_NUMBER,
				WP_MySQL_Lexer::FLOAT_NUMBER,
				WP_MySQL_Lexer::INT_NUMBER,
				WP_MySQL_Lexer::LONG_NUMBER,
				WP_MySQL_Lexer::ULONGLONG_NUMBER,
			),
			true
		);
	}

	/**
	 * Check whether a token is a string literal.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token is a string literal.
	 */
	private function is_mysql_string_literal_token( WP_MySQL_Token $token ): bool {
		return WP_MySQL_Lexer::SINGLE_QUOTED_TEXT === $token->id || WP_MySQL_Lexer::DOUBLE_QUOTED_TEXT === $token->id;
	}

	/**
	 * Check whether a token is a simple comparison operator.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token is a comparison operator.
	 */
	private function is_mysql_comparison_operator_token( WP_MySQL_Token $token ): bool {
		return in_array(
			$token->id,
			array(
				WP_MySQL_Lexer::EQUAL_OPERATOR,
				WP_MySQL_Lexer::GREATER_OR_EQUAL_OPERATOR,
				WP_MySQL_Lexer::GREATER_THAN_OPERATOR,
				WP_MySQL_Lexer::LESS_OR_EQUAL_OPERATOR,
				WP_MySQL_Lexer::LESS_THAN_OPERATOR,
				WP_MySQL_Lexer::NOT_EQUAL_OPERATOR,
			),
			true
		);
	}

	/**
	 * Validate the simple expression fragments used by translated DML/SELECT.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First fragment token position.
	 * @param int             $end    Final fragment token position, exclusive.
	 * @return bool Whether the expression fragment is supported.
	 */
	private function is_supported_simple_mysql_expression_fragment( array $tokens, int $start, int $end ): bool {
		for ( $i = $start; $i < $end; $i++ ) {
			if ( ! $this->is_supported_simple_mysql_expression_token( $tokens[ $i ] ) ) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Check that identifier references in a simple expression resolve to scope columns.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First expression token.
	 * @param int              $end    Final expression token, exclusive.
	 * @param array            $scope  Statement table scope.
	 * @return bool Whether all column-like references resolve to the supplied scope.
	 */
	private function mysql_expression_column_references_resolve_to_scope( array $tokens, int $start, int $end, array $scope ): bool {
		for ( $position = $start; $position < $end; $position++ ) {
			if ( $this->is_mysql_qualified_reference_suffix_position( $tokens, $position, $start ) ) {
				continue;
			}

			if ( null === $this->get_mysql_dml_identifier_token_value( $tokens[ $position ] ?? null ) ) {
				continue;
			}

			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === ( $tokens[ $position + 1 ]->id ?? null ) ) {
				continue;
			}

			$reference = $this->parse_mysql_column_reference( $tokens, $position, $end );
			if ( null === $reference ) {
				continue;
			}

			if ( null === $this->get_mysql_column_type_for_reference( $reference, $scope ) ) {
				return false;
			}

			$position = $reference['end'] - 1;
		}

		return true;
	}

	/**
	 * Check that qualified references in a simple expression use statement aliases.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First expression token.
	 * @param int              $end    Final expression token, exclusive.
	 * @param array            $scope  Statement table scope.
	 * @return bool Whether all qualified references use the supplied scope.
	 */
	private function mysql_expression_qualified_references_resolve_to_scope( array $tokens, int $start, int $end, array $scope ): bool {
		for ( $position = $start; $position < $end; $position++ ) {
			if ( $this->is_mysql_qualified_reference_suffix_position( $tokens, $position, $start ) ) {
				continue;
			}

			if ( null === $this->get_mysql_dml_identifier_token_value( $tokens[ $position ] ?? null ) ) {
				continue;
			}

			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === ( $tokens[ $position + 1 ]->id ?? null ) ) {
				continue;
			}

			$reference = $this->parse_mysql_column_reference( $tokens, $position, $end );
			if ( null === $reference ) {
				continue;
			}

			if (
				null !== $reference['qualifier']
				&& ! isset( $scope['aliases'][ strtolower( $reference['qualifier'] ) ] )
			) {
				return false;
			}

			$position = $reference['end'] - 1;
		}

		return true;
	}

	/**
	 * Validate a token for a simple expression fragment.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token is supported.
	 */
	private function is_supported_simple_mysql_expression_token( WP_MySQL_Token $token ): bool {
		if ( null !== $this->get_mysql_dml_identifier_token_value( $token ) ) {
			return true;
		}

		return in_array(
			$token->id,
			array(
				WP_MySQL_Lexer::AND_SYMBOL,
				WP_MySQL_Lexer::CLOSE_PAR_SYMBOL,
				WP_MySQL_Lexer::COMMA_SYMBOL,
				WP_MySQL_Lexer::DECIMAL_NUMBER,
				WP_MySQL_Lexer::DOT_SYMBOL,
				WP_MySQL_Lexer::EQUAL_OPERATOR,
				WP_MySQL_Lexer::FALSE_SYMBOL,
				WP_MySQL_Lexer::FLOAT_NUMBER,
				WP_MySQL_Lexer::GREATER_OR_EQUAL_OPERATOR,
				WP_MySQL_Lexer::GREATER_THAN_OPERATOR,
				WP_MySQL_Lexer::HEX_NUMBER,
				WP_MySQL_Lexer::IN_SYMBOL,
				WP_MySQL_Lexer::INT_NUMBER,
				WP_MySQL_Lexer::LESS_OR_EQUAL_OPERATOR,
				WP_MySQL_Lexer::LESS_THAN_OPERATOR,
				WP_MySQL_Lexer::LIKE_SYMBOL,
				WP_MySQL_Lexer::LONG_NUMBER,
				WP_MySQL_Lexer::MINUS_OPERATOR,
				WP_MySQL_Lexer::MULT_OPERATOR,
				WP_MySQL_Lexer::NOT_SYMBOL,
				WP_MySQL_Lexer::NOT_EQUAL_OPERATOR,
				WP_MySQL_Lexer::NULL_SYMBOL,
				WP_MySQL_Lexer::OPEN_PAR_SYMBOL,
				WP_MySQL_Lexer::OR_SYMBOL,
				WP_MySQL_Lexer::PLUS_OPERATOR,
				WP_MySQL_Lexer::REGEXP_SYMBOL,
				WP_MySQL_Lexer::SINGLE_QUOTED_TEXT,
				WP_MySQL_Lexer::SUBSTR_SYMBOL,
				WP_MySQL_Lexer::SUBSTRING_SYMBOL,
				WP_MySQL_Lexer::TRUE_SYMBOL,
				WP_MySQL_Lexer::ULONGLONG_NUMBER,
				WP_MySQL_Lexer::XOR_SYMBOL,
			),
			true
		);
	}

	/**
	 * Validate a simple ORDER BY clause.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  ORDER token position.
	 * @param int             $end    Final clause token position, exclusive.
	 * @return bool Whether the ORDER BY clause is supported.
	 */
	private function is_supported_simple_select_order_by_clause( array $tokens, int $start, int $end ): bool {
		if (
			$start + 2 >= $end
			|| WP_MySQL_Lexer::ORDER_SYMBOL !== $tokens[ $start ]->id
			|| WP_MySQL_Lexer::BY_SYMBOL !== $tokens[ $start + 1 ]->id
			|| null === $this->get_mysql_identifier_token_value( $tokens[ $start + 2 ] )
		) {
			return false;
		}

		if ( $start + 3 === $end ) {
			return true;
		}

		return $start + 4 === $end
			&& (
				WP_MySQL_Lexer::ASC_SYMBOL === $tokens[ $start + 3 ]->id
				|| WP_MySQL_Lexer::DESC_SYMBOL === $tokens[ $start + 3 ]->id
			);
	}

	/**
	 * Validate a safe trailing SELECT LIMIT clause.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  LIMIT token position.
	 * @param int             $end    Final clause token position, exclusive.
	 * @return bool Whether the LIMIT clause is supported.
	 */
	private function is_supported_simple_select_limit_clause( array $tokens, int $start, int $end ): bool {
		if (
			! isset( $tokens[ $start ], $tokens[ $start + 1 ] )
			|| WP_MySQL_Lexer::LIMIT_SYMBOL !== $tokens[ $start ]->id
		) {
			return false;
		}

		if ( $start + 2 === $end ) {
			return $this->is_supported_simple_select_limit_number( $tokens[ $start + 1 ] );
		}

		return $start + 4 === $end
			&& isset( $tokens[ $start + 2 ], $tokens[ $start + 3 ] )
			&& WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $start + 2 ]->id
			&& $this->is_supported_simple_select_limit_number( $tokens[ $start + 1 ] )
			&& $this->is_supported_simple_select_limit_number( $tokens[ $start + 3 ] );
	}

	/**
	 * Validate a LIMIT number token.
	 *
	 * @param WP_MySQL_Token $token MySQL lexer token.
	 * @return bool Whether the token is a supported non-negative integer.
	 */
	private function is_supported_simple_select_limit_number( WP_MySQL_Token $token ): bool {
		$is_parameter_marker = WP_MySQL_Lexer::PARAM_MARKER === $token->id;
		return in_array(
			$token->id,
			array(
				WP_MySQL_Lexer::INT_NUMBER,
				WP_MySQL_Lexer::LONG_NUMBER,
				WP_MySQL_Lexer::PARAM_MARKER,
				WP_MySQL_Lexer::ULONGLONG_NUMBER,
			),
			true
		) && ( $is_parameter_marker || ctype_digit( $token->get_value() ) );
	}

	/**
	 * Check whether a DML ORDER BY clause has a non-empty item list.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  ORDER token position.
	 * @param int              $end    Final clause token position, exclusive.
	 * @return bool Whether this is a non-empty ORDER BY clause.
	 */
	private function is_nonempty_mysql_order_by_clause( array $tokens, int $start, int $end ): bool {
		if (
			$start + 2 >= $end
			|| WP_MySQL_Lexer::ORDER_SYMBOL !== ( $tokens[ $start ]->id ?? null )
			|| WP_MySQL_Lexer::BY_SYMBOL !== ( $tokens[ $start + 1 ]->id ?? null )
		) {
			return false;
		}

		$items = $this->split_top_level_mysql_arguments( $tokens, $start + 2, $end );
		return null !== $items && ! empty( $items );
	}

	/**
	 * Translate a safe DML ORDER BY clause.
	 *
	 * @param WP_MySQL_Token[] $tokens     MySQL lexer token stream.
	 * @param int              $start      ORDER token position.
	 * @param int              $end        Final clause token position, exclusive.
	 * @param string           $table_name Table name.
	 * @param string|null      $alias      Optional table alias.
	 * @return string|null PostgreSQL ORDER BY clause SQL, or null when unsupported.
	 */
	private function translate_simple_dml_order_by_clause_to_postgresql( array $tokens, int $start, int $end, string $table_name, ?string $alias ): ?string {
		if (
			$start + 2 >= $end
			|| WP_MySQL_Lexer::ORDER_SYMBOL !== ( $tokens[ $start ]->id ?? null )
			|| WP_MySQL_Lexer::BY_SYMBOL !== ( $tokens[ $start + 1 ]->id ?? null )
		) {
			return null;
		}

		$items    = array();
		$position = $start + 2;
		while ( $position < $end ) {
			$item_start = $position;
			$reference  = $this->parse_mysql_column_reference( $tokens, $position, $end );
			if ( null === $reference ) {
				return null;
			}

			if (
				null !== $reference['qualifier']
				&& ! $this->is_mysql_dml_table_qualifier( $reference['qualifier'], $table_name, $alias )
			) {
				return null;
			}

			$position = $reference['end'];
			if (
				$position < $end
				&& (
					WP_MySQL_Lexer::ASC_SYMBOL === ( $tokens[ $position ]->id ?? null )
					|| WP_MySQL_Lexer::DESC_SYMBOL === ( $tokens[ $position ]->id ?? null )
				)
			) {
				++$position;
			}

			$items[] = $this->translate_mysql_token_sequence_to_postgresql( $tokens, $item_start, $position );
			if ( $position === $end ) {
				break;
			}

			if ( WP_MySQL_Lexer::COMMA_SYMBOL !== ( $tokens[ $position ]->id ?? null ) ) {
				return null;
			}
			++$position;
		}

		return empty( $items ) ? null : ' ORDER BY ' . implode( ', ', $items );
	}

	/**
	 * Translate a joined DML ORDER BY clause against the statement table scope.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  ORDER token position.
	 * @param int              $end    Final clause token position, exclusive.
	 * @param array            $scope  Statement table scope.
	 * @return string|null PostgreSQL ORDER BY clause SQL, or null when unsupported.
	 */
	private function translate_mysql_joined_dml_order_by_clause_to_postgresql( array $tokens, int $start, int $end, array $scope ): ?string {
		if (
			$start + 2 >= $end
			|| WP_MySQL_Lexer::ORDER_SYMBOL !== ( $tokens[ $start ]->id ?? null )
			|| WP_MySQL_Lexer::BY_SYMBOL !== ( $tokens[ $start + 1 ]->id ?? null )
		) {
			return null;
		}

		$item_ranges = $this->split_top_level_mysql_arguments( $tokens, $start + 2, $end );
		if ( null === $item_ranges || empty( $item_ranges ) ) {
			return null;
		}

		$items = array();
		foreach ( $item_ranges as $item_range ) {
			$item_start = $item_range['start'];
			$item_end   = $item_range['end'];
			$direction  = '';
			if (
				$item_start < $item_end
				&& (
					WP_MySQL_Lexer::ASC_SYMBOL === ( $tokens[ $item_end - 1 ]->id ?? null )
					|| WP_MySQL_Lexer::DESC_SYMBOL === ( $tokens[ $item_end - 1 ]->id ?? null )
				)
			) {
				$direction = ' ' . strtoupper( $tokens[ $item_end - 1 ]->get_bytes() );
				--$item_end;
			}

			if (
				$item_start >= $item_end
				|| ! $this->is_supported_simple_mysql_expression_fragment( $tokens, $item_start, $item_end )
				|| ! $this->mysql_expression_qualified_references_resolve_to_scope( $tokens, $item_start, $item_end, $scope )
			) {
				return null;
			}

			$expression = $this->translate_mysql_expression_token_sequence_to_postgresql(
				$tokens,
				$item_start,
				$item_end,
				$scope
			);
			$items[]    = $expression['sql'] . $direction;
		}

		return ' ORDER BY ' . implode( ', ', $items );
	}

	/**
	 * Translate a safe DML LIMIT row-count clause.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  LIMIT token position.
	 * @param int              $end    Final clause token position, exclusive.
	 * @param bool             $allow_offset_count Whether LIMIT offset,count is supported for this DML statement.
	 * @return string|null PostgreSQL LIMIT clause SQL, or null when unsupported.
	 */
	private function translate_simple_dml_limit_clause_to_postgresql( array $tokens, int $start, int $end, bool $allow_offset_count = false ): ?string {
		if (
			WP_MySQL_Lexer::LIMIT_SYMBOL !== ( $tokens[ $start ]->id ?? null )
			|| ! isset( $tokens[ $start + 1 ] )
		) {
			return null;
		}

		if ( $start + 2 === $end && $this->is_supported_simple_select_limit_number( $tokens[ $start + 1 ] ) ) {
			return ' LIMIT ' . $tokens[ $start + 1 ]->get_bytes();
		}

		if (
			$allow_offset_count
			&& $start + 4 === $end
			&& isset( $tokens[ $start + 2 ], $tokens[ $start + 3 ] )
			&& WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $start + 2 ]->id
			&& $this->is_supported_simple_select_limit_number( $tokens[ $start + 1 ] )
			&& $this->is_supported_simple_select_limit_number( $tokens[ $start + 3 ] )
		) {
			return ' LIMIT ' . $tokens[ $start + 3 ]->get_bytes() . ' OFFSET ' . $tokens[ $start + 1 ]->get_bytes();
		}

		if (
			$allow_offset_count
			&& $start + 4 === $end
			&& isset( $tokens[ $start + 2 ], $tokens[ $start + 3 ] )
			&& WP_MySQL_Lexer::OFFSET_SYMBOL === $tokens[ $start + 2 ]->id
			&& $this->is_supported_simple_select_limit_number( $tokens[ $start + 1 ] )
			&& $this->is_supported_simple_select_limit_number( $tokens[ $start + 3 ] )
		) {
			return ' LIMIT ' . $tokens[ $start + 1 ]->get_bytes() . ' OFFSET ' . $tokens[ $start + 3 ]->get_bytes();
		}

		return null;
	}

	/**
	 * Translate a supported trailing SELECT LIMIT clause to PostgreSQL.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  LIMIT token position.
	 * @param int             $end    Final clause token position, exclusive.
	 * @return string PostgreSQL LIMIT clause.
	 */
	private function translate_simple_select_limit_clause_to_postgresql( array $tokens, int $start, int $end ): string {
		if ( $start + 4 === $end ) {
			return ' LIMIT ' . $tokens[ $start + 3 ]->get_bytes() . ' OFFSET ' . $tokens[ $start + 1 ]->get_bytes();
		}

		return ' LIMIT ' . $tokens[ $start + 1 ]->get_bytes();
	}

	/**
	 * Strip MySQL SELECT row-locking clauses.
	 *
	 * SQLite strips these clauses because file-level locking already protects the
	 * database. The PostgreSQL adapter uses the same compatibility behavior so
	 * MySQL plugin queries keep running even when the test backend is SQLite.
	 *
	 * @param string $query MySQL SELECT query.
	 * @return string|null PostgreSQL SQL without the locking clause, or null when absent.
	 */
	private function translate_mysql_select_row_locking_query( string $query ): ?string {
		$tokens = $this->get_mysql_tokens( $query );
		if ( ! isset( $tokens[0] ) || WP_MySQL_Lexer::SELECT_SYMBOL !== $tokens[0]->id ) {
			return null;
		}

		$statement_end = $this->get_mysql_statement_end_position( $tokens, 1 );
		if ( null === $statement_end ) {
			return null;
		}

		$locking_start = $this->find_mysql_select_row_locking_clause_start( $tokens, 1, $statement_end );
		if ( null === $locking_start ) {
			return null;
		}

		$stripped_query = $this->translate_mysql_token_sequence_to_postgresql( $tokens, 0, $locking_start );
		return $this->translate_mysql_select_query_for_postgresql( $stripped_query )['sql'];
	}

	/**
	 * Find a supported trailing SELECT row-locking clause.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First token to scan.
	 * @param int              $end    Final statement token position, exclusive.
	 * @return int|null Locking clause start position, or null when absent.
	 */
	private function find_mysql_select_row_locking_clause_start( array $tokens, int $start, int $end ): ?int {
		$depth = 0;
		for ( $i = $start; $i < $end; $i++ ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $i ]->id ) {
				++$depth;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $i ]->id ) {
				--$depth;
				if ( $depth < 0 ) {
					return null;
				}
				continue;
			}

			if ( 0 !== $depth ) {
				continue;
			}

			if (
				WP_MySQL_Lexer::FOR_SYMBOL === $tokens[ $i ]->id
				&& isset( $tokens[ $i + 1 ] )
				&& in_array( $tokens[ $i + 1 ]->id, array( WP_MySQL_Lexer::SHARE_SYMBOL, WP_MySQL_Lexer::UPDATE_SYMBOL ), true )
			) {
				if ( $end === $this->parse_supported_mysql_select_row_locking_clause( $tokens, $i, $end ) ) {
					return $i;
				}

				throw new InvalidArgumentException( 'Unsupported SELECT locking clause.' );
			}

			if (
				WP_MySQL_Lexer::LOCK_SYMBOL === $tokens[ $i ]->id
				&& isset( $tokens[ $i + 1 ] )
				&& WP_MySQL_Lexer::IN_SYMBOL === $tokens[ $i + 1 ]->id
			) {
				if ( $end === $this->parse_supported_mysql_select_row_locking_clause( $tokens, $i, $end ) ) {
					return $i;
				}

				throw new InvalidArgumentException( 'Unsupported SELECT locking clause.' );
			}
		}

		return null;
	}

	/**
	 * Parse a supported MySQL SELECT row-locking clause.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First locking token.
	 * @param int              $end    Final statement token position, exclusive.
	 * @return int|null Position after the clause, or null when unsupported.
	 */
	private function parse_supported_mysql_select_row_locking_clause( array $tokens, int $start, int $end ): ?int {
		if (
			isset( $tokens[ $start ], $tokens[ $start + 1 ], $tokens[ $start + 2 ], $tokens[ $start + 3 ] )
			&& WP_MySQL_Lexer::LOCK_SYMBOL === $tokens[ $start ]->id
			&& WP_MySQL_Lexer::IN_SYMBOL === $tokens[ $start + 1 ]->id
			&& WP_MySQL_Lexer::SHARE_SYMBOL === $tokens[ $start + 2 ]->id
			&& WP_MySQL_Lexer::MODE_SYMBOL === $tokens[ $start + 3 ]->id
		) {
			return $start + 4;
		}

		if (
			! isset( $tokens[ $start ], $tokens[ $start + 1 ] )
			|| WP_MySQL_Lexer::FOR_SYMBOL !== $tokens[ $start ]->id
			|| ! in_array( $tokens[ $start + 1 ]->id, array( WP_MySQL_Lexer::SHARE_SYMBOL, WP_MySQL_Lexer::UPDATE_SYMBOL ), true )
		) {
			return null;
		}

		$position = $start + 2;
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::OF_SYMBOL === $tokens[ $position ]->id ) {
			$position = $this->parse_mysql_select_locking_table_reference_list( $tokens, $position + 1, $end );
			if ( null === $position ) {
				return null;
			}
		}

		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::NOWAIT_SYMBOL === $tokens[ $position ]->id ) {
			return $position + 1;
		}

		if (
			isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::SKIP_SYMBOL === $tokens[ $position ]->id
			&& WP_MySQL_Lexer::LOCKED_SYMBOL === $tokens[ $position + 1 ]->id
		) {
			return $position + 2;
		}

		return $position;
	}

	/**
	 * Parse an OF table-reference list in a SELECT locking clause.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First table-reference token.
	 * @param int              $end    Final statement token position, exclusive.
	 * @return int|null Position after the list, or null when unsupported.
	 */
	private function parse_mysql_select_locking_table_reference_list( array $tokens, int $start, int $end ): ?int {
		$position = $this->parse_mysql_select_locking_table_reference( $tokens, $start, $end );
		if ( null === $position ) {
			return null;
		}

		while ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::COMMA_SYMBOL === $tokens[ $position ]->id ) {
			$position = $this->parse_mysql_select_locking_table_reference( $tokens, $position + 1, $end );
			if ( null === $position ) {
				return null;
			}
		}

		return $position;
	}

	/**
	 * Parse one table reference in a SELECT locking clause.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int              $start  First table-reference token.
	 * @param int              $end    Final statement token position, exclusive.
	 * @return int|null Position after the table reference, or null when unsupported.
	 */
	private function parse_mysql_select_locking_table_reference( array $tokens, int $start, int $end ): ?int {
		if ( $start >= $end || null === $this->get_mysql_identifier_token_value( $tokens[ $start ] ?? null ) ) {
			return null;
		}

		$position = $start + 1;
		while (
			isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $position ]->id
			&& null !== $this->get_mysql_identifier_token_value( $tokens[ $position + 1 ] )
		) {
			$position += 2;
		}

		return $position;
	}

	/**
	 * Find the token position ending a single MySQL statement.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Token position where scanning starts.
	 * @return int|null EOF or semicolon token position, or null for multi-statements.
	 */
	private function get_mysql_statement_end_position( array $tokens, int $position ): ?int {
		for ( $i = $position; isset( $tokens[ $i ] ); $i++ ) {
			if ( WP_MySQL_Lexer::EOF === $tokens[ $i ]->id ) {
				return $i;
			}

			if ( WP_MySQL_Lexer::SEMICOLON_SYMBOL === $tokens[ $i ]->id ) {
				return $this->is_at_mysql_query_end( $tokens, $i ) ? $i : null;
			}
		}

		return null;
	}

	/**
	 * Find the position after a matching parenthesized token sequence.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Opening parenthesis position.
	 * @param int             $limit    Final token position, exclusive.
	 * @return int|null Position after the matching close parenthesis, or null.
	 */
	private function get_mysql_parenthesized_sequence_end( array $tokens, int $position, int $limit ): ?int {
		if ( ! isset( $tokens[ $position ] ) || WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		$depth = 0;
		for ( $i = $position; $i < $limit; $i++ ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $i ]->id ) {
				++$depth;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL !== $tokens[ $i ]->id ) {
				continue;
			}

			--$depth;
			if ( 0 === $depth ) {
				return $i + 1;
			}

			if ( $depth < 0 ) {
				return null;
			}
		}

		return null;
	}

	/**
	 * Find a top-level MySQL token in a bounded token range.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $token_id Token ID to find.
	 * @param int             $start    First token position, inclusive.
	 * @param int             $end      Final token position, exclusive.
	 * @return int|null Token position, or null when not found.
	 */
	private function find_top_level_mysql_token( array $tokens, int $token_id, int $start, int $end ): ?int {
		$depth = 0;

		for ( $i = $start; $i < $end; $i++ ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $i ]->id ) {
				++$depth;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $i ]->id ) {
				--$depth;
				if ( $depth < 0 ) {
					return null;
				}
				continue;
			}

			if ( 0 === $depth && $token_id === $tokens[ $i ]->id ) {
				return $i;
			}
		}

		return null;
	}

	/**
	 * Find the first top-level token matching any supplied token ID.
	 *
	 * @param WP_MySQL_Token[] $tokens    MySQL lexer token stream.
	 * @param int[]           $token_ids Token IDs to find.
	 * @param int             $start     First token position, inclusive.
	 * @param int             $end       Final token position, exclusive.
	 * @return int|null Token position, or null when not found.
	 */
	private function find_first_top_level_mysql_token( array $tokens, array $token_ids, int $start, int $end ): ?int {
		$lookup = array();
		foreach ( $token_ids as $token_id ) {
			$lookup[ $token_id ] = true;
		}

		$depth = 0;
		for ( $i = $start; $i < $end; $i++ ) {
			if ( WP_MySQL_Lexer::OPEN_PAR_SYMBOL === $tokens[ $i ]->id ) {
				++$depth;
				continue;
			}

			if ( WP_MySQL_Lexer::CLOSE_PAR_SYMBOL === $tokens[ $i ]->id ) {
				--$depth;
				if ( $depth < 0 ) {
					return null;
				}
				continue;
			}

			if ( 0 === $depth && isset( $lookup[ $tokens[ $i ]->id ] ) ) {
				return $i;
			}
		}

		return null;
	}

	/**
	 * Check whether a bounded token range contains any top-level token IDs.
	 *
	 * @param WP_MySQL_Token[] $tokens    MySQL lexer token stream.
	 * @param int             $start     First token position, inclusive.
	 * @param int             $end       Final token position, exclusive.
	 * @param int[]           $token_ids Token IDs to detect.
	 * @return bool Whether any token ID was found.
	 */
	private function contains_top_level_mysql_token( array $tokens, int $start, int $end, array $token_ids ): bool {
		foreach ( $token_ids as $token_id ) {
			if ( null !== $this->find_top_level_mysql_token( $tokens, $token_id, $start, $end ) ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Check whether the token position is at the end of a single query.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Current token position.
	 * @return bool Whether only an optional semicolon and EOF remain.
	 */
	private function is_at_mysql_query_end( array $tokens, int $position ): bool {
		if ( isset( $tokens[ $position ] ) && WP_MySQL_Lexer::SEMICOLON_SYMBOL === $tokens[ $position ]->id ) {
			++$position;
		}

		return isset( $tokens[ $position ] ) && WP_MySQL_Lexer::EOF === $tokens[ $position ]->id;
	}

	/**
	 * Translate a MySQL token sequence to PostgreSQL SQL.
	 *
	 * @param WP_MySQL_Token[] $tokens MySQL lexer token stream.
	 * @param int             $start  First token position, inclusive.
	 * @param int             $end    Final token position, exclusive.
	 * @return string PostgreSQL SQL fragment.
	 */
	private function translate_mysql_token_sequence_to_postgresql( array $tokens, int $start, int $end ): string {
		$sql               = '';
		$previous_token_id = null;

		for ( $i = $start; $i < $end; $i++ ) {
			$token               = $tokens[ $i ];
			$fragment_token_id   = $token->id;
			$translated_fragment = $this->translate_mysql_dual_table_reference_to_postgresql( $tokens, $i, $end );
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_index_hint_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_limit_offset_count_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_field_function_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_integer_cast_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_integer_convert_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_character_cast_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_date_time_cast_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_binary_cast_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_regexp_operator_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_rand_function_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_common_function_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_date_arithmetic_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_week_function_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_weekday_index_function_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_date_format_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_date_time_extract_to_postgresql( $tokens, $i, $end );
			}
			if ( null === $translated_fragment ) {
				$translated_fragment = $this->translate_mysql_convert_using_to_postgresql( $tokens, $i, $end );
			}

			if ( null !== $translated_fragment ) {
				$fragment          = $translated_fragment['sql'];
				$fragment_token_id = $translated_fragment['token_id'];
				$i                 = $translated_fragment['position'];
			} else {
				$fragment = $this->translate_mysql_token_to_postgresql( $token, $tokens[ $i + 1 ] ?? null );
			}

			if ( '' === $fragment ) {
				continue;
			}

			if ( '' === $sql ) {
				$sql = $fragment;
			} elseif ( $this->should_join_mysql_tokens_without_space( $previous_token_id, $fragment_token_id ) ) {
				$sql .= $fragment;
			} else {
				$sql .= ' ' . $fragment;
			}

			$previous_token_id = $fragment_token_id;
		}

		return $sql;
	}

	/**
	 * Translate MySQL's dummy DUAL table reference.
	 *
	 * MySQL accepts SELECT and INSERT ... SELECT statements with FROM DUAL as a
	 * one-row dummy table. PostgreSQL supports the same projections without a
	 * FROM clause, so erase only the exact unaliased FROM DUAL reference.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int              $position FROM token position.
	 * @param int              $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_dual_table_reference_to_postgresql( array $tokens, int $position, int $end ): ?array {
		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::FROM_SYMBOL !== $tokens[ $position ]->id
			|| WP_MySQL_Lexer::DUAL_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return null;
		}

		if (
			isset( $tokens[ $position + 2 ] )
			&& $position + 2 < $end
			&& ! $this->is_mysql_dual_table_reference_boundary_token( $tokens[ $position + 2 ] )
		) {
			return null;
		}

		return array(
			'sql'      => '',
			'token_id' => WP_MySQL_Lexer::FROM_SYMBOL,
			'position' => $position + 1,
		);
	}

	/**
	 * Check whether a token can follow an erased FROM DUAL reference.
	 *
	 * @param WP_MySQL_Token $token MySQL token.
	 * @return bool Whether the token starts a clause or closes the SELECT.
	 */
	private function is_mysql_dual_table_reference_boundary_token( WP_MySQL_Token $token ): bool {
		return in_array(
			$token->id,
			array(
				WP_MySQL_Lexer::CLOSE_PAR_SYMBOL,
				WP_MySQL_Lexer::EOF,
				WP_MySQL_Lexer::GROUP_SYMBOL,
				WP_MySQL_Lexer::HAVING_SYMBOL,
				WP_MySQL_Lexer::LIMIT_SYMBOL,
				WP_MySQL_Lexer::ORDER_SYMBOL,
				WP_MySQL_Lexer::SEMICOLON_SYMBOL,
				WP_MySQL_Lexer::UNION_SYMBOL,
				WP_MySQL_Lexer::WHERE_SYMBOL,
			),
			true
		);
	}

	/**
	 * Erase supported MySQL optimizer index hints.
	 *
	 * PostgreSQL has no equivalent for MySQL's USE/FORCE/IGNORE INDEX hints.
	 * Keep this bounded to the parsed hint clause so surrounding aliases, joins,
	 * predicates, grouping, ordering, and limits are still rendered normally.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Hint keyword token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_index_hint_to_postgresql( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_index_hint_bounds( $tokens, $position, $end );
		if ( null === $bounds ) {
			return null;
		}

		return array(
			'sql'      => '',
			'token_id' => $tokens[ $position ]->id,
			'position' => $bounds['end'] - 1,
		);
	}

	/**
	 * Get token bounds for a supported MySQL optimizer index hint.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Hint keyword token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{end: int}|null Hint bounds, or null when unsupported.
	 */
	private function get_mysql_index_hint_bounds( array $tokens, int $position, int $end ): ?array {
		if ( ! $this->is_mysql_index_hint_marker( $tokens, $position, $end ) ) {
			return null;
		}

		$hint_action = $tokens[ $position ]->id;
		$position   += 2;

		if ( isset( $tokens[ $position ] ) && $position < $end && WP_MySQL_Lexer::FOR_SYMBOL === $tokens[ $position ]->id ) {
			$position = $this->get_mysql_index_hint_scope_end( $tokens, $position, $end );
			if ( null === $position ) {
				return null;
			}
		}

		if ( ! isset( $tokens[ $position ] ) || $position >= $end || WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position, $end );
		if ( null === $after_close ) {
			return null;
		}

		$allow_empty_list = WP_MySQL_Lexer::USE_SYMBOL === $hint_action;
		if ( ! $this->is_mysql_index_hint_identifier_list( $tokens, $position + 1, $after_close - 1, $allow_empty_list ) ) {
			return null;
		}

		return array(
			'end' => $after_close,
		);
	}

	/**
	 * Check whether tokens at a position begin a MySQL optimizer index hint.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Current token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return bool Whether an index hint marker is present.
	 */
	private function is_mysql_index_hint_marker( array $tokens, int $position, int $end ): bool {
		return $position + 1 < $end
			&& $this->is_mysql_index_hint_action_token( $tokens[ $position ] ?? null )
			&& $this->is_mysql_index_hint_type_token( $tokens[ $position + 1 ] ?? null );
	}

	/**
	 * Check whether a token starts a MySQL optimizer index hint.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @return bool Whether the token is USE, FORCE, or IGNORE.
	 */
	private function is_mysql_index_hint_action_token( ?WP_MySQL_Token $token ): bool {
		if ( null === $token ) {
			return false;
		}

		return in_array(
			$token->id,
			array(
				WP_MySQL_Lexer::FORCE_SYMBOL,
				WP_MySQL_Lexer::IGNORE_SYMBOL,
				WP_MySQL_Lexer::USE_SYMBOL,
			),
			true
		);
	}

	/**
	 * Check whether a token names the hinted object type.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @return bool Whether the token is INDEX or KEY.
	 */
	private function is_mysql_index_hint_type_token( ?WP_MySQL_Token $token ): bool {
		if ( null === $token ) {
			return false;
		}

		return WP_MySQL_Lexer::INDEX_SYMBOL === $token->id || WP_MySQL_Lexer::KEY_SYMBOL === $token->id;
	}

	/**
	 * Get the position after a supported MySQL optimizer index hint scope.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position FOR token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return int|null Position after scope tokens, or null when unsupported.
	 */
	private function get_mysql_index_hint_scope_end( array $tokens, int $position, int $end ): ?int {
		if ( ! isset( $tokens[ $position ], $tokens[ $position + 1 ] ) || $position + 1 >= $end ) {
			return null;
		}

		if ( WP_MySQL_Lexer::FOR_SYMBOL !== $tokens[ $position ]->id ) {
			return null;
		}

		if ( WP_MySQL_Lexer::JOIN_SYMBOL === $tokens[ $position + 1 ]->id ) {
			return $position + 2;
		}

		if (
			isset( $tokens[ $position + 2 ] )
			&& $position + 2 < $end
			&& WP_MySQL_Lexer::BY_SYMBOL === $tokens[ $position + 2 ]->id
			&& (
				WP_MySQL_Lexer::GROUP_SYMBOL === $tokens[ $position + 1 ]->id
				|| WP_MySQL_Lexer::ORDER_SYMBOL === $tokens[ $position + 1 ]->id
			)
		) {
			return $position + 3;
		}

		return null;
	}

	/**
	 * Check whether a token range is a supported MySQL index-name list.
	 *
	 * @param WP_MySQL_Token[] $tokens      MySQL lexer token stream.
	 * @param int             $start       First list token position.
	 * @param int             $end         Final list token position, exclusive.
	 * @param bool            $allow_empty Whether an empty list is valid.
	 * @return bool Whether the token range is a supported index-name list.
	 */
	private function is_mysql_index_hint_identifier_list( array $tokens, int $start, int $end, bool $allow_empty ): bool {
		if ( $start === $end ) {
			return $allow_empty;
		}

		$expect_identifier = true;
		for ( $i = $start; $i < $end; $i++ ) {
			if ( $expect_identifier ) {
				if ( ! $this->is_mysql_index_hint_identifier_token( $tokens[ $i ] ?? null ) ) {
					return false;
				}

				$expect_identifier = false;
				continue;
			}

			if ( WP_MySQL_Lexer::COMMA_SYMBOL !== $tokens[ $i ]->id ) {
				return false;
			}

			$expect_identifier = true;
		}

		return ! $expect_identifier;
	}

	/**
	 * Check whether a token can name an index in a MySQL optimizer hint.
	 *
	 * @param WP_MySQL_Token|null $token MySQL token.
	 * @return bool Whether the token is a supported index identifier.
	 */
	private function is_mysql_index_hint_identifier_token( ?WP_MySQL_Token $token ): bool {
		if ( null === $token ) {
			return false;
		}

		return WP_MySQL_Lexer::PRIMARY_SYMBOL === $token->id
			|| null !== $this->get_mysql_identifier_token_value( $token );
	}

	/**
	 * Translate MySQL LIMIT offset,count syntax to PostgreSQL LIMIT count OFFSET offset.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position LIMIT token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_limit_offset_count_to_postgresql( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_limit_offset_count_bounds( $tokens, $position, $end );
		if ( null === $bounds ) {
			return null;
		}

		$sql = 'LIMIT ' . $tokens[ $bounds['count_position'] ]->get_bytes()
			. ' OFFSET ' . $tokens[ $bounds['offset_position'] ]->get_bytes();

		return array(
			'sql'      => $sql,
			'token_id' => WP_MySQL_Lexer::LIMIT_SYMBOL,
			'position' => $bounds['count_position'],
		);
	}

	/**
	 * Get token bounds for a MySQL LIMIT offset,count clause.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position LIMIT token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{offset_position: int, count_position: int}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_limit_offset_count_bounds( array $tokens, int $position, int $end ): ?array {
		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ], $tokens[ $position + 2 ], $tokens[ $position + 3 ] )
			|| WP_MySQL_Lexer::LIMIT_SYMBOL !== $tokens[ $position ]->id
			|| WP_MySQL_Lexer::COMMA_SYMBOL !== $tokens[ $position + 2 ]->id
			|| $position + 4 !== $end
			|| ! $this->is_supported_simple_select_limit_number( $tokens[ $position + 1 ] )
			|| ! $this->is_supported_simple_select_limit_number( $tokens[ $position + 3 ] )
		) {
			return null;
		}

		return array(
			'offset_position' => $position + 1,
			'count_position'  => $position + 3,
		);
	}

	/**
	 * Translate MySQL FIELD(expr, value, ...) to a PostgreSQL CASE expression.
	 *
	 * PostgreSQL does not coerce unknown text and integer values the same way
	 * MySQL FIELD() does. Cast both sides of each comparison to text to keep the
	 * WordPress ordering use-cases executable across mixed ID/name arguments.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position Function token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_field_function_to_postgresql( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_function_call_bounds( $tokens, $position, $end, 'field' );
		if ( null === $bounds ) {
			return null;
		}

		$arguments = $this->split_top_level_mysql_arguments( $tokens, $bounds['arguments_start'], $bounds['arguments_end'] );
		if ( null === $arguments || count( $arguments ) < 2 ) {
			return null;
		}

		$value_sql = $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$arguments[0]['start'],
			$arguments[0]['end']
		);

		$clauses = array(
			sprintf( 'WHEN %s IS NULL THEN 0', $value_sql ),
		);

		for ( $i = 1; $i < count( $arguments ); $i++ ) {
			$argument_sql = $this->translate_mysql_token_sequence_to_postgresql(
				$tokens,
				$arguments[ $i ]['start'],
				$arguments[ $i ]['end']
			);

			$clauses[] = sprintf(
				'WHEN CAST(%1$s AS text) = CAST(%2$s AS text) THEN %3$d',
				$value_sql,
				$argument_sql,
				$i
			);
		}

		return array(
			'sql'      => 'CASE ' . implode( ' ', $clauses ) . ' ELSE 0 END',
			'token_id' => WP_MySQL_Lexer::CASE_SYMBOL,
			'position' => $bounds['close'],
		);
	}

	/**
	 * Translate MySQL CAST(expr AS SIGNED/UNSIGNED [INTEGER]) to PostgreSQL.
	 *
	 * Both SIGNED and UNSIGNED map to bigint. This preserves WordPress meta
	 * comparison/query execution but does not emulate MySQL UNSIGNED wraparound.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position CAST token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_integer_cast_to_postgresql( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_integer_cast_bounds( $tokens, $position, $end );
		if ( null === $bounds ) {
			return null;
		}

		$expression_sql = $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$bounds['expression_start'],
			$bounds['expression_end']
		);

		return array(
			'sql'      => $this->get_postgresql_mysql_integer_cast_sql( $expression_sql ),
			'token_id' => WP_MySQL_Lexer::CAST_SYMBOL,
			'position' => $bounds['close'],
		);
	}

	/**
	 * Translate MySQL CONVERT(expr, SIGNED/UNSIGNED [INTEGER]) to PostgreSQL.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position CONVERT token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{sql: string, token_id: int, position: int}|null Translation data, or null when unsupported.
	 */
	private function translate_mysql_integer_convert_to_postgresql( array $tokens, int $position, int $end ): ?array {
		$bounds = $this->get_mysql_integer_convert_bounds( $tokens, $position, $end );
		if ( null === $bounds ) {
			return null;
		}

		$expression_sql = $this->translate_mysql_token_sequence_to_postgresql(
			$tokens,
			$bounds['expression_start'],
			$bounds['expression_end']
		);

		return array(
			'sql'      => $this->get_postgresql_mysql_integer_cast_sql( $expression_sql ),
			'token_id' => WP_MySQL_Lexer::CAST_SYMBOL,
			'position' => $bounds['close'],
		);
	}

	/**
	 * Get PostgreSQL SQL for MySQL-compatible integer text coercion.
	 *
	 * MySQL accepts text values when casting to SIGNED/UNSIGNED and coerces the
	 * leading integer prefix, or zero when no prefix exists. PostgreSQL bigint
	 * casts reject those values, so extract a safe prefix before casting.
	 *
	 * @param string $expression_sql PostgreSQL expression SQL.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_mysql_integer_cast_sql( string $expression_sql ): string {
		$expression_text_sql = sprintf( 'CAST(%s AS text)', $expression_sql );
		$integer_pattern     = $this->connection->quote( '^[[:space:]]*[+-]?[0-9]+' );

		return sprintf(
			'CASE WHEN %1$s IS NULL THEN NULL ELSE CAST(COALESCE(SUBSTRING(%1$s, %2$s), \'0\') AS bigint) END',
			$expression_text_sql,
			$integer_pattern
		);
	}

	/**
	 * Get PostgreSQL SQL for MySQL-compatible decimal text coercion.
	 *
	 * MySQL text values in numeric expression contexts use the leading numeric
	 * prefix, including decimal and exponent forms, or zero when no prefix exists.
	 *
	 * @param string $expression_sql PostgreSQL expression SQL.
	 * @return string PostgreSQL expression SQL.
	 */
	private function get_postgresql_mysql_numeric_cast_sql( string $expression_sql ): string {
		$expression_text_sql = sprintf( 'CAST(%s AS text)', $expression_sql );
		$substring_sql       = array();
		$numeric_patterns    = array(
			'^[[:space:]]*[+-]?[0-9]+[.][0-9]*[eE][+-]?[0-9]+',
			'^[[:space:]]*[+-]?[.][0-9]+[eE][+-]?[0-9]+',
			'^[[:space:]]*[+-]?[0-9]+[eE][+-]?[0-9]+',
			'^[[:space:]]*[+-]?[0-9]+[.][0-9]*',
			'^[[:space:]]*[+-]?[.][0-9]+',
			'^[[:space:]]*[+-]?[0-9]+',
		);

		foreach ( $numeric_patterns as $pattern ) {
			$substring_sql[] = sprintf(
				'SUBSTRING(%1$s, %2$s)',
				$expression_text_sql,
				$this->connection->quote( $pattern )
			);
		}

		return sprintf(
			'CASE WHEN %1$s IS NULL THEN NULL ELSE CAST(COALESCE(%2$s, \'0\') AS numeric) END',
			$expression_text_sql,
			implode( ', ', $substring_sql )
		);
	}

	/**
	 * Get token bounds for a supported MySQL integer CAST expression.
	 *
	 * @param WP_MySQL_Token[] $tokens   MySQL lexer token stream.
	 * @param int             $position CAST token position.
	 * @param int             $end      Final token position, exclusive.
	 * @return array{expression_start: int, expression_end: int, close: int}|null Bounds, or null when unsupported.
	 */
	private function get_mysql_integer_cast_bounds( array $tokens, int $position, int $end ): ?array {
		if (
			! isset( $tokens[ $position ], $tokens[ $position + 1 ] )
			|| WP_MySQL_Lexer::CAST_SYMBOL !== $tokens[ $position ]->id
			|| WP_MySQL_Lexer::OPEN_PAR_SYMBOL !== $tokens[ $position + 1 ]->id
		) {
			return null;
		}

		$after_close = $this->get_mysql_parenthesized_sequence_end( $tokens, $position + 1, $end );
		if ( null === $after_close ) {
			return null;
		}

		$close_position = $after_close - 1;
		$as_position    = $this->find_top_level_mysql_token(
			$tokens,
			WP_MySQL_Lexer::AS_SYMBOL,
			$position + 2,
			$close_position
		);
		if (
			null === $as_position
			|| $as_position <= $position + 2
			|| null === $this->get_postgresql_integer_cast_type( $tokens, $as_position + 1, $close_position )
		) {
			return null;
		}

		return array(
			'expression_start' => $position + 2,
			'expression_end'   => $as_position,
			'close'            => $close_position,
		);
	}

